from __future__ import annotations
import json
from collections.abc import Iterable, Sequence
from enum import Enum
from typing import Any, cast
import networkx as nx
import numpy as np
import cirq
from cirq_aqt import aqt_device_metadata
gate_dict = {'X': cirq.X, 'Y': cirq.Y, 'Z': cirq.Z, 'MS': cirq.XX, 'R': cirq.PhasedXPowGate}
class OperationString(Enum):
    MS = "MS"
    Z = "Z"
    R = "R"
    MEASURE = "Meas"
def get_op_string(op_obj: cirq.Operation) -> str:
    if isinstance(op_obj.gate, cirq.XXPowGate):
        op_str = OperationString.MS.value
    elif isinstance(op_obj.gate, cirq.ZPowGate):
        op_str = OperationString.Z.value
    elif isinstance(op_obj.gate, cirq.PhasedXPowGate):
        op_str = OperationString.R.value
    elif isinstance(op_obj.gate, cirq.MeasurementGate):
        op_str = OperationString.MEASURE.value
    else:
        raise ValueError(f'Got unknown gate on operation: {op_obj}.')
    return str(op_str)
class AQTNoiseModel(cirq.NoiseModel):
    def __init__(self):
        self.noise_op_dict = get_default_noise_dict()
    def noisy_moment(
        self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]
    ) -> list[cirq.Operation]:
        noise_list = []
        for op in moment.operations:
            op_str = get_op_string(op)
            if op_str not in self.noise_op_dict:
                break
            noise_op = self.noise_op_dict[op_str]
            for qubit in op.qubits:
                noise_list.append(noise_op.on(qubit))
            noise_list += self.get_crosstalk_operation(op, system_qubits)
        return list(moment) + noise_list
    def get_crosstalk_operation(
        self, operation: cirq.Operation, system_qubits: Sequence[cirq.Qid]
    ) -> list[cirq.Operation]:
        cast(tuple[cirq.LineQubit], system_qubits)
        num_qubits = len(system_qubits)
        xtlk_arr = np.zeros(num_qubits)
        idx_list = []
        for qubit in operation.qubits:
            idx = system_qubits.index(qubit)
            idx_list.append(idx)
            neighbors = [idx - 1, idx + 1]
            for neigh_idx in neighbors:
                if neigh_idx >= 0 and neigh_idx < num_qubits:
                    xtlk_arr[neigh_idx] = self.noise_op_dict['crosstalk']
        for idx in idx_list:
            xtlk_arr[idx] = 0
        xtlk_op_list = []
        op_str = get_op_string(operation)
        gate = cast(cirq.EigenGate, gate_dict[op_str])
        if len(operation.qubits) == 1:
            for idx in xtlk_arr.nonzero()[0]:
                exponent = operation.gate.exponent  # type:ignore
                exponent = exponent * xtlk_arr[idx]
                xtlk_op = operation.gate.on(system_qubits[idx]) ** exponent  # type:ignore
                xtlk_op_list.append(xtlk_op)
        elif len(operation.qubits) == 2:
            for op_qubit in operation.qubits:
                for idx in xtlk_arr.nonzero()[0]:
                    exponent = operation.gate.exponent  # type:ignore
                    exponent = exponent * xtlk_arr[idx]
                    xtlk_op = gate.on(op_qubit, system_qubits[idx]) ** exponent
                    xtlk_op_list.append(xtlk_op)
        return xtlk_op_list
class AQTSimulator:
    def __init__(
        self,
        num_qubits: int,
        circuit: cirq.Circuit = cirq.Circuit(),
        simulate_ideal: bool = False,
        noise_dict: dict | None = None,
    ):
        self.circuit = circuit
        self.num_qubits = num_qubits
        self.qubit_list = cirq.LineQubit.range(num_qubits)
        if noise_dict is None:
            noise_dict = get_default_noise_dict()
        self.noise_dict = noise_dict
        self.simulate_ideal = simulate_ideal
    def generate_circuit_from_list(self, json_string: str) -> None:
        self.circuit = cirq.Circuit()
        json_obj = json.loads(json_string)
        gate: cirq.PhasedXPowGate | cirq.EigenGate
        for circuit_list in json_obj:
            op_str = circuit_list[0]
            if op_str == 'R':
                gate = cast(cirq.PhasedXPowGate, gate_dict[op_str])
                theta = circuit_list[1]
                phi = circuit_list[2]
                qubits = [self.qubit_list[i] for i in circuit_list[3]]
                self.circuit.append(gate(phase_exponent=phi, exponent=theta).on(*qubits))
            else:
                gate = cast(cirq.EigenGate, gate_dict[op_str])
                angle = circuit_list[1]
                qubits = [self.qubit_list[i] for i in circuit_list[2]]
                self.circuit.append(gate.on(*qubits) ** angle)
        self.circuit.append(cirq.measure(*[qubit for qubit in self.qubit_list], key='m'))
    def simulate_samples(self, repetitions: int) -> cirq.Result:
        if self.simulate_ideal:
            noise_model = cirq.NO_NOISE
        else:
            noise_model = AQTNoiseModel()
        if self.circuit == cirq.Circuit():
            raise RuntimeError('Simulate called without a valid circuit.')
        sim = cirq.DensityMatrixSimulator(noise=noise_model)
        result = sim.run(self.circuit, repetitions=repetitions)
        return result
@cirq.value_equality
class AQTDevice(cirq.Device):
    def __init__(
        self,
        measurement_duration: cirq.DURATION_LIKE,
        twoq_gates_duration: cirq.DURATION_LIKE,
        oneq_gates_duration: cirq.DURATION_LIKE,
        qubits: Iterable[cirq.LineQubit],
    ) -> None:
        if not all(isinstance(qubit, cirq.LineQubit) for qubit in qubits):
            raise TypeError(
                "All qubits were not of type cirq.LineQubit, instead were "
                f"{set(type(qubit) for qubit in qubits)}"
            )
        self.qubits = frozenset(qubits)
        graph = nx.Graph()
        graph.add_edges_from([(a, b) for a in qubits for b in qubits if a != b], directed=False)
        self._metadata = aqt_device_metadata.AQTDeviceMetadata(
            qubits=self.qubits,
            measurement_duration=measurement_duration,
            twoq_gates_duration=twoq_gates_duration,
            oneq_gates_duration=oneq_gates_duration,
        )
    @property
    def metadata(self) -> aqt_device_metadata.AQTDeviceMetadata:
        return self._metadata
    def validate_gate(self, gate: cirq.Gate) -> None:
        if gate not in self.metadata.gateset:
            raise ValueError(f'Unsupported gate type: {gate!r}')
    def validate_operation(self, operation) -> None:
        if not isinstance(operation, cirq.GateOperation):
            raise ValueError(f'Unsupported operation: {operation!r}')
        self.validate_gate(operation.gate)
        for q in operation.qubits:
            if not isinstance(q, cirq.LineQubit):
                raise ValueError(f'Unsupported qubit type: {q!r}')
            if q not in self.qubits:
                raise ValueError(f'Qubit not on device: {q!r}')
    def validate_circuit(self, circuit: cirq.AbstractCircuit) -> None:
        super().validate_circuit(circuit)
        _verify_unique_measurement_keys(circuit.all_operations())
    def at(self, position: int) -> cirq.LineQubit | None:
        q = cirq.LineQubit(position)
        return q if q in self.qubits else None
    def _value_equality_values_(self) -> Any:
        return (self.metadata, self.qubits)
    def __str__(self) -> str:
        diagram = cirq.TextDiagramDrawer()
        for q in self.qubits:
            diagram.write(q.x, 0, str(q))
            for q2 in q.neighbors(self.qubits):
                diagram.grid_line(q.x, 0, q2.x, 0)
        return diagram.render(horizontal_spacing=3, vertical_spacing=2, use_unicode_characters=True)
    def __repr__(self) -> str:
        return (
            f'cirq_aqt.aqt_device.AQTDevice('
            f'measurement_duration={self.metadata.measurement_duration!r}, '
            f'twoq_gates_duration={self.metadata.twoq_gates_duration!r}, '
            f'oneq_gates_duration={self.metadata.oneq_gates_duration!r}, '
            f'qubits={sorted(self.qubits)!r}'
            f')'
        )
    def _repr_pretty_(self, p: Any, cycle: bool):
        p.text("AQTDevice(...)" if cycle else self.__str__())
def get_aqt_device(num_qubits: int) -> tuple[AQTDevice, list[cirq.LineQubit]]:
    qubit_list = cirq.LineQubit.range(num_qubits)
    us = 1000 * cirq.Duration(nanos=1)
    ion_device = AQTDevice(
        measurement_duration=100 * us,
        twoq_gates_duration=200 * us,
        oneq_gates_duration=10 * us,
        qubits=qubit_list,
    )
    return ion_device, qubit_list
def get_default_noise_dict() -> dict[str, Any]:
    default_noise_dict = {
        OperationString.R.value: cirq.depolarize(1e-3),
        OperationString.Z.value: cirq.depolarize(0),
        OperationString.MS.value: cirq.depolarize(1e-2),
        'crosstalk': 0.03,
    }
    return default_noise_dict
def _verify_unique_measurement_keys(operations: Iterable[cirq.Operation]):
    seen: set[str] = set()
    for op in operations:
        if isinstance(op.gate, cirq.MeasurementGate):
            meas = op.gate
            key = cirq.measurement_key_name(meas)
            if key in seen:
                raise ValueError(f'Measurement key {key} repeated')
            seen.add(key)

from __future__ import annotations
from collections.abc import Iterable, Mapping
from typing import Any
import networkx as nx
import cirq
from cirq_aqt import aqt_target_gateset
class AQTDeviceMetadata(cirq.DeviceMetadata):
    def __init__(
        self,
        qubits: Iterable[cirq.LineQubit],
        measurement_duration: cirq.DURATION_LIKE,
        twoq_gates_duration: cirq.DURATION_LIKE,
        oneq_gates_duration: cirq.DURATION_LIKE,
    ):
        graph = nx.Graph()
        graph.add_edges_from([(a, b) for a in qubits for b in qubits if a != b], directed=False)
        super().__init__(qubits, graph)
        self._gateset = aqt_target_gateset.AQTTargetGateset()
        self._measurement_duration = cirq.Duration(measurement_duration)
        self._twoq_gates_duration = cirq.Duration(twoq_gates_duration)
        self._oneq_gates_duration = cirq.Duration(oneq_gates_duration)
        self._gate_durations = {
            cirq.GateFamily(cirq.MeasurementGate): self._measurement_duration,
            cirq.GateFamily(cirq.XXPowGate): self._twoq_gates_duration,
            cirq.GateFamily(cirq.ZPowGate): self._oneq_gates_duration,
            cirq.GateFamily(cirq.PhasedXPowGate): self._oneq_gates_duration,
        }
        assert not self._gateset.gates.symmetric_difference(
            self._gate_durations.keys()
        ), "AQTDeviceMetadata.gate_durations must have the same Gates as AQTTargetGateset."
    @property
    def gateset(self) -> cirq.Gateset:
        return self._gateset
    @property
    def gate_durations(self) -> Mapping[cirq.GateFamily, cirq.Duration]:
        return self._gate_durations
    @property
    def measurement_duration(self) -> cirq.DURATION_LIKE:
        return self._measurement_duration
    @property
    def oneq_gates_duration(self) -> cirq.DURATION_LIKE:
        return self._oneq_gates_duration
    @property
    def twoq_gates_duration(self) -> cirq.DURATION_LIKE:
        return self._twoq_gates_duration
    def duration_of(self, operation: cirq.Operation) -> cirq.DURATION_LIKE:
        for gate_family, duration in self.gate_durations.items():
            if operation in gate_family:
                return duration
        else:
            raise ValueError(f'Unsupported gate type: {operation!r}')
    def _value_equality_values_(self) -> Any:
        return (
            self._measurement_duration,
            self._twoq_gates_duration,
            self._oneq_gates_duration,
            self.qubit_set,
        )
    def __repr__(self) -> str:
        return (
            f'cirq_aqt.aqt_device_metadata.AQTDeviceMetadata('
            f'qubits={sorted(self.qubit_set)!r}, '
            f'measurement_duration={self.measurement_duration!r}, '
            f'twoq_gates_duration={self.twoq_gates_duration!r}, '
            f'oneq_gates_duration={self.oneq_gates_duration!r}'
            f')'
        )

from __future__ import annotations
from datetime import timedelta
import pytest
import cirq
from cirq_aqt import aqt_device, aqt_device_metadata
@pytest.fixture
def qubits() -> list[cirq.LineQubit]:
    return cirq.LineQubit.range(3)
@pytest.fixture
def device(qubits) -> aqt_device.AQTDevice:
    ms = cirq.Duration(millis=1)
    return aqt_device.AQTDevice(
        measurement_duration=100 * ms,
        twoq_gates_duration=200 * ms,
        oneq_gates_duration=10 * ms,
        qubits=qubits,
    )
class NotImplementedOperation(cirq.Operation):
    def with_qubits(self, *new_qubits) -> NotImplementedOperation:
        raise NotImplementedError()
    @property
    def qubits(self) -> tuple[cirq.Qid, ...]:
        raise NotImplementedError()
def test_init_qubits(device, qubits) -> None:
    ms = cirq.Duration(millis=1)
    assert device.qubits == frozenset(qubits)
    with pytest.raises(TypeError, match="NamedQubit"):
        aqt_device.AQTDevice(
            measurement_duration=100 * ms,
            twoq_gates_duration=200 * ms,
            oneq_gates_duration=10 * ms,
            qubits=[cirq.LineQubit(0), cirq.NamedQubit("a")],  # type: ignore[list-item]
        )
@pytest.mark.parametrize('ms', [cirq.Duration(millis=1), timedelta(milliseconds=1)])
def test_init_durations(ms, qubits) -> None:
    dev = aqt_device.AQTDevice(
        qubits=qubits,
        measurement_duration=100 * ms,
        twoq_gates_duration=200 * ms,
        oneq_gates_duration=10 * ms,
    )
    assert dev.metadata.twoq_gates_duration == cirq.Duration(millis=200)
    assert dev.metadata.oneq_gates_duration == cirq.Duration(millis=10)
    assert dev.metadata.measurement_duration == cirq.Duration(millis=100)
def test_metadata(device, qubits) -> None:
    assert isinstance(device.metadata, aqt_device_metadata.AQTDeviceMetadata)
    assert device.metadata.qubit_set == frozenset(qubits)
def test_repr(device) -> None:
    assert repr(device) == (
        "cirq_aqt.aqt_device.AQTDevice("
        "measurement_duration=cirq.Duration(millis=100), "
        "twoq_gates_duration=cirq.Duration(millis=200), "
        "oneq_gates_duration=cirq.Duration(millis=10), "
        "qubits=[cirq.LineQubit(0), cirq.LineQubit(1), "
        "cirq.LineQubit(2)])"
    )
    cirq.testing.assert_equivalent_repr(device, setup_code='import cirq\nimport cirq_aqt\n')
def test_validate_measurement_non_adjacent_qubits_ok(device) -> None:
    device.validate_operation(
        cirq.GateOperation(cirq.MeasurementGate(2, 'key'), (cirq.LineQubit(0), cirq.LineQubit(1)))
    )
def test_validate_operation_existing_qubits(device) -> None:
    device.validate_operation(cirq.GateOperation(cirq.XX, (cirq.LineQubit(0), cirq.LineQubit(1))))
    device.validate_operation(cirq.Z(cirq.LineQubit(0)))
    device.validate_operation(
        cirq.PhasedXPowGate(phase_exponent=0.75, exponent=0.25, global_shift=0.1).on(
            cirq.LineQubit(1)
        )
    )
    with pytest.raises(ValueError):
        device.validate_operation(cirq.CZ(cirq.LineQubit(0), cirq.LineQubit(-1)))
    with pytest.raises(ValueError):
        device.validate_operation(cirq.Z(cirq.LineQubit(-1)))
    with pytest.raises(ValueError):
        device.validate_operation(cirq.CZ(cirq.LineQubit(1), cirq.LineQubit(1)))
    with pytest.raises(ValueError):
        device.validate_operation(cirq.X(cirq.NamedQubit("q1")))
def test_validate_operation_supported_gate(device) -> None:
    class MyGate(cirq.Gate):
        def num_qubits(self):
            return 1
    device.validate_operation(cirq.GateOperation(cirq.Z, [cirq.LineQubit(0)]))
    assert MyGate().num_qubits() == 1
    with pytest.raises(ValueError):
        device.validate_operation(cirq.GateOperation(MyGate(), [cirq.LineQubit(0)]))
    with pytest.raises(ValueError):
        device.validate_operation(NotImplementedOperation())
def test_aqt_device_eq(device) -> None:
    eq = cirq.testing.EqualsTester()
    eq.make_equality_group(lambda: device)
def test_validate_circuit_repeat_measurement_keys(device) -> None:
    circuit = cirq.Circuit()
    circuit.append(
        [cirq.measure(cirq.LineQubit(0), key='a'), cirq.measure(cirq.LineQubit(1), key='a')]
    )
    with pytest.raises(ValueError, match='Measurement key a repeated'):
        device.validate_circuit(circuit)
def test_aqt_device_str(device) -> None:
    assert str(device) == "q(0)───q(1)───q(2)"
def test_aqt_device_pretty_repr(device) -> None:
    cirq.testing.assert_repr_pretty(device, "q(0)───q(1)───q(2)")
    cirq.testing.assert_repr_pretty(device, "AQTDevice(...)", cycle=True)
def test_at(device) -> None:
    assert device.at(-1) is None
    assert device.at(0) == cirq.LineQubit(0)
    assert device.at(2) == cirq.LineQubit(2)

from __future__ import annotations
import json
import time
import uuid
from collections.abc import Callable, Sequence
from typing import cast, Literal, TypedDict
from urllib.parse import urljoin
import numpy as np
from requests import get, post
import cirq
from cirq_aqt.aqt_device import AQTSimulator, get_op_string, OperationString
_DEFAULT_HOST = "https://arnica.aqt.eu/api/v1/"
class SingleQubitGate(TypedDict):
    qubit: int
class GateRZ(SingleQubitGate):
    operation: Literal["RZ"]
    phi: float
class GateR(SingleQubitGate):
    operation: Literal["R"]
    phi: float
    theta: float
class GateRXX(TypedDict):
    operation: Literal["RXX"]
    qubits: list[int]
    theta: float
class Measure(TypedDict):
    operation: Literal["MEASURE"]
Gate = GateRZ | GateR | GateRXX
Operation = Gate | Measure
class Resource(TypedDict):
    id: str
    name: str
    type: Literal["device", "simulator"]
class Workspace(TypedDict):
    id: str
    resources: list[Resource]
class AQTSampler(cirq.Sampler):
    def __init__(
        self, workspace: str, resource: str, access_token: str, remote_host: str = _DEFAULT_HOST
    ):
        self.workspace = workspace
        self.resource = resource
        self.remote_host = remote_host
        self.access_token = access_token
    @staticmethod
    def fetch_resources(access_token: str, remote_host: str = _DEFAULT_HOST) -> list[Workspace]:
        headers = {"Authorization": f"Bearer {access_token}", "SDK": "cirq"}
        url = urljoin(remote_host if remote_host[-1] == "/" else remote_host + "/", "workspaces")
        response = get(url, headers=headers)
        if response.status_code != 200:
            raise RuntimeError('Got unexpected return data from server: \n' + str(response.json()))
        workspaces = [
            Workspace(
                id=w['id'],
                resources=[
                    Resource(id=r['id'], name=r['name'], type=r['type']) for r in w['resources']
                ],
            )
            for w in response.json()
        ]
        return workspaces
    @staticmethod
    def print_resources(
        access_token: str, emit: Callable = print, remote_host: str = _DEFAULT_HOST
    ) -> None:
        table_lines = []
        workspaces = AQTSampler.fetch_resources(access_token, remote_host)
        if len(workspaces) == 0:
            return emit("No workspaces are accessible with this access token.")
        if any(len(w['resources']) == 0 for w in workspaces):
            return emit("No workspaces accessible with this access token contain resources.")
        col_widths = [
            max([len(w['id']) for w in workspaces]),
            max([len(d['name']) for w in workspaces for d in w['resources']]),
            max([len(d['id']) for w in workspaces for d in w['resources']]),
            3,
        ]
        SEPARATOR = "+-" + "-+-".join(col_width * "-" for col_width in col_widths) + "-+"
        table_lines.append(SEPARATOR)
        table_lines.append(
            f"| {'WORKSPACE ID'.ljust(col_widths[0])} |"
            f" {'RESOURCE NAME'.ljust(col_widths[1])} |"
            f" {'RESOURCE ID'.ljust(col_widths[2])} |"
            f" {'D/S'.ljust(col_widths[3])} |"
        )
        table_lines.append(SEPARATOR)
        for workspace in workspaces:
            next_workspace = workspace['id']
            for resource in workspace["resources"]:
                table_lines.append(
                    f"| {next_workspace.ljust(col_widths[0])} |"
                    f" {resource['name'].ljust(col_widths[1])} |"
                    f" {resource['id'].ljust(col_widths[2])} |"
                    f" {resource['type'][0].upper().ljust(col_widths[3])} |"
                )
                next_workspace = ""
            table_lines.append(SEPARATOR)
        emit("\n".join(table_lines))
    def _generate_json(
        self, circuit: cirq.AbstractCircuit, param_resolver: cirq.ParamResolverOrSimilarType
    ) -> str:
        seq_list: list[tuple[str, float, list[int]] | tuple[str, float, float, list[int]]] = []
        circuit = cirq.resolve_parameters(circuit, param_resolver)
        for op in circuit.all_operations():
            line_qubit = cast(tuple[cirq.LineQubit], op.qubits)
            op = cast(cirq.GateOperation, op)
            qubit_idx = [obj.x for obj in line_qubit]
            op_str = get_op_string(op)
            gate: cirq.EigenGate | cirq.PhasedXPowGate
            if op_str == 'R':
                gate = cast(cirq.PhasedXPowGate, op.gate)
                seq_list.append(
                    (op_str, float(gate.exponent), float(gate.phase_exponent), qubit_idx)
                )
            else:
                gate = cast(cirq.EigenGate, op.gate)
                seq_list.append((op_str, float(gate.exponent), qubit_idx))
        if len(seq_list) == 0:
            raise RuntimeError('Cannot send an empty circuit')
        json_str = json.dumps(seq_list)
        return json_str
    def _parse_legacy_circuit_json(self, json_str: str) -> list[Operation]:
        circuit = []
        number_of_measurements = 0
        instruction: Operation
        for legacy_op in json.loads(json_str):
            if number_of_measurements > 0:
                raise ValueError("Need exactly one `MEASURE` operation at the end of the circuit.")
            if legacy_op[0] == OperationString.Z.value:
                instruction = GateRZ(operation="RZ", qubit=legacy_op[2][0], phi=legacy_op[1])
            elif legacy_op[0] == OperationString.R.value:
                instruction = GateR(
                    operation="R", qubit=legacy_op[3][0], theta=legacy_op[1], phi=legacy_op[2]
                )
            elif legacy_op[0] == OperationString.MS.value:
                instruction = GateRXX(operation="RXX", qubits=legacy_op[2], theta=legacy_op[1])
            elif legacy_op[0] == OperationString.MEASURE.value:
                instruction = Measure(operation="MEASURE")
                number_of_measurements += 1
            else:
                raise ValueError(f'Got unknown gate on operation: {legacy_op}.')
            circuit.append(instruction)
        if circuit[-1]["operation"] != "MEASURE":
            circuit.append({"operation": "MEASURE"})
        return circuit
    def _send_json(
        self, *, json_str: str, id_str: str, repetitions: int = 1, num_qubits: int = 1
    ) -> np.ndarray:
        headers = {"Authorization": f"Bearer {self.access_token}", "SDK": "cirq"}
        quantum_circuit = self._parse_legacy_circuit_json(json_str)
        submission_data = {
            "job_type": "quantum_circuit",
            "label": id_str,
            "payload": {
                "circuits": [
                    {
                        "repetitions": repetitions,
                        "quantum_circuit": quantum_circuit,
                        "number_of_qubits": num_qubits,
                    }
                ]
            },
        }
        submission_url = urljoin(self.remote_host, f"submit/{self.workspace}/{self.resource}")
        response = post(submission_url, json=submission_data, headers=headers)
        response = response.json()
        data = cast(dict, response)
        if 'response' not in data.keys() or 'status' not in data['response'].keys():
            raise RuntimeError('Got unexpected return data from server: \n' + str(data))
        if data['response']['status'] == 'error':
            raise RuntimeError('AQT server reported error: \n' + str(data))
        if 'job' not in data.keys() or 'job_id' not in data['job'].keys():
            raise RuntimeError('Got unexpected return data from AQT server: \n' + str(data))
        job_id = data['job']['job_id']
        result_url = urljoin(self.remote_host, f"result/{job_id}")
        while True:
            response = get(result_url, headers=headers)
            response = response.json()
            data = cast(dict, response)
            if 'response' not in data.keys() or 'status' not in data['response'].keys():
                raise RuntimeError('Got unexpected return data from AQT server: \n' + str(data))
            if data['response']['status'] == 'finished':
                break
            elif data['response']['status'] == 'error':
                raise RuntimeError('Got unexpected return data from AQT server: \n' + str(data))
            time.sleep(1.0)
        if 'result' not in data['response'].keys():
            raise RuntimeError('Got unexpected return data from AQT server: \n' + str(data))
        measurement_int = data['response']['result']['0']
        measurements = np.zeros((repetitions, num_qubits), dtype=int)
        for i, repetition in enumerate(measurement_int):
            for j in range(num_qubits):
                measurements[i, j] = repetition[j]
        return measurements
    def run_sweep(
        self, program: cirq.AbstractCircuit, params: cirq.Sweepable, repetitions: int = 1
    ) -> Sequence[cirq.Result]:
        meas_name = 'm'
        trial_results: list[cirq.Result] = []
        for param_resolver in cirq.to_resolvers(params):
            id_str = str(uuid.uuid1())
            num_qubits = len(program.all_qubits())
            json_str = self._generate_json(circuit=program, param_resolver=param_resolver)
            results = self._send_json(
                json_str=json_str, id_str=id_str, repetitions=repetitions, num_qubits=num_qubits
            )
            results = results.astype(bool)
            res_dict = {meas_name: results}
            trial_results.append(cirq.ResultDict(params=param_resolver, measurements=res_dict))
        return trial_results
