from __future__ import annotations
from collections.abc import Callable, Mapping, Sequence
from typing import TYPE_CHECKING
import numpy as np
from cirq.ops import QubitOrder, QubitOrderOrList
from cirq.sim import final_state_vector
from cirq.value import state_vector_to_probabilities
if TYPE_CHECKING:
    import cirq
def linear_xeb_fidelity_from_probabilities(
    hilbert_space_dimension: int, probabilities: Sequence[float]
) -> float:
    return hilbert_space_dimension * np.mean(probabilities).item() - 1
def log_xeb_fidelity_from_probabilities(
    hilbert_space_dimension: int, probabilities: Sequence[float]
) -> float:
    return np.log(hilbert_space_dimension) + np.euler_gamma + np.mean(np.log(probabilities))
def hog_score_xeb_fidelity_from_probabilities(
    hilbert_space_dimension: int, probabilities: Sequence[float]
) -> float:
    score = np.mean(probabilities > np.log(2) / hilbert_space_dimension)
    return (2 * score - 1) / np.log(2)
def xeb_fidelity(
    circuit: cirq.Circuit,
    bitstrings: Sequence[int],
    qubit_order: QubitOrderOrList = QubitOrder.DEFAULT,
    amplitudes: Mapping[int, complex] | np.ndarray | None = None,
    estimator: Callable[[int, Sequence[float]], float] = linear_xeb_fidelity_from_probabilities,
) -> float:
    dim = np.prod(circuit.qid_shape()).item()
    if isinstance(bitstrings, tuple):
        bitstrings = list(bitstrings)
    for bitstring in bitstrings:
        if not 0 <= bitstring < dim:
            raise ValueError(
                f'Bitstring {bitstring} could not have been observed '
                f'on {len(circuit.qid_shape())} qubits.'
            )
    if amplitudes is None:
        output_state = final_state_vector(circuit, qubit_order=qubit_order)
        output_probabilities = state_vector_to_probabilities(output_state)
        bitstring_probabilities = output_probabilities[bitstrings].tolist()
    else:
        bitstring_probabilities = [abs(amplitudes[bitstring]) ** 2 for bitstring in bitstrings]
    return estimator(dim, bitstring_probabilities)
def linear_xeb_fidelity(
    circuit: cirq.Circuit,
    bitstrings: Sequence[int],
    qubit_order: QubitOrderOrList = QubitOrder.DEFAULT,
    amplitudes: Mapping[int, complex] | np.ndarray | None = None,
) -> float:
    return xeb_fidelity(
        circuit,
        bitstrings,
        qubit_order,
        amplitudes,
        estimator=linear_xeb_fidelity_from_probabilities,
    )
def log_xeb_fidelity(
    circuit: cirq.Circuit,
    bitstrings: Sequence[int],
    qubit_order: QubitOrderOrList = QubitOrder.DEFAULT,
    amplitudes: Mapping[int, complex] | np.ndarray | None = None,
) -> float:
    return xeb_fidelity(
        circuit, bitstrings, qubit_order, amplitudes, estimator=log_xeb_fidelity_from_probabilities
    )

from __future__ import annotations
from collections.abc import Hashable, Iterable, Iterator, Sequence, Set
from functools import cached_property
from types import NotImplementedType
from typing import TYPE_CHECKING
from cirq import _compat, protocols
from cirq.circuits import AbstractCircuit, Alignment, Circuit
from cirq.circuits.insert_strategy import InsertStrategy
if TYPE_CHECKING:
    import numpy as np
    import cirq
class FrozenCircuit(AbstractCircuit, protocols.SerializableByKey):
    def __init__(
        self,
        *contents: cirq.OP_TREE,
        strategy: cirq.InsertStrategy = InsertStrategy.EARLIEST,
        tags: Sequence[Hashable] = (),
    ) -> None:
        base = Circuit(contents, strategy=strategy)
        self._moments = tuple(base.moments)
        self._tags = tuple(tags)
    @classmethod
    def _from_moments(
        cls, moments: Iterable[cirq.Moment], tags: Sequence[Hashable]
    ) -> FrozenCircuit:
        new_circuit = FrozenCircuit()
        new_circuit._moments = tuple(moments)
        new_circuit._tags = tuple(tags)
        return new_circuit
    @property
    def moments(self) -> Sequence[cirq.Moment]:
        return self._moments
    def freeze(self) -> cirq.FrozenCircuit:
        return self
    def unfreeze(self, copy: bool = True) -> cirq.Circuit:
        return Circuit._from_moments(self._moments, tags=self.tags)
    @property
    def tags(self) -> tuple[Hashable, ...]:
        return self._tags
    @cached_property
    def untagged(self) -> cirq.FrozenCircuit:
        return super().untagged
    def with_tags(self, *new_tags: Hashable) -> cirq.FrozenCircuit:
        if not new_tags:
            return self
        new_circuit = FrozenCircuit(tags=self.tags + new_tags)
        new_circuit._moments = self._moments
        return new_circuit
    @_compat.cached_method
    def __hash__(self) -> int:
        return hash((self.moments, self.tags))
    def __getstate__(self):
        state = self.__dict__
        hash_attr = _compat._method_cache_name(self.__hash__)
        if hash_attr in state:
            state = state.copy()
            del state[hash_attr]
        return state
    @_compat.cached_method
    def _num_qubits_(self) -> int:
        return len(self.all_qubits())
    @_compat.cached_method
    def _qid_shape_(self) -> tuple[int, ...]:
        return super()._qid_shape_()
    @_compat.cached_method
    def _has_unitary_(self) -> bool:
        return super()._has_unitary_()
    @_compat.cached_method
    def _unitary_(self) -> np.ndarray | NotImplementedType:
        return super()._unitary_()
    @_compat.cached_method
    def _is_measurement_(self) -> bool:
        return protocols.is_measurement(self.unfreeze())
    @_compat.cached_method
    def all_qubits(self) -> frozenset[cirq.Qid]:
        return super().all_qubits()
    @cached_property
    def _all_operations(self) -> tuple[cirq.Operation, ...]:
        return tuple(super().all_operations())
    def all_operations(self) -> Iterator[cirq.Operation]:
        return iter(self._all_operations)
    def has_measurements(self) -> bool:
        return self._is_measurement_()
    @_compat.cached_method
    def all_measurement_key_objs(self) -> frozenset[cirq.MeasurementKey]:
        return super().all_measurement_key_objs()
    def _measurement_key_objs_(self) -> frozenset[cirq.MeasurementKey]:
        return self.all_measurement_key_objs()
    @_compat.cached_method
    def _control_keys_(self) -> frozenset[cirq.MeasurementKey]:
        return super()._control_keys_()
    @_compat.cached_method
    def are_all_measurements_terminal(self) -> bool:
        return super().are_all_measurements_terminal()
    @_compat.cached_method
    def all_measurement_key_names(self) -> frozenset[str]:
        return frozenset(str(key) for key in self.all_measurement_key_objs())
    @_compat.cached_method
    def _is_parameterized_(self) -> bool:
        return super()._is_parameterized_()
    @_compat.cached_method
    def _parameter_names_(self) -> Set[str]:
        return super()._parameter_names_()
    def _measurement_key_names_(self) -> frozenset[str]:
        return self.all_measurement_key_names()
    def __add__(self, other) -> cirq.FrozenCircuit:
        return (self.unfreeze() + other).freeze()
    def __radd__(self, other) -> cirq.FrozenCircuit:
        return (other + self.unfreeze()).freeze()
    __array_priority__ = 10000
    def __mul__(self, other) -> cirq.FrozenCircuit:
        return (self.unfreeze() * other).freeze()
    def __rmul__(self, other) -> cirq.FrozenCircuit:
        return (other * self.unfreeze()).freeze()
    def __pow__(self, other) -> cirq.FrozenCircuit:
        try:
            return (self.unfreeze() ** other).freeze()
        except:
            return NotImplemented
    @classmethod
    def _from_json_dict_(cls, moments, *, tags=(), **kwargs):
        return cls(moments, strategy=InsertStrategy.EARLIEST, tags=tags)
    def concat_ragged(
        *circuits: cirq.AbstractCircuit, align: cirq.Alignment | str = Alignment.LEFT
    ) -> cirq.FrozenCircuit:
        return AbstractCircuit.concat_ragged(*circuits, align=align).freeze()
    concat_ragged.__doc__ = AbstractCircuit.concat_ragged.__doc__
    def zip(
        *circuits: cirq.AbstractCircuit, align: cirq.Alignment | str = Alignment.LEFT
    ) -> cirq.FrozenCircuit:
        return AbstractCircuit.zip(*circuits, align=align).freeze()
    zip.__doc__ = AbstractCircuit.zip.__doc__
    def to_op(self) -> cirq.CircuitOperation:
        from cirq.circuits import CircuitOperation
        return CircuitOperation(self)

import networkx as nx
import numpy as np
import cirq.circuits as circuits
import cirq.devices as devices
import cirq.ops as ops
import cirq.protocols as protocols
import cirq.transformers as transformers
def _transform_circuit(circuit: circuits.Circuit) -> circuits.Circuit:
    qubits = list(circuit.all_qubits())
    circuit = circuit + circuits.Circuit(ops.measure(*qubits, key="m"))
    circuit = transformers.align_right(transformers.merge_single_qubit_gates_to_phxz(circuit))
    circuit = transformers.stratified_circuit(
        circuit[::-1], categories=[lambda op: protocols.num_qubits(op) == k for k in (1, 2)]
    )[::-1]
    circuit = transformers.add_dynamical_decoupling(circuit)
    circuit = circuits.Circuit(circuit[:-1])
    return circuit
def generate_2d_ghz_circuit(
    center: devices.GridQubit,
    graph: nx.Graph,
    num_qubits: int,
    randomized: bool = False,
    rng_or_seed: int | np.random.Generator | None = None,
    add_dd_and_align_right: bool = False,
) -> circuits.Circuit:
    if num_qubits <= 0:
        raise ValueError("num_qubits must be a positive integer.")
    if num_qubits > len(graph.nodes):
        raise ValueError("num_qubits cannot exceed the total number of qubits on the processor.")
    if randomized:
        rng = (
            rng_or_seed
            if isinstance(rng_or_seed, np.random.Generator)
            else np.random.default_rng(rng_or_seed)
        )
        def sort_neighbors_fn(neighbors: list) -> list:
            neighbors = list(neighbors)
            rng.shuffle(neighbors)
            return neighbors
    else:
        def sort_neighbors_fn(neighbors: list) -> list:
            return sorted(
                neighbors, key=lambda q: (q.row - center.row) ** 2 + (q.col - center.col) ** 2
            )
    bfs_tree = nx.bfs_tree(graph, center, sort_neighbors=sort_neighbors_fn)
    qubits_to_include = list(bfs_tree.nodes)[:num_qubits]
    final_tree = bfs_tree.subgraph(qubits_to_include)
    ghz_ops = []
    for node in nx.topological_sort(final_tree):
        if node == center:
            ghz_ops.append(ops.H(node))
            continue
        for parent in final_tree.predecessors(node):
            ghz_ops.extend([ops.H(node), ops.CZ(parent, node), ops.H(node)])
    circuit = circuits.Circuit(ghz_ops)
    if add_dd_and_align_right:
        return _transform_circuit(circuit)
    else:
        return circuit

