            elif not self.batch_mode:
                return requests.get(
                    f'{self.url}/jobs/{job_id}/results/probabilities',
                    params=params,
                    headers=self.headers,
                )
        return self._make_request(request, {}).json()
    def list_jobs(
        self, status: str | None = None, limit: int = 100, batch_size: int = 1000
    ) -> list[dict[str, Any]]:
        params = {}
