    def cancel_job(self, job_id: str) -> dict:
        def request():
            return requests.put(f'{self.url}/jobs/{job_id}/status/cancel', headers=self.headers)
        return self._make_request(request, {}).json()
    def delete_job(self, job_id: str) -> dict:
