        return f'cirq_ionq.MSGate(phi0={self.phi0!r}, phi1={self.phi1!r})'
    def _json_dict_(self) -> dict[str, Any]:
        return cirq.obj_to_dict_helper(self, ['phi0', 'phi1', 'theta'])
