from cirq_pasqal import PasqalGateset, ThreeDQubit, TwoDQubit
@cirq.value.value_equality(unhashable=True)
class PasqalDevice(cirq.devices.Device):
    def __init__(self, qubits: Sequence[cirq.Qid]) -> None:
        if len(qubits) > 0:
            q_type = type(qubits[0])
        for q in qubits:
            if not isinstance(q, self.supported_qubit_type):
                raise TypeError(
                    f'Unsupported qubit type: {q!r}. This device '
                    f'supports qubit types: {self.supported_qubit_type}'
                )
            if not type(q) is q_type:
                raise TypeError("All qubits must be of same type.")
        if len(qubits) > self.maximum_qubit_number:
            raise ValueError(
                f'Too many qubits. {type(self)} accepts at most {self.maximum_qubit_number} qubits.'
            )
        self.gateset = PasqalGateset()
        self.qubits = qubits
        self._metadata = cirq.DeviceMetadata(
            qubits, nx.from_edgelist([(a, b) for a in qubits for b in qubits if a != b])
        )
    @property
    def supported_qubit_type(self):
        return (NamedQubit,)
    @property
    def maximum_qubit_number(self):
        return 100
    @property
    def metadata(self):
        return self._metadata
    def qubit_list(self):
        return [qubit for qubit in self.qubits]
    def is_pasqal_device_op(self, op: cirq.Operation) -> bool:
        if not isinstance(op, cirq.Operation):
            raise ValueError('Got unknown operation:', op)
        return op in self.gateset
    def validate_operation(self, operation: cirq.Operation):
        if not isinstance(operation, cirq.GateOperation):
            raise ValueError("Unsupported operation")
        if not self.is_pasqal_device_op(operation):
            raise ValueError(f'{operation.gate!r} is not a supported gate')
        for qub in operation.qubits:
            if not isinstance(qub, self.supported_qubit_type):
                raise ValueError(
                    f'{qub} is not a valid qubit for gate {operation.gate!r}. This '
                    f'device accepts gates on qubits of type: '
                    f'{self.supported_qubit_type}'
                )
            if qub not in self.metadata.qubit_set:
                raise ValueError(f'{qub} is not part of the device.')
        if isinstance(operation.gate, cirq.MeasurementGate):
            if operation.gate.invert_mask != ():
                raise NotImplementedError(
                    "Measurements on Pasqal devices don't support invert_mask."
                )
    def validate_circuit(self, circuit: cirq.AbstractCircuit) -> None:
        super().validate_circuit(circuit)
        has_measurement_occurred = False
        for moment in circuit:
            if has_measurement_occurred:
                if len(moment.operations) > 0:
                    raise ValueError("Non-empty moment after measurement")
            for operation in moment.operations:
                if isinstance(operation.gate, cirq.MeasurementGate):
                    has_measurement_occurred = True
    def __repr__(self):
        return f'pasqal.PasqalDevice(qubits={sorted(self.qubits)!r})'
    def _value_equality_values_(self):
        return self.qubits
    def _json_dict_(self):
        return cirq.protocols.obj_to_dict_helper(self, ['qubits'])
class PasqalVirtualDevice(PasqalDevice):
    def __init__(
        self, control_radius: float, qubits: Sequence[ThreeDQubit | GridQubit | LineQubit]
    ) -> None:
        super().__init__(qubits)
        if not control_radius >= 0:
            raise ValueError('Control_radius needs to be a non-negative float.')
        if len(self.qubits) > 1:
            if control_radius > 3.0 * self.minimal_distance():
                raise ValueError(
                    'Control_radius cannot be larger than 3 times'
                    ' the minimal distance between qubits.'
                )
        self.control_radius = control_radius
        self.gateset = PasqalGateset(include_additional_controlled_ops=False)
        self.controlled_gateset = cirq.Gateset(cirq.AnyIntegerPowerGateFamily(cirq.CZPowGate))
    @property
    def supported_qubit_type(self):
        return (ThreeDQubit, TwoDQubit, GridQubit, LineQubit)
    def validate_operation(self, operation: cirq.Operation):
        super().validate_operation(operation)
        if operation in self.controlled_gateset:
            for p in operation.qubits:
                for q in operation.qubits:
                    if self.distance(p, q) > self.control_radius:
                        raise ValueError(f"Qubits {p!r}, {q!r} are too far away")
    def validate_moment(self, moment: cirq.Moment):
        super().validate_moment(moment)
        if len(moment) > 1:
            for operation in moment:
                if not isinstance(operation.gate, cirq.MeasurementGate):
                    raise ValueError("Cannot do simultaneous gates. Use cirq.InsertStrategy.NEW.")
    def minimal_distance(self) -> float:
        if len(self.qubits) <= 1:
            raise ValueError("Two qubits to compute a minimal distance.")
        return min([self.distance(q1, q2) for q1 in self.qubits for q2 in self.qubits if q1 != q2])
    def distance(self, p: Any, q: Any) -> float:
        all_qubits = self.qubit_list()
        if p not in all_qubits or q not in all_qubits:
            raise ValueError("Qubit not part of the device.")
        if isinstance(p, GridQubit):
            return np.sqrt((p.row - q.row) ** 2 + (p.col - q.col) ** 2)
        if isinstance(p, LineQubit):
            return abs(p.x - q.x)
        return np.sqrt((p.x - q.x) ** 2 + (p.y - q.y) ** 2 + (p.z - q.z) ** 2)
    def __repr__(self):
        return (
            'pasqal.PasqalVirtualDevice('
            f'control_radius={self.control_radius!r}, '
            f'qubits={sorted(self.qubits)!r})'
        )
    def _value_equality_values_(self) -> Any:
        return (self.control_radius, self.qubits)
    def _json_dict_(self) -> dict[str, Any]:
        return cirq.protocols.obj_to_dict_helper(self, ['control_radius', 'qubits'])

from __future__ import annotations
from typing import Any, TYPE_CHECKING
import cirq
if TYPE_CHECKING:
    from cirq.protocols.decompose_protocol import DecomposeResult
class PasqalGateset(cirq.CompilationTargetGateset):
    def __init__(self, include_additional_controlled_ops: bool = True):
        gate_families: list[type[cirq.Gate] | cirq.Gate | cirq.GateFamily] = [
            cirq.ParallelGateFamily(cirq.H),
            cirq.ParallelGateFamily(cirq.PhasedXPowGate),
            cirq.ParallelGateFamily(cirq.XPowGate),
            cirq.ParallelGateFamily(cirq.YPowGate),
            cirq.ParallelGateFamily(cirq.ZPowGate),
            cirq.AnyIntegerPowerGateFamily(cirq.CZPowGate),
            cirq.IdentityGate,
            cirq.MeasurementGate,
        ]
        self.include_additional_controlled_ops = include_additional_controlled_ops
        if self.include_additional_controlled_ops:
            gate_families.append(cirq.AnyIntegerPowerGateFamily(cirq.CNotPowGate))
            gate_families.append(cirq.AnyIntegerPowerGateFamily(cirq.CCNotPowGate))
            gate_families.append(cirq.AnyIntegerPowerGateFamily(cirq.CCZPowGate))
        super().__init__(*gate_families, unroll_circuit_op=False)
    @property
    def num_qubits(self) -> int:
        return 2
    def decompose_to_target_gateset(self, op: cirq.Operation, moment_idx: int) -> DecomposeResult:
        mat = cirq.unitary(op, None) if len(op.qubits) <= 2 else None
        if mat is not None and len(op.qubits) == 1:
            gates = cirq.single_qubit_matrix_to_phased_x_z(mat)
            return [g.on(op.qubits[0]) for g in gates]
        if mat is not None and len(op.qubits) == 2:
            return cirq.two_qubit_matrix_to_cz_operations(
                op.qubits[0], op.qubits[1], mat, allow_partial_czs=False, clean_operations=True
            )
        return NotImplemented
    @property
    def preprocess_transformers(self) -> list[cirq.TRANSFORMER]:
        return []
    @property
    def postprocess_transformers(self) -> list[cirq.TRANSFORMER]:
        return []
    def __repr__(self):
        return (
            f'cirq_pasqal.PasqalGateset(include_additional_controlled_ops='
            f'{self.include_additional_controlled_ops})'
        )
    @classmethod
    def _from_json_dict_(cls, include_additional_controlled_ops, **kwargs):
        return cls(include_additional_controlled_ops=include_additional_controlled_ops)
    def _json_dict_(self) -> dict[str, Any]:
        return cirq.protocols.obj_to_dict_helper(self, ['include_additional_controlled_ops'])

from __future__ import annotations
from collections.abc import Sequence
from typing import Any
import cirq
import cirq_pasqal
class PasqalNoiseModel(cirq.devices.NoiseModel):
    def __init__(self, device: cirq.devices.Device):
        self.noise_op_dict = self.get_default_noise_dict()
        if not isinstance(device, cirq_pasqal.PasqalDevice):
            raise TypeError(
                "The noise model varies between Pasqal's devices. "
                "Please specify the one you intend to execute the "
                "circuit on."
            )
        self.device = device
    def get_default_noise_dict(self) -> dict[str, Any]:
        default_noise_dict = {
            str(cirq.YPowGate()): cirq.depolarize(1e-2),
            str(cirq.ZPowGate()): cirq.depolarize(1e-2),
            str(cirq.XPowGate()): cirq.depolarize(1e-2),
            str(cirq.PhasedXPowGate(phase_exponent=0)): cirq.depolarize(1e-2),
            str(cirq.HPowGate(exponent=1)): cirq.depolarize(1e-2),
            str(cirq.CNotPowGate(exponent=1)): cirq.depolarize(3e-2),
            str(cirq.CZPowGate(exponent=1)): cirq.depolarize(3e-2),
            str(cirq.CCXPowGate(exponent=1)): cirq.depolarize(8e-2),
            str(cirq.CCZPowGate(exponent=1)): cirq.depolarize(8e-2),
        }
        return default_noise_dict
    def noisy_moment(
        self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]
    ) -> list[cirq.Operation]:
        noise_list = []
        for op in moment:
            op_str = self.get_op_string(op)
            noise_op = self.noise_op_dict.get(op_str, cirq.depolarize(5e-2))
            for qubit in op.qubits:
                noise_list.append(noise_op.on(qubit))
        return list(moment) + noise_list
    def get_op_string(self, cirq_op: cirq.Operation) -> str:
        if not self.device.is_pasqal_device_op(cirq_op) or isinstance(
            cirq_op.gate, cirq.MeasurementGate
        ):
            raise ValueError('Got unknown operation:', cirq_op)
        return str(cirq_op.gate)

from __future__ import annotations
import numpy as np
from numpy import sqrt
import cirq
class ThreeDQubit(cirq.ops.Qid):
    def __init__(self, x: float, y: float, z: float):
        self.x = x
        self.y = y
        self.z = z
    def _comparison_key(self):
        return round(self.z, 15), round(self.y, 15), round(self.x, 15)
    @property
    def dimension(self) -> int:
        return 2
    def distance(self, other: cirq.ops.Qid) -> float:
        if not isinstance(other, ThreeDQubit):
            raise TypeError(f"Can compute distance to another ThreeDQubit, but {other}")
        return sqrt((self.x - other.x) ** 2 + (self.y - other.y) ** 2 + (self.z - other.z) ** 2)
    @staticmethod
    def cube(diameter: int, x0: float = 0, y0: float = 0, z0: float = 0) -> list[ThreeDQubit]:
        return ThreeDQubit.parallelep(diameter, diameter, diameter, x0=x0, y0=y0, z0=z0)
    @staticmethod
    def parallelep(
        rows: int, cols: int, lays: int, x0: float = 0, y0: float = 0, z0: float = 0
    ) -> list[ThreeDQubit]:
        return [
            ThreeDQubit(x0 + x, y0 + y, z0 + z)
            for z in range(lays)
            for y in range(cols)
            for x in range(rows)
        ]
    def __repr__(self):
        return f'pasqal.ThreeDQubit({self.x}, {self.y}, {self.z})'
    def __str__(self):
        return f'({self.x}, {self.y}, {self.z})'
    def _json_dict_(self):
        return cirq.protocols.obj_to_dict_helper(self, ['x', 'y', 'z'])
class TwoDQubit(ThreeDQubit):
    def __init__(self, x: float, y: float):
        super().__init__(x, y, z=0)
    @staticmethod
    def square(diameter: int, x0: float = 0, y0: float = 0) -> list[TwoDQubit]:
        return TwoDQubit.rect(diameter, diameter, x0=x0, y0=y0)
    @staticmethod
    def rect(rows: int, cols: int, x0: float = 0, y0: float = 0) -> list[TwoDQubit]:
        return [TwoDQubit(x0 + x, y0 + y) for y in range(cols) for x in range(rows)]
    @staticmethod
    def triangular_lattice(l: int, x0: float = 0, y0: float = 0):
        coords = np.array([[x, y] for x in range(l + 1) for y in range(l + 1)], dtype=float)
        coords[:, 0] += 0.5 * np.mod(coords[:, 1], 2)
        coords[:, 1] *= np.sqrt(3) / 2
        coords += [x0, y0]
        return [TwoDQubit(coord[0], coord[1]) for coord in coords]
    def __repr__(self):
        return f'pasqal.TwoDQubit({self.x}, {self.y})'
    def __str__(self):
        return f'({self.x}, {self.y})'
    def _json_dict_(self):
        return cirq.protocols.obj_to_dict_helper(self, ['x', 'y'])

from __future__ import annotations
import re
from collections.abc import Callable, Iterator, Sequence, Set
from typing import TYPE_CHECKING
import numpy as np
import sympy
from cirq import linalg, ops, protocols, value
from cirq._compat import proper_repr
if TYPE_CHECKING:
    import cirq
@value.value_equality(approximate=True)
class QasmUGate(ops.Gate):
    def __init__(self, theta: cirq.TParamVal, phi: cirq.TParamVal, lmda: cirq.TParamVal) -> None:
        self.theta = theta % 2
        self.phi = phi % 2
        self.lmda = lmda % 2
    def _num_qubits_(self) -> int:
        return 1
    @staticmethod
    def from_matrix(mat: np.ndarray) -> QasmUGate:
        pre_phase, rotation, post_phase = linalg.deconstruct_single_qubit_matrix_into_angles(mat)
        return QasmUGate(rotation / np.pi, post_phase / np.pi, pre_phase / np.pi)
    def _has_unitary_(self):
        return not self._is_parameterized_()
    def _is_parameterized_(self) -> bool:
        return (
            protocols.is_parameterized(self.theta)
            or protocols.is_parameterized(self.phi)
            or protocols.is_parameterized(self.lmda)
        )
    def _parameter_names_(self) -> Set[str]:
        return (
            protocols.parameter_names(self.theta)
            | protocols.parameter_names(self.phi)
            | protocols.parameter_names(self.lmda)
        )
    def _resolve_parameters_(self, resolver: cirq.ParamResolver, recursive: bool) -> QasmUGate:
        return QasmUGate(
            protocols.resolve_parameters(self.theta, resolver, recursive),
            protocols.resolve_parameters(self.phi, resolver, recursive),
            protocols.resolve_parameters(self.lmda, resolver, recursive),
        )
    def _qasm_(self, qubits: tuple[cirq.Qid, ...], args: cirq.QasmArgs) -> str:
        args.validate_version('2.0', '3.0')
        return args.format(
            'u3({0:half_turns},{1:half_turns},{2:half_turns}) {3};\n',
            self.theta,
            self.phi,
            self.lmda,
            qubits[0],
        )
    def __repr__(self) -> str:
        return (
            f'cirq.circuits.qasm_output.QasmUGate('
            f'theta={proper_repr(self.theta)}, '
            f'phi={proper_repr(self.phi)}, '
            f'lmda={proper_repr(self.lmda)})'
        )
    def _decompose_(self, qubits):
        def mul_pi(x):
            return x * (sympy.pi if protocols.is_parameterized(x) else np.pi)
        q = qubits[0]
        phase_correction_half_turns = (self.phi + self.lmda) / 2
        return [
            ops.rz(mul_pi(self.lmda)).on(q),
            ops.ry(mul_pi(self.theta)).on(q),
            ops.rz(mul_pi(self.phi)).on(q),
            ops.global_phase_operation(1j ** (2 * phase_correction_half_turns)),
        ]
    def _value_equality_values_(self):
        return self.lmda, self.theta, self.phi
    def _json_dict_(self) -> dict[str, float]:
        return {'theta': self.theta, 'phi': self.phi, 'lmda': self.lmda}
    @classmethod
    def _from_json_dict_(cls, theta: float, phi: float, lmda: float, **kwargs) -> QasmUGate:
        return cls(theta, phi, lmda)
@value.value_equality
class QasmTwoQubitGate(ops.Gate):
    def __init__(self, kak: cirq.KakDecomposition) -> None:
        self.kak = kak
    def _num_qubits_(self) -> int:
        return 2
    def _value_equality_values_(self):
        return self.kak
    @staticmethod
    def from_matrix(mat: np.ndarray, atol=1e-8) -> QasmTwoQubitGate:
        kak = linalg.kak_decomposition(mat, atol=atol)
        return QasmTwoQubitGate(kak)
    def _unitary_(self):
        return protocols.unitary(self.kak)
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        q0, q1 = qubits
        x, y, z = self.kak.interaction_coefficients
        a = x * -2 / np.pi + 0.5
        b = y * -2 / np.pi + 0.5
        c = z * -2 / np.pi + 0.5
        b0, b1 = self.kak.single_qubit_operations_before
        yield QasmUGate.from_matrix(b0).on(q0)
        yield QasmUGate.from_matrix(b1).on(q1)
        yield ops.X(q0) ** 0.5
        yield ops.CNOT(q0, q1)
        yield ops.X(q0) ** a
        yield ops.Y(q1) ** b
        yield ops.CNOT(q1, q0)
        yield ops.X(q1) ** -0.5
        yield ops.Z(q1) ** c
        yield ops.CNOT(q0, q1)
        a0, a1 = self.kak.single_qubit_operations_after
        yield QasmUGate.from_matrix(a0).on(q0)
        yield QasmUGate.from_matrix(a1).on(q1)
    def __repr__(self) -> str:
        return f'cirq.circuits.qasm_output.QasmTwoQubitGate({self.kak!r})'
class QasmOutput:
    valid_id_re = re.compile(r'[a-z][a-zA-Z0-9_]*\Z')
    def __init__(
        self,
        operations: cirq.OP_TREE,
        qubits: tuple[cirq.Qid, ...],
        header: str = '',
        precision: int = 10,
        version: str = '2.0',
    ) -> None:
        self.operations = tuple(ops.flatten_to_ops(operations))
        self.qubits = qubits
        self.header = header
        self.measurements = tuple(
            op for op in self.operations if isinstance(op.gate, ops.MeasurementGate)
        )
        meas_key_id_map, meas_comments = self._generate_measurement_ids()
        self.meas_comments = meas_comments
        qubit_id_map = self._generate_qubit_ids()
        self.cregs = self._generate_cregs(meas_key_id_map)
        self.args = protocols.QasmArgs(
            precision=precision,
            version=version,
            qubit_id_map=qubit_id_map,
            meas_key_id_map=meas_key_id_map,
            meas_key_bitcount={k: v[0] for k, v in self.cregs.items()},
        )
    def _generate_measurement_ids(self) -> tuple[dict[str, str], dict[str, str | None]]:
        meas_key_id_map: dict[str, str] = {}
        meas_comments: dict[str, str | None] = {}
        meas_i = 0
        for meas in self.measurements:
            key = protocols.measurement_key_name(meas)
            if key in meas_key_id_map:
                continue
            meas_id = f'm_{key}'
            if self.is_valid_qasm_id(meas_id):
                meas_comments[key] = None
            else:
                meas_id = f'm{meas_i}'
                meas_i += 1
                meas_comments[key] = ' '.join(key.split('\n'))
            meas_key_id_map[key] = meas_id
        return meas_key_id_map, meas_comments
    def _generate_qubit_ids(self) -> dict[cirq.Qid, str]:
        return {qubit: f'q[{i}]' for i, qubit in enumerate(self.qubits)}
    def _generate_cregs(self, meas_key_id_map: dict[str, str]) -> dict[str, tuple[int, str]]:
        cregs: dict[str, tuple[int, str]] = {}
        for meas in self.measurements:
            key = protocols.measurement_key_name(meas)
            meas_id = meas_key_id_map[key]
            if self.meas_comments[key] is not None:
                comment = f'  // Measurement: {self.meas_comments[key]}'
            else:
                comment = ''
            if meas_id not in cregs or cregs[meas_id][0] < len(meas.qubits):
                cregs[meas_id] = (len(meas.qubits), comment)
        return cregs
    def is_valid_qasm_id(self, id_str: str) -> bool:
        return self.valid_id_re.match(id_str) is not None
    def save(self, path: str | bytes | int) -> None:
        with open(path, 'w') as f:
            def write(s: str) -> None:
                f.write(s)
            self._write_qasm(write)
    def __str__(self) -> str:
        output = []
        self._write_qasm(lambda s: output.append(s))
        return ''.join(output)
    def _write_qasm(self, output_func: Callable[[str], None]) -> None:
        self.args.validate_version('2.0', '3.0')
        line_gap = [0]
        def output_line_gap(n):
            line_gap[0] = max(line_gap[0], n)
        def output(text):
            if line_gap[0] > 0:
                output_func('\n' * line_gap[0])
                line_gap[0] = 0
            output_func(text)
        if self.header:
            for line in self.header.split('\n'):
                output(('// ' + line).rstrip() + '\n')
            output('\n')
        output(f'OPENQASM {self.args.version};\n')
        if self.args.version == '2.0':
            output('include "qelib1.inc";\n')
        else:
            output('include "stdgates.inc";\n')
        output_line_gap(2)
        output(f"// Qubits: [{', '.join(map(str, self.qubits))}]\n")
        if len(self.qubits) > 0:
            if self.args.version == '2.0':
                output(f'qreg q[{len(self.qubits)}];\n')
            else:
                output(f'qubit[{len(self.qubits)}] q;\n')
        for meas_id in self.cregs:
            length, comment = self.cregs[meas_id]
            if self.args.version == '2.0':
                output(f'creg {meas_id}[{length}];{comment}\n')
            else:
                output(f'bit[{length}] {meas_id};{comment}\n')
        if any(not isinstance(op.gate, ops.GlobalPhaseGate) for op in self.operations):
            output_line_gap(2)
        self._write_operations(self.operations, output, output_line_gap)
    def _write_operations(
        self,
        op_tree: cirq.OP_TREE,
        output: Callable[[str], None],
        output_line_gap: Callable[[int], None],
    ) -> None:
        def keep(op: cirq.Operation) -> bool:
            return protocols.qasm(op, args=self.args, default=None) is not None
        def fallback(op):
            if len(op.qubits) not in [1, 2]:
                return NotImplemented
            mat = protocols.unitary(op, None)
            if mat is None:
                return NotImplemented
            if len(op.qubits) == 1:
                return QasmUGate.from_matrix(mat).on(*op.qubits)  # pragma: no cover
            return QasmTwoQubitGate.from_matrix(mat).on(*op.qubits)
        def on_stuck(bad_op):
            return ValueError(f'Cannot output operation as QASM: {bad_op!r}')
        for main_op in ops.flatten_op_tree(op_tree):
            decomposed = protocols.decompose(
                main_op, keep=keep, fallback_decomposer=fallback, on_stuck_raise=on_stuck
            )
            qasms = [protocols.qasm(op, args=self.args) for op in decomposed]
            should_annotate = decomposed != [main_op] or qasms[0].count('\n') > 1
            if should_annotate:
                output_line_gap(1)
                if isinstance(main_op, ops.GateOperation):
                    x = str(main_op.gate).replace('\n', '\n//       ')
                    output(f'// Gate: {x!s}\n')
                else:
                    x = str(main_op).replace('\n', '\n//            ')
                    output(f'// Operation: {x!s}\n')
            for qasm in qasms:
                output(qasm)
            if should_annotate:
                output_line_gap(1)

