from __future__ import annotations
import numpy as np
import cirq
def _build_by_code(mat: np.ndarray) -> list[str]:
    out = []
    n = mat.shape[1] // 2
    for i in range(mat.shape[0]):
        ps = ''
        for j in range(n):
            k = 2 * mat[i, j + n] + mat[i, j]
            ps += "IXZY"[k]
        out.append(ps)
    return out
def _gaussian_elimination(
    M: np.ndarray, min_row: int, max_row: int, min_col: int, max_col: int
) -> int:
    assert M.shape[1] % 2 == 0
    n = M.shape[1] // 2
    max_rank = min(max_row - min_row, max_col - min_col)
    rank = 0
    for r in range(max_rank):
        i = min_row + r
        j = min_col + r
        pivot_rows, pivot_cols = np.nonzero(M[i:max_row, j:max_col])
        if pivot_rows.size == 0:
            break
        pi = pivot_rows[0]
        pj = pivot_cols[0]
        M[[i, i + pi]] = M[[i + pi, i]]
        M[:, [(j + pj), j]] = M[:, [j, (j + pj)]]
        j_other_half = (j + n) % (2 * n)
        M[:, [(j_other_half + pj), j_other_half]] = M[:, [j_other_half, (j_other_half + pj)]]
        for k in range(i + 1, max_row):
            if M[k, j] == 1:
                M[k, :] = np.mod(M[i, :] + M[k, :], 2)
        rank += 1
    for r in reversed(range(rank)):
        i = min_row + r
        j = min_col + r
        for k in range(i - 1, min_row - 1, -1):
            if M[k, j] == 1:
                M[k, :] = np.mod(M[i, :] + M[k, :], 2)
    return rank
def _transfer_to_standard_form(
    M: np.ndarray, n: int, k: int
) -> tuple[np.ndarray, np.ndarray, np.ndarray, int]:
    r: int = _gaussian_elimination(M, 0, n - k, 0, n)
    _ = _gaussian_elimination(M, r, n - k, n + r, 2 * n)
    A2 = M[0:r, (n - k) : n]
    C1 = M[0:r, (n + r) : (2 * n - k)]
    C2 = M[0:r, (2 * n - k) : (2 * n)]
    E = M[r : (n - k), (2 * n - k) : (2 * n)]
    X = np.concatenate(
        [
            np.zeros((k, r), dtype=np.int8),
            E.T,
            np.eye(k, dtype=np.int8),
            np.mod(E.T @ C1.T + C2.T, 2),
            np.zeros((k, n - r), np.int8),
        ],
        axis=1,
    )
    Z = np.concatenate(
        [
            np.zeros((k, n), dtype=np.int8),
            A2.T,
            np.zeros((k, n - k - r), dtype=np.int8),
            np.eye(k, dtype=np.int8),
        ],
        axis=1,
    )
    return M, X, Z, r
class StabilizerCode:
    def __init__(self, group_generators: list[str], correctable_errors: list[str]):
        n = len(group_generators[0])
        k = n - len(group_generators)
        M = np.zeros((n - k, 2 * n), np.int8)
        for i, group_generator in enumerate(group_generators):
            for j, c in enumerate(group_generator):
                if c == 'X' or c == 'Y':
                    M[i, j] = 1
                elif c == 'Z' or c == 'Y':
                    M[i, n + j] = 1
        M, X, Z, r = _transfer_to_standard_form(M, n, k)
        self.n: int = n
        self.k: int = k
        self.r: int = r
        self.M: list[str] = _build_by_code(M)
        self.logical_Xs: list[str] = _build_by_code(X)
        self.logical_Zs: list[str] = _build_by_code(Z)
        self.syndromes_to_corrections: dict[tuple[int, ...], tuple[str, int]] = {}
        for qid in range(self.n):
            for op in correctable_errors:
                syndrome = tuple(
                    1 if self.M[r][qid] == 'I' or self.M[r][qid] == op else -1
                    for r in range(self.n - self.k)
                )
                self.syndromes_to_corrections[syndrome] = (op, qid)
    def encode(
        self, additional_qubits: list[cirq.Qid], unencoded_qubits: list[cirq.Qid]
    ) -> cirq.Circuit:
        assert len(additional_qubits) == self.n - self.k
        assert len(unencoded_qubits) == self.k
        qubits = additional_qubits + unencoded_qubits
        circuit = cirq.Circuit()
        for r, x in enumerate(self.logical_Xs):
            for j in range(self.r, self.n - self.k):
                if x[j] == 'X' or x[j] == 'Y':
                    circuit.append(
                        cirq.ControlledOperation(
                            [unencoded_qubits[r]], cirq.X(additional_qubits[j])
                        )
                    )
        gate_dict = {'X': cirq.X, 'Y': cirq.Y, 'Z': cirq.Z}
        for r in range(self.r):
            circuit.append(cirq.H(qubits[r]))
            if self.M[r][r] == 'Y' or self.M[r][r] == 'Z':
                circuit.append(cirq.S(qubits[r]))
            for n in range(self.n):
                if n == r:
                    continue
                if self.M[r][n] == 'I':
                    continue
                op = gate_dict[self.M[r][n]]
                circuit.append(cirq.ControlledOperation([qubits[r]], op(qubits[n])))
        return circuit
    def correct(self, qubits: list[cirq.Qid], ancillas: list[cirq.Qid]) -> cirq.Circuit:
        circuit = cirq.Circuit()
        gate_dict = {'X': cirq.X, 'Y': cirq.Y, 'Z': cirq.Z}
        for r in range(self.n - self.k):
            for n in range(self.n):
                if self.M[r][n] == 'Z':
                    circuit.append(cirq.ControlledOperation([qubits[n]], cirq.X(ancillas[r])))
                elif self.M[r][n] == 'X':
                    circuit.append(cirq.H(qubits[n]))
                    circuit.append(cirq.ControlledOperation([qubits[n]], cirq.X(ancillas[r])))
                    circuit.append(cirq.H(qubits[n]))
                elif self.M[r][n] == 'Y':
                    circuit.append(cirq.S(qubits[n]) ** -1)
                    circuit.append(cirq.H(qubits[n]))
                    circuit.append(cirq.ControlledOperation([qubits[n]], cirq.X(ancillas[r])))
                    circuit.append(cirq.H(qubits[n]))
                    circuit.append(cirq.S(qubits[n]))
        for syndrome, correction in self.syndromes_to_corrections.items():
            op = gate_dict[correction[0]]
            n = correction[1]
            for r in range(self.n - self.k):
                if syndrome[r] == 1:
                    circuit.append(cirq.X(ancillas[r]))
            circuit.append(cirq.ControlledOperation(ancillas, op(qubits[n])))
            for r in range(self.n - self.k):
                if syndrome[r] == 1:
                    circuit.append(cirq.X(ancillas[r]))
        return circuit
    def decode(self, qubits: list[cirq.Qid], ancillas: list[cirq.Qid], state_vector) -> list[int]:
        r
        qubit_map = {qubit: i for i, qubit in enumerate(qubits + ancillas)}
        decoded = []
        for z in self.logical_Zs:
            pauli_string: cirq.PauliString = cirq.PauliString(dict(zip(qubits, z)))
            trace = pauli_string.expectation_from_state_vector(state_vector, qubit_map)
            decoded.append(round((1 - trace.real) / 2))
        return decoded

from __future__ import annotations
from typing import cast
import numpy as np
import pytest
import cirq
import examples.stabilizer_code as sc
def encode_corrupt_correct(
    code: sc.StabilizerCode, input_val: int, error_gate: cirq.Gate | None, error_loc: int | None
):
    circuit = cirq.Circuit()
    additional_qubits: list[cirq.Qid] = cast(
        list[cirq.Qid], [cirq.NamedQubit(str(i)) for i in range(code.n - code.k)]
    )
    unencoded_qubits: list[cirq.Qid] = cast(list[cirq.Qid], [cirq.NamedQubit('c')])
    qubits = additional_qubits + unencoded_qubits
    ancillas: list[cirq.Qid] = cast(
        list[cirq.Qid], [cirq.NamedQubit(f"d{i}") for i in range(code.n - code.k)]
    )
    circuit += code.encode(additional_qubits, unencoded_qubits)
    if error_gate and error_loc:
        circuit.append(error_gate(qubits[error_loc]))
    circuit += code.correct(qubits, ancillas)
    state_vector = (
        cirq.Simulator()
        .simulate(
            circuit, qubit_order=(qubits + ancillas), initial_state=(input_val * 2 ** len(ancillas))
        )
        .state_vector()
    )
    decoded = code.decode(qubits, ancillas, state_vector)
    nq = len(qubits)
    na = len(ancillas)
    traced_out_state = np.sum(
        state_vector.reshape((2,) * (nq + na)), axis=tuple(range(nq, nq + na))
    ).reshape(-1)
    return decoded[0], traced_out_state
def test_no_error() -> None:
    five_qubit_code = sc.StabilizerCode(
        group_generators=['XZZXI', 'IXZZX', 'XIXZZ', 'ZXIXZ'], correctable_errors=['X', 'Z']
    )
    for input_val in [0, 1]:
        decoded, _ = encode_corrupt_correct(
            five_qubit_code, input_val, error_gate=None, error_loc=None
        )
        assert decoded == input_val
@pytest.mark.parametrize(
    'group_generators',
    [
        (['XZZXI', 'IXZZX', 'XIXZZ', 'ZXIXZ']),
        (['XXXXIII', 'XXIIXXI', 'XIXIXIX', 'ZZZZIII', 'ZZIIZZI', 'ZIZIZIZ']),
    ],
)
def test_errors(group_generators) -> None:
    code = sc.StabilizerCode(group_generators=group_generators, correctable_errors=['X', 'Z'])
    for input_val in [0, 1]:
        _, traced_out_state_no_error = encode_corrupt_correct(
            code, input_val, error_gate=None, error_loc=None
        )
        for error_gate in [cirq.X, cirq.Z]:
            for error_loc in range(code.n):
                decoded, traced_out_state = encode_corrupt_correct(
                    code, input_val, error_gate, error_loc
                )
                assert decoded == input_val
                np.testing.assert_allclose(traced_out_state_no_error, traced_out_state, atol=1e-6)
def test_imperfect_code() -> None:
    bit_flip_code = sc.StabilizerCode(group_generators=['ZZI', 'ZIZ'], correctable_errors=['X'])
    for input_val in [0, 1]:
        _, traced_out_state_no_error = encode_corrupt_correct(
            bit_flip_code, input_val, error_gate=None, error_loc=None
        )
        for error_gate in [cirq.X]:
            for error_loc in range(bit_flip_code.n):
                decoded, traced_out_state = encode_corrupt_correct(
                    bit_flip_code, input_val, error_gate, error_loc
                )
                assert decoded == input_val
                np.testing.assert_allclose(traced_out_state_no_error, traced_out_state, atol=1e-6)
    _, traced_out_state_no_error = encode_corrupt_correct(
        bit_flip_code, input_val=1, error_gate=None, error_loc=None
    )
    _, traced_out_state_z1_error = encode_corrupt_correct(
        bit_flip_code, input_val=1, error_gate=cirq.Z, error_loc=1
    )
    with np.testing.assert_raises(AssertionError):
        np.testing.assert_allclose(traced_out_state_no_error, traced_out_state_z1_error, atol=1e-6)

from __future__ import annotations
import abc
from dataclasses import dataclass, field
from functools import cached_property
from typing import TYPE_CHECKING
from cirq import devices, ops, qis
from cirq.devices import noise_utils
if TYPE_CHECKING:
    import cirq
@dataclass
class SuperconductingQubitsNoiseProperties(devices.NoiseProperties, abc.ABC):
    gate_times_ns: dict[type, float]
    t1_ns: dict[cirq.Qid, float]
    tphi_ns: dict[cirq.Qid, float]
    readout_errors: dict[cirq.Qid, list[float]]
    gate_pauli_errors: dict[noise_utils.OpIdentifier, float]
    validate: bool = True
    _qubits: list[cirq.Qid] = field(init=False, default_factory=list)
    def __post_init__(self):
        if not self.validate:
            return
        t1_qubits = set(self.t1_ns)
        tphi_qubits = set(self.tphi_ns)
        if t1_qubits != tphi_qubits:
            raise ValueError('Keys specified for T1 and Tphi are not identical.')
        self._validate_symmetric_errors('gate_pauli_errors')
    def _validate_symmetric_errors(self, field_name: str) -> None:
        gate_error_dict = getattr(self, field_name)
        for op_id in gate_error_dict:
            if len(op_id.qubits) != 2:
                if len(op_id.qubits) > 2:
                    raise ValueError(
                        f'Found gate {op_id.gate_type} with {len(op_id.qubits)} qubits. '
                        'Symmetric errors can only apply to 2-qubit gates.'
                    )
            elif op_id.gate_type in self.symmetric_two_qubit_gates():
                op_id_swapped = noise_utils.OpIdentifier(op_id.gate_type, *op_id.qubits[::-1])
                if op_id_swapped not in gate_error_dict:
                    raise ValueError(
                        f'Operation {op_id} of field {field_name} has errors '
                        f'but its symmetric id {op_id_swapped} does not.'
                    )
            elif op_id.gate_type not in self.asymmetric_two_qubit_gates():
                raise ValueError(
                    f'Found gate {op_id.gate_type} which does not appear in the '
                    'symmetric or asymmetric gate sets.'
                )
    @property
    def qubits(self) -> list[cirq.Qid]:
        if not self._qubits:
            self._qubits = sorted(self.t1_ns)
        return self._qubits
    @classmethod
    @abc.abstractmethod
    def single_qubit_gates(cls) -> set[type[ops.Gate]]:
    @classmethod
    @abc.abstractmethod
    def symmetric_two_qubit_gates(cls) -> set[type[ops.Gate]]:
    @classmethod
    @abc.abstractmethod
    def asymmetric_two_qubit_gates(cls) -> set[type[ops.Gate]]:
    @classmethod
    def two_qubit_gates(cls) -> set[type[ops.Gate]]:
        return cls.symmetric_two_qubit_gates() | cls.asymmetric_two_qubit_gates()
    @classmethod
    def expected_gates(cls) -> set[type[ops.Gate]]:
        return cls.single_qubit_gates() | cls.two_qubit_gates()
    def _get_pauli_error(self, p_error: float, op_id: noise_utils.OpIdentifier):
        time_ns = float(self.gate_times_ns[op_id.gate_type])
        for q in op_id.qubits:
            p_error -= qis.decoherence_pauli_error(self.t1_ns[q], self.tphi_ns[q], time_ns)
        return p_error
    @cached_property
    def _depolarizing_error(self) -> dict[noise_utils.OpIdentifier, float]:
        depol_errors = {}
        for op_id, p_error in self.gate_pauli_errors.items():
            gate_type = op_id.gate_type
            if issubclass(gate_type, ops.MeasurementGate):
                continue
            expected_qubits = 1 if gate_type in self.single_qubit_gates() else 2
            if len(op_id.qubits) != expected_qubits:
                raise ValueError(
                    f'Gate {gate_type} takes {expected_qubits} qubit(s), '
                    f'but {op_id.qubits} were given.'
                )
            depol_errors[op_id] = self._get_pauli_error(p_error, op_id)
        return depol_errors
    def build_noise_models(self) -> list[cirq.NoiseModel]:
        noise_models: list[cirq.NoiseModel] = []
        if self.t1_ns:
            noise_models.append(
                devices.ThermalNoiseModel(
                    set(self.t1_ns.keys()),
                    self.gate_times_ns,
                    cool_rate_GHz={q: 1 / T1 for q, T1 in self.t1_ns.items()},
                    dephase_rate_GHz={q: 1 / Tp for q, Tp in self.tphi_ns.items()},
                )
            )
        depolarizing_error = self._depolarizing_error
        added_pauli_errors = {
            op_id: ops.depolarize(p_error, len(op_id.qubits)).on(*op_id.qubits)
            for op_id, p_error in depolarizing_error.items()
            if p_error > 0
        }
        noise_models.append(devices.InsertionNoiseModel(ops_added=added_pauli_errors))
        if self.readout_errors:
            added_measure_errors: dict[noise_utils.OpIdentifier, cirq.Operation] = {}
            for qubit in self.readout_errors:
                p_00, p_11 = self.readout_errors[qubit]
                p = p_11 / (p_00 + p_11)
                gamma = p_11 / p
                added_measure_errors[noise_utils.OpIdentifier(ops.MeasurementGate, qubit)] = (
                    ops.generalized_amplitude_damp(p, gamma).on(qubit)
                )
            noise_models.append(
                devices.InsertionNoiseModel(ops_added=added_measure_errors, prepend=True)
            )
        return noise_models

from __future__ import annotations
import warnings
from collections.abc import Sequence
from typing import Any, cast, TYPE_CHECKING
import numpy as np
import pandas as pd
import sympy
from matplotlib import pyplot as plt
from cirq import _import, circuits, ops, study, value
from cirq._compat import proper_repr
if TYPE_CHECKING:
    import cirq
optimize = _import.LazyLoader("optimize", globals(), "scipy.optimize")
def t1_decay(
    sampler: cirq.Sampler,
    *,
    qubit: cirq.Qid,
    num_points: int,
    max_delay: cirq.DURATION_LIKE,
    min_delay: cirq.DURATION_LIKE = None,
    repetitions: int = 1000,
) -> cirq.experiments.T1DecayResult:
    min_delay_dur = value.Duration(min_delay)
    max_delay_dur = value.Duration(max_delay)
    min_delay_nanos = min_delay_dur.total_nanos()
    max_delay_nanos = max_delay_dur.total_nanos()
    if repetitions <= 0:
        raise ValueError('repetitions <= 0')
    if isinstance(min_delay_nanos, sympy.Expr) or isinstance(max_delay_nanos, sympy.Expr):
        raise ValueError('min_delay and max_delay cannot be sympy expressions.')
    if max_delay_dur < min_delay_dur:
        raise ValueError('max_delay < min_delay')
    if min_delay_dur < 0:
        raise ValueError('min_delay < 0')
    var = sympy.Symbol('delay_ns')
    if min_delay_nanos == 0:
        min_delay_nanos = 0.4
    sweep_vals_ns = np.unique(
        np.round(np.logspace(np.log10(min_delay_nanos), np.log10(max_delay_nanos), num_points))
    )
    sweep = study.Points(var, cast(Sequence[float], sweep_vals_ns))
    circuit = circuits.Circuit(
        ops.X(qubit), ops.wait(qubit, nanos=var), ops.measure(qubit, key='output')
    )
    results = sampler.sample(circuit, params=sweep, repetitions=repetitions)
    tab = pd.crosstab(results.delay_ns, results.output)
    tab.rename_axis(None, axis="columns", inplace=True)
    tab = tab.rename(columns={0: 'false_count', 1: 'true_count'}).reset_index()
    for col_index, name in [(1, 'false_count'), (2, 'true_count')]:
        if name not in tab:
            tab.insert(col_index, name, [0] * tab.shape[0])
    return T1DecayResult(tab)
class T1DecayResult:
    def __init__(self, data: pd.DataFrame):
        assert list(data.columns) == ['delay_ns', 'false_count', 'true_count']
        self._data = data
    @property
    def data(self) -> pd.DataFrame:
        return self._data
    @property
    def constant(self) -> float:
        def exp_decay(x, t1, a, b):
            return a * np.exp(-x / t1) + b
        xs = self._data['delay_ns']
        ts = self._data['true_count']
        fs = self._data['false_count']
        probs = ts / (fs + ts)
        guess_index = np.argmin(np.abs(probs - 1.0 / np.e))
        t1_guess = xs[guess_index]
        try:
            self.popt, _ = optimize.curve_fit(exp_decay, xs, probs, p0=[t1_guess, 1.0, 0.0])
            t1 = self.popt[0]
            return t1
        except RuntimeError:
            warnings.warn("Optimal parameters could not be found for curve fit", RuntimeWarning)
            return np.nan
    def plot(
        self, ax: plt.Axes | None = None, include_fit: bool = False, **plot_kwargs: Any
    ) -> plt.Axes:
        show_plot = not ax
        if show_plot:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        assert ax is not None
        ax.set_ylim(ymin=0, ymax=1)
        xs = self._data['delay_ns']
        ts = self._data['true_count']
        fs = self._data['false_count']
        ax.plot(xs, ts / (fs + ts), 'ro-', **plot_kwargs)
        if include_fit and not np.isnan(self.constant):
            t1 = self.constant
            t1, a, b = self.popt
            ax.plot(xs, a * np.exp(-xs / t1) + b, label='curve fit')
            plt.legend()
        ax.set_xlabel(r"Delay between initialization and measurement (nanoseconds)")
        ax.set_ylabel('Excited State Probability')
        ax.set_title('T1 Decay Experiment Data')
        if show_plot:
            fig.show()
        return ax
    def __str__(self) -> str:
        return f'T1DecayResult with data:\n{self.data}'
    def __eq__(self, other) -> bool:
        if not isinstance(other, type(self)):
            return NotImplemented
        return self.data.equals(other.data)
    def __ne__(self, other) -> bool:
        return not self == other
    def __repr__(self) -> str:
        return f'cirq.experiments.T1DecayResult(data={proper_repr(self.data)})'
    def _repr_pretty_(self, p: Any, cycle: bool) -> None:
        if cycle:
            p.text('T1DecayResult(...)')
        else:
            p.text(str(self))

from __future__ import annotations
import enum
from typing import Any, TYPE_CHECKING
import pandas as pd
import sympy
from matplotlib import pyplot as plt
from cirq import circuits, ops, study, value
from cirq._compat import proper_repr
if TYPE_CHECKING:
    import cirq
class ExperimentType(enum.Enum):
    RAMSEY = 1  # Often denoted as t2*
    HAHN_ECHO = 2  # Spin echo or t2
    CPMG = 3  # Carr-Purcell-Meiboom-Gill sequence
_T2_COLUMNS = ['delay_ns', 0, 1]
def t2_decay(
    sampler: cirq.Sampler,
    *,
    qubit: cirq.Qid,
    experiment_type: ExperimentType = ExperimentType.RAMSEY,
    num_points: int,
    max_delay: cirq.DURATION_LIKE,
    min_delay: cirq.DURATION_LIKE = None,
    repetitions: int = 1000,
    delay_sweep: study.Sweep | None = None,
    num_pulses: list[int] | None = None,
) -> cirq.experiments.T2DecayResult:
    min_delay_dur = value.Duration(min_delay)
    max_delay_dur = value.Duration(max_delay)
    min_delay_nanos = min_delay_dur.total_nanos()
    max_delay_nanos = max_delay_dur.total_nanos()
    if repetitions <= 0:
        raise ValueError('repetitions <= 0')
    if isinstance(min_delay_nanos, sympy.Expr) or isinstance(max_delay_nanos, sympy.Expr):
        raise ValueError('min_delay and max_delay cannot be sympy expressions.')
    if max_delay_dur < min_delay_dur:
        raise ValueError('max_delay < min_delay')
    if min_delay_dur < 0:
        raise ValueError('min_delay < 0')
    if num_pulses and experiment_type != ExperimentType.CPMG:
        raise ValueError('num_pulses is only valid for CPMG experiments.')
    delay_var = sympy.Symbol('delay_ns')
    inv_x_var = sympy.Symbol('inv_x')
    inv_y_var = sympy.Symbol('inv_y')
    max_pulses = max(num_pulses) if num_pulses else 0
    if not delay_sweep:
        delay_sweep = study.Linspace(
            delay_var, start=min_delay_nanos, stop=max_delay_nanos, length=num_points
        )
    if delay_sweep.keys != ['delay_ns']:
        raise ValueError('delay_sweep must be a SingleSweep with delay_ns parameter')
    if experiment_type == ExperimentType.RAMSEY:
        circuit = circuits.Circuit(ops.Y(qubit) ** 0.5, ops.wait(qubit, nanos=delay_var))
    else:
        if experiment_type == ExperimentType.HAHN_ECHO:
            num_pulses = [0]
        if not num_pulses:
            raise ValueError('At least one value must be given for num_pulses in a CPMG experiment')
        circuit = _cpmg_circuit(qubit, delay_var, max_pulses)
    circuit.append(ops.X(qubit) ** inv_x_var)
    circuit.append(ops.Y(qubit) ** inv_y_var)
    circuit.append(ops.measure(qubit, key='output'))
    tomography_sweep = study.Zip(
        study.Points('inv_x', [0.0, 0.5]), study.Points('inv_y', [-0.5, 0.0])
    )
    if num_pulses and max_pulses > 0:
        pulse_sweep = _cpmg_sweep(num_pulses)
        sweep = study.Product(delay_sweep, pulse_sweep, tomography_sweep)
    else:
        sweep = study.Product(delay_sweep, tomography_sweep)
    results = sampler.sample(circuit, params=sweep, repetitions=repetitions)
    y_basis_measurements = results[abs(results.inv_y) > 0].copy()
    x_basis_measurements = results[abs(results.inv_x) > 0].copy()
    if num_pulses and len(num_pulses) > 1:
        cols = tuple(f'pulse_{t}' for t in range(max_pulses))
        x_basis_measurements['num_pulses'] = x_basis_measurements.loc[:, cols].sum(axis=1)
        y_basis_measurements['num_pulses'] = y_basis_measurements.loc[:, cols].sum(axis=1)
    x_basis_tabulation = _create_tabulation(x_basis_measurements)
    y_basis_tabulation = _create_tabulation(y_basis_measurements)
    return T2DecayResult(x_basis_tabulation, y_basis_tabulation)
def _create_tabulation(measurements: pd.DataFrame) -> pd.DataFrame:
    if 'num_pulses' in measurements.columns:
        cols = [measurements.delay_ns, measurements.num_pulses]
    else:
        cols = [measurements.delay_ns]
    tabulation = pd.crosstab(cols, measurements.output).reset_index()
    for col_index, name in [(1, 0), (2, 1)]:
        if name not in tabulation:
            tabulation.insert(col_index, name, [0] * tabulation.shape[0])
    return tabulation
def _cpmg_circuit(qubit: cirq.Qid, delay_var: sympy.Symbol, max_pulses: int) -> cirq.Circuit:
    circuit = circuits.Circuit(ops.Y(qubit) ** 0.5, ops.wait(qubit, nanos=delay_var), ops.X(qubit))
    for n in range(max_pulses):
        pulse_n_on = sympy.Symbol(f'pulse_{n}')
        circuit.append(ops.wait(qubit, nanos=2 * delay_var * pulse_n_on))
        circuit.append(ops.X(qubit) ** pulse_n_on)
    circuit.append(ops.wait(qubit, nanos=delay_var))
    return circuit
def _cpmg_sweep(num_pulses: list[int]):
    pulse_points = []
    for n in range(max(num_pulses)):
        pulse_points.append(study.Points(f'pulse_{n}', [1 if p > n else 0 for p in num_pulses]))
    return study.Zip(*pulse_points)
class T2DecayResult:
    def __init__(self, x_basis_data: pd.DataFrame, y_basis_data: pd.DataFrame):
        x_cols = list(x_basis_data.columns)
        y_cols = list(y_basis_data.columns)
        if any(col not in x_cols for col in _T2_COLUMNS):
            raise ValueError(
                f'x_basis_data must have columns {_T2_COLUMNS} '
                f'but had {list(x_basis_data.columns)}'
            )
        if any(col not in y_cols for col in _T2_COLUMNS):
            raise ValueError(
                f'y_basis_data must have columns {_T2_COLUMNS} '
                f'but had {list(y_basis_data.columns)}'
            )
        self._x_basis_data = x_basis_data
        self._y_basis_data = y_basis_data
        self._expectation_pauli_x = self._expectation(x_basis_data)
        self._expectation_pauli_y = self._expectation(y_basis_data)
    def _expectation(self, data: pd.DataFrame) -> pd.DataFrame:
        delay = data['delay_ns']
        ones = data[1]
        zeros = data[0]
        pauli_expectation = (2 * (ones / (ones + zeros))) - 1.0
        if 'num_pulses' in data.columns:
            return pd.DataFrame(
                {'delay_ns': delay, 'num_pulses': data['num_pulses'], 'value': pauli_expectation}
            )
        return pd.DataFrame({'delay_ns': delay, 'value': pauli_expectation})
    @property
    def expectation_pauli_x(self) -> pd.DataFrame:
        return self._expectation_pauli_x
    @property
    def expectation_pauli_y(self) -> pd.DataFrame:
        return self._expectation_pauli_y
    def plot_expectations(self, ax: plt.Axes | None = None, **plot_kwargs: Any) -> plt.Axes:
        show_plot = not ax
        if show_plot:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        assert ax is not None
        ax.set_ylim(ymin=-2, ymax=2)
        ax.plot(
            self._expectation_pauli_x['delay_ns'],
            self._expectation_pauli_x['value'],
            'bo-',
            label='<X>',
            **plot_kwargs,
        )
        ax.plot(
            self._expectation_pauli_y['delay_ns'],
            self._expectation_pauli_y['value'],
            'go-',
            label='<Y>',
            **plot_kwargs,
        )
        ax.set_xlabel(r"Delay between initialization and measurement (nanoseconds)")
        ax.set_ylabel('Pauli Operator Expectation')
        ax.set_title('T2 Decay Pauli Expectations')
        ax.legend()
        if show_plot:
            fig.show()
        return ax
    def plot_bloch_vector(self, ax: plt.Axes | None = None, **plot_kwargs: Any) -> plt.Axes:
        show_plot = not ax
        if show_plot:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        assert ax is not None
        ax.set_ylim(ymin=0, ymax=1)
        bloch_vector = self._expectation_pauli_x**2 + self._expectation_pauli_y**2
        ax.plot(self._expectation_pauli_x['delay_ns'], bloch_vector['value'], 'r+-', **plot_kwargs)
        ax.set_xlabel(r"Delay between initialization and measurement (nanoseconds)")
        ax.set_ylabel('Bloch Vector X-Y Projection Squared')
        ax.set_title('T2 Decay Experiment Data')
        if show_plot:
            fig.show()
        return ax
    def __str__(self):
        return f'T2DecayResult with data:\n<X>\n{self._x_basis_data}\n<Y>\n{self._y_basis_data}'
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented
        return self._expectation_pauli_x.equals(
            other._expectation_pauli_x
        ) and self._expectation_pauli_y.equals(other._expectation_pauli_y)
    def __repr__(self):
        return (
            f'cirq.experiments.T2DecayResult('
            f'x_basis_data={proper_repr(self._x_basis_data)}, '
            f'y_basis_data={proper_repr(self._y_basis_data)})'
        )
    def _repr_pretty_(self, p: Any, cycle: bool) -> None:
        if cycle:
            p.text('T2DecayResult(...)')
        else:
            p.text(str(self))

from __future__ import annotations
from collections.abc import Callable, Iterable, Mapping, Sequence
from typing import Any, cast, NamedTuple, Self, TYPE_CHECKING
import numpy as np
from cirq import value
from cirq.circuits._block_diagram_drawer import BlockDiagramDrawer
from cirq.circuits._box_drawing_character_data import (
    ASCII_BOX_CHARS,
    BOLD_BOX_CHARS,
    BoxDrawCharacterSet,
    DOUBLED_BOX_CHARS,
    NORMAL_BOX_CHARS,
)
if TYPE_CHECKING:
    import cirq
_HorizontalLine = NamedTuple(
    '_HorizontalLine',
    [('y', float), ('x1', float), ('x2', float), ('emphasize', bool), ('doubled', bool)],
)
_VerticalLine = NamedTuple(
    '_VerticalLine',
    [('x', float), ('y1', float), ('y2', float), ('emphasize', bool), ('doubled', bool)],
)
_DiagramText = NamedTuple('_DiagramText', [('text', str), ('transposed_text', str)])
def pick_charset(use_unicode: bool, emphasize: bool, doubled: bool) -> BoxDrawCharacterSet:
    if not use_unicode:
        return ASCII_BOX_CHARS
    if emphasize and doubled:
        raise ValueError('Cannot use both emphasized and doubled.')
    if emphasize:
        return BOLD_BOX_CHARS
    if doubled:
        return DOUBLED_BOX_CHARS
    return NORMAL_BOX_CHARS
@value.value_equality(unhashable=True)
class TextDiagramDrawer:
    def __init__(
        self,
        entries: Mapping[tuple[int, int], _DiagramText] | None = None,
        horizontal_lines: Iterable[_HorizontalLine] | None = None,
        vertical_lines: Iterable[_VerticalLine] | None = None,
        horizontal_padding: Mapping[int, float] | None = None,
        vertical_padding: Mapping[int, float] | None = None,
    ) -> None:
        self.entries: dict[tuple[int, int], _DiagramText] = (
            dict() if entries is None else dict(entries)
        )
        self.horizontal_lines: list[_HorizontalLine] = (
            [] if horizontal_lines is None else list(horizontal_lines)
        )
        self.vertical_lines: list[_VerticalLine] = (
            [] if vertical_lines is None else list(vertical_lines)
        )
        self.horizontal_padding: dict[int, float] = (
            dict() if horizontal_padding is None else dict(horizontal_padding)
        )
        self.vertical_padding: dict[int, float] = (
            dict() if vertical_padding is None else dict(vertical_padding)
        )
    def _value_equality_values_(self):
        attrs = (
            'entries',
            'horizontal_lines',
            'vertical_lines',
            'horizontal_padding',
            'vertical_padding',
        )
        return tuple(getattr(self, attr) for attr in attrs)
    def __bool__(self):
        return any(self._value_equality_values_())
    def write(self, x: int, y: int, text: str, transposed_text: str | None = None) -> None:
        entry = self.entries.get((x, y), _DiagramText('', ''))
        self.entries[(x, y)] = _DiagramText(
            entry.text + text,
            entry.transposed_text + (transposed_text if transposed_text else text),
        )
    def content_present(self, x: int, y: int) -> bool:
        if (x, y) in self.entries:
            return True
        if any(v.x == x and v.y1 < y < v.y2 for v in self.vertical_lines):
            return True
        if any(line_y == y and x1 < x < x2 for line_y, x1, x2, _, _ in self.horizontal_lines):
            return True  # pragma: no cover
        return False
    def grid_line(
        self, x1: int, y1: int, x2: int, y2: int, emphasize: bool = False, doubled: bool = False
    ) -> None:
        if x1 == x2:
            self.vertical_line(x1, y1, y2, emphasize, doubled)
        elif y1 == y2:
            self.horizontal_line(y1, x1, x2, emphasize, doubled)
        else:
            raise ValueError("Line is neither horizontal nor vertical")
    def vertical_line(
        self, x: float, y1: float, y2: float, emphasize: bool = False, doubled: bool = False
    ) -> None:
        y1, y2 = sorted([y1, y2])
        self.vertical_lines.append(_VerticalLine(x, y1, y2, emphasize, doubled))
    def horizontal_line(
        self, y: float, x1: float, x2: float, emphasize: bool = False, doubled: bool = False
    ) -> None:
        x1, x2 = sorted([x1, x2])
        self.horizontal_lines.append(_HorizontalLine(y, x1, x2, emphasize, doubled))
    def transpose(self) -> cirq.TextDiagramDrawer:
        out = TextDiagramDrawer()
        out.entries = {
            (y, x): _DiagramText(v.transposed_text, v.text) for (x, y), v in self.entries.items()
        }
        out.vertical_lines = [_VerticalLine(*e) for e in self.horizontal_lines]
        out.horizontal_lines = [_HorizontalLine(*e) for e in self.vertical_lines]
        out.vertical_padding = self.horizontal_padding.copy()
        out.horizontal_padding = self.vertical_padding.copy()
        return out
    def width(self) -> int:
        max_x = -1.0
        for x, _ in self.entries.keys():
            max_x = max(max_x, x)
        for v in self.vertical_lines:
            max_x = max(max_x, v.x)
        for h in self.horizontal_lines:
            max_x = max(max_x, h.x1, h.x2)
        return 1 + int(max_x)
    def height(self) -> int:
        max_y = -1.0
        for _, y in self.entries.keys():
            max_y = max(max_y, y)
        for h in self.horizontal_lines:
            max_y = max(max_y, h.y)
        for v in self.vertical_lines:
            max_y = max(max_y, v.y1, v.y2)
        return 1 + int(max_y)
    def force_horizontal_padding_after(self, index: int, padding: float) -> None:
        self.horizontal_padding[index] = padding
    def force_vertical_padding_after(self, index: int, padding: float) -> None:
        self.vertical_padding[index] = padding
    def _transform_coordinates(self, func: Callable[[float, float], tuple[float, float]]) -> None:
        def func_x(x: float) -> float:
            return func(x, 0)[0]
        def func_y(y: float) -> float:
            return func(0, y)[1]
        self.entries = {
            cast(tuple[int, int], func(int(x), int(y))): v for (x, y), v in self.entries.items()
        }
        self.vertical_lines = [
            _VerticalLine(func_x(x), func_y(y1), func_y(y2), emph, doubled)
            for x, y1, y2, emph, doubled in self.vertical_lines
        ]
        self.horizontal_lines = [
            _HorizontalLine(func_y(y), func_x(x1), func_x(x2), emph, doubled)
            for y, x1, x2, emph, doubled in self.horizontal_lines
        ]
        self.horizontal_padding = {
            int(func_x(int(x))): padding for x, padding in self.horizontal_padding.items()
        }
        self.vertical_padding = {
            int(func_y(int(y))): padding for y, padding in self.vertical_padding.items()
        }
    def insert_empty_columns(self, x: int, amount: int = 1) -> None:
        def transform_columns(column: float, row: float) -> tuple[float, float]:
            return column + (amount if column >= x else 0), row
        self._transform_coordinates(transform_columns)
    def insert_empty_rows(self, y: int, amount: int = 1) -> None:
        def transform_rows(column: float, row: float) -> tuple[float, float]:
            return column, row + (amount if row >= y else 0)
        self._transform_coordinates(transform_rows)
    def render(
        self,
        horizontal_spacing: int = 1,
        vertical_spacing: int = 1,
        crossing_char: str | None = None,
        use_unicode_characters: bool = True,
    ) -> str:
        block_diagram = BlockDiagramDrawer()
        w = self.width()
        h = self.height()
        for x in range(w - 1):
            block_diagram.set_col_min_width(
                x * 2 + 1,
                int(np.ceil(self.horizontal_padding.get(x, horizontal_spacing))),
            )
            block_diagram.set_col_min_width(x * 2, 1)
        for y in range(h - 1):
            block_diagram.set_row_min_height(
                y * 2 + 1,
                int(np.floor(self.vertical_padding.get(y, vertical_spacing))),
            )
            block_diagram.set_row_min_height(y * 2, 1)
        for x_b, y1_b, y2_b, emphasize, doubled in self.vertical_lines:
            x = int(x_b * 2)
            y1, y2 = int(min(y1_b, y2_b) * 2), int(max(y1_b, y2_b) * 2)
            charset = pick_charset(use_unicode_characters, emphasize, doubled)
            block_diagram.mutable_block(x, y1).draw_curve(charset, bottom=True)
            block_diagram.mutable_block(x, y2).draw_curve(charset, top=True)
            for y in range(y1 + 1, y2):
                block_diagram.mutable_block(x, y).draw_curve(charset, top=True, bottom=True)
        for y_b, x1_b, x2_b, emphasize, doubled in self.horizontal_lines:
            y = int(y_b * 2)
            x1, x2 = int(min(x1_b, x2_b) * 2), int(max(x1_b, x2_b) * 2)
            charset = pick_charset(use_unicode_characters, emphasize, doubled)
            block_diagram.mutable_block(x1, y).draw_curve(charset, right=True)
            block_diagram.mutable_block(x2, y).draw_curve(charset, left=True)
            for x in range(x1 + 1, x2):
                block_diagram.mutable_block(x, y).draw_curve(
                    charset, left=True, right=True, crossing_char=crossing_char
                )
        for (x, y), v in self.entries.items():
            x *= 2
            y *= 2
            block_diagram.mutable_block(x, y).content = v.text
        return block_diagram.render()
    def copy(self) -> Self:
        return self.__class__(
            entries=self.entries,
            vertical_lines=self.vertical_lines,
            horizontal_lines=self.horizontal_lines,
            vertical_padding=self.vertical_padding,
            horizontal_padding=self.horizontal_padding,
        )
    def shift(self, dx: int = 0, dy: int = 0) -> cirq.TextDiagramDrawer:
        self._transform_coordinates(lambda x, y: (x + dx, y + dy))
        return self
    def shifted(self, dx: int = 0, dy: int = 0) -> cirq.TextDiagramDrawer:
        return self.copy().shift(dx, dy)
    def superimpose(self, other: cirq.TextDiagramDrawer) -> cirq.TextDiagramDrawer:
        self.entries.update(other.entries)
        self.horizontal_lines += other.horizontal_lines
        self.vertical_lines += other.vertical_lines
        self.horizontal_padding.update(other.horizontal_padding)
        self.vertical_padding.update(other.vertical_padding)
        return self
    def superimposed(self, other: cirq.TextDiagramDrawer) -> cirq.TextDiagramDrawer:
        return self.copy().superimpose(other)
    @classmethod
    def vstack(
        cls,
        diagrams: Sequence[cirq.TextDiagramDrawer],
        padding_resolver: Callable[[Sequence[int | None]], int] | None = None,
    ):
        if padding_resolver is None:
            padding_resolver = _same_element_or_throw_error
        stacked = cls()
        dy = 0
        for diagram in diagrams:
            stacked.superimpose(diagram.shifted(dy=dy))
            dy += diagram.height()
        for x in stacked.horizontal_padding:
            resolved_padding = padding_resolver(
                tuple(cast(int | None, diagram.horizontal_padding.get(x)) for diagram in diagrams)
            )
            if resolved_padding is not None:
                stacked.horizontal_padding[x] = resolved_padding
        return stacked
    @classmethod
    def hstack(
        cls,
        diagrams: Sequence[cirq.TextDiagramDrawer],
        padding_resolver: Callable[[Sequence[int | None]], int] | None = None,
    ):
        if padding_resolver is None:
            padding_resolver = _same_element_or_throw_error
        stacked = cls()
        dx = 0
        for diagram in diagrams:
            stacked.superimpose(diagram.shifted(dx=dx))
            dx += diagram.width()
        for y in stacked.vertical_padding:
            resolved_padding = padding_resolver(
                tuple(cast(int | None, diagram.vertical_padding.get(y)) for diagram in diagrams)
            )
            if resolved_padding is not None:
                stacked.vertical_padding[y] = resolved_padding
        return stacked
def _same_element_or_throw_error(elements: Sequence[Any]):
    unique_elements = set(elements)
    if len(unique_elements) > 1:
        raise ValueError(f'len(set({elements})) > 1')
    return unique_elements.pop() if elements else None

from __future__ import annotations
import functools
from collections.abc import Sequence
from typing import TYPE_CHECKING
import numpy as np
import sympy
from cirq import devices, ops, protocols, qis, value
from cirq._compat import proper_repr
from cirq._import import LazyLoader
from cirq.devices.noise_utils import PHYSICAL_GATE_TAG
if TYPE_CHECKING:
    import cirq
linalg = LazyLoader("linalg", globals(), "scipy.linalg")
moment_module = LazyLoader("moment_module", globals(), "cirq.circuits.moment")
def _left_mul(mat: np.ndarray) -> np.ndarray:
    mat = np.asarray(mat)
    if mat.shape[-1] != mat.shape[-2]:
        raise ValueError(
            f'_left_mul only accepts square matrices, but input matrix has shape {mat.shape}.'
        )
    dim = mat.shape[-1]
    return np.kron(mat, np.eye(dim))
def _right_mul(mat: np.ndarray) -> np.ndarray:
    mat = np.asarray(mat)
    if mat.shape[-1] != mat.shape[-2]:
        raise ValueError(
            f'_right_mul only accepts square matrices, but input matrix has shape {mat.shape}.'
        )
    dim = mat.shape[-1]
    return np.kron(np.eye(dim), np.swapaxes(mat, -2, -1))
def _lindbladian(left_op: np.ndarray) -> np.ndarray:
    r
    left_op = np.asarray(left_op)
    right_op = left_op.conj().T
    square = right_op @ left_op
    out = _left_mul(left_op) @ _right_mul(right_op)
    out -= 0.5 * (_left_mul(square) + _right_mul(square))
    return out
@functools.lru_cache(maxsize=256)
def _kraus_ops_from_rates(
    flat_rates: tuple[float, ...], shape: tuple[int, int]
) -> Sequence[np.ndarray]:
    rates = np.array(flat_rates).reshape(shape)
    num_op = np.diag(np.sqrt(np.diag(rates)))
    annihilation = np.sqrt(np.triu(rates, 1))
    creation = np.sqrt(np.triu(rates.T, 1)).T
    L = _lindbladian(annihilation) + _lindbladian(creation) + 2 * _lindbladian(num_op)
    superop = linalg.expm(L.real)
    return qis.superoperator_to_kraus(superop)
def _decoherence_matrix(
    cool_rate: float, dephase_rate: float, heat_rate: float = 0.0, dim: int = 2
) -> np.ndarray:
    rate_matrix = np.diag(np.arange(1, dim) * heat_rate, 1).T.astype(float)
    rate_matrix += np.diag(np.arange(1, dim) * cool_rate, 1)
    rate_matrix += np.diag(dephase_rate * np.arange(dim) ** 2)
    return rate_matrix
def _get_rate_for_qubit(
    rate_or_dict: float | dict[cirq.Qid, float] | None, qubit: cirq.Qid
) -> float:
    if rate_or_dict is None:
        return 0.0
    elif isinstance(rate_or_dict, dict):
        return rate_or_dict.get(qubit, 0.0)
    else:
        return rate_or_dict
def _validate_rates(qubits: set[cirq.Qid], rates: dict[cirq.Qid, np.ndarray]) -> None:
    if qubits != set(rates):
        raise ValueError('qubits for rates inconsistent with those through qubit_dims')
    for q in rates:
        if rates[q].shape != (q.dimension, q.dimension):
            raise ValueError(
                f'Invalid shape for rate matrix: should be ({q.dimension}, {q.dimension}), '
                f'but got {rates[q].shape}'
            )
@value.value_equality
class ThermalNoiseModel(devices.NoiseModel):
    def __init__(
        self,
        qubits: set[cirq.Qid],
        gate_durations_ns: dict[type, float],
        heat_rate_GHz: float | dict[cirq.Qid, float] | None = None,
        cool_rate_GHz: float | dict[cirq.Qid, float] | None = None,
        dephase_rate_GHz: float | dict[cirq.Qid, float] | None = None,
        require_physical_tag: bool = True,
        skip_measurements: bool = True,
        prepend: bool = False,
    ):
        rate_dict = {}
        for q in sorted(qubits):
            gamma_h = _get_rate_for_qubit(heat_rate_GHz, q)
            gamma_c = _get_rate_for_qubit(cool_rate_GHz, q)
            gamma_phi = _get_rate_for_qubit(dephase_rate_GHz, q)
            rate_dict[q] = _decoherence_matrix(gamma_c, gamma_phi, gamma_h, q.dimension)
        _validate_rates(qubits, rate_dict)
        self.gate_durations_ns: dict[type, float] = gate_durations_ns
        self.rate_matrix_GHz: dict[cirq.Qid, np.ndarray] = rate_dict
        self._heat_rate_GHz = heat_rate_GHz
        self._cool_rate_GHz = cool_rate_GHz
        self._dephase_rate_GHz = dephase_rate_GHz
        self.require_physical_tag: bool = require_physical_tag
        self.skip_measurements: bool = skip_measurements
        self._prepend = prepend
    def _value_equality_values_(self):
        gate_durations_ns_tuple = tuple(
            sorted(self.gate_durations_ns.items(), key=lambda x: str(x[0]))
        )
        rate_matrix_GHz_tuple = tuple(
            sorted((q, tuple(m.flat)) for q, m in self.rate_matrix_GHz.items())
        )
        return (
            gate_durations_ns_tuple,
            rate_matrix_GHz_tuple,
            self.require_physical_tag,
            self.skip_measurements,
            self._prepend,
        )
    def __repr__(self) -> str:
        rate_args_repr = []
        if self._heat_rate_GHz is not None:
            rate_args_repr.append(f"heat_rate_GHz={proper_repr(self._heat_rate_GHz)}, ")
        if self._cool_rate_GHz is not None:
            rate_args_repr.append(f"cool_rate_GHz={proper_repr(self._cool_rate_GHz)}, ")
        if self._dephase_rate_GHz is not None:
            rate_args_repr.append(f"dephase_rate_GHz={proper_repr(self._dephase_rate_GHz)}, ")
        return (
            "cirq.devices.ThermalNoiseModel("
            f"qubits={set(self.rate_matrix_GHz.keys())!r}, "
            f"gate_durations_ns={proper_repr(self.gate_durations_ns)}, "
            f"{''.join(rate_args_repr)}"
            f"require_physical_tag={self.require_physical_tag!r}, "
            f"skip_measurements={self.skip_measurements!r}, prepend={self._prepend!r})"
        )
    def noisy_moment(self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        if not moment.operations:
            return [moment]
        if self.require_physical_tag:
            physical_ops = [PHYSICAL_GATE_TAG in op.tags for op in moment]
            if any(physical_ops):
                if not all(physical_ops):
                    raise ValueError(
                        "Moments are expected to be all physical or all virtual ops, "
                        f"but found {moment.operations}"
                    )
            else:
                return [moment]
        noise_ops: list[cirq.Operation] = []
        moment_ns: float = 0
        for op in moment:
            op_duration: float | None = None
            for key, duration in self.gate_durations_ns.items():
                if not issubclass(type(op.gate), key):
                    continue  # gate type doesn't match
                op_duration = duration
                break
            if op_duration is None and isinstance(op.gate, ops.WaitGate):
                nanos = op.gate.duration.total_nanos()
                if isinstance(nanos, sympy.Expr):
                    raise ValueError('Symbolic wait times are not supported')
                op_duration = nanos
            if op_duration is not None:
                moment_ns = max(moment_ns, op_duration)
        if moment_ns == 0:
            return [moment]
        for qubit in system_qubits:
            qubit_op = moment.operation_at(qubit)
            if self.skip_measurements and protocols.is_measurement(qubit_op):
                continue
            rates = self.rate_matrix_GHz[qubit] * moment_ns
            kraus_ops = _kraus_ops_from_rates(tuple(rates.reshape(-1)), rates.shape)
            noise_ops.append(ops.KrausChannel(kraus_ops).on(qubit))
        if not noise_ops:
            return [moment]
        output = [moment, moment_module.Moment(noise_ops)]
        return output[::-1] if self._prepend else output
    def _json_dict_(self) -> dict[str, object]:
        qubits = sorted(self.rate_matrix_GHz.keys())
        return {
            'qubits': qubits,
            'gate_durations_ns': {
                protocols.json_cirq_type(k): v for k, v in self.gate_durations_ns.items()
            },
            'heat_rate_GHz': [_get_rate_for_qubit(self._heat_rate_GHz, q) for q in qubits],
            'cool_rate_GHz': [_get_rate_for_qubit(self._cool_rate_GHz, q) for q in qubits],
            'dephase_rate_GHz': [_get_rate_for_qubit(self._dephase_rate_GHz, q) for q in qubits],
            'require_physical_tag': self.require_physical_tag,
            'skip_measurements': self.skip_measurements,
            'prepend': self._prepend,
        }
    @classmethod
    def _from_json_dict_(
        cls,
        qubits,
        gate_durations_ns,
        heat_rate_GHz,
        cool_rate_GHz,
        dephase_rate_GHz,
        require_physical_tag,
        skip_measurements,
        prepend,
        **kwargs,
    ):
        return cls(
            qubits=set(qubits),
            gate_durations_ns={
                protocols.cirq_type_from_json(k): v for k, v in gate_durations_ns.items()
            },
            heat_rate_GHz=dict(zip(qubits, heat_rate_GHz)),
            cool_rate_GHz=dict(zip(qubits, cool_rate_GHz)),
            dephase_rate_GHz=dict(zip(qubits, dephase_rate_GHz)),
            require_physical_tag=require_physical_tag,
            skip_measurements=skip_measurements,
            prepend=prepend,
        )

import cirq
class MapLargeExpandedCircuit:
    param_names = ["num_qubits", "num_moments"]
    params = ([100, 500, 1000], [100, 1000, 4000])
    timeout = 600  # Change timeout to 2 minutes instead of default 60 seconds.
    def setup(self, num_qubits: int, num_moments: int) -> None:
        qubits = cirq.LineQubit.range(num_qubits)
        one_q_x_moment = cirq.Moment(cirq.X(q) for q in qubits[::2])
        one_q_y_moment = cirq.Moment(cirq.Y(q) for q in qubits[1::2])
        two_q_cx_moment = cirq.Moment(
            cirq.CNOT(q1, q2) for q1, q2 in zip(qubits[::4], qubits[1::4])
        )
        two_q_cz_moment = cirq.Moment(cirq.CZ(q1, q2) for q1, q2 in zip(qubits[::4], qubits[1::4]))
        self.circuit = cirq.Circuit(
            [one_q_x_moment, two_q_cx_moment, one_q_y_moment, two_q_cz_moment] * (num_moments // 4)
        )
    def time_map_moments(self, num_qubits: int, _) -> None:
        all_qubits = cirq.LineQubit.range(num_qubits)
        def map_func(m: cirq.Moment, _) -> cirq.Moment:
            new_ops = [op.with_tags("old op") for op in m.operations]
            new_ops += [
                cirq.Z(q).with_tags("new op")
                for q in all_qubits
                if not m.operates_on_single_qubit(q)
            ]
            return cirq.Moment(new_ops)
        _ = cirq.map_moments(circuit=self.circuit, map_func=map_func)
    def time_map_operations_apply_tag(self, *_) -> None:
        def map_func(op: cirq.Operation, _) -> cirq.Operation:
            return op.with_tags("old op")
        _ = cirq.map_operations(circuit=self.circuit, map_func=map_func)
    def time_map_operations_to_optree(self, *_) -> None:
        def map_func(op: cirq.Operation, _) -> cirq.OP_TREE:
            return [op, op]
        _ = cirq.map_operations(circuit=self.circuit, map_func=map_func)
    def time_map_operations_to_optree_and_unroll(self, *_) -> None:
        def map_func(op: cirq.Operation, _) -> cirq.OP_TREE:
            return [op, op]
        _ = cirq.map_operations_and_unroll(circuit=self.circuit, map_func=map_func)

