def run_rb_and_xeb(
    sampler: cirq.Sampler,
    qubits: Sequence[cirq.GridQubit] | None = None,
    repetitions: int = 10**3,
    num_circuits: int = 20,
    num_clifford_range: Sequence[int] = tuple(
        np.logspace(np.log10(5), np.log10(1000), 5, dtype=int)
    ),
