def _try_defaults_from_unitary(gate: cirq.Gate) -> dict[str, cirq.TParamVal] | None:
    r
    u = protocols.unitary(gate, default=None)
    if u is None:
        return None
    gamma = np.angle(u[1, 1] * u[2, 2] - u[1, 2] * u[2, 1]) / -2
    phi = -np.angle(u[3, 3]) - 2 * gamma
    phased_cos_theta_2 = u[1, 1] * u[2, 2]
    if phased_cos_theta_2 == 0:
        zeta = 0
    else:
        zeta = np.angle(u[2, 2] / u[1, 1]) / 2
    phased_sin_theta_2 = u[1, 2] * u[2, 1]
    if phased_sin_theta_2 == 0:
        chi = 0
    else:
        chi = np.angle(u[1, 2] / u[2, 1]) / 2
    theta = np.angle(np.exp(1j * (gamma + zeta)) * u[1, 1] - np.exp(1j * (gamma - chi)) * u[1, 2])
    if np.allclose(
        u,
        protocols.unitary(
            ops.PhasedFSimGate(theta=theta, phi=phi, chi=chi, zeta=zeta, gamma=gamma)
        ),
    ):
        return {
            'theta_default': theta,
            'phi_default': phi,
            'gamma_default': gamma,
            'zeta_default': zeta,
            'chi_default': chi,
        }
    return None
def phased_fsim_angles_from_gate(gate: cirq.Gate) -> dict[str, cirq.TParamVal]:
    defaults: dict[str, cirq.TParamVal] = {
        'theta_default': 0.0,
        'zeta_default': 0.0,
        'chi_default': 0.0,
        'gamma_default': 0.0,
        'phi_default': 0.0,
    }
    if gate == ops.SQRT_ISWAP:
        defaults['theta_default'] = -np.pi / 4
        return defaults
    if gate == ops.SQRT_ISWAP_INV:
        defaults['theta_default'] = np.pi / 4
        return defaults
    if isinstance(gate, ops.FSimGate):
        defaults['theta_default'] = gate.theta
        defaults['phi_default'] = gate.phi
        return defaults
    if isinstance(gate, ops.PhasedFSimGate):
        return {
            'theta_default': gate.theta,
            'zeta_default': gate.zeta,
            'chi_default': gate.chi,
            'gamma_default': gate.gamma,
            'phi_default': gate.phi,
        }
    from_unitary = _try_defaults_from_unitary(gate)
    if from_unitary is not None:
        return from_unitary
    raise ValueError(f"Unknown default angles for {gate}.")
@dataclasses.dataclass(frozen=True)
class XEBPhasedFSimCharacterizationOptions(XEBCharacterizationOptions):
    characterize_theta: bool = True
    characterize_zeta: bool = True
    characterize_chi: bool = True
    characterize_gamma: bool = True
    characterize_phi: bool = True
    theta_default: float | None = None
    zeta_default: float | None = None
    chi_default: float | None = None
    gamma_default: float | None = None
    phi_default: float | None = None
    def _iter_angles(self) -> Iterable[tuple[bool, float | None, sympy.Symbol]]:
        yield from (
            (self.characterize_theta, self.theta_default, THETA_SYMBOL),
            (self.characterize_zeta, self.zeta_default, ZETA_SYMBOL),
            (self.characterize_chi, self.chi_default, CHI_SYMBOL),
            (self.characterize_gamma, self.gamma_default, GAMMA_SYMBOL),
            (self.characterize_phi, self.phi_default, PHI_SYMBOL),
        )
    def _iter_angles_for_characterization(self) -> Iterable[tuple[float | None, sympy.Symbol]]:
        yield from (
            (default, symbol)
            for characterize, default, symbol in self._iter_angles()
            if characterize
        )
    def get_initial_simplex_and_names(
        self, initial_simplex_step_size: float = 0.1
    ) -> tuple[np.ndarray, list[str]]:
        x0_list = []
        names = []
        for default, symbol in self._iter_angles_for_characterization():
            if default is None:
                raise ValueError(f'{symbol.name}_default was not set.')
            x0_list.append(default)
            names.append(symbol.name)
        x0 = np.asarray(x0_list)
        n_param = len(x0)
        initial_simplex = [x0]
        for i in range(n_param):
            basis_vec = np.eye(1, n_param, i)[0]
            initial_simplex += [x0 + initial_simplex_step_size * basis_vec]
        return np.asarray(initial_simplex), names
    def get_parameterized_gate(self) -> cirq.Gate:
        theta = THETA_SYMBOL if self.characterize_theta else self.theta_default
        zeta = ZETA_SYMBOL if self.characterize_zeta else self.zeta_default
        chi = CHI_SYMBOL if self.characterize_chi else self.chi_default
        gamma = GAMMA_SYMBOL if self.characterize_gamma else self.gamma_default
        phi = PHI_SYMBOL if self.characterize_phi else self.phi_default
        return ops.PhasedFSimGate(theta=theta, zeta=zeta, chi=chi, gamma=gamma, phi=phi)
    @staticmethod
    def should_parameterize(op: cirq.Operation) -> bool:
        return isinstance(op.gate, (ops.PhasedFSimGate, ops.ISwapPowGate, ops.FSimGate))
    def defaults_set(self) -> bool:
        defaults_set = [default is not None for _, default, _ in self._iter_angles()]
        if any(defaults_set):
            if all(defaults_set):
                return True
            problems = [
                symbol.name for _, default, symbol in self._iter_angles() if default is None
            ]
            raise ValueError(f"Some angles are set, but values for {problems} are not.")
        return False
    def with_defaults_from_gate(
        self, gate: cirq.Gate, gate_to_angles_func=phased_fsim_angles_from_gate
    ) -> XEBPhasedFSimCharacterizationOptions:
        return XEBPhasedFSimCharacterizationOptions(
            characterize_theta=self.characterize_theta,
            characterize_zeta=self.characterize_zeta,
            characterize_chi=self.characterize_chi,
            characterize_gamma=self.characterize_gamma,
            characterize_phi=self.characterize_phi,
            **gate_to_angles_func(gate),
        )
    def _json_dict_(self):
        return protocols.dataclass_json_dict(self)
def SqrtISwapXEBOptions(*args, **kwargs) -> XEBPhasedFSimCharacterizationOptions:
    return XEBPhasedFSimCharacterizationOptions(*args, **kwargs).with_defaults_from_gate(
        ops.SQRT_ISWAP
    )
def parameterize_circuit(
    circuit: cirq.Circuit,
    options: XEBCharacterizationOptions,
    target_gatefamily: ops.GateFamily | None = None,
) -> cirq.Circuit:
    if isinstance(target_gatefamily, ops.GateFamily):
        should_parameterize = lambda op: op in target_gatefamily or options.should_parameterize(op)
    else:
        should_parameterize = options.should_parameterize
    gate = options.get_parameterized_gate()
    return circuits.Circuit(
        circuits.Moment(
            gate.on(*op.qubits) if should_parameterize(op) else op for op in moment.operations
        )
        for moment in circuit.moments
    )
QPair_T = tuple['cirq.Qid', 'cirq.Qid']
@dataclasses.dataclass(frozen=True)
class XEBCharacterizationResult:
    optimization_results: dict[QPair_T, scipy.optimize.OptimizeResult]
    final_params: dict[QPair_T, dict[str, float]]
    fidelities_df: pd.DataFrame
def characterize_phased_fsim_parameters_with_xeb(
    sampled_df: pd.DataFrame,
    parameterized_circuits: list[cirq.Circuit],
    cycle_depths: Sequence[int],
    options: XEBCharacterizationOptions,
    initial_simplex_step_size: float = 0.1,
    xatol: float = 1e-3,
    fatol: float = 1e-3,
    verbose: bool = True,
    pool: multiprocessing.pool.Pool | None = None,
) -> XEBCharacterizationResult:
    (pair,) = sampled_df['pair'].unique()
    initial_simplex, names = options.get_initial_simplex_and_names(
        initial_simplex_step_size=initial_simplex_step_size
    )
    x0 = initial_simplex[0]
    def _mean_infidelity(angles):
        params = dict(zip(names, angles))
        if verbose:
            params_str = ''
            for name, val in params.items():
                params_str += f'{name:5s} = {val:7.3g} '
            print(f"Simulating with {params_str}")
        fids = benchmark_2q_xeb_fidelities(
            sampled_df, parameterized_circuits, cycle_depths, param_resolver=params, pool=pool
        )
        loss = 1 - fids['fidelity'].mean()
        if verbose:
            print(f"Loss: {loss:7.3g}", flush=True)
        return loss
    optimization_result = optimize.minimize(
        _mean_infidelity,
        x0=x0,
        options={'initial_simplex': initial_simplex, 'xatol': xatol, 'fatol': fatol},
        method='nelder-mead',
    )
    final_params: cirq.ParamDictType = dict(zip(names, optimization_result.x))
    fidelities_df = benchmark_2q_xeb_fidelities(
        sampled_df, parameterized_circuits, cycle_depths, param_resolver=final_params
    )
    return XEBCharacterizationResult(
        optimization_results={pair: optimization_result},
        final_params={pair: final_params},
        fidelities_df=fidelities_df,
    )
@dataclasses.dataclass(frozen=True)
class _CharacterizePhasedFsimParametersWithXebClosure:
    parameterized_circuits: list[cirq.Circuit]
    cycle_depths: Sequence[int]
    options: XEBCharacterizationOptions
    initial_simplex_step_size: float = 0.1
    xatol: float = 1e-3
    fatol: float = 1e-3
    def __call__(self, sampled_df) -> XEBCharacterizationResult:
        return characterize_phased_fsim_parameters_with_xeb(
            sampled_df=sampled_df,
            parameterized_circuits=self.parameterized_circuits,
            cycle_depths=self.cycle_depths,
            options=self.options,
            initial_simplex_step_size=self.initial_simplex_step_size,
            xatol=self.xatol,
            fatol=self.fatol,
            verbose=False,
            pool=None,
        )
def characterize_phased_fsim_parameters_with_xeb_by_pair(
    sampled_df: pd.DataFrame,
    parameterized_circuits: list[cirq.Circuit],
    cycle_depths: Sequence[int],
    options: XEBCharacterizationOptions,
    initial_simplex_step_size: float = 0.1,
    xatol: float = 1e-3,
    fatol: float = 1e-3,
    pool: multiprocessing.pool.Pool | None = None,
) -> XEBCharacterizationResult:
    pairs = sampled_df['pair'].unique()
    closure = _CharacterizePhasedFsimParametersWithXebClosure(
        parameterized_circuits=parameterized_circuits,
        cycle_depths=cycle_depths,
        options=options,
        initial_simplex_step_size=initial_simplex_step_size,
        xatol=xatol,
        fatol=fatol,
    )
    subselected_dfs = [sampled_df[sampled_df['pair'] == pair] for pair in pairs]
    if pool is not None:
        results = pool.map(closure, subselected_dfs)
    else:
        results = [closure(df) for df in subselected_dfs]
    optimization_results = {}
    all_final_params = {}
    fid_dfs = []
    for result in results:
        optimization_results.update(result.optimization_results)
        all_final_params.update(result.final_params)
        fid_dfs.append(result.fidelities_df)
    return XEBCharacterizationResult(
        optimization_results=optimization_results,
        final_params=all_final_params,
        fidelities_df=pd.concat(fid_dfs),
    )
def exponential_decay(cycle_depths: np.ndarray, a: float, layer_fid: float) -> np.ndarray:
    return a * layer_fid**cycle_depths
def _fit_exponential_decay(
    cycle_depths: np.ndarray, fidelities: np.ndarray
) -> tuple[float, float, float, float]:
    cycle_depths = np.asarray(cycle_depths)
    fidelities = np.asarray(fidelities)
    positives = fidelities > 0
    if np.sum(positives) <= 1:
        return 0, 0, np.inf, np.inf
    cycle_depths_pos = cycle_depths[positives]
    log_fidelities = np.log(fidelities[positives])
    slope, intercept, _, _, _ = stats.linregress(cycle_depths_pos, log_fidelities)
    layer_fid_0 = np.clip(np.exp(slope), 0, 1)
    a_0 = np.clip(np.exp(intercept), 0, 1)
    try:
        (a, layer_fid), pcov = optimize.curve_fit(
            exponential_decay,
            cycle_depths,
            fidelities,
            p0=(a_0, layer_fid_0),
            bounds=((0, 0), (1, 1)),
            maxfev=1000,
        )
    except ValueError:  # pragma: no cover
        return 0, 0, np.inf, np.inf
    a_std, layer_fid_std = np.sqrt(np.diag(pcov))
    return a, layer_fid, a_std, layer_fid_std
def fit_exponential_decays(fidelities_df: pd.DataFrame) -> pd.DataFrame:
    def _per_pair(f1):
        a, layer_fid, a_std, layer_fid_std = _fit_exponential_decay(
            f1['cycle_depth'], f1['fidelity']
        )
        fidelity_variance = 0
        if 'fidelity_variance' in f1:
            fidelity_variance = f1['fidelity_variance'].values
        record = {
            'a': a,
            'layer_fid': layer_fid,
            'cycle_depths': f1['cycle_depth'].values,
            'fidelities': f1['fidelity'].values,
            'a_std': a_std,
            'layer_fid_std': np.sqrt(layer_fid_std**2 + fidelity_variance),
        }
        return pd.Series(record)
    if 'layer_i' in fidelities_df.columns:
        groupby = ['layer_i', 'pair_i', 'pair']
    else:
        groupby = ['pair']
    return fidelities_df.groupby(groupby).apply(_per_pair, include_groups=False)
def before_and_after_characterization(
    fidelities_df_0: pd.DataFrame, characterization_result: XEBCharacterizationResult
) -> pd.DataFrame:
    fit_decay_df_0 = fit_exponential_decays(fidelities_df_0)
    fit_decay_df_c = fit_exponential_decays(characterization_result.fidelities_df)
    joined_df = fit_decay_df_0.join(fit_decay_df_c, how='outer', lsuffix='_0', rsuffix='_c')
    joined_df = joined_df.reset_index().set_index('pair')
    joined_df['characterized_angles'] = [
        characterization_result.final_params[pair] for pair in joined_df.index
    ]
    fp, *_ = characterization_result.final_params.values()
    for angle_name in fp.keys():
        joined_df[angle_name] = [
            characterization_result.final_params[pair][angle_name] for pair in joined_df.index
        ]
    return joined_df

from __future__ import annotations
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Any, TYPE_CHECKING
import numpy as np
import pandas as pd
from cirq import sim, value
if TYPE_CHECKING:
    import multiprocessing
    import cirq
@dataclass(frozen=True)
class _Simulate2qXEBTask:
    circuit_i: int
    cycle_depths: Sequence[int]
    circuit: cirq.Circuit
    param_resolver: cirq.ParamResolverOrSimilarType
class _Simulate_2q_XEB_Circuit:
    def __init__(self, simulator: cirq.SimulatesIntermediateState):
        self.simulator = simulator
    def __call__(self, task: _Simulate2qXEBTask) -> list[dict[str, Any]]:
        circuit_i = task.circuit_i
        cycle_depths = set(task.cycle_depths)
        circuit = task.circuit
        param_resolver = task.param_resolver
        circuit_max_cycle_depth = (len(circuit) - 1) // 2
        if max(cycle_depths) > circuit_max_cycle_depth:
            raise ValueError("`circuit` was not long enough to compute all `cycle_depths`.")
        records: list[dict[str, Any]] = []
        for moment_i, step_result in enumerate(
            self.simulator.simulate_moment_steps(circuit=circuit, param_resolver=param_resolver)
        ):
            if moment_i % 2 == 1:
                continue
            cycle_depth = moment_i // 2
            if cycle_depth not in cycle_depths:
                continue
            psi = step_result.state_vector()
            pure_probs = value.state_vector_to_probabilities(psi)
            records += [
                {'circuit_i': circuit_i, 'cycle_depth': cycle_depth, 'pure_probs': pure_probs}
            ]
        return records
def simulate_2q_xeb_circuits(
    circuits: Sequence[cirq.Circuit],
    cycle_depths: Sequence[int],
    param_resolver: cirq.ParamResolverOrSimilarType = None,
    pool: multiprocessing.pool.Pool | None = None,
    simulator: cirq.SimulatesIntermediateState | None = None,
) -> pd.DataFrame:
    if simulator is None:
        simulator = sim.Simulator(seed=np.random.RandomState(), dtype=np.complex128)
    _simulate_2q_xeb_circuit = _Simulate_2q_XEB_Circuit(simulator=simulator)
    tasks = tuple(
        _Simulate2qXEBTask(
            circuit_i=circuit_i,
            cycle_depths=cycle_depths,
            circuit=circuit,
            param_resolver=param_resolver,
        )
        for circuit_i, circuit in enumerate(circuits)
    )
    if pool is not None:
        nested_records = pool.map(_simulate_2q_xeb_circuit, tasks)
    else:
        nested_records = [_simulate_2q_xeb_circuit(task) for task in tasks]
    records = [record for sublist in nested_records for record in sublist]
    return pd.DataFrame(records).set_index(['circuit_i', 'cycle_depth'])

from __future__ import annotations
import collections
from cirq.circuits._box_drawing_character_data import box_draw_character, BoxDrawCharacterSet
class Block:
    def __init__(self):
        self.left = ''
        self.right = ''
        self.top = ''
        self.bottom = ''
        self.center = ''
        self.content = ''
        self.horizontal_alignment = 0
        self._prev_curve_grid_chars = None
    def min_width(self) -> int:
        return max(
            max(len(e) for e in self.content.split('\n')),
            int(any([self.top, self.bottom])),
        )
    def min_height(self) -> int:
        return max(
            len(self.content.split('\n')) if self.content else 0,
            int(any([self.left, self.right])),
        )
    def draw_curve(
        self,
        grid_characters: BoxDrawCharacterSet,
        *,
        top: bool = False,
        left: bool = False,
        right: bool = False,
        bottom: bool = False,
        crossing_char: str | None = None,
    ):
        if not any([top, left, right, bottom]):
            return
        sign_top = +1 if top else -1 if self.top else 0
        sign_bottom = +1 if bottom else -1 if self.bottom else 0
        sign_left = +1 if left else -1 if self.left else 0
        sign_right = +1 if right else -1 if self.right else 0
        if top:
            self.top = grid_characters.top_bottom
        if bottom:
            self.bottom = grid_characters.top_bottom
        if left:
            self.left = grid_characters.left_right
        if right:
            self.right = grid_characters.left_right
        if not all([crossing_char, self.top, self.bottom, self.left, self.right]):
            crossing_char = box_draw_character(
                self._prev_curve_grid_chars,
                grid_characters,
                top=sign_top,
                bottom=sign_bottom,
                left=sign_left,
                right=sign_right,
            )
        self.center = crossing_char or ''
        self._prev_curve_grid_chars = grid_characters
    def render(self, width: int, height: int) -> list[str]:
        if width == 0 or height == 0:
            return [''] * height
        out_chars = [[' '] * width for _ in range(height)]
        mid_x = int((width - 1) * self.horizontal_alignment)
        mid_y = (height - 1) // 2
        if self.left:
            out_chars[mid_y][: mid_x + 1] = self.left * (mid_x + 1)
        if self.right:
            out_chars[mid_y][mid_x:] = self.right * (width - mid_x)
        if self.top:
            for y in range(mid_y + 1):
                out_chars[y][mid_x] = self.top
        if self.bottom:
            for y in range(mid_y, height):
                out_chars[y][mid_x] = self.bottom
        mid = self.content or self.center
        if self.content or self.center:
            content_lines = mid.split('\n')
            y = mid_y - (len(content_lines) - 1) // 2
            for dy, content_line in enumerate(content_lines):
                s = int((len(content_line) - 1) * self.horizontal_alignment)
                x = mid_x - s
                for dx, c in enumerate(content_line):
                    out_chars[y + dy][x + dx] = c
        return [''.join(line) for line in out_chars]
class BlockDiagramDrawer:
    def __init__(self) -> None:
        self._blocks: dict[tuple[int, int], Block] = collections.defaultdict(Block)
        self._min_widths: dict[int, int] = collections.defaultdict(lambda: 0)
        self._min_heights: dict[int, int] = collections.defaultdict(lambda: 0)
        _ = self._blocks[(0, 0)]
        _ = self._min_widths[0]
        _ = self._min_heights[0]
    def mutable_block(self, x: int, y: int) -> Block:
        if x < 0 or y < 0:
            raise IndexError('x < 0 or y < 0')
        return self._blocks[(x, y)]
    def set_col_min_width(self, x: int, min_width: int):
        if x < 0:
            raise IndexError('x < 0')
        self._min_widths[x] = min_width
    def set_row_min_height(self, y: int, min_height: int):
        if y < 0:
            raise IndexError('y < 0')
        self._min_heights[y] = min_height
    def render(
        self,
        *,
        block_span_x: int | None = None,
        block_span_y: int | None = None,
        min_block_width: int = 0,
        min_block_height: int = 0,
    ) -> str:
        if block_span_x is None:
            block_span_x = 1 + max(
                max(x for x, _ in self._blocks.keys()), max(self._min_widths.keys())
            )
        if block_span_y is None:
            block_span_y = 1 + max(
                max(y for _, y in self._blocks.keys()), max(self._min_heights.keys())
            )
        empty = Block()
        def block(x: int, y: int) -> Block:
            return self._blocks.get((x, y), empty)
        widths = {
            x: max(
                max(block(x, y).min_width() for y in range(block_span_y)),
                self._min_widths.get(x, 0),
                min_block_width,
            )
            for x in range(block_span_x)
        }
        heights = {
            y: max(
                max(block(x, y).min_height() for x in range(block_span_x)),
                self._min_heights.get(y, 0),
                min_block_height,
            )
            for y in range(block_span_y)
        }
        block_renders = {
            (x, y): block(x, y).render(widths[x], heights[y])
            for x in range(block_span_x)
            for y in range(block_span_y)
        }
        out_lines: list[str] = []
        for y in range(block_span_y):
            for by in range(heights[y]):
                out_line_chunks: list[str] = []
                for x in range(block_span_x):
                    out_line_chunks.extend(block_renders[x, y][by])
                out_lines.append(''.join(out_line_chunks).rstrip())
        return '\n'.join(out_lines)

