            'Pow',
            'Add',
            'Mod',
            'Integer',
            'Float',
            'Rational',
            'GreaterThan',
            'StrictGreaterThan',
            'LessThan',
            'StrictLessThan',
            'Equality',
            'Unequality',
            'And',
            'Or',
            'Not',
            'Xor',
            'Indexed',
            'IndexedBase',
