def _dec_to_binary_right(d: Union[np.ndarray, int], n: int) -> Union[np.ndarray, int]:
    i = np.arange(n // 2)
    return (
        np.floor(np.outer(d, 1 / 2**i)) - np.floor(np.outer(d, 1 / 2 ** (i + 1))) * 2
    ).astype("int")
class KPZExperimentResultsFromAmplitudes:
    def __init__(self, prob_right: np.ndarray, initial_states: np.ndarray):
        num_trials, n = initial_states.shape
        num_right = np.sum(initial_states[:, n // 2 :], 1)
        self.num_initial_states = num_trials
        self.num_right_initial = num_right
        self.transferred_magnetization_vals = np.arange(-n // 2, n // 2 + 1) * 2
        transferred_magnetization_probs = np.zeros((num_trials, n + 1))
        for trial in range(num_trials):
            transferred_magnetization_probs[
                trial, (n // 2 - num_right[trial]) : (n - num_right[trial] + 1)
            ] = prob_right[trial, :]
        self.transferred_magnetization_probs_all = transferred_magnetization_probs
        self.transferred_magnetization_probs = np.mean(
            transferred_magnetization_probs, 0
        )
        self.mean = self._mean()
        self.variance = self._variance()
        self.skewness = self._skewness()
        self.kurtosis = self._kurtosis()
    def _mean(self) -> float:
        return (
            self.transferred_magnetization_probs @ self.transferred_magnetization_vals
        )
    def _variance(self) -> float:
        return (
            self.transferred_magnetization_probs
            @ (self.transferred_magnetization_vals - self.mean) ** 2
        )
    def _skewness(self) -> float:
        return (
            self.transferred_magnetization_probs
            @ (self.transferred_magnetization_vals - self.mean) ** 3
            / self.variance ** (3 / 2)
        )
    def _kurtosis(self) -> float:
        return (
            self.transferred_magnetization_probs
            @ (self.transferred_magnetization_vals - self.mean) ** 4
            / self.variance**2
            - 3
        )
    def _mean_excluding_i(self, i: int) -> float:
        p = np.mean(
            np.delete(self.transferred_magnetization_probs_all, i, axis=0), axis=0
        )
        return p @ self.transferred_magnetization_vals
    def _variance_excluding_i(self, i: int) -> float:
        p = np.mean(
            np.delete(self.transferred_magnetization_probs_all, i, axis=0), axis=0
        )
        mean_i = p @ self.transferred_magnetization_vals
        return p @ (self.transferred_magnetization_vals - mean_i) ** 2
    def _skew_excluding_i(self, i: int) -> float:
        p = np.mean(
            np.delete(self.transferred_magnetization_probs_all, i, axis=0), axis=0
        )
        mean_i = p @ self.transferred_magnetization_vals
        variance_i = p @ (self.transferred_magnetization_vals - mean_i) ** 2
        return (
            p
            @ (self.transferred_magnetization_vals - mean_i) ** 3
            / variance_i ** (3 / 2)
        )
    def _kurtosis_excluding_i(self, i: int) -> float:
        p = np.mean(
            np.delete(self.transferred_magnetization_probs_all, i, axis=0), axis=0
        )
        mean_i = p @ self.transferred_magnetization_vals
        variance_i = p @ (self.transferred_magnetization_vals - mean_i) ** 2
        return (
            p @ (self.transferred_magnetization_vals - mean_i) ** 4 / variance_i**2
            - 3
        )
    def jackknife_mean(self) -> float:
        r
        if self.num_initial_states == 1:
            return 0
        mean_i = [self._mean_excluding_i(i) for i in range(self.num_initial_states)]
        return np.std(mean_i) * np.sqrt(self.num_initial_states - 1)
    def jackknife_variance(self) -> float:
        r
        if self.num_initial_states == 1:
            return 0
        variance_i = [
            self._variance_excluding_i(i) for i in range(self.num_initial_states)
        ]
        return np.std(variance_i) * np.sqrt(self.num_initial_states - 1)
    def jackknife_skew(self) -> float:
        r
        if self.num_initial_states == 1:
            return 0
        skew_i = [self._skew_excluding_i(i) for i in range(self.num_initial_states)]
        return np.std(skew_i) * np.sqrt(self.num_initial_states - 1)
    def jackknife_kurtosis(self) -> float:
        r
        if self.num_initial_states == 1:
            return 0
        kurtosis_i = [
            self._kurtosis_excluding_i(i) for i in range(self.num_initial_states)
        ]
        return np.std(kurtosis_i) * np.sqrt(self.num_initial_states - 1)
    def plot_histogram(self, ax: Optional[Union[None, plt.Axes]] = None) -> plt.Axes:
        if not ax:
            fig, ax = plt.subplots(facecolor="white", dpi=200)
        bins = (
            np.append(
                self.transferred_magnetization_vals // 2,
                self.transferred_magnetization_vals[-1] // 2 + 1,
            )
            - 0.5
        )
        ax.hist(
            self.transferred_magnetization_vals // 2,
            weights=self.transferred_magnetization_probs,
            bins=bins,
            edgecolor="k",
        )
        ax.tick_params(direction="in", top=True, right=True)
        ax.set_xlabel(r"Number of 1s that crossed center, $\mathcal{M}/2$")
        ax.set_ylabel("Probability")
        return ax
class KPZExperimentResults:
    def __init__(
        self,
        raw_results: List[List[cirq.study.result.ResultDict]],
        initial_states: np.ndarray,
    ):
        num_trials, n = initial_states.shape
        num_right = np.sum(initial_states[:, n // 2 :], 1)
        self.num_initial_states = num_trials
        self.num_right_initial = num_right
        self.bitstrs = np.array([res.measurements["m"] for res in raw_results])
        self.num_right_final = np.sum(self.bitstrs[:, :, n // 2 :], 2)
        self.transferred_magnetization = self._transferred_magnetization()
        self.mean = self._mean()
        self.variance = self._variance()
        self.skewness = self._skewness()
        self.kurtosis = self._kurtosis()
    def _transferred_magnetization(self) -> np.ndarray:
        final = self.num_right_final
        num_trials, num_reps = final.shape
        initial = np.outer(self.num_right_initial, np.ones(num_reps, dtype=int))
        return 2 * (final - initial)
    def _mean(self) -> float:
        return np.mean(self.transferred_magnetization.flatten())
    def _variance(self) -> float:
        return np.var(self.transferred_magnetization.flatten())
    def _skewness(self) -> float:
        return sstats.skew(self.transferred_magnetization.flatten())
    def _kurtosis(self) -> float:
        return sstats.kurtosis(self.transferred_magnetization.flatten(), fisher=True)
    def _mean_excluding_i(self, i: int, axis: Optional[int] = 0) -> float:
        tm = np.delete(self.transferred_magnetization, i, axis=axis)
        return np.mean(tm.flatten())
    def _variance_excluding_i(self, i: int, axis: Optional[int] = 0) -> float:
        tm = np.delete(self.transferred_magnetization, i, axis=axis)
        return np.var(tm.flatten())
    def _skew_excluding_i(self, i: int, axis: Optional[int] = 0) -> float:
        tm = np.delete(self.transferred_magnetization, i, axis=axis)
        return sstats.skew(tm.flatten())
    def _kurtosis_excluding_i(self, i: int, axis: Optional[int] = 0) -> float:
        tm = np.delete(self.transferred_magnetization, i, axis=axis)
        return sstats.kurtosis(tm.flatten(), fisher=True)
    def jackknife_mean(self) -> float:
        if self.num_initial_states == 1:
            tm = self.transferred_magnetization.flatten()
            return np.std(tm) / np.sqrt(len(tm))
        mean_i = [self._mean_excluding_i(i) for i in range(self.num_initial_states)]
        return np.std(mean_i) * np.sqrt(self.num_initial_states - 1)
    def jackknife_variance(self) -> float:
        if self.num_initial_states == 1:
            axis = 1
            tot = self.transferred_magnetization.size
        else:
            axis = 0
            tot = self.num_initial_states
        variance_i = [self._variance_excluding_i(i, axis=axis) for i in range(tot)]
        return np.std(variance_i) * np.sqrt(tot - 1)
    def jackknife_skew(self) -> float:
        if self.num_initial_states == 1:
            axis = 1
            tot = self.transferred_magnetization.size
        else:
            axis = 0
            tot = self.num_initial_states
        skew_i = [self._skew_excluding_i(i, axis=axis) for i in range(tot)]
        return np.std(skew_i) * np.sqrt(tot - 1)
    def jackknife_kurtosis(self) -> float:
        if self.num_initial_states == 1:
            axis = 1
            tot = self.transferred_magnetization.size
        else:
            axis = 0
            tot = self.num_initial_states
        kurtosis_i = [self._kurtosis_excluding_i(i, axis=axis) for i in range(tot)]
        return np.std(kurtosis_i) * np.sqrt(tot - 1)
    def plot_histogram(self, ax: Optional[Union[None, plt.Axes]] = None) -> plt.Axes:
        if not ax:
            fig, ax = plt.subplots(facecolor="white", dpi=200)
        num_crossed = self.transferred_magnetization // 2
        lower = min(num_crossed.flatten())
        upper = max(num_crossed.flatten())
        ax.hist(
            num_crossed.flatten(),
            bins=np.arange(lower - 0.5, upper + 1.5),
            density=True,
            edgecolor="k",
        )
        ax.tick_params(direction="in", top=True, right=True)
        ax.set_xlabel(r"Number of 1s that crossed center, $\mathcal{M}/2$")
        ax.set_ylabel("Probability")
        return ax
class KPZExperiment:
    r
    def __init__(
        self,
        num_cycles: int,
        mu: float,
        num_init_states: int,
        theta: float,
        phi: float,
        num_qubits: Optional[Union[None, int]] = None,
    ):
        if mu == np.inf and num_init_states > 1:
            warnings.warn(
                "When mu=inf, there is only 1 initial state. Setting num_init_states = 1"
            )
            num_init_states = 1
        self.num_cycles = num_cycles
        self.mu = mu
        self.num_init_states = num_init_states
        self.num_qubits = 2 * num_cycles if num_qubits == None else num_qubits
        if self.num_qubits == 0:
            self.num_qubits = 2
        self.initial_states = self._generate_initial_states()
        self.theta = theta
        self.phi = phi
        self.circuits = self._generate_all_circuits()
    def _generate_initial_states(self) -> np.ndarray:
        mu = self.mu
        n = self.num_qubits
        nTrials = self.num_init_states
        if mu == np.inf:
            bitstrs = np.array(
                [np.append(np.ones(n // 2, dtype=int), np.zeros(n // 2, dtype=int))]
            )
        elif mu < np.inf:
            p = np.exp(mu) / (np.exp(mu) + np.exp(-mu))
            bitstrs_L = rng.choice(2, p=[1 - p, p], size=(nTrials, n // 2))
            bitstrs_R = rng.choice(2, p=[p, 1 - p], size=(nTrials, n // 2))
            bitstrs = np.append(bitstrs_L, bitstrs_R, axis=1)
        return bitstrs
    def _generate_cycle(self) -> cirq.Circuit:
        n = self.num_qubits
        theta = self.theta
        phi = self.phi
        qubits = cirq.LineQubit.range(n)
        qc = cirq.Circuit(
            cirq.FSimGate(theta, phi)(*qubits[q : q + 2]) for q in range(0, n - 1, 2)
        )
        qc += cirq.Circuit(
            cirq.FSimGate(theta, phi)(*qubits[q : q + 2]) for q in range(1, n - 1, 2)
        )
        return qc
    def _generate_circuit(self, locs: Iterator[int]) -> cirq.Circuit:
        n = self.num_qubits
        num_cycles = self.num_cycles
        qubits = cirq.LineQubit.range(n)
        qc = cirq.Circuit(cirq.X(qubits[q]) for q in locs)
        if num_cycles > 0:
            cycle = self._generate_cycle()
            qc += cycle * num_cycles
        qc.append(cirq.measure(*qubits, key="m"))
        return qc
    def _generate_all_circuits(self) -> List[cirq.Circuit]:
        locs_all = [np.nonzero(bitstr)[0] for bitstr in self.initial_states]
        return [self._generate_circuit(locs) for locs in locs_all]
    def run_experiment(self, sampler: cirq.Sampler, reps: int) -> KPZExperimentResults:
        result = [
            sampler.run(circuit, repetitions=reps)
            for circuit in tqdm(self.circuits, total=self.num_init_states)
        ]
        return KPZExperimentResults(result, self.initial_states)
    def run_experiment_amplitudes(
        self, sampler: cirq.SimulatesAmplitudes
    ) -> KPZExperimentResultsFromAmplitudes:
        all_states = np.arange(2**self.num_qubits)
        binary_states = _dec_to_binary_right(all_states, self.num_qubits)
        num_right = np.sum(binary_states, 1)
        del binary_states  # this is exponentially large; delete to save memory
        prob_right = np.zeros((self.num_init_states, self.num_qubits // 2 + 1))
        for idx, (qc, initial_bitstr) in tqdm(
            enumerate(zip(self.circuits, self.initial_states)),
            total=self.num_init_states,
        ):
            num_right_initial = np.sum(initial_bitstr)
            probs = (
                np.abs(
                    sampler.simulate(
                        cirq.drop_terminal_measurements(qc)
                    ).final_state_vector
                )
                ** 2
            )
            for num_right_val in np.arange(
                min(self.num_qubits // 2 + 1, num_right_initial + 1)
            ):
                prob_right[idx, num_right_val] = probs @ (num_right == num_right_val)
        return KPZExperimentResultsFromAmplitudes(prob_right, self.initial_states)

from collections.abc import Sequence
from typing import Any
import cirq
from matplotlib import colormaps
import matplotlib.patches as mpatches
import matplotlib.pyplot as plt
import numpy as np
import sympy
from recirq.lattice_gauge.lattice_gauge_grid import QubitNeighbor, LGTGrid
def variational_ground_state_minimal_qubits_cols(
    grid: LGTGrid, x_ancillary_qubits_in_cols: list[set[cirq.GridQubit]], theta: float
) -> list[cirq.Moment]:
    x_ancillary_qubits_all = x_ancillary_qubits_in_cols[0].union(x_ancillary_qubits_in_cols[1])
    return [
        cirq.Moment(cirq.Ry(rads=theta).on_each(grid.u_set(x_ancillary_qubits_all))),
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(x_ancillary_qubits_all, QubitNeighbor.U, QubitNeighbor.L)),
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(x_ancillary_qubits_all, QubitNeighbor.U, QubitNeighbor.R)),
        *cirq.Circuit.zip(
            cirq.Circuit.from_moments(
                *cnot_on_layer(
                    pairs_list=grid.ancillary_to_pair(x_ancillary_qubits_in_cols[0], QubitNeighbor.L, QubitNeighbor.D)
                )
            ),
            cirq.Circuit.from_moments(
                *cnot_on_layer(
                    pairs_list=grid.ancillary_to_pair(x_ancillary_qubits_in_cols[1], QubitNeighbor.R, QubitNeighbor.D)
                )
            ),
        ).moments,
    ]
def variational_ground_state_minimal_qubits(
    grid: LGTGrid, theta: float, extra_x_plaquette_indices: list[tuple[int, int]] = []
) -> list[cirq.Moment]:
    extra_ancilla_qubits = {}
    for col in range(grid.cols):
        extra_ancilla_qubits[col] = []
        for p in extra_x_plaquette_indices:
            if p[1] == col:
                extra_ancilla_qubits[col].append(grid.x_plaquette_to_x_ancilla(p[0], p[1]))
    moments = []
    if (grid.cols / 2).is_integer():
        for col in range(int(grid.cols / 2), grid.cols):
            moments = moments + variational_ground_state_minimal_qubits_cols(
                grid,
                [
                    grid.x_ancillary_qubits_by_col[grid.cols - col - 1].union(
                        extra_ancilla_qubits[grid.cols - col - 1]
                    ),
                    grid.x_ancillary_qubits_by_col[col].union(extra_ancilla_qubits[col]),
                ],
                theta=theta,
            )
    else:
        moments = moments + variational_ground_state_minimal_qubits_cols(
            grid,
            [
                grid.x_ancillary_qubits_by_col[int(grid.cols / 2 - 0.5)].union(
                    extra_ancilla_qubits[int(grid.cols / 2 - 0.5)]
                ),
                {},
            ],
            theta=theta,
        )
        for col in range(1, int(grid.cols / 2 + 0.5)):
            moments = moments + variational_ground_state_minimal_qubits_cols(
                grid,
                [
                    grid.x_ancillary_qubits_by_col[int(grid.cols / 2 - 0.5 - col)].union(
                        extra_ancilla_qubits[int(grid.cols / 2 - 0.5 - col)]
                    ),
                    grid.x_ancillary_qubits_by_col[int(grid.cols / 2 - 0.5 + col)].union(
                        extra_ancilla_qubits[int(grid.cols / 2 - 0.5 + col)]
                    ),
                ],
                theta=theta,
            )
    return moments
def trotter_even_zcol_entangle_minimal_qubits(
    grid: LGTGrid, extra_z_plaquette_indices: list[tuple[int, int]] = []
) -> list[cirq.Moment]:
    extra_even_qubits = []
    for p in extra_z_plaquette_indices:
        if p[1] % 2 == 0:
            extra_even_qubits.append(grid.z_plaquette_to_z_ancilla(p[0], p[1]))
    extra_z_plaquette_ancillary_qubit = set(extra_even_qubits)
    return [
        *cnot_on_layer(
            pairs_list=grid.ancillary_to_pair(
                grid.z_ancillary_l_side_qubits
                - grid.z_ancillary_dl_corner_qubits
                - extra_z_plaquette_ancillary_qubit,
                QubitNeighbor.D,
                QubitNeighbor.R,
            ).union(
                grid.ancillary_to_pair(
                    (
                        grid.z_even_col_ancillary_qubits
                        - grid.z_ancillary_l_side_qubits
                        - grid.z_ancillary_d_side_qubits
                    ).union(extra_z_plaquette_ancillary_qubit),
                    QubitNeighbor.D,
                    QubitNeighbor.L,
                )
            )
        ),
        *cnot_on_layer(
            pairs_list=grid.ancillary_to_pair(
                grid.z_ancillary_l_side_qubits
                - grid.z_ancillary_ul_corner_qubits
                - grid.z_ancillary_dl_corner_qubits
                - extra_z_plaquette_ancillary_qubit,
                QubitNeighbor.R,
                QubitNeighbor.U,
            )
            .union(
                grid.ancillary_to_pair(
                    grid.z_ancillary_dl_corner_qubits - extra_z_plaquette_ancillary_qubit, QubitNeighbor.R, QubitNeighbor.U
                )
            )
            .union(
                grid.ancillary_to_pair(
                    (
                        grid.z_even_col_ancillary_qubits
                        - grid.z_ancillary_l_side_qubits
                        - grid.z_ancillary_u_side_qubits
                    ).union(extra_z_plaquette_ancillary_qubit),
                    QubitNeighbor.L,
                    QubitNeighbor.U,
                )
            )
            .union(
                grid.ancillary_to_pair(
                    grid.z_ancillary_u_side_qubits.intersection(grid.z_even_col_ancillary_qubits)
                    - grid.z_ancillary_l_side_qubits
                    - grid.z_ancillary_r_side_qubits
                    - extra_z_plaquette_ancillary_qubit,
                    QubitNeighbor.L,
                    QubitNeighbor.R,
                )
            )
        ),
        *cnot_on_layer(
            pairs_list=grid.ancillary_to_pair(
                (
                    grid.z_even_col_ancillary_qubits
                    - grid.z_ancillary_l_side_qubits
                    - grid.z_ancillary_u_side_qubits
                    - grid.z_ancillary_r_side_qubits
                ).union(extra_z_plaquette_ancillary_qubit),
                QubitNeighbor.R,
                QubitNeighbor.U,
            )
        ),
    ]
def trotter_odd_zcol_entangle_minimal_qubits(
    grid: LGTGrid, extra_z_plaquette_indices: list[tuple[int, int]] = []
) -> list[cirq.Moment]:
    extra_odd_qubits = []
    for p in extra_z_plaquette_indices:
        if p[1] % 2 == 1:
            extra_odd_qubits.append(grid.z_plaquette_to_z_ancilla(p[0], p[1]))
    extra_z_plaquette_ancillary_qubit = set(extra_odd_qubits)
    return [
        *cnot_on_layer(
            pairs_list=grid.ancillary_to_pair(
                (grid.z_odd_col_ancillary_qubits - grid.z_ancillary_d_side_qubits).union(
                    extra_z_plaquette_ancillary_qubit
                ),
                QubitNeighbor.D,
                QubitNeighbor.L,
            )
        ),
        *cnot_on_layer(
            pairs_list=grid.ancillary_to_pair(
                (
                    grid.z_odd_col_ancillary_qubits
                    - grid.z_ancillary_u_side_qubits
                    - grid.z_ancillary_dr_corner_qubits
                ).union(extra_z_plaquette_ancillary_qubit),
                QubitNeighbor.L,
                QubitNeighbor.U,
            )
            .union(
                grid.ancillary_to_pair(
                    grid.z_ancillary_u_side_qubits.intersection(grid.z_odd_col_ancillary_qubits)
                    - grid.z_ancillary_r_side_qubits
                    - extra_z_plaquette_ancillary_qubit,
                    QubitNeighbor.L,
                    QubitNeighbor.R,
                )
            )
            .union(
                grid.ancillary_to_pair(
                    grid.z_ancillary_dr_corner_qubits.intersection(grid.z_odd_col_ancillary_qubits)
                    - extra_z_plaquette_ancillary_qubit,
                    QubitNeighbor.U,
                    QubitNeighbor.L,
                )
            )
        ),
        *cnot_on_layer(
            pairs_list=grid.ancillary_to_pair(
                (
                    grid.z_odd_col_ancillary_qubits
                    - grid.z_ancillary_u_side_qubits
                    - grid.z_ancillary_r_side_qubits
                ).union(extra_z_plaquette_ancillary_qubit),
                QubitNeighbor.R,
                QubitNeighbor.U,
            )
        ),
    ]
def trotter_even_xcol_entangle_minimal_qubits(
    grid: LGTGrid, extra_plaquette_indices: list[tuple[int, int]] = []
) ->list[cirq.Moment]:
    extra_even_plaquette_indices = []
    for p in extra_plaquette_indices:
        if p[1] % 2 == 0:
            extra_even_plaquette_indices.append(p)
    ancilla_qubits = grid.x_even_col_ancillary_qubits.union(
        {grid.x_plaquette_to_x_ancilla(p[0], p[1]) for p in extra_even_plaquette_indices}
    )
    return [
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(ancilla_qubits, QubitNeighbor.D, QubitNeighbor.L)),
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(ancilla_qubits, QubitNeighbor.L, QubitNeighbor.U)),
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(ancilla_qubits, QubitNeighbor.R, QubitNeighbor.U)),
    ]
def trotter_odd_xcol_entangle_minimal_qubits(
    grid: LGTGrid, extra_plaquette_indices: list[tuple[int, int]] = []
) -> list[cirq.Moment]:
    extra_odd_plaquette_indices = []
    for p in extra_plaquette_indices:
        if p[1] % 2 == 1:
            extra_odd_plaquette_indices.append(p)
    ancilla_qubits = grid.x_odd_col_ancillary_qubits.union(
        {grid.x_plaquette_to_x_ancilla(p[0], p[1]) for p in extra_odd_plaquette_indices}
    )
    return [
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(ancilla_qubits, QubitNeighbor.D, QubitNeighbor.L)),
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(ancilla_qubits, QubitNeighbor.L, QubitNeighbor.U)),
        *cnot_on_layer(pairs_list=grid.ancillary_to_pair(ancilla_qubits, QubitNeighbor.R, QubitNeighbor.U)),
    ]
def trotter_step_minimal_qubits(
    grid: LGTGrid,
    dt: sympy.Symbol,
    coupling: sympy.Symbol,
    he: sympy.Symbol,
    je: sympy.Symbol = 1,
    jm: sympy.Symbol = 1,
    extra_z_plaquette_indices: list[tuple[int, int]] = [],
    extra_x_plaquette_indices: list[tuple[int, int]] = [],
) -> list[cirq.Moment]:
    extra_z_plaquette_ancillary_qubits = {
        grid.z_plaquette_to_z_ancilla(plaquette_indices[0], plaquette_indices[1])
        for plaquette_indices in extra_z_plaquette_indices
    }
    extra_x_plaquette_ancillary_qubits = {
        grid.x_plaquette_to_x_ancilla(p[0], p[1]) for p in extra_x_plaquette_indices
    }
    extra_x_plaquette_even_col_ancillary_qubits = set([])
    extra_x_plaquette_odd_col_ancillary_qubits = set([])
    for p in extra_x_plaquette_indices:
        if p[1] % 2 == 0:
            extra_x_plaquette_even_col_ancillary_qubits.add(
                grid.x_plaquette_to_x_ancilla(p[0], p[1])
            )
        else:
            extra_x_plaquette_odd_col_ancillary_qubits.add(
                grid.x_plaquette_to_x_ancilla(p[0], p[1])
            )
    extended_physical_qubits = sorted(
        grid.u_set(grid.x_ancillary_qubits.union(extra_x_plaquette_ancillary_qubits))
        .union(grid.r_set(grid.x_ancillary_qubits.union(extra_x_plaquette_ancillary_qubits)))
        .union(grid.d_set(grid.x_ancillary_qubits.union(extra_x_plaquette_ancillary_qubits)))
        .union(grid.l_set(grid.x_ancillary_qubits.union(extra_x_plaquette_ancillary_qubits)))
    )
    return [
        *trotter_even_zcol_entangle_minimal_qubits(grid, extra_z_plaquette_indices),
        cirq.Moment(
            cirq.rz(-2 * je * dt).on_each(
                grid.u_set(
                    (grid.z_even_col_ancillary_qubits - grid.z_ancillary_u_side_qubits).union(
                        extra_z_plaquette_ancillary_qubits.intersection(
                            grid.z_even_col_ancillary_qubits
                        )
                    )
                )
            ),
            cirq.rz(-2 * je * dt).on_each(
                grid.r_set(
                    grid.z_ancillary_u_side_qubits.intersection(grid.z_even_col_ancillary_qubits)
                    - grid.z_ancillary_ur_corner_qubits
                    - extra_z_plaquette_ancillary_qubits
                )
            ),
            cirq.rz(-2 * je * dt).on_each(
                grid.l_set(
                    grid.z_ancillary_ur_corner_qubits.intersection(grid.z_even_col_ancillary_qubits)
                    - extra_z_plaquette_ancillary_qubits
                )
            ),
        ),
        *trotter_even_zcol_entangle_minimal_qubits(grid, extra_z_plaquette_indices)[::-1],
        *trotter_odd_zcol_entangle_minimal_qubits(grid, extra_z_plaquette_indices),
        cirq.Moment(
            cirq.rz(-2 * je * dt).on_each(
                grid.u_set(
                    (
                        grid.z_odd_col_ancillary_qubits
                        - grid.z_ancillary_u_side_qubits
                        - grid.z_ancillary_dr_corner_qubits
                    ).union(
                        extra_z_plaquette_ancillary_qubits.intersection(
                            grid.z_odd_col_ancillary_qubits
                        )
                    )
                )
            ),
            cirq.rz(-2 * je * dt).on_each(
                grid.r_set(
                    grid.z_ancillary_u_side_qubits.intersection(grid.z_odd_col_ancillary_qubits)
                    - grid.z_ancillary_r_side_qubits
                    - extra_z_plaquette_ancillary_qubits
                )
            ),
            cirq.rz(-2 * je * dt).on_each(
                grid.l_set(
                    grid.z_ancillary_ur_corner_qubits.union(
                        grid.z_ancillary_dr_corner_qubits
                    ).intersection(grid.z_odd_col_ancillary_qubits)
                    - extra_z_plaquette_ancillary_qubits
                )
            ),
        ),
        *trotter_odd_zcol_entangle_minimal_qubits(grid, extra_z_plaquette_indices)[::-1],
        cirq.Moment(cirq.H.on_each(extended_physical_qubits)),
        *trotter_even_xcol_entangle_minimal_qubits(
            grid, extra_plaquette_indices=extra_x_plaquette_indices
        ),
        cirq.Moment(
            cirq.rz(-2 * jm * dt).on_each(
                grid.u_set(
                    grid.x_even_col_ancillary_qubits.union(
                        extra_x_plaquette_even_col_ancillary_qubits
                    )
                )
            )
        ),
        *trotter_even_xcol_entangle_minimal_qubits(
            grid, extra_plaquette_indices=extra_x_plaquette_indices
        )[::-1],
        *trotter_odd_xcol_entangle_minimal_qubits(
            grid, extra_plaquette_indices=extra_x_plaquette_indices
        ),
        cirq.Moment(
            cirq.rz(-2 * jm * dt).on_each(
                grid.u_set(
                    grid.x_odd_col_ancillary_qubits.union(
                        extra_x_plaquette_odd_col_ancillary_qubits
                    )
                )
            )
        ),
        *trotter_odd_xcol_entangle_minimal_qubits(
            grid, extra_plaquette_indices=extra_x_plaquette_indices
        )[::-1],
        cirq.Moment(cirq.H.on_each(extended_physical_qubits)),
        cirq.Moment(cirq.rz(-2 * he * dt).on_each(grid.physical_qubits)),
        cirq.Moment(cirq.rx(-2 * coupling * dt).on_each(grid.physical_qubits)),
    ]
def plaquette_bitstrings(
    data: np.array, grid: LGTGrid, particle_locs: list[tuple[int, int]] = []
) -> np.ndarray:
    plaquette_bitstrings = np.zeros((np.shape(data)[0], (grid.rows + 1) * (grid.cols + 1)))
    for row in range(grid.rows + 1):
        for col in range(grid.cols + 1):
            if (row, col) not in particle_locs:
                p = col + (grid.cols + 1) * row
                plaquette_bitstrings[:, p] = (
                    np.sum(
                        data[
                            :,
                            list(
                                grid.z_plaquette_to_physical_qubit_indices(
                                    p // (grid.cols + 1), p % (grid.cols + 1)
                                )
                            ),
                        ],
                        axis=1,
                    )
                    % 2
                )
            else:
                p = col + (grid.cols + 1) * row
                plaquette_bitstrings[:, p] = (
                    np.sum(
                        data[
                            :,
                            list(
                                grid.z_plaquette_to_physical_qubit_indices(
                                    p // (grid.cols + 1), p % (grid.cols + 1)
                                )
                            ),
                        ],
                        axis=1,
                    )
                    + 1
                ) % 2
    return plaquette_bitstrings
def x_plaquette_bitstrings(data: np.array, grid: LGTGrid) -> np.ndarray:
    plaquette_bitstrings = np.zeros((np.shape(data)[0], (grid.rows) * (grid.cols)))
    for row in range(grid.rows):
        for col in range(grid.cols):
            p = col + (grid.cols) * row
            plaquette_bitstrings[:, p] = (
                np.sum(
                    data[
                        :,
                        list(
                            grid.x_plaquette_to_physical_qubit_indices(
                                p // (grid.cols), p % (grid.cols)
                            )
                        ),
                    ],
                    axis=1,
                )
                % 2
            )
    return plaquette_bitstrings
def cnot_on_layer(
    pairs_list: Sequence[tuple[cirq.GridQubit, cirq.GridQubit]],
    depolarization_probability: float | dict | None = None,
) -> Sequence[cirq.Moment]:
    if depolarization_probability is None:
        return [
            cirq.Moment(cirq.H.on_each(pair[1] for pair in pairs_list)),
            cirq.Moment(cirq.CZ.on(qc, qt) for qc, qt in pairs_list),
            cirq.Moment(cirq.H.on_each(pair[1] for pair in pairs_list)),
        ]
    elif isinstance(depolarization_probability, float):
        return [
            cirq.Moment(cirq.H.on_each(pair[1] for pair in pairs_list)),
            cirq.Moment(cirq.CZ.on(qc, qt) for qc, qt in pairs_list),
            cirq.Moment(
                cirq.depolarize(depolarization_probability, 2).on(pair[0], pair[1])
                for pair in pairs_list
            ),
            cirq.Moment(cirq.H.on_each(pair[1] for pair in pairs_list)),
        ]
    elif isinstance(depolarization_probability, dict):
        assert set(pairs_list).intersection(set(depolarization_probability.keys())) == set(
            pairs_list
        )
        return [
            cirq.Moment(cirq.H.on_each(pair[1] for pair in pairs_list)),
            cirq.Moment(cirq.CZ.on(qc, qt) for qc, qt in pairs_list),
            cirq.Moment(
                cirq.depolarize(depolarization_probability[pair], 2).on(pair[0], pair[1])
                for pair in pairs_list
            ),
            cirq.Moment(cirq.H.on_each(pair[1] for pair in pairs_list)),
        ]
def excitation_sep_plaquette_input(
    plaq_data: np.ndarray, plaq_rows: int = 3, plaq_cols: int = 2
) -> np.ndarray:
    mat1 = np.zeros((plaq_rows * plaq_cols, plaq_rows * plaq_cols))
    mat1[:] = np.arange(np.shape(mat1)[1]) % plaq_cols
    mat1 = np.transpose(mat1)
    mat2 = np.zeros((plaq_rows * plaq_cols, plaq_rows * plaq_cols))
    mat2[:] = np.arange(np.shape(mat2)[1]) % plaq_cols
    mat3 = np.zeros((plaq_rows * plaq_cols, plaq_rows * plaq_cols))
    mat3[:] = np.arange(np.shape(mat3)[1]) // plaq_cols
    mat3 = np.transpose(mat3)
    mat4 = np.zeros((plaq_rows * plaq_cols, plaq_rows * plaq_cols))
    mat4[:] = np.arange(np.shape(mat4)[1]) // plaq_cols
    distance_metric = (abs(mat1 - mat2) + abs(mat3 - mat4)) / 2
    distances = np.einsum("ij,jl,il->i", plaq_data, distance_metric, plaq_data)
    return distances
def plot_qubit_polarization_values(
    grid:LGTGrid,
    qubit_polarization_data: np.ndarray,
    ancilla_states_data:np.ndarray,
    ax: plt.Axes | None = None,
    qubit_kwargs: dict[str, Any] | None = None,
    set_axis_off: bool = True,
    force_equal_aspect: bool = True,
    qubit_colormap=colormaps.get_cmap("Oranges"),
    ancilla_colormap = colormaps.get_cmap("Oranges"),
    plot_physical_qubits: bool | list[list[tuple[int]]] = False,
    plot_ancillas: bool | list[list[tuple[int]]] = False,
) -> plt.Axes:
    if qubit_kwargs is None:
        qubit_kwargs = {"edgecolor": "k", "linewidth": 1.0}
    rows = grid.rows
    cols = grid.cols
    if ax is None:
        _fig, ax = plt.subplots()
    if set_axis_off:  # Remove axis frame
        ax.set_axis_off()
    if force_equal_aspect:
        ax.set_aspect("equal")
    ax.set_xlim(-1, cols)
    ax.set_ylim(rows, -1.5)
    ax.set_xticks(range(cols))
    ax.set_yticks(range(rows))
    qubit_order = []
    for row in range(grid.rows+1):
        for col in range(grid.cols):
            qubit_order.append(*grid.u_set({grid.x_plaquette_to_x_ancilla(row,col)}))
    for row in range(1,grid.rows+1):
        for col in range(grid.cols+1):
            qubit_order.append(*grid.u_set({grid.z_plaquette_to_z_ancilla(row,col)}))
    qubit_order
    pols_shuffled = np.array([qubit_polarization_data[np.nonzero(np.array(grid.physical_qubits) == qubit)[0][0]] for qubit in qubit_order])
    if plot_physical_qubits is True:
        qubit_index = 0
        for row in range(grid.rows + 1):
            for col in range(grid.cols):
                ax.add_patch(
                    get_qubit_patch_rect(
                        pols_shuffled,
                        qubit_index,
                        row,
                        col,
                        x_basis=True,
                        qubit_colormap=qubit_colormap,
                        **qubit_kwargs,
                    )
                )
                qubit_index += 1
        for row, col in grid.z_plaquette_indices:
            if row != grid.rows:
                ax.add_patch(
                    get_qubit_patch_rect(
                        pols_shuffled,
                        qubit_index,
                        row,
                        col,
                        x_basis=False,
                        qubit_colormap=qubit_colormap,
                        **qubit_kwargs,
                    )
                )
                qubit_index += 1
    elif isinstance(plot_physical_qubits, list):
        for row, col in plot_physical_qubits[0]:
            qubit_index = (row) * grid.cols + col
            ax.add_patch(
                get_qubit_patch_rect(
                    qubit_polarization_data,
                    qubit_index,
                    row,
                    col,
                    x_basis=True,
                    qubit_colormap=qubit_colormap,
                    **qubit_kwargs,
                )
            )
        for row, col in plot_physical_qubits[1]:
            qubit_index = (
                (grid.rows + 1) * (grid.cols + 1) + (row) * (grid.cols + 1) + col
            )
            ax.add_patch(
                get_qubit_patch_rect(
                    qubit_polarization_data,
                    qubit_index,
                    row,
                    col,
                    x_basis=False,
                    qubit_colormap=qubit_colormap,
                    **qubit_kwargs,
                )
            )
    if plot_ancillas is True:
        for row, col in grid.z_plaquette_indices:
            qubit_index = (2*grid.cols+1)*row+col
            ax.add_patch(
                get_ancilla_patch(data = ancilla_states_data, qubit_index = qubit_index,row=row, col=col, x_basis=False, ancilla_cmap = ancilla_colormap, **qubit_kwargs)
            )
        for row, col in grid.x_plaquette_indices:
            qubit_index = (2*grid.cols+1)*row+3+col
            ax.add_patch(
                get_ancilla_patch(data = ancilla_states_data, qubit_index = qubit_index,row=row, col=col, x_basis=True, ancilla_cmap = ancilla_colormap, **qubit_kwargs)
                )
    elif isinstance(plot_ancillas, list):
        for row, col in plot_ancillas[0]:
            ax.add_patch(
                get_ancilla_patch(row=row, col=col, x_basis=False, **qubit_kwargs)
            )
        for row, col in plot_ancillas[1]:
            ax.add_patch(get_ancilla_patch(row=row, col=col, x_basis=True, **qubit_kwargs))
    return ax
def get_qubit_patch_rect(
    data: np.array,
    qubit_index: int,
    row: int,
    col: int,
    x_basis: bool,
    qubit_colormap=colormaps.get_cmap("Oranges"),
    **kwargs,
) -> mpatches.Patch:
    if not x_basis:  # z basis, includes special boundary cases
        coordinates = [
            (col - 0.5 + 0.2, row),
            (col - 0.5, row + 0.25),
            (col - 0.5 - 0.2, row),
            (col - 0.5, row - 0.25),
        ]
    else:  # x basis
        coordinates = [
            (col + 0.25, row - 0.5),
            (col, row - 0.5 + 0.2),
            (col - 0.25, row - 0.5),
            (col, row - 0.5 - 0.2),
        ]
    color = qubit_colormap((data[qubit_index] - 1)/(-2))
    return mpatches.Polygon(coordinates, closed=True, facecolor=color, **kwargs)
def get_ancilla_patch(
        data:np.ndarray,
        qubit_index,
        row: int,
        col: int,
        x_basis: bool,
        ancilla_cmap,
        **kwargs
    ) -> mpatches.Patch:
    if not x_basis:
        coordinates = (col - 0.5, row - 0.5)
    else:  # x basis
        coordinates = (col, row)
    color = ancilla_cmap(data[qubit_index])
    return mpatches.Circle(coordinates, radius=0.146, facecolor=color, **kwargs)
def mean_field_energy(theta, Lx=5, Ly=5, Je=1., Jm=1., he=0.0):
    energy = - Je * Lx * Ly\
             - Jm * (Lx-1) * (Ly-1) * np.sin(theta)\
             - he * (2 * (Lx-1) + 2 * (Ly-1)) * np.cos(theta)\
             - he * (2 * Lx * Ly - 3 * Lx - 3 * Ly + 4) * np.cos(theta)**2
    return energy
def bitstring_to_expectation_value(
        bitstrings:np.ndarray
)->np.ndarray:
    return -2 * bitstrings + 1
def energy_from_measurements(
        grid:LGTGrid,
        hamiltonian_coefs:dict,
        z_basis_results:np.ndarray,
        x_basis_results:np.ndarray
) -> float:
    return (-hamiltonian_coefs['Je'] * np.sum(np.mean(bitstring_to_expectation_value(plaquette_bitstrings(z_basis_results,grid)),axis=0))
            -hamiltonian_coefs['Jm'] * np.sum(np.mean(bitstring_to_expectation_value(x_plaquette_bitstrings(x_basis_results,grid)),axis=0))
            -hamiltonian_coefs['he'] * np.sum(np.mean(bitstring_to_expectation_value(z_basis_results),axis=0))
            -hamiltonian_coefs['lambda'] * np.sum(np.mean(bitstring_to_expectation_value(x_basis_results),axis=0))
    )

from collections.abc import Iterator
from enum import Enum
import cirq
import numpy as np
class QubitNeighbor(Enum):
    A = "a"
    U = "u"
    R = "r"
    D = "d"
    L = "l"
class LGTGrid:
    def __init__(
        self,
        origin_qubit: cirq.GridQubit,
        orientation_vector: tuple[int, int],
        rows: int,
        cols: int,
        flip_rowcol: bool = False,
    ):
        if np.any(np.abs(orientation_vector) != np.array([1, 1])):
            raise ValueError(
                f"Inconsistent orientation_vector={orientation_vector}: must be (±1, ±1)"
            )
        if rows < 1 or cols < 1:
            raise ValueError(f"rows ({rows}) and cols ({cols}) must both be at least 1")
        self.origin_qubit = origin_qubit
        self.orientation_vector = orientation_vector
        self.row_vector = np.array([2 * orientation_vector[0], 0], dtype=int)
        self.col_vector = np.array([0, 2 * orientation_vector[1]], dtype=int)
        self.rows = rows
        self.cols = cols
        self.flip_rowcol = flip_rowcol
    @property
    def physical_qubits(self) -> set[cirq.GridQubit]:
        return sorted(
            self.u_set(self.x_ancillary_qubits)
            .union(self.r_set(self.x_ancillary_qubits))
            .union(self.d_set(self.x_ancillary_qubits))
            .union(self.l_set(self.x_ancillary_qubits))
        )
    @property
    def x_ancillary_qubits(self) -> set[cirq.GridQubit]:
        return {self.x_plaquette_to_x_ancilla(row, col) for row, col in self.x_plaquette_indices}
    @property
    def z_ancillary_l_side_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(row, 0) for row in range(0, self.rows + 1)}
    @property
    def z_ancillary_dl_corner_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(self.rows, 0)}
    @property
    def z_even_col_ancillary_qubits(self) -> set[cirq.GridQubit]:
        return {
            self.z_plaquette_to_z_ancilla(row, col)
            for row, col in self.z_plaquette_even_col_indices
        }
    @property
    def z_ancillary_d_side_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(self.rows, col) for col in range(0, self.cols + 1)}
    @property
    def z_ancillary_ul_corner_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(0, 0)}
    @property
    def z_ancillary_u_side_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(0, col) for col in range(0, self.cols + 1)}
    @property
    def z_ancillary_r_side_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(row, self.cols) for row in range(0, self.rows + 1)}
    @property
    def z_ancillary_ur_corner_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(0, self.cols)}
    @property
    def z_odd_col_ancillary_qubits(self) -> set[cirq.GridQubit]:
        return {
            self.z_plaquette_to_z_ancilla(row, col) for row, col in self.z_plaquette_odd_col_indices
        }
    @property
    def x_ancillary_qubits_by_col(self) -> list[set[cirq.GridQubit]]:
        return [
            {self.x_plaquette_to_x_ancilla(row, col) for row in range(self.rows)}
            for col in range(self.cols)
        ]
    @property
    def z_ancillary_dr_corner_qubits(self) -> set[cirq.GridQubit]:
        return {self.z_plaquette_to_z_ancilla(self.rows, self.cols)}
    @property
    def x_even_col_ancillary_qubits(self) -> set[cirq.GridQubit]:
        return {
            self.x_plaquette_to_x_ancilla(row, col)
            for row, col in self.x_plaquette_even_col_indices
        }
    @property
    def x_odd_col_ancillary_qubits(self) -> set[cirq.GridQubit]:
        return {
            self.x_plaquette_to_x_ancilla(row, col) for row, col in self.x_plaquette_odd_col_indices
        }
    @property
    def x_plaquette_indices(self) -> Iterator[tuple[int, int]]:
        for row in range(self.rows):
            for col in range(self.cols):
                yield row, col
    @property
    def z_plaquette_indices(self) -> Iterator[tuple[int, int]]:
        for row in range(self.rows + 1):
            for col in range(self.cols + 1):
                yield row, col
    @property
    def z_plaquette_even_col_indices(self) -> Iterator[tuple[int, int]]:
        for row in range(self.rows + 1):
            for col in range(0, self.cols + 1, 2):
                yield row, col
    @property
    def z_plaquette_odd_col_indices(self) -> Iterator[tuple[int, int]]:
        for row in range(self.rows + 1):
            for col in range(1, self.cols + 1, 2):
                yield row, col
    @property
    def x_plaquette_even_col_indices(self) -> Iterator[tuple[int, int]]:
        for row in range(self.rows):
            for col in range(0, self.cols, 2):
                yield row, col
    @property
    def x_plaquette_odd_col_indices(self) -> Iterator[tuple[int, int]]:
        for row in range(self.rows):
            for col in range(1, self.cols, 2):
                yield row, col
    def q_displaced(self, qubit: cirq.GridQubit, displacement: np.ndarray) -> cirq.GridQubit:
        if self.flip_rowcol is False:
            return qubit + (int(round(displacement[0])), int(round(displacement[1])))
        else:
            return qubit + (int(round(displacement[1])), int(round(displacement[0])))
    def u_set(self, qubit_set: set[cirq.GridQubit]) -> set[cirq.GridQubit]:
        return {self.q_displaced(qubit, -self.row_vector / 2) for qubit in qubit_set}
    def r_set(self, qubit_set: set[cirq.GridQubit]) -> set[cirq.GridQubit]:
        return {self.q_displaced(qubit, self.col_vector / 2) for qubit in qubit_set}
    def d_set(self, qubit_set: set[cirq.GridQubit]) -> set[cirq.GridQubit]:
        return {self.q_displaced(qubit, self.row_vector / 2) for qubit in qubit_set}
    def l_set(self, qubit_set: set[cirq.GridQubit]) -> set[cirq.GridQubit]:
        return {self.q_displaced(qubit, -self.col_vector / 2) for qubit in qubit_set}
    def ancillary_to_pair(
        self, a_set: set[cirq.GridQubit], qubit1_relationship: QubitNeighbor, qubit2_relationship: QubitNeighbor
    ) -> set[tuple[cirq.GridQubit, cirq.GridQubit]]:
        displacement_dict ={
            QubitNeighbor.A: 0,
            QubitNeighbor.U: -self.row_vector / 2,
            QubitNeighbor.R: self.col_vector / 2,
            QubitNeighbor.D: self.row_vector / 2,
            QubitNeighbor.L: -self.col_vector / 2,
        }
        return {
            (
                self.q_displaced(qubit, displacement_dict[qubit1_relationship]),
                self.q_displaced(qubit, displacement_dict[qubit2_relationship])
            )
            for qubit in a_set
        }
    def z_plaquette_to_physical_qubit_indices(self, row: int, col: int) -> list[int]:
        return [
            sorted(list(self.physical_qubits)).index(qubit)
            for qubit in self.z_plaquette_to_physical_qubits(row, col).values()
        ]
    def x_plaquette_to_physical_qubit_indices(self, row: int, col: int) -> list[int]:
        return [
            sorted(list(self.physical_qubits)).index(qubit)
            for qubit in self.x_plaquette_to_physical_qubits(row, col).values()
        ]
    def z_plaquette_to_physical_qubits(self, row: int, col: int) -> dict[str : cirq.GridQubit]:
        u_displacement = (
            (row - 0.5) * self.row_vector + (col - 0.5) * self.col_vector - self.row_vector / 2
        )
        r_displacement = (
            (row - 0.5) * self.row_vector + (col - 0.5) * self.col_vector + self.col_vector / 2
        )
        d_displacement = (
            (row - 0.5) * self.row_vector + (col - 0.5) * self.col_vector + self.row_vector / 2
        )
        l_displacement = (
            (row - 0.5) * self.row_vector + (col - 0.5) * self.col_vector - self.col_vector / 2
        )
        if row == 0 and col == 0:
            return {
                "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
                "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
            }
        elif row == 0 and col == self.cols:
            return {
                "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
                "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
            }
        elif row == self.rows and col == 0:
            return {
                "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
                "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
            }
        elif row == self.rows and col == self.cols:
            return {
                "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
                "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
            }
        elif row == 0:
            return {
                "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
                "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
                "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
            }
        elif col == 0:
            return {
                "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
                "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
                "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
            }
        elif row == self.rows:
            return {
                "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
                "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
                "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
            }
        elif col == self.cols:
            return {
                "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
                "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
                "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
            }
        else:
            return {
                "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
                "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
                "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
                "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
            }
    def x_plaquette_to_physical_qubits(self, row: int, col: int) -> dict[str : cirq.GridQubit]:
        u_displacement = (row) * self.row_vector + (col) * self.col_vector - self.row_vector / 2
        r_displacement = (row) * self.row_vector + (col) * self.col_vector + self.col_vector / 2
        d_displacement = (row) * self.row_vector + (col) * self.col_vector + self.row_vector / 2
        l_displacement = (row) * self.row_vector + (col) * self.col_vector - self.col_vector / 2
        return {
            "u_qubit": self.q_displaced(self.origin_qubit, u_displacement),
            "r_qubit": self.q_displaced(self.origin_qubit, r_displacement),
            "d_qubit": self.q_displaced(self.origin_qubit, d_displacement),
            "l_qubit": self.q_displaced(self.origin_qubit, l_displacement),
        }
    def x_plaquette_to_x_ancilla(self, row: int, col: int) -> cirq.GridQubit:
        displacement = row * self.row_vector + col * self.col_vector
        return self.q_displaced(self.origin_qubit, displacement)
    def z_plaquette_to_z_ancilla(self, row: int, col: int) -> cirq.GridQubit:
        displacement = (row - 1 / 2) * self.row_vector + (col - 1 / 2) * self.col_vector
        return self.q_displaced(self.origin_qubit, displacement)

from dataclasses import dataclass
from typing import Callable
import numpy as np
import cirq
import cirq_google as cg
@dataclass(frozen=True)
class HomogeneousCircuitStats:
    num_phx: int
    num_z: int
    num_syc: int
    has_permutation: bool = False
    has_measurement: bool = False
def _homogeneous_moment(
        moment: 'cirq.Moment',
        op_condition: Callable[[cirq.Operation], bool]) -> bool:
    cases = {op_condition(op) for op in moment}
    if len(cases) != 1:
        return False
    return list(cases)[0]
def _homogeneous_gate_type(moment, gate_type):
    return _homogeneous_moment(
        moment,
        lambda op: op.gate is not None and isinstance(op.gate, gate_type))
MOMENT_GATE_CLASSES = [
    cirq.PhasedXPowGate,
    cirq.ZPowGate,
    cg.SycamoreGate,
    cirq.MeasurementGate,
    cirq.QubitPermutationGate,
]
def get_moment_class(moment: cirq.Moment):
    mom_class_vec = [_homogeneous_gate_type(moment, gc) for gc in MOMENT_GATE_CLASSES]
    if np.sum(mom_class_vec) != 1:
        return None
    return MOMENT_GATE_CLASSES[np.argmax(mom_class_vec)]
def get_moment_classes(circuit: cirq.Circuit):
    return [get_moment_class(moment) for moment in circuit.moments]
def _find_circuit_structure_violations(mom_classes):
    violations = np.asarray([mom_class is None for mom_class in mom_classes])
    violation_indices = np.where(violations)[0]
    return violation_indices
def find_circuit_structure_violations(circuit: cirq.Circuit):
    mom_classes = get_moment_classes(circuit)
    return _find_circuit_structure_violations(mom_classes)
class BadlyStructuredCircuitError(ValueError):
    pass
def validate_well_structured(circuit: cirq.Circuit,
                             allow_terminal_permutations=False):
    mom_classes = get_moment_classes(circuit)
    violation_indices = _find_circuit_structure_violations(mom_classes)
    if len(violation_indices) > 0:
        raise BadlyStructuredCircuitError(
            "Badly structured circuit. "
            "Inhomogeneous or non-device moments at indices {}"
                .format(violation_indices))
    num_phx = 0
    num_z = 0
    hit_permutation = False
    hit_measurement = False
    tot_n_phx = 0
    tot_n_z = 0
    tot_n_syc = 0
    for mom_class in mom_classes:
        if mom_class in [cirq.PhasedXPowGate, cirq.ZPowGate, cg.SycamoreGate]:
            if hit_permutation:
                raise BadlyStructuredCircuitError(
                    "Permutations must be terminal")
            if hit_measurement:
                raise BadlyStructuredCircuitError(
                    "Measurements must be terminal")
        if mom_class == cirq.PhasedXPowGate:
            num_phx += 1
            tot_n_phx += 1
        elif mom_class == cirq.ZPowGate:
            num_z += 1
            tot_n_z += 1
        elif mom_class == cg.SycamoreGate:
            tot_n_syc += 1
            if num_phx > 1:
                raise BadlyStructuredCircuitError("Too many PhX in this slice")
            if num_z > 1:
                raise BadlyStructuredCircuitError("Too many Z in this slice")
            if num_phx < 1:
                print("Warning: no PhX in this slice")
            num_phx = 0
            num_z = 0
        elif mom_class == cirq.MeasurementGate:
            if hit_measurement:
                raise BadlyStructuredCircuitError("Too many measurements")
            if hit_permutation:
                pass  # fine
            hit_measurement = True
        elif mom_class == cirq.QubitPermutationGate:
            if not allow_terminal_permutations:
                raise BadlyStructuredCircuitError(
                    "Circuit contains permutation gates")
            if hit_measurement:
                raise BadlyStructuredCircuitError("Measurements must be terminal")
            if hit_permutation:
                raise BadlyStructuredCircuitError("Too many permutations")
            hit_permutation = True
        else:
            raise BadlyStructuredCircuitError("Unknown moment class")
    return mom_classes, HomogeneousCircuitStats(tot_n_phx, tot_n_z, tot_n_syc,
                                                hit_permutation,
                                                hit_measurement)
def _idle_qubits_by_moment(circuit: cirq.Circuit):
    qubits = circuit.all_qubits()
    for i, moment in enumerate(circuit.moments):
        idle_qubits = qubits - moment.qubits
        yield i, idle_qubits
def count_circuit_holes(circuit: cirq.Circuit):
    return sum(len(iq) for _, iq in _idle_qubits_by_moment(circuit))

from collections import defaultdict
from typing import Sequence, List, Optional, Tuple, Dict, Iterator
import networkx as nx
import numpy as np
import cirq
from recirq.qaoa.problems import _validate_problem_graph
try:
    from cirq_google.optimizers.convert_to_sycamore_gates import swap_rzz, rzz
except ImportError:
    from cirq_google.transformers.analytical_decompositions.two_qubit_to_sycamore import (
        _swap_rzz as swap_rzz,
        _rzz as rzz
    )
from recirq.qaoa.circuit_structure import validate_well_structured
class ZZSwap(cirq.Gate):
    def __init__(self, *,
                 zz_exponent: float,
                 zz_global_shift: float = 0):
        self._zz_gate = cirq.ZZPowGate(exponent=zz_exponent,
                                       global_shift=zz_global_shift)
        self._swap_gate = cirq.SWAP
    def _num_qubits_(self) -> int:
        return 2
    def _decompose_(self, qubits) -> 'cirq.OP_TREE':
        assert len(qubits) == 2
        yield self._zz_gate.on(*qubits)
        yield self._swap_gate.on(*qubits)
    @property
    def theta(self):
        return self._zz_gate.exponent * np.pi / 2
    def _circuit_diagram_info_(
            self,
            args: 'cirq.CircuitDiagramInfoArgs'
    ) -> 'cirq.CircuitDiagramInfo':
        return cirq.CircuitDiagramInfo(
            wire_symbols=('zzswap', f't={self._zz_gate.exponent:.3f}'))
def compile_problem_unitary_to_zzswap(
        problem_graph: nx.Graph,
        gamma: float,
        qubits: Sequence[cirq.Qid],
) -> Iterator[cirq.Operation]:
    n_qubits = len(qubits)
    order = list(range(n_qubits))
    for layer_num in range(n_qubits):
        lowest_active_qubit = layer_num % 2
        active_pairs = ((i, i + 1)
                        for i in range(lowest_active_qubit, n_qubits - 1, 2))
        for i, j in active_pairs:
            p, q = order[i], order[j]
            weight = problem_graph[p][q]['weight']
            yield ZZSwap(
                zz_exponent=2 * gamma * weight / np.pi,
                zz_global_shift=-0.5,
            ).on(qubits[i], qubits[j])
            order[i], order[j] = q, p
class ProblemUnitary(cirq.Gate):
    def __init__(self, problem_graph: nx.Graph, gamma: float):
        _validate_problem_graph(problem_graph)
        self.problem_graph = problem_graph
        self.gamma = gamma
    def _num_qubits_(self) -> int:
        return self.problem_graph.number_of_nodes()
    def _decompose_(self, qubits) -> 'cirq.OP_TREE':
        for i1, i2, weight in self.problem_graph.edges.data('weight'):
            q0 = qubits[i1]
            q1 = qubits[i2]
            yield cirq.ZZPowGate(
                exponent=2 * self.gamma * weight / np.pi, global_shift=-0.5).on(q0, q1)
    def _circuit_diagram_info_(
            self,
            args: 'cirq.CircuitDiagramInfoArgs'
    ) -> 'cirq.CircuitDiagramInfo':
        excess_q = self.num_qubits() - 2
        return cirq.CircuitDiagramInfo(
            wire_symbols=('problem', f'g={self.gamma:.3f}') + tuple(
                f'#{i + 2 + 1}' for i in range(excess_q)))
class SwapNetworkProblemUnitary(ProblemUnitary):
    def _decompose_(self, qubits) -> 'cirq.OP_TREE':
        yield from super()._decompose_(qubits)
        yield cirq.QubitPermutationGate(list(range(len(qubits)))[::-1]).on(*qubits)
    def _circuit_diagram_info_(
            self,
            args: 'cirq.CircuitDiagramInfoArgs'
    ) -> 'cirq.CircuitDiagramInfo':
        excess_q = self.num_qubits() - 2
        return cirq.CircuitDiagramInfo(
            wire_symbols=('swap-network', f'g={self.gamma:.3f}') + tuple(
                f'#{i + 2 + 1}' for i in range(excess_q)))
def compile_problem_unitary_to_swap_network(circuit: cirq.Circuit) -> cirq.Circuit:
    permutation = {q: q for q in circuit.all_qubits()}
    new_moments = []
    for moment in circuit.moments:
        permuted_moment = moment.transform_qubits(lambda q: permutation[q])
        new_ops = []
        for op in permuted_moment.operations:
            if (op.gate is not None and isinstance(op.gate, ProblemUnitary)
                    and not isinstance(op.gate, SwapNetworkProblemUnitary)):
                gate = op.gate  # type: ProblemUnitary
                new_gate = SwapNetworkProblemUnitary(problem_graph=gate.problem_graph,
                                                     gamma=gate.gamma)
                new_op = new_gate.on(*op.qubits)
                new_ops.append(new_op)
                qubits = op.qubits
                nq = len(qubits)
                qs_to_permute = {qubits[i]: qubits[nq - i - 1] for i in range(nq)}
                permutation = {q_from: qs_to_permute.get(q_to, permutation[q_to])
                               for q_from, q_to in permutation.items()}
            else:
                new_ops.append(op)
        new_moments.append(cirq.Moment(new_ops))
    needs_permute = sorted(q_from
                           for q_from, q_to in permutation.items()
                           if q_from != q_to)
    permute_i = []
    for q_from in needs_permute:
        q_to = permutation[q_from]
        permute_i.append(needs_permute.index(q_to))
    if len(permute_i) > 0:
        new_moments.append(cirq.Moment([
            cirq.QubitPermutationGate(permute_i).on(*needs_permute)
        ]))
    return cirq.Circuit(new_moments)
class _SwapNetworkToZZSWAP(cirq.PointOptimizer):
    def optimization_at(
            self,
            circuit: 'cirq.Circuit',
            index: int,
            op: 'cirq.Operation'
    ) -> Optional[cirq.PointOptimizationSummary]:
        if isinstance(op.gate, SwapNetworkProblemUnitary):
            gate = op.gate  # type: SwapNetworkProblemUnitary
            return cirq.PointOptimizationSummary(
                clear_span=1,
                clear_qubits=op.qubits,
                new_operations=compile_problem_unitary_to_zzswap(
                    gate.problem_graph, gate.gamma, op.qubits)
            )
def compile_swap_network_to_zzswap(circuit: cirq.Circuit, *, mutate=False) -> cirq.Circuit:
    if mutate:
        c2 = circuit
