def calibration_data_to_graph(calib_dict: cg.Calibration) -> nx.Graph:
    err_graph = nx.Graph()
    for (q1, q2), err in calib_dict['two_qubit_sycamore_gate_xeb_cycle_total_error'].items():
        err_graph.add_edge(q1, q2, weight=err[0])
    for (q,), err in calib_dict['single_qubit_readout_p0_error'].items():
        err_graph.nodes[q]['weight'] = err[0]
    for (q,), err in calib_dict['single_qubit_readout_p1_error'].items():
        err_graph.nodes[q]['weight'] += err[0]
    return err_graph
def _qubit_index_edges(device: cirq.Device):
    qubits = device.metadata.qubit_set if device.metadata else ()
    dev_graph = ccr.gridqubits_to_graph_device(qubits)
    for n1, n2 in dev_graph.edges:
        yield Node('grid', n1.row, n1.col), Node('grid', n2.row, n2.col)
def _device_to_tket_device(device: cirq.Device):
    return Architecture(
        list(_qubit_index_edges(device))
    )
def tk_to_cirq_qubit(tk: 'Qubit'):
    ind = tk.index
    return (
        cirq.LineQubit(ind[0])
        if len(ind) == 1
        else cirq.GridQubit(*ind)
    )
def place_on_device(circuit: cirq.Circuit,
                    device: cirq.Device,
                    ) -> Tuple[cirq.Circuit,
                               Dict[cirq.Qid, cirq.Qid],
                               Dict[cirq.Qid, cirq.Qid]]:
    if RouteCQC is NotImplemented:
        if pytket is NotImplemented:
            raise RuntimeError("Routing utilities are not available")
        else:
            tk_circuit = pytket.extensions.cirq.cirq_to_tk(circuit)
            tk_device = _device_to_tket_device(device)
            unit = CompilationUnit(tk_circuit, [ConnectivityPredicate(tk_device)])
            passes = SequencePass([
                PlacementPass(GraphPlacement(tk_device)),
                RoutingPass(tk_device)])
            passes.apply(unit)
            valid = unit.check_all_predicates()
            if not valid:
                raise RuntimeError("Routing failed")
            initial_map = {tk_to_cirq_qubit(n1): tk_to_cirq_qubit(n2)
                           for n1, n2 in unit.initial_map.items()}
            final_map = {tk_to_cirq_qubit(n1): tk_to_cirq_qubit(n2)
                         for n1, n2 in unit.final_map.items()}
            routed_circuit = pytket.extensions.cirq.tk_to_cirq(unit.circuit)
            return routed_circuit, initial_map, final_map
    router = cirq.RouteCQC(device.metadata.nx_graph)
    routed_circuit, initial_map, swap_map = router.route_circuit(circuit)
    return routed_circuit, initial_map, {lq: swap_map[initial_map[lq]] for lq in initial_map}
def path_weight(graph: nx.Graph, path,
                include_node_weights=True) -> float:
    if path is None:
        return float('inf')
    weight = 0
    for i in range(len(path) - 1):
        weight += graph[path[i]][path[i + 1]]['weight']
    if include_node_weights and 'weight' in graph.nodes[path[0]]:
        n = len(path)
        for node in path:
            weight += graph.nodes[node]['weight'] / n * 2
    return weight
def min_weight_simple_paths_brute_force(
        graph: nx.Graph,
        weight_fun: Callable[[nx.Graph, List], float] = path_weight):
    best_weights = defaultdict(lambda: float('inf'))
    best_paths = {}
    nodelist = list(graph.nodes())
    for i in range(len(nodelist) - 1):
        for j in range(i + 1, len(nodelist)):
            for path in nx.all_simple_paths(graph, nodelist[i], nodelist[j]):
                n = len(path)
                my_weight = weight_fun(graph, path)
                if my_weight < best_weights[n]:
                    best_paths[n] = path
                    best_weights[n] = my_weight
    return best_paths
def min_weight_simple_path_brute_force(
        graph: nx.Graph,
        n: int,
        weight_fun: Callable[[nx.Graph, List], float] = path_weight):
    return min_weight_simple_paths_brute_force(graph, weight_fun).get(n, None)
def join_path(path1, path2):
    if path1[-1] == path2[0]:
        return path1 + path2[1:]
    elif path2[-1] == path1[0]:
        return path2 + path1[1:]
    elif path1[-1] == path2[-1]:
        return path1 + path2[1::-1]
    elif path1[0] == path2[0]:
        return path2[:0:-1] + path1
    raise ValueError('Paths cannot be joined as they do not share any ends')
def min_weight_simple_path_greedy(
        graph: nx.Graph,
        n: int,
        weight_fun: Callable[[nx.Graph, List], float] = path_weight):
    def _grow_path_lowest_weight(path, partial_graph):
        adjacent_edges = sorted(list(partial_graph.edges([path[0], path[-1]],
                                                         data='weight')), key=lambda e: e[2])
        if len(adjacent_edges) == 0:
            return path
        u, v, _ = adjacent_edges[0]
        if path[0] == u or path[-1] == u:
            partial_graph.remove_node(u)
        else:
            partial_graph.remove_node(v)
        return join_path(path, [u, v])
    edges_sorted = sorted(list(graph.edges.data('weight')), key=lambda e: e[2])
    edges_sorted = edges_sorted[:len(edges_sorted) // 2]
    best_weight = float('inf')
    best_path = None
    for e in edges_sorted:
        subgraph = graph.copy()
        path = [e[0], e[1]]  # start with the given edge
        subgraph.remove_edge(e[0], e[1])
        while len(path) < n:
            path2 = _grow_path_lowest_weight(path, subgraph)
            if path2 == path:  # can't grow anymore
                break
            else:
                path = path2
                if subgraph.has_edge(path[0], path[-1]):
                    subgraph.remove_edge(path[0], path[-1])
        my_weight = weight_fun(graph, path)
        if len(path) == n and my_weight < best_weight:
            best_path = path
            best_weight = my_weight
    return best_path
def make_simple_path(graph: nx.Graph, n: int):
    subgraph = graph.copy()
    path = n * [None]
    degree_dict = dict(subgraph.degree())
    path[0] = min(degree_dict, key=degree_dict.get)
    len_so_far = 1
    while len_so_far < n:
        neighbors = sorted([(v, dv) for v, dv
                            in subgraph.degree(subgraph.neighbors(path[len_so_far - 1]))],
                           key=lambda x: x[1])
        if len(neighbors) == 0:
            return None  # dead end, can't add any more nodes
        next_node = neighbors[0][0]
        for i in range(len(neighbors)):
            if neighbors[i][1] >= 2:  # if there's a neighbor with degree 2
                next_node = neighbors[i][0]  # change the next node to that
                break
        path[len_so_far] = next_node
        subgraph.remove_node(path[len_so_far - 1])
        len_so_far += 1
    return path
def random_simple_path(graph: nx.Graph,
                       n: int,
                       num_tries=10):
    default_path = make_simple_path(graph, n)
    if default_path is None:
        return None
    def _grow_simple_path(path, subgraph):
        adjacent_edges = list(subgraph.edges([path[0], path[-1]]))
        if len(adjacent_edges) == 0:  # no neighboring edge
            return path
        u, v = adjacent_edges[np.random.randint(len(adjacent_edges))]
        if path[0] == u or path[-1] == u:
            subgraph.remove_node(u)
        else:
            subgraph.remove_node(v)
        return join_path(path, [u, v])
    edges = list(graph.edges)
    for _ in range(num_tries):
        u, v = edges[np.random.randint(len(edges))]
        path = [u, v]
        subgraph = graph.copy()
        subgraph.remove_edge(u, v)
        while len(path) < n:
            new_path = _grow_simple_path(path, subgraph)
            if new_path == path:
                break
            path = new_path
            if subgraph.has_edge(path[0], path[-1]):
                subgraph.remove_edge(path[0], path[-1])
        if len(path) == n:
            return path
    return default_path
class Snake:
    def __init__(self,
                 graph: nx.Graph,
                 path: List,
                 weight_fun: Callable[[nx.Graph, List], float] = path_weight):
        if not nx.is_simple_path(graph, path):
            raise ValueError("Invalid input: path must be simple")
        self.graph = graph
        self.path = path
        self.weight_fun = weight_fun
    def wiggle(self):
        node_index_list = list(range(len(self.path)))
        np.random.shuffle(node_index_list)
        for index in node_index_list:
            node = self.path[index]
            neighbors = nx.single_source_shortest_path_length(self.graph,
                                                              node, cutoff=2)
            for q in neighbors:
                if (q not in self.path
                        and neighbors[q] == 2
                        and (index == 0 or self.graph.has_edge(q, self.path[index - 1]))
                        and (index == len(self.path) - 1
                             or self.graph.has_edge(q, self.path[index + 1]))
                ):
                    new_path = self.path.copy()
                    new_path[index] = q
                    return Snake(self.graph, new_path, self.weight_fun)
        return self  # wasn't able to wiggle
    def slither(self, head=True):
        if not head:
            self.path.reverse()
        head_neighbors = list(self.graph.neighbors(self.path[0]))
        np.random.shuffle(head_neighbors)
        for q in head_neighbors:
            if q not in self.path or q == self.path[-1]:
                test_path = self.path.copy()
                test_path[1:] = test_path[:-1]
                test_path[0] = q
                return Snake(self.graph, test_path, self.weight_fun)
        if not head:
            self.path.reverse()
        return self  # wasn't able to slither
    def reassemble(self, head=True):
        if not head:
            self.path.reverse()
        head_neighbors = list(self.graph.neighbors(self.path[0]))
        np.random.shuffle(head_neighbors)
        for q in head_neighbors:
            if q != self.path[1] and q in self.path:
                new_path = self.path.copy()
                q_index = new_path.index(q)
                new_path[:q_index] = reversed(new_path[:q_index])
                return Snake(self.graph, new_path, self.weight_fun)
        if not head:
            self.path.reverse()
        return self  # wasn't able to reassemble
    def random_move(self):
        coin = np.random.randint(3)
        if coin == 0:
            return self.wiggle()
        elif coin == 1:
            return self.slither(head=np.random.choice(True, False))
        else:
            return self.reassemble(head=np.random.choice(True, False))
    def force_random_move(self):
        moves = [self.wiggle,
                 self.slither,
                 self.reassemble,
                 lambda: self.slither(head=False),
                 lambda: self.reassemble(head=False)]
        np.random.shuffle(moves)
        for mv in moves:
            new_snake = mv()
            if new_snake is not self:
                return new_snake
        return self  # wasn't able to make any moves
    def total_weight(self):
        return self.weight_fun(self.graph, self.path)
    def to_path(self):
        return self.path
def min_weight_simple_path_anneal(
        graph: nx.Graph,
        n: int,
        start_path=None,
        anneal_schedule: Optional[np.array] = None,
        weight_fun: Callable[[nx.Graph, List], float] = path_weight):
    if n < 2:
        raise ValueError('n needs to be >= 2')
    if start_path is None:
        if start_path is None:
            start_path = random_simple_path(graph, n)
        if start_path is None:
            return None
        my_snake = Snake(graph, start_path, weight_fun)
    else:
        my_snake = Snake(graph, start_path, weight_fun)
    my_E = my_snake.total_weight()
    best_E = my_E
    best_snake = my_snake
    if anneal_schedule is None:
        weights = [w for u, v, w in graph.edges(data='weight')]
        T_max = max(weights) * 2
        T_min = min(weights) / 2
        anneal_schedule = np.linspace(T_max, T_min, 3 * n * len(graph))
    for T in anneal_schedule:
        new_snake = my_snake.force_random_move()
        if new_snake is my_snake:
            break
        new_E = new_snake.total_weight()
        if new_E <= best_E:
            best_snake = new_snake
            best_E = new_E
        if np.exp(-(new_E - my_E) / T) >= np.random.rand():
            my_snake = new_snake
            my_E = new_E
    return best_snake.to_path()
def min_weight_simple_paths_mst(
        graph: nx.Graph,
        weight_fun: Callable[[nx.Graph, List], float] = path_weight):
    mst = nx.minimum_spanning_tree(graph)
    path_of_node_pairs = dict(nx.all_pairs_shortest_path(mst))
    best_paths = {}
    for u in path_of_node_pairs:
        for v in path_of_node_pairs[u]:
            n = len(path_of_node_pairs[u][v])
            if n < 2:
                continue
            if (n not in best_paths
                    or weight_fun(mst, best_paths[n])
                    > weight_fun(mst, path_of_node_pairs[u][v])):
                best_paths[n] = path_of_node_pairs[u][v]
    return best_paths
def min_weight_simple_path_mst(graph: nx.Graph, n: int,
                               weight_func: Callable[[nx.Graph, List], float] = path_weight):
    return min_weight_simple_paths_mst(graph, weight_func).get(n, None)
def min_weight_simple_path_mixed_strategy(
        graph: nx.Graph,
        n: int,
        num_restarts=10,
        weight_fun: Callable[[nx.Graph, List], float] = path_weight):
    paths_mst = min_weight_simple_paths_mst(graph)
    start_path = paths_mst.get(n, None)
    path_greedy = min_weight_simple_path_greedy(graph, n)
    if path_greedy is not None and weight_fun(graph, path_greedy) < weight_fun(graph, start_path):
        start_path = path_greedy
    if start_path is None:
        return None
    best_path = start_path
    for _ in range(num_restarts):
        path = min_weight_simple_path_anneal(graph, n, start_path=start_path)
        if weight_fun(graph, path) < weight_fun(graph, best_path):
            best_path = path
    return best_path
@lru_cache()
def _get_device_calibration(device_name: str):
    processor_id = recirq.get_processor_id_by_device_name(device_name)
    if processor_id is None:
        device_obj = recirq.get_device_obj_by_name(device_name)
        dummy_graph = ccr.gridqubits_to_graph_device(
            device_obj.metadata.qubit_set if device_obj.metadata is not None else ()
        )
        nx.set_edge_attributes(dummy_graph, name='weight', values=0.01)
        return dummy_graph
    calibration = cg.get_engine_calibration(processor_id)
    err_graph = calibration_data_to_graph(calibration)
    return err_graph
PLACEMENT_STRATEGIES = {
    'brute_force': min_weight_simple_path_brute_force,
    'random': random_simple_path,
    'greedy': min_weight_simple_path_greedy,
    'anneal': min_weight_simple_path_anneal,
    'mst': min_weight_simple_path_mst,
    'mixed': min_weight_simple_path_mixed_strategy,
}
def place_line_on_device(
        device_name: str,
        n: int,
        line_placement_strategy: str,
        err_graph=None,
) -> List[cirq.GridQubit]:
    if line_placement_strategy not in PLACEMENT_STRATEGIES.keys():
        raise ValueError(f"Unknown line placement strategy {line_placement_strategy}")
    if err_graph is None:
        err_graph = _get_device_calibration(device_name)
    return PLACEMENT_STRATEGIES[line_placement_strategy](err_graph, n)

from collections import defaultdict
from dataclasses import dataclass
from typing import Dict, Optional, Tuple, List, Union
import networkx as nx
import numpy as np
import cirq
import recirq
def _validate_problem_graph(graph: nx.Graph):
    if min(graph.degree[node] for node in graph.nodes) == 0:
        raise ValueError("Can't serialize graphs with orphan nodes")
    all_attrs = set()
    for u, v in graph.edges:
        all_attrs |= graph.edges[u, v].keys()
    if not all_attrs == {'weight'}:
        raise ValueError(
            "Problem graph must have `weight` edge attributes")
    if sorted(graph.nodes) != list(range(graph.number_of_nodes())):
        raise ValueError(
            "Problem graph must have contiguous, 0-indexed integer nodes, not {}".format(graph.nodes))
def _graph_to_serializable_edgelist(graph: nx.Graph):
    _validate_problem_graph(graph)
    return [(v1, v2, float(w)) for (v1, v2, w) in graph.edges.data('weight')]
def _serialized_edgelist_to_graph(edgelist: List[Tuple]):
    g = nx.Graph()
    for u, v, w in edgelist:
        g.add_edge(u, v, weight=w)
    return g
def get_growing_subgraphs(device_graph: nx.Graph, central_qubit: cirq.Qid,
                          min_size=2, max_size=None) -> Dict[int, Tuple[cirq.Qid]]:
    by_radius = defaultdict(list)
    for q, distance in nx.shortest_path_length(device_graph, source=central_qubit).items():
        by_radius[distance].append(q)
    by_radius = {k: sorted(v) for k, v in by_radius.items()}
    subgraphs = []
    for r in by_radius:
        qs = by_radius[r]
        for i, q in enumerate(qs):
            if len(subgraphs) > 0:
                prev = subgraphs[-1]
            else:
                prev = tuple()
            subgraph = prev + (q,)
            subgraphs.append(subgraph)
    if max_size is None:
        max_size = device_graph.number_of_nodes()
    return {len(subgraph): subgraph for subgraph in subgraphs
            if min_size <= len(subgraph) <= max_size}
def random_plus_minus_1_weights(graph: nx.Graph, rs: Optional[np.random.RandomState] = None):
    if rs is None:
        rs = np.random
    elif not isinstance(rs, np.random.RandomState):
        raise ValueError("Invalid random state: {}".format(rs))
    problem_graph = nx.Graph()
    for n1, n2 in graph.edges:
        problem_graph.add_edge(n1, n2, weight=rs.choice([-1, 1]))
    return problem_graph
@dataclass
class HardwareGridProblem:
    graph: nx.Graph
    coordinates: List[Tuple[int, int]]
    def _json_dict_(self):
        return {
            'cirq_type': 'recirq.qaoa.' + self.__class__.__name__,
            'edgelist': _graph_to_serializable_edgelist(self.graph),
            'coordinates': self.coordinates,
        }
    @classmethod
    def _from_json_dict_(cls, edgelist, coordinates, **kwargs):
        graph = _serialized_edgelist_to_graph(edgelist)
        coordinates = [tuple(v) for v in coordinates]
        return cls(graph=graph, coordinates=coordinates)
recirq.Registry.register('recirq.qaoa.HardwareGridProblem', HardwareGridProblem)
def get_all_hardware_grid_problems(
        device_graph: nx.Graph,
        central_qubit: cirq.GridQubit,
        n_instances: int,
        rs: np.random.RandomState,
):
    all_hg_problems: Dict[Tuple[int, int], HardwareGridProblem] = {}
    subgraphs = get_growing_subgraphs(device_graph=device_graph,
                                      central_qubit=central_qubit)
    for n_qubits in sorted(subgraphs):
        subgraph = nx.subgraph(device_graph, subgraphs[n_qubits])
        for instance_i in range(n_instances):
            problem = random_plus_minus_1_weights(subgraph, rs=rs)
            qubits = sorted(problem.nodes)
            coordinates = [(q.row, q.col) for q in qubits]
            problem = nx.relabel_nodes(problem, {q: i for i, q in enumerate(qubits)})
            all_hg_problems[n_qubits, instance_i] = HardwareGridProblem(
                graph=problem,
                coordinates=coordinates,
            )
    return all_hg_problems
@dataclass
class SKProblem:
    graph: nx.Graph
    def _json_dict_(self):
        return {
            'cirq_type': 'recirq.qaoa.' + self.__class__.__name__,
            'edgelist': _graph_to_serializable_edgelist(self.graph)
        }
    @classmethod
    def _from_json_dict_(cls, edgelist, **kwargs):
        return cls(graph=_serialized_edgelist_to_graph(edgelist))
recirq.Registry.register('recirq.qaoa.SKProblem', SKProblem)
def get_all_sk_problems(
        max_n_qubits: int,
        n_instances: int,
        rs: np.random.RandomState):
    all_sk_problems: Dict[Tuple[int, int], SKProblem] = {}
    for n_qubits in range(2, max_n_qubits + 1):
        for instance_i in range(n_instances):
            graph = nx.complete_graph(n_qubits)
            graph = random_plus_minus_1_weights(graph, rs=rs)
            all_sk_problems[n_qubits, instance_i] = SKProblem(
                graph=graph,
            )
    return all_sk_problems
@dataclass
class ThreeRegularProblem:
    graph: nx.Graph
    def _json_dict_(self):
        return {
            'cirq_type': 'recirq.qaoa.' + self.__class__.__name__,
            'edgelist': _graph_to_serializable_edgelist(self.graph)
        }
    @classmethod
    def _from_json_dict_(cls, edgelist, **kwargs):
        return cls(graph=_serialized_edgelist_to_graph(edgelist))
recirq.Registry.register('recirq.qaoa.ThreeRegularProblem', ThreeRegularProblem)
def get_all_3_regular_problems(
        max_n_qubits: int,
        n_instances: int,
        rs: np.random.RandomState):
    all_3reg_problems: Dict[Tuple[int, int], ThreeRegularProblem] = {}
    for n_qubits in range(4, max_n_qubits + 1, 2):
        for instance_i in range(n_instances):
            graph = nx.random_regular_graph(3, n_qubits, seed=rs)
            nx.set_edge_attributes(graph, values=1, name='weight')
            all_3reg_problems[n_qubits, instance_i] = ThreeRegularProblem(
                graph=graph)
    return all_3reg_problems
ProblemT = Union[HardwareGridProblem, SKProblem, ThreeRegularProblem]

from typing import Tuple, Optional, Dict, List
import itertools
import multiprocessing
import networkx as nx
import numpy as np
import cirq
SIGMA_X_IND, SIGMA_Y_IND, SIGMA_Z_IND = (1, 2, 3)
def minimizable_qaoa_fun(graph: nx.Graph, flag_z2_sym=True,
                         node_to_index_map=None, dtype=np.complex128):
    r
    HamC = create_ZZ_HamC(graph=graph, flag_z2_sym=flag_z2_sym,
                          node_to_index_map=node_to_index_map, dtype=dtype)
    n_nodes = graph.number_of_nodes()
    def f(param):
        return ising_qaoa_grad(n_nodes, HamC, param, flag_z2_sym, dtype=dtype)
    return f
def create_ZZ_HamC(graph: nx.Graph, flag_z2_sym=True, node_to_index_map=None, dtype=np.complex128):
    r
    n_nodes = graph.number_of_nodes()
    HamC = np.zeros((2 ** n_nodes, 1), dtype=dtype)
    sigma_z = np.asarray([[1], [-1]], dtype=dtype)
    if node_to_index_map is None:
        node_to_index_map = {q: i for i, q in enumerate(graph.nodes)}
    for a, b in graph.edges:
        HamC += graph[a][b]['weight'] * ham_two_local_term(
            sigma_z, sigma_z, node_to_index_map[a], node_to_index_map[b], n_nodes, dtype=dtype)
    if flag_z2_sym:
        return HamC[range(2 ** (n_nodes - 1)), 0]
    else:
        return HamC[:, 0]
def ham_two_local_term(op1, op2, ind1, ind2, N, dtype=np.complex128):
    r
    if ind1 > ind2:
        return ham_two_local_term(op2, op1, ind2, ind1, N, dtype=dtype)
    if op1.shape != op2.shape or op1.ndim != 2:
        raise ValueError('ham_two_local_term: invalid operator input')
    if ind1 < 0 or ind2 > N - 1:
        raise ValueError('ham_two_local_term: invalid input indices')
    if op1.shape[0] == 1 or op1.shape[1] == 1:
        myeye = lambda n: np.ones(np.asarray(op1.shape) ** n, dtype=dtype)
    else:
        myeye = lambda n: np.eye(np.asarray(op1.shape) ** n, dtype=dtype)
    return np.kron(myeye(ind1),
                   np.kron(op1, np.kron(myeye(ind2 - ind1 - 1),
                                        np.kron(op2, myeye(N - ind2 - 1)))))
def multiply_single_spin(psi, N: int, i: int, pauli_ind: int, dtype=np.complex128):
    IndL = 2 ** i
    IndR = 2 ** (N - i - 1)
    out = psi.reshape([IndL, 2, IndR], order='F').copy()
    if pauli_ind == SIGMA_X_IND:  # sigma_X
        out = np.flip(out, 1)
    elif pauli_ind == SIGMA_Y_IND:  # sigma_Y
        out = np.flip(out, 1).astype(dtype, copy=False)
        out[:, 0, :] = -1j * out[:, 0, :]
        out[:, 1, :] = 1j * out[:, 1, :]
    elif pauli_ind == SIGMA_Z_IND:  # sigma_Z
        out[:, 1, :] = -out[:, 1, :]
    return out.reshape(2 ** N, order='F')
def evolve_by_HamB(N, beta, psi_in, flag_z2_sym=False, copy=True, dtype=np.complex128):
    r
    if copy:
        psi = psi_in.copy()
    else:
        psi = psi_in
    if not flag_z2_sym:
        for i in range(N):
            psi = (np.cos(beta) * psi
                   - 1j * np.sin(beta) * multiply_single_spin(psi, N, i, SIGMA_X_IND, dtype))
    else:
        for i in range(N - 1):
            psi = (np.cos(beta) * psi
                   - 1j * np.sin(beta) * multiply_single_spin(psi, N - 1, i, SIGMA_X_IND, dtype))
        psi = np.cos(beta) * psi - 1j * np.sin(beta) * np.flipud(psi)
    return psi
def ising_qaoa_grad(N, HamC, param, flag_z2_sym=False, dtype=np.complex128):
    p = len(param) // 2
    gammas = param[:p]
    betas = param[p:]
    def evolve_by_ham_b_local(beta, psi):
        return evolve_by_HamB(N, beta, psi, flag_z2_sym, copy=False, dtype=dtype)
    if flag_z2_sym:
        psi_p = np.zeros([2 ** (N - 1), 2 * p + 2], dtype=dtype)
        psi_p[:, 0] = 1 / 2 ** ((N - 1) / 2)
    else:
        psi_p = np.zeros([2 ** N, 2 * p + 2], dtype=dtype)
        psi_p[:, 0] = 1 / 2 ** (N / 2)
    for q in range(p):
        psi_p[:, q + 1] = evolve_by_ham_b_local(
            betas[q], np.exp(-1j * gammas[q] * HamC) * psi_p[:, q])
    psi_p[:, p + 1] = HamC * psi_p[:, p]
    for q in range(p):
        psi_p[:, p + 2 + q] = (np.exp(1j * gammas[p - 1 - q] * HamC)
                               * evolve_by_ham_b_local(-betas[p - 1 - q], psi_p[:, p + 1 + q]))
    F = np.real(np.vdot(psi_p[:, p], psi_p[:, p + 1]))
    Fgrad = np.zeros(2 * p)
    for q in range(p):
        Fgrad[q] = -2 * np.imag(np.vdot(psi_p[:, q], HamC * psi_p[:, 2 * p + 1 - q]))
        if not flag_z2_sym:
            psi_temp = np.zeros(2 ** N, dtype=dtype)
            for i in range(N):
                psi_temp += multiply_single_spin(psi_p[:, 2 * p - q], N, i, 1, dtype=dtype)
        else:
            psi_temp = np.zeros(2 ** (N - 1), dtype=dtype)
            for i in range(N - 1):
                psi_temp += multiply_single_spin(psi_p[:, 2 * p - q], N - 1, i, 1, dtype=dtype)
            psi_temp += np.flipud(psi_p[:, 2 * p - q])
        Fgrad[p + q] = -2 * np.imag(np.vdot(psi_p[:, q + 1], psi_temp))
    return F, Fgrad
def ising_qaoa_expectation_and_variance(N, HamC, param, flag_z2_sym=False, dtype=np.complex128):
    p = len(param) // 2
    gammas = param[:p]
    betas = param[p:]
    def evolve_by_HamB_local(beta, psi):
        return evolve_by_HamB(N, beta, psi, flag_z2_sym, False, dtype=dtype)
    if flag_z2_sym:
        psi = np.empty(2 ** (N - 1), dtype=dtype)
        psi[:] = 1 / 2 ** ((N - 1) / 2)
    else:
        psi = np.empty(2 ** N, dtype=dtype)
        psi[:] = 1 / 2 ** (N / 2)
    for q in range(p):
        psi = evolve_by_HamB_local(betas[q], np.exp(-1j * gammas[q] * HamC) * psi)
    expectation = np.real(np.vdot(psi, HamC * psi))
    variance = np.real(np.vdot(psi, HamC ** 2 * psi) - expectation ** 2)
    return expectation, variance, psi
def qaoa_expectation_and_variance_fun(
        graph: nx.Graph,
        flag_z2_sym=True,
        node_to_index_map=None,
        dtype=np.complex128):
    r
    HamC = create_ZZ_HamC(graph, flag_z2_sym, node_to_index_map, dtype=dtype)
    N = graph.number_of_nodes()
    def f(param):
        return ising_qaoa_expectation_and_variance(
            N=N, HamC=HamC, param=param, flag_z2_sym=flag_z2_sym, dtype=dtype)
    return f
def _ising_qaoa_expectation(N, HamC, param, flag_z2_sym, dtype):
    return ising_qaoa_expectation_and_variance(
        N, HamC, param, flag_z2_sym, dtype)[0]
def exact_qaoa_values_on_grid(
        graph: nx.Graph,
        xlim: Tuple[float, float] = (0, np.pi / 2),
        ylim: Tuple[float, float] = (-np.pi / 4, np.pi / 4),
        x_grid_num: int = 20,
        y_grid_num: int = 20,
        num_processors: int = 1,
        dtype=np.complex128):
    a, b = xlim
    c, d = ylim
    gammas = np.linspace(a, b, x_grid_num)
    betas = np.linspace(c, d, y_grid_num)
    HamC = create_ZZ_HamC(graph, dtype=dtype)
    N = graph.number_of_nodes()
    with multiprocessing.Pool(num_processors) as pool:
        vals = pool.starmap(_ising_qaoa_expectation,
                            [(N, HamC, x, True, dtype)
                             for x in itertools.product(gammas, betas)])
    return np.reshape(np.array(vals), (x_grid_num, y_grid_num)).T
def hamiltonian_objective(
        bitstring: np.ndarray,
        graph: nx.Graph,
        node_to_index_map: Optional[Dict[cirq.Qid, int]] = None
) -> float:
    if node_to_index_map is None:
        node_to_index_map = {q: i for i, q in enumerate(sorted(graph.nodes))}
    return sum(graph[a][b]['weight'] * (-1) ** (
            bool(bitstring[node_to_index_map[a]])
            + bool(bitstring[node_to_index_map[b]]))
               for a, b in graph.edges)
def hamiltonian_objectives(
        bitstrings: np.ndarray,
        graph: nx.Graph,
        nodelist: Optional[List[int]] = None,
        readout_calibration: Optional[cirq.experiments.SingleQubitReadoutCalibrationResult] = None,
        qubit_map: Optional[Dict[int, cirq.Qid]] = None
) -> np.ndarray:
    if nodelist is None:
        nodelist = sorted(graph.nodes)
    mat = nx.adjacency_matrix(graph, nodelist=nodelist)
    if readout_calibration:
        if qubit_map is None:
            qubit_map = {q: q for q in nodelist}
        correction_matrix = np.empty(mat.shape)
        for i, j in itertools.product(range(len(graph)), repeat=2):
            p0_i = 1 - readout_calibration.zero_state_errors[qubit_map[nodelist[i]]]
            p1_i = 1 - readout_calibration.one_state_errors[qubit_map[nodelist[i]]]
            p0_j = 1 - readout_calibration.zero_state_errors[qubit_map[nodelist[j]]]
            p1_j = 1 - readout_calibration.one_state_errors[qubit_map[nodelist[j]]]
            correction_matrix[i, j] = (1 / ((p0_i + p1_i - 1) * (p0_j + p1_j - 1)))
        mat = mat.toarray() * correction_matrix
    vecs = (-1) ** bitstrings
    return 0.5 * np.sum(vecs * (mat @ vecs.T).T, axis=-1)
def hamiltonian_objective_avg_and_err(
        bitstrings: np.ndarray,
        graph: nx.Graph,
        nodelist: Optional[List[int]] = None,
) -> Tuple[float, float]:
    if nodelist is None:
        nodelist = sorted(graph.nodes)
    assert len(nodelist) == bitstrings.shape[1]
    node_to_i = {n: i for i, n in enumerate(nodelist)}
    vecs = (-1) ** bitstrings
    coeffs = []
    vars = []
    for n1, n2, w in graph.edges.data('weight'):
        coeffs += [w]
        i1 = node_to_i[n1]
        i2 = node_to_i[n2]
        vars += [vecs[:, i1] * vecs[:, i2]]
    vars = np.asarray(vars)
    coeffs = np.asarray(coeffs)[np.newaxis, :]
    f = coeffs @ np.mean(vars, axis=1)
    f = f.item()  # to normal float
    var = coeffs @ np.atleast_2d(np.cov(vars)) @ coeffs.T
    var = var.item()  # to normal float
    std_err = np.sqrt(var / len(bitstrings))
    return f, std_err
def lowest_and_highest_energy(graph: nx.Graph):
    hamiltonian = create_ZZ_HamC(graph, dtype=np.float64)
    return np.min(hamiltonian), np.max(hamiltonian)

from functools import lru_cache
from typing import Optional
from cirq.protocols.json_serialization import ObjectFactory, DEFAULT_RESOLVERS
from .sk_model import (
    SKModelQAOASpec,
)
@lru_cache()
def _resolve_json(cirq_type: str) -> Optional[ObjectFactory]:
    if not cirq_type.startswith('recirq.qaoa.'):
        return None
    cirq_type = cirq_type[len('recirq.qaoa.'):]
    return {k.__name__: k for k in [
