@attrs.frozen
class TrialWavefunctionData(data.Data):
    params: PerfectPairingPlusTrialWavefunctionParams
    ansatz_circuit: cirq.Circuit
    superposition_circuit: cirq.Circuit
    hf_energy: float
    ansatz_energy: float
    fci_energy: float
    one_body_basis_change_mat: np.ndarray = attrs.field(
        converter=_to_numpy, eq=attrs.cmp_using(eq=np.array_equal)
    )
    one_body_params: np.ndarray = attrs.field(
        converter=_to_numpy, eq=attrs.cmp_using(eq=np.array_equal)
    )
    two_body_params: np.ndarray = attrs.field(
        converter=_to_numpy, eq=attrs.cmp_using(eq=np.array_equal)
    )
    def _json_dict_(self):
        simple_dict = attrs.asdict(self)
        simple_dict["params"] = self.params
        return simple_dict
    @classmethod
    def build_pp_plus_trial_from_dependencies(
        cls,
        params: PerfectPairingPlusTrialWavefunctionParams,
        *,
        dependencies: Dict[data.Params, data.Data],
        do_print: bool = False,
    ) -> "TrialWavefunctionData":
        from recirq.qcqmc import optimize_wf
        if do_print:
            print("Building Trial Wavefunction")
        np.random.seed(params.seed)
        hamiltonian_data = dependencies[params.hamiltonian_params]
        assert isinstance(hamiltonian_data, hamiltonian.HamiltonianData)
        if params.n_orb != params.n_elec:
            raise ValueError("PP wavefunction must have n_orb = n_elec")
        if params.do_optimization:
            (
                one_body_params,
                two_body_params,
                one_body_basis_change_mat,
            ) = optimize_wf.get_pp_plus_params(
                hamiltonian_data=hamiltonian_data,
                restricted=params.restricted,
                random_parameter_scale=params.random_parameter_scale,
                initial_orbital_rotation=params.initial_orbital_rotation,
                heuristic_layers=params.heuristic_layers,
                do_pp=params.do_pp,
                n_optimization_restarts=params.n_optimization_restarts,
                do_print=do_print,
                use_fast_gradients=params.use_fast_gradients,
            )
        else:
            if params.initial_two_body_qchem_amplitudes is None:
                raise NotImplementedError(
                    "if initial_two_body_qchem_amplitudes must be set if do_optimization is False."
                )
            if params.initial_orbital_rotation: 
                raise NotImplementedError(
                    "Initial oribtal rotation must be None if do_optimization is False."
                )
            n_one_body_params = params.n_orb * (params.n_orb - 1)
            one_body_params = np.zeros(n_one_body_params)
            one_body_basis_change_mat = np.diag(np.ones(params.n_orb * 2))
            two_body_params = optimize_wf.get_two_body_params_from_qchem_amplitudes(
                params.initial_two_body_qchem_amplitudes
            )
        (superposition_circuit, ansatz_circuit) = afqmc_circuits.get_circuits(
            two_body_params=two_body_params,
            n_orb=params.n_orb,
            n_elec=params.n_elec,
            heuristic_layers=params.heuristic_layers,
        )
        ansatz_energy, hf_energy = optimize_wf.get_and_check_energy(
            hamiltonian_data=hamiltonian_data,
            ansatz_circuit=ansatz_circuit,
            params=params,
            one_body_params=one_body_params,
            two_body_params=two_body_params,
            one_body_basis_change_mat=one_body_basis_change_mat,
        )
        return cls(
            params=params,
            ansatz_circuit=ansatz_circuit,
            superposition_circuit=superposition_circuit,
            hf_energy=hf_energy,
            ansatz_energy=ansatz_energy,
            fci_energy=hamiltonian_data.e_fci,
            one_body_basis_change_mat=one_body_basis_change_mat,
            one_body_params=one_body_params,
            two_body_params=two_body_params,
        )
def get_rotated_hamiltonians(
    *,
    hamiltonian_data: hamiltonian.HamiltonianData,
    one_body_basis_change_mat: np.ndarray,
    mode_qubit_map: Mapping[fermion_mode.FermionicMode, cirq.Qid],
    ordered_qubits: Sequence[cirq.Qid],
) -> Tuple[fqe.hamiltonians.hamiltonian.Hamiltonian, float, scipy.sparse.csc_matrix]:
    n_qubits = len(mode_qubit_map)
    fqe_ham = hamiltonian_data.get_restricted_fqe_hamiltonian()
    e_core = hamiltonian_data.e_core
    mol_ham = hamiltonian_data.get_molecular_hamiltonian()
    mol_ham.rotate_basis(one_body_basis_change_mat)
    fermion_operator_ham = of.get_fermion_operator(mol_ham)
    reorder_func = fqe_conversion.get_reorder_func(
        mode_qubit_map=mode_qubit_map, ordered_qubits=ordered_qubits
    )
    fermion_operator_ham_qubit_ordered = of.reorder(
        fermion_operator_ham, reorder_func, num_modes=n_qubits
    )
    sparse_qubit_ham = of.get_sparse_operator(fermion_operator_ham_qubit_ordered)
    return fqe_ham, e_core, sparse_qubit_ham

from typing import Callable, Dict, List, Tuple
from numbers import Number
import os
import cirq
import cirq_google
import functools
import numpy as np
@functools.lru_cache(maxsize=128)
def _load_circuit(fname: str) -> cirq.Circuit:
    with open(os.path.join(os.path.dirname(__file__), fname), "r") as f:
        return cirq.read_json(f)
def tsym_block(qubits: List[cirq.Qid], params: List[Number]) -> List[cirq.Operation]:
    mapped_circuit = _load_circuit("tsym_permute.json").transform_qubits(
        {cirq.GridQubit(0, 0): qubits[0], cirq.GridQubit(0, 1): qubits[1]}
    )
    rots = [cirq.Y(qubits[0]) ** params[0], cirq.Y(qubits[1]) ** params[1]]
    return rots + list(mapped_circuit.all_operations())
def _get_op(code: Number) -> cirq.Gate:
    if code <= 4 / 3:
        return cirq.X ** 0.5
    elif code <= 2 * (4 / 3):
        return cirq.Y ** 0.5
    elif code <= 3 * (4 / 3):
        return cirq.PhasedXZGate(axis_phase_exponent=0.25, x_exponent=0.5, z_exponent=0)
    raise ValueError("Random codes must be between 0 and 4.")
def scrambling_block(
    qubits: List[cirq.Qid], params: List[Number]
) -> List[cirq.Operation]:
    a_op = _get_op(params[0])
    b_op = _get_op(params[1])
    return [a_op(qubits[0]), b_op(qubits[1]), cirq_google.SycamoreGate()(*qubits)]
def block_1d_circuit(
    qubits: List[cirq.Qid],
    depth: int,
    block_fn: Callable,
    random_source: List[List[Number]],
) -> cirq.Circuit:
    ops = []
    i_random = 0
    for t in range(depth):
        for i in range(0 if t % 2 == 0 else 1, len(qubits) - 1, 2):
            ops += block_fn([qubits[i], qubits[i + 1]], random_source[i_random])
            i_random += 1
    return cirq.Circuit(ops)
def bell_pair_block(qubits: List[cirq.Qid]) -> List[cirq.Operation]:
    mapped_circuit = _load_circuit("syc_bell_pair.json").transform_qubits(
        {cirq.GridQubit(0, 0): qubits[0], cirq.GridQubit(0, 1): qubits[1]}
    )
    return mapped_circuit.all_operations()
def un_bell_pair_block(qubits: List[cirq.Qid]) -> List[cirq.Operation]:
    mapped_circuit = _load_circuit("syc_un_bell_pair.json").transform_qubits(
        {cirq.GridQubit(0, 0): qubits[0], cirq.GridQubit(0, 1): qubits[1]}
    )
    return mapped_circuit.all_operations()
def swap_block(qubits: List[cirq.Qid]) -> List[cirq.Operation]:
    mapped_circuit = _load_circuit("syc_swap.json").transform_qubits(
        {cirq.GridQubit(0, 0): qubits[0], cirq.GridQubit(0, 1): qubits[1]}
    )
    return mapped_circuit.all_operations()
def inv_z_basis_gate(pauli: str) -> cirq.Gate:
    if pauli == "I" or pauli == "Z":
        return cirq.I
    if pauli == "X":
        return cirq.H
    if pauli == "Y":
        return cirq.PhasedXZGate(
            axis_phase_exponent=-0.5, x_exponent=0.5, z_exponent=-0.5
        )
    raise ValueError("Invalid Pauli.")
def create_randomized_sweeps(
    hidden_p: np.ndarray,
    symbols: Tuple[str],
    n_params: int,
    rand_state: np.random.RandomState,
) -> List[Dict[str, int]]:
    last_i = 0
    for i, pauli in enumerate(hidden_p):
        if pauli != "I":
            last_i = i
    sign_p = rand_state.choice([1, -1])
    all_sweeps = []
    for _ in range(n_params):
        current_sweep = dict()
        for twocopy in [0, 1]:
            parity = sign_p * rand_state.choice([1, -1], p=[0.95, 0.05])
            for i, pauli in enumerate(hidden_p):
                current_symbol = symbols[2 * i + twocopy]
                current_sweep[current_symbol] = rand_state.choice([0, 1])
                if pauli != "I":
                    if last_i == i:
                        v = 1 if parity == -1 else 0
                        current_sweep[current_symbol] = v
                    elif current_sweep[current_symbol] == 1:
                        parity *= -1
        all_sweeps.append(current_sweep)
    return all_sweeps

from typing import Dict, List, Optional
import cirq
import numpy as np
from openfermion import QubitOperator
def get_operator_from_tag(tag: Dict) -> QubitOperator:
    if tag['type'] == 'Z':
        assert len(tag['ham_ids']) == 1
        qop = QubitOperator('Z{}'.format(*tag['ham_ids']))
    elif tag['type'] == 'ZZ':
        assert len(tag['ham_ids']) == 2
        qop = QubitOperator('Z{} Z{}'.format(*tag['ham_ids']))
    elif tag['type'] == 'XXYYIZZI':
        assert len(tag['ham_ids']) == 2
        qop = (
            tag['sign'] * 0.5 * QubitOperator('X{} X{}'.format(*tag['ham_ids']))
            + tag['sign'] * 0.5 * QubitOperator('Y{} Y{}'.format(*tag['ham_ids']))
            + 0.5 * QubitOperator(f"Z{tag['ham_ids'][0]}")
            + 0.5 * QubitOperator(f"Z{tag['ham_ids'][1]}")
        )
    elif tag['type'] == 'XXYYZZII':
        assert len(tag['ham_ids']) == 2
        qop = (
            tag['sign'] * 0.5 * QubitOperator('X{} X{}'.format(*tag['ham_ids']))
            + tag['sign'] * 0.5 * QubitOperator('Y{} Y{}'.format(*tag['ham_ids']))
            + 0.5 * QubitOperator('Z{} Z{}'.format(*tag['ham_ids']))
            + 0.5 * QubitOperator()
        )
    else:
        raise TypeError('Didnt understand tag')
    return qop
def get_num_circuit_copies(tag: Dict, hamiltonian: QubitOperator, factor: float) -> int:
    operator = get_operator_from_tag(tag)
    term_sum = 0
    for term in operator.terms:
        if term in hamiltonian.terms:
            term_sum += hamiltonian.terms[term]
    return int(np.ceil(np.abs(term_sum) * factor))
def get_standard_qubit_set(
    num_qubits: int, q0: Optional[cirq.GridQubit] = None, direction: Optional[str] = 'R'
) -> List[cirq.GridQubit]:
    if q0 is None:
        q0 = cirq.GridQubit(0, 0)
    if direction == 'R':
        qubits = [q0 + (0, j) for j in range(num_qubits // 2)]
        qubits += [q0 + (1, j) for j in range(num_qubits // 2 - 1, -1, -1)]
    elif direction == 'L':
        qubits = [q0 + (0, -j) for j in range(num_qubits // 2)]
        qubits += [q0 + (-1, -j) for j in range(num_qubits // 2 - 1, -1, -1)]
    elif direction == 'D':
        qubits = [q0 + (j, 0) for j in range(num_qubits // 2)]
        qubits += [q0 + (j, -1) for j in range(num_qubits // 2 - 1, -1, -1)]
    elif direction == 'U':
        qubits = [q0 + (-j, 0) for j in range(num_qubits // 2)]
        qubits += [q0 + (-j, 1) for j in range(num_qubits // 2 - 1, -1, -1)]
    else:
        raise ValueError('I dont understand the given direction')
    return qubits
def get_all_standard_qubit_sets(
    num_qubits: int,
    all_qubits: List[cirq.GridQubit],
) -> List[List[cirq.GridQubit]]:
    all_ladders = []
    for q0 in all_qubits:
        for direction in ['R', 'L', 'U', "D"]:
            ladder_qubits = get_standard_qubit_set(num_qubits, q0, direction)
            if all([qubit in all_qubits for qubit in ladder_qubits]):
                all_ladders.append(ladder_qubits)
                all_ladders.append(list(reversed(ladder_qubits)))
    return all_ladders
def qubit_hamming_distance(q0: cirq.GridQubit, q1: cirq.GridQubit) -> int:
    return abs(q0.row - q1.row) + abs(q0.col - q1.col)
def check_if_sq_and_preserves_computational_basis(
    gate: cirq.Gate,
    tol: Optional[float]=1e-6
) -> bool:
    if len(gate.qubits) > 1:
        return False
    elif cirq.protocols.is_measurement(gate):
        return True
    elif isinstance(gate.gate, cirq.PhasedXZGate):
        if (gate.gate.x_exponent + tol) % 1 < 2 * tol:
            return True
        return False
    elif isinstance(gate.gate, cirq.ZPowGate):
        return True
    elif isinstance(gate.gate, (cirq.XPowGate, cirq.YPowGate)):
        if (gate.gate.exponent + tol) % 1 < 2 * tol:
            return True
        return False
    unitary = cirq.unitary(gate)
    if abs(unitary[0, 0]) < tol or abs(unitary[0, 1]) < tol:
        return True
    return False
def add_echoes(circuit: cirq.Circuit, check_1q_2q_form: Optional[bool] = True) -> cirq.Circuit:
    if check_1q_2q_form:
        check_separated_single_and_two_qubit_layers([circuit], strict=True)
    for qubit in circuit.all_qubits():
        last_moment_id = circuit.prev_moment_operating_on([qubit])
        while (
            check_if_sq_and_preserves_computational_basis(circuit[last_moment_id][qubit]) is True
            and last_moment_id is not None
        ):
            last_moment_id = circuit.prev_moment_operating_on(
                [qubit], end_moment_index=last_moment_id
            )
        if last_moment_id is None:
            break
        first_moment_id = circuit.next_moment_operating_on([qubit])
        while (
            check_if_sq_and_preserves_computational_basis(circuit[first_moment_id][qubit]) is True
            and first_moment_id is not None
        ):
            first_moment_id = circuit.next_moment_operating_on(
                [qubit], start_moment_index=first_moment_id + 1
            )
        if first_moment_id is None:
            raise ValueError('This shouldnt happen.')
        current_moment_id = first_moment_id
        while current_moment_id < last_moment_id:
            next_moment_id = circuit.next_moment_operating_on(
                [qubit], start_moment_index=current_moment_id + 1
            )
            if next_moment_id < current_moment_id + 4 - (current_moment_id % 2):
                current_moment_id = next_moment_id
                continue
            if current_moment_id % 2 == 0:
                current_moment_id += 1
            num_echoes = (next_moment_id - current_moment_id + 1) // 4
            for echo_id in range(num_echoes):
                echo_moment_1 = current_moment_id + echo_id * 4 + 1
                echo_moment_2 = current_moment_id + echo_id * 4 + 3
                assert echo_moment_1 < next_moment_id
                circuit[echo_moment_1] += [cirq.X(qubit)]
                try:
                    circuit[echo_moment_2] += [cirq.X(qubit)]
                except ValueError:
                    assert echo_id == num_echoes - 1
                    other_gate = circuit[echo_moment_2][qubit]
                    new_gate = merge_faster(cirq.X(qubit), other_gate)
                    circuit[echo_moment_2] -= other_gate
                    if new_gate is not None:
                        circuit[echo_moment_2] += new_gate
            current_moment_id = next_moment_id
    return circuit
def check_separated_single_and_two_qubit_layers(
    circuits: List[cirq.Circuit], strict: Optional[bool] = True
):
    for circuit_id, circuit in enumerate(circuits):
        for moment_id, moment in enumerate(circuit[:-1]):
            test_set = set([len(gate.qubits) for gate in moment])
            if len(test_set) > 1:
                raise TypeError(f'Circuit: {circuit_id}, moment: {moment_id} is mixed')
            if strict and (
                len(test_set) == 1 and (next(iter(test_set)) % 2 != (moment_id + 1) % 2)
            ):
                raise TypeError(f'Circuit: {circuit_id}, moment: {moment_id} off-position.')
def parallelize_circuits(*circuits: List[cirq.Circuit]) -> cirq.Circuit:
    len_new_circuit = max([len(circuit) for circuit in circuits])
    new_circuit = cirq.Circuit()
    for moment_id in range(len_new_circuit):
        new_moment = cirq.Moment()
        for circuit in circuits:
            if moment_id >= len(circuit):
                continue
            new_moment += circuit[moment_id]
        new_circuit.moments.append(new_moment)
    return new_circuit
def safe_tetris_circuits(circuit1: cirq.Circuit, circuit2: cirq.Circuit) -> cirq.Circuit:
    if len(circuit2) == 0:
        return circuit1[:]
    if len(circuit1) == 0:
        return circuit2[:]
    moment_to_tetris_to = circuit1.prev_moment_operating_on(circuit2.all_qubits())
    if moment_to_tetris_to is None:  # No overlap
        circuit = parallelize_circuits(circuit1, circuit2)
        return circuit
    moment_1r = circuit1[moment_to_tetris_to]
    moment_2l = circuit2[0]
    test_set_1r = set([len(gate.qubits) for gate in moment_1r])
    test_set_2l = set([len(gate.qubits) for gate in moment_2l])
    if len(test_set_1r) != 1:
        raise ValueError('Circuit 1 not in correct form, moments {}, {}'.format(
            moment_1r, moment_2l))
    if len(test_set_2l) != 1:
        raise ValueError('Circuit 2 not in correct form, moments {}, {}'.format(
            moment_1r, moment_2l))
    (gate_type_1r,) = test_set_1r
    (gate_type_2l,) = test_set_2l
    if gate_type_1r == 1:
        if gate_type_2l == 1:
            circuit = safe_concatenate_circuits(circuit1[: moment_to_tetris_to + 1], circuit2[0:1])
            circuit = safe_concatenate_circuits(
                circuit, parallelize_circuits(circuit1[moment_to_tetris_to + 1 :], circuit2[1:])
            )
        elif gate_type_2l == 2:
            circuit = safe_concatenate_circuits(
                circuit1[: moment_to_tetris_to + 1],
                parallelize_circuits([circuit2, circuit1[moment_to_tetris_to + 1 :]]),
            )
        else:
            raise ValueError(f'Dont understand gate_type_2l={gate_type_2l}')
    elif gate_type_1r == 2:
        moment_1l = circuit1[moment_to_tetris_to + 1]
        test_set_1l = set([len(gate.qubits) for gate in moment_1l])
        if len(test_set_1l) != 1:
            raise ValueError('Circuit 1 not in correct form, moments {}, {}, {}'.format(
                moment_1r, moment_1l, moment_2l))
        (gate_type_1l,) = test_set_1l
        if gate_type_1l == gate_type_2l:
            circuit = safe_concatenate_circuits(
                circuit1[: moment_to_tetris_to + 1],
                parallelize_circuits(circuit1[moment_to_tetris_to + 1 :], circuit2),
            )
        else:
            circuit = safe_concatenate_circuits(
                circuit1[: moment_to_tetris_to + 2],
                parallelize_circuits(circuit1[moment_to_tetris_to + 2 :], circuit2),
            )
    else:
        raise ValueError(f'Dont understand gate_type_1r={gate_type_1r}')
    return circuit
def safe_concatenate_circuits(circuit1: cirq.Circuit, circuit2: cirq.Circuit) -> cirq.Circuit:
    if len(circuit2) == 0:
        return circuit1[:]
    if len(circuit1) == 0:
        return circuit2[:]
    moment_1r = circuit1[-1]
    moment_2l = circuit2[0]
    test_set_1r = set([len(gate.qubits) for gate in moment_1r])
    test_set_2l = set([len(gate.qubits) for gate in moment_2l])
    if len(test_set_1r) != 1:
        raise ValueError('Circuit 1 not in correct form, moments {}, {}'.format(
            moment_1r, moment_2l))
    if len(test_set_2l) != 1:
        raise ValueError('Circuit 2 not in correct form, moments {}, {}'.format(
            moment_1r, moment_2l))
    (gate_type_1r,) = test_set_1r
    (gate_type_2l,) = test_set_2l
    if gate_type_1r == 1 and gate_type_2l == 1:
        new_middle_moment = cirq.Moment()
        for gate_1r in moment_1r:
            if gate_1r.qubits[0] in moment_2l.qubits:
                gate_2l = moment_2l[gate_1r.qubits[0]]
                new_gate = merge_faster(gate_1r, gate_2l)
                if new_gate is not None:
                    new_middle_moment += [new_gate]
            else:
                new_middle_moment += [gate_1r]
        for gate_2l in moment_2l:
            if gate_2l.qubits[0] not in moment_1r.qubits:
                new_middle_moment += [gate_2l]
        circuit = cirq.Circuit()
        circuit._moments = circuit1.moments[:-1]
        circuit._moments.append(new_middle_moment)
        circuit._moments += circuit2.moments[1:]
    else:
        circuit = cirq.Circuit()
        circuit._moments = circuit1.moments
        circuit._moments += circuit2.moments
    return circuit
def merge_faster(gate1: cirq.Gate, gate2: cirq.Gate, tol: Optional[float]=1e-6) -> cirq.Gate:
    if (
        isinstance(gate1.gate, cirq.PhasedXZGate)
        and isinstance(gate2.gate, cirq.PhasedXZGate)
        and abs(gate2.gate.x_exponent) < tol
    ):
        new_gate = cirq.PhasedXZGate(
            axis_phase_exponent=gate1.gate.axis_phase_exponent,
            x_exponent=gate1.gate.x_exponent,
            z_exponent=gate1.gate.z_exponent + gate2.gate.z_exponent,
        )
    else:
        new_unitary = cirq.unitary(gate2.gate) @ cirq.unitary(gate1.gate)
        new_gate = cirq.single_qubit_matrix_to_phxz(new_unitary)
        if new_gate is None:
            return None
    return new_gate.on(gate1.qubits[0])

import copy
from collections import defaultdict
from typing import cast, Dict, List, Optional, Set, Tuple
import cirq
import numpy as np
UNITARY_ATOL = 1e-8
def _gates_are_close(gate0: cirq.Gate, gate1: cirq.Gate) -> bool:
    if cirq.qid_shape(gate0) != cirq.qid_shape(gate1):
        return False
    return cirq.allclose_up_to_global_phase(
        cirq.unitary(gate0), cirq.unitary(gate1), atol=UNITARY_ATOL
    )
def _qubits_with_hadamard(moment: cirq.Moment) -> Set[cirq.Qid]:
    return {op.qubits[0] for op in moment if _gates_are_close(op.gate, cirq.H)}
def _has_measurement(moment: cirq.Moment) -> bool:
    return any(cirq.is_measurement(op) for op in moment)
def _has_2q_gates(moment: cirq.Moment) -> bool:
    return any(len(op.qubits) == 2 and cirq.has_unitary(op) for op in moment)
def _is_exclusively_1q_gates(moment: cirq.Moment) -> bool:
    return all(len(op.qubits) == 1 and cirq.has_unitary(op) for op in moment)
def _has_cnot(moment: cirq.Moment) -> bool:
    return any(_gates_are_close(op.gate, cirq.CNOT) for op in moment)
def _merge_hadamards(moment0: cirq.Moment, moment1: cirq.Moment) -> List[cirq.Moment]:
    double_hadamard_qubits = _qubits_with_hadamard(moment0) & _qubits_with_hadamard(
        moment1
    )
    moment0_merged_hadamards = moment0.without_operations_touching(
        double_hadamard_qubits
    )
    moment1_merged_hadamards = moment1.without_operations_touching(
        double_hadamard_qubits
    )
    if moment0_merged_hadamards.qubits & moment1_merged_hadamards.qubits:
        return [moment0_merged_hadamards, moment1_merged_hadamards]
    elif moment0_merged_hadamards.qubits | moment1_merged_hadamards.qubits:
        return [moment0_merged_hadamards + moment1_merged_hadamards]
    return []
def _break_up_cnots(
    moment: cirq.Moment,
) -> Tuple[cirq.Moment, cirq.Moment, cirq.Moment]:
    cnot_control_target_pairs: Set[Tuple[cirq.Qid, cirq.Qid]] = {
        cast(Tuple[cirq.Qid, cirq.Qid], op.qubits)
        for op in moment
        if _gates_are_close(op.gate, cirq.CNOT)
    }
    hadamards = cirq.Moment(cirq.H(pair[1]) for pair in cnot_control_target_pairs)
    ops_besides_cnot = [op for op in moment if not _gates_are_close(op.gate, cirq.CNOT)]
    czs = [cirq.CZ(*pair) for pair in cnot_control_target_pairs]
    moment_with_czs_instead = cirq.Moment(ops_besides_cnot + czs)
    return hadamards, moment_with_czs_instead, hadamards
def _combine_1q_cliffords(*gates: cirq.Gate) -> cirq.Gate:
    unitary = np.asarray(cirq.linalg.dot(*(cirq.unitary(gate) for gate in gates[::-1])))
    clifford = cirq.SingleQubitCliffordGate.from_unitary(unitary)
    clifford_to_friendly_rep: Dict[cirq.SingleQubitCliffordGate, cirq.Gate] = {
        cirq.SingleQubitCliffordGate.I: cirq.I,
        cirq.SingleQubitCliffordGate.H: cirq.H,
        cirq.SingleQubitCliffordGate.X: cirq.X,
        cirq.SingleQubitCliffordGate.Y: cirq.Y,
        cirq.SingleQubitCliffordGate.Z: cirq.Z,
        cirq.SingleQubitCliffordGate.X_sqrt: cirq.X**0.5,
        cirq.SingleQubitCliffordGate.Y_sqrt: cirq.Y**0.5,
        cirq.SingleQubitCliffordGate.Z_sqrt: cirq.S,
        cirq.SingleQubitCliffordGate.X_nsqrt: cirq.X**-0.5,
        cirq.SingleQubitCliffordGate.Y_nsqrt: cirq.Y**-0.5,
        cirq.SingleQubitCliffordGate.Z_nsqrt: cirq.S**-1,
    }
    return clifford_to_friendly_rep.get(clifford, clifford)
def convert_cnot_moments_to_cz_and_simplify_hadamards(
    circuit: cirq.Circuit,
) -> cirq.Circuit:
    moment_on_deck = cirq.Moment()
    new_circuit = cirq.Circuit()
    for moment in circuit:
        if _has_2q_gates(moment):
            hadamard0, cz, hadamard1 = _break_up_cnots(moment)
            new_circuit += _merge_hadamards(moment_on_deck, hadamard0)
            new_circuit += cz
            moment_on_deck = hadamard1
        elif _is_exclusively_1q_gates(moment):
            merge_moments = _merge_hadamards(moment_on_deck, moment)
            if len(merge_moments) > 1:
                new_circuit += merge_moments[0]
            moment_on_deck = merge_moments[-1] or cirq.Moment()
        else:
            if moment_on_deck:
                new_circuit += moment_on_deck
                moment_on_deck = cirq.Moment()
            new_circuit += moment
    if moment_on_deck:
        new_circuit += moment_on_deck
    return new_circuit
def defer_single_qubit_gates(circuit: cirq.Circuit) -> cirq.Circuit:
    new_circuit = copy.deepcopy(circuit)
    exclusively_1q_moments: List[int] = []
    deferrable_qubits = set(new_circuit.all_qubits())
    qubit_to_deferred_ops: Dict[cirq.Qid, List[cirq.Operation]] = defaultdict(list)
    def resolve_qubit(q: cirq.Qid) -> None:
        for idx, op in enumerate(reversed(qubit_to_deferred_ops[q])):
            insert_idx = (
                exclusively_1q_moments[-1 - idx] + 1
            )  # insert acts just before this index
            new_circuit.insert(insert_idx, op, strategy=cirq.InsertStrategy.INLINE)
        del qubit_to_deferred_ops[q]
    for idx, moment in enumerate(new_circuit):
        if _is_exclusively_1q_gates(moment):
            exclusively_1q_moments.append(idx)
            for op in moment:
                qubit = op.qubits[0]
                if qubit in deferrable_qubits:
                    qubit_to_deferred_ops[qubit].append(op)
            new_circuit[idx] = moment.without_operations_touching(deferrable_qubits)
        else:
            qubits_to_resolve_now = set(
                moment.qubits
            )  # Can't defer further if in this moment
            deferrable_qubits -= qubits_to_resolve_now
            for q in qubits_to_resolve_now:
                resolve_qubit(q)
    for q in list(qubit_to_deferred_ops):
        resolve_qubit(q)
    new_circuit = cirq.Circuit(m for m in new_circuit.moments if m)
    return new_circuit
def propagate_inserted_paulis(
    circuit: cirq.Circuit, *, inserted_pauli_tag: str
) -> Tuple[cirq.Circuit, cirq.PauliString]:
    pauli_frame: cirq.PauliString[cirq.Qid] = cirq.PauliString()
    modified_circuit = cirq.Circuit()
    for old_moment in circuit:
        new_moment_ops = []
        for op in old_moment:
            new_op = op
            if inserted_pauli_tag in op.tags:
                pauli_frame *= op
                new_op = op.untagged
                if len(op.tags) > 1:
                    new_tags = (tag for tag in op.tags if tag != inserted_pauli_tag)
                    new_op = new_op.with_tags(*new_tags)
            elif isinstance(op.gate, cirq.MeasurementGate):
                gate = op.gate
                inverted_qubits = {
                    q for q in op.qubits if pauli_frame.get(q) in (cirq.X, cirq.Y)
                }
                if inverted_qubits:
                    new_gate = gate.with_bits_flipped(
                        *(i for i, q in enumerate(op.qubits) if q in inverted_qubits)
                    )
                    new_op = new_gate.on(*op.qubits)
            elif isinstance(op.gate, cirq.ResetChannel):
                pauli_frame *= pauli_frame.get(op.qubits[0], cirq.I).on(op.qubits[0])
            else:
                try:
                    pauli_frame = pauli_frame.pass_operations_over(
                        [op], after_to_before=True
                    )
                except TypeError as ex:
                    raise NotImplementedError(
                        f"Don't know how to handle {op!r}."
                    ) from ex
            new_moment_ops.append(new_op)
        modified_circuit.append(cirq.Moment(new_moment_ops))
    return modified_circuit, pauli_frame / pauli_frame.coefficient
def insert_echos_on_idle_qubits(
    circuit: cirq.Circuit, echo: cirq.Pauli = cirq.X, resolve_to_hadamard: bool = False
) -> cirq.Circuit:
    if not isinstance(echo, cirq.Pauli):
        raise ValueError(f"{echo=} invalid: not a Pauli gate")
    new_circuit = copy.deepcopy(circuit)
    final_1q_moment: Optional[int] = None
    for idx, moment in enumerate(new_circuit):
        if _is_exclusively_1q_gates(moment):
            final_1q_moment = idx
        elif _has_measurement(moment):
            break
    if final_1q_moment is None:  # We only want to change exclusively-1q moments
        return new_circuit
    tag = "insert_echos_on_idle_qubits"
    new_circuit = copy.deepcopy(circuit)
    idle_qubits: Set[cirq.Qid] = set()
    for idx, moment in enumerate(new_circuit[:final_1q_moment]):
        if _is_exclusively_1q_gates(moment):  # Add echos
            for q in idle_qubits - moment.qubits:
                new_circuit.insert(
                    idx + 1, echo(q).with_tags(tag), strategy=cirq.InsertStrategy.INLINE
                )
        idle_qubits |= moment.qubits  # Eligible for subsequent echos
    untagged_partial_circuit, pauli_frame = propagate_inserted_paulis(
        new_circuit[:final_1q_moment], inserted_pauli_tag=tag
    )
    new_circuit[:final_1q_moment] = untagged_partial_circuit
    uncorrected_moment = new_circuit[final_1q_moment]
    combined_moment = cirq.Moment()
    relevant_qubits = uncorrected_moment.qubits | set(pauli_frame.qubits)
    for q in relevant_qubits:
        pauli = pauli_frame.get(q, cirq.I)
        op = uncorrected_moment.operation_at(q) or cirq.I(q)
        combined_moment += _combine_1q_cliffords(pauli, op.gate).on(q)
    if resolve_to_hadamard:  # Split into up to 3 moments ~ -Z--H--Z-
        resolved_combined_circuit = resolve_moment_to_hadamard(combined_moment)
        before = new_circuit[:final_1q_moment]
        after = new_circuit[final_1q_moment + 1 :]
        new_circuit = before + resolved_combined_circuit + after
    else:
        new_circuit[final_1q_moment] = combined_moment
    return new_circuit
def resolve_moment_to_hadamard(moment: cirq.Moment) -> cirq.Circuit:
    new_ops: List[List[cirq.Operation]] = [[], [], []]
    for op in moment:
        replacements = resolve_gate_to_hadamard(op.gate)
        for idx, gate in enumerate(replacements):
            if gate != cirq.I:
                new_ops[idx].append(gate.on(op.qubits[0]))
    return cirq.Circuit(cirq.Moment(*ops) for ops in new_ops if ops)
def resolve_gate_to_hadamard(gate: cirq.Gate) -> Tuple[cirq.Gate, cirq.Gate, cirq.Gate]:
    xz_gate = cirq.PhasedXZGate.from_matrix(cirq.unitary(gate))
    if not np.isclose(abs(xz_gate.x_exponent), 0.5):
        return cirq.I, gate, cirq.I
    if np.isclose(float(xz_gate.x_exponent), 0.5):
        xz_gate = cirq.PhasedXZGate(
            x_exponent=-0.5,
            z_exponent=xz_gate.z_exponent,
            axis_phase_exponent=xz_gate.axis_phase_exponent + 1,
        )
    z_exp_before = 0.5 - xz_gate.axis_phase_exponent
    z_exp_after = xz_gate.axis_phase_exponent + xz_gate.z_exponent - 1.5
    gate_before = _combine_1q_cliffords(cirq.Z**z_exp_before)
    gate_after = _combine_1q_cliffords(cirq.Z**z_exp_after)
    return gate_before, cirq.H, gate_after

from typing import Iterator, List, Set, Tuple
import cirq
import numpy as np
def q_displaced(qubit: cirq.GridQubit, displacement: np.ndarray) -> cirq.GridQubit:
    return qubit + (int(round(displacement[0])), int(round(displacement[1])))
class ToricCodeRectangle:
    def __init__(
        self,
        origin_qubit: cirq.GridQubit,
        row_vector: Tuple[int, int],
        rows: int,
        cols: int,
    ):
        if np.any(np.abs(row_vector) != np.array([1, 1])):
            raise ValueError(f"Illegal row_vector={row_vector}: must be (±1, ±1)")
        if rows < 1 or cols < 1:
            raise ValueError(f"rows ({rows}) and cols ({cols}) must both be at least 1")
        self.origin_qubit = origin_qubit
        self.row_vector = np.array(row_vector, dtype=int)
        self.col_vector = np.array((-row_vector[1], row_vector[0]), dtype=int)
        self.rows = rows
        self.cols = cols
        self.qubits_reading_order = self._qubits_reading_order()
    def __repr__(self) -> str:
        return (
            f"ToricCodeRectangle(origin_qubit=cirq.GridQubit{self.origin_qubit}, "
            f"row_vector={tuple(self.row_vector)}, rows={self.rows}, cols={self.cols})"
        )
    @property
    def captain_qubits(self) -> Set[cirq.GridQubit]:
        return {
            self.x_plaquette_to_captain(row, col)
            for row, col in self.x_plaquette_indices()
        }
    @property
    def qubits(self) -> Set[cirq.GridQubit]:
        return {
            qubit
            for row, col in self.x_plaquette_indices()
            for qubit in self.x_plaquette_to_qubits(row, col)
        }
    def _qubits_reading_order(self) -> Tuple[cirq.GridQubit, ...]:
        qubits: List[cirq.GridQubit] = []
        for row in range(self.rows):
            for col in range(self.cols):
                qubits.append(self.x_plaquette_to_captain(row, col))
            for col in range(self.cols + 1):
                captain = self.x_plaquette_to_captain(row, col)
                qubits.append(self.q_lower_left(captain))
        for col in range(self.cols):
            qubits.append(self.x_plaquette_to_captain(self.rows, col))
        return tuple(qubits)
    def x_plaquette_indices(self) -> Iterator[Tuple[int, int]]:
        for row in range(self.rows):
            for col in range(self.cols):
                yield row, col
    def z_plaquette_indices(self) -> Iterator[Tuple[int, int]]:
        for row in range(self.rows + 1):
            for col in range(self.cols + 1):
                yield row, col
    def is_corner(self, row: int, col: int) -> bool:
        return (row, col) in {
            (0, 0),
            (0, self.cols),
            (self.rows, 0),
            (self.rows, self.cols),
        }
    def is_edge(self, row: int, col: int) -> bool:
        if self.is_corner(row, col):
            return False
        return row == 0 or row == self.rows or col == 0 or col == self.cols
    def is_boundary(self, row: int, col: int) -> bool:
        return self.is_corner(row, col) or self.is_edge(row, col)
    def x_plaquette_to_captain(self, row: int, col: int) -> cirq.GridQubit:
        displacement = row * self.row_vector + col * self.col_vector
        return q_displaced(self.origin_qubit, displacement)
    def x_plaquette_to_qubits(self, row: int, col: int) -> Set[cirq.GridQubit]:
        captain = self.x_plaquette_to_captain(row, col)
        return {
            captain,
            self.q_lower_left(captain),
            self.q_lower_right(captain),
            self.q_down(captain),
        }
    def z_plaquette_to_qubits(self, row: int, col: int) -> Set[cirq.GridQubit]:
        right_qubit = self.x_plaquette_to_captain(row, col)
        possible_qubits = {
            right_qubit,
            self.q_upper_left(right_qubit),
            self.q_across_left(right_qubit),
            self.q_lower_left(right_qubit),
        }
        return possible_qubits & self.qubits
    def x_plaquette_to_qubit_idxs(self, row: int, col: int) -> Set[int]:
        plaquette_qubits = self.x_plaquette_to_qubits(row, col)
        all_qubits = sorted(self.qubits)
        return {all_qubits.index(q) for q in plaquette_qubits}
    def z_plaquette_to_qubit_idxs(self, row: int, col: int) -> Set[int]:
        plaquette_qubits = self.z_plaquette_to_qubits(row, col)
        all_qubits = sorted(self.qubits)
        return {all_qubits.index(q) for q in plaquette_qubits}
    def captain_to_x_plaquette(self, captain_qubit: cirq.GridQubit) -> Tuple[int, int]:
        dr_grid = captain_qubit.row - self.origin_qubit.row
        dc_grid = captain_qubit.col - self.origin_qubit.col
        c0, c1 = self.col_vector
        r0, r1 = self.row_vector
        plaq_row = (c0 * dc_grid - c1 * dr_grid) / (c0 * r1 - c1 * r0)
        plaq_col = (r1 * dr_grid - r0 * dc_grid) / (c0 * r1 - c1 * r0)
        plaq_vector = np.array((plaq_row, plaq_col))
        if not np.allclose(plaq_vector, np.round(plaq_vector)):
            raise ValueError(
                f'{captain_qubit} is not a valid "captain" qubit for '
                f"origin {self.origin_qubit}, row_vector {self.row_vector}."
            )
        return int(round(plaq_row)), int(round(plaq_col))
    def q_lower_left(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        return q_displaced(captain_qubit, (self.row_vector - self.col_vector) / 2)
    def q_lower_right(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        return q_displaced(captain_qubit, (self.row_vector + self.col_vector) / 2)
    def q_down(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        return q_displaced(captain_qubit, self.row_vector)
    def q_upper_left(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        return q_displaced(captain_qubit, (-self.row_vector - self.col_vector) / 2)
    def q_across_left(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        return q_displaced(captain_qubit, -self.col_vector)
    def q_lower_outside(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        _row, col = self.captain_to_x_plaquette(captain_qubit)
        if col < self.cols // 2:
            return self.q_lower_left(captain_qubit)
        return self.q_lower_right(captain_qubit)
    def q_lower_inside(self, captain_qubit: cirq.GridQubit) -> cirq.GridQubit:
        _row, col = self.captain_to_x_plaquette(captain_qubit)
        if col < self.cols // 2:
            return self.q_lower_right(captain_qubit)
        return self.q_lower_left(captain_qubit)

from __future__ import annotations
from typing import Iterator, List, Set
import cirq
from . import toric_code_rectangle as tcr
def toric_code_cnot_circuit(
    code: tcr.ToricCodeRectangle, x_basis: bool = False
) -> cirq.Circuit:
    circuit = cirq.Circuit(cirq.H(q) for q in code.captain_qubits)
    cnot_moments: List[List[cirq.Operation]] = [[]]
    for idx, cols in enumerate(_middle_out_column_groups(code)):
        cnot_moments.extend([[], []])
        for col in cols:
            for row in range(code.rows):
                captain = code.x_plaquette_to_captain(row, col)
                if idx == 0:  # Center columns: left, right, down
                    q0 = code.q_lower_left(captain)
                    q1 = code.q_lower_right(captain)
                else:  # Outer columns: outside, inside, down
                    q0 = code.q_lower_outside(captain)
                    q1 = code.q_lower_inside(captain)
                q2 = code.q_down(captain)
                cnot_moments[-3].append(cirq.CNOT(captain, q0))
                cnot_moments[-2].append(cirq.CNOT(captain, q1))
                cnot_moments[-1].append(cirq.CNOT(code.q_lower_outside(captain), q2))
    circuit += (cirq.Moment(ops) for ops in cnot_moments)
    if x_basis:
        circuit += cirq.Moment(cirq.H(q) for q in code.qubits)
    return circuit
def _middle_out_column_groups(code: tcr.ToricCodeRectangle) -> Iterator[Set[int]]:
    cols = code.cols
    if cols % 2 == 0:
        center_cols = {cols // 2 - 1, cols // 2}
    else:
        center_cols = {cols // 2}
    yield center_cols
    for right_col in range(cols // 2 + 1, cols):
        left_col = cols - right_col - 1
        yield {left_col, right_col}

from typing import Iterable, List, Sequence, Tuple
import cirq
import numpy as np
from recirq.third_party.quaff import indexing, linalg, random
class BasisChangeGate(cirq.Gate):
    def __init__(self, matrix: np.ndarray):
        self.matrix = np.copy(matrix)
    def num_qubits(self):
        return len(self.matrix)
    def _unitary_(self):
        N = 2 ** self.num_qubits()
        bitstrings = indexing.get_all_bitstrings(self.num_qubits())
        LHS = np.tensordot(
            bitstrings, np.ones(N, dtype=linalg.DTYPE), axes=0
        ).transpose((0, 2, 1))
        RHS = np.tensordot(
            (bitstrings @ self.matrix.T) % 2, np.ones(N, dtype=linalg.DTYPE), axes=0
        ).transpose((2, 0, 1))
        return (LHS == RHS).all(axis=-1)
    @classmethod
    def random(cls, num_qubits, seed=None):
        rng = np.random.default_rng(seed)
        matrix = random.random_invertible_matrix(num_qubits, seed=rng)
        return cls(matrix)
    def __pow__(self, exponent) -> "BasisChangeGate":
        if not np.issubdtype(type(exponent), np.integer):
            raise ValueError("Exponent must be an integer.")
        if exponent < 0:
            return self.inverse() ** (-exponent)
        return type(self)(np.linalg.matrix_power(self.matrix, exponent) % 2)
    def inverse(self) -> "BasisChangeGate":
        return type(self)(linalg.get_inverse(self.matrix))
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            raise TypeError
        return np.array_equal(self.matrix % 2, other.matrix % 2)
    def __str__(self):
        return "BasisChangeGate([{}])".format(
            ",".join(
                "[{}]".format(",".join(str(e) for e in row)) for row in self.matrix
            )
        )
    @classmethod
    def from_unitary(cls, unitary: np.ndarray):
        if not np.isreal(unitary).all():
            raise ValueError("Unitary not real.")
        unitary = np.real(unitary)
        N = len(unitary)
        n = indexing.log2(N)
        bitstrings = indexing.get_all_bitstrings(n)
        masks = (1 << np.arange(n))[::-1]
        matrix = np.zeros((n, n), dtype=linalg.DTYPE)
        for i, mask in enumerate(masks):
            matrix[:, i] = unitary[:, mask] @ bitstrings
        return cls(matrix)
    def expand(self, new_num_qubits: int, indices: np.ndarray) -> "BasisChangeGate":
        indices = np.array(tuple(indices))
        matrix = np.zeros((new_num_qubits,) * 2, dtype=linalg.DTYPE)
        matrix[np.ix_(indices, indices)] = self.matrix
        new_indices = np.array(
            sorted(set(range(new_num_qubits)) - set(indices)), dtype=linalg.DTYPE
        )
        num_new_indices = new_num_qubits - self.num_qubits()
        matrix[np.ix_(new_indices, new_indices)] = np.eye(num_new_indices)
        return type(self)(matrix)
    def copy(self):
        return type(self)(np.copy(self.matrix))
    @classmethod
    def from_gate(cls, gate: cirq.Gate):
        if gate == cirq.CNOT:
            return cls([[1, 0], [1, 1]])
        raise NotImplementedError
    def __matmul__(self, other: "BasisChangeGate") -> "BasisChangeGate":
        if not isinstance(other, type(self)):
            raise TypeError("Can only matmul by an instance of BasisChangeGate")
        if self.num_qubits() != other.num_qubits():
            raise ValueError(
                "Can only matmal basis change gates with the same number of qubits."
            )
        return type(self)((self.matrix @ other.matrix) % 2)
    def _decompose_(self, qubits):
        if self.num_qubits() <= 2:
            return None
        clearing_network, nw_tri_matrix = get_clearing_network(self.matrix, qubits)
        reversal_network = list(get_reversal_network(nw_tri_matrix, qubits))
        yield cirq.inverse(reversal_network)
        yield cirq.inverse(clearing_network)
    @classmethod
    def identity(cls, num_qubits: int) -> "BasisChangeGate":
        return cls(np.eye(num_qubits, dtype=linalg.DTYPE))
def get_clearing_network(
    matrix: np.ndarray, qubits: Sequence[cirq.Qid], include_output_matrix: bool = False
) -> Tuple[List[cirq.Operation], np.ndarray]:
    n = len(matrix)
    values = np.copy(matrix)
    V = linalg.get_lexicographic_basis(matrix)
    pi = tuple(np.argmax(np.flip(V, 1), 1))
    W = np.empty_like(matrix)
    for i in range(n):
        W[pi[i]] = V[i]
    assert linalg.is_nw_tri(W)
    labels = np.array(pi)
    ops = []
    for layer in range(n):
        for i in range(layer % 2, n - 1, 2):
            j, k = labels[i : i + 2]
            if j < k:
                continue
            labels[i : i + 2] = k, j
            u, v = values[i : i + 2]
            W_minor = np.vstack((W[:k], W[k + 1 :]))
            for a, b in [(0, 1), (1, 1), (1, 0)]:
                rhs = (a * u + b * v) % 2
                solution = linalg.get_coordinates(rhs, W_minor)
                if solution is not None:
                    assert np.array_equal(linalg.dot(solution, W_minor), rhs)
                    break
            solution = np.insert(solution, k, 0)
            assert np.array_equal(linalg.dot(solution, W), rhs)
            if (a, b) == (1, 0):
                values[i] = (u + v) % 2
            values[i + 1] = rhs
            op = BasisChangeGate(np.array([[1, a * (1 - b)], [a, b]]))(
                *qubits[i : i + 2]
            )
            ops.append(op)
    assert np.array_equal(labels, np.arange(n))
    assert linalg.is_nw_tri(values)
    return ops, values
def get_reversal_network(
    matrix: np.ndarray, qubits: Sequence[cirq.Qid]
) -> Iterable[cirq.Operation]:
    n = len(matrix)
    labels = np.arange(n)[::-1]
    values = np.copy(matrix)
    for layer in range(n):
        for i in range(layer % 2, n - 1, 2):
            gate_matrix = np.array([[0, 1], [1, 0]], dtype=linalg.DTYPE)
            if values[i][labels[i + 1]]:
                values[i] = (values[i] + values[i + 1]) % 2
                gate_matrix[1, 1] = 1
            values[i : i + 2] = values[i : i + 2][::-1]
            labels[i : i + 2] = labels[i : i + 2][::-1]
            yield BasisChangeGate(gate_matrix)(*qubits[i : i + 2])

import collections
import itertools
from typing import Iterable, Tuple, cast
import cirq
import numpy as np
from recirq.third_party.quaff import basis_change, gates, indexing, linalg
def get_index_range(num_qubits: int, num_steps: int, i: int):
    num_steps %= 2 * (num_qubits + 1)
    if num_steps == 0:
        return i, i
    if num_steps == num_qubits + 1:
        return (num_qubits - 1 - i,) * 2
    if num_steps > num_qubits + 1:
        raise NotImplementedError
    min_index = i - num_steps + ((i + num_steps) % 2)
    if i < num_steps - 1:
        min_index = -1 - min_index
    min_index %= num_qubits
    max_index = num_steps + i - 1 + ((i + 1 + num_steps) % 2)
    if max_index >= num_qubits:
        max_index = -1 - max_index
    max_index %= num_qubits
    return min_index, max_index
class CZLayerBasisChangeStageGate(cirq.Gate):
    def __init__(self, num_qubits: int, num_steps: int = 2):
        self.num_steps = int(num_steps)
        self._num_qubits = num_qubits
    def num_qubits(self):
        return self._num_qubits
    @property
    def basis_change_matrix(self):
        return self.get_basis_change_matrix(self._num_qubits, self.num_steps)
    @staticmethod
    def get_basis_change_matrix(num_qubits: int, num_steps: int = 2):
        matrix = np.zeros((num_qubits,) * 2, dtype=linalg.DTYPE)
        for i in range(num_qubits):
            min_index, max_index = get_index_range(num_qubits, num_steps, i)
            matrix[i, np.arange(min_index, max_index + 1)] = 1
        return matrix
    def as_basis_change_gate(self):
        return basis_change.BasisChangeGate(self.basis_change_matrix)
    def _decompose_(self, qubits):
        n = self.num_qubits()
        for s in range(self.num_steps):
            if not (s % 2):
                for i in range(0, n - 1, 2):
                    yield cirq.CNOT(qubits[i], qubits[i + 1])
                for i in range(1, n - 1, 2):
                    yield cirq.CNOT(qubits[i + 1], qubits[i])
            else:
                for i in range(0, n - 1, 2):
                    yield cirq.CNOT(qubits[i + 1], qubits[i])
                for i in range(1, n - 1, 2):
                    yield cirq.CNOT(qubits[i], qubits[i + 1])
    def _unitary_(self):
        return self.as_basis_change_gate()._unitary_()
    def __str__(self):
        return f"{type(self).__name__}({self._num_qubits}, {self.num_steps})"
class CZLayerGate(cirq.Gate):
    def __init__(
        self,
        num_qubits: int,
        pairs: Iterable[Tuple[int, int]],
        include_first_stage: bool = True,
        include_final_stage: bool = True,
    ):
        counter = collections.Counter(tuple(sorted(pair)) for pair in pairs)
        pairs = tuple(
            cast(Tuple[int, int], pair) for pair in sorted(counter) if counter[pair] % 2
        )
        for pair in pairs:
            if len(set(pair)) != 2:
                raise ValueError(
                    f"Pair {pair} is does not contain exactly two distinct elements."
                )
            for i in pair:
                if not (0 <= i < num_qubits):
                    raise ValueError(f"Index {i} out of range [0, {num_qubits}).")
        self._num_qubits = num_qubits
        self.pairs = pairs
        if not (include_first_stage or include_final_stage):
            raise ValueError(
                "At most one of the first and final stages can be omitted."
            )
        if not (include_first_stage and include_final_stage):
            raise NotImplementedError
        self.includes_first_stage = bool(include_first_stage)
        self.includes_final_stage = bool(include_final_stage)
    def __str__(self):
        pair_str = ";".join(",".join(str(i) for i in pair) for pair in self.pairs)
        return f"CZs({pair_str})"
    def num_qubits(self):
        return self._num_qubits
    def _unitary_(self):
        n = self.num_qubits()
        basis = indexing.get_all_bitstrings(n)
        parity = np.zeros(2**n, dtype=linalg.DTYPE)
        for pair in self.pairs:
            parity += (basis[:, pair] == 1).all(axis=1)
        U = np.diag((-1) ** parity)
        axes = np.concatenate((np.arange(n)[::-1], np.arange(n, 2 * n)))
        return np.transpose(U.reshape((2,) * 2 * n), axes).reshape((2**n,) * 2)
    @property
    def phase_poly(self):
        return self.get_phase_poly(self.num_qubits(), self.pairs)
    @staticmethod
    def get_phase_poly(num_qubits, pairs):
        phase_poly = np.zeros((num_qubits,) * 2, dtype=linalg.DTYPE)
        for pair in pairs:
            i, j = sorted(pair)
            assert i < j
            phase_poly[i, i] += 1
            phase_poly[j, j] += 1
            if j == i + 1:
                phase_poly[i, j] -= 1
                continue
            assert i + 1 <= j - 1
            phase_poly[i, i] += 1
            phase_poly[j, j] += 1
            for a, b in itertools.product((i, i + 1), (j - 1, j)):
                phase_poly[a, b] += 1
        return phase_poly % 4
    def _get_phases(self):
        n = self.num_qubits()
        phase_poly = self.phase_poly
        quadratic = np.zeros((n // 2, n), dtype=linalg.DTYPE)
        for s in range(n // 2):
            for r in range(n):
                i, j = get_index_range(n, 2 * (s + 1), r)
                if i == j:
                    continue
                quadratic[s, r] = (phase_poly[i, j] + phase_poly[j, i]) % 4
        return np.diag(phase_poly), quadratic
    def _decompose_(self, qubits):
        n = self.num_qubits()
        basis_change_gate = CZLayerBasisChangeStageGate(n, 2)
        linear, quadratic = self._get_phases()
        single_qubit_phase_layer = gates.SingleQubitLayerGate(
            cirq.S**u if u else cirq.I for u in linear
        )(*qubits)
        yield single_qubit_phase_layer
        for s in range(n // 2):
            yield basis_change_gate(*qubits)
            for q, u in zip(qubits, quadratic[s]):
                if u:
                    yield (cirq.S**u)(q)
        if self.includes_final_stage:
            yield CZLayerBasisChangeStageGate(n, 1 + (n % 2))(*qubits)

from typing import Optional, cast
from cirq.protocols.json_serialization import ObjectFactory
from recirq.third_party import quaff
def json_resolver(quaff_type: str) -> Optional[ObjectFactory]:
    if quaff_type.startswith("quaff."):
        return cast(
            ObjectFactory,
            getattr(quaff, quaff_type[6:])
        )
    return None

import cirq
DEFAULT_RESOLVERS = list(cirq.DEFAULT_RESOLVERS)
def _internal_register_resolver(resolver: cirq.JsonResolver):
    DEFAULT_RESOLVERS.append(resolver)
def read_json(*args, **kwargs):
    kwargs["resolvers"] = DEFAULT_RESOLVERS
    return cirq.read_json(*args, **kwargs)
