from typing import Any, Tuple
import cirq
import numpy as np
from recirq.third_party.quaff import linalg
def assert_consistent_unitary_round_trip(num_qubits, gate_type, seed):
    gate = gate_type.random(num_qubits, seed=seed)
    U = gate._unitary_()
    assert np.allclose(U @ U.T.conjugate(), np.eye(len(U)))
    reconstructed_gate = gate_type.from_unitary(U)
    reconstructed_U = reconstructed_gate._unitary_()
    assert np.allclose(reconstructed_U @ reconstructed_U.T.conjugate(), np.eye(len(U)))
    assert np.allclose(U, reconstructed_U)
def assert_equivalent_repr(value: Any):
    print("VALUE")
    print(value, type(value))
    return cirq.testing.assert_equivalent_repr(value)
def is_boolean_tuple_of_len(obj: Any, n: int):
    return len(obj) == n and all(0 <= x < 2 for x in obj)
def is_nested_boolean_tuples_of_shape(obj: Any, shape: Tuple[int, ...]):
    array = np.array(obj, dtype=linalg.DTYPE)
    if not is_boolean_array_of_shape(array, shape):
        return False
    return linalg.tuplify(array) == obj
def is_boolean_array_of_shape(obj: Any, shape: Tuple[int, ...]):
    if not isinstance(obj, np.ndarray):
        return False
    if obj.shape != shape:
        return False
    if obj.dtype != linalg.DTYPE:
        return False
    if (obj < 0).any():
        return False
    if (obj > 1).any():
        return False
    return True
def complex_formatter(val) -> str:
    if np.isclose(val, 0):
        return "  0"
    formatted = ""
    for part, suffix in zip((val.real, val.imag), ("", "j")):
        if np.isclose(part, 0):
            continue
        if np.isclose(part, round(part)):
            part = round(part)
        sign = "+" if part > 0 else "-"
        formatted += (sign + str(abs(part)) + suffix).rjust(3)
    if formatted[0] == "+":
        return " " + formatted[1:]
    return formatted

import dataclasses
import itertools
from dataclasses import dataclass
from typing import Optional, Tuple, cast
import cirq
import numpy as np
from recirq.third_party.quaff import linalg, sampling, testing
from recirq.third_party.quaff.gates.hadamard_free import HadamardFreeGate
from recirq.third_party.quaff.gates.single_qubit_layer import SingleQubitLayerGate
def _recover_permutation(matrix: np.ndarray) -> Optional[np.ndarray]:
    n = len(matrix)
    S_inv = n - 1 - np.argmax(np.flip(matrix, 1), 1)
    if not np.array_equal(sorted(S_inv), range(n)):
        return None
    return linalg.invert_permutation(S_inv)
@dataclass
class FHFGate(cirq.Gate):
    num_qubits: dataclasses.InitVar[int]
    _num_qubits: int = dataclasses.field(init=False)
    F1: HadamardFreeGate = dataclasses.field(init=False)
    H: np.ndarray = dataclasses.field(init=False)
    F2: HadamardFreeGate = dataclasses.field(init=False)
    first_H_free_gate: dataclasses.InitVar[HadamardFreeGate] = None
    hadamards: dataclasses.InitVar[np.ndarray] = None
    second_H_free_gate: dataclasses.InitVar[np.ndarray] = None
    def __post_init__(
        self, num_qubits, first_H_free_gate, hadamards, second_H_free_gate
    ):
        self._num_qubits = num_qubits
        if first_H_free_gate is None:
            self.F1 = HadamardFreeGate(num_qubits)
        else:
            self.F1 = first_H_free_gate
        if hadamards is None:
            self.H = np.zeros(num_qubits, dtype=linalg.DTYPE)
        else:
            self.H = np.array(hadamards, dtype=linalg.DTYPE)
        if second_H_free_gate is None:
            self.F2 = HadamardFreeGate(num_qubits)
        else:
            self.F2 = second_H_free_gate
    @classmethod
    def _from_json_dict_(cls, _num_qubits, F1, H, F2, **kwargs):
        return cls(
            num_qubits=_num_qubits,
            first_H_free_gate=F1,
            hadamards=H,
            second_H_free_gate=F2,
        )
    def _json_dict_(self):
        print(cirq.dataclass_json_dict(self))
        return cirq.dataclass_json_dict(self)
    @classmethod
    def _json_namespace_(cls):
        return "quaff"
    def _num_qubits_(self):
        return self._num_qubits
    @property
    def phase_constant(self):
        return (self.F1.phase_constant + self.F2.phase_constant) % 4
    def __str__(self):
        args_str = ", ".join(
            (
                self.F1._args_str(suffix="1"),
                f"H={linalg.vector_to_tight_str(self.H)}",
                self.F2._args_str(include_num_qubits=False, suffix="1"),
            )
        )
        return (
            "" if np.isclose(self.phase_constant, 0) else f"i^{self.phase_constant} * "
        ) + f"FHFGate({args_str})"
    def validate(self) -> bool:
        return (
            self.F1.validate()
            and testing.is_boolean_array_of_shape(self.H, (self._num_qubits,))
            and self.F2.validate()
        )
    def is_canonical(self) -> bool:
        if not np.array_equal(self.F1.phase_matrix, self.F1.phase_matrix.T):
            return False
        S = cast(np.ndarray, _recover_permutation(self.F1.parity_matrix))
        if not linalg.is_tril_and_unit_diag(self.F1.parity_matrix[S]):
            return False
        if self.F2.parity_shift.any():
            return False
        if self.F2.phase_shift.any():
            return False
        if not np.array_equal(self.F2.phase_matrix, self.F2.phase_matrix.T):
            return False
        for i, j in itertools.product(range(self._num_qubits), repeat=2):
            if (
                ((not self.H[i]) and (not self.H[j]) and self.F2.phase_matrix[i, j])
                or (
                    self.H[i]
                    and (not self.H[j])
                    and S[i] > S[j]
                    and self.F2.phase_matrix[i, j]
                )
                or (
                    (not self.H[i])
                    and (not self.H[j])
                    and S[i] > S[j]
                    and self.F2.parity_matrix[i, j]
                )
                or (
                    self.H[i]
                    and self.H[j]
                    and S[i] < S[j]
                    and self.F2.parity_matrix[i, j]
                )
                or (self.H[i] and (not self.H[j]) and self.F2.parity_matrix[i, j])
            ):
                return False
        return True
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return False
        return (
            self._num_qubits == other._num_qubits
            and self.F1 == other.F1
            and np.array_equal(self.H, other.H)
            and self.F2 == other.F2
        )
    def copy(self):
        return type(self)(
            num_qubits=self._num_qubits,
            first_H_free_gate=self.F1.copy(),
            hadamards=np.copy(self.H),
            second_H_free_gate=self.F2.copy(),
        )
    def _hadamard_layer_gate(self):
        return SingleQubitLayerGate(
            cast(cirq.testing.SingleQubitGate, cirq.H if h else cirq.I)
            for i, h in enumerate(self.H)
        )
    def split(self) -> Tuple[cirq.Gate, ...]:
        return self.F1, self._hadamard_layer_gate(), self.F2
    def push_earlier(self) -> None:
        n = self._num_qubits
        F0 = self.F1
        assert F0.validate()
        self.F1 = type(F0)(num_qubits=n)
        if self.F2.parity_shift.any():
            raise NotImplementedError
        if self.F2.phase_shift.any():
            raise NotImplementedError
        H_indices = np.flatnonzero(self.H)
        I_indices = np.flatnonzero(np.logical_not(self.H))
        HH_indices = np.ix_(H_indices, H_indices)
        HI_indices = np.ix_(H_indices, I_indices)
        IH_indices = np.ix_(I_indices, H_indices)
        II_indices = np.ix_(I_indices, I_indices)
        k = len(H_indices)
        assert k == self.H.sum()
        assert k + len(I_indices) == n
        Δ_HH = self.F2.parity_matrix[HH_indices]
        Δ_HI = self.F2.parity_matrix[HI_indices]
        Δ_IH = self.F2.parity_matrix[IH_indices]
        Δ_II = self.F2.parity_matrix[II_indices]
        if np.any(Δ_HI):
            raise NotImplementedError
        I_HH = np.eye(k, dtype=linalg.DTYPE)
        I_HI = np.zeros_like(Δ_HI)
        I_IH = np.zeros_like(Δ_IH)
        I_II = np.eye(n - k, dtype=linalg.DTYPE)
        Δ_HH_inv = cast(np.ndarray, linalg.get_inverse(Δ_HH, True))
        new_Δ_IH = (Δ_IH @ Δ_HH_inv) % 2
        Δ = np.block([[Δ_HH, Δ_HI], [Δ_IH, Δ_II]])
        new_Δ = np.block([[I_HH, 0 * I_HI], [new_Δ_IH, I_II]])
        eye = np.eye(n, dtype=linalg.DTYPE)
        assert np.array_equal(self.F1.parity_matrix, eye)
        new_Δ_HH = linalg.get_inverse(Δ_HH.T)
        assert np.array_equal(new_Δ_HH, Δ_HH_inv.T)
        self.F1.parity_matrix[HH_indices] = new_Δ_HH
        self.F1.parity_matrix[II_indices] = Δ_II
        self.F2.parity_matrix = np.copy(eye)
        self.F2.parity_matrix[IH_indices] = new_Δ_IH
        assert self.F1.validate()
        assert F0.validate()
        F0 = self.F1 @ F0
        self.F1 = type(F0)(num_qubits=n)
        C, B = self.F2.to_phase_then_parity()
        assert not self.F1.phase_matrix[II_indices].any()
        assert not self.F1.phase_shift[I_indices].any()
        self.F1.phase_matrix[II_indices] = C.phase_matrix[II_indices]
        self.F1.phase_shift[I_indices] = C.phase_shift[I_indices]
        C.phase_matrix[II_indices] = 0
        C.phase_shift[I_indices] = 0
        assert np.array_equal(self.F1.parity_matrix, np.eye(n))
        assert not self.F1.parity_shift.any()
        assert np.array_equal(C.phase_matrix[HI_indices], C.phase_matrix[IH_indices].T)
        self.F1.parity_matrix[HI_indices] = C.phase_matrix[HI_indices]
        C.phase_matrix[HI_indices] = 0
        C.phase_matrix[IH_indices] = 0
        self.F2 = B @ C
        self.F1 @= F0
    def _decompose_(self, qubits):
        for gate in self.split():
            yield gate(*qubits)
    @classmethod
    def _from_sample(cls, sample: sampling.CliffordSample):
        num_qubits = sample.num_qubits()
        inv_perm = linalg.invert_permutation(sample.permutation)
        first_H_free_gate = HadamardFreeGate(
            num_qubits=num_qubits,
            parity_matrix=np.array(sample.first_parity_matrix, dtype=linalg.DTYPE)[
                inv_perm
            ],
            phase_matrix=np.array(sample.first_phase_matrix, dtype=linalg.DTYPE)[
                np.ix_(inv_perm, inv_perm)
            ],
            parity_shift=np.array(sample.parity_shift, dtype=linalg.DTYPE)[inv_perm],
            phase_shift=np.array(sample.phase_shift, dtype=linalg.DTYPE)[inv_perm],
        )
        second_H_free_gate = HadamardFreeGate(
            num_qubits=num_qubits,
            parity_matrix=np.array(sample.second_parity_matrix, dtype=linalg.DTYPE),
            phase_matrix=np.array(sample.second_phase_matrix, dtype=linalg.DTYPE),
        )
        FHF = cls(
            num_qubits,
            first_H_free_gate=first_H_free_gate,
            hadamards=np.array(sample.hadamards, dtype=linalg.DTYPE),
            second_H_free_gate=second_H_free_gate,
        )
        return FHF
    @classmethod
    def random(cls, num_qubits, seed=None):
        rng = np.random.default_rng(seed)
        sample = sampling.CliffordSampler(num_qubits).sample(rng)
        return cls._from_sample(sample)

import dataclasses
from dataclasses import dataclass
from typing import Any, Tuple
import cirq
import numpy as np
from recirq.third_party.quaff import indexing, linalg, random, testing
@dataclass
class HadamardFreeGate(cirq.Gate):
    num_qubits: dataclasses.InitVar[int]
    _num_qubits: int = dataclasses.field(init=False)
    parity_matrix: np.ndarray = None
    phase_matrix: np.ndarray = None
    parity_shift: np.ndarray = None
    phase_shift: np.ndarray = None
    phase_constant: float = 0
    def __post_init__(self, num_qubits):
        self._num_qubits = num_qubits
        if self.parity_matrix is None:
            self.parity_matrix = np.eye(num_qubits, dtype=linalg.DTYPE)
        else:
            self.parity_matrix = np.array(self.parity_matrix, dtype=linalg.DTYPE)
        if self.phase_matrix is None:
            self.phase_matrix = np.zeros((num_qubits,) * 2, dtype=linalg.DTYPE)
        else:
            self.phase_matrix = np.array(self.phase_matrix, dtype=linalg.DTYPE)
        if self.parity_shift is None:
            self.parity_shift = np.zeros(num_qubits, dtype=linalg.DTYPE)
        else:
            self.parity_shift = np.array(self.parity_shift, dtype=linalg.DTYPE)
        if self.phase_shift is None:
            self.phase_shift = np.zeros(num_qubits, dtype=linalg.DTYPE)
        else:
            self.phase_shift = np.array(self.phase_shift, dtype=linalg.DTYPE)
    @classmethod
    def _from_json_dict_(cls, *, _num_qubits, **kwargs):
        del kwargs["cirq_type"]
        return cls(num_qubits=_num_qubits, **kwargs)
    def _json_dict_(self):
        return cirq.dataclass_json_dict(self)
    @classmethod
    def _json_namespace_(cls):
        return "quaff"
    def _num_qubits_(self):
        return self._num_qubits
    def _unitary_(self):
        return self.unitary()
    def __bool__(self):
        if self.phase_matrix.any():
            return True
        if self.phase_shift.any():
            return True
        if self.parity_shift.any():
            return True
        if not np.array_equal(
            self.parity_matrix, np.eye(self._num_qubits, dtype=linalg.DTYPE)
        ):
            return True
        if not np.isclose(self.phase_constant, 0):
            return True
        return False
    def copy(self):
        return type(self)(
            num_qubits=self._num_qubits,
            parity_matrix=np.copy(self.parity_matrix),
            phase_matrix=np.copy(self.phase_matrix),
            parity_shift=np.copy(self.parity_shift),
            phase_shift=np.copy(self.phase_shift),
            phase_constant=self.phase_constant,
        )
    def validate(self) -> bool:
        n = self._num_qubits
        if not testing.is_boolean_array_of_shape(self.parity_matrix, (n, n)):
            return False
        if not linalg.is_invertible(self.parity_matrix):
            return False
        if not testing.is_boolean_array_of_shape(self.phase_matrix, (n, n)):
            return False
        if not np.array_equal(self.phase_matrix, self.phase_matrix.T):
            return False
        if not testing.is_boolean_array_of_shape(self.parity_shift, (n,)):
            return False
        if not testing.is_boolean_array_of_shape(self.phase_shift, (n,)):
            return False
        if not np.isclose(self.phase_constant.real, self.phase_constant):
            return False
        return True
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented
        return (
            np.array_equal(self.parity_matrix, other.parity_matrix)
            and np.array_equal(self.phase_matrix, other.phase_matrix)
            and np.array_equal(self.parity_shift, other.parity_shift)
            and np.array_equal(self.phase_shift, other.phase_shift)
            and np.isclose(abs(self.phase_constant - other.phase_constant) % 4, 0)
        )
    @property
    def changes_parity(self):
        return self.parity_shift.any() or not np.array_equal(
            self.parity_matrix, np.eye(self._num_qubits)
        )
    @property
    def changes_phase(self):
        return self.phase_shift.any() or self.phase_matrix.any()
    def __matmul__(self, other) -> "HadamardFreeGate":
        if not isinstance(other, type(self)):
            return NotImplemented
        if self._num_qubits != other._num_qubits:
            return NotImplemented
        G2, G1 = self, other
        assert G2.validate()
        assert G1.validate()
        c = G2.phase_constant + G1.phase_constant
        if not G2.changes_parity:
            Δ = np.copy(G1.parity_matrix)
            Γ = G1.phase_matrix + G2.phase_matrix
            X = np.copy(G1.parity_shift)
            Z = G1.phase_shift + G2.phase_shift + (np.diag(Γ) // 2)
        elif not G1.changes_phase:
            Δ = G2.parity_matrix @ G1.parity_matrix
            Γ = np.copy(G2.phase_matrix)
            X = G2.parity_matrix @ G1.parity_shift + G2.parity_shift
            Z = np.copy(G2.phase_shift)
        elif not (G2.changes_phase or G1.changes_parity):
            Δ = np.copy(G2.parity_matrix)
            Δ2_T_inv = linalg.get_inverse(Δ.T)
            Δ2_inv = linalg.get_inverse(Δ)
            Γ = Δ2_T_inv @ G1.phase_matrix @ Δ2_inv
            Z = Δ2_T_inv @ G1.phase_shift + Γ.T @ G2.parity_shift + (np.diag(Γ) // 2)
            Γ %= 2
            X = np.copy(G2.parity_shift)
            c -= (G2.parity_shift @ np.dot(Γ, G2.parity_shift)) % 4
            c -= (2 * Z @ G2.parity_shift) % 4
        else:
            C2, B2 = G2.to_phase_then_parity()
            assert C2.validate()
            assert B2.validate()
            assert B2 @ C2 == G2
            R = C2 @ G1
            assert R.validate()
            C1, B1 = R.to_phase_then_parity()
            assert C1.validate()
            assert B1.validate()
            assert (B1 @ C1) == R
            return (B2 @ B1) @ C1
        return type(self)(
            num_qubits=self._num_qubits,
            parity_matrix=Δ % 2,
            phase_matrix=Γ % 2,
            parity_shift=X % 2,
            phase_shift=Z % 2,
            phase_constant=c % 4,
        )
    @classmethod
    def random(cls, num_qubits: int, seed=None, include_phase_constant=True):
        rng = np.random.default_rng(seed)
        return cls(
            num_qubits=num_qubits,
            parity_matrix=random.random_invertible_matrix(num_qubits, seed=rng),
            phase_matrix=random.random_symmetric_matrix(num_qubits, seed=rng),
            parity_shift=random.random_vector(num_qubits, seed),
            phase_shift=random.random_vector(num_qubits, seed),
            phase_constant=4 * rng.random(),
        )
    def _args_str(self, include_num_qubits: bool = True, suffix: str = ""):
        args = [f"n={self._num_qubits}"] if include_num_qubits else []
        if not np.array_equal(self.parity_matrix, np.eye(self._num_qubits)):
            args.append(f"Δ{suffix}={linalg.matrix_to_tight_str(self.parity_matrix)}")
        if self.phase_matrix.any():
            args.append(f"Γ{suffix}={linalg.matrix_to_tight_str(self.phase_matrix)}")
        if self.parity_shift.any():
            args.append(f"X{suffix}={linalg.vector_to_tight_str(self.parity_shift)}")
        if self.phase_shift.any():
            args.append(f"Z{suffix}={linalg.vector_to_tight_str(self.phase_shift)}")
        return ", ".join(args)
    def __str__(self):
        return (
            "" if np.isclose(self.phase_constant, 0) else f"i^{self.phase_constant} * "
        ) + f"{type(self).__name__}({self._args_str()})"
    def inverse(self):
        if not self.changes_parity:
            Γ = np.copy(self.phase_matrix)
            Z = self.phase_shift + np.diag(Γ)
            return type(self)(
                num_qubits=self._num_qubits,
                phase_matrix=Γ,
                phase_shift=Z % 2,
                phase_constant=-self.phase_constant,
            )
        if not self.changes_phase:
            Δ = linalg.get_inverse(self.parity_matrix)
            X = (Δ @ self.parity_shift) % 2
            return type(self)(
                num_qubits=self._num_qubits,
                parity_matrix=Δ,
                parity_shift=X,
                phase_constant=-self.phase_constant,
            )
        B, C = self.split()
        return B.inverse() @ C.inverse()
    def is_minimal(self, hadamards: np.ndarray):
        if self.parity_shift.any():
            return False
        H_indices = np.flatnonzero(hadamards)
        k = len(H_indices)
        I_indices = np.flatnonzero(np.logical_not(hadamards))
        HH_indices = np.ix_(H_indices, H_indices)
        HI_indices = np.ix_(H_indices, I_indices)
        IH_indices = np.ix_(I_indices, H_indices)
        II_indices = np.ix_(I_indices, I_indices)
        if not np.array_equal(self.parity_matrix[HH_indices], np.eye(k)):
            return False
        if not np.array_equal(
            self.parity_matrix[II_indices], np.eye(self._num_qubits - k)
        ):
            return False
        if self.parity_matrix[np.ix_(H_indices, I_indices)].any():
            return False
        if self.phase_shift[I_indices].any():
            return False
        if self.phase_matrix[HI_indices].any():
            return False
        if self.phase_matrix[IH_indices].any():
            return False
        if self.phase_matrix[II_indices].any():
            return False
        return True
    def split(self) -> Tuple[Any, Any]:
        return type(self)(
            num_qubits=self._num_qubits,
            parity_matrix=np.copy(self.parity_matrix),
            parity_shift=np.copy(self.parity_shift),
        ), type(self)(
            num_qubits=self._num_qubits,
            phase_matrix=np.copy(self.phase_matrix),
            phase_shift=np.copy(self.phase_shift),
            phase_constant=self.phase_constant,
        )
    def to_phase_then_parity(self) -> Tuple[Any, Any]:
        new_Γ = self.parity_matrix.T @ self.phase_matrix @ self.parity_matrix
        new_Z = (np.diag(new_Γ) // 2) + (
            self.parity_matrix.T
            @ (self.phase_shift + (self.phase_matrix @ self.parity_shift))
        )
        new_phase_constant = (
            self.phase_constant
            + 2 * self.parity_shift @ self.phase_shift
            + self.parity_shift @ self.phase_matrix @ self.parity_shift
        ) % 4
        return type(self)(
            num_qubits=self._num_qubits, phase_matrix=new_Γ % 2, phase_shift=new_Z % 2
        ), type(self)(
            num_qubits=self._num_qubits,
            parity_matrix=np.copy(self.parity_matrix),
            parity_shift=np.copy(self.parity_shift),
            phase_constant=new_phase_constant,
        )
    def unitary(self):
        N = 2**self._num_qubits
        input_bitstrings = indexing.get_all_bitstrings(self._num_qubits)
        output_bitstrings = (
            self.parity_matrix @ input_bitstrings.transpose((1, 0))
        ).transpose((1, 0)) % 2
        output_bitstrings ^= self.parity_shift[np.newaxis, :]
        output_indices = indexing.bitstrings_to_indices(output_bitstrings)
        U = np.zeros((N, N), dtype=np.complex128)
        phases = np.einsum(
            "ij,jk,ik->i", output_bitstrings, self.phase_matrix, output_bitstrings
        ) + (2 * output_bitstrings @ self.phase_shift)
        U[output_indices, np.arange(N)] = 1j**phases
        return (1j**self.phase_constant) * U

from typing import Any, Iterable, Optional, Sequence
import cirq
import sympy
from recirq.third_party.quaff import cz_layer
from recirq.third_party.quaff.gates.truncated_clifford import TruncatedCliffordGate
def get_truncated_clifford_resolver(
    gate: TruncatedCliffordGate, suffix: Optional[Any] = None
):
    if suffix is None:
        suffix = ""
    else:
        suffix = "_" + str(suffix)
    resolver = {}
    for i, h in enumerate(gate.H):
        resolver[f"h_{i}{suffix}"] = h
    linear, quadratic = gate._CZ_layer()._get_phases()
    for i, s in enumerate((linear + gate._full_P()) % 4):
        resolver[f"s_{i}{suffix}"] = s
    for i, row in enumerate(quadratic):
        for j, u in enumerate(row):
            resolver[f"u_{i}_{j}{suffix}"] = u
    return resolver
def get_truncated_cliffords_resolver(gates: Iterable[TruncatedCliffordGate]):
    resolver = {}
    for i, gate in enumerate(gates):
        resolver.update(get_truncated_clifford_resolver(gate, i))
    return resolver
def get_parameterized_truncated_clifford_ops(
    qubits, suffix: Optional[Any] = None
) -> cirq.OP_TREE:
    if suffix is None:
        suffix = ""
    else:
        suffix = "_" + str(suffix)
    n = len(qubits)
    for i, q in enumerate(qubits):
        yield cirq.H(q) ** (1 - sympy.Symbol(f"h_{i}{suffix}"))
    for i, q in enumerate(qubits):
        yield cirq.S(q) ** sympy.Symbol(f"s_{i}{suffix}")
    basis_change_op = cz_layer.CZLayerBasisChangeStageGate(n, 2)(*qubits)
    for i in range(n // 2):
        yield basis_change_op
        for j, q in enumerate(qubits):
            yield cirq.S(q) ** sympy.Symbol(f"u_{i}_{j}{suffix}")
    yield cz_layer.CZLayerBasisChangeStageGate(n, 1 + (n % 2))(*qubits)
    for q in qubits:
        yield cirq.H(q)
def get_parameterized_truncated_cliffords_ops(
    partition: Sequence[Sequence[cirq.Qid]],
) -> cirq.OP_TREE:
    for i, part in enumerate(partition):
        yield get_parameterized_truncated_clifford_ops(part, i)

from typing import Iterable
import cirq
class SingleQubitLayerGate(cirq.Gate):
    def __init__(self, gates: Iterable[cirq.testing.SingleQubitGate]):
        self.gates = tuple(gates)
        for gate in gates:
            if cirq.num_qubits(gate) != 1:
                raise ValueError(f"{gate} is not a single-qubit gate.")
    def _unitary_(self):
        return cirq.kron(*(cirq.unitary(gate) for gate in self.gates))
    def _decompose_(self, qubits):
        for qubit, gate in zip(qubits, self.gates):
            yield gate(qubit)
    def num_qubits(self):
        return len(self.gates)
    def __pow__(self, exponent):
        return type(self)(gate**exponent for gate in self.gates)
    def __str__(self):
        return str(self.gates)
    def __eq__(self, other):
        if not isinstance(other, cirq.Gate):
            raise TypeError
        if not isinstance(other, type(self)):
            return False
        if self.num_qubits() != other.num_qubits():
            return False
        return all(gate == other_gate for gate, other_gate in zip(self.gates, other.gates))

import dataclasses
from dataclasses import dataclass
from typing import cast
import cirq
import numpy as np
from recirq.third_party.quaff import comb, cz_layer, indexing, linalg, sampling, testing
from recirq.third_party.quaff.gates.fhf import FHFGate
from recirq.third_party.quaff.gates.hadamard_free import HadamardFreeGate
from recirq.third_party.quaff.gates.single_qubit_layer import SingleQubitLayerGate
from recirq.third_party.quaff.linalg import BooleanMatrix, BooleanVector
@dataclass(eq=True, order=True)
class TruncatedCliffordGate(cirq.Gate):
    num_qubits: dataclasses.InitVar[int]
    _num_qubits: int = dataclasses.field(init=False)
    H: BooleanVector = cast(BooleanVector, None)
    CX: BooleanMatrix = cast(BooleanMatrix, None)
    CZ: BooleanVector = cast(BooleanVector, None)
    P: BooleanVector = cast(BooleanVector, None)
    def __post_init__(self, num_qubits):
        self._num_qubits = num_qubits
        if self.H is None:
            self.H = (0,) * num_qubits
        else:
            self.H = tuple(linalg.DTYPE(x) for x in self.H)
        k = self.rank
        if self.CX is None:
            if k:
                self.CX = ((0,) * k,) * (num_qubits - k)
            else:
                self.CX = ()
        else:
            self.CX = linalg.tuple_of_tuples(self.CX)
        if self.CZ is None:
            self.CZ = (0,) * comb.binom(k)
        else:
            self.CZ = tuple(linalg.DTYPE(x) for x in self.CZ)
        if self.P is None:
            self.P = (0,) * k
        else:
            self.P = tuple(linalg.DTYPE(x) for x in self.P)
    @classmethod
    def _from_json_dict_(cls, *, _num_qubits, **kwargs):
        del kwargs["cirq_type"]
        return cls(num_qubits=_num_qubits, **kwargs)
    def _json_dict_(self):
        return cirq.dataclass_json_dict(self)
    @classmethod
    def _json_namespace_(cls):
        return "quaff"
    def __str__(self):
        args = [f"n={self._num_qubits}"]
        if np.any(self.H):
            args.append(f"H={linalg.vector_to_tight_str(self.H)}")
        if np.any(self.CX):
            args.append(f"CX={linalg.matrix_to_tight_str(self.CX)}")
        if np.any(self.CZ) or np.any(self.P):
            args.append(
                f"phase={linalg.matrix_to_tight_str(self._phase_matrix_block())}"
            )
        args_str = ", ".join(args)
        return f"{type(self).__name__}({args_str})"
    def copy(self):
        return type(self)(
            num_qubits=self._num_qubits, H=self.H, CX=self.CX, CZ=self.CZ, P=self.P
        )
    @property
    def rank(self):
        return sum(self.H)
    def validate(self) -> bool:
        k = self.rank
        if not testing.is_boolean_tuple_of_len(self.P, k):
            return False
        if not testing.is_boolean_tuple_of_len(self.CZ, comb.binom(k)):
            return False
        if not testing.is_boolean_tuple_of_len(self.H, self._num_qubits):
            return False
        if k in (0, self._num_qubits):
            if self.CX != ():
                return False
        else:
            if not testing.is_nested_boolean_tuples_of_shape(
                self.CX, (self._num_qubits - k, k)
            ):
                return False
        return True
    def _num_qubits_(self):
        return self._num_qubits
    def _phase_matrix_block(self) -> np.ndarray:
        k = self.rank
        Γ = np.zeros((k, k), dtype=linalg.DTYPE)
        Γ[indexing.triu_indices(k)] = self.CZ
        Γ[indexing.tril_indices(k)] = self.CZ
        Γ[np.diag_indices(k)] = self.P
        return Γ
    def _CZ_layer(self):
        H_indices = np.flatnonzero(self.H)
        I_indices = np.flatnonzero(np.logical_not(self.H))
        pairs = []
        for i, j, cz in zip(*indexing.triu_indices(self.rank), self.CZ):
            if cz:
                pairs.append((H_indices[i], H_indices[j]))
        for i, row in zip(I_indices, self.CX):
            for j, cx in zip(H_indices, row):
                if cx:
                    pairs.append((i, j))
        return cz_layer.CZLayerGate(num_qubits=self._num_qubits, pairs=pairs)
    def _full_P(self):
        P = np.zeros(self._num_qubits, dtype=linalg.DTYPE)
        H_indices = np.flatnonzero(self.H)
        P[H_indices] = self.P
        return P
    def _decompose_(self, qubits):
        first_layer = [cirq.I] * self._num_qubits
        j = 0
        for i, h in enumerate(self.H):
            if h:
                if self.P[j]:
                    first_layer[i] = cirq.S
                j += 1
            else:
                first_layer[i] = cirq.H
        yield SingleQubitLayerGate(first_layer)(*qubits)
        yield self._CZ_layer()(*qubits)
        yield SingleQubitLayerGate(cirq.H for _ in self.H)(*qubits)
    def to_FHF_gate(self):
        n = self._num_qubits
        H_indices = np.flatnonzero(self.H)
        I_indices = np.flatnonzero(np.logical_not(self.H))
        Δ = np.eye(n, dtype=linalg.DTYPE)
        if self.rank not in (0, n):
            Δ[np.ix_(I_indices, H_indices)] = self.CX
        Γ = np.zeros((n, n), dtype=linalg.DTYPE)
        if self.rank:
            Γ[np.ix_(H_indices, H_indices)] = self._phase_matrix_block()
        F1 = HadamardFreeGate(num_qubits=n, parity_matrix=Δ, phase_matrix=Γ)
        F2 = HadamardFreeGate(
            num_qubits=n, parity_matrix=np.flip(np.eye(n, dtype=linalg.DTYPE), 0)
        )
        return FHFGate(
            num_qubits=n, first_H_free_gate=F1, hadamards=self.H, second_H_free_gate=F2
        )
    @classmethod
    def _from_sample(cls, sample: sampling.CliffordSample):
        FHF_gate = FHFGate._from_sample(sample)
        FHF_gate.push_earlier()
        F2, H = FHF_gate.F2, FHF_gate.H
        H_indices = np.flatnonzero(H)
        I_indices = np.flatnonzero(np.logical_not(H))
        HH_indices = np.ix_(H_indices, H_indices)
        IH_indices = np.ix_(I_indices, H_indices)
        k = len(H_indices)
        CX = F2.parity_matrix[IH_indices]
        CZ = F2.phase_matrix[HH_indices][indexing.tril_indices(k)]
        P = np.diag(F2.phase_matrix)[H_indices]
        return cls(
            num_qubits=sample.num_qubits(),
            H=tuple(H),
            CX=tuple(tuple(row) for row in CX) if CX.size else (),
            CZ=tuple(CZ),
            P=tuple(P),
        )
    @classmethod
    def random(cls, num_qubits, seed=None):
        rng = np.random.default_rng(seed)
        sample = sampling.CliffordSampler(num_qubits).sample(rng)
        return cls._from_sample(sample)

import itertools
import math
from dataclasses import dataclass
from typing import Iterable, NamedTuple, Optional, Tuple
import cirq
import numpy as np
from recirq.third_party.quaff import comb, indexing, linalg, testing
from recirq.third_party.quaff.sampling.sampler import SingleParameterSampler
QuantumMallowsSample = Tuple[Tuple[bool, ...], Tuple[int, ...]]
QuantumMallowsRandomness = Tuple[int, ...]
class QuantumMallowsSampler(SingleParameterSampler):
    def sample_randomness(
        self, rng: Optional[np.random.Generator] = None
    ) -> QuantumMallowsRandomness:
        rng = np.random.default_rng(rng)
        return tuple(rng.integers(0, 4**m - 1) for m in np.arange(self.n, 0, -1))
    def randomness_iter(self) -> Iterable[QuantumMallowsRandomness]:
        return itertools.product(*(range(k) for k in 4 ** np.arange(self.n, 0, -1) - 1))
    def randomness_size(self) -> int:
        return math.prod(4 ** np.arange(self.n, 0, -1) - 1)
    def validate_randomness(self, randomness: QuantumMallowsRandomness) -> bool:
        if any(r < 0 for r in randomness):
            return False
        return all(r < 4**m - 1 for r, m in zip(randomness, np.arange(self.n, 0, -1)))
    def _parse_randomness(self, randomness) -> Iterable[Tuple[int, int, int, int]]:
        for i, r in enumerate(randomness):
            m = self.n - i
            threshold = 2**m - 1
            if r < threshold:
                h = 0
                threshold = 0
                for k in range(1, m + 1):
                    threshold += 2 ** (k - 1)
                    if r < threshold:
                        break
            else:
                h = 1
                r -= threshold
                threshold = 0
                for k in range(1, m + 1):
                    threshold += 2 ** (2 * m - k)
                    if r < threshold:
                        break
            yield i, k - 1, h, threshold - 1 - r
    def randomness_to_sample(
        self, randomness: QuantumMallowsRandomness
    ) -> QuantumMallowsSample:
        H = np.zeros(self.n, dtype=bool)
        S = np.zeros(self.n, dtype=int)
        A = list(range(self.n))
        for i, k, h, _ in self._parse_randomness(randomness):
            H[i] = h
            S[i] = A.pop(k)
        return tuple(H), tuple(S)
    def num_unique_samples(self):
        return (2**self.n) * math.factorial(self.n)
    def unique_samples_iter(self) -> Iterable[QuantumMallowsSample]:
        return itertools.product(
            itertools.product((False, True), repeat=self.n),
            itertools.permutations(range(self.n)),
        )
    def sample_multiplicity(self, sample: QuantumMallowsSample):
        h, S = sample
        exponent = (
            comb.binom(self.n)
            + np.sum(h)
            + sum(
                1 if h[i] else -1
                for i, j in itertools.combinations(range(self.n), 2)
                if S[i] < S[j]
            )
        )
        return 2**exponent
    def name(self):
        return "QuantumMallowsSampler"
@dataclass(frozen=True, order=True)
class CliffordSample:
    first_parity_matrix: linalg.BooleanMatrix
    first_phase_matrix: linalg.BooleanMatrix
    parity_shift: linalg.BooleanVector
    phase_shift: linalg.BooleanVector
    permutation: Tuple[int, ...]
    hadamards: linalg.BooleanVector
    second_parity_matrix: linalg.BooleanMatrix
    second_phase_matrix: linalg.BooleanMatrix
    @classmethod
    def _from_json_dict_(cls, **kwargs):
        return cls(
            **{
                key: (
                    linalg.tuple_of_tuples(val)
                    if key.endswith("matrix")
                    else tuple(val)
                )
                for key, val in kwargs.items()
                if key != "cirq_type"
            }
        )
    def _json_dict_(self):
        return cirq.dataclass_json_dict(self)
    @classmethod
    def _json_namespace_(cls):
        return "quaff"
    def num_qubits(self):
        return len(self.parity_shift)
    def __str__(self):
        args_str = ", ".join(
            (
                f"Δ1={linalg.matrix_to_tight_str(self.first_parity_matrix)}",
                f"Γ1={linalg.matrix_to_tight_str(self.first_phase_matrix)}",
                f"X={linalg.vector_to_tight_str(self.parity_shift)}",
                f"Z={linalg.vector_to_tight_str(self.phase_shift)}",
                f"S={self.permutation}",
                f"H={linalg.vector_to_tight_str(self.hadamards)}",
                f"Δ2={linalg.matrix_to_tight_str(self.second_parity_matrix)}",
                f"Γ2={linalg.matrix_to_tight_str(self.second_phase_matrix)}",
            )
        )
        return f"CliffordSample({args_str})"
class CliffordRandomness(NamedTuple):
    mallows_randomness: QuantumMallowsRandomness
    parity_matrix_randomness: Tuple[bool, ...]
    phase_matrix_randomness: Tuple[bool, ...]
    parity_shift_randomness: Tuple[bool, ...]
    phase_shift_randomness: Tuple[bool, ...]
class CliffordSampler(SingleParameterSampler):
    def __init__(self, n: int):
        self.n = n
        self.mallows_sampler = QuantumMallowsSampler(n)
    def sample_randomness(
        self, rng: Optional[np.random.Generator]
    ) -> CliffordRandomness:
        rng = np.random.default_rng(rng)
        binom = comb.binom(self.n)
        return CliffordRandomness(
            mallows_randomness=self.mallows_sampler.sample_randomness(rng),
            parity_matrix_randomness=tuple(rng.integers(0, 2, binom)),
            phase_matrix_randomness=tuple(rng.integers(0, 2, binom + self.n)),
            parity_shift_randomness=tuple(rng.integers(0, 2, self.n)),
            phase_shift_randomness=tuple(rng.integers(0, 2, self.n)),
        )
    def _get_Δ_and_Γ_indices(
        self, H: np.ndarray, S: np.ndarray
    ) -> Tuple[np.ndarray, np.ndarray]:
        Δ_indices, Γ_indices = [], []
        for j, i in itertools.combinations(range(self.n), 2):
            if H[j]:
                if H[i]:
                    Γ_indices.append((i, j))
                    if S[i] > S[j]:
                        Δ_indices.append((i, j))
                else:
                    Δ_indices.append((i, j))
                    if S[i] > S[j]:
                        Γ_indices.append((i, j))
            else:
                if S[i] >= S[j]:
                    continue
                if H[i]:
                    Γ_indices.append((i, j))
                else:
                    Δ_indices.append((i, j))
        return (
            (
                tuple(np.array(Δ_indices).T)
                if Δ_indices
                else (np.zeros(0, dtype=int),) * 2
            ),
            (
                tuple(np.array(Γ_indices).T)
                if Γ_indices
                else (np.zeros(0, dtype=int),) * 2
            ),
        )
    def randomness_to_sample(self, randomness: CliffordRandomness) -> CliffordSample:
        S = np.zeros(self.n, dtype=int)
        A = list(range(self.n))
        H = np.zeros(self.n, dtype=linalg.DTYPE)
        Δ1, Δ2 = (np.eye(self.n, dtype=linalg.DTYPE) for _ in "12")
        Γ1, Γ2 = (np.zeros((self.n,) * 2, dtype=linalg.DTYPE) for _ in "12")
        Γ1_diag_bits = randomness.phase_matrix_randomness[: self.n]
        Γ1[np.diag_indices(self.n)] = Γ1_diag_bits
        Γ1_offdiag_bits = randomness.phase_matrix_randomness[self.n :]
        if self.n > 1:
            tril_indices = indexing.tril_indices(self.n)
            triu_indices = indexing.triu_indices(self.n)
            Δ1[tril_indices] = randomness.parity_matrix_randomness
            Γ1[tril_indices] = Γ1_offdiag_bits
            Γ1[triu_indices] = Γ1_offdiag_bits
        special_bits = []
        for i, k, h, j in self.mallows_sampler._parse_randomness(
            randomness.mallows_randomness
        ):
            S[i] = A.pop(k)
            H[i] = h
            n_extra_bits = 2 * (self.n - i) - k - 1 if h else k
            special_bits += list(indexing.index_to_bitstring(n_extra_bits, j))
        Δ_indices, Γ_indices = self._get_Δ_and_Γ_indices(H, S)
        H_indices = tuple(np.flatnonzero(H))
        n_H_bits = np.sum(H, dtype=int)
        n_Δ_bits = len(Δ_indices[0])
        n_Γ_bits = len(Γ_indices[0])
        assert all(Δ_indices[d].shape == (n_Δ_bits,) for d in (0, 1))
        assert len(Δ_indices) == 2
        assert all(Γ_indices[d].shape == (n_Γ_bits,) for d in (0, 1))
        assert len(Γ_indices) == 2
        assert n_H_bits + n_Δ_bits + n_Γ_bits == len(special_bits)
        H_bits = special_bits[:n_H_bits]
        Δ_bits = special_bits[n_H_bits : n_H_bits + n_Δ_bits]
        Γ_bits = special_bits[n_H_bits + n_Δ_bits :]
        if Δ_bits:
            Δ2[Δ_indices] = Δ_bits
        if H_bits:
            Γ2[H_indices, H_indices] = H_bits
        if Γ_bits:
            Γ2[Γ_indices] = Γ_bits
            Γ2[Γ_indices[::-1]] = Γ_bits
        return CliffordSample(
            first_parity_matrix=tuple(tuple(row) for row in Δ1),
            first_phase_matrix=tuple(tuple(row) for row in Γ1),
            hadamards=tuple(H),
            permutation=tuple(S),
            parity_shift=randomness.parity_shift_randomness,
            phase_shift=randomness.phase_shift_randomness,
            second_parity_matrix=tuple(tuple(row) for row in Δ2),
            second_phase_matrix=tuple(tuple(row) for row in Γ2),
        )
    def randomness_iter(self) -> Iterable[CliffordRandomness]:
        binom = comb.binom(self.n)
        for HS, Δ, Γ, X, Z in itertools.product(
            self.mallows_sampler.randomness_iter(),
            itertools.product((0, 1), repeat=binom),
            itertools.product((0, 1), repeat=binom + self.n),
            itertools.product((0, 1), repeat=self.n),
            itertools.product((0, 1), repeat=self.n),
        ):
            yield CliffordRandomness(
                mallows_randomness=HS,
                parity_matrix_randomness=tuple(bool(δ) for δ in Δ),
                phase_matrix_randomness=tuple(bool(γ) for γ in Γ),
                parity_shift_randomness=tuple(bool(x) for x in X),
                phase_shift_randomness=tuple(bool(z) for z in Z),
            )
    def validate_randomness(self, randomness: CliffordRandomness) -> bool:
        if not self.mallows_sampler.validate_randomness(randomness.mallows_randomness):
            return False
        binom = comb.binom(self.n)
        return all(
            (
                testing.is_boolean_tuple_of_len(
                    randomness.parity_matrix_randomness, binom
                ),
                testing.is_boolean_tuple_of_len(
                    randomness.phase_matrix_randomness, binom + self.n
                ),
                testing.is_boolean_tuple_of_len(
                    randomness.parity_shift_randomness, self.n
                ),
                testing.is_boolean_tuple_of_len(
                    randomness.phase_shift_randomness, self.n
                ),
            )
        )
    def name(self) -> str:
        return "CliffordSampler"
    def unique_samples_iter(self) -> Iterable[CliffordSample]:
        binom = comb.binom(self.n)
        Δ1, Δ2 = (np.eye(self.n, dtype=linalg.DTYPE) for _ in "12")
        Γ1, Γ2 = (np.zeros((self.n,) * 2, dtype=linalg.DTYPE) for _ in "12")
        tril_indices = indexing.tril_indices(self.n)
        triu_indices = indexing.triu_indices(self.n)
        for H, S in itertools.product(
            itertools.product((0, 1), repeat=self.n),
            itertools.permutations(range(self.n)),
        ):
            Δ_indices, Γ_indices = self._get_Δ_and_Γ_indices(H, S)
            H_indices = np.flatnonzero(H)
            for H_bits, Δ1_bits, Γ1_bits, Δ2_bits, Γ2_bits in itertools.product(
                itertools.product((0, 1), repeat=len(H_indices)),
                itertools.product((0, 1), repeat=binom),
                itertools.product((0, 1), repeat=binom + self.n),
                itertools.product((0, 1), repeat=len(Δ_indices[0])),
                itertools.product((0, 1), repeat=len(Γ_indices[0])),
            ):
                Γ1[np.diag_indices(self.n)] = Γ1_bits[: self.n]
                assert Γ1[tril_indices].shape == (binom,)
                if self.n > 1:
                    Δ1[tril_indices] = Δ1_bits
                    Γ1[tril_indices] = Γ1_bits[self.n :]
                    Γ1[triu_indices] = Γ1_bits[self.n :]
                    Δ2[tril_indices] = 0
                if Δ2_bits:
                    Δ2[Δ_indices] = Δ2_bits
                Γ2[:, :] = 0
                if len(H_indices):
                    Γ2[H_indices, H_indices] = H_bits
                if Γ2_bits:
                    Γ2[Γ_indices] = Γ2_bits
                    Γ2[Γ_indices[::-1]] = Γ2_bits
                for X, Z in itertools.product(
                    itertools.product((0, 1), repeat=self.n), repeat=2
                ):
                    yield CliffordSample(
                        first_parity_matrix=tuple(tuple(row) for row in Δ1),
                        first_phase_matrix=tuple(tuple(row) for row in Γ1),
                        parity_shift=tuple(bool(x) for x in X),
                        phase_shift=tuple(bool(z) for z in Z),
                        permutation=tuple(S),
                        hadamards=tuple(bool(h) for h in H),
                        second_parity_matrix=tuple(tuple(row) for row in Δ2),
                        second_phase_matrix=tuple(tuple(row) for row in Γ2),
                    )
    def num_unique_samples(self) -> int:
        return comb.num_cliffords(self.n)

from typing import List, Optional
import cirq
from recirq.seniority_zero.circuits_expt.gate_sets import SeniorityZeroGateSet
from recirq.seniority_zero.misc import (
    parallelize_circuits,
    safe_concatenate_circuits,
    safe_tetris_circuits,
)
from recirq.seniority_zero.scheduling import get_tqbg_groups
def _make_lightcone(num_qubits: int, depth: int=None) -> List[cirq.Gate]:
    if depth is None:
        depth = num_qubits // 2
    gates_per_layer = num_qubits // 2
    last_layer_offset = (gates_per_layer + 1) % 2
    timelike_gates_all_qubits = []
    for qid in range(num_qubits):
        timelike_gates_this_qubit = [[((qid - last_layer_offset) % num_qubits) // 2]]
        for layer_id in range(1, num_qubits // 2):
            timelike_gates_this_qubit.append(list(timelike_gates_this_qubit[-1]))
            offset = (layer_id + last_layer_offset) % 2
            if offset == 0:
                timelike_gates_this_qubit[-1].append(
                    (timelike_gates_this_qubit[-1][-1] + 1) % gates_per_layer
                )
            else:
                timelike_gates_this_qubit[-1].insert(
                    0, (timelike_gates_this_qubit[-1][0] - 1) % gates_per_layer
                )
        timelike_gates_all_qubits.append(timelike_gates_this_qubit)
    return timelike_gates_all_qubits
_timelike_gates = {num_qubits: _make_lightcone(num_qubits) for num_qubits in [4, 6, 8, 10, 12]}
def gs_layer(
    qubits: List,
    layer_params: List[float],
    offset: int,
    gate_indices: List[int],
    gateset: SeniorityZeroGateSet,
) -> cirq.Circuit:
    assert len(layer_params) == len(qubits) // 2
    circuits = [
        gateset.gsgate(qubits[2 * i + offset],
                       qubits[(2 * i + 1 + offset) % len(qubits)],
                       layer_params[i])
        for i in gate_indices
    ]
    circuit = parallelize_circuits(*circuits)
    return circuit
def givens_swap_network(
    qubits: List,
    params: List[float],
    depth: int,
    gateset: SeniorityZeroGateSet,
    target_qids: Optional[List[cirq.Qid]] = None,
    inverse: Optional[bool] = False,
    global_echo: Optional[bool] = False,
    echoed_layers: Optional[List] = None,
) -> cirq.Circuit:
    num_qubits = len(qubits)
    nparams_layer = num_qubits // 2
    echo_flag = global_echo
    layer_indices = range(depth)
    if inverse:
        layer_indices = reversed(layer_indices)
    if echoed_layers is None:
        echoed_layers = []
    echo_layer = cirq.Circuit([cirq.X(qubit) for qubit in qubits])
    circuit = cirq.Circuit()
    for layer_id in layer_indices:
        if layer_id in echoed_layers:
            circuit = safe_concatenate_circuits(circuit, echo_layer)
            echo_flag = not echo_flag
        offset = layer_id % 2
        if target_qids:
            gate_indices = set(
                [
                    gid
                    for qid in target_qids
                    for gid in _timelike_gates[num_qubits][qid][depth - layer_id - 1]
                ]
            )
        else:
            gate_indices = range(len(qubits) // 2)
        layer_params = params[layer_id * nparams_layer : (layer_id + 1) * nparams_layer]
        if echo_flag is True:
            layer_params = [-xx for xx in layer_params]
        layer_circuit = gs_layer(
            qubits=qubits,
            layer_params=layer_params,
            offset=layer_id % 2,
            gate_indices=gate_indices,
            gateset=gateset,
        )
        circuit = safe_concatenate_circuits(circuit, layer_circuit)
    if len(echoed_layers) % 2 == 1:
        circuit = safe_concatenate_circuits(circuit, echo_layer)
    return circuit
def GHZ_prep_2xn_mixed_filling(
    qubit_line1: List,
    qubit_line2: List,
    state_line1: List[int],
    state_line2: List[int],
    starting_index: int,
    gateset: SeniorityZeroGateSet,
    inverse: Optional[bool] = False,
    global_echo: Optional[bool] = False,
) -> cirq.Circuit:
    if global_echo is True:
        cnot_or_cmnot = gateset.cmnot
    else:
        cnot_or_cmnot = gateset.cnot
    swap = gateset.swap
    filled_indices = [
        index
        for index in range(len(qubit_line1))
        if (state_line1[index] == 1 or state_line2[index] == 1)
    ]
    right_gates = []
    for qr_index in range(starting_index + 1, max(filled_indices) + 1):
        if qr_index - 1 == starting_index or qr_index - 1 in filled_indices:
            right_gates.append(cnot_or_cmnot(qubit_line1[qr_index - 1], qubit_line1[qr_index]))
        else:
            right_gates.append(swap(qubit_line1[qr_index - 1], qubit_line1[qr_index]))
    left_gates = []
    for ql_index in range(starting_index - 1, min(filled_indices) - 1, -1):
        if ql_index + 1 in filled_indices:
            left_gates.append(cnot_or_cmnot(qubit_line1[ql_index + 1], qubit_line1[ql_index]))
        else:
            left_gates.append(swap(qubit_line1[ql_index + 1], qubit_line1[ql_index]))
    combined_gates = [right_gates[0]]
    for left_gate, right_gate in zip(left_gates, right_gates[1:]):
        combined_gates.append(parallelize_circuits(right_gate, left_gate))
    if len(left_gates) > len(right_gates) - 1:
        combined_gates += left_gates[len(right_gates) - 1 :]
        if state_line2[min(filled_indices)] == 1 or state_line2[min(filled_indices) + 1] == 1:
            combined_gates.append(cirq.Circuit())
    elif len(right_gates) > len(left_gates) + 1:
        combined_gates += right_gates[len(left_gates) + 1 :]
        if state_line2[max(filled_indices)] == 1 or state_line2[max(filled_indices) - 1] == 1:
            combined_gates.append(cirq.Circuit())
    else:
        if (
            state_line2[max(filled_indices)] == 1
            or state_line2[max(filled_indices) - 1] == 1
            or state_line2[min(filled_indices)] == 1
            or state_line2[min(filled_indices) + 1] == 1
        ):
            combined_gates.append(cirq.Circuit())
    last_layer_gates = []
    for index in filled_indices:
        if state_line2[index] == 1:
            if state_line1[index] == 1:
                last_layer_gates.append(cnot_or_cmnot(qubit_line1[index], qubit_line2[index]))
            else:
                last_layer_gates.append(swap(qubit_line1[index], qubit_line2[index]))
    combined_gates[-1] = parallelize_circuits(combined_gates[-1], *last_layer_gates)
    if inverse:
        combined_gates = reversed(combined_gates)
    circuit = cirq.Circuit()
    for subcircuit in combined_gates:
        circuit = safe_concatenate_circuits(circuit, subcircuit)
    return circuit
def starting_index_GHZ_prep_2xn(state_line1: List, state_line2: List) -> int:
    filled_indices = [
        index
        for index in range(len(state_line1))
        if (state_line1[index] == 1 or state_line2[index] == 1)
    ]
    starting_index = (max(filled_indices) + min(filled_indices)) // 2
    return starting_index
def get_starting_qubits_all_groups_2xN(qubits: List[cirq.Qid], extra_shift=None) -> List[cirq.Qid]:
    num_qubits = len(qubits)
    groups = get_tqbg_groups(qubits)
    starting_qubits = []
    for group in groups:
        if extra_shift is None:
            extra_shift = (num_qubits % 4) // 2
        shift = group.shift
        starting_state = [(qid + shift + extra_shift) % 2 for qid in range(num_qubits)]
        state_line1 = starting_state[: num_qubits // 2]
        state_line2 = list(reversed(starting_state[num_qubits // 2 :]))
        qubit_line1 = qubits[: num_qubits // 2]
        qubit_line2 = list(reversed(qubits[num_qubits // 2 :]))
        q0id = starting_index_GHZ_prep_2xn(state_line1, state_line2)
        q0 = qubit_line1[q0id]
        starting_qubits.append(q0)
    return starting_qubits
def get_starting_qubits_all_groups_loop(qubits, groups, extra_shift=None) -> List[cirq.Qid]:
    num_qubits = len(qubits)
    starting_qubits = []
    for group in groups:
        if extra_shift is None:
            extra_shift = (num_qubits % 4) // 2
        shift = group.shift
        initial_state = [(qid + shift + extra_shift) % 2 for qid in range(num_qubits)]
        q0id = starting_index_loop_on_lattice(qubits, initial_state)
        q0 = qubits[q0id]
        starting_qubits.append(q0)
    return starting_qubits
def starting_index_loop_on_lattice(loop: List[cirq.Qid], initial_state: List[int]) -> int:
    pair = starting_pair_loop_on_lattice(loop, initial_state)
    q0id = loop.index(pair[0])
    return q0id
def starting_pair_loop_on_lattice(
    loop: List[cirq.Qid],
    initial_state: List[int]
) -> List[cirq.Qid]:
    adjacent_pairs = [
        (q0, q1) for q0id, q0 in enumerate(loop) for q1 in loop[q0id + 1 :] if q0.is_adjacent(q1)
    ]
    best_pair = None
    best_depth = None
    for pair in adjacent_pairs:
        q0id = loop.index(pair[0])
        q1id = loop.index(pair[1])
        depth_inner = (q1id - q0id - 1) // 2  # N.B. should be an integer anyway!
        depth_outer = (len(loop) - (q1id - q0id) - 1) // 2  # N.B this also.
        depth = max(depth_inner, depth_outer)
        if depth_inner == depth_outer:
            depth += 1
        if best_depth is None or depth < best_depth:
            best_pair = pair
            best_depth = depth
    return best_pair
def GHZ_prep_loop_on_lattice(
    loop: List[cirq.Qid],
    initial_state: List[int],
    gateset: SeniorityZeroGateSet,
    global_echo: Optional[bool] = False,
    inverse: Optional[bool] = False,
) -> cirq.Circuit:
    if global_echo is True:
        cnot_or_cmnot = gateset.cmnot
    else:
        cnot_or_cmnot = gateset.cnot
    swap = gateset.swap
    init_pair = starting_pair_loop_on_lattice(loop, initial_state)
    circuit_list = [cnot_or_cmnot(init_pair[0], init_pair[1])]
    q0id = loop.index(init_pair[0])
    q1id = loop.index(init_pair[1])
    inner_line = loop[q0id : q1id + 1]
    inner_state = initial_state[q0id : q1id + 1]
    outer_line = list(reversed(loop[q1id:] + loop[: q0id + 1]))
    outer_state = list(reversed(initial_state[q1id:] + initial_state[: q0id + 1]))
    if len(inner_line) <= len(outer_line):
        line_0 = outer_line
        state_0 = outer_state
        line_1 = inner_line
        state_1 = inner_state
    else:
        line_0 = inner_line
        state_0 = inner_state
        line_1 = outer_line
        state_1 = outer_state
    for line_id, line, state in [[0, line_0, state_0], [1, line_1, state_1]]:
        depth = len(line) // 2
        line_piece0 = line[:depth]
        state_piece0 = state[:depth]
        line_piece1 = list(reversed(line[depth:]))
        state_piece1 = list(reversed(state[depth:]))
        for qid, (ql, qr) in enumerate(zip(line_piece0[:-1], line_piece0[1:])):
            if sum(state_piece0[qid + 1 :]) == 0:
                continue
            if state_piece0[qid] == 1 or (line_id + qid == 0 and len(line_1) > 2):
                circuit = cnot_or_cmnot(ql, qr)
            else:
                circuit = swap(ql, qr)
            circuit_list.append(circuit)
        for qid, (ql, qr) in enumerate(zip(line_piece1[:-1], line_piece1[1:])):
            if sum(state_piece1[qid + 1 :]) == 0:
                continue
            if state_piece1[qid] == 1 or (line_id + qid == 0 and len(line_1) > 2):
                circuit = cnot_or_cmnot(ql, qr)
            else:
                circuit = swap(ql, qr)
            circuit_list.append(circuit)
    if inverse is True:
        circuit_list = reversed(circuit_list)
    circuit = cirq.Circuit()
    for new_circuit in circuit_list:
        circuit = safe_tetris_circuits(circuit, new_circuit)
    return circuit

