import cirq
from recirq.seniority_zero.circuits_expt.core import starting_pair_loop_on_lattice
from recirq.seniority_zero.circuits_simplified.gates import GSGate
def brickwall_loop_layer(
    qubits: List[cirq.GridQubit], layer_params: List[float], offset: int, gate: Type[cirq.Gate]
) -> Generator:
    pairs = [
        (qubits[(2 * ii + offset) % len(qubits)], qubits[(2 * ii + 1 + offset) % len(qubits)])
        for ii in range(len(qubits))
    ]
    for param, (q0, q1) in zip(layer_params, pairs):
        yield gate(param).on(q0, q1)
def brickwall_givens_swap_network(
    qubits: List[cirq.GridQubit], params: List[float], depth: int, inverse: Optional[bool] = False
) -> Generator:
    assert depth * len(qubits) // 2 == len(params)
    nparams_layer = len(qubits) // 2
    layer_indices = range(depth)
    if inverse:
        layer_indices = reversed(layer_indices)
    for layer_id in layer_indices:
        layer_params = params[layer_id * nparams_layer : (layer_id + 1) * nparams_layer]
        yield brickwall_loop_layer(qubits, layer_params, layer_id % 2, GSGate)
def GHZ_prep_loop_on_lattice(loop: List[cirq.GridQubit], initial_state: List[int]) -> Generator:
    init_pair = starting_pair_loop_on_lattice(loop, initial_state)
    yield cirq.CNOT(init_pair[0], init_pair[1])
    q0id = loop.index(init_pair[0])
    q1id = loop.index(init_pair[1])
    inner_line = loop[q0id : q1id + 1]
    inner_state = initial_state[q0id : q1id + 1]
    outer_line = list(reversed(loop[q1id:] + loop[: q0id + 1]))
    outer_state = list(reversed(initial_state[q1id:] + initial_state[: q0id + 1]))
    if len(inner_line) <= len(outer_line):
        line_0 = outer_line
        state_0 = outer_state
        line_1 = inner_line
        state_1 = inner_state
    else:
        line_0 = inner_line
        state_0 = inner_state
        line_1 = outer_line
        state_1 = outer_state
    for line_id, line, state in [[0, line_0, state_0], [1, line_1, state_1]]:
        depth = len(line) // 2
        line_piece0 = line[:depth]
        state_piece0 = state[:depth]
        line_piece1 = list(reversed(line[depth:]))
        state_piece1 = list(reversed(state[depth:]))
        for qid, (ql, qr) in enumerate(zip(line_piece0[:-1], line_piece0[1:])):
            if sum(state_piece0[qid + 1 :]) == 0:
                continue
            if state_piece0[qid] == 1 or (line_id + qid == 0 and len(line_1) > 2):
                yield cirq.CNOT(ql, qr)
            else:
                yield cirq.SWAP(ql, qr)
        for qid, (ql, qr) in enumerate(zip(line_piece1[:-1], line_piece1[1:])):
            if sum(state_piece1[qid + 1 :]) == 0:
                continue
            if state_piece1[qid] == 1 or (line_id + qid == 0 and len(line_1) > 2):
                yield cirq.CNOT(ql, qr)
            else:
                yield cirq.SWAP(ql, qr)
def lochschmidt_echo(circuit: cirq.Circuit, qubits: List[cirq.GridQubit]) -> Generator:
    circuit = cirq.drop_terminal_measurements(circuit)
    yield circuit
    yield cirq.inverse(circuit)
    yield [cirq.measure(qubit, key=str(qubit)) for qubit in qubits]

from typing import Generator, List
import cirq
import numpy as np
class GSGate(cirq.Gate):
    def __init__(self, angle: float):
        super(GSGate, self)
        self.angle = angle
    def _num_qubits_(self) -> int:
        return 2
    def _unitary_(self) -> np.ndarray:
        return np.array(
            [
                [1, 0, 0, 0],
                [0, np.sin(self.angle), np.cos(self.angle), 0],
                [0, np.cos(self.angle), -np.sin(self.angle), 0],
                [0, 0, 0, 1],
            ]
        )
    def _decompose_(self, qubits: List[cirq.Qid]) -> Generator:
        q0, q1 = qubits
        yield cirq.PhasedXZGate(x_exponent=0.5, axis_phase_exponent=-0.5, z_exponent=0).on(q0)
        yield cirq.CZ(q0, q1)
        yield [
            cirq.PhasedXZGate(x_exponent=0.5, axis_phase_exponent=0.5, z_exponent=0).on(q0),
            cirq.PhasedXZGate(
                x_exponent=self.angle / np.pi + 0.5, axis_phase_exponent=-0.5, z_exponent=1
            ).on(q1),
        ]
        yield cirq.CZ(q0, q1)
        yield [
            cirq.PhasedXZGate(x_exponent=0.5, axis_phase_exponent=-0.5, z_exponent=0).on(q0),
            cirq.PhasedXZGate(
                x_exponent=self.angle / np.pi + 0.5, axis_phase_exponent=-0.5, z_exponent=1
            ).on(q1),
        ]
        yield cirq.CZ(q0, q1)
        yield cirq.PhasedXZGate(x_exponent=0.5, axis_phase_exponent=0.5, z_exponent=0).on(q0)
    def __pow__(self, exponent: float) -> cirq.Gate:
        if exponent == -1:
            return GSGate(self.angle)
        raise NotImplementedError
    def _circuit_diagram_info_(self, args) -> List[str]:
        return [f"GS({self.angle})"] * self.num_qubits()
class ZIpXYRotationGate(cirq.Gate):
    def __init__(self, angle: float):
        super(ZIpXYRotationGate, self)
        self.angle = angle
    def _num_qubits_(self) -> int:
        return 2
    def _unitary_(self) -> np.ndarray:
        return np.array(
            [
                [np.exp(-1j * self.angle / 2), 0, 0, 0],
                [0, np.cos(-self.angle / 2), 1j * np.sin(-self.angle / 2), 0],
                [0, 1j * np.sin(-self.angle / 2), np.cos(-self.angle / 2), 0],
                [0, 0, 0, np.exp(1j * self.angle / 2)],
            ]
        )
    def _decompose_(self, qubits: List[cirq.Qid]) -> Generator:
        yield GSGate(np.pi / 4).on(*qubits)
        yield cirq.rz(self.angle).on(qubits[0])
        yield GSGate(np.pi / 4).on(*qubits)
    def __pow__(self, exponent: float) -> cirq.Gate:
        return ZIpXYRotationGate(self.angle * exponent)
    def _circuit_diagram_info_(self, args) -> List[str]:
        return [f"ZIpXY({self.theta})"] * self.num_qubits()
class ZImXYRotationGate(cirq.Gate):
    def __init__(self, angle: float):
        super(ZImXYRotationGate, self)
        self.angle = angle
    def _num_qubits_(self) -> int:
        return 2
    def _unitary_(self) -> np.ndarray:
        return np.array(
            [
                [np.exp(-1j * self.angle / 2), 0, 0, 0],
                [0, np.cos(-self.angle / 2), -1j * np.sin(-self.angle / 2), 0],
                [0, -1j * np.sin(-self.angle / 2), np.cos(-self.angle / 2), 0],
                [0, 0, 0, np.exp(1j * self.angle / 2)],
            ]
        )
    def _decompose_(self, qubits: List[cirq.Qid]) -> Generator:
        yield GSGate(np.pi / 4).on(*qubits)
        yield cirq.rz(self.angle).on(qubits[1])
        yield GSGate(np.pi / 4).on(*qubits)
    def __pow__(self, exponent: float) -> cirq.Gate:
        return ZImXYRotationGate(self.angle * exponent)
    def _circuit_diagram_info_(self, args) -> List[str]:
        return [f"ZImXY({self.theta})"] * self.num_qubits()
class ZZRotationGate(cirq.Gate):
    def __init__(self, angle: float):
        super(ZZRotationGate, self)
        self.angle = angle
    def _num_qubits_(self) -> int:
        return 2
    def _unitary_(self) -> np.ndarray:
        return np.array(
            [
                [np.exp(1j * self.angle), 0, 0, 0],
                [0, np.exp(-1j * self.angle), 0, 0],
                [0, 0, np.exp(-1j * self.angle), 0],
                [0, 0, 0, np.exp(1j * self.angle)],
            ]
        )
    def _decompose_(self, qubits: List[cirq.Qid]) -> Generator:
        q0, q1 = qubits
        yield cirq.PhasedXZGate(x_exponent=0.5, axis_phase_exponent=-0.5, z_exponent=0).on(q1)
        yield cirq.CZ(q0, q1)
        yield cirq.PhasedXZGate(
            x_exponent=2 * self.angle / np.pi, axis_phase_exponent=0, z_exponent=0
        ).on(q1)
        yield cirq.CZ(q0, q1)
        yield cirq.PhasedXZGate(x_exponent=0.5, axis_phase_exponent=0.5, z_exponent=0).on(q1)
    def __pow__(self, exponent: float) -> cirq.Gate:
        return ZZRotationGate(self.angle * exponent)
    def _circuit_diagram_info_(self, args) -> List[str]:
        return [f"rZZ({self.theta})"] * self.num_qubits()

from itertools import product
from typing import List, Optional, Tuple
import cirq
import numpy as np
import openfermion as of
class RGDOCI:
    def __init__(self, g_value: float, norbs: int):
        r
        self.g_value = g_value
        self.norbs = norbs
        self.n_qubits = norbs
    def get_spinorb_ints(self) -> Tuple[np.ndarray, np.ndarray]:
        r
        spatial_orbs = self.norbs
        h1 = np.diag(np.arange(spatial_orbs) + 1)
        h1 = np.kron(h1, np.eye(2))
        h2 = np.zeros((2 * spatial_orbs,) * 4)
        for p, q in product(range(spatial_orbs), repeat=2):
            if p != q:
                h2[2 * p, 2 * p + 1, 2 * q + 1, 2 * q] = self.g_value / 2
                h2[2 * p + 1, 2 * p, 2 * q, 2 * q + 1] = self.g_value / 2
        return h1, h2
    def get_spinorb_ints_ov_basis(self) -> Tuple[np.ndarray, np.ndarray]:
        norbs = self.norbs
        _, h2 = self.get_spinorb_ints()
        perm_order = [(xx, (norbs // 2) + xx) for xx in range(norbs // 2)]
        perm_order = [k for pair in perm_order for k in pair]
        h1 = np.diag(np.arange(norbs) + 1)
        h1 = h1[:, perm_order]
        h1 = h1[perm_order, :]
        h1 = np.kron(h1, np.eye(2))
        return h1, h2
    def get_cc_spinorbs(self) -> Tuple[np.ndarray, np.ndarray]:
        h1, h2 = self.get_spinorb_ints()
        antih2 = 0.5 * (h2 - np.einsum('ijlk', h2))
        return h1, antih2
    def get_fermion_ham(self) -> of.FermionOperator:
        spatial_orbs = self.norbs
        h1, h2 = self.get_spinorb_ints()
        fham = of.FermionOperator()
        for pp in range(spatial_orbs):
            fham += of.FermionOperator(
                ((2 * pp, 1), (2 * pp, 0)), coefficient=float(h1[2 * pp, 2 * pp])
            )
            fham += of.FermionOperator(
                ((2 * pp + 1, 1), (2 * pp + 1, 0)), coefficient=float(h1[2 * pp + 1, 2 * pp + 1])
            )
        for p, q in product(range(spatial_orbs), repeat=2):
            if p != q:
                ab = ((2 * p, 1), (2 * p + 1, 1), (2 * q + 1, 0), (2 * q, 0))
                ba = ((2 * p + 1, 1), (2 * p, 1), (2 * q, 0), (2 * q + 1, 0))
                fham += of.FermionOperator(ab, coefficient=h2[2 * p, 2 * p + 1, 2 * q + 1, 2 * q])
                fham += of.FermionOperator(ba, coefficient=h2[2 * p + 1, 2 * p, 2 * q, 2 * q + 1])
        return fham
    def get_fermion_ham_ov_basis(self) -> of.FermionOperator:
        spatial_orbs = self.norbs
        h1, h2 = self.get_spinorb_ints_ov_basis()
        fham = of.FermionOperator()
        for pp in range(spatial_orbs):
            fham += of.FermionOperator(
                ((2 * pp, 1), (2 * pp, 0)), coefficient=float(h1[2 * pp, 2 * pp])
            )
            fham += of.FermionOperator(
                ((2 * pp + 1, 1), (2 * pp + 1, 0)), coefficient=float(h1[2 * pp + 1, 2 * pp + 1])
            )
        for p, q in product(range(spatial_orbs), repeat=2):
            if p != q:
                ab = ((2 * p, 1), (2 * p + 1, 1), (2 * q + 1, 0), (2 * q, 0))
                ba = ((2 * p + 1, 1), (2 * p, 1), (2 * q, 0), (2 * q + 1, 0))
                fham += of.FermionOperator(ab, coefficient=h2[2 * p, 2 * p + 1, 2 * q + 1, 2 * q])
                fham += of.FermionOperator(ba, coefficient=h2[2 * p + 1, 2 * p, 2 * q, 2 * q + 1])
        return fham
    def get_qubit_hamiltonian(self) -> Tuple[of.QubitOperator, float]:
        r
        spatial_orbs = self.norbs
        qham = of.QubitOperator()
        h1 = np.diag(np.arange(spatial_orbs) + 1)
        constant = sum(np.diagonal(h1))
        for pp in range(spatial_orbs):
            qham += of.QubitOperator((pp, 'Z'), coefficient=float(-h1[pp, pp]))
            for qq in range(spatial_orbs):
                if pp != qq:
                    qham += of.QubitOperator(((pp, 'X'), (qq, 'X')), coefficient=self.g_value / 4)
                    qham += of.QubitOperator(((pp, 'Y'), (qq, 'Y')), coefficient=self.g_value / 4)
        return qham, float(constant)
    def get_qubit_hamiltonian_ov_basis(
        self,
        reverse_order: Optional[bool]=False
    ) -> Tuple[of.QubitOperator, float]:
        r
        spatial_orbs = self.norbs
        qham = of.QubitOperator()
        if reverse_order:
            h1 = np.diag((np.arange(spatial_orbs) + 1)[::-1])
        else:
            h1 = np.diag(np.arange(spatial_orbs) + 1)
        perm_order = [(xx, (self.norbs // 2) + xx) for xx in range(self.norbs // 2)]
        perm_order = [k for pair in perm_order for k in pair]
        h1 = h1[:, perm_order]
        h1 = h1[perm_order, :]
        constant = sum(np.diagonal(h1))
        for pp in range(spatial_orbs):
            qham += of.QubitOperator((pp, 'Z'), coefficient=float(-h1[pp, pp]))
            for qq in range(spatial_orbs):
                if pp != qq:
                    qham += of.QubitOperator(((pp, 'X'), (qq, 'X')), coefficient=self.g_value / 4)
                    qham += of.QubitOperator(((pp, 'Y'), (qq, 'Y')), coefficient=self.g_value / 4)
        return qham, float(constant)
    def get_cirq_operator(
        self,
        qubits: List[cirq.Qid],
        ov_basis: Optional[bool]=False
    ) -> cirq.PauliSum:
        if len(qubits) != self.norbs:
            raise ValueError("Number of qubits is not consistent with the problem size")
        if ov_basis:
            qubit_operator, constant = self.get_qubit_hamiltonian_ov_basis()
        else:
            qubit_operator, constant = self.get_qubit_hamiltonian()
        self.constant = constant
        qubit_map = dict(zip(range(self.norbs), qubits))
        cirq_pauli_terms = []
        for term, val in qubit_operator.terms.items():
            pauli_term_dict = dict([(qubit_map[xx], yy) for xx, yy in term])
            pauli_term = cirq.PauliString(pauli_term_dict, coefficient=val)
            cirq_pauli_terms.append(pauli_term)
        return cirq.PauliSum().from_pauli_strings(cirq_pauli_terms)

