import abc
from typing import Sequence, Optional
import numpy
import cirq
from openfermion.linalg import fit_known_frequencies
from openfermion.circuits import standard_vpe_rotation_set
class _VPEEstimator(metaclass=abc.ABCMeta):
    @abc.abstractmethod
    def get_simulation_points(self) -> numpy.ndarray:
    @abc.abstractmethod
    def get_expectation_value(self, phase_function: numpy.ndarray) -> numpy.ndarray:
class PhaseFitEstimator(_VPEEstimator):
    def __init__(self, evals: numpy.ndarray, ref_eval: float = 0):
        self.evals = evals
        self.ref_eval = ref_eval
    def get_simulation_points(self, safe: bool = True) -> numpy.ndarray:
        if safe:
            numsteps = len(self.evals) * 2
            step_size = numpy.pi / (max(self.evals) - min(self.evals))
        else:
            numsteps = len(self.evals)
            step_size = numpy.pi / (max(self.evals) - min(self.evals))
        maxtime = step_size * (numsteps - 1)
        times = numpy.linspace(0, maxtime, numsteps)
        return times
    def get_amplitudes(self, phase_function: numpy.ndarray) -> numpy.ndarray:
        times = self.get_simulation_points()
        phase_function_shifted = numpy.array(phase_function) * numpy.exp(1j * times * self.ref_eval)
        amplitudes = fit_known_frequencies(phase_function_shifted, times, self.evals)
        return amplitudes
    def get_expectation_value(self, phase_function: numpy.ndarray) -> numpy.ndarray:
        amplitudes = self.get_amplitudes(phase_function)
        expectation_value = numpy.dot(numpy.abs(amplitudes), self.evals) / numpy.sum(
            numpy.abs(amplitudes)
        )
        return expectation_value
def get_phase_function(
    results: Sequence[cirq.Result],
    qubits: Sequence[cirq.Qid],
    target_qid: int,
    rotation_set: Optional[Sequence] = None,
):
    hs_index = 2 ** (len(qubits) - target_qid - 1)
    if rotation_set is None:
        rotation_set = standard_vpe_rotation_set
    phase_function = 0
    if len(results) != len(rotation_set):
        raise ValueError(
            "I have an incorrect number of TrialResults "
            "in results. Correct length should be: {}".format(len(rotation_set))
        )
    for result, rdata in zip(results, rotation_set):
        total_shots = result.data['msmt'].count()
        msmt_counts = result.data['msmt'].value_counts()
        if 0 in msmt_counts:
            vprob0 = msmt_counts[0] / total_shots
        else:
            vprob0 = 0
        if hs_index in msmt_counts:
            vprob1 = msmt_counts[hs_index] / total_shots
        else:
            vprob1 = 0
        phase_function += rdata[0] * (vprob0 - vprob1)
    return phase_function

from typing import Optional, Sequence
import cirq
from openfermion.ops.operators import QubitOperator
from openfermion.utils.operator_utils import count_qubits
def _qubit_operator_term_to_pauli_string(
    term: dict, qubits: Sequence[cirq.Qid]
) -> cirq.PauliString:
    ind_ops, coeff = term
    return cirq.PauliString(dict((qubits[ind], op) for ind, op in ind_ops), coeff)
def qubit_operator_to_pauli_sum(
    operator: QubitOperator, qubits: Optional[Sequence[cirq.Qid]] = None
) -> cirq.PauliSum:
    if not isinstance(operator, QubitOperator):
        raise TypeError('Input must be a QubitOperator.')
    if qubits is None:
        qubits = cirq.LineQubit.range(count_qubits(operator))
    pauli_sum = cirq.PauliSum()
    for pauli in operator.terms.items():
        pauli_sum += _qubit_operator_term_to_pauli_string(pauli, qubits)
    return pauli_sum

from typing import Optional
import numpy as np
import sympy
import cirq
class FSwapPowGate(cirq.EigenGate, cirq.InterchangeableQubitsGate):
    def num_qubits(self):
        return 2
    def _eigen_components(self):
        return [
            (0,
             np.array([[1, 0, 0, 0],
                       [0, 0.5, 0.5, 0],
                       [0, 0.5, 0.5, 0],
                       [0, 0, 0, 0]])),
            (1,
             np.array([[0, 0, 0, 0],
                       [0, 0.5, -0.5, 0],
                       [0, -0.5, 0.5, 0],
                       [0, 0, 0, 1]])),
        ]
    def _apply_unitary_(self, args: cirq.ApplyUnitaryArgs) -> Optional[np.ndarray]:
        if self.exponent != 1:
            return NotImplemented
        oi = args.subspace_index(0b01)
        io = args.subspace_index(0b10)
        ii = args.subspace_index(0b11)
        args.available_buffer[oi] = args.target_tensor[oi]
        args.target_tensor[oi] = args.target_tensor[io]
        args.target_tensor[io] = args.available_buffer[oi]
        args.target_tensor[ii] *= -1
        return args.target_tensor
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        if args.use_unicode_characters:
            symbols = '×ᶠ', '×ᶠ'
        else:
            symbols = 'fswap', 'fswap'
        return cirq.CircuitDiagramInfo(wire_symbols=symbols, exponent=self._diagram_exponent(args))
    def __str__(self) -> str:
        if self.exponent == 1:
            return 'FSWAP'
        return 'FSWAP**{!r}'.format(self.exponent)
    def __repr__(self) -> str:
        if self.exponent == 1:
            return 'openfermion.FSWAP'
        return '(openfermion.FSWAP**{!r})'.format(self.exponent)
def Rxxyy(rads: float) -> cirq.ISwapPowGate:
    pi = sympy.pi if isinstance(rads, sympy.Basic) else np.pi
    return cirq.ISwapPowGate(exponent=-2 * rads / pi)
def Ryxxy(rads: float) -> cirq.PhasedISwapPowGate:
    pi = sympy.pi if isinstance(rads, sympy.Basic) else np.pi
    return cirq.PhasedISwapPowGate(exponent=2 * rads / pi)
def Rzz(rads: float) -> cirq.ZZPowGate:
    pi = sympy.pi if isinstance(rads, sympy.Basic) else np.pi
    return cirq.ZZPowGate(exponent=2 * rads / pi, global_shift=-0.5)
def rot11(rads: float) -> cirq.CZPowGate:
    pi = sympy.pi if isinstance(rads, sympy.Basic) else np.pi
    return cirq.CZ ** (rads / pi)
FSWAP = FSwapPowGate()

