from typing import Iterable, List, Optional, Sequence, Tuple, Union, cast
import numpy
import cirq
from openfermion import circuits, linalg
def bogoliubov_transform(
    qubits: Sequence[cirq.Qid],
    transformation_matrix: numpy.ndarray,
    initial_state: Optional[Union[int, Sequence[int]]] = None,
) -> cirq.OP_TREE:
    r
    n_qubits = len(qubits)
    shape = transformation_matrix.shape
    if shape not in [(n_qubits, n_qubits), (n_qubits, 2 * n_qubits)]:
        raise ValueError(
            'Bad shape for transformation_matrix. '
            'Expected {} or {} but got {}.'.format(
                (n_qubits, n_qubits), (n_qubits, 2 * n_qubits), shape
            )
        )
    if isinstance(initial_state, int):
        initial_state = _occupied_orbitals(initial_state, n_qubits)
    initially_occupied_orbitals = cast(Optional[Sequence[int]], initial_state)
    if _is_spin_block_diagonal(transformation_matrix):
        up_block = transformation_matrix[: n_qubits // 2, : n_qubits // 2]
        up_qubits = qubits[: n_qubits // 2]
        down_block = transformation_matrix[n_qubits // 2 :, n_qubits // 2 :]
        down_qubits = qubits[n_qubits // 2 :]
        if initially_occupied_orbitals is None:
            up_orbitals = None
            down_orbitals = None
        else:
            up_orbitals = [i for i in initially_occupied_orbitals if i < n_qubits // 2]
            down_orbitals = [
                i - n_qubits // 2 for i in initially_occupied_orbitals if i >= n_qubits // 2
            ]
        yield bogoliubov_transform(up_qubits, up_block, initial_state=up_orbitals)
        yield bogoliubov_transform(down_qubits, down_block, initial_state=down_orbitals)
        return
    if shape == (n_qubits, n_qubits):
        yield _slater_basis_change(qubits, transformation_matrix, initially_occupied_orbitals)
    else:
        yield _gaussian_basis_change(qubits, transformation_matrix, initially_occupied_orbitals)
def _is_spin_block_diagonal(matrix) -> bool:
    n = matrix.shape[0]
    if n % 2:
        return False
    max_upper_right = numpy.max(numpy.abs(matrix[: n // 2, n // 2 :]))
    max_lower_left = numpy.max(numpy.abs(matrix[n // 2 :, : n // 2]))
    return numpy.isclose(max_upper_right, 0.0) and numpy.isclose(max_lower_left, 0.0)
def _occupied_orbitals(computational_basis_state: int, n_qubits) -> List[int]:
    bitstring = format(computational_basis_state, 'b').zfill(n_qubits)
    return [j for j in range(len(bitstring)) if bitstring[j] == '1']
def _slater_basis_change(
    qubits: Sequence[cirq.Qid],
    transformation_matrix: numpy.ndarray,
    initially_occupied_orbitals: Optional[Sequence[int]],
) -> cirq.OP_TREE:
    n_qubits = len(qubits)
    if initially_occupied_orbitals is None:
        decomposition, diagonal = linalg.givens_decomposition_square(transformation_matrix)
        circuit_description = list(reversed(decomposition))
        yield (cirq.rz(rads=numpy.angle(diagonal[j])).on(qubits[j]) for j in range(n_qubits))
    else:
        initially_occupied_orbitals = cast(Sequence[int], initially_occupied_orbitals)
        transformation_matrix = transformation_matrix[list(initially_occupied_orbitals)]
        n_occupied = len(initially_occupied_orbitals)
        initially_occupied_orbitals_set = set(initially_occupied_orbitals)
        yield (
            cirq.X(qubits[j])
            for j in range(n_qubits)
            if (j < n_occupied) != (j in initially_occupied_orbitals_set)
        )
        circuit_description = circuits.slater_determinant_preparation_circuit(transformation_matrix)
    yield _ops_from_givens_rotations_circuit_description(qubits, circuit_description)
def _gaussian_basis_change(
    qubits: Sequence[cirq.Qid],
    transformation_matrix: numpy.ndarray,
    initially_occupied_orbitals: Optional[Sequence[int]],
) -> cirq.OP_TREE:
    n_qubits = len(qubits)
    left_block = transformation_matrix[:, :n_qubits]
    right_block = transformation_matrix[:, n_qubits:]
    transformation_matrix = numpy.block([numpy.conjugate(right_block), numpy.conjugate(left_block)])
    decomposition, left_decomposition, _, left_diagonal = linalg.fermionic_gaussian_decomposition(
        transformation_matrix
    )
    if initially_occupied_orbitals is not None and len(initially_occupied_orbitals) == 0:
        circuit_description = list(reversed(decomposition))
    else:
        if initially_occupied_orbitals is None:
            yield (
                cirq.rz(rads=numpy.angle(left_diagonal[j])).on(qubits[j]) for j in range(n_qubits)
            )
        circuit_description = list(reversed(decomposition + left_decomposition))
    yield _ops_from_givens_rotations_circuit_description(qubits, circuit_description)
def _ops_from_givens_rotations_circuit_description(
    qubits: Sequence[cirq.Qid],
    circuit_description: Iterable[Iterable[Union[str, Tuple[int, int, float, float]]]],
) -> cirq.OP_TREE:
    for parallel_ops in circuit_description:
        for op in parallel_ops:
            if op == 'pht':
                yield cirq.X(qubits[-1])
            else:
                i, j, theta, phi = cast(Tuple[int, int, float, float], op)
                yield circuits.Ryxxy(theta).on(qubits[i], qubits[j])
                yield cirq.Z(qubits[j]) ** (phi / numpy.pi)

from typing import Iterable, List, Sequence
import numpy as np
from sympy.ntheory import factorint
import cirq
import cirq.contrib.acquaintance.permutation
from openfermion.circuits.gates import FSWAP
from .bogoliubov_transform import bogoliubov_transform
class _F0Gate(cirq.MatrixGate):
    r
    def __init__(self):
        cirq.MatrixGate.__init__(
            self,
            np.array(
                [
                    [1, 0, 0, 0],
                    [0, -(2 ** (-0.5)), 2 ** (-0.5), 0],
                    [0, 2 ** (-0.5), 2 ** (-0.5), 0],
                    [0, 0, 0, -1],
                ]
            ),
            qid_shape=(2, 2),
        )
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        if args.use_unicode_characters:
            symbols = 'F₀', 'F₀'
        else:
            symbols = 'F0', 'F0'
        return cirq.CircuitDiagramInfo(wire_symbols=symbols)
class _TwiddleGate(cirq.Gate):
    r
    def __init__(self, k, n):
        self.k = k
        self.n = n
    def _num_qubits_(self) -> int:
        return 1
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        if args.use_unicode_characters:
            symbols = ('ω^{}_{}'.format(self.k, self.n),)
        else:
            symbols = ('w^{}_{}'.format(self.k, self.n),)
        return cirq.CircuitDiagramInfo(wire_symbols=symbols)
    def _decompose_(self, qubits: Iterable[cirq.Qid]):
        (q,) = qubits
        exponent = -2 * self.k / self.n
        yield cirq.ZPowGate(exponent=exponent, global_shift=0).on(q)
F0 = _F0Gate()
def ffft(qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
    r
    n = len(qubits)
    if n == 0:
        raise ValueError('Number of qubits is 0.')
    if n == 1:
        return []
    factors = [f for f, count in factorint(n).items() for _ in range(count)]
    return _ffft(qubits, factors)
def _ffft_prime(qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
    def fft_matrix(n):
        unit = np.exp(-2j * np.pi / n)
        return np.array([[unit ** (j * k) for k in range(n)] for j in range(n)]) / np.sqrt(n)
    n = len(qubits)
    if n == 2:
        return F0(*qubits)
    else:
        return bogoliubov_transform(qubits, fft_matrix(n))
def _ffft(qubits: Sequence[cirq.Qid], factors: List[int]) -> cirq.OP_TREE:
    if len(factors) == 1:
        return _ffft_prime(qubits)
    n = len(qubits)
    factors_y = factors[:1]
    factors_x = factors[1:]
    ny = np.prod(factors_y)
    nx = n // ny
    permutation = [(i % ny) * nx + (i // ny) for i in range(n)]
    permutation_gate = _permute(qubits, permutation)
    operations = []
    operations.append(permutation_gate)
    for y in range(ny):
        operations.append(_ffft(qubits[nx * y : nx * (y + 1)], factors_x))
    operations.append(cirq.inverse(permutation_gate))
    for x in range(nx):
        for y in range(1, ny):
            operations.append(_TwiddleGate(x * y, n).on(qubits[ny * x + y]))
        operations.append(_ffft(qubits[ny * x : ny * (x + 1)], factors_y))
    operations.append(permutation_gate)
    return operations
def _permute(qubits: Sequence[cirq.Qid], permutation: List[int]) -> cirq.OP_TREE:
    return cirq.contrib.acquaintance.permutation.LinearPermutationGate(
        len(qubits), {i: permutation[i] for i in range(len(permutation))}, FSWAP
    ).on(*qubits)

from typing import cast, Iterable, Sequence, Tuple
import numpy
import cirq
from openfermion.linalg import givens_matrix_elements, givens_rotate
from openfermion.circuits.gates import Ryxxy
class GivensTranspositionError(Exception):
    pass
class GivensMatrixError(Exception):
    pass
def optimal_givens_decomposition(
    qubits: Sequence[cirq.Qid], unitary: numpy.ndarray
) -> Iterable[cirq.Operation]:
    r
    N = unitary.shape[0]
    right_rotations = []
    left_rotations = []
    for i in range(1, N):
        if i % 2 == 1:
            for j in range(0, i):
                gmat = givens_matrix_elements(
                    unitary[N - j - 1, i - j - 1], unitary[N - j - 1, i - j - 1 + 1], which='left'
                )
                right_rotations.append((gmat.T, (i - j - 1, i - j)))
                givens_rotate(unitary, gmat.conj(), i - j - 1, i - j, which='col')
        else:
            for j in range(1, i + 1):
                gmat = givens_matrix_elements(
                    unitary[N + j - i - 1 - 1, j - 1], unitary[N + j - i - 1, j - 1], which='right'
                )
                left_rotations.append((gmat, (N + j - i - 2, N + j - i - 1)))
                givens_rotate(unitary, gmat, N + j - i - 2, N + j - i - 1, which='row')
    new_left_rotations = []
    for left_gmat, (i, j) in reversed(left_rotations):
        phase_matrix = numpy.diag([unitary[i, i], unitary[j, j]])
        matrix_to_decompose = left_gmat.conj().T.dot(phase_matrix)
        new_givens_matrix = givens_matrix_elements(
            matrix_to_decompose[1, 0], matrix_to_decompose[1, 1], which='left'
        )
        new_phase_matrix = matrix_to_decompose.dot(new_givens_matrix.T)
        if not numpy.allclose(new_phase_matrix.dot(new_givens_matrix.conj()), matrix_to_decompose):
            raise GivensTranspositionError("Failed to shift the phase matrix " "from right to left")
        unitary[i, i], unitary[j, j] = new_phase_matrix[0, 0], new_phase_matrix[1, 1]
        new_left_rotations.append((new_givens_matrix.conj(), (i, j)))
    phases = numpy.diag(unitary)
    rotations = []
    ordered_rotations = []
    for gmat, (i, j) in list(reversed(new_left_rotations)) + list(
        map(lambda x: (x[0].conj().T, x[1]), reversed(right_rotations))
    ):
        ordered_rotations.append((gmat, (i, j)))
        if not numpy.isclose(gmat[0, 0].imag, 0.0):
            raise GivensMatrixError(
                "Givens matrix does not obey our convention that all elements "
                "in the first column are real"
            )
        if not numpy.isclose(gmat[1, 0].imag, 0.0):
            raise GivensMatrixError(
                "Givens matrix does not obey our convention that all elements "
                "in the first column are real"
            )
        theta = numpy.arcsin(numpy.real(gmat[1, 0]))
        phi = numpy.angle(gmat[1, 1])
        rotations.append((i, j, theta, phi))
    for op in reversed(rotations):
        i, j, theta, phi = cast(Tuple[int, int, float, float], op)
        if not numpy.isclose(phi, 0.0):
            yield cirq.Z(qubits[j]) ** (phi / numpy.pi)
        yield Ryxxy(-theta).on(qubits[i], qubits[j])
    for idx, phase in enumerate(phases):
        yield cirq.Z(qubits[idx]) ** (numpy.angle(phase) / numpy.pi)

from typing import Iterable, Optional, Sequence, Set, TYPE_CHECKING, Tuple, Union, cast
import numpy
import cirq
from openfermion.circuits.gates import Ryxxy
from openfermion.circuits.slater_determinants import (
    gaussian_state_preparation_circuit,
    slater_determinant_preparation_circuit,
)
if TYPE_CHECKING:
    import openfermion
def prepare_gaussian_state(
    qubits: Sequence[cirq.Qid],
    quadratic_hamiltonian: 'openfermion.QuadraticHamiltonian',
    occupied_orbitals: Optional[Union[Sequence[int], Tuple[Sequence[int], Sequence[int]]]] = None,
    initial_state: Union[int, Sequence[int]] = 0,
) -> cirq.OP_TREE:
    if not occupied_orbitals or isinstance(occupied_orbitals[0], int):
        occupied_orbitals = cast(Sequence[int], occupied_orbitals)
        yield _generic_gaussian_circuit(
            qubits, quadratic_hamiltonian, occupied_orbitals, initial_state
        )
    else:
        occupied_orbitals = cast(Tuple[Sequence[int], Sequence[int]], occupied_orbitals)
        yield _spin_symmetric_gaussian_circuit(
            qubits, quadratic_hamiltonian, occupied_orbitals, initial_state
        )
def _generic_gaussian_circuit(
    qubits: Sequence[cirq.Qid],
    quadratic_hamiltonian: 'openfermion.QuadraticHamiltonian',
    occupied_orbitals: Optional[Sequence[int]],
    initial_state: Union[int, Sequence[int]],
) -> cirq.OP_TREE:
    n_qubits = len(qubits)
    circuit_description, start_orbitals = gaussian_state_preparation_circuit(
        quadratic_hamiltonian, occupied_orbitals
    )
    if isinstance(initial_state, int):
        initially_occupied_orbitals = _occupied_orbitals(initial_state, n_qubits)
    else:
        initially_occupied_orbitals = initial_state  # type: ignore
    yield (
        cirq.X(qubits[j])
        for j in range(n_qubits)
        if (j in initially_occupied_orbitals) != (j in start_orbitals)
    )
    yield _ops_from_givens_rotations_circuit_description(qubits, circuit_description)
def _spin_symmetric_gaussian_circuit(
    qubits: Sequence[cirq.Qid],
    quadratic_hamiltonian: 'openfermion.QuadraticHamiltonian',
    occupied_orbitals: Tuple[Sequence[int], Sequence[int]],
    initial_state: Union[int, Sequence[int]],
) -> cirq.OP_TREE:
    n_qubits = len(qubits)
    if isinstance(initial_state, int):
        initially_occupied_orbitals = _occupied_orbitals(initial_state, n_qubits)
    else:
        initially_occupied_orbitals = initial_state  # type: ignore
    for spin_sector in range(2):
        circuit_description, start_orbitals = gaussian_state_preparation_circuit(
            quadratic_hamiltonian, occupied_orbitals[spin_sector], spin_sector=spin_sector
        )
        def index_map(i):
            return i + spin_sector * (n_qubits // 2)
        spin_indices = [index_map(i) for i in range(n_qubits // 2)]
        spin_qubits = [qubits[i] for i in spin_indices]
        yield (
            cirq.X(spin_qubits[j])
            for j in range(n_qubits // 2)
            if (index_map(j) in initially_occupied_orbitals)
            != (index_map(j) in [index_map(k) for k in start_orbitals])
        )
        yield _ops_from_givens_rotations_circuit_description(spin_qubits, circuit_description)
def prepare_slater_determinant(
    qubits: Sequence[cirq.Qid],
    slater_determinant_matrix: numpy.ndarray,
    initial_state: Union[int, Sequence[int]] = 0,
) -> cirq.OP_TREE:
    r
    n_qubits = len(qubits)
    circuit_description = slater_determinant_preparation_circuit(slater_determinant_matrix)
    n_occupied = slater_determinant_matrix.shape[0]
    if isinstance(initial_state, int):
        initially_occupied_orbitals = _occupied_orbitals(initial_state, n_qubits)
    else:
        initially_occupied_orbitals = initial_state  # type: ignore
    yield (
        cirq.X(qubits[j])
        for j in range(n_qubits)
        if (j < n_occupied) != (j in initially_occupied_orbitals)
    )
    yield _ops_from_givens_rotations_circuit_description(qubits, circuit_description)
def _occupied_orbitals(computational_basis_state: int, n_qubits) -> Set[int]:
    bitstring = format(computational_basis_state, 'b').zfill(n_qubits)
    return {j for j in range(len(bitstring)) if bitstring[j] == '1'}
def _ops_from_givens_rotations_circuit_description(
    qubits: Sequence[cirq.Qid],
    circuit_description: Iterable[Iterable[Union[str, Tuple[int, int, float, float]]]],
) -> cirq.OP_TREE:
    for parallel_ops in circuit_description:
        for op in parallel_ops:
            if op == 'pht':
                yield cirq.X(qubits[-1])
            else:
                i, j, theta, phi = cast(Tuple[int, int, float, float], op)
                yield Ryxxy(theta).on(qubits[i], qubits[j])
                yield cirq.Z(qubits[j]) ** (phi / numpy.pi)

