@pytest.mark.parametrize(
    'n_qubits, conserves_particle_number, occupied_orbitals, initial_state',
    [
        (4, True, None, 0b0010),
        (4, False, None, 0b1001),
        (5, True, None, 0),
        (5, False, None, 0b10101),
        (5, True, range(4), 0),
        (5, False, (0, 2, 3), [1, 2, 3, 4]),
    ],
)
