        yield swap_network(qubits, one_and_two_body_interaction, fermionic=True)
        qubits = qubits[::-1]
        yield (
            rot11(rads=-self.hamiltonian.one_body[i, i].real * time).on(control_qubit, qubits[i])
            for i in range(n_qubits)
