class SplitOperatorTrotterStep(TrotterStep):
    def __init__(self, hamiltonian: 'openfermion.DiagonalCoulombHamiltonian') -> None:
        quad_ham = ops.QuadraticHamiltonian(hamiltonian.one_body)
