from __future__ import annotations
import dataclasses
import numpy as np
import cirq
def bell_pair_prep_circuit(q0: cirq.GridQubit, q1: cirq.GridQubit) -> cirq.Circuit:
    return cirq.Circuit.from_moments(cirq.H.on_each(q0, q1), cirq.CZ(q0, q1), cirq.H(q1))
def state_prep_circuit(
    alice_data_qubits: tuple[cirq.GridQubit, cirq.GridQubit],
    bob_data_qubits: tuple[cirq.GridQubit, cirq.GridQubit],
) -> cirq.Circuit:
    a1, a2 = alice_data_qubits
    b1, b2 = bob_data_qubits
    return bell_pair_prep_circuit(a1, b1).zip(bell_pair_prep_circuit(a2, b2))
def construct_measure_circuit(
    alice_qubits: list[cirq.GridQubit],
    bob_qubits: list[cirq.GridQubit],
    mermin_row: int,
    mermin_col: int,
) -> cirq.Circuit:
    q = alice_qubits[1:3]  # data qubits
    m = (alice_qubits[0], alice_qubits[3])  # measure qubits
    if mermin_row == 0:
        alice_circuit = cirq.Circuit.from_moments(cirq.M(*q, key="alice"))
    elif mermin_row == 1:
        alice_circuit = cirq.Circuit.from_moments(cirq.H.on_each(*q), cirq.M(*q, key="alice"))
    elif mermin_row == 2:
        alice_circuit = cirq.Circuit.from_moments(
            cirq.CZ(*q),
            cirq.H.on_each(*q, *m),
            cirq.CZ.on_each(*zip(m, q)),
            cirq.H.on_each(*m),
            cirq.M(*m, key="alice"),
        )
    q = bob_qubits[1:3]  # data qubits
    m = (bob_qubits[0], bob_qubits[3])  # measure qubits
    if mermin_col == 0:
        bob_circuit = cirq.Circuit.from_moments(cirq.H(q[0]), cirq.M(*q, key="bob"))
    elif mermin_col == 1:
        bob_circuit = cirq.Circuit.from_moments(cirq.H(q[1]), cirq.M(*q, key="bob"))
    elif mermin_col == 2:
        bob_circuit = cirq.Circuit.from_moments(
            cirq.H(q[0]),
            cirq.CZ(*q),
            cirq.H.on_each(*q, *m),
            cirq.CZ.on_each(*zip(m, q)),
            cirq.H.on_each(*m),
            cirq.M(*m, key="bob"),
        )
    last_moment_circuit = cirq.Circuit.from_moments(
        cirq.Moment(alice_circuit[-1] + bob_circuit[-1])
    )
    if mermin_row == 0:
        circuit = bob_circuit[:-1] + last_moment_circuit
    elif mermin_row == 1:
        if mermin_col == 2:
            circuit = bob_circuit[:-2] + alice_circuit.zip(bob_circuit[-2:])
        else:
            circuit = alice_circuit[:-1].zip(bob_circuit[:-1]) + last_moment_circuit
    elif mermin_row == 2:
        if mermin_col == 2:
            circuit = (
                cirq.Circuit.from_moments(bob_circuit[0])
                + alice_circuit[:-1].zip(bob_circuit[1:-1])
                + last_moment_circuit
            )
        else:
            circuit = (
                alice_circuit[0:3]
                + cirq.Circuit.from_moments(cirq.Moment(alice_circuit[3] + bob_circuit[0]))
                + last_moment_circuit
            )
    return circuit
def construct_magic_square_circuit(
    alice_qubits: list[cirq.GridQubit],
    bob_qubits: list[cirq.GridQubit],
    mermin_row: int,
    mermin_col: int,
    add_dd: bool,
    dd_scheme: tuple[cirq.Gate, ...] = (cirq.X, cirq.Y, cirq.X, cirq.Y),
) -> cirq.Circuit:
    assert len(alice_qubits) == 4, f"Expected 4 qubits, but got {len(alice_qubits)}"
    assert len(bob_qubits) == 4, f"Expected 4 qubits, but got {len(bob_qubits)}"
    alice_data_qubits = (alice_qubits[1], alice_qubits[2])
    bob_data_qubits = (bob_qubits[1], bob_qubits[2])
    prep_circuit = state_prep_circuit(alice_data_qubits, bob_data_qubits)
    measure_circuit = construct_measure_circuit(alice_qubits, bob_qubits, mermin_row, mermin_col)
    circuit = prep_circuit + measure_circuit
    if add_dd:
        circuit = cirq.add_dynamical_decoupling(
            circuit, single_qubit_gate_moments_only=True, schema=dd_scheme
        )
    return circuit
@dataclasses.dataclass
class MagicSquareResult:
    alice_measurements: np.ndarray
    bob_measurements: np.ndarray
    def _generate_choices_from_rules(self) -> tuple[np.ndarray, np.ndarray]:
        repetitions = self.alice_measurements.shape[2]
        alice_choices = np.zeros((3, 3, repetitions, 3), dtype=bool)
        bob_choices = np.zeros((3, 3, repetitions, 3), dtype=bool)
        alice_choices[0, :, :, 0] = self.alice_measurements[0, :, :, 1]
        alice_choices[0, :, :, 1] = self.alice_measurements[0, :, :, 0]
        alice_choices[1, :, :, :2] = self.alice_measurements[1, :, :, :2]
        alice_choices[2, :, :, :2] = 1 - self.alice_measurements[2, :, :, :2]
        bob_choices[:, 0, :, 0] = self.bob_measurements[:, 0, :, 1]
        bob_choices[:, 0, :, 1] = self.bob_measurements[:, 0, :, 0]
        bob_choices[:, 1:, :, :2] = self.bob_measurements[:, 1:, :, :2]
        alice_choices[:, :, :, 2] = np.sum(alice_choices, axis=3) % 2
        bob_choices[:, :, :, 2] = 1 - (np.sum(bob_choices, axis=3) % 2)
        assert np.all((np.sum(alice_choices, axis=3) % 2) == 0)
        assert np.all((np.sum(bob_choices, axis=3) % 2) == 1)
        return alice_choices, bob_choices
    def generate_choices(self, seed: int | None = None) -> tuple[np.ndarray, np.ndarray]:
        return self._generate_choices_from_rules()
    def get_win_matrix(self, seed: int | None = None) -> np.ndarray:
        alice_choices, bob_choices = self.generate_choices(seed)
        win_matrix = np.zeros((3, 3))
        for row in range(3):
            for col in range(3):
                win_matrix[row, col] = np.mean(
                    alice_choices[row, col, :, col] == bob_choices[row, col, :, row]
                )
        return win_matrix
def run_magic_square_game(
    sampler: cirq.Sampler,
    alice_qubits: list[cirq.GridQubit],
    bob_qubits: list[cirq.GridQubit],
    repetitions: int = 10_000,
    add_dd: bool = True,
    dd_scheme: tuple[cirq.Gate, ...] = (cirq.X, cirq.Y, cirq.X, cirq.Y),
) -> MagicSquareResult:
    all_circuits = []
    for mermin_row in range(3):
        for mermin_col in range(3):
            all_circuits.append(
                construct_magic_square_circuit(
                    alice_qubits, bob_qubits, mermin_row, mermin_col, add_dd, dd_scheme
                )
            )
    results = sampler.run_batch(all_circuits, repetitions=repetitions)
    alice_measurements = np.zeros((3, 3, repetitions, len(alice_qubits) - 2), dtype=bool)
    bob_measurements = np.zeros((3, 3, repetitions, len(bob_qubits) - 2), dtype=bool)
    idx = 0
    for row in range(3):
        for col in range(3):
            alice_measurements[row, col] = results[idx][0].measurements["alice"]
            bob_measurements[row, col] = results[idx][0].measurements["bob"]
            idx += 1
    return MagicSquareResult(alice_measurements, bob_measurements)
def main():
    sampler = cirq.Simulator()
    alice_qubits = cirq.GridQubit.rect(1, 4, 0, 0)
    bob_qubits = cirq.GridQubit.rect(1, 4, 1, 0)
    add_dd = False
    for row in range(3):
        for col in range(3):
            print(f'(row, col) = ({row}, {col})')
            print(construct_magic_square_circuit(alice_qubits, bob_qubits, row, col, add_dd))
            print('\n')
    result = run_magic_square_game(sampler, alice_qubits, bob_qubits, add_dd=add_dd)
    print('Win rate for all 9 possible inputs, out of 10,000 repetitions each:')
    print(result.get_win_matrix())
if __name__ == '__main__':
    main()

from __future__ import annotations
import argparse
import fractions
import math
import random
from collections.abc import Callable, Sequence
import sympy
import cirq
parser = argparse.ArgumentParser(description='Factorization demo.')
parser.add_argument('n', type=int, help='composite integer to factor')
parser.add_argument(
    '--order_finder',
    type=str,
    choices=('naive', 'quantum'),
    default='naive',
    help=(
        'order finder to use; must be either "naive" '
        'for a naive classical algorithm or "quantum" '
        'for a quantum circuit; note that in practice '
        '"quantum" is substantially slower since it '
        'incurs the overhead of classical simulation.'
    ),
)
def naive_order_finder(x: int, n: int) -> int | None:
    if x < 2 or n <= x or math.gcd(x, n) > 1:
        raise ValueError(f'Invalid x={x} for modulus n={n}.')
    r, y = 1, x
    while y != 1:
        y = (x * y) % n
        r += 1
    return r
class ModularExp(cirq.ArithmeticGate):
    def __init__(
        self, target: Sequence[int], exponent: int | Sequence[int], base: int, modulus: int
    ) -> None:
        if len(target) < modulus.bit_length():
            raise ValueError(
                f'Register with {len(target)} qubits is too small for modulus {modulus}'
            )
        self.target = target
        self.exponent = exponent
        self.base = base
        self.modulus = modulus
    def registers(self) -> Sequence[int | Sequence[int]]:
        return self.target, self.exponent, self.base, self.modulus
    def with_registers(self, *new_registers: int | Sequence[int]) -> ModularExp:
        if len(new_registers) != 4:
            raise ValueError(
                f'Expected 4 registers (target, exponent, base, '
                f'modulus), but got {len(new_registers)}'
            )
        target, exponent, base, modulus = new_registers
        if not isinstance(target, Sequence):
            raise ValueError(f'Target must be a qubit register, got {type(target)}')
        if not isinstance(base, int):
            raise ValueError(f'Base must be a classical constant, got {type(base)}')
        if not isinstance(modulus, int):
            raise ValueError(f'Modulus must be a classical constant, got {type(modulus)}')
        return ModularExp(target, exponent, base, modulus)
    def apply(self, *register_values: int) -> int:
        assert len(register_values) == 4
        target, exponent, base, modulus = register_values
        if target >= modulus:
            return target
        return (target * base**exponent) % modulus
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        assert args.known_qubits is not None
        wire_symbols = [f't{i}' for i in range(len(self.target))]
        e_str = str(self.exponent)
        if isinstance(self.exponent, Sequence):
            e_str = 'e'
            wire_symbols += [f'e{i}' for i in range(len(self.exponent))]
        wire_symbols[0] = f'ModularExp(t*{self.base}**{e_str} % {self.modulus})'
        return cirq.CircuitDiagramInfo(wire_symbols=tuple(wire_symbols))
def make_order_finding_circuit(x: int, n: int) -> cirq.Circuit:
    L = n.bit_length()
    target = cirq.LineQubit.range(L)
    exponent = cirq.LineQubit.range(L, 3 * L + 3)
    return cirq.Circuit(
        cirq.X(target[L - 1]),
        cirq.H.on_each(*exponent),
        ModularExp([2] * len(target), [2] * len(exponent), x, n).on(*target + exponent),
        cirq.qft(*exponent, inverse=True),
        cirq.measure(*exponent, key='exponent'),
    )
def read_eigenphase(result: cirq.Result) -> float:
    exponent_as_integer = result.data['exponent'][0]
    exponent_num_bits = result.measurements['exponent'].shape[1]
    return float(exponent_as_integer / 2**exponent_num_bits)
def quantum_order_finder(x: int, n: int) -> int | None:
    if x < 2 or n <= x or math.gcd(x, n) > 1:
        raise ValueError(f'Invalid x={x} for modulus n={n}.')
    circuit = make_order_finding_circuit(x, n)
    result = cirq.sample(circuit)
    eigenphase = read_eigenphase(result)
    f = fractions.Fraction.from_float(eigenphase).limit_denominator(n)
    if f.numerator == 0:
        return None  # pragma: no cover
    r = f.denominator
    if x**r % n != 1:
        return None  # pragma: no cover
    return r
def find_factor_of_prime_power(n: int) -> int | None:
    for k in range(2, math.floor(math.log2(n)) + 1):
        c = math.pow(n, 1 / k)
        c1 = math.floor(c)
        if c1**k == n:
            return c1
        c2 = math.ceil(c)
        if c2**k == n:
            return c2
    return None
def find_factor(
    n: int, order_finder: Callable[[int, int], int | None], max_attempts: int = 30
) -> int | None:
    if sympy.isprime(n):
        return None
    if n % 2 == 0:
        return 2
    c = find_factor_of_prime_power(n)
    if c is not None:
        return c
    for _ in range(max_attempts):
        x = random.randint(2, n - 1)
        c = math.gcd(x, n)
        if 1 < c < n:
            return c  # pragma: no cover
        r = order_finder(x, n)
        if r is None:
            continue  # pragma: no cover
        if r % 2 != 0:
            continue  # pragma: no cover
        y = x ** (r // 2) % n
        assert 1 < y < n
        c = math.gcd(y - 1, n)
        if 1 < c < n:
            return c
    return None  # pragma: no cover
def main(n: int, order_finder: Callable[[int, int], int | None] = naive_order_finder):
    if n < 2:
        raise ValueError(f'Invalid input {n}, expected positive integer greater than one.')
    d = find_factor(n, order_finder)
    if d is None:
        print(f'No non-trivial factor of {n} found. It is probably a prime.')
    else:
        print(f'{d} is a non-trivial factor of {n}')
        assert 1 < d < n
        assert n % d == 0
if __name__ == '__main__':  # pragma: no cover
    ORDER_FINDERS = {'naive': naive_order_finder, 'quantum': quantum_order_finder}
    args = parser.parse_args()
    main(n=args.n, order_finder=ORDER_FINDERS[args.order_finder])

from __future__ import annotations
import random
import cirq
class OneQubitShorsCode:
    def __init__(self):
        self.num_physical_qubits = 9
        self.physical_qubits = cirq.LineQubit.range(self.num_physical_qubits)
    def encode(self):
        yield cirq.Moment([cirq.CNOT(self.physical_qubits[0], self.physical_qubits[3])])
        yield cirq.Moment([cirq.CNOT(self.physical_qubits[0], self.physical_qubits[6])])
        yield cirq.Moment(
            [
                cirq.H(self.physical_qubits[0]),
                cirq.H(self.physical_qubits[3]),
                cirq.H(self.physical_qubits[6]),
            ]
        )
        yield cirq.Moment(
            [
                cirq.CNOT(self.physical_qubits[0], self.physical_qubits[1]),
                cirq.CNOT(self.physical_qubits[3], self.physical_qubits[4]),
                cirq.CNOT(self.physical_qubits[6], self.physical_qubits[7]),
            ]
        )
        yield cirq.Moment(
            [
                cirq.CNOT(self.physical_qubits[0], self.physical_qubits[2]),
                cirq.CNOT(self.physical_qubits[3], self.physical_qubits[5]),
                cirq.CNOT(self.physical_qubits[6], self.physical_qubits[8]),
            ]
        )
    def apply_gate(self, gate: cirq.Gate, pos: int):
        if pos > self.num_physical_qubits:
            raise IndexError
        else:
            return gate(self.physical_qubits[pos])
    def correct(self):
        yield cirq.Moment(
            [
                cirq.CNOT(self.physical_qubits[0], self.physical_qubits[1]),
                cirq.CNOT(self.physical_qubits[3], self.physical_qubits[4]),
                cirq.CNOT(self.physical_qubits[6], self.physical_qubits[7]),
            ]
        )
        yield cirq.Moment(
            [
                cirq.CNOT(self.physical_qubits[0], self.physical_qubits[2]),
                cirq.CNOT(self.physical_qubits[3], self.physical_qubits[5]),
                cirq.CNOT(self.physical_qubits[6], self.physical_qubits[8]),
            ]
        )
        yield cirq.Moment(
            [
                cirq.CCNOT(
                    self.physical_qubits[1], self.physical_qubits[2], self.physical_qubits[0]
                ),
                cirq.CCNOT(
                    self.physical_qubits[4], self.physical_qubits[5], self.physical_qubits[3]
                ),
                cirq.CCNOT(
                    self.physical_qubits[7], self.physical_qubits[8], self.physical_qubits[6]
                ),
            ]
        )
        yield cirq.Moment(
            [
                cirq.H(self.physical_qubits[0]),
                cirq.H(self.physical_qubits[3]),
                cirq.H(self.physical_qubits[6]),
            ]
        )
