    resolve_operation,
    SymbolResolver,
)
class Circuit3D(widget.Widget):
    def __init__(
        self,
        circuit: cirq.Circuit,
        resolvers: Iterable[SymbolResolver] = DEFAULT_SYMBOL_RESOLVERS,
        padding_factor: float = 1,
    ):
        super().__init__()
        self.circuit = circuit
        self._resolvers = resolvers
        self.padding_factor = padding_factor
    def get_client_code(self) -> str:
        stripped_id = self.id.replace('-', '')
        moments = len(self.circuit.moments)
        self.serialized_circuit = self._serialize_circuit()
        return f
    def get_widget_bundle_name(self) -> str:
        return 'circuit.bundle.js'
    def _serialize_circuit(self) -> str:
        args = []
        moments = self.circuit.moments
        for moment_id, moment in enumerate(moments):
            for item in moment:
                symbol = self._build_3D_symbol(item, moment_id)
                args.append(symbol.to_typescript())
        argument_str = ','.join(str(item) for item in args)
        return f'[{argument_str}]'
    def _build_3D_symbol(self, operation, moment) -> Operation3DSymbol:
        symbol_info = resolve_operation(operation, self._resolvers)
        location_info = []
        for qubit in operation.qubits:
            if isinstance(qubit, cirq.GridQubit):
                location_info.append({'row': qubit.row, 'col': qubit.col})
            elif isinstance(qubit, cirq.LineQubit):
                location_info.append({'row': qubit.x, 'col': 0})
            else:
                raise ValueError('Unsupported qubit type')
        return Operation3DSymbol(symbol_info.labels, location_info, symbol_info.colors, moment)

from __future__ import annotations
import abc
import dataclasses
from collections.abc import Iterable
import cirq
from cirq.protocols.circuit_diagram_info_protocol import CircuitDiagramInfoArgs
@dataclasses.dataclass
class SymbolInfo:
    labels: list[str]
    colors: list[str]
    @staticmethod
    def unknown_operation(num_qubits: int) -> SymbolInfo:
        symbol_info = SymbolInfo([], [])
        for _ in range(num_qubits):
            symbol_info.colors.append('gray')
            symbol_info.labels.append('?')
        return symbol_info
class SymbolResolver(metaclass=abc.ABCMeta):
    def __call__(self, operation: cirq.Operation) -> SymbolInfo | None:
        return self.resolve(operation)
    @abc.abstractmethod
    def resolve(self, operation: cirq.Operation) -> SymbolInfo | None:
class DefaultResolver(SymbolResolver):
    _SYMBOL_COLORS = {
        '@': 'black',
        'H': 'yellow',
        'I': 'orange',
        'X': 'black',
        'Y': 'pink',
        'Z': 'cyan',
        'S': '#90EE90',
        'T': '#CBC3E3',
    }
    def resolve(self, operation: cirq.Operation) -> SymbolInfo | None:
        try:
            info = cirq.circuit_diagram_info(operation)
        except TypeError:
            return SymbolInfo.unknown_operation(cirq.num_qubits(operation))
        wire_symbols = info.wire_symbols
        symbol_exponent = info._wire_symbols_including_formatted_exponent(
            CircuitDiagramInfoArgs.UNINFORMED_DEFAULT
        )
        symbol_info = SymbolInfo(list(symbol_exponent), [])
        for symbol in wire_symbols:
            symbol_info.colors.append(DefaultResolver._SYMBOL_COLORS.get(symbol, 'gray'))
        return symbol_info
DEFAULT_SYMBOL_RESOLVERS: Iterable[SymbolResolver] = tuple([DefaultResolver()])
def resolve_operation(operation: cirq.Operation, resolvers: Iterable[SymbolResolver]) -> SymbolInfo:
    symbol_info = None
    for resolver in resolvers:
        info = resolver(operation)
        if info is not None:
            symbol_info = info
    if symbol_info is None:
        raise ValueError(f'Cannot resolve operation: {operation}')
    return symbol_info
class Operation3DSymbol:
    def __init__(self, wire_symbols, location_info, color_info, moment):
        self.wire_symbols = wire_symbols
        self.location_info = location_info
        self.color_info = color_info
        self.moment = moment
    def to_typescript(self):
        return {
            'wire_symbols': list(self.wire_symbols),
            'location_info': self.location_info,
            'color_info': self.color_info,
            'moment': self.moment,
        }

