        python_version_string = f'python/{platform.python_version()}'
        return f'{cirq_version_string} ({python_version_string})'
    def _target(self, target: str | None) -> str:
        assert target is not None or self.default_target is not None, (
            'One must specify a target on this call, or a default_target on the service/client, '
            'but neither were set.'
        )
        return cast(str, target or self.default_target)
    def _make_request(
        self, request: Callable[[], requests.Response], json: dict
    ) -> requests.Response:
        delay_seconds = 0.1
        while True:
            try:
                response = request()
                if response.ok:
                    return response
                if response.status_code == requests.codes.unauthorized:
                    raise ionq_exceptions.IonQException(
                        '"Not authorized" returned by IonQ API. Check to ensure you have supplied '
                        'the correct API key.',
                        response.status_code,
                    )
                if response.status_code == requests.codes.not_found:
                    raise ionq_exceptions.IonQNotFoundException(
                        'IonQ could not find requested resource.'
                    )
                if not _is_retriable(response.status_code, response.request.method):
                    error = {}
                    try:
                        error = response.json()
                    except jd.JSONDecodeError:  # pragma: no cover
                        pass
                    raise ionq_exceptions.IonQException(
                        'Non-retry-able error making request to IonQ API. '
                        f'Request Body: {json} '
                        f'Response Body: {error} '
                        f'Status: {response.status_code} '
                        f'Error:{response.reason}',
                        response.status_code,
                    )
                message = response.reason
            except requests.RequestException as e:
                message = f'RequestException of type {type(e)}.'
            if delay_seconds > self.max_retry_seconds:
                raise TimeoutError(f'Reached maximum number of retries. Last error: {message}')
            if self.verbose:
                print(message, file=sys.stderr)
                print(f'Waiting {delay_seconds} seconds before retrying.')
            time.sleep(delay_seconds)
            delay_seconds *= 2
    def _list(
        self, resource_path: str, params: dict, response_key: str, limit: int, batch_size: int
    ) -> list[dict]:
        json = {'limit': batch_size}
        token: str | None = None
        results: list[dict[str, Any]] = []
        while len(results) < limit:
            full_params = params.copy()
            if token:
                full_params['next'] = token
            def request():
                return requests.get(
                    f'{self.url}/{resource_path}',
                    headers=self.headers,
                    json=json,
                    params=full_params,
                )
            response = self._make_request(request, json).json()
            results.extend(response[response_key])
            if 'next' not in response:
                break
            token = response['next']
        return results[:limit]

from __future__ import annotations
from collections.abc import Sequence
import cirq
from cirq_ionq import ionq_gateset
class IonQAPIDevice(cirq.Device):
    def __init__(self, qubits: Sequence[cirq.LineQubit] | int, atol=1e-8):
        if isinstance(qubits, int):
            self.qubits = frozenset(cirq.LineQubit.range(qubits))
        else:
            self.qubits = frozenset(qubits)
        self.atol = atol
        self.gateset = ionq_gateset.IonQTargetGateset()
        self._metadata = cirq.DeviceMetadata(
            self.qubits, [(a, b) for a in self.qubits for b in self.qubits if a != b]
        )
    @property
    def metadata(self) -> cirq.DeviceMetadata:
        return self._metadata
    def validate_operation(self, operation: cirq.Operation):
        if operation.gate is None:
            raise ValueError(
                f'IonQAPIDevice does not support operations with no gates {operation}.'
            )
        if not self.is_api_gate(operation):
            raise ValueError(f'IonQAPIDevice has unsupported gate {operation.gate}.')
        if not set(operation.qubits).intersection(self.metadata.qubit_set):
            raise ValueError(f'Operation with qubits not on the device. Qubits: {operation.qubits}')
    def is_api_gate(self, operation: cirq.Operation) -> bool:
        return operation in self.gateset

from __future__ import annotations
from collections.abc import Iterator
from typing import Any
import cirq
class IonQTargetGateset(cirq.TwoQubitCompilationTargetGateset):
    def __init__(self, *, atol: float = 1e-8):
        super().__init__(
            cirq.H,
            cirq.CNOT,
            cirq.SWAP,
            cirq.XPowGate,
            cirq.YPowGate,
            cirq.ZPowGate,
            cirq.XXPowGate,
            cirq.YYPowGate,
            cirq.ZZPowGate,
            cirq.MeasurementGate,
            cirq.GlobalPhaseGate,
            unroll_circuit_op=False,
        )
        self.atol = atol
    def _decompose_single_qubit_operation(self, op: cirq.Operation, _) -> Iterator[cirq.OP_TREE]:
        qubit = op.qubits[0]
        mat = cirq.unitary(op)
        for gate in cirq.single_qubit_matrix_to_gates(mat, self.atol):
            yield gate(qubit)
    def _decompose_two_qubit_operation(self, op: cirq.Operation, _) -> cirq.OP_TREE:
        if not cirq.has_unitary(op):
            return NotImplemented
        mat = cirq.unitary(op)
        q0, q1 = op.qubits
        naive = cirq.two_qubit_matrix_to_cz_operations(q0, q1, mat, allow_partial_czs=False)
        temp = cirq.map_operations_and_unroll(
            cirq.Circuit(naive),
            lambda op, _: (
                [cirq.H(op.qubits[1]), cirq.CNOT(*op.qubits), cirq.H(op.qubits[1])]
                if op.gate == cirq.CZ
                else op
            ),
        )
        return cirq.merge_k_qubit_unitaries(
            temp, k=1, rewriter=lambda op: self._decompose_single_qubit_operation(op, -1)
        ).all_operations()
    def _decompose_multi_qubit_operation(self, op: cirq.Operation, _) -> cirq.OP_TREE:
        if isinstance(op.gate, cirq.CCZPowGate):
            return decompose_all_to_all_connect_ccz_gate(op.gate, op.qubits)
        return NotImplemented
    @property
    def preprocess_transformers(self) -> list[cirq.TRANSFORMER]:
        return [
            cirq.create_transformer_with_kwargs(
                cirq.expand_composite, no_decomp=lambda op: cirq.num_qubits(op) <= 3
            )
        ]
    @property
    def postprocess_transformers(self) -> list[cirq.TRANSFORMER]:
        return [cirq.drop_negligible_operations, cirq.drop_empty_moments]
    def __repr__(self) -> str:
        return f'cirq_ionq.IonQTargetGateset(atol={self.atol})'
    def _value_equality_values_(self) -> Any:
        return self.atol
    def _json_dict_(self) -> dict[str, Any]:
        return cirq.obj_to_dict_helper(self, ['atol'])
    @classmethod
    def _from_json_dict_(cls, atol, **kwargs):
        return cls(atol=atol)
def decompose_all_to_all_connect_ccz_gate(
    ccz_gate: cirq.CCZPowGate, qubits: tuple[cirq.Qid, ...]
) -> cirq.OP_TREE:
    if len(qubits) != 3:
        raise ValueError(f'Expect 3 qubits for CCZ gate, got {len(qubits)} qubits.')
    a, b, c = qubits
    p = cirq.T**ccz_gate._exponent
    global_phase = 1j ** (2 * ccz_gate.global_shift * ccz_gate._exponent)
    global_phase = (
        complex(global_phase)
        if cirq.is_parameterized(global_phase) and global_phase.is_complex
        else global_phase
    )
    global_phase_operation = (
        [cirq.global_phase_operation(global_phase)]
        if cirq.is_parameterized(global_phase) or abs(global_phase - 1.0) > 0
        else []
    )
    return global_phase_operation + [
        cirq.CNOT(b, c),
        p(c) ** -1,
        cirq.CNOT(a, c),
        p(c),
        cirq.CNOT(b, c),
        p(c) ** -1,
        cirq.CNOT(a, c),
        p(b),
        p(c),
        cirq.CNOT(a, b),
        p(a),
        p(b) ** -1,
        cirq.CNOT(a, b),
    ]

