    def postprocess_transformers(self) -> list[cirq.TRANSFORMER]:
        return [cirq.drop_negligible_operations, cirq.drop_empty_moments]
    def single_qubit_matrix_to_native_gates(self, mat: np.ndarray) -> list[cirq.Gate]:
        z_rad_before, y_rad, z_rad_after = linalg.deconstruct_single_qubit_matrix_into_angles(mat)
        return [
            GPI2Gate(phi=(np.pi - z_rad_before) / (2.0 * np.pi)),
            GPIGate(phi=(y_rad / 2 + z_rad_after / 2 - z_rad_before / 2) / (2.0 * np.pi)),
            GPI2Gate(phi=(np.pi + z_rad_after) / (2.0 * np.pi)),
        ]
    def _value_equality_values_(self) -> Any:
        return self.atol
    def _value_equality_values_cls_(self) -> Any:
        return type(self)
    def _json_dict_(self) -> dict[str, Any]:
        return cirq.obj_to_dict_helper(self, ['atol'])
    @classmethod
    def _from_json_dict_(cls, atol, **kwargs):
        return cls(atol=atol)
    def _hadamard(self, qubit):
        return [GPI2Gate(phi=0.25).on(qubit), GPIGate(phi=0).on(qubit)]
    def _cnot(self, *qubits):
        raise NotImplementedError()
    def decompose_all_to_all_connect_ccz_gate(
        self, ccz_gate: cirq.CCZPowGate, qubits: tuple[cirq.Qid, ...]
    ) -> cirq.OP_TREE:
        if len(qubits) != 3:
            raise ValueError(f'Expect 3 qubits for CCZ gate, got {len(qubits)} qubits.')
        a, b, c = qubits
        p = cirq.T**ccz_gate._exponent
        global_phase = 1j ** (2 * ccz_gate.global_shift * ccz_gate._exponent)
        global_phase = (
            complex(global_phase)
            if cirq.is_parameterized(global_phase) and global_phase.is_complex
            else global_phase
        )
        global_phase_operation = (
            [cirq.global_phase_operation(global_phase)]
            if cirq.is_parameterized(global_phase) or abs(global_phase - 1.0) > 0
            else []
        )
        return global_phase_operation + [
            self._cnot(*[b, c]),
            p(c) ** -1,
            self._cnot(*[a, c]),
            p(c),
            self._cnot(*[b, c]),
            p(c) ** -1,
            self._cnot(*[a, c]),
            p(b),
            p(c),
            self._cnot(*[a, b]),
            p(a),
            p(b) ** -1,
            self._cnot(*[a, b]),
        ]
class AriaNativeGateset(IonqNativeGatesetBase):
    def __init__(self, *, atol: float = 1e-8):
        super().__init__(GPIGate, GPI2Gate, MSGate, ops.MeasurementGate, atol=atol)
    def __repr__(self) -> str:
        return f'cirq_ionq.AriaNativeGateset(atol={self.atol})'
    def _cnot(self, *qubits):
        return [
            GPI2Gate(phi=1 / 4).on(qubits[0]),
            MSGate(phi0=0, phi1=0).on(qubits[0], qubits[1]),
            GPI2Gate(phi=1 / 2).on(qubits[1]),
            GPI2Gate(phi=1 / 2).on(qubits[0]),
            GPI2Gate(phi=-1 / 4).on(qubits[0]),
        ]
class ForteNativeGateset(IonqNativeGatesetBase):
    def __init__(self, *, atol: float = 1e-8):
        super().__init__(GPIGate, GPI2Gate, ZZGate, ops.MeasurementGate, atol=atol)
    def __repr__(self) -> str:
        return f'cirq_ionq.ForteNativeGateset(atol={self.atol})'
    def _cnot(self, *qubits):
        return [
            GPI2Gate(phi=0).on(qubits[1]),
            GPIGate(phi=-0.125).on(qubits[1]),
            GPI2Gate(phi=0.5).on(qubits[1]),
            ZZGate(theta=0.25).on(qubits[0], qubits[1]),
            GPI2Gate(phi=0.75).on(qubits[0]),
            GPIGate(phi=0.125).on(qubits[0]),
            GPI2Gate(phi=0.5).on(qubits[0]),
            GPI2Gate(phi=1.25).on(qubits[1]),
            GPIGate(phi=0.5).on(qubits[1]),
            GPI2Gate(phi=0.5).on(qubits[1]),
        ]

from __future__ import annotations
import json
import time
import warnings
from collections.abc import Sequence
from typing import TYPE_CHECKING
import cirq
from cirq._doc import document
from cirq_ionq import ionq_exceptions, results
if TYPE_CHECKING:
    import cirq_ionq
def _little_endian_to_big(value: int, bit_count: int) -> int:
    return cirq.big_endian_bits_to_int(
        cirq.big_endian_int_to_bits(value, bit_count=bit_count)[::-1]
    )
class Job:
    TERMINAL_STATES = ('completed', 'canceled', 'failed', 'deleted')
    document(
        TERMINAL_STATES,
        'States of the IonQ API job from which the job cannot transition. '
        'Note that deleted can only exist in a return call from a delete '
        '(subsequent calls will return not found).',
    )
    NON_TERMINAL_STATES = ('ready', 'submitted', 'running')
    document(
        NON_TERMINAL_STATES, 'States of the IonQ API job which can transition to other states.'
    )
    ALL_STATES = TERMINAL_STATES + NON_TERMINAL_STATES
    document(ALL_STATES, 'All states that an IonQ API job can exist in.')
    UNSUCCESSFUL_STATES = ('canceled', 'failed', 'deleted')
    document(
        UNSUCCESSFUL_STATES,
        'States of the IonQ API job when it was not successful and so does not have any '
        'data associated with it beyond an id and a status.',
    )
    def __init__(self, client: cirq_ionq.ionq_client._IonQClient, job_dict: dict):
        self._client = client
        self._job = job_dict
    def _refresh_job(self):
        if self._job['status'] not in self.TERMINAL_STATES:
            self._job = self._client.get_job(self.job_id())
    def _check_if_unsuccessful(self):
        if self.status() in self.UNSUCCESSFUL_STATES:
            raise ionq_exceptions.IonQUnsuccessfulJobException(self.job_id(), self.status())
    def job_id(self) -> str:
        return self._job['id']
    def status(self) -> str:
        self._refresh_job()
        return self._job['status']
    def target(self) -> str:
        self._check_if_unsuccessful()
        return self._job['backend']
    def name(self) -> str:
        self._check_if_unsuccessful()
        return self._job['name']
    def num_qubits(self, circuit_index=None) -> int:
        self._check_if_unsuccessful()
        if 'metadata' in self._job and circuit_index is not None:
            if 'qubit_numbers' in self._job['metadata'].keys():
                qubit_numbers = json.loads(self._job['metadata']['qubit_numbers'])
                for index, qubit_number in enumerate(qubit_numbers):
                    if index == circuit_index:
                        return qubit_number
        return int(self._job['stats']['qubits'])
    def repetitions(self) -> int:
        self._check_if_unsuccessful()
        return int(self._job['metadata']['shots'])
    def measurement_dict(self, circuit_index=0) -> dict[str, Sequence[int]]:
        measurement_dict: dict[str, Sequence[int]] = {}
        if 'metadata' in self._job:
            measurement_matadata = None
            if 'measurements' in self._job['metadata'].keys():
                measurements = json.loads(self._job['metadata']['measurements'])
                for index, measurement in enumerate(measurements):
                    if index == circuit_index:
                        measurement_matadata = measurement
                        break
            else:
                measurement_matadata = self._job['metadata']
            if measurement_matadata is not None:
                full_str = ''.join(
                    value
                    for key, value in measurement_matadata.items()
                    if key.startswith('measurement')
                )
                if full_str == '':
                    return measurement_dict
                for key_value in full_str.split(chr(30)):
                    key, value = key_value.split(chr(31))
                    measurement_dict[key] = [int(t) for t in value.split(',')]
        return measurement_dict
    def results(
        self,
        timeout_seconds: int = 7200,
        polling_seconds: int = 1,
        sharpen: bool | None = None,
        extra_query_params: dict | None = None,
    ) -> list[results.QPUResult] | list[results.SimulatorResult]:
        time_waited_seconds = 0
        while time_waited_seconds < timeout_seconds:
            if self.status() in self.TERMINAL_STATES:
                break
            time.sleep(polling_seconds)
            time_waited_seconds += polling_seconds
        if 'warning' in self._job and 'messages' in self._job['warning']:
            for warning in self._job['warning']['messages']:
                warnings.warn(warning)
        if self.status() != 'completed':
            if 'failure' in self._job and 'error' in self._job['failure']:
                error = self._job['failure']['error']
                raise RuntimeError(f'Job failed. Error message: {error}')
            if time_waited_seconds >= timeout_seconds:
                raise TimeoutError(f'Job timed out after waiting {time_waited_seconds} seconds.')
            raise RuntimeError(
                f'Job was not completed successfully. Instead had status: {self.status()}'
            )
        backend_results = self._client.get_results(
            job_id=self.job_id(), sharpen=sharpen, extra_query_params=extra_query_params
        )
        some_inner_value = next(iter(backend_results.values()))
        if isinstance(some_inner_value, dict):
            histograms = backend_results.values()
        else:
            histograms = [backend_results]
        if self.target().startswith('qpu'):
            big_endian_results_qpu: list[results.QPUResult] = []
            for circuit_index, histogram in enumerate(histograms):
                repetitions = self.repetitions()
                counts = {
                    _little_endian_to_big(int(k), self.num_qubits(circuit_index)): round(
                        repetitions * float(v)
                    )
                    for k, v in histogram.items()
                }
                big_endian_results_qpu.append(
                    results.QPUResult(
                        counts=counts,
                        num_qubits=self.num_qubits(circuit_index),
                        measurement_dict=self.measurement_dict(circuit_index=circuit_index),
                    )
                )
            return big_endian_results_qpu
        else:
            big_endian_results_sim: list[results.SimulatorResult] = []
            for circuit_index, histogram in enumerate(histograms):
                probabilities = {
                    _little_endian_to_big(int(k), self.num_qubits(circuit_index)): float(v)
                    for k, v in histogram.items()
                }
                big_endian_results_sim.append(
                    results.SimulatorResult(
                        probabilities=probabilities,
                        num_qubits=self.num_qubits(circuit_index),
                        measurement_dict=self.measurement_dict(circuit_index=circuit_index),
                        repetitions=self.repetitions(),
                    )
                )
            return big_endian_results_sim
    def cancel(self):
        self._job = self._client.cancel_job(job_id=self.job_id())
    def delete(self):
        self._job = self._client.delete_job(job_id=self.job_id())
    def __str__(self) -> str:
        return f'cirq_ionq.Job(job_id={self.job_id()})'

from __future__ import annotations
import collections
from collections import Counter
from collections.abc import Sequence
import numpy as np
import cirq
class QPUResult:
    def __init__(
        self, counts: dict[int, int], num_qubits: int, measurement_dict: dict[str, Sequence[int]]
    ):
        self._counts = collections.OrderedDict(sorted(counts.items()))
        self._num_qubits = num_qubits
        self._measurement_dict = measurement_dict
        self._repetitions = sum(self._counts.values())
    def num_qubits(self) -> int:
        return self._num_qubits
    def repetitions(self) -> int:
        return self._repetitions
    def ordered_results(self, key: str | None = None) -> list[int]:
        if key is not None and not key in self._measurement_dict:
            raise ValueError(
                f'Measurement key {key} is not a key for a measurement gate in the'
                'circuit that produced these results.'
            )
        targets = self._measurement_dict[key] if key is not None else range(self.num_qubits())
        result: list[int] = []
        for value, count in self._counts.items():
            bits = [(value >> (self.num_qubits() - target - 1)) & 1 for target in targets]
            bit_value = sum(bit * (1 << i) for i, bit in enumerate(bits[::-1]))
            result.extend([bit_value] * count)
        return result
    def counts(self, key: str | None = None) -> Counter[int]:
        if key is None:
            return collections.Counter(self._counts)
        if not key in self._measurement_dict:
            raise ValueError(
                f'Measurement key {key} is not a key for a measurement gate in the'
                'circuit that produced these results.'
            )
        result: Counter[int] = collections.Counter()
        result.update([bit_value for bit_value in self.ordered_results(key)])
        return result
    def measurement_dict(self) -> dict[str, Sequence[int]]:
        return self._measurement_dict
    def to_cirq_result(self, params: cirq.ParamResolver | None = None) -> cirq.Result:
        if len(self.measurement_dict()) == 0:
            raise ValueError(
                'Can convert to cirq results only if the circuit had measurement gates '
                'with measurement keys.'
            )
        measurements = {}
        for key, targets in self.measurement_dict().items():
            qpu_results = self.ordered_results(key)
            measurements[key] = np.array(
                list(cirq.big_endian_int_to_bits(x, bit_count=len(targets)) for x in qpu_results)
            )
        return cirq.ResultDict(params=params or cirq.ParamResolver({}), measurements=measurements)
    def __eq__(self, other):
        if not isinstance(other, QPUResult):
            return NotImplemented
        return (
            self._counts == other._counts
            and self._num_qubits == other._num_qubits
            and self._measurement_dict == other._measurement_dict
            and self._repetitions == other._repetitions
        )
    def __str__(self) -> str:
        return _pretty_str_dict(self._counts, self._num_qubits)
class SimulatorResult:
    def __init__(
        self,
        probabilities: dict[int, float],
        num_qubits: int,
        measurement_dict: dict[str, Sequence[int]],
        repetitions: int,
    ):
        self._probabilities = probabilities
        self._num_qubits = num_qubits
        self._measurement_dict = measurement_dict
        self._repetitions = repetitions
    def num_qubits(self) -> int:
        return self._num_qubits
    def repetitions(self) -> int:
        return self._repetitions
    def probabilities(self, key: str | None = None) -> dict[int, float]:
        if key is None:
            return self._probabilities
        if not key in self._measurement_dict:
            raise ValueError(
                f'Measurement key {key} is not a key for a measurement gate in the'
                'circuit that produced these results.'
            )
        targets = self._measurement_dict[key]
        result: dict[int, float] = dict()
        for value, probability in self._probabilities.items():
            bits = [(value >> (self.num_qubits() - target - 1)) & 1 for target in targets]
            bit_value = sum(bit * (1 << i) for i, bit in enumerate(bits[::-1]))
            if bit_value in result:
                result[bit_value] += probability
            else:
                result[bit_value] = probability
        return result
    def measurement_dict(self) -> dict[str, Sequence[int]]:
        return self._measurement_dict
    def to_cirq_result(
        self,
        params: cirq.ParamResolver | None = None,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
        override_repetitions=None,
    ) -> cirq.Result:
        if len(self.measurement_dict()) == 0:
            raise ValueError(
                'Can convert to cirq results only if the circuit had measurement gates '
                'with measurement keys.'
            )
        rand = cirq.value.parse_random_state(seed)
        measurements = {}
        values, weights = zip(*list(self.probabilities().items()))
        total = sum(weights)
        if np.isclose(total, 1.0, rtol=0, atol=1e-5):
            weights = tuple(w / total for w in weights)
        indices = rand.choice(
            range(len(values)), p=weights, size=override_repetitions or self.repetitions()
        )
        rand_values = np.array(values)[indices]
        for key, targets in self.measurement_dict().items():
            bits = [
                [(value >> (self.num_qubits() - target - 1)) & 1 for target in targets]
                for value in rand_values
            ]
            measurements[key] = np.array(bits)
        return cirq.ResultDict(params=params or cirq.ParamResolver({}), measurements=measurements)
    def __eq__(self, other):
        if not isinstance(other, SimulatorResult):
            return NotImplemented
        return (
            self._probabilities == other._probabilities
            and self._num_qubits == other._num_qubits
            and self._measurement_dict == other._measurement_dict
            and self._repetitions == other._repetitions
        )
    def __str__(self) -> str:
        return _pretty_str_dict(self._probabilities, self._num_qubits)
def _pretty_str_dict(value: dict, bit_count: int) -> str:
    strs = []
    for k, v in value.items():
        bits = ''.join(str(b) for b in cirq.big_endian_int_to_bits(k, bit_count=bit_count))
        strs.append(f'{bits}: {v}')
    return '\n'.join(strs)

