    assert result.repetitions() == 100
def test_simulator_result_str():
    result = ionq.SimulatorResult(
        {0: 0.4, 1: 0.6}, num_qubits=2, measurement_dict={'a': [0]}, repetitions=100
    )
    assert str(result) == '00: 0.4\n01: 0.6'
def test_simulator_result_eq():
    equals_tester = cirq.testing.EqualsTester()
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=1, measurement_dict={'a': [0]}, repetitions=100
        ),
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=1, measurement_dict={'a': [0]}, repetitions=100
        ),
    )
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.4, 1: 0.6}, num_qubits=1, measurement_dict={'a': [0]}, repetitions=100
        )
    )
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=2, measurement_dict={'a': [0]}, repetitions=100
        )
    )
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=1, measurement_dict={'b': [0]}, repetitions=100
        )
    )
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=1, measurement_dict={'a': [1]}, repetitions=100
        )
    )
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=1, measurement_dict={'a': [0, 1]}, repetitions=100
        )
    )
    equals_tester.add_equality_group(
        ionq.SimulatorResult(
            {0: 0.5, 1: 0.5}, num_qubits=1, measurement_dict={'a': [0, 1]}, repetitions=10
        )
    )
def test_simulator_result_measurement_key():
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [0]}, repetitions=100
    )
    assert result.probabilities() == {0b00: 0.2, 0b01: 0.8}
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [0]}, repetitions=100
    )
    assert result.probabilities('a') == {0b0: 1.0}
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [1]}, repetitions=100
    )
    assert result.probabilities('a') == {0b0: 0.2, 0b1: 0.8}
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [0, 1]}, repetitions=100
    )
    assert result.probabilities('a') == {0b00: 0.2, 0b01: 0.8}
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [1, 0]}, repetitions=100
    )
    assert result.probabilities('a') == {0b00: 0.2, 0b10: 0.8}
    result = ionq.SimulatorResult(
        {0b000: 0.2, 0b111: 0.8}, num_qubits=3, measurement_dict={'a': [2]}, repetitions=100
    )
    assert result.probabilities('a') == {0b0: 0.2, 0b1: 0.8}
    result = ionq.SimulatorResult(
        {0b000: 0.2, 0b100: 0.8}, num_qubits=3, measurement_dict={'a': [1, 2]}, repetitions=100
    )
    assert result.probabilities('a') == {0b00: 1.0}
def test_simulator_result_measurement_multiple_key():
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [0], 'b': [1]}, repetitions=100
    )
    assert result.probabilities('a') == {0b0: 1.0}
    assert result.probabilities('b') == {0b0: 0.2, 0b1: 0.8}
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [1], 'b': [0]}, repetitions=100
    )
    assert result.probabilities('a') == {0b0: 0.2, 0b1: 0.8}
    assert result.probabilities('b') == {0b0: 1.0}
def test_simulator_result_bad_measurement_key():
    result = ionq.SimulatorResult(
        {0b00: 0.2, 0b01: 0.8}, num_qubits=2, measurement_dict={'a': [0], 'b': [1]}, repetitions=100
    )
    with pytest.raises(ValueError, match='bad'):
        result.probabilities('bad')
def test_simulator_result_to_cirq_result():
    result = ionq.SimulatorResult(
        {0b00: 0.25, 0b01: 0.75}, num_qubits=2, measurement_dict={'x': [0, 1]}, repetitions=3
    )
    assert result.to_cirq_result(seed=2) == cirq.ResultDict(
        params=cirq.ParamResolver({}), measurements={'x': np.array([[0, 1], [0, 0], [0, 1]])}
    )
    assert result.to_cirq_result(seed=3) == cirq.ResultDict(
        params=cirq.ParamResolver({}), measurements={'x': np.array([[0, 1], [0, 1], [0, 1]])}
    )
    params = cirq.ParamResolver({'a': 0.1})
    assert result.to_cirq_result(seed=3, params=params) == cirq.ResultDict(
        params=params, measurements={'x': np.array([[0, 1], [0, 1], [0, 1]])}
    )
    assert result.to_cirq_result(seed=2, override_repetitions=2) == cirq.ResultDict(
        params=cirq.ParamResolver({}), measurements={'x': np.array([[0, 1], [0, 0]])}
    )
    result = ionq.SimulatorResult(
        {0b00: 0.25, 0b01: 0.75}, num_qubits=2, measurement_dict={'x': [0]}, repetitions=3
    )
    assert result.to_cirq_result(seed=2) == cirq.ResultDict(
        params=cirq.ParamResolver({}), measurements={'x': np.array([[0], [0], [0]])}
    )
    result = ionq.SimulatorResult(
        {0b00: 0.25, 0b01: 0.75}, num_qubits=2, measurement_dict={'x': [1]}, repetitions=3
    )
    assert result.to_cirq_result(seed=2) == cirq.ResultDict(
        params=cirq.ParamResolver({}), measurements={'x': np.array([[1], [0], [1]])}
    )
    assert type(result.to_cirq_result().measurements['x']) == np.ndarray
def test_simulator_result_to_cirq_result_multiple_keys():
    result = ionq.SimulatorResult(
        {0b000: 0.25, 0b011: 0.75},
        num_qubits=3,
        measurement_dict={'x': [1], 'y': [2, 0]},
        repetitions=3,
    )
    assert result.to_cirq_result(seed=2) == cirq.ResultDict(
        params=cirq.ParamResolver({}),
        measurements={'x': np.array([[1], [0], [1]]), 'y': np.array([[1, 0], [0, 0], [1, 0]])},
    )
def test_simulator_result_to_cirq_result_no_keys():
    result = ionq.SimulatorResult(
        {0b00: 1, 0b01: 2}, num_qubits=2, measurement_dict={}, repetitions=3
    )
    with pytest.raises(ValueError, match='cirq results'):
        _ = result.to_cirq_result()

from __future__ import annotations
import dataclasses
import json
import math
from collections.abc import Callable, Collection, Iterator, Sequence
from typing import Any, cast, TYPE_CHECKING
import numpy as np
import cirq
from cirq.devices import line_qubit
from cirq_ionq.ionq_exceptions import (
    IonQSerializerMixedGatesetsException,
    NotSupportedPauliexpParameters,
)
from cirq_ionq.ionq_native_gates import GPI2Gate, GPIGate, MSGate, ZZGate
if TYPE_CHECKING:
    import sympy
    from cirq.ops.pauli_string_phasor import PauliStringPhasorGate
_NATIVE_GATES = cirq.Gateset(
    GPIGate, GPI2Gate, MSGate, ZZGate, cirq.MeasurementGate, unroll_circuit_op=False
)
@dataclasses.dataclass
class SerializedProgram:
    input: dict
    settings: dict
    metadata: dict
    compilation: dict
    error_mitigation: dict
    noise: dict
    dry_run: bool
class Serializer:
    def __init__(self, atol: float = 1e-8):
        self.atol = atol
        self._dispatch: dict[type[cirq.Gate], Callable] = {
            cirq.XPowGate: self._serialize_x_pow_gate,
            cirq.YPowGate: self._serialize_y_pow_gate,
            cirq.ZPowGate: self._serialize_z_pow_gate,
            cirq.XXPowGate: self._serialize_xx_pow_gate,
            cirq.YYPowGate: self._serialize_yy_pow_gate,
            cirq.ZZPowGate: self._serialize_zz_pow_gate,
            cirq.CNotPowGate: self._serialize_cnot_pow_gate,
            cirq.HPowGate: self._serialize_h_pow_gate,
            cirq.SwapPowGate: self._serialize_swap_gate,
            cirq.MeasurementGate: self._serialize_measurement_gate,
            cirq.ops.pauli_string_phasor.PauliStringPhasorGate: self._serialize_pauli_string_phasor_gate,  # noqa: E501
            GPIGate: self._serialize_gpi_gate,
            GPI2Gate: self._serialize_gpi2_gate,
            MSGate: self._serialize_ms_gate,
            ZZGate: self._serialize_zz_gate,
        }
    def serialize_single_circuit(
        self,
        circuit: cirq.AbstractCircuit,
        job_settings: dict | None = None,
        compilation: dict | None = None,
        error_mitigation: dict | None = None,
        noise: dict | None = None,
        metadata: dict | None = None,
        dry_run: bool = False,
    ) -> SerializedProgram:
        self._validate_circuit(circuit)
        self._validate_qubits(circuit.all_qubits())
        num_qubits = self._num_qubits(circuit)
        serialized_ops = self._serialize_circuit(circuit)
        gateset = "qis" if not _NATIVE_GATES.validate(circuit) else "native"
        program_input = {
            'gateset': gateset,
            'qubits': num_qubits,
            'circuit': [op for op in serialized_ops if op['gate'] != 'meas'],
        }
        if metadata is not None:
            metadata.update(
                self._serialize_measurements(op for op in serialized_ops if op['gate'] == 'meas')
            )
        else:
            metadata = self._serialize_measurements(
                op for op in serialized_ops if op['gate'] == 'meas'
            )
        return SerializedProgram(
            input=program_input,
            settings=(job_settings or {}),
            compilation=(compilation or {}),
            error_mitigation=(error_mitigation or {}),
            noise=(noise or {}),
            metadata=(metadata or {}),
            dry_run=dry_run,
        )
    def serialize_many_circuits(
        self,
        circuits: list[cirq.AbstractCircuit],
        job_settings: dict | None = None,
        compilation: dict | None = None,
        error_mitigation: dict | None = None,
        noise: dict | None = None,
        metadata: dict | None = None,
        dry_run: bool = False,
    ) -> SerializedProgram:
        for circuit in circuits:
            self._validate_circuit(circuit)
            self._validate_qubits(circuit.all_qubits())
        num_qubits = max([self._num_qubits(circuit) for circuit in circuits])
        gateset = None
        for circuit in circuits:
            current_gateset = "qis" if not _NATIVE_GATES.validate(circuit) else "native"
            if gateset is None:
                gateset = current_gateset
            if current_gateset != gateset:
                raise IonQSerializerMixedGatesetsException(
                    "For batch circuit submission, all circuits in a batch must contain "
                    "the same type of gates: either 'qis' or 'native' gates."
                )
        program_input: dict[str, Any] = {'gateset': gateset, 'qubits': num_qubits, 'circuits': []}
        measurements = []
        qubit_numbers = []
        for circuit in circuits:
            serialized_ops = self._serialize_circuit(circuit)
            program_input['circuits'].append(
                {'circuit': [op for op in serialized_ops if op['gate'] != 'meas']}
            )
            measurements.append(
                self._serialize_measurements(op for op in serialized_ops if op['gate'] == 'meas')
            )
            qubit_numbers.append(self._num_qubits(circuit))
        if metadata is not None:
            new_entries = {
                "measurements": json.dumps(measurements),
                "qubit_numbers": json.dumps(qubit_numbers),
            }
            metadata.update(new_entries)
        else:
            metadata = {
                "measurements": json.dumps(measurements),
                "qubit_numbers": json.dumps(qubit_numbers),
            }
        return SerializedProgram(
            input=program_input,
            settings=(job_settings or {}),
            compilation=(compilation or {}),
            error_mitigation=(error_mitigation or {}),
            noise=(noise or {}),
            metadata=(metadata or {}),
            dry_run=dry_run,
        )
    def _validate_circuit(self, circuit: cirq.AbstractCircuit):
        if len(circuit) == 0:
            raise ValueError('Cannot serialize empty circuit.')
        if not circuit.are_all_measurements_terminal():
            raise ValueError('All measurements in circuit must be at end of circuit.')
    def _validate_qubits(self, all_qubits: Collection[cirq.Qid]):
        if any(not isinstance(q, line_qubit.LineQubit) for q in all_qubits):
            raise ValueError(
                f'All qubits must be cirq.LineQubits but were {set(type(q) for q in all_qubits)}'
            )
        if any(cast(line_qubit.LineQubit, q).x < 0 for q in all_qubits):
            raise ValueError(
                'IonQ API must use LineQubits from 0 to number of qubits - 1. Instead found line '
                f'qubits with indices {all_qubits}.'
            )
    def _num_qubits(self, circuit: cirq.AbstractCircuit) -> int:
        all_qubits = circuit.all_qubits()
        return cast(line_qubit.LineQubit, max(all_qubits)).x + 1
    def _serialize_circuit(self, circuit: cirq.AbstractCircuit) -> list[dict]:
        return [
            serialized_op
            for moment in circuit
            for op in moment
            for serialized_op in [self._serialize_op(op)]
            if serialized_op != {}
        ]
    def _serialize_op(self, op: cirq.Operation) -> dict:
        if op.gate is None:
            raise ValueError(
                'Attempt to serialize circuit with an operation which does not have a gate. '
                f'Type: {type(op)} Op: {op}.'
            )
        targets = [cast(line_qubit.LineQubit, q).x for q in op.qubits]
        gate = op.gate
        if cirq.is_parameterized(gate):
            raise ValueError(
                f'IonQ API does not support parameterized gates. Gate {gate} was parameterized. '
                'Consider resolving before sending.'
            )
        gate_type = type(gate)
        for gate_mro_type in gate_type.mro():
            if gate_mro_type in self._dispatch:
                serialized_op = self._dispatch[gate_mro_type](gate, targets)
                if serialized_op == {} or serialized_op:
                    return serialized_op
        raise ValueError(f'Gate {gate} acting on {targets} cannot be serialized by IonQ API.')
    def _serialize_x_pow_gate(self, gate: cirq.XPowGate, targets: Sequence[int]) -> dict:
        if self._near_mod_n(gate.exponent, 1, 2):
            return {'gate': 'x', 'targets': targets}
        elif self._near_mod_n(gate.exponent, 0.5, 2):
            return {'gate': 'v', 'targets': targets}
        elif self._near_mod_n(gate.exponent, -0.5, 2):
            return {'gate': 'vi', 'targets': targets}
        return {'gate': 'rx', 'targets': targets, 'rotation': gate.exponent * np.pi}
    def _serialize_y_pow_gate(self, gate: cirq.YPowGate, targets: Sequence[int]) -> dict:
        if self._near_mod_n(gate.exponent, 1, 2):
            return {'gate': 'y', 'targets': targets}
        return {'gate': 'ry', 'targets': targets, 'rotation': gate.exponent * np.pi}
    def _serialize_z_pow_gate(self, gate: cirq.ZPowGate, targets: Sequence[int]) -> dict:
        if self._near_mod_n(gate.exponent, 1, 2):
            return {'gate': 'z', 'targets': targets}
        elif self._near_mod_n(gate.exponent, 0.5, 2):
            return {'gate': 's', 'targets': targets}
        elif self._near_mod_n(gate.exponent, -0.5, 2):
            return {'gate': 'si', 'targets': targets}
        elif self._near_mod_n(gate.exponent, 0.25, 2):
            return {'gate': 't', 'targets': targets}
        elif self._near_mod_n(gate.exponent, -0.25, 2):
            return {'gate': 'ti', 'targets': targets}
        return {'gate': 'rz', 'targets': targets, 'rotation': gate.exponent * np.pi}
    def _serialize_xx_pow_gate(self, gate: cirq.XXPowGate, targets: Sequence[int]) -> dict:
        return self._serialize_parity_pow_gate(gate, targets, 'xx')
    def _serialize_yy_pow_gate(self, gate: cirq.YYPowGate, targets: Sequence[int]) -> dict:
        return self._serialize_parity_pow_gate(gate, targets, 'yy')
    def _serialize_zz_pow_gate(self, gate: cirq.ZZPowGate, targets: Sequence[int]) -> dict:
        return self._serialize_parity_pow_gate(gate, targets, 'zz')
    def _serialize_parity_pow_gate(
        self, gate: cirq.EigenGate, targets: Sequence[int], name: str
    ) -> dict:
        return {'gate': name, 'targets': targets, 'rotation': gate.exponent * np.pi}
    def _serialize_swap_gate(self, gate: cirq.SwapPowGate, targets: Sequence[int]) -> dict | None:
        if self._near_mod_n(gate.exponent, 1, 2):
            return {'gate': 'swap', 'targets': targets}
        return None
    def _serialize_h_pow_gate(self, gate: cirq.HPowGate, targets: Sequence[int]) -> dict | None:
        if self._near_mod_n(gate.exponent, 1, 2):
            return {'gate': 'h', 'targets': targets}
        return None
    def _serialize_pauli_string_phasor_gate(
        self, gate: PauliStringPhasorGate, targets: Sequence[int]
    ) -> dict[str, Any] | None:
        PAULIS = {0: "I", 1: "X", 2: "Y", 3: "Z"}
        big_endian_pauli_string = ''.join(
            [PAULIS[pindex] for pindex in gate.dense_pauli_string.pauli_mask]
        )
        little_endian_pauli_string = big_endian_pauli_string[::-1]
        pauli_string_coefficient = gate.dense_pauli_string.coefficient
        coefficients = [pauli_string_coefficient.real]
        time = math.pi * (gate.exponent_neg - gate.exponent_pos) / 2
        if time < 0:
            raise NotSupportedPauliexpParameters(
                'IonQ `pauliexp` gates does not support negative evolution times. '
                f'Found in a PauliStringPhasorGate a negative evolution time {time}.'
            )
        if little_endian_pauli_string == "" or time == 0:
            seralized_gate = {}
        else:
            seralized_gate = {
                'gate': 'pauliexp',
                'terms': [little_endian_pauli_string],
                "coefficients": coefficients,
                'targets': targets,
                'time': time,
            }
        return seralized_gate
    def _serialize_gpi_gate(self, gate: GPIGate, targets: Sequence[int]) -> dict | None:
        return {'gate': 'gpi', 'target': targets[0], 'phase': gate.phase}
    def _serialize_gpi2_gate(self, gate: GPI2Gate, targets: Sequence[int]) -> dict | None:
        return {'gate': 'gpi2', 'target': targets[0], 'phase': gate.phase}
    def _serialize_ms_gate(self, gate: MSGate, targets: Sequence[int]) -> dict | None:
        return {'gate': 'ms', 'targets': targets, 'phases': gate.phases, 'angle': gate.theta}
    def _serialize_zz_gate(self, gate: ZZGate, targets: Sequence[int]) -> dict | None:
        return {'gate': 'zz', 'targets': targets, 'phase': gate.phase}
    def _serialize_cnot_pow_gate(
        self, gate: cirq.CNotPowGate, targets: Sequence[int]
    ) -> dict | None:
        if self._near_mod_n(gate.exponent, 1, 2):
            return {'gate': 'cnot', 'control': targets[0], 'target': targets[1]}
        return None
    def _serialize_measurement_gate(
        self, gate: cirq.MeasurementGate, targets: Sequence[int]
    ) -> dict:
        key = cirq.measurement_key_name(gate)
        if chr(31) in key or chr(30) in key:
            raise ValueError(
                'Measurement gates for IonQ API cannot have a key with a ascii unit'
                f'or record separator in it. Key was {key}'
            )
        return {'gate': 'meas', 'key': key, 'targets': ','.join(str(t) for t in targets)}
    def _near_mod_n(self, e: float | sympy.Expr, t: float, n: float) -> bool:
        return abs((cast(float, e) - t + 1) % n - 1) <= self.atol
    def _serialize_measurements(self, meas_ops: Iterator) -> dict[str, str]:
        key_values = [f'{op["key"]}{chr(31)}{op["targets"]}' for op in meas_ops]
        full_str = chr(30).join(key_values)
        max_value_size = 40
        split_strs = [
            full_str[i : i + max_value_size] for i in range(0, len(full_str), max_value_size)
        ]
        if len(split_strs) > 9:
            raise ValueError(
                'Measurement keys plus target strings too long for IonQ API. Please use '
                'smaller keys.'
            )
        return {f'measurement{i}': x for i, x in enumerate(split_strs)}

from __future__ import annotations
import datetime
import os
from unittest import mock
import numpy as np
import pandas as pd
import pytest
import sympy
import cirq
import cirq_ionq as ionq
@pytest.mark.parametrize(
    'target,expected_results', [('qpu', [[0], [1], [1], [1]]), ('simulator', [[1], [0], [1], [1]])]
)
def test_service_run(target, expected_results):
    service = ionq.Service(remote_host='http://example.com', api_key='key')
    mock_client = mock.MagicMock()
    mock_client.create_job.return_value = {'id': 'job_id', 'status': 'ready'}
    mock_client.get_job.return_value = {
        'id': 'job_id',
        'status': 'completed',
        'backend': target,
        'metadata': {'shots': '4', 'measurement0': f'a{chr(31)}0'},
        'stats': {'qubits': '1'},
    }
    mock_client.get_results.return_value = {'0': '0.25', '1': '0.75'}
    service._client = mock_client
    a = sympy.Symbol('a')
    q = cirq.LineQubit(0)
    circuit = cirq.Circuit((cirq.X**a)(q), cirq.measure(q, key='a'))
    params = cirq.ParamResolver({'a': 0.5})
    result = service.run(
        circuit=circuit, repetitions=4, target=target, name='bacon', param_resolver=params, seed=2
    )
    assert result == cirq.ResultDict(params=params, measurements={'a': np.array(expected_results)})
    create_job_kwargs = mock_client.create_job.call_args[1]
    assert create_job_kwargs['serialized_program'].input['qubits'] == 1
    assert create_job_kwargs['serialized_program'].metadata == {'measurement0': f'a{chr(31)}0'}
    assert create_job_kwargs['repetitions'] == 4
    assert create_job_kwargs['target'] == target
    assert create_job_kwargs['name'] == 'bacon'
@pytest.mark.parametrize(
    'target,expected_results1,expected_results2',
    [
        ('qpu', [[0], [1], [1], [1]], [[1], [1], [1], [1]]),
        ('simulator', [[1], [0], [1], [1]], [[1], [1], [1], [1]]),
    ],
)
def test_service_run_batch(target, expected_results1, expected_results2):
    service = ionq.Service(remote_host='http://example.com', api_key='key')
    mock_client = mock.MagicMock()
    mock_client.create_job.return_value = {'id': 'job_id', 'status': 'ready'}
    mock_client.get_job.return_value = {
        'id': 'job_id',
        'status': 'completed',
        'backend': target,
        'metadata': {
            'shots': '4',
            'measurements': (
                "[{\"measurement0\": \"a\\u001f0\"}, {\"measurement0\": \"b\\u001f0\"}]"
            ),
            'qubit_numbers': '[1, 1]',
        },
        'stats': {'qubits': '1'},
    }
    mock_client.get_results.return_value = {
        "xxx": {'0': '0.25', '1': '0.75'},
        "yyy": {'0': '0', '1': '1'},
    }
    service._client = mock_client
    a = sympy.Symbol('a')
    b = sympy.Symbol('b')
