from __future__ import annotations
from collections.abc import Sequence
from typing import cast, TYPE_CHECKING
import duet
import cirq
if TYPE_CHECKING:
    import cirq_google as cg
class ProcessorSampler(cirq.Sampler):
    def __init__(
        self,
        *,
        processor: cg.engine.AbstractProcessor,
        run_name: str = "",
        snapshot_id: str = "",
        device_config_name: str = "",
        max_concurrent_jobs: int = 100,
    ):
        if (bool(run_name) or bool(snapshot_id)) ^ bool(device_config_name):
            raise ValueError('Cannot specify only one of `run_name` and `device_config_name`')
        self._processor = processor
        self._run_name = run_name
        self._snapshot_id = snapshot_id
        self._device_config_name = device_config_name
        self._concurrent_job_limiter = duet.Limiter(max_concurrent_jobs)
    async def run_sweep_async(
        self, program: cirq.AbstractCircuit, params: cirq.Sweepable, repetitions: int = 1
    ) -> Sequence[cg.EngineResult]:
        async with self._concurrent_job_limiter:
            job = await self._processor.run_sweep_async(
                program=program,
                params=params,
                repetitions=repetitions,
                run_name=self._run_name,
                snapshot_id=self._snapshot_id,
                device_config_name=self._device_config_name,
            )
            return await job.results_async()
    run_sweep = duet.sync(run_sweep_async)
    async def run_batch_async(
        self,
        programs: Sequence[cirq.AbstractCircuit],
        params_list: Sequence[cirq.Sweepable] | None = None,
        repetitions: int | Sequence[int] = 1,
    ) -> Sequence[Sequence[cg.EngineResult]]:
        return cast(
            Sequence[Sequence['cg.EngineResult']],
            await super().run_batch_async(programs, params_list, repetitions),
        )
    run_batch = duet.sync(run_batch_async)
    @property
    def processor(self) -> cg.engine.AbstractProcessor:
        return self._processor
    @property
    def run_name(self) -> str:
        return self._run_name
    @property
    def snapshot_id(self) -> str:
        return self._snapshot_id  # pragma: no cover
    @property
    def device_config_name(self) -> str:
        return self._device_config_name
    @property
    def max_concurrent_jobs(self) -> int:
        assert self._concurrent_job_limiter.capacity is not None
        return self._concurrent_job_limiter.capacity

from __future__ import annotations
from collections.abc import Sequence
import cirq
_BASE_LATENCY = 1.5
def _initial_time(width, depth, sweeps):
    return ((width / 8) * (depth / 125) + (width / 12)) * max(1, sweeps / 5)
def _rep_time(width: int, depth: int, sweeps: int, reps: int) -> float:
    total_reps = sweeps * reps
    rep_rate = 24000 / (0.9 + width / 38) / (0.9 + depth / 5000)
    if sweeps > 1:
        rep_rate *= 0.72
        if width < 55:
            rep_rate *= 1 - (width - 25) / 40
        else:
            rep_rate *= 0.25
    return total_reps / rep_rate
def _estimate_run_time_seconds(
    width: int, depth: int, sweeps: int, repetitions: int, latency: float | None = _BASE_LATENCY
) -> float:
    init_time = _initial_time(width, depth, sweeps)
    rep_time = _rep_time(width, depth, sweeps, repetitions)
    return rep_time + init_time + latency
def estimate_run_time(
    program: cirq.AbstractCircuit, repetitions: int, latency: float | None = _BASE_LATENCY
) -> float:
    width = len(program.all_qubits())
    depth = len(program)
    return _estimate_run_time_seconds(width, depth, 1, repetitions, latency)
def estimate_run_sweep_time(
    program: cirq.AbstractCircuit,
    params: cirq.Sweepable = None,
    repetitions: int = 1000,
    latency: float | None = _BASE_LATENCY,
) -> float:
    width = len(program.all_qubits())
    depth = len(program)
    sweeps = len(list(cirq.to_resolvers(params)))
    return _estimate_run_time_seconds(width, depth, sweeps, repetitions, latency)
def estimate_run_batch_time(
    programs: Sequence[cirq.AbstractCircuit],
    params_list: list[cirq.Sweepable],
    repetitions: int = 1000,
    latency: float = _BASE_LATENCY,
) -> float:
    total_time = 0.0
    current_width = None
    total_depth = 0
    total_sweeps = 0
    num_circuits = 0
    for idx, program in enumerate(programs):
        width = len(program.all_qubits())
        if width != current_width:
            if num_circuits > 0:
                total_time += _estimate_run_time_seconds(
                    width, total_depth // num_circuits, total_sweeps, repetitions, 0.25
                )
            num_circuits = 0
            total_depth = 0
            total_sweeps = 0
            current_width = width
        total_depth += len(program)
        num_circuits += 1
        total_sweeps += len(list(cirq.to_resolvers(params_list[idx])))
    if num_circuits > 0:
        total_time += _estimate_run_time_seconds(
            width, total_depth // num_circuits, total_sweeps, repetitions, 0.0
        )
    return total_time + latency

