def create_noiseless_virtual_engine_from_device(
    processor_id: str,
    device: cirq.Device,
    device_specification: v2.device_pb2.DeviceSpecification | None = None,
) -> SimulatedLocalEngine:
    return SimulatedLocalEngine(
