def arg_to_proto(
    value: ARG_LIKE | None, *, out: v2.program_pb2.Arg | None = None
) -> v2.program_pb2.Arg:
    msg = v2.program_pb2.Arg() if out is None else out
    if value is None:
        return msg
    if isinstance(value, (bool, np.bool_)):
        msg.arg_value.bool_value = bool(value)
    elif isinstance(value, FLOAT_TYPES):
        msg.arg_value.float_value = float(value)
    elif isinstance(value, complex):
        msg.arg_value.complex_value.real_value = value.real
        msg.arg_value.complex_value.imag_value = value.imag
    elif isinstance(value, bytes):
        msg.arg_value.bytes_value = value
    elif isinstance(value, str):
        msg.arg_value.string_value = value
    elif isinstance(value, (list, tuple, np.ndarray, set, frozenset)):
        if isinstance(value, np.ndarray):
            _ndarray_to_proto(value, out=msg)
        elif len(value) == 0:
            _tuple_to_proto(value, out=msg.arg_value.tuple_value)
        elif isinstance(value, list) and isinstance(value[0], str):
            if not all(isinstance(x, str) for x in value):
                _tuple_to_proto(value, out=msg.arg_value.tuple_value)
                return msg
            msg.arg_value.string_values.values.extend(str(x) for x in value)
        else:
            numerical_fields = [
                [msg.arg_value.bool_values.values, (bool, np.bool_)],
                [msg.arg_value.int64_values.values, (int, np.integer, bool)],
                [msg.arg_value.double_values.values, (float, np.floating, int, bool)],
            ]
            cur_index = 0
            non_numerical = None
            for v in value:
                while cur_index < len(numerical_fields) and not isinstance(
                    v, numerical_fields[cur_index][1]
                ):
                    cur_index += 1
                if cur_index == len(numerical_fields):
                    non_numerical = v
                    break
            if non_numerical is not None:
                _tuple_to_proto(value, out=msg.arg_value.tuple_value)
                return msg
            field, types_tuple = numerical_fields[cur_index]
            field.extend(types_tuple[0](x) for x in value)
    elif isinstance(value, tunits.Value):
        msg.arg_value.value_with_unit.MergeFrom(value.to_proto())
    elif isinstance(value, MeasurementKey):
        msg.measurement_key.string_key = value.name
        msg.measurement_key.path.extend(value.path)
    else:
        _arg_func_to_proto(value, msg)
    return msg
def dict_to_arg_mapping_proto(
    value_dict: dict[ARG_LIKE, ARG_LIKE] | None, *, out: v2.program_pb2.ArgMapping | None = None
) -> v2.program_pb2.ArgMapping:
    msg = v2.program_pb2.ArgMapping() if out is None else out
    if value_dict is None:
        return msg
    for key, value in value_dict.items():
        entry = msg.entries.add()
        arg_to_proto(key, out=entry.key)
        arg_to_proto(value, out=entry.value)
    return msg
def _ndarray_to_proto(value: np.ndarray, out: v2.program_pb2.Arg):
    ndarray_msg = out.arg_value.ndarray_value
    match value.dtype:
        case np.float64:
            ndarrays.to_float64_array(value, out=ndarray_msg.float64_array)
        case np.float32:
            ndarrays.to_float32_array(value, out=ndarray_msg.float32_array)
        case np.float16:
            ndarrays.to_float16_array(value, out=ndarray_msg.float16_array)
        case np.int64:
            ndarrays.to_int64_array(value, out=ndarray_msg.int64_array)
        case np.int32:
            ndarrays.to_int32_array(value, out=ndarray_msg.int32_array)
        case np.int16:
            ndarrays.to_int16_array(value, out=ndarray_msg.int16_array)
        case np.int8:
            ndarrays.to_int8_array(value, out=ndarray_msg.int8_array)
        case np.uint8:
            ndarrays.to_uint8_array(value, out=ndarray_msg.uint8_array)
        case np.complex128:
            ndarrays.to_complex128_array(value, out=ndarray_msg.complex128_array)
        case np.complex64:
            ndarrays.to_complex64_array(value, out=ndarray_msg.complex64_array)
        case np.bool_:
            ndarrays.to_bitarray(value, out=ndarray_msg.bit_array)
def _ndarray_from_proto(msg: v2.program_pb2.ArgValue):
    ndarray_msg = msg.ndarray_value
    match ndarray_msg.WhichOneof('arr'):
        case 'float64_array':
            return ndarrays.from_float64_array(ndarray_msg.float64_array)
        case 'float32_array':
            return ndarrays.from_float32_array(ndarray_msg.float32_array)
        case 'float16_array':
            return ndarrays.from_float16_array(ndarray_msg.float16_array)
        case 'int64_array':
            return ndarrays.from_int64_array(ndarray_msg.int64_array)
        case 'int32_array':
            return ndarrays.from_int32_array(ndarray_msg.int32_array)
        case 'int16_array':
            return ndarrays.from_int16_array(ndarray_msg.int16_array)
        case 'int8_array':
            return ndarrays.from_int8_array(ndarray_msg.int8_array)
        case 'uint8_array':
            return ndarrays.from_uint8_array(ndarray_msg.uint8_array)
        case 'complex128_array':
            return ndarrays.from_complex128_array(ndarray_msg.complex128_array)
        case 'complex64_array':
            return ndarrays.from_complex64_array(ndarray_msg.complex64_array)
        case 'bit_array':
            return ndarrays.from_bitarray(ndarray_msg.bit_array)
def _tuple_to_proto(value: list | tuple | set | frozenset, out: v2.program_pb2.Tuple):
    if isinstance(value, list):
        out.sequence_type = v2.program_pb2.Tuple.SequenceType.LIST
    elif isinstance(value, tuple):
        out.sequence_type = v2.program_pb2.Tuple.SequenceType.TUPLE
    elif isinstance(value, set):
        out.sequence_type = v2.program_pb2.Tuple.SequenceType.SET
    elif isinstance(value, frozenset):
        out.sequence_type = v2.program_pb2.Tuple.SequenceType.FROZENSET
    else:
        out.sequence_type = v2.program_pb2.Tuple.SequenceType.UNSPECIFIED  # pragma: nocover
    for arg in value:
        new_arg = out.values.add()
        arg_to_proto(arg, out=new_arg)
def _arg_func_to_proto(value: ARG_LIKE, msg: v2.program_pb2.Arg | v2.program_pb2.FloatArg) -> None:
    if isinstance(value, sympy.Symbol):
        msg.symbol = str(value.free_symbols.pop())
    elif isinstance(value, _SUPPORTED_SYMPY_TYPES):
        msg.func.type = _SUPPORTED_SYMPY_TYPE_MAPPING[type(value)]
        for arg in value.args:
            arg_to_proto(arg, out=msg.func.args.add())
    elif isinstance(value, sympy.Indexed):
        msg.func.type = "[]"
        arg_to_proto(value.base.label, out=msg.func.args.add())
        for arg in value.indices:
            arg_to_proto(arg, out=msg.func.args.add())
    else:
        raise ValueError(
            f"Unrecognized Sympy expression type: {type(value)}."
            " Only the following types are recognized: 'sympy.Symbol', 'sympy.Add', 'sympy.Mul',"
            " 'sympy.Pow', and sympy comparison types."
        )
def float_arg_from_proto(
    arg_proto: v2.program_pb2.FloatArg, *, required_arg_name: str | None = None
) -> FLOAT_ARG_LIKE | None:
    which = arg_proto.WhichOneof('arg')
    match which:
        case 'float_value':
            result = float(arg_proto.float_value)
            if round(result) == result:
                result = int(result)
            return result
        case 'symbol':
            return sympy.Symbol(arg_proto.symbol)
        case 'func':
            func = _arg_func_from_proto(arg_proto.func, required_arg_name=required_arg_name)
            if func is None and required_arg_name is not None:
                raise ValueError(  # pragma: no cover
                    f'Arg {arg_proto.func} could not be processed for {required_arg_name}.'
                )
            return cast(FLOAT_ARG_LIKE, func)
        case None:
            if required_arg_name is not None:
                raise ValueError(f'Arg {required_arg_name} is missing.')
            return None
    raise ValueError(f'unrecognized argument type ({which}).')
def arg_from_proto(
    arg_proto: v2.program_pb2.Arg, *, required_arg_name: str | None = None
) -> ARG_RETURN_LIKE | None:
    which = arg_proto.WhichOneof('arg')
    match which:
        case 'arg_value':
            arg_value = arg_proto.arg_value
            which_val = arg_value.WhichOneof('arg_value')
            match which_val:
                case 'float_value':
                    result = float(arg_value.float_value)
                    if math.ceil(result) == math.floor(result):
                        return int(result)
                    return result
                case 'double_value':
                    result = float(arg_value.double_value)
                    if math.ceil(result) == math.floor(result):
                        return int(result)
                    return result
                case 'bool_value':
                    return bool(arg_value.bool_value)
                case 'bool_values':
                    return list(arg_value.bool_values.values)
                case 'string_value':
                    return str(arg_value.string_value)
                case 'int64_values':
                    return [int(v) for v in arg_value.int64_values.values]
                case 'double_values':
                    return [float(v) for v in arg_value.double_values.values]
                case 'string_values':
                    return [str(v) for v in arg_value.string_values.values]
                case 'value_with_unit':
                    return tunits.Value.from_proto(arg_value.value_with_unit)
                case 'bytes_value':
                    return bytes(arg_value.bytes_value)
                case 'complex_value':
                    return complex(
                        arg_value.complex_value.real_value, arg_value.complex_value.imag_value
                    )
                case 'tuple_value':
                    values = (
                        arg_from_proto(tuple_proto) for tuple_proto in arg_value.tuple_value.values
                    )
                    sequence_type = arg_value.tuple_value.sequence_type
                    match sequence_type:
                        case v2.program_pb2.Tuple.SequenceType.LIST:
                            return list(values)
                        case v2.program_pb2.Tuple.SequenceType.TUPLE:
                            return tuple(values)
                        case v2.program_pb2.Tuple.SequenceType.SET:
                            return set(values)
                        case v2.program_pb2.Tuple.SequenceType.FROZENSET:
                            return frozenset(values)
                    raise ValueError(f'Unrecognized type: {sequence_type}')  # pragma: no cover
                case 'ndarray_value':
                    return _ndarray_from_proto(arg_value)
            raise ValueError(f'Unrecognized value type: {which_val!r}')  # pragma: no cover
        case 'symbol':
            return sympy.Symbol(arg_proto.symbol)
        case 'func':
            func = _arg_func_from_proto(arg_proto.func, required_arg_name=required_arg_name)
            if func is not None:
                return func
        case 'measurement_key':
            return MeasurementKey(
                name=arg_proto.measurement_key.string_key,
                path=tuple(arg_proto.measurement_key.path),
            )
    if required_arg_name is not None:
        raise ValueError(
            f'{required_arg_name} is missing or has an unrecognized '
            f'argument type (WhichOneof("arg")={which!r}).'
        )
    return None
def dict_from_arg_mapping_proto(
    arg_mapping_proto: v2.program_pb2.ArgMapping, *, required_arg_name: str | None = None
) -> dict[ARG_LIKE, ARG_LIKE] | None:
    if not arg_mapping_proto.entries:
        return None
    return {
        arg_from_proto(entry.key, required_arg_name=required_arg_name): arg_from_proto(
            entry.value, required_arg_name=required_arg_name
        )
        for entry in arg_mapping_proto.entries
    }
def _arg_func_from_proto(
    func: v2.program_pb2.ArgFunction, *, required_arg_name: str | None = None
) -> ARG_RETURN_LIKE | None:
    if (op_expr := _SYMPY_EXPR_PER_TYPE.get(func.type, None)) is not None:
        return op_expr(
            *[arg_from_proto(a, required_arg_name=f'An {func.type} argument') for a in func.args]
        )
    if func.type == "[]":
        base = sympy.IndexedBase(arg_from_proto(func.args[0]))
        args = [arg_from_proto(a) for a in func.args[1:]]
        return sympy.Indexed(base, *args)
    raise ValueError(f'Unrecognized sympy function {func}')
def condition_to_proto(control: Condition, *, out: v2.program_pb2.Arg) -> v2.program_pb2.Arg:
    if isinstance(control, KeyCondition):
        out.measurement_key.string_key = control.key.name
        out.measurement_key.path.extend(control.key.path)
        out.measurement_key.index = control.index
    elif isinstance(control, SympyCondition):
        arg_to_proto(control.expr, out=out)
    elif isinstance(control, BitMaskKeyCondition):
        if control.equal_target:
            out.func.type = "bitmask=="
        else:
            out.func.type = "bitmask!="
        key_proto = out.func.args.add().measurement_key
        key_proto.string_key = control.key.name
        key_proto.path.extend(control.key.path)
        key_proto.index = control.index
        target_proto = out.func.args.add()
        arg_to_proto(control.target_value, out=target_proto)
        if control.bitmask is not None:
            bitmask_proto = out.func.args.add()
            arg_to_proto(control.bitmask, out=bitmask_proto)
    return out
def condition_from_proto(condition: v2.program_pb2.Arg) -> Condition:
    which = condition.WhichOneof("arg")
    if which == 'measurement_key':
        key = condition.measurement_key
        return KeyCondition(
            key=MeasurementKey(key.string_key, path=tuple(key.path)), index=key.index
        )
    elif which == 'func':
        if condition.func.type == "bitmask==" or condition.func.type == "bitmask!=":
            key = condition.func.args[0].measurement_key
            if len(condition.func.args) > 2:
                bitmask = int(arg_from_proto(condition.func.args[2]))  # type: ignore
            else:
                bitmask = None
            return BitMaskKeyCondition(
                key=MeasurementKey(key.string_key, path=tuple(key.path)),
                index=key.index,
                target_value=int(arg_from_proto(condition.func.args[1])),  # type: ignore
                equal_target=(condition.func.type == "bitmask=="),
                bitmask=bitmask,
            )
        else:
            expr = arg_from_proto(condition)
            return SympyCondition(expr)
    else:
        raise ValueError(f'Unrecognized condition {condition}')  # pragma: nocover
def internal_gate_arg_to_proto(
    value: InternalGate, *, out: v2.program_pb2.InternalGate | None = None
):
    msg = v2.program_pb2.InternalGate() if out is None else out
    msg.name = value.gate_name
    msg.module = value.gate_module
    msg.num_qubits = value.num_qubits()
    for k, v in value.gate_args.items():
        arg_to_proto(value=v, out=msg.gate_args[k])
    for ck, cv in value.custom_args.items():
        msg.custom_args[ck].MergeFrom(cv)
    return msg
def internal_gate_from_proto(msg: v2.program_pb2.InternalGate) -> InternalGate:
    gate_args = {}
    for k, v in msg.gate_args.items():
        gate_args[k] = arg_from_proto(v)
    return InternalGate(
        gate_name=str(msg.name),
        gate_module=str(msg.module),
        num_qubits=int(msg.num_qubits),
        custom_args=msg.custom_args,
        **gate_args,
    )
def clifford_tableau_arg_to_proto(
    value: CliffordTableau, *, out: v2.program_pb2.CliffordTableau | None = None
):
    msg = v2.program_pb2.CliffordTableau() if out is None else out
    msg.num_qubits = value.n
    msg.initial_state = value.initial_state
    msg.xs.extend(map(bool, value.xs.flatten()))
    msg.rs.extend(map(bool, value.rs.flatten()))
    msg.zs.extend(map(bool, value.zs.flatten()))
    return msg
def clifford_tableau_from_proto(msg: v2.program_pb2.CliffordTableau) -> CliffordTableau:
    return CliffordTableau(
        num_qubits=msg.num_qubits,
        initial_state=msg.initial_state,
        rs=np.array(msg.rs, dtype=bool) if msg.rs else None,
        xs=np.array(msg.xs, dtype=bool).reshape((2 * msg.num_qubits, -1)) if msg.xs else None,
        zs=np.array(msg.zs, dtype=bool).reshape((2 * msg.num_qubits, -1)) if msg.zs else None,
    )

from __future__ import annotations
import functools
import inspect
import warnings
from collections.abc import Callable, Hashable, Mapping, Sequence
from typing import Any
import sympy
import cirq
from cirq_google.api import v2
from cirq_google.experimental.ops import CouplerPulse
from cirq_google.ops import (
    AnalogDetuneCouplerOnly,
    AnalogDetuneQubit,
    CompressDurationTag,
    DynamicalDecouplingTag,
    FSimViaModelTag,
    InternalGate,
    InternalTag,
    PhysicalZTag,
    SycamoreGate,
    WaitGateWithUnit,
    WillowGate,
)
from cirq_google.ops.calibration_tag import CalibrationTag
from cirq_google.serialization import (
    arg_func_langs,
    op_deserializer,
    op_serializer,
    serializer,
    stimcirq_deserializer,
    stimcirq_serializer,
    tag_deserializer,
    tag_serializer,
)
_SERIALIZER_NAME = 'v2_5'
class CircuitSerializer(serializer.Serializer):
    def __init__(
        self,
        op_serializer: op_serializer.OpSerializer | None = None,
        op_deserializer: op_deserializer.OpDeserializer | None = None,
        tag_serializer: tag_serializer.TagSerializer | None = None,
        tag_deserializer: tag_deserializer.TagDeserializer | None = None,
        **kwargs,
    ):
        super().__init__(gate_set_name=_SERIALIZER_NAME)
        self.op_serializer = op_serializer
        self.op_deserializer = op_deserializer
        self.tag_serializer = tag_serializer
        self.tag_deserializer = tag_deserializer
        self.stimcirq_serializer = stimcirq_serializer.StimCirqSerializer()
        self.stimcirq_deserializer = stimcirq_deserializer.StimCirqDeserializer()
    def serialize(
        self, program: cirq.AbstractCircuit, msg: v2.program_pb2.Program | None = None
    ) -> v2.program_pb2.Program:
        if not isinstance(program, (cirq.Circuit, cirq.FrozenCircuit)):
            raise NotImplementedError(f'Unrecognized program type: {type(program)}')
        raw_constants: dict[Any, int] = {}
        if msg is None:
            msg = v2.program_pb2.Program()
        msg.language.gate_set = self.name
        msg.language.arg_function_language = 'exp'
        self._serialize_circuit(
            program, msg.circuit, constants=msg.constants, raw_constants=raw_constants
        )
        return msg
    def serialize_multi_program(
        self,
        multi_program: Sequence[cirq.AbstractCircuit] | Mapping[str, cirq.AbstractCircuit],
        msg: v2.program_pb2.Program | None = None,
    ) -> v2.program_pb2.Program:
        raw_constants: dict[Any, int] = {}
        if msg is None:
            msg = v2.program_pb2.Program()
        msg.language.gate_set = self.name
        msg.language.arg_function_language = 'exp'
        if isinstance(multi_program, Mapping):
            for key, program in multi_program.items():
                new_program = msg.keyed_circuits.add()
                new_program.key = key
                self._serialize_circuit(
                    program,
                    new_program.circuit,
                    constants=msg.constants,
                    raw_constants=raw_constants,
                )
        elif isinstance(multi_program, Sequence):
            for program in multi_program:
                new_program = msg.keyed_circuits.add()
                self._serialize_circuit(
                    program,
                    new_program.circuit,
                    constants=msg.constants,
                    raw_constants=raw_constants,
                )
        else:
            raise NotImplementedError(f'Unrecognized program type: {type(multi_program)}')
        return msg
    def serialize_circuit_function(
        self,
        circuit_function: (
            Callable[..., cirq.AbstractCircuit] | Callable[..., Mapping[str, cirq.AbstractCircuit]]
        ),
        sweep: cirq.Sweep,
        msg: v2.program_pb2.Program | None = None,
    ) -> v2.program_pb2.Program:
        raw_constants: dict[Any, int] = {}
        if msg is None:
            msg = v2.program_pb2.Program()
        msg.language.gate_set = self.name
        msg.language.arg_function_language = 'exp'
        if not callable(circuit_function):
            raise NotImplementedError(f'Unrecognized program type: {type(circuit_function)}')
        sig = inspect.signature(circuit_function)
        if all(p.kind != inspect.Parameter.VAR_KEYWORD for p in sig.parameters.values()):
            names = set(sig.parameters)
        else:
            names = None
        for param_tuple in sweep.param_tuples():
            if names is None:
                circuit_or_map = circuit_function(**dict(param_tuple))
            else:
                circuit_or_map = circuit_function(
                    **dict({k: v for k, v in param_tuple if k in names})
                )
            if isinstance(circuit_or_map, cirq.AbstractCircuit):
                circuit_tuples: Sequence[tuple[str, cirq.AbstractCircuit]] = [("", circuit_or_map)]
            elif isinstance(circuit_or_map, Mapping):
                circuit_tuples = list(circuit_or_map.items())
            else:
                raise ValueError(f'Function returned unrecognized type: {type(circuit_or_map)}')
            for key, circuit in circuit_tuples:
                new_program = msg.keyed_circuits.add()
                new_program.key = key
                for key, val in param_tuple:
                    arg_func_langs.arg_to_proto(val, out=new_program.args[key])
                self._serialize_circuit(
                    circuit,
                    new_program.circuit,
                    constants=msg.constants,
                    raw_constants=raw_constants,
                )
        return msg
    def _serialize_circuit(
        self,
        circuit: cirq.AbstractCircuit,
        msg: v2.program_pb2.Circuit,
        *,
        constants: list[v2.program_pb2.Constant],
        raw_constants: dict[Any, int],
    ) -> None:
        msg.scheduling_strategy = v2.program_pb2.Circuit.MOMENT_BY_MOMENT
        for moment in circuit:
            if (moment_index := raw_constants.get(moment, None)) is not None:
                msg.moment_indices.append(moment_index)
                continue
            else:
                moment_proto = v2.program_pb2.Moment()
            for op in moment:
                if isinstance(op.untagged, cirq.CircuitOperation) or (
                    isinstance(op.untagged, cirq.ClassicallyControlledOperation)
                    and isinstance(op.untagged.without_classical_controls(), cirq.CircuitOperation)
                ):
                    op_pb = moment_proto.circuit_operations.add()
                    self._serialize_circuit_op(
                        op.untagged.without_classical_controls(),  # type: ignore
                        op_pb,
                        constants=constants,
                        raw_constants=raw_constants,
                    )
                    for control in op.classical_controls:
                        arg_func_langs.condition_to_proto(control, out=op_pb.conditioned_on.add())
                else:
                    if (op_index := raw_constants.get(op, None)) is not None:
                        moment_proto.operation_indices.append(op_index)
                    else:
                        op_pb = v2.program_pb2.Operation()
                        if self.op_serializer and self.op_serializer.can_serialize_operation(op):
                            self.op_serializer.to_proto(
                                op, op_pb, constants=constants, raw_constants=raw_constants
                            )
                        elif self.stimcirq_serializer.can_serialize_operation(op):
                            self.stimcirq_serializer.to_proto(
                                op, op_pb, constants=constants, raw_constants=raw_constants
                            )
                        else:
                            self._serialize_gate_op(
                                op, op_pb, constants=constants, raw_constants=raw_constants
                            )
                        constants.append(v2.program_pb2.Constant(operation_value=op_pb))
                        op_index = len(constants) - 1
                        raw_constants[op] = op_index
                        moment_proto.operation_indices.append(op_index)
            for tag in moment.tags:
                self._serialize_tag(
                    tag, moment_proto, constants=constants, raw_constants=raw_constants
                )
            constants.append(v2.program_pb2.Constant(moment_value=moment_proto))
            moment_index = len(constants) - 1
            raw_constants[moment] = moment_index
            msg.moment_indices.append(moment_index)
        for tag in circuit.tags:
            self._serialize_tag(tag, msg, constants=constants, raw_constants=raw_constants)
    def _serialize_gate_op(
        self,
        op: cirq.Operation,
        msg: v2.program_pb2.Operation,
        *,
        constants: list[v2.program_pb2.Constant],
        raw_constants: dict[Any, int],
    ) -> v2.program_pb2.Operation:
        gate = op.gate
        if isinstance(op, cirq.ClassicallyControlledOperation):
            gate = op.without_classical_controls().gate
            for control in op.classical_controls:
                arg_func_langs.condition_to_proto(control, out=msg.conditioned_on.add())
        if isinstance(gate, InternalGate):
            arg_func_langs.internal_gate_arg_to_proto(gate, out=msg.internalgate)
        elif isinstance(gate, cirq.XPowGate):
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.xpowgate.exponent)
        elif isinstance(gate, cirq.YPowGate):
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.ypowgate.exponent)
        elif isinstance(gate, cirq.ZPowGate):
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.zpowgate.exponent)
            if any(isinstance(tag, PhysicalZTag) for tag in op.tags):
                msg.zpowgate.is_physical_z = True
        elif isinstance(gate, cirq.PhasedXPowGate):
            arg_func_langs.float_arg_to_proto(
                gate.phase_exponent, out=msg.phasedxpowgate.phase_exponent
            )
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.phasedxpowgate.exponent)
        elif isinstance(gate, cirq.PhasedXZGate):
            arg_func_langs.float_arg_to_proto(gate.x_exponent, out=msg.phasedxzgate.x_exponent)
            arg_func_langs.float_arg_to_proto(gate.z_exponent, out=msg.phasedxzgate.z_exponent)
            arg_func_langs.float_arg_to_proto(
                gate.axis_phase_exponent, out=msg.phasedxzgate.axis_phase_exponent
            )
        elif isinstance(gate, cirq.ops.SingleQubitCliffordGate):
            arg_func_langs.clifford_tableau_arg_to_proto(
                gate._clifford_tableau, out=msg.singlequbitcliffordgate.tableau
            )
        elif isinstance(gate, cirq.ops.IdentityGate):
            msg.identitygate.qid_shape.extend(cirq.qid_shape(gate))
        elif isinstance(gate, cirq.HPowGate):
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.hpowgate.exponent)
        elif isinstance(gate, cirq.CZPowGate):
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.czpowgate.exponent)
        elif isinstance(gate, cirq.ISwapPowGate):
            arg_func_langs.float_arg_to_proto(gate.exponent, out=msg.iswappowgate.exponent)
        elif isinstance(gate, SycamoreGate):
            msg.iswaplikegate.original_gate = v2.program_pb2.ISwapLikeGate.OriginalCirqGate.SYCAMORE
        elif isinstance(gate, WillowGate):
            msg.iswaplikegate.original_gate = v2.program_pb2.ISwapLikeGate.OriginalCirqGate.WILLOW
        elif isinstance(gate, cirq.FSimGate):
            arg_func_langs.float_arg_to_proto(gate.theta, out=msg.fsimgate.theta)
            arg_func_langs.float_arg_to_proto(gate.phi, out=msg.fsimgate.phi)
            if any(isinstance(tag, FSimViaModelTag) for tag in op.tags):
                msg.fsimgate.translate_via_model = True
        elif isinstance(gate, cirq.MeasurementGate):
            arg_func_langs.arg_to_proto(gate.key, out=msg.measurementgate.key)
            if len(gate.invert_mask):
                arg_func_langs.arg_to_proto(gate.invert_mask, out=msg.measurementgate.invert_mask)
        elif isinstance(gate, WaitGateWithUnit):  # WaitGateWithUnit is subclass of WaitGate.
            arg_func_langs.arg_to_proto(gate._duration, out=msg.wait_gate_with_unit.duration)
            msg.wait_gate_with_unit.qid_shape.extend(gate._qid_shape)
        elif isinstance(gate, cirq.WaitGate):
            arg_func_langs.float_arg_to_proto(
                gate.duration.total_nanos(), out=msg.waitgate.duration_nanos
            )
        elif isinstance(gate, cirq.ResetChannel):
            arg_func_langs.arg_to_proto(gate.dimension, out=msg.resetgate.arguments['dimension'])
        elif isinstance(gate, CouplerPulse):
            arg_func_langs.float_arg_to_proto(
                gate.hold_time.total_picos(), out=msg.couplerpulsegate.hold_time_ps
            )
            arg_func_langs.float_arg_to_proto(
                gate.rise_time.total_picos(), out=msg.couplerpulsegate.rise_time_ps
            )
            arg_func_langs.float_arg_to_proto(
                gate.padding_time.total_picos(), out=msg.couplerpulsegate.padding_time_ps
            )
            arg_func_langs.float_arg_to_proto(
                gate.coupling_mhz, out=msg.couplerpulsegate.coupling_mhz
            )
            arg_func_langs.float_arg_to_proto(
                gate.q0_detune_mhz, out=msg.couplerpulsegate.q0_detune_mhz
            )
            arg_func_langs.float_arg_to_proto(
                gate.q1_detune_mhz, out=msg.couplerpulsegate.q1_detune_mhz
            )
        elif isinstance(gate, cirq.DepolarizingChannel):
            arg_func_langs.float_arg_to_proto(
                gate.p, out=msg.noisechannel.depolarizingchannel.probability
            )
            msg.noisechannel.depolarizingchannel.num_qubits = len(op.qubits)
        elif isinstance(gate, cirq.RandomGateChannel):
            arg_func_langs.float_arg_to_proto(
                gate.probability, out=msg.noisechannel.randomgatechannel.probability
            )
            self._serialize_gate_op(
                gate.sub_gate(*op.qubits),
                msg=msg.noisechannel.randomgatechannel.sub_gate,
                constants=constants,
                raw_constants=raw_constants,
            )
        elif isinstance(gate, AnalogDetuneQubit):
            arg_func_langs.arg_to_proto(gate.length, out=msg.analog_detune_qubit.length)
            arg_func_langs.arg_to_proto(gate.w, out=msg.analog_detune_qubit.w)
            arg_func_langs.arg_to_proto(gate.target_freq, out=msg.analog_detune_qubit.target_freq)
            arg_func_langs.arg_to_proto(gate.prev_freq, out=msg.analog_detune_qubit.prev_freq)
            arg_func_langs.dict_to_arg_mapping_proto(
                gate.neighbor_coupler_g_dict, out=msg.analog_detune_qubit.neighbor_coupler_g_dict  # type: ignore[arg-type]
            )
            arg_func_langs.dict_to_arg_mapping_proto(
                gate.prev_neighbor_coupler_g_dict,  # type: ignore[arg-type]
                out=msg.analog_detune_qubit.prev_neighbor_coupler_g_dict,
            )
            msg.analog_detune_qubit.linear_rise = gate.linear_rise
        elif isinstance(gate, AnalogDetuneCouplerOnly):
            arg_func_langs.arg_to_proto(gate.length, out=msg.analog_detune_coupler_only.length)
            arg_func_langs.arg_to_proto(gate.w, out=msg.analog_detune_coupler_only.w)
            arg_func_langs.arg_to_proto(gate.g_0, out=msg.analog_detune_coupler_only.g_0)
            arg_func_langs.arg_to_proto(gate.g_max, out=msg.analog_detune_coupler_only.g_max)
            arg_func_langs.arg_to_proto(
                gate.g_ramp_exponent, out=msg.analog_detune_coupler_only.g_ramp_exponent
            )
            msg.analog_detune_coupler_only.neighbor_qubits_freq.extend(
                [arg_func_langs.arg_to_proto(q) for q in gate.neighbor_qubits_freq]
            )
            msg.analog_detune_coupler_only.prev_neighbor_qubits_freq.extend(
                [arg_func_langs.arg_to_proto(q) for q in gate.prev_neighbor_qubits_freq]
            )
            msg.analog_detune_coupler_only.interpolate_coupling_cal = gate.interpolate_coupling_cal
            msg.analog_detune_coupler_only.analog_cal_for_pulseshaping = (
                gate.analog_cal_for_pulseshaping
            )
        else:
            raise ValueError(f'Cannot serialize op {op!r} of type {type(gate)}')
        for qubit in op.qubits:
            if qubit not in raw_constants:
                constants.append(
                    v2.program_pb2.Constant(
                        qubit=v2.program_pb2.Qubit(id=v2.qubit_to_proto_id(qubit))
                    )
                )
                raw_constants[qubit] = len(constants) - 1
            msg.qubit_constant_index.append(raw_constants[qubit])
        for tag in op.tags:
            self._serialize_tag(tag, msg, constants=constants, raw_constants=raw_constants)
        return msg
    def _serialize_tag(
        self,
        tag: Hashable,
        msg: v2.program_pb2.Operation | v2.program_pb2.Moment | v2.program_pb2.Circuit,
        *,
        constants: list[v2.program_pb2.Constant],
        raw_constants: dict[Any, int],
    ):
        constant = v2.program_pb2.Constant()
        if (tag_index := raw_constants.get(tag, None)) is None:
            if self.tag_serializer and self.tag_serializer.can_serialize_tag(tag):
                self.tag_serializer.to_proto(
                    tag, msg=constant.tag_value, constants=constants, raw_constants=raw_constants
                )
            elif getattr(tag, 'to_proto', None) is not None:
                tag.to_proto(constant.tag_value)  # type: ignore
            else:
                try:
                    arg_func_langs.arg_to_proto(tag, out=constant.tag_value.raw_value)
                except ValueError:
                    raise ValueError(f'Unrecognized Tag {tag}, cannot serialize.')
            if constant.WhichOneof('const_value'):
                constants.append(constant)
                if raw_constants is not None:
                    raw_constants[tag] = len(constants) - 1
                msg.tag_indices.append(len(constants) - 1)
        else:
            msg.tag_indices.append(tag_index)
    def _serialize_circuit_op(
        self,
        op: cirq.CircuitOperation,
        msg: v2.program_pb2.CircuitOperation | None = None,
        *,
        constants: list[v2.program_pb2.Constant] | None = None,
        raw_constants: dict[Any, int] | None = None,
    ) -> v2.program_pb2.CircuitOperation:
        circuit = op.circuit
        if constants is None or raw_constants is None:
            raise ValueError(
                'CircuitOp serialization requires a constants list and a corresponding '
                'map of pre-serialization values to indices (raw_constants).'
            )
        serializer = op_serializer.CircuitOpSerializer()
        if circuit not in raw_constants:
            subcircuit_msg = v2.program_pb2.Circuit()
            self._serialize_circuit(
                circuit, subcircuit_msg, constants=constants, raw_constants=raw_constants
            )
            constants.append(v2.program_pb2.Constant(circuit_value=subcircuit_msg))
            raw_constants[circuit] = len(constants) - 1
        return serializer.to_proto(op, msg, constants=constants, raw_constants=raw_constants)
    def deserialize_multi_program(
        self, proto: v2.program_pb2.Program
    ) -> Sequence[tuple[str, tuple[tuple[str, Any], ...], cirq.AbstractCircuit]]:
        deserialized_constants: list[Any] = self._deserialize_constants(proto)
        return_circuits: list[tuple[str, tuple[tuple[str, Any], ...], cirq.AbstractCircuit]] = []
        for keyed_circuit in proto.keyed_circuits:
            key = keyed_circuit.key
            param_tuples = tuple(
                (param, arg_func_langs.arg_from_proto(arg))
                for param, arg in keyed_circuit.args.items()
            )
            circuit = self._deserialize_circuit(
                keyed_circuit.circuit,
                constants=proto.constants,
                deserialized_constants=deserialized_constants,
            )
            return_circuits.append((key, param_tuples, circuit))
        return return_circuits
    def deserialize(self, proto: v2.program_pb2.Program) -> cirq.Circuit:
        which = proto.WhichOneof('program')
        if which == 'circuit':
            deserialized_constants: list[Any] = self._deserialize_constants(proto)
            circuit = self._deserialize_circuit(
                proto.circuit,
                constants=proto.constants,
                deserialized_constants=deserialized_constants,
            )
            return circuit
        if which == 'schedule':
            raise ValueError('Deserializing a schedule is no longer supported.')
        raise NotImplementedError('Program proto does not contain a circuit.')
    def _deserialize_constants(self, proto: v2.program_pb2.Program) -> list[Any]:
        deserialized_constants: list[Any] = []
        for constant in proto.constants:
            which_const = constant.WhichOneof('const_value')
            if which_const == 'string_value':
                deserialized_constants.append(constant.string_value)  # pragma: nocover
            elif which_const == 'circuit_value':
                circuit = self._deserialize_circuit(
                    constant.circuit_value,
                    constants=proto.constants,
                    deserialized_constants=deserialized_constants,
                )
                deserialized_constants.append(circuit.freeze())
            elif which_const == 'qubit':
                deserialized_constants.append(v2.qubit_from_proto_id(constant.qubit.id))
            elif which_const == 'operation_value':
                if self.op_deserializer and self.op_deserializer.can_deserialize_proto(
                    constant.operation_value
                ):
                    op_pb = self.op_deserializer.from_proto(
                        constant.operation_value,
                        constants=proto.constants,
                        deserialized_constants=deserialized_constants,
                    )
                elif self.stimcirq_deserializer.can_deserialize_proto(constant.operation_value):
                    op_pb = self.stimcirq_deserializer.from_proto(
                        constant.operation_value,
                        constants=proto.constants,
                        deserialized_constants=deserialized_constants,
                    )
                else:
                    op_pb = self._deserialize_gate_op(
                        constant.operation_value,
                        constants=proto.constants,
                        deserialized_constants=deserialized_constants,
                    )
                deserialized_constants.append(op_pb)
            elif which_const == 'moment_value':
                deserialized_constants.append(
                    self._deserialize_moment(
                        constant.moment_value,
                        constants=proto.constants,
                        deserialized_constants=deserialized_constants,
                    )
                )
            elif which_const == 'tag_value':
                if self.tag_deserializer and self.tag_deserializer.can_deserialize_proto(
                    constant.tag_value
                ):
                    deserialized_constants.append(
                        self.tag_deserializer.from_proto(
                            constant.tag_value,
                            constants=proto.constants,
                            deserialized_constants=deserialized_constants,
                        )
                    )
                else:
                    deserialized_constants.append(self._deserialize_tag(constant.tag_value))
            else:
                msg = f'Unrecognized constant type {which_const}, ignoring.'  # pragma: no cover
                warnings.warn(msg)  # pragma: no cover
                deserialized_constants.append(None)  # pragma: no cover
        return deserialized_constants
    def _deserialize_circuit(
        self,
        circuit_proto: v2.program_pb2.Circuit,
        *,
        constants: list[v2.program_pb2.Constant],
        deserialized_constants: list[Any],
    ) -> cirq.Circuit:
        moments = []
        tags = []
        if circuit_proto.moments and circuit_proto.moment_indices:
            raise ValueError(
                'Circuit message must not have "moments" and '
                '"moment_indices" fields set at the same time.'
            )
        for moment_proto in circuit_proto.moments:
            moments.append(
                self._deserialize_moment(
                    moment_proto, constants=constants, deserialized_constants=deserialized_constants
                )
            )
        for moment_index in circuit_proto.moment_indices:
            moments.append(deserialized_constants[moment_index])
        for tag_index in circuit_proto.tag_indices:
            tags.append(deserialized_constants[tag_index])
        return cirq.Circuit(moments, tags=tags)
    def _deserialize_moment(
        self,
        moment_proto: v2.program_pb2.Moment,
        *,
        constants: list[v2.program_pb2.Constant],
        deserialized_constants: list[Any],
    ) -> cirq.Moment:
        moment_ops = []
        tags = []
        for op in moment_proto.operations:
            if self.op_deserializer and self.op_deserializer.can_deserialize_proto(op):
                gate_op = self.op_deserializer.from_proto(
                    op, constants=constants, deserialized_constants=deserialized_constants
                )
            elif self.stimcirq_deserializer.can_deserialize_proto(op):
                gate_op = self.stimcirq_deserializer.from_proto(
                    op, constants=constants, deserialized_constants=deserialized_constants
                )
            else:
                gate_op = self._deserialize_gate_op(
                    op, constants=constants, deserialized_constants=deserialized_constants
                )
            moment_ops.append(gate_op)
        for op in moment_proto.circuit_operations:
            moment_ops.append(
                self._deserialize_circuit_op(
                    op, constants=constants, deserialized_constants=deserialized_constants
                )
            )
        for operation_index in moment_proto.operation_indices:
            moment_ops.append(deserialized_constants[operation_index])
        for tag_index in moment_proto.tag_indices:
            tags.append(deserialized_constants[tag_index])
        moment = cirq.Moment(moment_ops, tags=tuple(tags))
        return moment
    def _deserialize_gate_op(
        self,
        operation_proto: v2.program_pb2.Operation,
        *,
        constants: list[v2.program_pb2.Constant] | None = None,
        deserialized_constants: list[Any] | None = None,
    ) -> cirq.Operation:
        if deserialized_constants is not None:
            qubits = [deserialized_constants[q] for q in operation_proto.qubit_constant_index]
        else:
            qubits = []
        for q in operation_proto.qubits:
            qubits.append(v2.qubit_from_proto_id(q.id))
        which_gate_type = operation_proto.WhichOneof('gate_value')
        if which_gate_type == 'xpowgate':
            op = cirq.XPowGate(
                exponent=arg_func_langs.float_arg_from_proto(
                    operation_proto.xpowgate.exponent, required_arg_name=None
                )
                or 0.0
            )(*qubits)
        elif which_gate_type == 'ypowgate':
            op = cirq.YPowGate(
                exponent=arg_func_langs.float_arg_from_proto(
                    operation_proto.ypowgate.exponent, required_arg_name=None
                )
                or 0.0
            )(*qubits)
        elif which_gate_type == 'zpowgate':
            op = cirq.ZPowGate(
                exponent=arg_func_langs.float_arg_from_proto(
                    operation_proto.zpowgate.exponent, required_arg_name=None
                )
                or 0.0
            )(*qubits)
            if operation_proto.zpowgate.is_physical_z:
                op = op.with_tags(PhysicalZTag())
        elif which_gate_type == 'hpowgate':
            op = cirq.HPowGate(
                exponent=arg_func_langs.float_arg_from_proto(
                    operation_proto.hpowgate.exponent, required_arg_name=None
                )
                or 0.0
            )(*qubits)
        elif which_gate_type == 'identitygate':
            op = cirq.IdentityGate(qid_shape=tuple(operation_proto.identitygate.qid_shape))(*qubits)
        elif which_gate_type == 'singlequbitcliffordgate':
            tableau = arg_func_langs.clifford_tableau_from_proto(
                operation_proto.singlequbitcliffordgate.tableau
            )
            op = cirq.ops.SingleQubitCliffordGate.from_clifford_tableau(tableau)(*qubits)
        elif which_gate_type == 'phasedxpowgate':
            exponent = (
                arg_func_langs.float_arg_from_proto(
                    operation_proto.phasedxpowgate.exponent, required_arg_name=None
                )
                or 0.0
            )
            phase_exponent = (
                arg_func_langs.float_arg_from_proto(
                    operation_proto.phasedxpowgate.phase_exponent, required_arg_name=None
                )
                or 0.0
            )
            op = cirq.PhasedXPowGate(exponent=exponent, phase_exponent=phase_exponent)(*qubits)
        elif which_gate_type == 'phasedxzgate':
            x_exponent = (
                arg_func_langs.float_arg_from_proto(
                    operation_proto.phasedxzgate.x_exponent, required_arg_name=None
                )
                or 0.0
            )
            z_exponent = (
                arg_func_langs.float_arg_from_proto(
                    operation_proto.phasedxzgate.z_exponent, required_arg_name=None
                )
                or 0.0
            )
            axis_phase_exponent = (
                arg_func_langs.float_arg_from_proto(
                    operation_proto.phasedxzgate.axis_phase_exponent, required_arg_name=None
                )
                or 0.0
            )
            op = cirq.PhasedXZGate(
                x_exponent=x_exponent,
                z_exponent=z_exponent,
                axis_phase_exponent=axis_phase_exponent,
            )(*qubits)
        elif which_gate_type == 'czpowgate':
            op = cirq.CZPowGate(
                exponent=arg_func_langs.float_arg_from_proto(
                    operation_proto.czpowgate.exponent, required_arg_name=None
                )
                or 0.0
            )(*qubits)
        elif which_gate_type == 'iswappowgate':
            op = cirq.ISwapPowGate(
                exponent=arg_func_langs.float_arg_from_proto(
                    operation_proto.iswappowgate.exponent, required_arg_name=None
                )
                or 0.0
            )(*qubits)
        elif which_gate_type == 'iswaplikegate':
            if (
                operation_proto.iswaplikegate.original_gate
                == v2.program_pb2.ISwapLikeGate.OriginalCirqGate.WILLOW
            ):
                op = WillowGate()(*qubits)
            else:
                op = SycamoreGate()(*qubits)
        elif which_gate_type == 'fsimgate':
            theta = arg_func_langs.float_arg_from_proto(
                operation_proto.fsimgate.theta, required_arg_name=None
            )
            phi = arg_func_langs.float_arg_from_proto(
                operation_proto.fsimgate.phi, required_arg_name=None
            )
            if isinstance(theta, (int, float, sympy.Basic)) and isinstance(
                phi, (int, float, sympy.Basic)
            ):
                op = cirq.FSimGate(theta=theta, phi=phi)(*qubits)
            else:
                raise ValueError('theta and phi must be specified for FSimGate')
            if operation_proto.fsimgate.translate_via_model:
                op = op.with_tags(FSimViaModelTag())
        elif which_gate_type == 'measurementgate':
            key = arg_func_langs.arg_from_proto(
                operation_proto.measurementgate.key, required_arg_name=None
            )
            parsed_invert_mask = arg_func_langs.arg_from_proto(
                operation_proto.measurementgate.invert_mask, required_arg_name=None
            )
            if (
                isinstance(parsed_invert_mask, (list, tuple)) or parsed_invert_mask is None
            ) and isinstance(key, str):
                invert_mask: tuple[bool, ...] = ()
                if parsed_invert_mask is not None:
                    invert_mask = tuple(bool(x) for x in parsed_invert_mask)
                op = cirq.MeasurementGate(num_qubits=len(qubits), key=key, invert_mask=invert_mask)(
                    *qubits
                )
            else:
                raise ValueError(f'Incorrect types for measurement gate {parsed_invert_mask} {key}')
        elif which_gate_type == 'waitgate':
            total_nanos = arg_func_langs.float_arg_from_proto(
                operation_proto.waitgate.duration_nanos, required_arg_name=None
            )
            op = cirq.WaitGate(
                duration=cirq.Duration(nanos=total_nanos or 0.0), num_qubits=len(qubits)
            )(*qubits)
        elif which_gate_type == 'resetgate':
            dimensions_proto = operation_proto.resetgate.arguments.get('dimension', None)
            if dimensions_proto is not None:
                dimensions = arg_func_langs.arg_from_proto(dimensions_proto)
            else:
                dimensions = 2
            if not isinstance(dimensions, int):
                raise ValueError(f"dimensions {dimensions} for ResetChannel must be an integer!")
            op = cirq.ResetChannel(dimension=dimensions)(*qubits)
        elif which_gate_type == 'internalgate':
            msg = operation_proto.internalgate
            op = arg_func_langs.internal_gate_from_proto(msg)(*qubits)
        elif which_gate_type == 'couplerpulsegate':
            gate = CouplerPulse(
                hold_time=cirq.Duration(
                    picos=arg_func_langs.float_arg_from_proto(
                        operation_proto.couplerpulsegate.hold_time_ps, required_arg_name=None
                    )
                    or 0.0
                ),
                rise_time=cirq.Duration(
                    picos=arg_func_langs.float_arg_from_proto(
                        operation_proto.couplerpulsegate.rise_time_ps, required_arg_name=None
                    )
                    or 0.0
                ),
                padding_time=cirq.Duration(
                    picos=arg_func_langs.float_arg_from_proto(
