from __future__ import annotations
import abc
from typing import Any
import sympy
import cirq
from cirq_google.api import v2
from cirq_google.serialization import arg_func_langs
class OpDeserializer(abc.ABC):
    @abc.abstractmethod
    def can_deserialize_proto(self, proto) -> bool:
    @abc.abstractmethod
    def from_proto(
        self, proto, *, constants: list[v2.program_pb2.Constant], deserialized_constants: list[Any]
    ) -> cirq.Operation:
class CircuitOpDeserializer(OpDeserializer):
    def can_deserialize_proto(self, proto):
        return isinstance(proto, v2.program_pb2.CircuitOperation)  # pragma: no cover
    def from_proto(
        self,
        proto: v2.program_pb2.CircuitOperation,
        *,
        constants: list[v2.program_pb2.Constant],
        deserialized_constants: list[Any],
    ) -> cirq.Operation:
        if len(deserialized_constants) <= proto.circuit_constant_index:
            raise ValueError(
                f'Constant index {proto.circuit_constant_index} in CircuitOperation '
                'does not appear in the deserialized_constants list '
                f'(length {len(deserialized_constants)}).'
            )
        circuit = deserialized_constants[proto.circuit_constant_index]
        if not isinstance(circuit, cirq.FrozenCircuit):
            raise ValueError(
                f'Constant at index {proto.circuit_constant_index} was expected to be a circuit, '
                f'but it has type {type(circuit)} in the deserialized_constants list.'
            )
        which_rep_spec = proto.repetition_specification.WhichOneof('repetition_value')
        if which_rep_spec == 'repetition_count':
            rep_ids = None
            repetitions = proto.repetition_specification.repetition_count
        elif which_rep_spec == 'repetition_ids':
            rep_ids = proto.repetition_specification.repetition_ids.ids
            repetitions = len(rep_ids)
        else:
            rep_ids = None
            repetitions = 1
        qubit_map = {
            v2.qubit_from_proto_id(entry.key.id): v2.qubit_from_proto_id(entry.value.id)
            for entry in proto.qubit_map.entries
        }
        measurement_key_map = {
            entry.key.string_key: entry.value.string_key
            for entry in proto.measurement_key_map.entries
        }
        arg_map = {
            arg_func_langs.arg_from_proto(entry.key): arg_func_langs.arg_from_proto(entry.value)
            for entry in proto.arg_map.entries
        }
        for arg in arg_map.keys():
            if not isinstance(arg, (str, sympy.Symbol)):
                raise ValueError(
                    'Invalid key parameter type in deserialized CircuitOperation. '
                    f'Expected str or sympy.Symbol, found {type(arg)}.'
                    f'\nFull arg: {arg}'
                )
        for arg in arg_map.values():
            if not isinstance(arg, (str, sympy.Symbol, float, int)):
                raise ValueError(
                    'Invalid value parameter type in deserialized CircuitOperation. '
                    f'Expected str, sympy.Symbol, or number; found {type(arg)}.'
                    f'\nFull arg: {arg}'
                )
        if proto.HasField('repeat_until'):
            repeat_until = arg_func_langs.condition_from_proto(proto.repeat_until)
        else:
            repeat_until = None
        circuit_op = cirq.CircuitOperation(
            circuit,
            repetitions,
            qubit_map,
            measurement_key_map,
            arg_map,
            rep_ids,
            use_repetition_ids=proto.use_repetition_ids,
            repeat_until=repeat_until,
        )
        if len(proto.conditioned_on):
            conditions = [
                arg_func_langs.condition_from_proto(condition) for condition in proto.conditioned_on
            ]
            return circuit_op.with_classical_controls(*conditions)
        return circuit_op

from __future__ import annotations
import abc
import numbers
from typing import Any
import numpy as np
import cirq
from cirq.circuits import circuit_operation
from cirq_google.api import v2
from cirq_google.serialization.arg_func_langs import arg_to_proto, condition_to_proto
class OpSerializer(abc.ABC):
    @abc.abstractmethod
    def to_proto(
        self,
        op,
        msg=None,
        *,
        constants: list[v2.program_pb2.Constant],
        raw_constants: dict[Any, int],
    ) -> v2.program_pb2.CircuitOperation | v2.program_pb2.Operation | None:
    @abc.abstractmethod
    def can_serialize_operation(self, op: cirq.Operation) -> bool:
class CircuitOpSerializer(OpSerializer):
    def can_serialize_operation(self, op: cirq.Operation):
        return isinstance(op.untagged, cirq.CircuitOperation)
    def to_proto(
        self,
        op: cirq.CircuitOperation,
        msg: v2.program_pb2.CircuitOperation | None = None,
        *,
        constants: list[v2.program_pb2.Constant],
        raw_constants: dict[Any, int],
    ) -> v2.program_pb2.CircuitOperation:
        if not isinstance(op, cirq.CircuitOperation):
            raise ValueError(f'Serializer expected CircuitOperation but got {type(op)}.')
        msg = msg or v2.program_pb2.CircuitOperation()
        try:
            msg.circuit_constant_index = raw_constants[op.circuit]
        except KeyError as err:
            raise ValueError(
                f'Encountered a circuit not in the constants table. Full error message:\n{err}'
            )
        if (
            op.repetition_ids is not None
            and op.repetition_ids != circuit_operation.default_repetition_ids(op.repetitions)
        ):
            for rep_id in op.repetition_ids:
                msg.repetition_specification.repetition_ids.ids.append(rep_id)
        elif isinstance(op.repetitions, (int, np.integer)):
            msg.repetition_specification.repetition_count = int(op.repetitions)
        else:
            raise ValueError(f'Cannot serialize repetitions of type {type(op.repetitions)}')
        for q1, q2 in op.qubit_map.items():
            entry = msg.qubit_map.entries.add()
            entry.key.id = v2.qubit_to_proto_id(q1)
            entry.value.id = v2.qubit_to_proto_id(q2)
        for mk1, mk2 in op.measurement_key_map.items():
            entry = msg.measurement_key_map.entries.add()
            entry.key.string_key = mk1
            entry.value.string_key = mk2
        for p1, p2 in op.param_resolver.param_dict.items():
            entry = msg.arg_map.entries.add()
            arg_to_proto(p1, out=entry.key)
            if isinstance(p2, numbers.Complex):
                if isinstance(p2, numbers.Real):
                    p2 = float(p2)
                else:
                    raise ValueError(f'Cannot serialize complex value {p2}')
            arg_to_proto(p2, out=entry.value)
        msg.use_repetition_ids = op.use_repetition_ids
        if op.repeat_until:
            condition_to_proto(op.repeat_until, out=msg.repeat_until)
        return msg

