def test_empty():
    assert chip_as_adjacency_list(_create_device([])) == {}
def test_single_qubit():
    q00 = cirq.GridQubit(0, 0)
    assert chip_as_adjacency_list(_create_device([q00])) == {q00: []}
def test_two_close_qubits():
    q00 = cirq.GridQubit(0, 0)
    q01 = cirq.GridQubit(0, 1)
