    if out is None:
        out = ndarrays_pb2.BitArray()
    if not isinstance(array.dtype, bool):  # Includes np.bool
        ok = np.logical_or(array == 0, array == 1)
        if not np.all(ok):
            not_ok = array[np.where(~ok)]
            raise ValueError(
                f"Cannot convert array to bitarray; values must be either 0 or 1. Got {not_ok}"
            )
    out.shape[:] = array.shape
    out.flat_bytes = np.packbits(array).tobytes()
    return out
def from_bitarray(msg: ndarrays_pb2.BitArray) -> np.ndarray:
    if not msg.shape:
        raise ValueError(f"Cannot convert unset/empty {type(msg)} message to a numpy array.")
    flat_bytes = np.frombuffer(msg.flat_bytes, dtype=np.uint8)
    tot_bits = functools.reduce(lambda x, y: x * y, msg.shape)
    flat_bits = np.unpackbits(flat_bytes, count=tot_bits)
    return np.reshape(flat_bits, msg.shape).view(np.bool_)

from __future__ import annotations
import re
import cirq
from cirq_google.ops.coupler import Coupler
GRID_QUBIT_ID_PATTERN = r'^q?(-?\d+)_(-?\d+)$'
def qubit_to_proto_id(q: cirq.Qid) -> str:
    if isinstance(q, cirq.GridQubit):
        return f'{q.row}_{q.col}'
    elif isinstance(q, cirq.NamedQubit):
        return q.name
    elif isinstance(q, cirq.LineQubit):
        return f'{q.x}'
    elif isinstance(q, Coupler):
        return f'c_{qubit_to_proto_id(q.qubit0)}_{qubit_to_proto_id(q.qubit1)}'
    else:
        raise ValueError(f'Qubits of type {type(q)} do not support proto id')
def qubit_from_proto_id(proto_id: str) -> cirq.Qid:
    qubit_field = proto_id.split('_')
    num_coords = len(qubit_field)
    if proto_id[:2] == 'c_':
        if num_coords == 5:
            grid_qubit0_str = qubit_field[1] + '_' + qubit_field[2]
            grid_qubit1_str = qubit_field[3] + '_' + qubit_field[4]
            try:
                grid_qubit0 = grid_qubit_from_proto_id(grid_qubit0_str)
                grid_qubit1 = grid_qubit_from_proto_id(grid_qubit1_str)
                return Coupler(grid_qubit0, grid_qubit1)
            except ValueError:
                pass  # Not valid grid qubits.
        elif num_coords == 3:
            line_qubit0 = qubit_from_proto_id(qubit_field[1])
            line_qubit1 = qubit_from_proto_id(qubit_field[2])
            return Coupler(line_qubit0, line_qubit1)
    elif num_coords == 2:
        try:
            grid_q = grid_qubit_from_proto_id(proto_id)
            return grid_q
        except ValueError:
            pass  # Not a grid qubit.
    elif num_coords == 1:
        try:
            line_q = line_qubit_from_proto_id(proto_id)
            return line_q
        except ValueError:
            pass  # Not a line qubit.
    named_q = named_qubit_from_proto_id(proto_id)
    return named_q
def grid_qubit_from_proto_id(proto_id: str) -> cirq.GridQubit:
    match = re.match(GRID_QUBIT_ID_PATTERN, proto_id)
    if match is None:
        raise ValueError(
            f'GridQubit proto id must be of the form [q]<int>_<int> but was {proto_id}'
        )
    row, col = match.groups()
    return cirq.GridQubit(row=int(row), col=int(col))
def line_qubit_from_proto_id(proto_id: str) -> cirq.LineQubit:
    try:
        return cirq.LineQubit(x=int(proto_id))
    except ValueError:
        raise ValueError(f'Line qubit proto id must be an int but was {proto_id}')
def named_qubit_from_proto_id(proto_id: str) -> cirq.NamedQubit:
    return cirq.NamedQubit(proto_id)

from __future__ import annotations
import dataclasses
from collections import OrderedDict
from collections.abc import Hashable, Iterable, Sequence
from typing import cast
import numpy as np
import cirq
from cirq_google.api import v2
from cirq_google.api.v2 import result_pb2
@dataclasses.dataclass
class MeasureInfo:
    key: str
    qubits: list[cirq.GridQubit]
    instances: int
    invert_mask: list[bool]
    tags: list[Hashable]
def find_measurements(program: cirq.AbstractCircuit) -> list[MeasureInfo]:
    if not isinstance(program, cirq.AbstractCircuit):
        raise NotImplementedError(f'Unrecognized program type: {type(program)}')
    measurements: dict[str, MeasureInfo] = {}
    for moment in program:
        for op in moment:
            if isinstance(op.gate, cirq.MeasurementGate):
                m = MeasureInfo(
                    key=op.gate.key,
                    qubits=_grid_qubits(op),
                    instances=1,
                    invert_mask=list(op.gate.full_invert_mask()),
                    tags=list(op.tags),
                )
                prev_m = measurements.get(m.key)
                if prev_m is None:
                    measurements[m.key] = m
                else:
                    if (
                        m.qubits != prev_m.qubits
                        or m.invert_mask != prev_m.invert_mask
                        or m.tags != prev_m.tags
                    ):
                        raise ValueError(f"Incompatible repeated keys: {m}, {prev_m}")
                    prev_m.instances += 1
    return list(measurements.values())
def _grid_qubits(op: cirq.Operation) -> list[cirq.GridQubit]:
    if not all(isinstance(q, cirq.GridQubit) for q in op.qubits):
        raise ValueError(f'Expected GridQubits: {op.qubits}')
    return cast(list[cirq.GridQubit], list(op.qubits))
def pack_bits(bits: np.ndarray) -> bytes:
    pad = -len(bits) % 8
    if pad:
        bits = np.pad(bits, (0, pad), 'constant')
    bits = bits.reshape((-1, 8))[:, ::-1]
    byte_arr = np.packbits(bits, axis=1).reshape(-1)
    return byte_arr.tobytes()
def unpack_bits(data: bytes, repetitions: int) -> np.ndarray:
    byte_arr = np.frombuffer(data, dtype='uint8').reshape((len(data), 1))
    bits = np.unpackbits(byte_arr, axis=1)[:, ::-1].reshape(-1).astype(bool)
    return bits[:repetitions]
def results_to_proto(
    trial_sweeps: Iterable[Iterable[cirq.Result]],
    measurements: list[MeasureInfo],
    *,
    out: result_pb2.Result | None = None,
) -> result_pb2.Result:
    if out is None:
        out = result_pb2.Result()
    for trial_sweep in trial_sweeps:
        sweep_result = out.sweep_results.add()
        for i, trial_result in enumerate(trial_sweep):
            if i == 0:
                sweep_result.repetitions = trial_result.repetitions
            elif trial_result.repetitions != sweep_result.repetitions:
                raise ValueError('Different numbers of repetitions in one sweep.')
            reps = sweep_result.repetitions
            pr = sweep_result.parameterized_results.add()
            pr.params.assignments.update(trial_result.params.param_dict)
            for m in measurements:
                mr = pr.measurement_results.add()
                mr.key = m.key
                mr.instances = m.instances
                m_data = trial_result.records[m.key]
                for i, qubit in enumerate(m.qubits):
                    qmr = mr.qubit_measurement_results.add()
                    qmr.qubit.id = v2.qubit_to_proto_id(qubit)
                    qmr.results = pack_bits(m_data[:, :, i].reshape(reps * m.instances))
    return out
def results_from_proto(
    msg: result_pb2.Result, measurements: list[MeasureInfo] | None = None
) -> Sequence[Sequence[cirq.Result]]:
    measure_map = {m.key: m for m in measurements} if measurements else None
    return [
        _trial_sweep_from_proto(sweep_result, measure_map) for sweep_result in msg.sweep_results
    ]
def _trial_sweep_from_proto(
    msg: result_pb2.SweepResult, measure_map: dict[str, MeasureInfo] | None = None
) -> Sequence[cirq.Result]:
    trial_sweep: list[cirq.Result] = []
    for pr in msg.parameterized_results:
        records: dict[str, np.ndarray] = {}
        for mr in pr.measurement_results:
            instances = max(mr.instances, 1)
            qubit_results: OrderedDict[cirq.GridQubit, np.ndarray] = OrderedDict()
            for qmr in mr.qubit_measurement_results:
                qubit = v2.grid_qubit_from_proto_id(qmr.qubit.id)
                if qubit in qubit_results:
                    raise ValueError(f'Qubit already exists: {qubit}.')
                qubit_results[qubit] = unpack_bits(qmr.results, msg.repetitions * instances)
            if measure_map:
                ordered_results = [qubit_results[qubit] for qubit in measure_map[mr.key].qubits]
            else:
                ordered_results = list(qubit_results.values())
            shape = (msg.repetitions, instances, len(qubit_results))
            records[mr.key] = np.array(ordered_results).transpose().reshape(shape)
        trial_sweep.append(
            cirq.ResultDict(params=cirq.ParamResolver(dict(pr.params.assignments)), records=records)
        )
    return trial_sweep

from __future__ import annotations
import functools
from collections.abc import Sequence
from cirq_google.api.v2 import program_pb2, run_context_pb2
_EMPTY_RESOURCE_PATH_IDX = -1
def to_device_parameters_diff(
    device_params: Sequence[
        tuple[
            run_context_pb2.DeviceParameter,
            program_pb2.ArgValue | run_context_pb2.DeviceParametersDiff.GenericValue,
        ]
    ],
) -> run_context_pb2.DeviceParametersDiff:
    diff = run_context_pb2.DeviceParametersDiff()
    @functools.lru_cache(maxsize=None)
    def token_id(s: str) -> int:
        idx = len(diff.strs)
        diff.strs.append(s)
        return idx
    resource_groups_index: dict[tuple[str, ...], int] = {tuple(): _EMPTY_RESOURCE_PATH_IDX}
    def resource_path_id(path: tuple[str, ...]) -> int:
        idx = resource_groups_index.get(path, None)
        if idx is not None:
            return idx
        parent_id = resource_path_id(path[:-1])
        idx = len(diff.groups)
        diff.groups.add(parent=parent_id, name=token_id(path[-1]))
        resource_groups_index[path] = idx
        return idx
    for device_param, value in device_params:
        resource_path = tuple(device_param.path[:-1])
        param_name = device_param.path[-1]
        path_id = resource_path_id(resource_path)
        val_kw = {}
        if isinstance(value, run_context_pb2.DeviceParametersDiff.GenericValue):
            val_kw["generic_value"] = value
        else:
            val_kw["value"] = value
        diff.params.add(name=token_id(param_name), resource_group=path_id, **val_kw)
    return diff

