class QasmUGate(ops.Gate):
    def __init__(self, theta: cirq.TParamVal, phi: cirq.TParamVal, lmda: cirq.TParamVal) -> None:
        self.theta = theta % 2
        self.phi = phi % 2
        self.lmda = lmda % 2
    def _num_qubits_(self) -> int:
        return 1
    @staticmethod
    def from_matrix(mat: np.ndarray) -> QasmUGate:
        pre_phase, rotation, post_phase = linalg.deconstruct_single_qubit_matrix_into_angles(mat)
        return QasmUGate(rotation / np.pi, post_phase / np.pi, pre_phase / np.pi)
    def _has_unitary_(self):
        return not self._is_parameterized_()
    def _is_parameterized_(self) -> bool:
        return (
            protocols.is_parameterized(self.theta)
            or protocols.is_parameterized(self.phi)
            or protocols.is_parameterized(self.lmda)
        )
    def _parameter_names_(self) -> Set[str]:
        return (
            protocols.parameter_names(self.theta)
            | protocols.parameter_names(self.phi)
            | protocols.parameter_names(self.lmda)
        )
    def _resolve_parameters_(self, resolver: cirq.ParamResolver, recursive: bool) -> QasmUGate:
        return QasmUGate(
            protocols.resolve_parameters(self.theta, resolver, recursive),
            protocols.resolve_parameters(self.phi, resolver, recursive),
            protocols.resolve_parameters(self.lmda, resolver, recursive),
        )
    def _qasm_(self, qubits: tuple[cirq.Qid, ...], args: cirq.QasmArgs) -> str:
        args.validate_version('2.0', '3.0')
        return args.format(
            'u3({0:half_turns},{1:half_turns},{2:half_turns}) {3};\n',
            self.theta,
            self.phi,
            self.lmda,
            qubits[0],
        )
    def __repr__(self) -> str:
        return (
            f'cirq.circuits.qasm_output.QasmUGate('
            f'theta={proper_repr(self.theta)}, '
            f'phi={proper_repr(self.phi)}, '
            f'lmda={proper_repr(self.lmda)})'
        )
    def _decompose_(self, qubits):
        def mul_pi(x):
            return x * (sympy.pi if protocols.is_parameterized(x) else np.pi)
        q = qubits[0]
        phase_correction_half_turns = (self.phi + self.lmda) / 2
        return [
            ops.rz(mul_pi(self.lmda)).on(q),
            ops.ry(mul_pi(self.theta)).on(q),
            ops.rz(mul_pi(self.phi)).on(q),
            ops.global_phase_operation(1j ** (2 * phase_correction_half_turns)),
        ]
    def _value_equality_values_(self):
        return self.lmda, self.theta, self.phi
    def _json_dict_(self) -> dict[str, float]:
        return {'theta': self.theta, 'phi': self.phi, 'lmda': self.lmda}
    @classmethod
    def _from_json_dict_(cls, theta: float, phi: float, lmda: float, **kwargs) -> QasmUGate:
        return cls(theta, phi, lmda)
@value.value_equality
class QasmTwoQubitGate(ops.Gate):
    def __init__(self, kak: cirq.KakDecomposition) -> None:
        self.kak = kak
    def _num_qubits_(self) -> int:
        return 2
    def _value_equality_values_(self):
        return self.kak
    @staticmethod
    def from_matrix(mat: np.ndarray, atol=1e-8) -> QasmTwoQubitGate:
        kak = linalg.kak_decomposition(mat, atol=atol)
        return QasmTwoQubitGate(kak)
    def _unitary_(self):
        return protocols.unitary(self.kak)
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        q0, q1 = qubits
        x, y, z = self.kak.interaction_coefficients
        a = x * -2 / np.pi + 0.5
        b = y * -2 / np.pi + 0.5
        c = z * -2 / np.pi + 0.5
        b0, b1 = self.kak.single_qubit_operations_before
        yield QasmUGate.from_matrix(b0).on(q0)
        yield QasmUGate.from_matrix(b1).on(q1)
        yield ops.X(q0) ** 0.5
        yield ops.CNOT(q0, q1)
        yield ops.X(q0) ** a
        yield ops.Y(q1) ** b
        yield ops.CNOT(q1, q0)
        yield ops.X(q1) ** -0.5
        yield ops.Z(q1) ** c
        yield ops.CNOT(q0, q1)
        a0, a1 = self.kak.single_qubit_operations_after
        yield QasmUGate.from_matrix(a0).on(q0)
        yield QasmUGate.from_matrix(a1).on(q1)
    def __repr__(self) -> str:
        return f'cirq.circuits.qasm_output.QasmTwoQubitGate({self.kak!r})'
class QasmOutput:
    valid_id_re = re.compile(r'[a-z][a-zA-Z0-9_]*\Z')
    def __init__(
        self,
        operations: cirq.OP_TREE,
        qubits: tuple[cirq.Qid, ...],
        header: str = '',
        precision: int = 10,
        version: str = '2.0',
    ) -> None:
        self.operations = tuple(ops.flatten_to_ops(operations))
        self.qubits = qubits
        self.header = header
        self.measurements = tuple(
            op for op in self.operations if isinstance(op.gate, ops.MeasurementGate)
        )
        meas_key_id_map, meas_comments = self._generate_measurement_ids()
        self.meas_comments = meas_comments
        qubit_id_map = self._generate_qubit_ids()
        self.cregs = self._generate_cregs(meas_key_id_map)
        self.args = protocols.QasmArgs(
            precision=precision,
            version=version,
            qubit_id_map=qubit_id_map,
            meas_key_id_map=meas_key_id_map,
            meas_key_bitcount={k: v[0] for k, v in self.cregs.items()},
        )
    def _generate_measurement_ids(self) -> tuple[dict[str, str], dict[str, str | None]]:
        meas_key_id_map: dict[str, str] = {}
        meas_comments: dict[str, str | None] = {}
        meas_i = 0
        for meas in self.measurements:
            key = protocols.measurement_key_name(meas)
            if key in meas_key_id_map:
                continue
            meas_id = f'm_{key}'
            if self.is_valid_qasm_id(meas_id):
                meas_comments[key] = None
            else:
                meas_id = f'm{meas_i}'
                meas_i += 1
                meas_comments[key] = ' '.join(key.split('\n'))
            meas_key_id_map[key] = meas_id
        return meas_key_id_map, meas_comments
    def _generate_qubit_ids(self) -> dict[cirq.Qid, str]:
        return {qubit: f'q[{i}]' for i, qubit in enumerate(self.qubits)}
    def _generate_cregs(self, meas_key_id_map: dict[str, str]) -> dict[str, tuple[int, str]]:
        cregs: dict[str, tuple[int, str]] = {}
        for meas in self.measurements:
            key = protocols.measurement_key_name(meas)
            meas_id = meas_key_id_map[key]
            if self.meas_comments[key] is not None:
                comment = f'  // Measurement: {self.meas_comments[key]}'
            else:
                comment = ''
            if meas_id not in cregs or cregs[meas_id][0] < len(meas.qubits):
                cregs[meas_id] = (len(meas.qubits), comment)
        return cregs
    def is_valid_qasm_id(self, id_str: str) -> bool:
        return self.valid_id_re.match(id_str) is not None
    def save(self, path: str | bytes | int) -> None:
        with open(path, 'w') as f:
            def write(s: str) -> None:
                f.write(s)
            self._write_qasm(write)
    def __str__(self) -> str:
        output = []
        self._write_qasm(lambda s: output.append(s))
        return ''.join(output)
    def _write_qasm(self, output_func: Callable[[str], None]) -> None:
        self.args.validate_version('2.0', '3.0')
        line_gap = [0]
        def output_line_gap(n):
            line_gap[0] = max(line_gap[0], n)
        def output(text):
            if line_gap[0] > 0:
                output_func('\n' * line_gap[0])
                line_gap[0] = 0
            output_func(text)
        if self.header:
            for line in self.header.split('\n'):
                output(('// ' + line).rstrip() + '\n')
            output('\n')
        output(f'OPENQASM {self.args.version};\n')
        if self.args.version == '2.0':
            output('include "qelib1.inc";\n')
        else:
            output('include "stdgates.inc";\n')
        output_line_gap(2)
        output(f"// Qubits: [{', '.join(map(str, self.qubits))}]\n")
        if len(self.qubits) > 0:
            if self.args.version == '2.0':
                output(f'qreg q[{len(self.qubits)}];\n')
            else:
                output(f'qubit[{len(self.qubits)}] q;\n')
        for meas_id in self.cregs:
            length, comment = self.cregs[meas_id]
            if self.args.version == '2.0':
                output(f'creg {meas_id}[{length}];{comment}\n')
            else:
                output(f'bit[{length}] {meas_id};{comment}\n')
        if any(not isinstance(op.gate, ops.GlobalPhaseGate) for op in self.operations):
            output_line_gap(2)
        self._write_operations(self.operations, output, output_line_gap)
    def _write_operations(
        self,
        op_tree: cirq.OP_TREE,
        output: Callable[[str], None],
        output_line_gap: Callable[[int], None],
    ) -> None:
        def keep(op: cirq.Operation) -> bool:
            return protocols.qasm(op, args=self.args, default=None) is not None
        def fallback(op):
            if len(op.qubits) not in [1, 2]:
                return NotImplemented
            mat = protocols.unitary(op, None)
            if mat is None:
                return NotImplemented
            if len(op.qubits) == 1:
                return QasmUGate.from_matrix(mat).on(*op.qubits)  # pragma: no cover
            return QasmTwoQubitGate.from_matrix(mat).on(*op.qubits)
        def on_stuck(bad_op):
            return ValueError(f'Cannot output operation as QASM: {bad_op!r}')
        for main_op in ops.flatten_op_tree(op_tree):
            decomposed = protocols.decompose(
                main_op, keep=keep, fallback_decomposer=fallback, on_stuck_raise=on_stuck
            )
            qasms = [protocols.qasm(op, args=self.args) for op in decomposed]
            should_annotate = decomposed != [main_op] or qasms[0].count('\n') > 1
            if should_annotate:
                output_line_gap(1)
                if isinstance(main_op, ops.GateOperation):
                    x = str(main_op.gate).replace('\n', '\n//       ')
                    output(f'// Gate: {x!s}\n')
                else:
                    x = str(main_op).replace('\n', '\n//            ')
                    output(f'// Operation: {x!s}\n')
            for qasm in qasms:
                output(qasm)
            if should_annotate:
                output_line_gap(1)

from __future__ import annotations
from collections.abc import Callable, Iterable, Mapping, Sequence
from typing import Any, cast, NamedTuple, Self, TYPE_CHECKING
import numpy as np
from cirq import value
from cirq.circuits._block_diagram_drawer import BlockDiagramDrawer
from cirq.circuits._box_drawing_character_data import (
    ASCII_BOX_CHARS,
    BOLD_BOX_CHARS,
    BoxDrawCharacterSet,
    DOUBLED_BOX_CHARS,
    NORMAL_BOX_CHARS,
)
if TYPE_CHECKING:
    import cirq
_HorizontalLine = NamedTuple(
    '_HorizontalLine',
    [('y', float), ('x1', float), ('x2', float), ('emphasize', bool), ('doubled', bool)],
)
_VerticalLine = NamedTuple(
    '_VerticalLine',
    [('x', float), ('y1', float), ('y2', float), ('emphasize', bool), ('doubled', bool)],
)
_DiagramText = NamedTuple('_DiagramText', [('text', str), ('transposed_text', str)])
def pick_charset(use_unicode: bool, emphasize: bool, doubled: bool) -> BoxDrawCharacterSet:
    if not use_unicode:
        return ASCII_BOX_CHARS
    if emphasize and doubled:
        raise ValueError('Cannot use both emphasized and doubled.')
    if emphasize:
        return BOLD_BOX_CHARS
    if doubled:
        return DOUBLED_BOX_CHARS
    return NORMAL_BOX_CHARS
@value.value_equality(unhashable=True)
class TextDiagramDrawer:
    def __init__(
        self,
        entries: Mapping[tuple[int, int], _DiagramText] | None = None,
        horizontal_lines: Iterable[_HorizontalLine] | None = None,
        vertical_lines: Iterable[_VerticalLine] | None = None,
        horizontal_padding: Mapping[int, float] | None = None,
        vertical_padding: Mapping[int, float] | None = None,
    ) -> None:
        self.entries: dict[tuple[int, int], _DiagramText] = (
            dict() if entries is None else dict(entries)
        )
        self.horizontal_lines: list[_HorizontalLine] = (
            [] if horizontal_lines is None else list(horizontal_lines)
        )
        self.vertical_lines: list[_VerticalLine] = (
            [] if vertical_lines is None else list(vertical_lines)
        )
        self.horizontal_padding: dict[int, float] = (
            dict() if horizontal_padding is None else dict(horizontal_padding)
        )
        self.vertical_padding: dict[int, float] = (
            dict() if vertical_padding is None else dict(vertical_padding)
        )
    def _value_equality_values_(self):
        attrs = (
            'entries',
            'horizontal_lines',
            'vertical_lines',
            'horizontal_padding',
            'vertical_padding',
        )
        return tuple(getattr(self, attr) for attr in attrs)
    def __bool__(self):
        return any(self._value_equality_values_())
    def write(self, x: int, y: int, text: str, transposed_text: str | None = None) -> None:
        entry = self.entries.get((x, y), _DiagramText('', ''))
        self.entries[(x, y)] = _DiagramText(
            entry.text + text,
            entry.transposed_text + (transposed_text if transposed_text else text),
        )
    def content_present(self, x: int, y: int) -> bool:
        if (x, y) in self.entries:
            return True
        if any(v.x == x and v.y1 < y < v.y2 for v in self.vertical_lines):
            return True
        if any(line_y == y and x1 < x < x2 for line_y, x1, x2, _, _ in self.horizontal_lines):
            return True  # pragma: no cover
        return False
    def grid_line(
        self, x1: int, y1: int, x2: int, y2: int, emphasize: bool = False, doubled: bool = False
    ) -> None:
        if x1 == x2:
            self.vertical_line(x1, y1, y2, emphasize, doubled)
        elif y1 == y2:
            self.horizontal_line(y1, x1, x2, emphasize, doubled)
        else:
            raise ValueError("Line is neither horizontal nor vertical")
    def vertical_line(
        self, x: float, y1: float, y2: float, emphasize: bool = False, doubled: bool = False
    ) -> None:
        y1, y2 = sorted([y1, y2])
        self.vertical_lines.append(_VerticalLine(x, y1, y2, emphasize, doubled))
    def horizontal_line(
        self, y: float, x1: float, x2: float, emphasize: bool = False, doubled: bool = False
    ) -> None:
        x1, x2 = sorted([x1, x2])
        self.horizontal_lines.append(_HorizontalLine(y, x1, x2, emphasize, doubled))
    def transpose(self) -> cirq.TextDiagramDrawer:
        out = TextDiagramDrawer()
        out.entries = {
            (y, x): _DiagramText(v.transposed_text, v.text) for (x, y), v in self.entries.items()
        }
        out.vertical_lines = [_VerticalLine(*e) for e in self.horizontal_lines]
        out.horizontal_lines = [_HorizontalLine(*e) for e in self.vertical_lines]
        out.vertical_padding = self.horizontal_padding.copy()
        out.horizontal_padding = self.vertical_padding.copy()
        return out
    def width(self) -> int:
        max_x = -1.0
        for x, _ in self.entries.keys():
            max_x = max(max_x, x)
        for v in self.vertical_lines:
            max_x = max(max_x, v.x)
        for h in self.horizontal_lines:
            max_x = max(max_x, h.x1, h.x2)
        return 1 + int(max_x)
    def height(self) -> int:
        max_y = -1.0
        for _, y in self.entries.keys():
            max_y = max(max_y, y)
        for h in self.horizontal_lines:
            max_y = max(max_y, h.y)
        for v in self.vertical_lines:
            max_y = max(max_y, v.y1, v.y2)
        return 1 + int(max_y)
    def force_horizontal_padding_after(self, index: int, padding: float) -> None:
        self.horizontal_padding[index] = padding
    def force_vertical_padding_after(self, index: int, padding: float) -> None:
        self.vertical_padding[index] = padding
    def _transform_coordinates(self, func: Callable[[float, float], tuple[float, float]]) -> None:
        def func_x(x: float) -> float:
            return func(x, 0)[0]
        def func_y(y: float) -> float:
            return func(0, y)[1]
        self.entries = {
            cast(tuple[int, int], func(int(x), int(y))): v for (x, y), v in self.entries.items()
        }
        self.vertical_lines = [
            _VerticalLine(func_x(x), func_y(y1), func_y(y2), emph, doubled)
            for x, y1, y2, emph, doubled in self.vertical_lines
        ]
        self.horizontal_lines = [
            _HorizontalLine(func_y(y), func_x(x1), func_x(x2), emph, doubled)
            for y, x1, x2, emph, doubled in self.horizontal_lines
        ]
        self.horizontal_padding = {
            int(func_x(int(x))): padding for x, padding in self.horizontal_padding.items()
        }
        self.vertical_padding = {
            int(func_y(int(y))): padding for y, padding in self.vertical_padding.items()
        }
    def insert_empty_columns(self, x: int, amount: int = 1) -> None:
        def transform_columns(column: float, row: float) -> tuple[float, float]:
            return column + (amount if column >= x else 0), row
        self._transform_coordinates(transform_columns)
    def insert_empty_rows(self, y: int, amount: int = 1) -> None:
        def transform_rows(column: float, row: float) -> tuple[float, float]:
            return column, row + (amount if row >= y else 0)
        self._transform_coordinates(transform_rows)
    def render(
        self,
        horizontal_spacing: int = 1,
        vertical_spacing: int = 1,
        crossing_char: str | None = None,
        use_unicode_characters: bool = True,
    ) -> str:
        block_diagram = BlockDiagramDrawer()
        w = self.width()
        h = self.height()
        for x in range(w - 1):
            block_diagram.set_col_min_width(
                x * 2 + 1,
                int(np.ceil(self.horizontal_padding.get(x, horizontal_spacing))),
            )
            block_diagram.set_col_min_width(x * 2, 1)
        for y in range(h - 1):
            block_diagram.set_row_min_height(
                y * 2 + 1,
                int(np.floor(self.vertical_padding.get(y, vertical_spacing))),
            )
            block_diagram.set_row_min_height(y * 2, 1)
        for x_b, y1_b, y2_b, emphasize, doubled in self.vertical_lines:
            x = int(x_b * 2)
            y1, y2 = int(min(y1_b, y2_b) * 2), int(max(y1_b, y2_b) * 2)
            charset = pick_charset(use_unicode_characters, emphasize, doubled)
            block_diagram.mutable_block(x, y1).draw_curve(charset, bottom=True)
            block_diagram.mutable_block(x, y2).draw_curve(charset, top=True)
            for y in range(y1 + 1, y2):
                block_diagram.mutable_block(x, y).draw_curve(charset, top=True, bottom=True)
        for y_b, x1_b, x2_b, emphasize, doubled in self.horizontal_lines:
            y = int(y_b * 2)
            x1, x2 = int(min(x1_b, x2_b) * 2), int(max(x1_b, x2_b) * 2)
            charset = pick_charset(use_unicode_characters, emphasize, doubled)
            block_diagram.mutable_block(x1, y).draw_curve(charset, right=True)
            block_diagram.mutable_block(x2, y).draw_curve(charset, left=True)
            for x in range(x1 + 1, x2):
                block_diagram.mutable_block(x, y).draw_curve(
                    charset, left=True, right=True, crossing_char=crossing_char
                )
        for (x, y), v in self.entries.items():
            x *= 2
            y *= 2
            block_diagram.mutable_block(x, y).content = v.text
        return block_diagram.render()
    def copy(self) -> Self:
        return self.__class__(
            entries=self.entries,
            vertical_lines=self.vertical_lines,
            horizontal_lines=self.horizontal_lines,
            vertical_padding=self.vertical_padding,
            horizontal_padding=self.horizontal_padding,
        )
    def shift(self, dx: int = 0, dy: int = 0) -> cirq.TextDiagramDrawer:
        self._transform_coordinates(lambda x, y: (x + dx, y + dy))
        return self
    def shifted(self, dx: int = 0, dy: int = 0) -> cirq.TextDiagramDrawer:
        return self.copy().shift(dx, dy)
    def superimpose(self, other: cirq.TextDiagramDrawer) -> cirq.TextDiagramDrawer:
        self.entries.update(other.entries)
        self.horizontal_lines += other.horizontal_lines
        self.vertical_lines += other.vertical_lines
        self.horizontal_padding.update(other.horizontal_padding)
        self.vertical_padding.update(other.vertical_padding)
        return self
    def superimposed(self, other: cirq.TextDiagramDrawer) -> cirq.TextDiagramDrawer:
        return self.copy().superimpose(other)
    @classmethod
    def vstack(
        cls,
        diagrams: Sequence[cirq.TextDiagramDrawer],
        padding_resolver: Callable[[Sequence[int | None]], int] | None = None,
    ):
        if padding_resolver is None:
            padding_resolver = _same_element_or_throw_error
        stacked = cls()
        dy = 0
        for diagram in diagrams:
            stacked.superimpose(diagram.shifted(dy=dy))
            dy += diagram.height()
        for x in stacked.horizontal_padding:
            resolved_padding = padding_resolver(
                tuple(cast(int | None, diagram.horizontal_padding.get(x)) for diagram in diagrams)
            )
            if resolved_padding is not None:
                stacked.horizontal_padding[x] = resolved_padding
        return stacked
    @classmethod
    def hstack(
        cls,
        diagrams: Sequence[cirq.TextDiagramDrawer],
        padding_resolver: Callable[[Sequence[int | None]], int] | None = None,
    ):
        if padding_resolver is None:
            padding_resolver = _same_element_or_throw_error
        stacked = cls()
        dx = 0
        for diagram in diagrams:
            stacked.superimpose(diagram.shifted(dx=dx))
            dx += diagram.width()
        for y in stacked.vertical_padding:
            resolved_padding = padding_resolver(
                tuple(cast(int | None, diagram.vertical_padding.get(y)) for diagram in diagrams)
            )
            if resolved_padding is not None:
                stacked.vertical_padding[y] = resolved_padding
        return stacked
def _same_element_or_throw_error(elements: Sequence[Any]):
    unique_elements = set(elements)
    if len(unique_elements) > 1:
        raise ValueError(f'len(set({elements})) > 1')
    return unique_elements.pop() if elements else None

from __future__ import annotations
import collections
from cirq.circuits._box_drawing_character_data import box_draw_character, BoxDrawCharacterSet
class Block:
    def __init__(self):
        self.left = ''
        self.right = ''
        self.top = ''
        self.bottom = ''
        self.center = ''
        self.content = ''
        self.horizontal_alignment = 0
        self._prev_curve_grid_chars = None
    def min_width(self) -> int:
        return max(
            max(len(e) for e in self.content.split('\n')),
            int(any([self.top, self.bottom])),
        )
    def min_height(self) -> int:
        return max(
            len(self.content.split('\n')) if self.content else 0,
            int(any([self.left, self.right])),
        )
    def draw_curve(
        self,
        grid_characters: BoxDrawCharacterSet,
        *,
        top: bool = False,
        left: bool = False,
        right: bool = False,
        bottom: bool = False,
        crossing_char: str | None = None,
    ):
        if not any([top, left, right, bottom]):
            return
        sign_top = +1 if top else -1 if self.top else 0
        sign_bottom = +1 if bottom else -1 if self.bottom else 0
        sign_left = +1 if left else -1 if self.left else 0
        sign_right = +1 if right else -1 if self.right else 0
        if top:
            self.top = grid_characters.top_bottom
        if bottom:
            self.bottom = grid_characters.top_bottom
        if left:
            self.left = grid_characters.left_right
        if right:
            self.right = grid_characters.left_right
        if not all([crossing_char, self.top, self.bottom, self.left, self.right]):
            crossing_char = box_draw_character(
                self._prev_curve_grid_chars,
                grid_characters,
                top=sign_top,
                bottom=sign_bottom,
                left=sign_left,
                right=sign_right,
            )
        self.center = crossing_char or ''
        self._prev_curve_grid_chars = grid_characters
    def render(self, width: int, height: int) -> list[str]:
        if width == 0 or height == 0:
            return [''] * height
        out_chars = [[' '] * width for _ in range(height)]
        mid_x = int((width - 1) * self.horizontal_alignment)
        mid_y = (height - 1) // 2
        if self.left:
            out_chars[mid_y][: mid_x + 1] = self.left * (mid_x + 1)
        if self.right:
            out_chars[mid_y][mid_x:] = self.right * (width - mid_x)
        if self.top:
            for y in range(mid_y + 1):
                out_chars[y][mid_x] = self.top
        if self.bottom:
            for y in range(mid_y, height):
                out_chars[y][mid_x] = self.bottom
        mid = self.content or self.center
        if self.content or self.center:
            content_lines = mid.split('\n')
            y = mid_y - (len(content_lines) - 1) // 2
            for dy, content_line in enumerate(content_lines):
                s = int((len(content_line) - 1) * self.horizontal_alignment)
                x = mid_x - s
                for dx, c in enumerate(content_line):
                    out_chars[y + dy][x + dx] = c
        return [''.join(line) for line in out_chars]
class BlockDiagramDrawer:
    def __init__(self) -> None:
        self._blocks: dict[tuple[int, int], Block] = collections.defaultdict(Block)
        self._min_widths: dict[int, int] = collections.defaultdict(lambda: 0)
        self._min_heights: dict[int, int] = collections.defaultdict(lambda: 0)
        _ = self._blocks[(0, 0)]
        _ = self._min_widths[0]
        _ = self._min_heights[0]
    def mutable_block(self, x: int, y: int) -> Block:
        if x < 0 or y < 0:
            raise IndexError('x < 0 or y < 0')
        return self._blocks[(x, y)]
    def set_col_min_width(self, x: int, min_width: int):
        if x < 0:
            raise IndexError('x < 0')
        self._min_widths[x] = min_width
    def set_row_min_height(self, y: int, min_height: int):
        if y < 0:
            raise IndexError('y < 0')
        self._min_heights[y] = min_height
    def render(
        self,
        *,
        block_span_x: int | None = None,
        block_span_y: int | None = None,
        min_block_width: int = 0,
        min_block_height: int = 0,
    ) -> str:
        if block_span_x is None:
            block_span_x = 1 + max(
                max(x for x, _ in self._blocks.keys()), max(self._min_widths.keys())
            )
        if block_span_y is None:
            block_span_y = 1 + max(
                max(y for _, y in self._blocks.keys()), max(self._min_heights.keys())
            )
        empty = Block()
        def block(x: int, y: int) -> Block:
            return self._blocks.get((x, y), empty)
        widths = {
            x: max(
                max(block(x, y).min_width() for y in range(block_span_y)),
                self._min_widths.get(x, 0),
                min_block_width,
            )
            for x in range(block_span_x)
        }
        heights = {
            y: max(
                max(block(x, y).min_height() for x in range(block_span_x)),
                self._min_heights.get(y, 0),
                min_block_height,
            )
            for y in range(block_span_y)
        }
        block_renders = {
            (x, y): block(x, y).render(widths[x], heights[y])
            for x in range(block_span_x)
            for y in range(block_span_y)
        }
        out_lines: list[str] = []
        for y in range(block_span_y):
            for by in range(heights[y]):
                out_line_chunks: list[str] = []
                for x in range(block_span_x):
                    out_line_chunks.extend(block_renders[x, y][by])
                out_lines.append(''.join(out_line_chunks).rstrip())
        return '\n'.join(out_lines)

from __future__ import annotations
import abc
from collections.abc import Iterable
from typing import TYPE_CHECKING
import networkx as nx
from cirq import value
if TYPE_CHECKING:
    import cirq
class Device(metaclass=abc.ABCMeta):
    @property
    def metadata(self) -> DeviceMetadata | None:
        return None
    def validate_operation(self, operation: cirq.Operation) -> None:
    def validate_circuit(self, circuit: cirq.AbstractCircuit) -> None:
        for moment in circuit:
            self.validate_moment(moment)
    def validate_moment(self, moment: cirq.Moment) -> None:
        for operation in moment.operations:
            self.validate_operation(operation)
@value.value_equality
class DeviceMetadata:
    def __init__(self, qubits: Iterable[cirq.Qid], nx_graph: nx.Graph):
        self._qubits_set: frozenset[cirq.Qid] = frozenset(qubits)
        self._nx_graph = nx_graph
    @property
    def qubit_set(self) -> frozenset[cirq.Qid]:
        return self._qubits_set
    @property
    def nx_graph(self) -> nx.Graph:
        return self._nx_graph
    def _value_equality_values_(self):
        graph_equality = (
            tuple(sorted(self._nx_graph.nodes())),
            tuple(sorted(self._nx_graph.edges(data='directed'))),
        )
        return self._qubits_set, graph_equality
    def _json_dict_(self):
        graph_payload = nx.readwrite.json_graph.node_link_data(self._nx_graph, edges='links')
        qubits_payload = sorted(list(self._qubits_set))
        return {'qubits': qubits_payload, 'nx_graph': graph_payload}
    @classmethod
    def _from_json_dict_(cls, qubits: Iterable[cirq.Qid], nx_graph: nx.Graph, **kwargs):
        graph_obj = nx.readwrite.json_graph.node_link_graph(nx_graph, edges='links')
        return cls(qubits, graph_obj)

from __future__ import annotations
from collections.abc import Iterable, Mapping
from typing import cast, TYPE_CHECKING
import networkx as nx
from cirq import value
from cirq.devices import device
if TYPE_CHECKING:
    import cirq
@value.value_equality
class GridDeviceMetadata(device.DeviceMetadata):
    def __init__(
        self,
        qubit_pairs: Iterable[tuple[cirq.GridQubit, cirq.GridQubit]],
        gateset: cirq.Gateset,
        gate_durations: Mapping[cirq.GateFamily, cirq.Duration] | None = None,
        all_qubits: Iterable[cirq.GridQubit] | None = None,
        compilation_target_gatesets: Iterable[cirq.CompilationTargetGateset] = (),
    ):
        sorted_pairs = sorted(list(qubit_pairs))
        for a, b in sorted_pairs:
            if a == b:
                raise ValueError(f"Self loop encountered in qubit {a}")
        edge_set = set()
        node_set = set()
        for a, b in sorted_pairs:
            node_set.add(a)
            node_set.add(b)
            if (b, a) not in edge_set:
                edge_set.add((a, b))
        if all_qubits is None:
            all_qubits = node_set
        all_qubits = frozenset(all_qubits)
        for q in node_set:
            if q not in all_qubits:
                raise ValueError(
                    f"Qubit {q} found in node_set and not in"
                    " all_qubits. all_qubits must contain at least"
                    " all the qubits found in all_qubits."
                )
        connectivity = nx.Graph()
        connectivity.add_nodes_from(sorted(all_qubits))
        connectivity.add_edges_from(sorted(edge_set), directed=False)
        super().__init__(all_qubits, connectivity)
        self._qubit_pairs = frozenset({frozenset(pair) for pair in edge_set})
        self._gateset = gateset
        self._isolated_qubits = all_qubits.difference(node_set)
        self._compilation_target_gatesets = tuple(compilation_target_gatesets)
        if gate_durations is not None:
            working_gatefamilies = frozenset(gate_durations.keys())
            if not working_gatefamilies.issubset(gateset.gates):
                raise ValueError(
                    "Some gate_durations keys are not found in gateset."
                    f" gate_durations={gate_durations}"
                    f" gateset.gates={gateset.gates}"
                )
        self._gate_durations = gate_durations
    @property
    def qubit_set(self) -> frozenset[cirq.GridQubit]:
        return cast(frozenset['cirq.GridQubit'], super().qubit_set)
    @property
