    graph: nx.Graph, ax: plt.Axes | None = None, tilted: bool = True, **kwargs
) -> dict[_GRIDLIKE_NODE, tuple[int, int]]:
    if ax is None:
        ax = plt.gca()  # pragma: no cover
    if tilted:
        pos = {node: (y, -x) for node, (x, y) in _node_and_coordinates(graph.nodes)}
    else:
        pos = {node: (x + y, y - x) for node, (x, y) in _node_and_coordinates(graph.nodes)}
