from cirq._import import LazyLoader
moment_module = LazyLoader("moment_module", globals(), "cirq.circuits.moment")
if TYPE_CHECKING:
    import cirq
class NoiseModel(metaclass=value.ABCMetaImplementAnyOneOf):
    @classmethod
    def from_noise_model_like(cls, noise: cirq.NOISE_MODEL_LIKE) -> cirq.NoiseModel:
        if noise is None:
            return NO_NOISE
        if isinstance(noise, NoiseModel):
            return noise
        if isinstance(noise, ops.Gate):
            if noise.num_qubits() != 1:
                raise ValueError(
                    'Multi-qubit gates cannot be implicitly wrapped into a '
                    'noise model. Please use a single qubit gate (which will '
                    'be wrapped with `cirq.ConstantQubitNoiseModel`) or '
                    'an instance of `cirq.NoiseModel`.'
                )
            return ConstantQubitNoiseModel(noise)
        raise TypeError(
            'Expected a NOISE_MODEL_LIKE (None, a cirq.NoiseModel, '
            f'or a single qubit gate). Got {noise!r}'
        )
    def is_virtual_moment(self, moment: cirq.Moment) -> bool:
        if not moment.operations:
            return False
        return all(ops.VirtualTag() in op.tags for op in moment)
    def _noisy_moments_impl_moment(
        self, moments: Iterable[cirq.Moment], system_qubits: Sequence[cirq.Qid]
    ) -> Sequence[cirq.OP_TREE]:
        result = []
        for moment in moments:
            result.append(self.noisy_moment(moment, system_qubits))
        return result
    def _noisy_moments_impl_operation(
        self, moments: Iterable[cirq.Moment], system_qubits: Sequence[cirq.Qid]
    ) -> Sequence[cirq.OP_TREE]:
        result = []
        for moment in moments:
            result.append([self.noisy_operation(op) for op in moment])
        return result
    @value.alternative(requires='noisy_moment', implementation=_noisy_moments_impl_moment)
    @value.alternative(requires='noisy_operation', implementation=_noisy_moments_impl_operation)
    def noisy_moments(
        self, moments: Iterable[cirq.Moment], system_qubits: Sequence[cirq.Qid]
    ) -> Sequence[cirq.OP_TREE]:
        raise NotImplementedError
    def _noisy_moment_impl_moments(
        self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]
    ) -> cirq.OP_TREE:
        return self.noisy_moments([moment], system_qubits)
    def _noisy_moment_impl_operation(
        self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]
    ) -> cirq.OP_TREE:
        return [self.noisy_operation(op) for op in moment]
    @value.alternative(requires='noisy_moments', implementation=_noisy_moment_impl_moments)
    @value.alternative(requires='noisy_operation', implementation=_noisy_moment_impl_operation)
    def noisy_moment(self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        raise NotImplementedError
    def _noisy_operation_impl_moments(self, operation: cirq.Operation) -> cirq.OP_TREE:
        return self.noisy_moments([moment_module.Moment([operation])], operation.qubits)
    def _noisy_operation_impl_moment(self, operation: cirq.Operation) -> cirq.OP_TREE:
        return self.noisy_moment(moment_module.Moment([operation]), operation.qubits)
    @value.alternative(requires='noisy_moments', implementation=_noisy_operation_impl_moments)
    @value.alternative(requires='noisy_moment', implementation=_noisy_operation_impl_moment)
    def noisy_operation(self, operation: cirq.Operation) -> cirq.OP_TREE:
        raise NotImplementedError
@value.value_equality
class _NoNoiseModel(NoiseModel):
    def noisy_moments(self, moments: Iterable[cirq.Moment], system_qubits: Sequence[cirq.Qid]):
        return list(moments)
    def noisy_moment(self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]) -> cirq.Moment:
        return moment
    def noisy_operation(self, operation: cirq.Operation) -> cirq.Operation:
        return operation
    def _value_equality_values_(self) -> Any:
        return None
    def __str__(self) -> str:
        return '(no noise)'
    def __repr__(self) -> str:
        return 'cirq.NO_NOISE'
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, [])
    def _has_unitary_(self) -> bool:
        return True
    def _has_mixture_(self) -> bool:
        return True
@value.value_equality
class ConstantQubitNoiseModel(NoiseModel):
    def __init__(self, qubit_noise_gate: cirq.Gate, prepend: bool = False):
        if qubit_noise_gate.num_qubits() != 1:
            raise ValueError('noise.num_qubits() != 1')
        self.qubit_noise_gate = qubit_noise_gate
        self._prepend = prepend
    def _value_equality_values_(self) -> Any:
        return self.qubit_noise_gate
    def __repr__(self) -> str:
        return f'cirq.ConstantQubitNoiseModel({self.qubit_noise_gate!r})'
    def noisy_moment(self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        if self.is_virtual_moment(moment):
            return moment
        output = [
            moment,
            moment_module.Moment(
                [self.qubit_noise_gate(q).with_tags(ops.VirtualTag()) for q in system_qubits]
            ),
        ]
        return output[::-1] if self._prepend else output
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, ['qubit_noise_gate'])
    def _has_unitary_(self) -> bool:
        return protocols.has_unitary(self.qubit_noise_gate)
    def _has_mixture_(self) -> bool:
        return protocols.has_mixture(self.qubit_noise_gate)
class GateSubstitutionNoiseModel(NoiseModel):
    def __init__(self, substitution_func: Callable[[cirq.Operation], cirq.Operation]):
        self.substitution_func = substitution_func
    def noisy_moment(self, moment: cirq.Moment, system_qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        return moment_module.Moment([self.substitution_func(op) for op in moment.operations])
NO_NOISE: cirq.NoiseModel = _NoNoiseModel()
document(
    NO_NOISE,
    ,
)
NOISE_MODEL_LIKE = Union[None, 'cirq.NoiseModel', 'cirq.Gate']
document(
    NOISE_MODEL_LIKE,
    ,
)
def validate_all_measurements(moment: cirq.Moment) -> bool:
    cases = {protocols.is_measurement(gate) for gate in moment}
    if len(cases) == 2:
        raise ValueError("Moment must be homogeneous: all measurements or all operations.")
    return True in cases

from __future__ import annotations
import abc
from collections.abc import Iterable, Sequence
from typing import TYPE_CHECKING
from cirq import _import, devices, ops, protocols, value
from cirq.devices.noise_utils import PHYSICAL_GATE_TAG
circuits = _import.LazyLoader("circuits", globals(), "cirq.circuits.circuit")
if TYPE_CHECKING:
    import cirq
class NoiseProperties(abc.ABC):
    @abc.abstractmethod
    def build_noise_models(self) -> list[cirq.NoiseModel]:
@value.value_equality
class NoiseModelFromNoiseProperties(devices.NoiseModel):
    def __init__(self, noise_properties: NoiseProperties) -> None:
        self._noise_properties = noise_properties
        self.noise_models = self._noise_properties.build_noise_models()
    def _value_equality_values_(self):
        return self._noise_properties
    def is_virtual(self, op: cirq.Operation) -> bool:
        return False
    def noisy_moments(
        self, moments: Iterable[cirq.Moment], system_qubits: Sequence[cirq.Qid]
    ) -> Sequence[cirq.OP_TREE]:
        split_measure_moments = []
        multi_measurements = {}
        for moment in moments:
            split_measure_ops = []
            for op in moment:
                if not protocols.is_measurement(op):
                    split_measure_ops.append(op)
                    continue
                m_key = protocols.measurement_key_obj(op)
                multi_measurements[m_key] = op
                for q in op.qubits:
                    split_measure_ops.append(ops.measure(q, key=m_key))
            split_measure_moments.append(circuits.Moment(split_measure_ops))
        new_moments = []
        for moment in split_measure_moments:
            virtual_ops = {op for op in moment if self.is_virtual(op)}
            physical_ops = [
                op.with_tags(PHYSICAL_GATE_TAG) for op in moment if op not in virtual_ops
            ]
            if virtual_ops:
                new_moments.append(circuits.Moment(virtual_ops))  # pragma: no cover
            if physical_ops:
                new_moments.append(circuits.Moment(physical_ops))
        split_measure_circuit = circuits.Circuit(new_moments)
        noisy_circuit = split_measure_circuit.copy()
        for model in self.noise_models:
            noisy_circuit = noisy_circuit.with_noise(model)
        final_moments = []
        for moment in noisy_circuit:
            combined_measure_ops = []
            restore_keys = set()
            for op in moment:
                if not protocols.is_measurement(op):
                    combined_measure_ops.append(op)
                    continue
                restore_keys.add(protocols.measurement_key_obj(op))
            for key in restore_keys:
                combined_measure_ops.append(multi_measurements[key])
            final_moments.append(circuits.Moment(combined_measure_ops))
        return final_moments
    def _json_dict_(self) -> dict[str, object]:
        return {'noise_properties': self._noise_properties}

from __future__ import annotations
from typing import TYPE_CHECKING
import cirq
import cirq.testing
from cirq.devices.insertion_noise_model import InsertionNoiseModel
from cirq.devices.noise_properties import NoiseModelFromNoiseProperties, NoiseProperties
from cirq.devices.noise_utils import OpIdentifier, PHYSICAL_GATE_TAG
if TYPE_CHECKING:
    from cirq.protocols.json_serialization import ObjectFactory
@cirq.value_equality
class SampleNoiseProperties(NoiseProperties):
    def __init__(self, system_qubits: list[cirq.Qid], qubit_pairs: list[tuple[cirq.Qid, cirq.Qid]]):
        self.qubits = system_qubits
        self.qubit_pairs = qubit_pairs
    def build_noise_models(self) -> list[cirq.NoiseModel]:
        add_h = InsertionNoiseModel({OpIdentifier(cirq.Gate, q): cirq.H(q) for q in self.qubits})
        add_iswap = InsertionNoiseModel(
            {OpIdentifier(cirq.Gate, *qs): cirq.ISWAP(*qs) for qs in self.qubit_pairs}
        )
        return [add_h, add_iswap]
    def _value_equality_values_(self):
        return (self.qubits, self.qubit_pairs)
    def _json_dict_(self) -> dict[str, object]:
        return {'system_qubits': self.qubits, 'qubit_pairs': self.qubit_pairs}
    @classmethod
    def _from_json_dict_(cls, system_qubits, qubit_pairs, **kwargs):
        return cls(system_qubits=system_qubits, qubit_pairs=[tuple(pair) for pair in qubit_pairs])
def test_sample_model() -> None:
    q0, q1 = cirq.LineQubit.range(2)
    props = SampleNoiseProperties([q0, q1], [(q0, q1), (q1, q0)])
    model = NoiseModelFromNoiseProperties(props)
    circuit = cirq.Circuit(
        cirq.X(q0), cirq.CNOT(q0, q1), cirq.Z(q1), cirq.measure(q0, q1, key='meas')
    )
    noisy_circuit = circuit.with_noise(model)
    expected_circuit = cirq.Circuit(
        cirq.Moment(cirq.X(q0).with_tags(PHYSICAL_GATE_TAG)),
        cirq.Moment(cirq.H(q0)),
        cirq.Moment(cirq.CNOT(q0, q1).with_tags(PHYSICAL_GATE_TAG)),
        cirq.Moment(cirq.ISWAP(q0, q1)),
        cirq.Moment(cirq.Z(q1).with_tags(PHYSICAL_GATE_TAG)),
        cirq.Moment(cirq.H(q1)),
        cirq.Moment(cirq.measure(q0, q1, key='meas')),
        cirq.Moment(cirq.H(q0), cirq.H(q1)),
    )
    assert noisy_circuit == expected_circuit
def custom_resolver(cirq_type: str) -> ObjectFactory | None:
    if cirq_type == "SampleNoiseProperties":
        return SampleNoiseProperties
    return None
def test_noise_model_from_noise_properties_json() -> None:
    q0, q1 = cirq.LineQubit.range(2)
    props = SampleNoiseProperties([q0, q1], [(q0, q1), (q1, q0)])
    model = NoiseModelFromNoiseProperties(props)
    resolvers = [custom_resolver] + cirq.DEFAULT_RESOLVERS
    cirq.testing.assert_json_roundtrip_works(model, resolvers=resolvers)

