def random_rotations_between_two_qubit_circuit(
    q0: cirq.Qid,
    q1: cirq.Qid,
    depth: int,
    two_qubit_op_factory: Callable[
        [cirq.Qid, cirq.Qid, np.random.RandomState], cirq.OP_TREE
    ] = lambda a, b, _: ops.CZPowGate()(a, b),
    single_qubit_gates: Sequence[cirq.Gate] = (
        ops.X**0.5,
        ops.Y**0.5,
        ops.PhasedXPowGate(phase_exponent=0.25, exponent=0.5),
    ),
    add_final_single_qubit_layer: bool = True,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> cirq.Circuit:
    prng = value.parse_random_state(seed)
    circuit = circuits.Circuit()
    previous_single_qubit_layer = circuits.Moment()
    single_qubit_layer_factory = _single_qubit_gates_arg_to_factory(
        single_qubit_gates=single_qubit_gates, qubits=(q0, q1), prng=prng
    )
    for _ in range(depth):
        single_qubit_layer = single_qubit_layer_factory.new_layer(previous_single_qubit_layer)
        circuit += single_qubit_layer
        circuit += two_qubit_op_factory(q0, q1, prng)
        previous_single_qubit_layer = single_qubit_layer
    if add_final_single_qubit_layer:
        circuit += single_qubit_layer_factory.new_layer(previous_single_qubit_layer)
    return circuit
def generate_library_of_2q_circuits(
    n_library_circuits: int,
    two_qubit_gate: cirq.Gate,
    *,
    max_cycle_depth: int = 100,
    q0: cirq.Qid = devices.LineQubit(0),
    q1: cirq.Qid = devices.LineQubit(1),
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    tags: Sequence[Any] = (),
) -> list[cirq.Circuit]:
    rs = value.parse_random_state(random_state)
    exponents = np.linspace(0, 7 / 4, 8)
    single_qubit_gates = [
        ops.PhasedXZGate(x_exponent=0.5, z_exponent=z, axis_phase_exponent=a)
        for a, z in itertools.product(exponents, repeat=2)
    ]
    return [
        random_rotations_between_two_qubit_circuit(
            q0,
            q1,
            depth=max_cycle_depth,
            two_qubit_op_factory=lambda a, b, _: two_qubit_gate(a, b).with_tags(*tags),
            single_qubit_gates=single_qubit_gates,
            seed=rs,
        )
        for _ in range(n_library_circuits)
    ]
def _get_active_pairs(graph: nx.Graph, grid_layer: GridInteractionLayer):
    for edge in graph.edges:
        if edge in grid_layer:
            yield edge
@dataclasses.dataclass(frozen=True)
class CircuitLibraryCombination:
    layer: Any | None
    combinations: np.ndarray
    pairs: Sequence[QidPairT]
def _get_random_combinations(
    n_library_circuits: int,
    n_combinations: int,
    *,
    pair_gen: Iterator[tuple[list[QidPairT], Any]],
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> list[CircuitLibraryCombination]:
    rs = value.parse_random_state(random_state)
    combinations_by_layer = []
    for pairs, layer in pair_gen:
        combinations = rs.randint(0, n_library_circuits, size=(n_combinations, len(pairs)))
        combinations_by_layer.append(
            CircuitLibraryCombination(layer=layer, combinations=combinations, pairs=pairs)
        )
    return combinations_by_layer
def get_random_combinations_for_device(
    n_library_circuits: int,
    n_combinations: int,
    device_graph: nx.Graph,
    *,
    pattern: Sequence[GridInteractionLayer] = HALF_GRID_STAGGERED_PATTERN,
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> list[CircuitLibraryCombination]:
    def pair_gen():
        for layer in pattern:
            pairs = sorted(_get_active_pairs(device_graph, layer))
            if len(pairs) == 0:
                continue
            yield pairs, layer
    return _get_random_combinations(
        n_library_circuits=n_library_circuits,
        n_combinations=n_combinations,
        random_state=random_state,
        pair_gen=pair_gen(),
    )
def get_random_combinations_for_pairs(
    n_library_circuits: int,
    n_combinations: int,
    all_pairs: list[list[QidPairT]],
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> list[CircuitLibraryCombination]:
    def pair_gen():
        for pairs in all_pairs:
            yield pairs, None
    return _get_random_combinations(
        n_library_circuits=n_library_circuits,
        n_combinations=n_combinations,
        random_state=random_state,
        pair_gen=pair_gen(),
    )
def _pairs_from_moment(moment: cirq.Moment) -> list[QidPairT]:
    pairs: list[QidPairT] = []
    for op in moment.operations:
        if len(op.qubits) != 2:
            raise ValueError("Layer circuit contains non-2-qubit operations.")
        pairs.append(op.qubits)
    return pairs
def get_random_combinations_for_layer_circuit(
    n_library_circuits: int,
    n_combinations: int,
    layer_circuit: cirq.Circuit,
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> list[CircuitLibraryCombination]:
    def pair_gen():
        for moment in layer_circuit.moments:
            yield _pairs_from_moment(moment), moment
    return _get_random_combinations(
        n_library_circuits=n_library_circuits,
        n_combinations=n_combinations,
        random_state=random_state,
        pair_gen=pair_gen(),
    )
def get_grid_interaction_layer_circuit(
    device_graph: nx.Graph,
    pattern: Sequence[GridInteractionLayer] = HALF_GRID_STAGGERED_PATTERN,
    two_qubit_gate=ops.ISWAP**0.5,
) -> cirq.Circuit:
    moments = []
    for layer in pattern:
        pairs = sorted(_get_active_pairs(device_graph, layer))
        if pairs:
            moments += [circuits.Moment(two_qubit_gate.on(*pair) for pair in pairs)]
    return circuits.Circuit(moments)
def random_rotations_between_grid_interaction_layers_circuit(
    qubits: Iterable[cirq.GridQubit],
    depth: int,
    *,  # forces keyword arguments
    two_qubit_op_factory: Callable[
        [cirq.GridQubit, cirq.GridQubit, np.random.RandomState], cirq.OP_TREE
    ] = lambda a, b, _: ops.CZPowGate()(a, b),
    pattern: Sequence[GridInteractionLayer] = GRID_STAGGERED_PATTERN,
    single_qubit_gates: Sequence[cirq.Gate] = (
        ops.X**0.5,
        ops.Y**0.5,
        ops.PhasedXPowGate(phase_exponent=0.25, exponent=0.5),
    ),
    add_final_single_qubit_layer: bool = True,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> cirq.Circuit:
    prng = value.parse_random_state(seed)
    qubits = list(qubits)
    coupled_qubit_pairs = _coupled_qubit_pairs(qubits)
    circuit = circuits.Circuit()
    previous_single_qubit_layer = circuits.Moment()
    single_qubit_layer_factory = _single_qubit_gates_arg_to_factory(
        single_qubit_gates=single_qubit_gates, qubits=qubits, prng=prng
    )
    for i in range(depth):
        single_qubit_layer = single_qubit_layer_factory.new_layer(previous_single_qubit_layer)
        circuit += single_qubit_layer
        two_qubit_layer = _two_qubit_layer(
            coupled_qubit_pairs, two_qubit_op_factory, pattern[i % len(pattern)], prng
        )
        circuit += two_qubit_layer
        previous_single_qubit_layer = single_qubit_layer
    if add_final_single_qubit_layer:
        circuit += single_qubit_layer_factory.new_layer(previous_single_qubit_layer)
    return circuit
def _coupled_qubit_pairs(qubits: list[cirq.GridQubit]) -> list[GridQubitPairT]:
    pairs = []
    qubit_set = set(qubits)
    for qubit in qubits:
        def add_pair(neighbor: cirq.GridQubit):
            if neighbor in qubit_set:
                pairs.append((qubit, neighbor))
        add_pair(devices.GridQubit(qubit.row, qubit.col + 1))
        add_pair(devices.GridQubit(qubit.row + 1, qubit.col))
    return pairs
class _RandomSingleQubitLayerFactory:
    def __init__(
        self,
        qubits: Sequence[cirq.Qid],
        single_qubit_gates: Sequence[cirq.Gate],
        prng: np.random.RandomState,
    ) -> None:
        self.qubits = qubits
        self.single_qubit_gates = single_qubit_gates
        self.prng = prng
    def new_layer(self, previous_single_qubit_layer: cirq.Moment) -> cirq.Moment:
        def random_gate(qubit: cirq.Qid) -> cirq.Gate:
            excluded_op = previous_single_qubit_layer.operation_at(qubit)
            excluded_gate = excluded_op.gate if excluded_op is not None else None
            g = self.single_qubit_gates[self.prng.randint(0, len(self.single_qubit_gates))]
            while g is excluded_gate:
                g = self.single_qubit_gates[self.prng.randint(0, len(self.single_qubit_gates))]
            return g
        return circuits.Moment(random_gate(q).on(q) for q in self.qubits)
class _FixedSingleQubitLayerFactory:
    def __init__(self, fixed_single_qubit_layer: dict[cirq.Qid, cirq.Gate]) -> None:
        self.fixed_single_qubit_layer = fixed_single_qubit_layer
    def new_layer(self, previous_single_qubit_layer: cirq.Moment) -> cirq.Moment:
        return circuits.Moment(v.on(q) for q, v in self.fixed_single_qubit_layer.items())
_SingleQubitLayerFactory = _FixedSingleQubitLayerFactory | _RandomSingleQubitLayerFactory
def _single_qubit_gates_arg_to_factory(
    single_qubit_gates: Sequence[cirq.Gate], qubits: Sequence[cirq.Qid], prng: np.random.RandomState
) -> _SingleQubitLayerFactory:
    if len(set(single_qubit_gates)) == 1:
        return _FixedSingleQubitLayerFactory({q: single_qubit_gates[0] for q in qubits})
    return _RandomSingleQubitLayerFactory(qubits, single_qubit_gates, prng)
def _two_qubit_layer(
    coupled_qubit_pairs: list[GridQubitPairT],
    two_qubit_op_factory: Callable[
        [cirq.GridQubit, cirq.GridQubit, np.random.RandomState], cirq.OP_TREE
    ],
    layer: GridInteractionLayer,
    prng: np.random.RandomState,
) -> Iterator[cirq.OP_TREE]:
    for a, b in coupled_qubit_pairs:
        if (a, b) in layer or (b, a) in layer:
            yield two_qubit_op_factory(a, b, prng)

from __future__ import annotations
import time
from collections.abc import Sequence
from typing import Any, cast, TYPE_CHECKING
import numpy as np
import scipy.optimize
import sympy
from cirq import circuits, ops, study, vis
from cirq._compat import proper_repr
if TYPE_CHECKING:
    import cirq
class TensoredConfusionMatrices:
    def __init__(
        self,
        confusion_matrices: np.ndarray | Sequence[np.ndarray],
        measure_qubits: Sequence[cirq.Qid] | Sequence[Sequence[cirq.Qid]],
        *,
        repetitions: int,
        timestamp: float,
    ):
        if len(measure_qubits) == 0:
            raise ValueError("measure_qubits cannot be empty.")
        if isinstance(confusion_matrices, np.ndarray):
            confusion_matrices = [confusion_matrices]
        measure_qubits = cast(
            Sequence[Sequence['cirq.Qid']],
            [measure_qubits] if isinstance(measure_qubits[0], ops.Qid) else measure_qubits,
        )
        if len(confusion_matrices) != len(measure_qubits):
            raise ValueError(
                f"len(confusion_matrices): {len(confusion_matrices)} should be equal to "
                f"len(measure_qubits): {len(measure_qubits)}"
            )
        for i, (cm, q) in enumerate(zip(confusion_matrices, measure_qubits)):
            if cm.shape != (2 ** len(q),) * 2:
                raise ValueError(
                    f"Shape mismatch for confusion matrix {cm} at index {i} corresponding to {q}."
                    f"Confusion Matrix shape {cm.shape} should match {(2 ** len(q),) * 2}"
                )
        self._timestamp = timestamp
        self._repetitions = repetitions
        self._confusion_matrices = tuple(confusion_matrices)
        self._measure_qubits = tuple(tuple(q) for q in measure_qubits)
        self._qubits = tuple(sorted(set(q for ql in measure_qubits for q in ql)))
        self._qubits_to_idx = {q: i for i, q in enumerate(self._qubits)}
        self._cache: dict[tuple[cirq.Qid, ...], np.ndarray] = {}
        if sum(len(q) for q in self._measure_qubits) != len(self._qubits):
            raise ValueError(f"Repeated qubits not allowed in measure_qubits: {measure_qubits}.")
    @classmethod
    def from_measurement(
        cls, gate: ops.MeasurementGate, qubits: Sequence[cirq.Qid]
    ) -> TensoredConfusionMatrices:
        if not gate.confusion_map:
            raise ValueError(f"Measurement has no confusion matrices: {gate}")
        confusion_matrices = []
        ordered_qubits = []
        for indices, cm in gate.confusion_map.items():
            confusion_matrices.append(cm)
            ordered_qubits.append(tuple(qubits[idx] for idx in indices))
        return cls(confusion_matrices, ordered_qubits, repetitions=0, timestamp=0)
    @property
    def repetitions(self) -> int:
        return self._repetitions
    @property
    def timestamp(self) -> float:
        return self._timestamp
    @property
    def confusion_matrices(self) -> tuple[np.ndarray, ...]:
        return self._confusion_matrices
    @property
    def measure_qubits(self) -> tuple[tuple[cirq.Qid, ...], ...]:
        return self._measure_qubits
    @property
    def qubits(self) -> tuple[cirq.Qid, ...]:
        return self._qubits
    def _get_vars(self, qubit_pattern: Sequence[cirq.Qid]) -> list[int]:
        in_vars = [2 * self._qubits_to_idx[q] for q in qubit_pattern]
        out_vars = [2 * self._qubits_to_idx[q] + 1 for q in qubit_pattern]
        return in_vars + out_vars
    def _confusion_matrix(self, qubits: Sequence[cirq.Qid]) -> np.ndarray:
        ein_input: list[np.ndarray | list[int]] = []
        for qs, cm in zip(self.measure_qubits, self.confusion_matrices):
            ein_input.extend([cm.reshape((2, 2) * len(qs)), self._get_vars(qs)])
        ein_out = self._get_vars(qubits)
        ret = np.einsum(*ein_input, ein_out).reshape((2 ** len(qubits),) * 2)
        return ret / ret.sum(axis=1)
    def confusion_matrix(self, qubits: Sequence[cirq.Qid] | None = None) -> np.ndarray:
        if qubits is None:
            qubits = self.qubits
        if any(q not in self.qubits for q in qubits):
            raise ValueError(f"qubits {qubits} should be a subset of self.qubits {self.qubits}.")
        key = tuple(qubits)
        if key not in self._cache:
            self._cache[key] = self._confusion_matrix(qubits)
        return self._cache[key]
    def correction_matrix(self, qubits: Sequence[cirq.Qid] | None = None) -> np.ndarray:
        if qubits is None:
            qubits = self.qubits
        if any(q not in self.qubits for q in qubits):
            raise ValueError(f"qubits {qubits} should be a subset of self.qubits {self.qubits}.")
        return np.linalg.pinv(self.confusion_matrix(qubits))
    def apply(
        self,
        result: np.ndarray,
        qubits: Sequence[cirq.Qid] | None = None,
        *,
        method='least_squares',
    ) -> np.ndarray:
        if qubits is None:
            qubits = self.qubits
        if result.shape != (2 ** len(qubits),):
            raise ValueError(f"result.shape {result.shape} should be {(2 ** len(qubits),)}.")
        if method not in ['pseudo_inverse', 'least_squares']:
            raise ValueError(f"method: {method} should be 'pseudo_inverse' or 'least_squares'.")
        if method == 'pseudo_inverse':
            return result @ self.correction_matrix(qubits)  # pragma: no cover
        cm = self.confusion_matrix(qubits)
        def func(x):
            return np.sum((result - x @ cm) ** 2)
        constraints = {'type': 'eq', 'fun': lambda x: sum(result) - sum(x)}
        bounds = tuple((0, sum(result)) for _ in result)
        res = scipy.optimize.minimize(
            func, result, method='SLSQP', constraints=constraints, bounds=bounds
        )
        if res.success is False:  # pragma: no cover
            raise ValueError(  # pragma: no cover
                f"SLSQP optimization for constrained minimization "  # pragma: no cover
                f"did not converge. Result:\n{res}"  # pragma: no cover
            )  # pragma: no cover
        return res.x
    def readout_mitigation_pauli_uncorrelated(
        self, qubits: Sequence[cirq.Qid], measured_bitstrings: np.ndarray
    ) -> tuple[float, float]:
        r
        measured_bitstrings = measured_bitstrings.astype(int)
        cm_all = []
        for qubit in qubits:
            try:
                idx = self.measure_qubits.index((qubit,))
            except:  # pragma: no cover
                raise NotImplementedError(
                    "The response matrix must be a tensor product of single-qubit "
                    f"response matrices, including that of qubit {qubit}."
                )
            cm_all.append(self.confusion_matrices[idx])
        cminv_all = [np.linalg.inv(cm) for cm in cm_all]
        z = np.array([1, -1])
        z_cminv_all = np.array([z @ cminv for cminv in cminv_all])
        z_mit_all_shots = np.prod(np.einsum("iji->ij", z_cminv_all[:, measured_bitstrings]), axis=0)
        return np.mean(z_mit_all_shots), np.std(z_mit_all_shots) / np.sqrt(len(measured_bitstrings))
    def __repr__(self) -> str:
        return (
            f"cirq.TensoredConfusionMatrices("
            f"[{','.join([proper_repr(cm) for cm in self.confusion_matrices])}],"
            f"{self.measure_qubits},"
            f"repetitions={self.repetitions},"
            f"timestamp={self.timestamp}"
            f")"
        )
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'confusion_matrices': self.confusion_matrices,
            'measure_qubits': self.measure_qubits,
            'repetitions': self.repetitions,
            'timestamp': self.timestamp,
        }
    @classmethod
    def _from_json_dict_(
        cls, confusion_matrices, measure_qubits, repetitions, timestamp, **kwargs
    ) -> TensoredConfusionMatrices:
        return cls(
            [np.asarray(cm) for cm in confusion_matrices],
            measure_qubits,
            repetitions=repetitions,
            timestamp=timestamp,
        )
    def _approx_eq_(self, other: Any, atol: float) -> bool:
        if not isinstance(other, type(self)):
            return NotImplemented
        return (
            self.qubits == other.qubits
            and self.repetitions == other.repetitions
            and self.timestamp == other.timestamp
            and all(
                np.allclose(cm, ocm, atol=atol)
                for cm, ocm in zip(self.confusion_matrices, other.confusion_matrices)
            )
        )
    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, type(self)):
            return NotImplemented
        return (
            self.qubits == other.qubits
            and self.repetitions == other.repetitions
            and self.timestamp == other.timestamp
            and all(
                np.array_equal(cm, ocm)
                for cm, ocm in zip(self.confusion_matrices, other.confusion_matrices)
            )
        )
    def __ne__(self, other: Any) -> bool:
        return not self == other
def measure_confusion_matrix(
    sampler: cirq.Sampler,
    qubits: Sequence[cirq.Qid] | Sequence[Sequence[cirq.Qid]],
    repetitions: int = 1000,
) -> TensoredConfusionMatrices:
    qubits = cast(
        Sequence[Sequence['cirq.Qid']], [qubits] if isinstance(qubits[0], ops.Qid) else qubits
    )
    confusion_matrices = []
    for qs in qubits:
        flip_symbols = sympy.symbols(f'flip_0:{len(qs)}')
        flip_circuit = circuits.Circuit(
            [ops.X(q) ** s for q, s in zip(qs, flip_symbols)], ops.measure(*qs)
        )
        sweeps = study.Product(*[study.Points(f'flip_{i}', [0, 1]) for i in range(len(qs))])
        results = sampler.run_sweep(flip_circuit, sweeps, repetitions=repetitions)
        confusion_matrices.append(
            np.asarray([vis.get_state_histogram(r) for r in results], dtype=float) / repetitions
        )
    return TensoredConfusionMatrices(
        confusion_matrices, qubits, repetitions=repetitions, timestamp=time.time()
    )

