import sympy
from matplotlib import pyplot as plt
from cirq import _import, circuits, ops, study, value
from cirq._compat import proper_repr
if TYPE_CHECKING:
    import cirq
optimize = _import.LazyLoader("optimize", globals(), "scipy.optimize")
def t1_decay(
    sampler: cirq.Sampler,
    *,
    qubit: cirq.Qid,
    num_points: int,
    max_delay: cirq.DURATION_LIKE,
    min_delay: cirq.DURATION_LIKE = None,
    repetitions: int = 1000,
) -> cirq.experiments.T1DecayResult:
    min_delay_dur = value.Duration(min_delay)
    max_delay_dur = value.Duration(max_delay)
    min_delay_nanos = min_delay_dur.total_nanos()
    max_delay_nanos = max_delay_dur.total_nanos()
    if repetitions <= 0:
        raise ValueError('repetitions <= 0')
    if isinstance(min_delay_nanos, sympy.Expr) or isinstance(max_delay_nanos, sympy.Expr):
        raise ValueError('min_delay and max_delay cannot be sympy expressions.')
    if max_delay_dur < min_delay_dur:
        raise ValueError('max_delay < min_delay')
    if min_delay_dur < 0:
        raise ValueError('min_delay < 0')
    var = sympy.Symbol('delay_ns')
    if min_delay_nanos == 0:
        min_delay_nanos = 0.4
    sweep_vals_ns = np.unique(
        np.round(np.logspace(np.log10(min_delay_nanos), np.log10(max_delay_nanos), num_points))
    )
    sweep = study.Points(var, cast(Sequence[float], sweep_vals_ns))
    circuit = circuits.Circuit(
        ops.X(qubit), ops.wait(qubit, nanos=var), ops.measure(qubit, key='output')
    )
    results = sampler.sample(circuit, params=sweep, repetitions=repetitions)
    tab = pd.crosstab(results.delay_ns, results.output)
    tab.rename_axis(None, axis="columns", inplace=True)
    tab = tab.rename(columns={0: 'false_count', 1: 'true_count'}).reset_index()
    for col_index, name in [(1, 'false_count'), (2, 'true_count')]:
        if name not in tab:
            tab.insert(col_index, name, [0] * tab.shape[0])
    return T1DecayResult(tab)
class T1DecayResult:
    def __init__(self, data: pd.DataFrame):
        assert list(data.columns) == ['delay_ns', 'false_count', 'true_count']
        self._data = data
    @property
    def data(self) -> pd.DataFrame:
        return self._data
    @property
    def constant(self) -> float:
        def exp_decay(x, t1, a, b):
            return a * np.exp(-x / t1) + b
        xs = self._data['delay_ns']
        ts = self._data['true_count']
        fs = self._data['false_count']
        probs = ts / (fs + ts)
        guess_index = np.argmin(np.abs(probs - 1.0 / np.e))
        t1_guess = xs[guess_index]
        try:
            self.popt, _ = optimize.curve_fit(exp_decay, xs, probs, p0=[t1_guess, 1.0, 0.0])
            t1 = self.popt[0]
            return t1
        except RuntimeError:
            warnings.warn("Optimal parameters could not be found for curve fit", RuntimeWarning)
            return np.nan
    def plot(
        self, ax: plt.Axes | None = None, include_fit: bool = False, **plot_kwargs: Any
    ) -> plt.Axes:
        show_plot = not ax
        if show_plot:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        assert ax is not None
        ax.set_ylim(ymin=0, ymax=1)
        xs = self._data['delay_ns']
        ts = self._data['true_count']
        fs = self._data['false_count']
        ax.plot(xs, ts / (fs + ts), 'ro-', **plot_kwargs)
        if include_fit and not np.isnan(self.constant):
            t1 = self.constant
            t1, a, b = self.popt
            ax.plot(xs, a * np.exp(-xs / t1) + b, label='curve fit')
            plt.legend()
        ax.set_xlabel(r"Delay between initialization and measurement (nanoseconds)")
        ax.set_ylabel('Excited State Probability')
        ax.set_title('T1 Decay Experiment Data')
        if show_plot:
            fig.show()
        return ax
    def __str__(self) -> str:
        return f'T1DecayResult with data:\n{self.data}'
    def __eq__(self, other) -> bool:
        if not isinstance(other, type(self)):
            return NotImplemented
        return self.data.equals(other.data)
    def __ne__(self, other) -> bool:
        return not self == other
    def __repr__(self) -> str:
        return f'cirq.experiments.T1DecayResult(data={proper_repr(self.data)})'
    def _repr_pretty_(self, p: Any, cycle: bool) -> None:
        if cycle:
            p.text('T1DecayResult(...)')
        else:
            p.text(str(self))

from __future__ import annotations
import enum
from typing import Any, TYPE_CHECKING
import pandas as pd
import sympy
from matplotlib import pyplot as plt
from cirq import circuits, ops, study, value
from cirq._compat import proper_repr
if TYPE_CHECKING:
    import cirq
class ExperimentType(enum.Enum):
    RAMSEY = 1  # Often denoted as t2*
    HAHN_ECHO = 2  # Spin echo or t2
    CPMG = 3  # Carr-Purcell-Meiboom-Gill sequence
_T2_COLUMNS = ['delay_ns', 0, 1]
def t2_decay(
    sampler: cirq.Sampler,
    *,
    qubit: cirq.Qid,
    experiment_type: ExperimentType = ExperimentType.RAMSEY,
    num_points: int,
    max_delay: cirq.DURATION_LIKE,
    min_delay: cirq.DURATION_LIKE = None,
    repetitions: int = 1000,
    delay_sweep: study.Sweep | None = None,
    num_pulses: list[int] | None = None,
) -> cirq.experiments.T2DecayResult:
    min_delay_dur = value.Duration(min_delay)
    max_delay_dur = value.Duration(max_delay)
    min_delay_nanos = min_delay_dur.total_nanos()
    max_delay_nanos = max_delay_dur.total_nanos()
    if repetitions <= 0:
        raise ValueError('repetitions <= 0')
    if isinstance(min_delay_nanos, sympy.Expr) or isinstance(max_delay_nanos, sympy.Expr):
        raise ValueError('min_delay and max_delay cannot be sympy expressions.')
    if max_delay_dur < min_delay_dur:
        raise ValueError('max_delay < min_delay')
    if min_delay_dur < 0:
        raise ValueError('min_delay < 0')
    if num_pulses and experiment_type != ExperimentType.CPMG:
        raise ValueError('num_pulses is only valid for CPMG experiments.')
    delay_var = sympy.Symbol('delay_ns')
    inv_x_var = sympy.Symbol('inv_x')
    inv_y_var = sympy.Symbol('inv_y')
    max_pulses = max(num_pulses) if num_pulses else 0
    if not delay_sweep:
        delay_sweep = study.Linspace(
            delay_var, start=min_delay_nanos, stop=max_delay_nanos, length=num_points
        )
    if delay_sweep.keys != ['delay_ns']:
        raise ValueError('delay_sweep must be a SingleSweep with delay_ns parameter')
    if experiment_type == ExperimentType.RAMSEY:
        circuit = circuits.Circuit(ops.Y(qubit) ** 0.5, ops.wait(qubit, nanos=delay_var))
    else:
        if experiment_type == ExperimentType.HAHN_ECHO:
            num_pulses = [0]
        if not num_pulses:
            raise ValueError('At least one value must be given for num_pulses in a CPMG experiment')
        circuit = _cpmg_circuit(qubit, delay_var, max_pulses)
    circuit.append(ops.X(qubit) ** inv_x_var)
    circuit.append(ops.Y(qubit) ** inv_y_var)
    circuit.append(ops.measure(qubit, key='output'))
    tomography_sweep = study.Zip(
        study.Points('inv_x', [0.0, 0.5]), study.Points('inv_y', [-0.5, 0.0])
    )
    if num_pulses and max_pulses > 0:
        pulse_sweep = _cpmg_sweep(num_pulses)
        sweep = study.Product(delay_sweep, pulse_sweep, tomography_sweep)
    else:
        sweep = study.Product(delay_sweep, tomography_sweep)
    results = sampler.sample(circuit, params=sweep, repetitions=repetitions)
    y_basis_measurements = results[abs(results.inv_y) > 0].copy()
    x_basis_measurements = results[abs(results.inv_x) > 0].copy()
    if num_pulses and len(num_pulses) > 1:
        cols = tuple(f'pulse_{t}' for t in range(max_pulses))
        x_basis_measurements['num_pulses'] = x_basis_measurements.loc[:, cols].sum(axis=1)
        y_basis_measurements['num_pulses'] = y_basis_measurements.loc[:, cols].sum(axis=1)
    x_basis_tabulation = _create_tabulation(x_basis_measurements)
    y_basis_tabulation = _create_tabulation(y_basis_measurements)
    return T2DecayResult(x_basis_tabulation, y_basis_tabulation)
def _create_tabulation(measurements: pd.DataFrame) -> pd.DataFrame:
    if 'num_pulses' in measurements.columns:
        cols = [measurements.delay_ns, measurements.num_pulses]
    else:
        cols = [measurements.delay_ns]
    tabulation = pd.crosstab(cols, measurements.output).reset_index()
    for col_index, name in [(1, 0), (2, 1)]:
        if name not in tabulation:
            tabulation.insert(col_index, name, [0] * tabulation.shape[0])
    return tabulation
def _cpmg_circuit(qubit: cirq.Qid, delay_var: sympy.Symbol, max_pulses: int) -> cirq.Circuit:
    circuit = circuits.Circuit(ops.Y(qubit) ** 0.5, ops.wait(qubit, nanos=delay_var), ops.X(qubit))
    for n in range(max_pulses):
        pulse_n_on = sympy.Symbol(f'pulse_{n}')
        circuit.append(ops.wait(qubit, nanos=2 * delay_var * pulse_n_on))
        circuit.append(ops.X(qubit) ** pulse_n_on)
    circuit.append(ops.wait(qubit, nanos=delay_var))
    return circuit
def _cpmg_sweep(num_pulses: list[int]):
    pulse_points = []
    for n in range(max(num_pulses)):
        pulse_points.append(study.Points(f'pulse_{n}', [1 if p > n else 0 for p in num_pulses]))
    return study.Zip(*pulse_points)
class T2DecayResult:
    def __init__(self, x_basis_data: pd.DataFrame, y_basis_data: pd.DataFrame):
        x_cols = list(x_basis_data.columns)
        y_cols = list(y_basis_data.columns)
        if any(col not in x_cols for col in _T2_COLUMNS):
            raise ValueError(
                f'x_basis_data must have columns {_T2_COLUMNS} '
                f'but had {list(x_basis_data.columns)}'
            )
        if any(col not in y_cols for col in _T2_COLUMNS):
            raise ValueError(
                f'y_basis_data must have columns {_T2_COLUMNS} '
                f'but had {list(y_basis_data.columns)}'
            )
        self._x_basis_data = x_basis_data
        self._y_basis_data = y_basis_data
        self._expectation_pauli_x = self._expectation(x_basis_data)
        self._expectation_pauli_y = self._expectation(y_basis_data)
    def _expectation(self, data: pd.DataFrame) -> pd.DataFrame:
        delay = data['delay_ns']
        ones = data[1]
        zeros = data[0]
        pauli_expectation = (2 * (ones / (ones + zeros))) - 1.0
        if 'num_pulses' in data.columns:
            return pd.DataFrame(
                {'delay_ns': delay, 'num_pulses': data['num_pulses'], 'value': pauli_expectation}
            )
        return pd.DataFrame({'delay_ns': delay, 'value': pauli_expectation})
    @property
    def expectation_pauli_x(self) -> pd.DataFrame:
        return self._expectation_pauli_x
    @property
    def expectation_pauli_y(self) -> pd.DataFrame:
        return self._expectation_pauli_y
    def plot_expectations(self, ax: plt.Axes | None = None, **plot_kwargs: Any) -> plt.Axes:
        show_plot = not ax
        if show_plot:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        assert ax is not None
        ax.set_ylim(ymin=-2, ymax=2)
        ax.plot(
            self._expectation_pauli_x['delay_ns'],
            self._expectation_pauli_x['value'],
            'bo-',
            label='<X>',
            **plot_kwargs,
        )
        ax.plot(
            self._expectation_pauli_y['delay_ns'],
            self._expectation_pauli_y['value'],
            'go-',
            label='<Y>',
            **plot_kwargs,
        )
        ax.set_xlabel(r"Delay between initialization and measurement (nanoseconds)")
        ax.set_ylabel('Pauli Operator Expectation')
        ax.set_title('T2 Decay Pauli Expectations')
        ax.legend()
        if show_plot:
            fig.show()
        return ax
    def plot_bloch_vector(self, ax: plt.Axes | None = None, **plot_kwargs: Any) -> plt.Axes:
        show_plot = not ax
        if show_plot:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        assert ax is not None
        ax.set_ylim(ymin=0, ymax=1)
        bloch_vector = self._expectation_pauli_x**2 + self._expectation_pauli_y**2
        ax.plot(self._expectation_pauli_x['delay_ns'], bloch_vector['value'], 'r+-', **plot_kwargs)
        ax.set_xlabel(r"Delay between initialization and measurement (nanoseconds)")
        ax.set_ylabel('Bloch Vector X-Y Projection Squared')
        ax.set_title('T2 Decay Experiment Data')
        if show_plot:
            fig.show()
        return ax
    def __str__(self):
        return f'T2DecayResult with data:\n<X>\n{self._x_basis_data}\n<Y>\n{self._y_basis_data}'
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented
        return self._expectation_pauli_x.equals(
            other._expectation_pauli_x
        ) and self._expectation_pauli_y.equals(other._expectation_pauli_y)
    def __repr__(self):
        return (
            f'cirq.experiments.T2DecayResult('
            f'x_basis_data={proper_repr(self._x_basis_data)}, '
            f'y_basis_data={proper_repr(self._y_basis_data)})'
        )
    def _repr_pretty_(self, p: Any, cycle: bool) -> None:
        if cycle:
            p.text('T2DecayResult(...)')
        else:
            p.text(str(self))

from __future__ import annotations
import functools
import itertools
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from types import MappingProxyType
from typing import Any, cast, TYPE_CHECKING
import networkx as nx
import numpy as np
from matplotlib import pyplot as plt
from cirq import ops, value, vis
from cirq._compat import cached_method
from cirq.experiments import random_quantum_circuit_generation as rqcg
from cirq.experiments.qubit_characterizations import (
    parallel_single_qubit_rb,
    ParallelRandomizedBenchmarkingResult,
    RBParameters,
)
from cirq.experiments.xeb_fitting import (
    benchmark_2q_xeb_fidelities,
    exponential_decay,
    fit_exponential_decays,
)
from cirq.experiments.xeb_sampling import sample_2q_xeb_circuits
from cirq.qis import noise_utils
if TYPE_CHECKING:
    import multiprocessing
    import pandas as pd
    import cirq
def _grid_qubits_for_sampler(sampler: cirq.Sampler) -> Sequence[cirq.GridQubit] | None:
    if hasattr(sampler, 'processor'):
        device = sampler.processor.get_device()
        return sorted(device.metadata.qubit_set)
    return None
def _manhattan_distance(qubit1: cirq.GridQubit, qubit2: cirq.GridQubit) -> int:
    return abs(qubit1.row - qubit2.row) + abs(qubit1.col - qubit2.col)
def qubits_and_pairs(
    sampler: cirq.Sampler,
    qubits: Sequence[cirq.GridQubit] | None = None,
    pairs: Sequence[tuple[cirq.GridQubit, cirq.GridQubit]] | None = None,
) -> tuple[Sequence[cirq.GridQubit], Sequence[tuple[cirq.GridQubit, cirq.GridQubit]]]:
    if qubits is None:
        if pairs is None:
            qubits = _grid_qubits_for_sampler(sampler)
            if qubits is None:
                raise ValueError("Couldn't determine qubits from sampler. Please specify them.")
        else:
            qubits_set = set(itertools.chain(*pairs))
            qubits = list(qubits_set)
    if pairs is None:
        pairs = [
            pair for pair in itertools.combinations(qubits, 2) if _manhattan_distance(*pair) == 1
        ]
    return qubits, pairs
@dataclass(frozen=True)
class TwoQubitXEBResult:
    fidelities: pd.DataFrame
    @functools.cached_property
    def _qubit_pair_map(self) -> dict[tuple[cirq.GridQubit, cirq.GridQubit], int]:
        if isinstance(self.fidelities.index[0][0], ops.Qid):
            return {
                (min(q0, q1), max(q0, q1)): i for i, (q0, q1) in enumerate(self.fidelities.index)
            }
        return {
            (min(q0, q1), max(q0, q1)): i
            for i, (_, _, (q0, q1)) in enumerate(self.fidelities.index)
        }
    @functools.cached_property
    def all_qubit_pairs(self) -> tuple[tuple[cirq.GridQubit, cirq.GridQubit], ...]:
        return tuple(sorted(self._qubit_pair_map.keys()))
    def plot_heatmap(self, ax: plt.Axes | None = None, **plot_kwargs) -> plt.Axes:
        show_plot = not ax
        if not isinstance(ax, plt.Axes):
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        heatmap_data: dict[tuple[cirq.GridQubit, ...], float] = {
            pair: self.xeb_error(*pair) for pair in self.all_qubit_pairs
        }
        ax.set_title('device xeb error heatmap')
        vis.TwoQubitInteractionHeatmap(heatmap_data).plot(ax=ax, **plot_kwargs)
        if show_plot:
            fig.show()
        return ax
    def plot_fitted_exponential(
        self, q0: cirq.GridQubit, q1: cirq.GridQubit, ax: plt.Axes | None = None, **plot_kwargs
    ) -> plt.Axes:
        show_plot = not ax
        if not isinstance(ax, plt.Axes):
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        record = self._record(q0, q1)
        ax.axhline(1, color='grey', ls='--')
        ax.plot(record['cycle_depths'], record['fidelities'], 'o')
        depths = np.linspace(0, np.max(record['cycle_depths']))
        ax.plot(
            depths,
            exponential_decay(depths, a=record['a'], layer_fid=record['layer_fid']),
            label='estimated exponential decay',
            **plot_kwargs,
        )
        ax.set_title(f'{q0}-{q1}')
        ax.set_ylabel('Circuit fidelity')
        ax.set_xlabel('Cycle Depth $d$')
        ax.legend(loc='best')
        if show_plot:
            fig.show()
        return ax
    def _record(self, q0, q1) -> pd.Series:
        if q0 > q1:
            q0, q1 = q1, q0
        return self.fidelities.iloc[self._qubit_pair_map[(q0, q1)]]
    def xeb_fidelity(self, q0: cirq.GridQubit, q1: cirq.GridQubit) -> float:
        return noise_utils.decay_constant_to_xeb_fidelity(
            self._record(q0, q1).layer_fid, num_qubits=2
        )
    def xeb_error(self, q0: cirq.GridQubit, q1: cirq.GridQubit) -> float:
        return 1 - self.xeb_fidelity(q0, q1)
    def all_errors(self) -> dict[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        return {(q0, q1): self.xeb_error(q0, q1) for q0, q1 in self.all_qubit_pairs}
    def plot_histogram(self, ax: plt.Axes | None = None, **plot_kwargs) -> plt.Axes:
        fig = None
        if ax is None:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        vis.integrated_histogram(data=self.all_errors(), ax=ax, **plot_kwargs)
        if fig is not None:
            fig.show(**plot_kwargs)
        return ax
    @cached_method
    def pauli_error(self) -> dict[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        return {
            pair: noise_utils.decay_constant_to_pauli_error(
                self._record(*pair).layer_fid, num_qubits=2
            )
            for pair in self.all_qubit_pairs
        }
@dataclass(frozen=True)
class InferredXEBResult:
    rb_result: ParallelRandomizedBenchmarkingResult
    xeb_result: TwoQubitXEBResult
    @property
    def all_qubit_pairs(self) -> Sequence[tuple[cirq.GridQubit, cirq.GridQubit]]:
        return self.xeb_result.all_qubit_pairs
    @cached_method
    def single_qubit_pauli_error(self) -> Mapping[cirq.Qid, float]:
        return self.rb_result.pauli_error()
    @cached_method
    def two_qubit_pauli_error(self) -> Mapping[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        return MappingProxyType(self.xeb_result.pauli_error())
    @cached_method
    def inferred_pauli_error(self) -> Mapping[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        single_q_paulis = self.rb_result.pauli_error()
        xeb = self.xeb_result.pauli_error()
        def _pauli_error(q0: cirq.GridQubit, q1: cirq.GridQubit) -> float:
            q0, q1 = sorted([q0, q1])
            return xeb[(q0, q1)] - single_q_paulis[q0] - single_q_paulis[q1]
        return MappingProxyType({pair: _pauli_error(*pair) for pair in self.all_qubit_pairs})
    @cached_method
    def inferred_decay_constant(self) -> Mapping[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        return MappingProxyType(
            {
                pair: noise_utils.pauli_error_to_decay_constant(pauli, 2)
                for pair, pauli in self.inferred_pauli_error().items()
            }
        )
    @cached_method
    def inferred_xeb_error(self) -> Mapping[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        return MappingProxyType(
            {
                pair: 1 - noise_utils.decay_constant_to_xeb_fidelity(decay, 2)
                for pair, decay in self.inferred_decay_constant().items()
            }
        )
    def _target_errors(
        self, target_error: str
    ) -> Mapping[tuple[cirq.GridQubit, cirq.GridQubit], float]:
        error_funcs = {
            'pauli': self.inferred_pauli_error,
            'decay_constant': self.inferred_decay_constant,
            'xeb': self.inferred_xeb_error,
        }
        return error_funcs[target_error]()
    def plot_heatmap(
        self, target_error: str = 'pauli', ax: plt.Axes | None = None, **plot_kwargs
    ) -> plt.Axes:
        show_plot = not ax
        if not isinstance(ax, plt.Axes):
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        heatmap_data = cast(
            Mapping[tuple['cirq.GridQubit', ...], float], self._target_errors(target_error)
        )
        name = f'{target_error} error' if target_error != 'decay_constant' else 'decay constant'
        ax.set_title(f'device {name} heatmap')
        vis.TwoQubitInteractionHeatmap(heatmap_data).plot(ax=ax, **plot_kwargs)
        if show_plot:
            fig.show()
        return ax
    def plot_histogram(
        self,
        target_error: str = 'pauli',
        ax: plt.Axes | None = None,
        kind: str = 'two_qubit',
        **plot_kwargs,
    ) -> plt.Axes:
        if kind not in ('single_qubit', 'two_qubit', 'both'):
            raise ValueError(
                f"kind must be one of 'single_qubit', 'two_qubit', or 'both', not {kind}"
            )
        if kind != 'two_qubit' and target_error != 'pauli':
            raise ValueError(f'{target_error} is not supported for single qubits')
        fig = None
        if ax is None:
            fig, ax = plt.subplots(1, 1, figsize=(8, 8))
        alpha = 0.5 if kind == 'both' else 1.0
        if kind == 'single_qubit' or kind == 'both':
            self.rb_result.plot_integrated_histogram(
                ax=ax, alpha=alpha, label='single qubit', color='green', **plot_kwargs
            )
        if kind == 'two_qubit' or kind == 'both':
            vis.integrated_histogram(
                data=self._target_errors(target_error),
                ax=ax,
                alpha=alpha,
                label='two qubit',
                color='blue',
                **plot_kwargs,
            )
        if fig is not None:
            fig.show(**plot_kwargs)
        return ax
def parallel_xeb_workflow(
    sampler: cirq.Sampler,
    qubits: Sequence[cirq.GridQubit] | None = None,
    entangling_gate: cirq.Gate = ops.CZ,
    n_repetitions: int = 10**4,
    n_combinations: int = 10,
    n_circuits: int = 20,
    cycle_depths: Sequence[int] = (5, 25, 50, 100, 200, 300),
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ax: plt.Axes | None = None,
    pairs: Sequence[tuple[cirq.GridQubit, cirq.GridQubit]] | None = None,
    pool: multiprocessing.pool.Pool | None = None,
    batch_size: int = 9,
    tags: Sequence[Any] = (),
    **plot_kwargs,
) -> tuple[pd.DataFrame, Sequence[cirq.Circuit], pd.DataFrame]:
    rs = value.parse_random_state(random_state)
    qubits, pairs = qubits_and_pairs(sampler, qubits, pairs)
    graph = nx.Graph(pairs)
    if ax is not None:
        nx.draw_networkx(graph, pos={q: (q.row, q.col) for q in qubits}, ax=ax)
        ax.set_title('device layout')
        ax.plot(**plot_kwargs)
    circuit_library = rqcg.generate_library_of_2q_circuits(
        n_library_circuits=n_circuits,
        two_qubit_gate=entangling_gate,
        random_state=rs,
        max_cycle_depth=max(cycle_depths),
        tags=tags,
    )
    combs_by_layer = rqcg.get_random_combinations_for_device(
        n_library_circuits=len(circuit_library),
        n_combinations=n_combinations,
        device_graph=graph,
        random_state=rs,
    )
    sampled_df = sample_2q_xeb_circuits(
        sampler=sampler,
        circuits=circuit_library,
        cycle_depths=cycle_depths,
        combinations_by_layer=combs_by_layer,
        shuffle=rs,
        repetitions=n_repetitions,
        batch_size=batch_size,
    )
    fids = benchmark_2q_xeb_fidelities(
        sampled_df=sampled_df, circuits=circuit_library, cycle_depths=cycle_depths, pool=pool
    )
    return fids, circuit_library, sampled_df
def parallel_two_qubit_xeb(
    sampler: cirq.Sampler,
    qubits: Sequence[cirq.GridQubit] | None = None,
    entangling_gate: cirq.Gate = ops.CZ,
    n_repetitions: int = 10**4,
    n_combinations: int = 10,
    n_circuits: int = 20,
    cycle_depths: Sequence[int] = (5, 25, 50, 100, 200, 300),
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ax: plt.Axes | None = None,
    pairs: Sequence[tuple[cirq.GridQubit, cirq.GridQubit]] | None = None,
    batch_size: int = 9,
    tags: Sequence[Any] = (),
    **plot_kwargs,
) -> TwoQubitXEBResult:
    fids, *_ = parallel_xeb_workflow(
        sampler=sampler,
        qubits=qubits,
        pairs=pairs,
        entangling_gate=entangling_gate,
        n_repetitions=n_repetitions,
        n_combinations=n_combinations,
        n_circuits=n_circuits,
        cycle_depths=cycle_depths,
        random_state=random_state,
        ax=ax,
        batch_size=batch_size,
        tags=tags,
        **plot_kwargs,
    )
    return TwoQubitXEBResult(fit_exponential_decays(fids))
def run_rb_and_xeb(
    sampler: cirq.Sampler,
    qubits: Sequence[cirq.GridQubit] | None = None,
