    target_qubit_axes: Sequence[int],
    little_endian_qureg_value: int = 0,
    *,  # Forces keyword args.
    big_endian_qureg_value: int = 0,
    num_qubits: int | None = None,
    qid_shape: tuple[int, ...] | None = None,
