from __future__ import annotations
import abc
import itertools
from collections.abc import Iterable, Sequence
from typing import cast, Self, TYPE_CHECKING
import numpy as np
from cirq.ops.raw_types import Gate
if TYPE_CHECKING:
    import cirq
class ArithmeticGate(Gate, metaclass=abc.ABCMeta):
    r
    @abc.abstractmethod
    def registers(self) -> Sequence[int | Sequence[int]]:
        raise NotImplementedError()
    @abc.abstractmethod
    def with_registers(self, *new_registers: int | Sequence[int]) -> Self:
        raise NotImplementedError()
    @abc.abstractmethod
    def apply(self, *register_values: int) -> int | Iterable[int]:
        raise NotImplementedError()
    def _qid_shape_(self) -> tuple[int, ...]:
        shape = []
        for r in self.registers():
            if isinstance(r, Sequence):
                for i in r:
                    shape.append(i)
        return tuple(shape)
    def _apply_unitary_(self, args: cirq.ApplyUnitaryArgs):
        registers = self.registers()
        input_ranges: list[Sequence[int]] = []
        shape: list[int] = []
        overflow_sizes: list[int] = []
        for register in registers:
            if isinstance(register, int):
                input_ranges.append([register])
                shape.append(1)
                overflow_sizes.append(register + 1)
            else:
                size = int(np.prod([dim for dim in register], dtype=np.int64).item())
                shape.append(size)
                input_ranges.append(range(size))
                overflow_sizes.append(size)
        leftover = args.target_tensor.size // np.prod(shape, dtype=np.int64).item()
        new_shape = (*shape, leftover)
        transposed_args = args.with_axes_transposed_to_start()
        src = transposed_args.target_tensor.reshape(new_shape)
        dst = transposed_args.available_buffer.reshape(new_shape)
        for input_seq in itertools.product(*input_ranges):
            output = self.apply(*input_seq)
            inputs: list[int] = list(input_seq)
            outputs: list[int] = [output] if isinstance(output, int) else list(output)
            if len(outputs) < len(inputs):
                outputs += inputs[len(outputs) - len(inputs) :]
            for i in range(len(outputs)):
                if isinstance(registers[i], int):
                    if outputs[i] != registers[i]:
                        raise ValueError(
                            _describe_bad_arithmetic_changed_const(
                                self.registers(), inputs, outputs
                            )
                        )
                    outputs[i] = 0
                    inputs[i] = 0
                else:
                    outputs[i] %= overflow_sizes[i]
            cast(list[int | slice], outputs).append(slice(None))
            cast(list[int | slice], inputs).append(slice(None))
            dst[tuple(outputs)] = src[tuple(inputs)]
        dst.shape = transposed_args.available_buffer.shape
        transposed_args.target_tensor[...] = dst
        return args.target_tensor
def _describe_bad_arithmetic_changed_const(
    registers: Sequence[int | Sequence[cirq.Qid | int]], inputs: list[int], outputs: list[int]
) -> str:
    from cirq.circuits import TextDiagramDrawer
    drawer = TextDiagramDrawer()
    drawer.write(0, 0, 'Register Data')
    drawer.write(1, 0, 'Register Type')
    drawer.write(2, 0, 'Input Value')
    drawer.write(3, 0, 'Output Value')
    for i in range(len(registers)):
        drawer.write(0, i + 1, str(registers[i]))
        drawer.write(1, i + 1, 'constant' if isinstance(registers[i], int) else 'qureg')
        drawer.write(2, i + 1, str(inputs[i]))
        drawer.write(3, i + 1, str(outputs[i]))
    return (
        "A register cannot be set to an int (a classical constant) unless its "
        "value is not affected by the gate.\n"
        "\nExample case where a constant changed:\n"
        + drawer.render(horizontal_spacing=1, vertical_spacing=0)
    )

from __future__ import annotations
import functools
import itertools
from collections.abc import Generator, Sequence
from typing import Any
import sympy.parsing.sympy_parser as sympy_parser
import cirq
from cirq import value
from cirq.ops import raw_types
from cirq.ops.linear_combinations import PauliSum
from cirq.ops.pauli_string import PauliString
@value.value_equality
class BooleanHamiltonianGate(raw_types.Gate):
    r
    def __init__(self, parameter_names: Sequence[str], boolean_strs: Sequence[str], theta: float):
        self._parameter_names: Sequence[str] = parameter_names
        self._boolean_strs: Sequence[str] = boolean_strs
        self._theta: float = theta
    def _qid_shape_(self) -> tuple[int, ...]:
        return (2,) * len(self._parameter_names)
    def _value_equality_values_(self) -> Any:
        return tuple(self._parameter_names), tuple(self._boolean_strs), self._theta
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'parameter_names': self._parameter_names,
            'boolean_strs': self._boolean_strs,
            'theta': self._theta,
        }
    @classmethod
    def _from_json_dict_(
        cls, parameter_names, boolean_strs, theta, **kwargs
    ) -> cirq.BooleanHamiltonianGate:
        return cls(parameter_names, boolean_strs, theta)
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        qubit_map = dict(zip(self._parameter_names, qubits))
        boolean_exprs = [sympy_parser.parse_expr(boolean_str) for boolean_str in self._boolean_strs]
        hamiltonian_polynomial_list = [
            PauliSum.from_boolean_expression(boolean_expr, qubit_map)
            for boolean_expr in boolean_exprs
        ]
        return _get_gates_from_hamiltonians(hamiltonian_polynomial_list, qubit_map, self._theta)
    def _has_unitary_(self) -> bool:
        return True
    def __repr__(self) -> str:
        return (
            f'cirq.BooleanHamiltonianGate('
            f'parameter_names={self._parameter_names!r}, '
            f'boolean_strs={self._boolean_strs!r}, '
            f'theta={self._theta!r})'
        )
def _gray_code_comparator(k1: tuple[int, ...], k2: tuple[int, ...], flip: bool = False) -> int:
    max_1 = k1[-1] if k1 else -1
    max_2 = k2[-1] if k2 else -1
    if max_1 != max_2:
        return -1 if (max_1 < max_2) ^ flip else 1
    if max_1 == -1:
        return 0
    return _gray_code_comparator(k1[0:-1], k2[0:-1], not flip)
def _simplify_commuting_cnots(
    cnots: list[tuple[int, int]], flip_control_and_target: bool
) -> tuple[bool, list[tuple[int, int]]]:
    target, control = (0, 1) if flip_control_and_target else (1, 0)
    to_remove = set()
    qubit_to_index: list[tuple[int, dict[int, int]]] = []
    for j in range(len(cnots)):
        if not qubit_to_index or cnots[j][target] != qubit_to_index[-1][0]:
            qubit_to_index.append((cnots[j][target], {cnots[j][control]: j}))
            continue
        if cnots[j][control] in qubit_to_index[-1][1]:
            k = qubit_to_index[-1][1].pop(cnots[j][control])
            to_remove.update([k, j])
            if not qubit_to_index[-1][1]:
                qubit_to_index.pop()
        else:
            qubit_to_index[-1][1][cnots[j][control]] = j
    cnots = [cnot for i, cnot in enumerate(cnots) if i not in to_remove]
    return bool(to_remove), cnots
def _simplify_cnots_triplets(
    cnots: list[tuple[int, int]], flip_control_and_target: bool
) -> tuple[bool, list[tuple[int, int]]]:
    target, control = (0, 1) if flip_control_and_target else (1, 0)
    for j in range(1, len(cnots) - 1):
        prev_match_index: dict[int, int] = {}
        for i in range(j - 1, -1, -1):
            if cnots[i][target] == cnots[j][target]:
                continue
            if cnots[i][control] != cnots[j][control]:
                break
            prev_match_index[cnots[i][target]] = i
        post_match_index: dict[int, int] = {}
        for k in range(j + 1, len(cnots)):
            if cnots[j][control] == cnots[k][control]:
                continue
            if cnots[j][target] != cnots[k][target]:
                break
            post_match_index[cnots[k][control]] = k
        keys = prev_match_index.keys() & post_match_index.keys()
        for key in keys:
            new_idx: list[int] = (
                [idx for idx in range(j) if idx != prev_match_index[key]]
                + [post_match_index[key], prev_match_index[key]]
                + [idx for idx in range(j + 1, len(cnots)) if idx != post_match_index[key]]
            )
            cnots = [cnots[idx] for idx in new_idx]
            return True, cnots
    return False, cnots
def _simplify_cnots(cnots: list[tuple[int, int]]) -> list[tuple[int, int]]:
    found_simplification = True
    while found_simplification:
        for simplify_fn, flip_control_and_target in itertools.product(
            [_simplify_commuting_cnots, _simplify_cnots_triplets], [False, True]
        ):
            found_simplification, cnots = simplify_fn(cnots, flip_control_and_target)
            if found_simplification:
                break
    return cnots
def _get_gates_from_hamiltonians(
    hamiltonian_polynomial_list: list[cirq.PauliSum], qubit_map: dict[str, cirq.Qid], theta: float
) -> Generator[cirq.Operation, None, None]:
    combined = sum(hamiltonian_polynomial_list, PauliSum.from_pauli_strings(PauliString({})))
    qubit_names = sorted(qubit_map.keys())
    qubits = [qubit_map[name] for name in qubit_names]
    qubit_indices = {qubit: i for i, qubit in enumerate(qubits)}
    hamiltonians = {}
    for pauli_string in combined:
        w = pauli_string.coefficient.real
        qubit_idx = tuple(sorted(qubit_indices[qubit] for qubit in pauli_string.qubits))
        hamiltonians[qubit_idx] = w
    def _apply_cnots(prevh: tuple[int, ...], currh: tuple[int, ...]):
        cnots: list[tuple[int, int]] = []
        cnots.extend((prevh[i], prevh[-1]) for i in range(len(prevh) - 1))
        cnots.extend((currh[i], currh[-1]) for i in range(len(currh) - 1))
        cnots = _simplify_cnots(cnots)
        for c, t in cnots:
            yield cirq.CNOT(qubits[c], qubits[t])
    sorted_hamiltonian_keys = sorted(
        hamiltonians.keys(), key=functools.cmp_to_key(_gray_code_comparator)
    )
    previous_h: tuple[int, ...] = ()
    for h in sorted_hamiltonian_keys:
        w = hamiltonians[h]
        yield _apply_cnots(previous_h, h)
        if len(h) >= 1:
            yield cirq.Rz(rads=(theta * w)).on(qubits[h[-1]])
        previous_h = h
    yield _apply_cnots(previous_h, ())

from __future__ import annotations
from collections.abc import Mapping, Sequence, Set
from typing import Any, TYPE_CHECKING
import sympy
from cirq import protocols, value
from cirq.ops import op_tree, raw_types
if TYPE_CHECKING:
    import cirq
@value.value_equality
class ClassicallyControlledOperation(raw_types.Operation):
    def __init__(
        self,
        sub_operation: cirq.Operation,
        conditions: Sequence[str | cirq.MeasurementKey | cirq.Condition | sympy.Basic],
    ):
        if protocols.measurement_key_objs(sub_operation):
            raise ValueError(
                f'Cannot conditionally run operations with measurements: {sub_operation}'
            )
        conditions = tuple(conditions)
        if isinstance(sub_operation, ClassicallyControlledOperation):
            conditions += sub_operation._conditions
            sub_operation = sub_operation._sub_operation
        conds: list[cirq.Condition] = []
        for c in conditions:
            if isinstance(c, str):
                c = value.MeasurementKey.parse_serialized(c)
            if isinstance(c, value.MeasurementKey):
                c = value.KeyCondition(c)
            if isinstance(c, sympy.Basic):
                c = value.SympyCondition(c)
            conds.append(c)
        self._conditions: tuple[cirq.Condition, ...] = tuple(conds)
        self._sub_operation: cirq.Operation = sub_operation
    @property
    def classical_controls(self) -> frozenset[cirq.Condition]:
        return frozenset(self._conditions).union(self._sub_operation.classical_controls)
    def without_classical_controls(self) -> cirq.Operation:
        return self._sub_operation.without_classical_controls()
    @property
    def qubits(self) -> tuple[cirq.Qid, ...]:
        return self._sub_operation.qubits
    def with_qubits(self, *new_qubits) -> cirq.Operation:
        return self._sub_operation.with_qubits(*new_qubits).with_classical_controls(
            *self._conditions
        )
    def _decompose_with_context_(self, *, context: cirq.DecompositionContext):
        result = protocols.decompose_once(self._sub_operation, None, flatten=False, context=context)
        if result is None:
            return None
        return op_tree.transform_op_tree(
            result, lambda op: ClassicallyControlledOperation(op, self._conditions)
        )
    def _value_equality_values_(self):
        return (frozenset(self._conditions), self._sub_operation)
    def __str__(self) -> str:
        keys = ', '.join(map(str, self._conditions))
        return f'{self._sub_operation}.with_classical_controls({keys})'
    def __repr__(self):
        return (
            f'cirq.ClassicallyControlledOperation('
            f'{self._sub_operation!r}, {list(self._conditions)!r})'
        )
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self._sub_operation)
    def _parameter_names_(self) -> Set[str]:
        return protocols.parameter_names(self._sub_operation)
    def _resolve_parameters_(
        self, resolver: cirq.ParamResolver, recursive: bool
    ) -> ClassicallyControlledOperation:
        new_sub_op = protocols.resolve_parameters(self._sub_operation, resolver, recursive)
        return ClassicallyControlledOperation(new_sub_op, self._conditions)
    def _circuit_diagram_info_(
        self, args: cirq.CircuitDiagramInfoArgs
    ) -> protocols.CircuitDiagramInfo | None:
        sub_args = protocols.CircuitDiagramInfoArgs(
            known_qubit_count=args.known_qubit_count,
            known_qubits=args.known_qubits,
            use_unicode_characters=args.use_unicode_characters,
            precision=args.precision,
            label_map=args.label_map,
        )
        sub_info = protocols.circuit_diagram_info(self._sub_operation, sub_args, None)
        if sub_info is None:
            return NotImplemented  # pragma: no cover
        control_label_count = 0
        if args.label_map is not None:
            control_label_count = len({k for c in self._conditions for k in c.keys})
        wire_symbols = sub_info.wire_symbols + ('^',) * control_label_count
        if control_label_count == 0 or any(
            not isinstance(c, value.KeyCondition) for c in self._conditions
        ):
            wire_symbols = (
                wire_symbols[0]
                + '(conditions=['
                + ', '.join(str(c) for c in self._conditions)
                + '])',
            ) + wire_symbols[1:]
        exp_index = sub_info.exponent_qubit_index
        if exp_index is None:
            exp_index = len(sub_info.wire_symbols) - 1
        return protocols.CircuitDiagramInfo(
            wire_symbols=wire_symbols, exponent=sub_info.exponent, exponent_qubit_index=exp_index
        )
    def _json_dict_(self) -> dict[str, Any]:
        return {'conditions': self._conditions, 'sub_operation': self._sub_operation}
    def _act_on_(self, sim_state: cirq.SimulationStateBase) -> bool:
        if all(c.resolve(sim_state.classical_data) for c in self._conditions):
            protocols.act_on(self._sub_operation, sim_state)
        return True
    def _with_measurement_key_mapping_(
        self, key_map: Mapping[str, str]
    ) -> ClassicallyControlledOperation:
        conditions = [protocols.with_measurement_key_mapping(c, key_map) for c in self._conditions]
        sub_operation = protocols.with_measurement_key_mapping(self._sub_operation, key_map)
        sub_operation = self._sub_operation if sub_operation is NotImplemented else sub_operation
        return sub_operation.with_classical_controls(*conditions)
    def _with_key_path_prefix_(self, prefix: tuple[str, ...]) -> ClassicallyControlledOperation:
        conditions = [protocols.with_key_path_prefix(c, prefix) for c in self._conditions]
        sub_operation = protocols.with_key_path_prefix(self._sub_operation, prefix)
        sub_operation = self._sub_operation if sub_operation is NotImplemented else sub_operation
        return sub_operation.with_classical_controls(*conditions)
    def _with_rescoped_keys_(
        self, path: tuple[str, ...], bindable_keys: frozenset[cirq.MeasurementKey]
    ) -> ClassicallyControlledOperation:
        conds = [protocols.with_rescoped_keys(c, path, bindable_keys) for c in self._conditions]
        sub_operation = protocols.with_rescoped_keys(self._sub_operation, path, bindable_keys)
        return sub_operation.with_classical_controls(*conds)
    def _control_keys_(self) -> frozenset[cirq.MeasurementKey]:
        local_keys: frozenset[cirq.MeasurementKey] = frozenset(
            k for condition in self._conditions for k in condition.keys
        )
        return local_keys.union(protocols.control_keys(self._sub_operation))
    def _qasm_(self, args: cirq.QasmArgs) -> str | None:
        args.validate_version('2.0', '3.0')
        if args.version == "2.0" and len(self._conditions) > 1:
            raise ValueError(
                'QASM 2.0 does not support multiple conditions. Consider exporting with QASM 3.0.'
            )
        subop_qasm = protocols.qasm(self._sub_operation, args=args)
        if not self._conditions:
            return subop_qasm
        condition_qasm = " && ".join(protocols.qasm(c, args=args) for c in self._conditions)
        return f'if ({condition_qasm}) {subop_qasm}'

