def _to_pauli_tuple(matrix: np.ndarray) -> tuple[Pauli, bool] | None:
    for pauli in Pauli._XYZ:
        p = protocols.unitary(pauli)
        if np.allclose(matrix, p):
            return (pauli, False)
        if np.allclose(matrix, -p):
            return (pauli, True)
    return None
