        next_pauli = Pauli.by_relative_index(pauli, 1)
        if sqrt:
            rotation_map = {
                prev_pauli: (next_pauli, True),
                pauli: (pauli, False),
                next_pauli: (prev_pauli, False),
            }
        else:
            rotation_map = {
                prev_pauli: (prev_pauli, True),
                pauli: (pauli, False),
                next_pauli: (next_pauli, True),
