    def __str__(self) -> str:
        return str(self.control_values) + str(self.sub_gate)
    def __repr__(self) -> str:
        if self.control_qid_shape == (2,) and self.control_values.is_trivial:
            return f'cirq.ControlledGate(sub_gate={self.sub_gate!r})'
        if self.control_values.is_trivial and set(self.control_qid_shape) == {2}:
            return (
                f'cirq.ControlledGate(sub_gate={self.sub_gate!r}, '
                f'num_controls={self.num_controls()!r})'
            )
        return (
            f'cirq.ControlledGate(sub_gate={self.sub_gate!r}, '
            f'control_values={self.control_values!r},'
            f'control_qid_shape={self.control_qid_shape!r})'
        )
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'control_values': self.control_values,
            'control_qid_shape': self.control_qid_shape,
            'sub_gate': self.sub_gate,
        }
def _validate_sub_object(sub_object: cirq.Gate | cirq.Operation):
    if protocols.is_measurement(sub_object):
        raise ValueError(f'Cannot control measurement {sub_object}')
    if not protocols.has_mixture(sub_object) and not protocols.is_parameterized(sub_object):
        raise ValueError(f'Cannot control channel with non-unitary operators: {sub_object}')

from __future__ import annotations
from collections.abc import Collection, Sequence, Set
from types import EllipsisType, NotImplementedType
from typing import Any, TYPE_CHECKING
import numpy as np
from cirq import protocols, qis, value
from cirq.ops import (
    common_gates,
    control_values as cv,
    controlled_gate,
    eigen_gate,
    gate_operation,
    op_tree,
    raw_types,
)
if TYPE_CHECKING:
    import cirq
@value.value_equality
class ControlledOperation(raw_types.Operation):
    def __init__(
        self,
        controls: Sequence[cirq.Qid],
        sub_operation: cirq.Operation,
        control_values: cv.AbstractControlValues | Sequence[int | Collection[int]] | None = None,
    ):
        controlled_gate._validate_sub_object(sub_operation)
        if control_values is None:
            control_values = ((1,),) * len(controls)
        if not isinstance(control_values, cv.AbstractControlValues):
            control_values = cv.ProductOfSums(control_values)
        if protocols.num_qubits(control_values) != len(controls):
            raise ValueError('cirq.num_qubits(control_values) != len(controls)')
        control_set = set(controls)
        if len(controls) != len(control_set):
            seen = set()
            dupes = [x for x in controls if x in seen or seen.add(x)]  # type: ignore
            raise ValueError(f'Duplicate control qubits {[str(x) for x in dupes]}.')
        if not control_set.isdisjoint(sub_operation.qubits):
            overlap = control_set.intersection(sub_operation.qubits)
            raise ValueError(f'Sub-op and controls share qubits {[str(x) for x in overlap]}.')
        self._control_values = control_values
        self._control_values.validate([q.dimension for q in controls])
        if not isinstance(sub_operation, ControlledOperation):
            self._controls = tuple(controls)
            self._sub_operation = sub_operation
        else:
            self._controls = tuple(controls) + sub_operation.controls
            self._sub_operation = sub_operation.sub_operation
            self._control_values = self._control_values & sub_operation.control_values
    @property
    def controls(self) -> tuple[cirq.Qid, ...]:
        return self._controls
    @property
    def control_values(self) -> cv.AbstractControlValues:
        return self._control_values
    @property
    def sub_operation(self) -> cirq.Operation:
        return self._sub_operation
    @property
    def gate(self) -> cirq.ControlledGate | None:
        if self.sub_operation.gate is None:
            return None
        return controlled_gate.ControlledGate(
            self.sub_operation.gate,
            control_values=self.control_values,
            control_qid_shape=[q.dimension for q in self.controls],
        )
    @property
    def qubits(self) -> tuple[cirq.Qid, ...]:
        return self.controls + self.sub_operation.qubits
    def with_qubits(self, *new_qubits) -> ControlledOperation:
        n = len(self.controls)
        return ControlledOperation(
            new_qubits[:n], self.sub_operation.with_qubits(*new_qubits[n:]), self.control_values
        )
    def _decompose_with_context_(self, *, context: cirq.DecompositionContext):
        result = protocols.decompose_once_with_qubits(
            self.gate, self.qubits, None, flatten=False, context=context
        )
        if result is not None:
            return result
        result = protocols.decompose_once(self.sub_operation, None, flatten=False, context=context)
        if result is None:
            return None
        return op_tree.transform_op_tree(
            result, lambda op: op.controlled_by(*self.controls, control_values=self.control_values)
        )
    def _value_equality_values_(self):
        sorted_controls, expanded_cvals = tuple(
            zip(*sorted(zip(self.controls, zip(*self.control_values.expand()))))
        )
        return sorted_controls, tuple(expanded_cvals), self.sub_operation
    def _apply_unitary_(self, args: protocols.ApplyUnitaryArgs) -> np.ndarray:
        n = len(self.controls)
        sub_n = len(args.axes) - n
        sub_axes = args.axes[n:]
        for control_vals in self.control_values.expand():
            active: tuple[EllipsisType | slice, ...] = (
                ...,
                *(slice(v, v + 1) for v in control_vals),
                *(slice(None),) * sub_n,
            )
            target_view = args.target_tensor[active]
            buffer_view = args.available_buffer[active]
            result = protocols.apply_unitary(
                self.sub_operation,
                protocols.ApplyUnitaryArgs(target_view, buffer_view, sub_axes),
                default=NotImplemented,
            )
            if result is NotImplemented:
                return NotImplemented
            if result is not target_view:
                target_view[...] = result
        return args.target_tensor
    def _has_unitary_(self) -> bool:
        return protocols.has_unitary(self.sub_operation)
    def _qasm_(self, args: cirq.QasmArgs) -> str | None:
        if (
            hasattr(self._sub_operation, "gate")
            and len(self._controls) == 1
            and self.control_values == cv.ProductOfSums(((1,),))
            and all(q.dimension == 2 for q in self.qubits)
        ):
            gate = self.sub_operation.gate
            if (
                isinstance(gate, eigen_gate.EigenGate)
                and gate.exponent == 1
                and gate.global_shift == 0
            ):
                instr = None
                if isinstance(gate, common_gates.XPowGate):
                    instr = 'cx {0},{1};\n'
                elif isinstance(gate, common_gates.YPowGate):
                    instr = 'cy {0},{1};\n'
                elif isinstance(gate, common_gates.ZPowGate):
                    instr = 'cz {0},{1};\n'
                elif isinstance(gate, common_gates.HPowGate):
                    instr = 'ch {0},{1};\n'
                if instr:
                    return args.format(instr, self._controls[0], self.sub_operation.qubits[0])
        return None
    def _extend_matrix(self, sub_matrix: np.ndarray) -> np.ndarray:
        qid_shape = protocols.qid_shape(self)
        sub_n = len(qid_shape) - len(self.controls)
        tensor = qis.eye_tensor(qid_shape, dtype=sub_matrix.dtype)
        sub_tensor = sub_matrix.reshape(qid_shape[len(self.controls) :] * 2)
        for control_vals in self.control_values.expand():
            active = (*(v for v in control_vals), *(slice(None),) * sub_n) * 2
            tensor[active] = sub_tensor  # type: ignore[index]
        return tensor.reshape((np.prod(qid_shape, dtype=np.int64).item(),) * 2)
    def _unitary_(self) -> np.ndarray | NotImplementedType:
        sub_matrix = protocols.unitary(self.sub_operation, None)
        if sub_matrix is None:
            return NotImplemented
        return self._extend_matrix(sub_matrix)
    def _has_mixture_(self) -> bool:
        return protocols.has_mixture(self.sub_operation)
    def _mixture_(self) -> list[tuple[float, np.ndarray]] | None:
        sub_mixture = protocols.mixture(self.sub_operation, None)
        if sub_mixture is None:
            return None
        return [(p, self._extend_matrix(m)) for p, m in sub_mixture]
    def __str__(self) -> str:
        prefix = str(self.control_values)
        if isinstance(self.sub_operation, gate_operation.GateOperation):
            qubits = ', '.join(map(str, self.qubits))
            return f'{prefix}{self.sub_operation.gate}({qubits})'
        controls = ', '.join(str(q) for q in self.controls)
        return f'{prefix}({controls}, {self.sub_operation})'
    def __repr__(self):
        if all(q.dimension == 2 for q in self.controls):
            if self.control_values.is_trivial:
                if self == self.sub_operation.controlled_by(*self.controls):
                    qubit_args = ', '.join(repr(q) for q in self.controls)
                    return f'{self.sub_operation!r}.controlled_by({qubit_args})'
        return (
            f'cirq.ControlledOperation('
            f'sub_operation={self.sub_operation!r},'
            f'control_values={self.control_values!r},'
            f'controls={self.controls!r})'
        )
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self.sub_operation)
    def _parameter_names_(self) -> Set[str]:
        return protocols.parameter_names(self.sub_operation)
    def _resolve_parameters_(
        self, resolver: cirq.ParamResolver, recursive: bool
    ) -> ControlledOperation:
        new_sub_op = protocols.resolve_parameters(self.sub_operation, resolver, recursive)
        return ControlledOperation(self.controls, new_sub_op, self.control_values)
    def _trace_distance_bound_(self) -> float | None:
        if self._is_parameterized_():
            return None
        u = protocols.unitary(self.sub_operation, default=None)
        if u is None:
            return NotImplemented  # pragma: no cover
        angle_list = np.append(np.angle(np.linalg.eigvals(u)), 0)
        return protocols.trace_distance_from_angle_list(angle_list)
    def __pow__(self, exponent: Any) -> ControlledOperation:
        new_sub_op = protocols.pow(self.sub_operation, exponent, NotImplemented)
        if new_sub_op is NotImplemented:
            return NotImplemented
        return ControlledOperation(self.controls, new_sub_op, self.control_values)
    def _circuit_diagram_info_(
        self, args: cirq.CircuitDiagramInfoArgs
    ) -> protocols.CircuitDiagramInfo | None:
        n = len(self.controls)
        sub_args = protocols.CircuitDiagramInfoArgs(
            known_qubit_count=(
                args.known_qubit_count - n if args.known_qubit_count is not None else None
            ),
            known_qubits=(args.known_qubits[n:] if args.known_qubits is not None else None),
            use_unicode_characters=args.use_unicode_characters,
            precision=args.precision,
            label_map=args.label_map,
        )
        sub_info = protocols.circuit_diagram_info(self.sub_operation, sub_args, None)
        if sub_info is None:
            return NotImplemented
        cv_info = protocols.circuit_diagram_info(self.control_values)
        wire_symbols = (*cv_info.wire_symbols, *sub_info.wire_symbols)
        exponent_qubit_index = None
        num_controls = protocols.num_qubits(self.control_values)
        if sub_info.exponent_qubit_index is not None:
            exponent_qubit_index = sub_info.exponent_qubit_index + num_controls
        elif sub_info.exponent is not None:
            exponent_qubit_index = num_controls
        return protocols.CircuitDiagramInfo(
            wire_symbols=wire_symbols,
            exponent=sub_info.exponent,
            exponent_qubit_index=exponent_qubit_index,
        )
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'controls': self.controls,
            'control_values': self.control_values,
            'sub_operation': self.sub_operation,
        }

from __future__ import annotations
import abc
import itertools
from collections.abc import Collection, Iterator, Sequence
from functools import cached_property
from typing import Any, TYPE_CHECKING
from cirq import protocols, value
if TYPE_CHECKING:
    import cirq
@value.value_equality
class AbstractControlValues(abc.ABC):
    @abc.abstractmethod
    def validate(self, qid_shapes: Sequence[int]) -> None:
    @abc.abstractmethod
    def expand(self) -> SumOfProducts:
    @property
    @abc.abstractmethod
    def is_trivial(self) -> bool:
    @abc.abstractmethod
    def _num_qubits_(self) -> int:
    @abc.abstractmethod
    def _json_dict_(self) -> dict[str, Any]:
    @abc.abstractmethod
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
    @abc.abstractmethod
    def __iter__(self) -> Iterator[tuple[int, ...]]:
    def _value_equality_values_(self) -> Any:
        return tuple(v for v in self.expand())
    def __and__(self, other: AbstractControlValues) -> AbstractControlValues:
        return SumOfProducts(
            tuple(x + y for (x, y) in itertools.product(self.expand(), other.expand()))
        )
    def __or__(self, other: AbstractControlValues) -> AbstractControlValues:
        if protocols.num_qubits(self) != protocols.num_qubits(other):
            raise ValueError(
                f"Control values {self} and {other} must act on equal number of qubits"
            )
        return SumOfProducts((*self.expand(), *other.expand()))
class ProductOfSums(AbstractControlValues):
    def __init__(self, data: Sequence[int | Collection[int]]):
        self._qubit_sums: tuple[tuple[int, ...], ...] = tuple(
            (cv,) if isinstance(cv, int) else tuple(sorted(set(cv))) for cv in data
        )
    @cached_property
    def is_trivial(self) -> bool:
        return self._qubit_sums == ((1,),) * self._num_qubits_()
    def __iter__(self) -> Iterator[tuple[int, ...]]:
        return iter(self._qubit_sums)
    def expand(self) -> SumOfProducts:
        return SumOfProducts(tuple(itertools.product(*self._qubit_sums)))
    def __repr__(self) -> str:
        return f'cirq.ProductOfSums({str(self._qubit_sums)})'
    def _num_qubits_(self) -> int:
        return len(self._qubit_sums)
    def __getitem__(self, key: int | slice) -> ProductOfSums | tuple[int, ...]:
        if isinstance(key, slice):
            return ProductOfSums(self._qubit_sums[key])
        return self._qubit_sums[key]
    def validate(self, qid_shapes: Sequence[int]) -> None:
        for i, (vals, shape) in enumerate(zip(self._qubit_sums, qid_shapes)):
            if not all(0 <= v < shape for v in vals):
                message = (
                    f'Control values <{vals!r}> outside of range for control qubit '
                    f'number <{i}>.'
                )
                raise ValueError(message)
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        def get_symbol(vals):
            return '@' if tuple(vals) == (1,) else f"({','.join(map(str, vals))})"
        return protocols.CircuitDiagramInfo(wire_symbols=[get_symbol(t) for t in self._qubit_sums])
    def __str__(self) -> str:
        if self.is_trivial:
            return 'C' * self._num_qubits_()
        def get_prefix(control_vals):
            control_vals_str = ''.join(map(str, sorted(control_vals)))
            return f'C{control_vals_str}'
        return ''.join(get_prefix(t) for t in self._qubit_sums)
    def _json_dict_(self) -> dict[str, Any]:
        return {"data": self._qubit_sums}
    def __and__(self, other: AbstractControlValues) -> AbstractControlValues:
        if isinstance(other, ProductOfSums):
            return ProductOfSums(self._qubit_sums + other._qubit_sums)
        return super().__and__(other)
    def __or__(self, other: AbstractControlValues) -> AbstractControlValues:
        if protocols.num_qubits(self) != protocols.num_qubits(other):
            raise ValueError(
                f"Control values {self} and {other} must act on equal number of qubits"
            )
        if isinstance(other, ProductOfSums):
            return ProductOfSums(tuple(x + y for x, y in zip(self._qubit_sums, other._qubit_sums)))
        return super().__or__(other)
class SumOfProducts(AbstractControlValues):
    def __init__(self, data: Collection[Sequence[int]], *, name: str | None = None):
        self._conjunctions: tuple[tuple[int, ...], ...] = tuple(
            sorted(set(tuple(cv) for cv in data))
        )
        self._name = name
        if not len(self._conjunctions):
            raise ValueError("SumOfProducts can't be empty.")
        num_qubits = len(self._conjunctions[0])
        if not all(len(p) == num_qubits for p in self._conjunctions):
            raise ValueError(f'Each term of {self._conjunctions} should be of length {num_qubits}.')
    @cached_property
    def is_trivial(self) -> bool:
        return self._conjunctions == ((1,) * self._num_qubits_(),)
    def expand(self) -> SumOfProducts:
        return self
    def __iter__(self) -> Iterator[tuple[int, ...]]:
        return iter(self._conjunctions)
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        if self._name is not None:
            wire_symbols = ['@'] * self._num_qubits_()
            wire_symbols[-1] = f'@({self._name})'
            return protocols.CircuitDiagramInfo(wire_symbols=wire_symbols)
        if len(self._conjunctions) == 1:
            return protocols.CircuitDiagramInfo(  # pragma: no cover
                wire_symbols=["@" if x == 1 else f"({x})" for x in self._conjunctions[0]]
            )
        wire_symbols = [''] * self._num_qubits_()
        for term in self._conjunctions:
            for q_i, q_val in enumerate(term):
                wire_symbols[q_i] = wire_symbols[q_i] + str(q_val)
        wire_symbols = [f'@({s})' for s in wire_symbols]
        return protocols.CircuitDiagramInfo(wire_symbols=wire_symbols)
    def __repr__(self) -> str:
        name = '' if self._name is None else f', name="{self._name}"'
        return f'cirq.SumOfProducts({self._conjunctions!s} {name})'
    def __str__(self) -> str:
        suffix = (
            self._name
            if self._name is not None
            else '_'.join(''.join(str(v) for v in t) for t in self._conjunctions)
        )
        return f'C_{suffix}'
    def _num_qubits_(self) -> int:
        return len(self._conjunctions[0])
    def validate(self, qid_shapes: Sequence[int]) -> None:
        if len(qid_shapes) != self._num_qubits_():
            raise ValueError(
                f'Length of qid_shapes: {qid_shapes} should be equal to self._num_qubits_():'
                f' {self._num_qubits_()}'
            )
        for product in self._conjunctions:
            for q_i, q_val in enumerate(product):
                if not (0 <= q_val < qid_shapes[q_i]):
                    raise ValueError(
                        f'Control value <{q_val}> in combination {product} is outside'
                        f' of range [0, {qid_shapes[q_i]}) for control qubit number <{q_i}>.'
                    )
    def _json_dict_(self) -> dict[str, Any]:
        return {'data': self._conjunctions, 'name': self._name}

from __future__ import annotations
import abc
import numbers
from collections.abc import Callable, Iterable, Iterator, Sequence, Set
from types import NotImplementedType
from typing import Any, cast, overload, Self, TYPE_CHECKING
import numpy as np
import sympy
from cirq import linalg, protocols, value
from cirq._compat import proper_repr
from cirq.ops import global_phase_op, identity, pauli_gates, pauli_string, raw_types
if TYPE_CHECKING:
    import cirq
PAULI_CHARS = 'IXYZ'
PAULI_GATES: list[cirq.Pauli | cirq.IdentityGate] = [
    identity.I,
    pauli_gates.X,
    pauli_gates.Y,
    pauli_gates.Z,
]
@value.value_equality(approximate=True, distinct_child_types=True)
class BaseDensePauliString(raw_types.Gate, metaclass=abc.ABCMeta):
    I_VAL = 0
    X_VAL = 1
    Y_VAL = 2
    Z_VAL = 3
    def __init__(
        self,
        pauli_mask: Iterable[cirq.PAULI_GATE_LIKE] | np.ndarray,
        *,
        coefficient: cirq.TParamValComplex = 1,
    ):
        self._pauli_mask = _as_pauli_mask(pauli_mask)
        self._coefficient: complex | sympy.Expr = (
            coefficient if isinstance(coefficient, sympy.Expr) else complex(coefficient)
        )
        if type(self) != MutableDensePauliString:
            self._pauli_mask = np.copy(self.pauli_mask)
            self._pauli_mask.flags.writeable = False
    @property
    def pauli_mask(self) -> np.ndarray:
        return self._pauli_mask
    @property
    def coefficient(self) -> cirq.TParamValComplex:
        return self._coefficient
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, ['pauli_mask', 'coefficient'])
    def _value_equality_values_(self):
        return self.coefficient, tuple(PAULI_CHARS[p] for p in self.pauli_mask)
    @classmethod
    def one_hot(cls, *, index: int, length: int, pauli: cirq.PAULI_GATE_LIKE) -> Self:
        mask = np.zeros(length, dtype=np.uint8)
        mask[index] = _pauli_index(pauli)
        concrete_cls = cast(Callable, DensePauliString if cls is BaseDensePauliString else cls)
        return concrete_cls(pauli_mask=mask)
    @classmethod
    def eye(cls, length: int) -> Self:
        concrete_cls = cast(Callable, DensePauliString if cls is BaseDensePauliString else cls)
        return concrete_cls(pauli_mask=np.zeros(length, dtype=np.uint8))
    def _num_qubits_(self) -> int:
        return len(self)
    def _has_unitary_(self) -> bool:
        if self._is_parameterized_():
            return False
        return abs(1 - abs(cast(complex, self.coefficient))) < 1e-8
    def _unitary_(self) -> np.ndarray | NotImplementedType:
        if not self._has_unitary_():
            return NotImplemented
        return self.coefficient * linalg.kron(
            *[protocols.unitary(PAULI_GATES[p]) for p in self.pauli_mask]
        )
    def _apply_unitary_(self, args) -> np.ndarray | None | NotImplementedType:
        if not self._has_unitary_():
            return NotImplemented
        from cirq import devices
        qubits = devices.LineQubit.range(len(self))
        decomposed_ops = cast(Iterable['cirq.OP_TREE'], self._decompose_(qubits))
        return protocols.apply_unitaries(decomposed_ops, qubits, args)
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> NotImplementedType | cirq.OP_TREE:
        if not self._has_unitary_():
            return NotImplemented
        result = [PAULI_GATES[p].on(q) for p, q in zip(self.pauli_mask, qubits) if p]
        if self.coefficient != 1:
            result.append(global_phase_op.global_phase_operation(self.coefficient))
        return result
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self.coefficient)
    def _parameter_names_(self) -> Set[str]:
        return protocols.parameter_names(self.coefficient)
    def _resolve_parameters_(self, resolver: cirq.ParamResolver, recursive: bool) -> Self:
        return self.copy(
            coefficient=protocols.resolve_parameters(self.coefficient, resolver, recursive)
        )
    def __pos__(self):
        return self
    def __pow__(self, power: float) -> NotImplementedType | Self:
        concrete_class = type(self)
        if isinstance(power, int):
            i_group = [1, +1j, -1, -1j]
            coef = (
                i_group[i_group.index(cast(complex, self.coefficient)) * power % 4]
                if self.coefficient in i_group
                else self.coefficient**power
            )
            if power % 2 == 0:
                return concrete_class.eye(len(self)).__mul__(coef)
            return concrete_class(coefficient=coef, pauli_mask=self.pauli_mask)
        return NotImplemented
    @overload
    def __getitem__(self, item: int) -> cirq.Pauli | cirq.IdentityGate:
        pass
    @overload
    def __getitem__(self, item: slice) -> Self:
        pass
    def __getitem__(self, item):
        if isinstance(item, int):
            return PAULI_GATES[self.pauli_mask[item]]
        if isinstance(item, slice):
            return type(self)(coefficient=1, pauli_mask=self.pauli_mask[item])
        raise TypeError(f'indices must be integers or slices, not {type(item)}')
    def __iter__(self) -> Iterator[cirq.Pauli | cirq.IdentityGate]:
        for i in range(len(self)):
            yield self[i]
    def __len__(self) -> int:
        return len(self.pauli_mask)
    def __neg__(self):
        return type(self)(coefficient=-self.coefficient, pauli_mask=self.pauli_mask)
    def __truediv__(self, other):
        if isinstance(other, (sympy.Basic, numbers.Number)):
