class FSimGate(gate_features.InterchangeableQubitsGate, raw_types.Gate):
    r
    def __init__(self, theta: cirq.TParamVal, phi: cirq.TParamVal) -> None:
        self._theta = _canonicalize(theta)
        self._phi = _canonicalize(phi)
