def test_mul() -> None:
    class GateRMul(cirq.Gate):
        def num_qubits(self) -> int:
            return 1
        def _rmul_with_qubits(self, qubits, other):
            if other == 2:
                return 3
            if isinstance(other, cirq.Operation) and isinstance(other.gate, GateRMul):
                return 4
            raise NotImplementedError()
    class GateMul(cirq.Gate):
        def num_qubits(self) -> int:
            return 1
        def _mul_with_qubits(self, qubits, other):
            if other == 2:
                return 5
            if isinstance(other, cirq.Operation) and isinstance(other.gate, GateMul):
                return 6
            raise NotImplementedError()
    q = cirq.LineQubit(0)
    r = GateRMul().on(q)
    assert 2 * r == 3  # type: ignore[operator]
    with pytest.raises(TypeError):
        _ = r * 2  # type: ignore[operator]
    m = GateMul().on(q)
    assert m * 2 == 5  # type: ignore[operator]
    with pytest.raises(TypeError):
        _ = 2 * m  # type: ignore[operator]
    assert m * m == 6  # type: ignore[operator]
    assert r * r == 4  # type: ignore[operator]
