def test_gate_to_operation_to_gate_round_trips() -> None:
    def all_subclasses(cls):
        return set(cls.__subclasses__()).union(
            [s for c in cls.__subclasses__() for s in all_subclasses(c)]
        )
    gate_subclasses = {
        g
        for g in all_subclasses(cirq.Gate)
        if g.__module__.startswith("cirq.")
        and "contrib" not in g.__module__
        and "test" not in g.__module__
    }
    test_module_spec = cirq.testing.json.spec_for("cirq.protocols")
    skip_classes = {
        cirq.ArithmeticGate,
        cirq.BaseDensePauliString,
        cirq.EigenGate,
        cirq.Pauli,
        cirq.transformers.analytical_decompositions.two_qubit_to_fsim._BGate,
        cirq.transformers.measurement_transformers._ConfusionChannel,
        cirq.transformers.measurement_transformers._ModAdd,
        cirq.transformers.routing.visualize_routed_circuit._SwapPrintGate,
        cirq.circuits.qasm_output.QasmTwoQubitGate,
        cirq.ops.MSGate,
        cirq.interop.quirk.QuirkQubitPermutationGate,
        cirq.interop.quirk.QuirkArithmeticGate,
    }
    skipped = set()
    for gate_cls in gate_subclasses:
        filename = test_module_spec.test_data_path.joinpath(f"{gate_cls.__name__}.json")
        if pathlib.Path(filename).is_file():
            gates = cirq.read_json(filename)
        else:
            if gate_cls in skip_classes:
                skipped.add(gate_cls)
                continue
            raise AssertionError(  # pragma: no cover
                f"{gate_cls} has no json file, please add a json file or add to the list of "
                "classes to be skipped if there is a reason this gate should not round trip "
                "to a gate via creating an operation."
            )
        if not isinstance(gates, collections.abc.Iterable):
            gates = [gates]
        for gate in gates:
            if gate.num_qubits():
                qudits = [cirq.LineQid(i, d) for i, d in enumerate(cirq.qid_shape(gate))]
                assert gate.on(*qudits).gate == gate
    assert (
        skipped == skip_classes
    ), "A gate that was supposed to be skipped was not, please update the list of skipped gates."

from __future__ import annotations
from collections.abc import Collection, Sequence, Set
from types import NotImplementedType
from typing import Any, cast
import numpy as np
import sympy
import cirq
from cirq import protocols, value
from cirq._compat import proper_repr
from cirq.ops import control_values as cv, controlled_gate, raw_types
@value.value_equality(approximate=True)
class GlobalPhaseGate(raw_types.Gate):
    def __init__(self, coefficient: cirq.TParamValComplex, atol: float = 1e-8) -> None:
        if not isinstance(coefficient, sympy.Basic):
            if abs(1 - abs(coefficient)) > atol:
                raise ValueError(f'Coefficient is not unitary: {coefficient!r}')
        self._coefficient = coefficient
    @property
    def coefficient(self) -> cirq.TParamValComplex:
        return self._coefficient
    def _value_equality_values_(self) -> Any:
        return self.coefficient
    def _has_unitary_(self) -> bool:
        return not self._is_parameterized_()
    def __pow__(self, power) -> cirq.GlobalPhaseGate:
        if isinstance(power, (int, float)):
            return GlobalPhaseGate(self.coefficient**power)
        return NotImplemented
    def _unitary_(self) -> np.ndarray | NotImplementedType:
        if not self._has_unitary_():
            return NotImplemented
        return np.array([[self.coefficient]])
    def _apply_unitary_(self, args: cirq.ApplyUnitaryArgs) -> np.ndarray | NotImplementedType:
        if not self._has_unitary_():
            return NotImplemented
        assert not cirq.is_parameterized(self)
        args.target_tensor *= cast(np.generic, self.coefficient)
        return args.target_tensor
    def _has_stabilizer_effect_(self) -> bool:
        return True
    def __str__(self) -> str:
        return str(self.coefficient)
    def __repr__(self) -> str:
        return f'cirq.GlobalPhaseGate({proper_repr(self.coefficient)})'
    def _op_repr_(self, qubits: Sequence[cirq.Qid]) -> str:
        return f'cirq.global_phase_operation({proper_repr(self.coefficient)})'
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, ['coefficient'])
    def _qid_shape_(self) -> tuple[int, ...]:
        return tuple()
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self.coefficient)
    def _parameter_names_(self) -> Set[str]:
        return protocols.parameter_names(self.coefficient)
    def _resolve_parameters_(
        self, resolver: cirq.ParamResolver, recursive: bool
    ) -> cirq.GlobalPhaseGate:
        coefficient = protocols.resolve_parameters(self.coefficient, resolver, recursive)
        return GlobalPhaseGate(coefficient=coefficient)
    def is_identity(self) -> bool:
        return not protocols.is_parameterized(self._coefficient) and np.isclose(self.coefficient, 1)
    def controlled(
        self,
        num_controls: int | None = None,
        control_values: cv.AbstractControlValues | Sequence[int | Collection[int]] | None = None,
        control_qid_shape: tuple[int, ...] | None = None,
    ) -> raw_types.Gate:
        result = super().controlled(num_controls, control_values, control_qid_shape)
        if (
            not self._is_parameterized_()
            and isinstance(result, controlled_gate.ControlledGate)
            and isinstance(result.control_values, cv.ProductOfSums)
            and result.control_values[-1] == (1,)
            and result.control_qid_shape[-1] == 2
        ):
            coefficient = complex(self.coefficient)
            exponent = float(np.angle(coefficient) / np.pi)
            return cirq.ZPowGate(exponent=exponent).controlled(
                result.num_controls() - 1, result.control_values[:-1], result.control_qid_shape[:-1]
            )
        return result
def global_phase_operation(
    coefficient: cirq.TParamValComplex, atol: float = 1e-8
) -> cirq.GateOperation:
    return GlobalPhaseGate(coefficient, atol)()
def from_phase_and_exponent(
    half_turns: cirq.TParamVal, exponent: cirq.TParamVal
) -> cirq.GlobalPhaseGate:
    coefficient = 1j ** (2 * half_turns * exponent)
    coefficient = (
        complex(coefficient)
        if isinstance(coefficient, sympy.Expr) and coefficient.is_complex
        else coefficient
    )
    return GlobalPhaseGate(coefficient)

from __future__ import annotations
from collections.abc import Iterable
from typing import TYPE_CHECKING
from cirq.ops import named_qubit, qid_util, qubit_manager
if TYPE_CHECKING:
    import cirq
class GreedyQubitManager(qubit_manager.QubitManager):
    def __init__(self, prefix: str, *, size: int = 0, maximize_reuse: bool = False):
        self._prefix = prefix
        self._used_qubits: set[cirq.Qid] = set()
        self._free_qubits: list[cirq.Qid] = []
        self._size = 0
        self.maximize_reuse = maximize_reuse
        self.resize(size)
    def _allocate_qid(self, name: str, dim: int) -> cirq.Qid:
        return qid_util.q(name) if dim == 2 else named_qubit.NamedQid(name, dimension=dim)
    def resize(self, new_size: int, dim: int = 2) -> None:
        if new_size <= self._size:
            return
        new_qubits: list[cirq.Qid] = [
            self._allocate_qid(f'{self._prefix}_{s}', dim) for s in range(self._size, new_size)
        ]
        self._free_qubits = new_qubits + self._free_qubits
        self._size = new_size
    def qalloc(self, n: int, dim: int = 2) -> list[cirq.Qid]:
        if not n:
            return []
        self.resize(self._size + n - len(self._free_qubits), dim=dim)
        ret_qubits = self._free_qubits[-n:] if self.maximize_reuse else self._free_qubits[:n]
        self._free_qubits = self._free_qubits[:-n] if self.maximize_reuse else self._free_qubits[n:]
        self._used_qubits.update(ret_qubits)
        return ret_qubits
    def qfree(self, qubits: Iterable[cirq.Qid]) -> None:
        qs = list(dict(zip(qubits, qubits)).keys())
        assert self._used_qubits.issuperset(qs), "Only managed qubits currently in-use can be freed"
        self._used_qubits = self._used_qubits.difference(qs)
        self._free_qubits.extend(qs)
    def qborrow(self, n: int, dim: int = 2) -> list[cirq.Qid]:
        return self.qalloc(n, dim)

from __future__ import annotations
import numbers
from collections.abc import Sequence
from types import NotImplementedType
from typing import Any, TYPE_CHECKING
import numpy as np
import sympy
from cirq import protocols, value
from cirq._doc import document
from cirq.ops import raw_types
if TYPE_CHECKING:
    import cirq
@value.value_equality
class IdentityGate(raw_types.Gate):
    def __init__(
        self, num_qubits: int | None = None, qid_shape: tuple[int, ...] | None = None
    ) -> None:
        if qid_shape is None:
            if num_qubits is None:
                raise ValueError('Specify either the num_qubits or qid_shape argument.')
            qid_shape = (2,) * num_qubits
        elif num_qubits is None:
            num_qubits = len(qid_shape)
        self._qid_shape = qid_shape
        if len(self._qid_shape) != num_qubits:
            raise ValueError('len(qid_shape) != num_qubits')
    def _act_on_(self, sim_state: cirq.SimulationStateBase, qubits: Sequence[cirq.Qid]):
        return True
    def _qid_shape_(self) -> tuple[int, ...]:
        return self._qid_shape
    def num_qubits(self) -> int:
        return len(self._qid_shape)
    def __pow__(self, power: Any) -> Any:
        if isinstance(power, (numbers.Complex, sympy.Basic)):
            return self
        return NotImplemented
    def _commutes_(self, other: Any, *, atol: float = 1e-8) -> bool | NotImplementedType:
        if not isinstance(other, raw_types.Gate):
            return NotImplemented
        return True
    def _has_unitary_(self) -> bool:
        return True
    def _unitary_(self) -> np.ndarray:
        return np.identity(np.prod(self._qid_shape, dtype=np.int64).item())
    def _apply_unitary_(self, args: protocols.ApplyUnitaryArgs) -> np.ndarray | None:
        return args.target_tensor
    def _pauli_expansion_(self) -> value.LinearDict[str]:
        if not all(d == 2 for d in self._qid_shape):
            return NotImplemented
        return value.LinearDict({'I' * self.num_qubits(): 1.0})
    def __repr__(self) -> str:
        if self._qid_shape == (2,):
            return 'cirq.I'
        if all(e == 2 for e in self._qid_shape):
            return f'cirq.IdentityGate({len(self._qid_shape)})'
        return f'cirq.IdentityGate(qid_shape={self._qid_shape!r})'
    def _decompose_(self, qubits) -> cirq.OP_TREE:
        return []
    def __str__(self) -> str:
        if self.num_qubits() == 1:
            return 'I'
        return f'I({self.num_qubits()})'
    def _value_equality_values_(self) -> Any:
        return self._qid_shape
    def _trace_distance_bound_(self) -> float:
        return 0.0
    def _json_dict_(self) -> dict[str, Any]:
        other = {}
        if not all(d == 2 for d in self._qid_shape):
            other['qid_shape'] = self._qid_shape
        return {'num_qubits': len(self._qid_shape), **other}
    def _mul_with_qubits(self, qubits: tuple[cirq.Qid, ...], other):
        if isinstance(other, raw_types.Operation):
            return other
        if isinstance(other, numbers.Complex):
            from cirq.ops.pauli_string import PauliString
            return PauliString(coefficient=other)
        return NotImplemented
    _rmul_with_qubits = _mul_with_qubits
    def _circuit_diagram_info_(self, args) -> tuple[str, ...]:
        if self.num_qubits() <= 0:
            return NotImplemented
        return ('I',) * self.num_qubits()
    def _qasm_(self, args: cirq.QasmArgs, qubits: tuple[cirq.Qid, ...]) -> str | None:
        args.validate_version('2.0', '3.0')
        return ''.join([args.format('id {0};\n', qubit) for qubit in qubits])
    @classmethod
    def _from_json_dict_(cls, num_qubits, qid_shape=None, **kwargs):
        return cls(num_qubits=num_qubits, qid_shape=None if qid_shape is None else tuple(qid_shape))
I = IdentityGate(num_qubits=1)
document(
    I,
    ,
)
def identity_each(*qubits: cirq.Qid) -> cirq.Operation:
    for qubit in qubits:
        if not isinstance(qubit, raw_types.Qid):
            raise ValueError(f'Not a cirq.Qid: {qubit!r}.')
    return IdentityGate(qid_shape=protocols.qid_shape(qubits)).on(*qubits)

from __future__ import annotations
from collections.abc import Iterable, Mapping
from typing import Any, TYPE_CHECKING
import numpy as np
from cirq import linalg, protocols, value
from cirq._compat import proper_repr
from cirq.ops import raw_types
if TYPE_CHECKING:
    import cirq
class KrausChannel(raw_types.Gate):
    def __init__(
        self,
        kraus_ops: Iterable[np.ndarray],
        key: str | cirq.MeasurementKey | None = None,
        validate: bool = False,
    ):
        kraus_ops = list(kraus_ops)
        if not kraus_ops:
            raise ValueError('KrausChannel must have at least one operation.')
        num_qubits = np.log2(kraus_ops[0].shape[0])
        if not num_qubits.is_integer() or kraus_ops[0].shape[1] != kraus_ops[0].shape[0]:
            raise ValueError(
                f'Input Kraus ops of shape {kraus_ops[0].shape} does not '
                'represent a square operator over qubits.'
            )
        self._num_qubits = int(num_qubits)
        for i, op in enumerate(kraus_ops):
            if not op.shape == kraus_ops[0].shape:
                raise ValueError(
                    'Inconsistent Kraus operator shapes: '
                    f'op[0]: {kraus_ops[0].shape}, op[{i}]: {op.shape}'
                )
