        qs = {q for k in self._linear_dict.keys() for q, _ in k}
        return tuple(sorted(qs))
    def _json_dict_(self) -> dict[str, Any]:
        linear_dict = []
        for projector_dict, scalar in dict(self._linear_dict).items():
            key = [[k, v] for k, v in dict(projector_dict).items()]
            linear_dict.append([key, scalar])
        return {'linear_dict': linear_dict}
    @classmethod
    def _from_json_dict_(cls, linear_dict, **kwargs):
        converted_dict = {}
        for projector_string in linear_dict:
            projector_dict = {x[0]: x[1] for x in projector_string[0]}
            scalar = projector_string[1]
            key = frozenset(projector_dict.items())
            converted_dict[key] = scalar
        return cls(linear_dict=value.LinearDict(converted_dict))
    @classmethod
    def from_projector_strings(cls, terms: ProjectorString | list[ProjectorString]) -> ProjectorSum:
        if isinstance(terms, ProjectorString):
            terms = [terms]
        termdict: defaultdict[frozenset[tuple[raw_types.Qid, int]], value.Scalar] = defaultdict(
            lambda: 0.0
        )
        for pstring in terms:
            key = frozenset(pstring.projector_dict.items())
            termdict[key] += pstring.coefficient
        return cls(linear_dict=value.LinearDict(termdict))
    def copy(self) -> ProjectorSum:
        return ProjectorSum(self._linear_dict.copy())
    def matrix(self, projector_qids: Iterable[raw_types.Qid] | None = None) -> csr_matrix:
        return sum(
            coeff * _projector_string_from_projector_dict(vec).matrix(projector_qids)
            for vec, coeff in self._linear_dict.items()
        )
    def expectation_from_state_vector(
        self, state_vector: np.ndarray, qid_map: Mapping[raw_types.Qid, int]
    ) -> float:
        return sum(
            coeff
            * _projector_string_from_projector_dict(vec).expectation_from_state_vector(
                state_vector, qid_map
            )
            for vec, coeff in self._linear_dict.items()
        )
    def expectation_from_density_matrix(
        self, state: np.ndarray, qid_map: Mapping[raw_types.Qid, int]
    ) -> float:
        return sum(
            coeff
            * _projector_string_from_projector_dict(vec).expectation_from_density_matrix(
                state, qid_map
            )
            for vec, coeff in self._linear_dict.items()
        )
    def __iter__(self):
        for vec, coeff in self._linear_dict.items():
            yield _projector_string_from_projector_dict(vec, coeff)
    def __len__(self) -> int:
        return len(self._linear_dict)
    def __truediv__(self, a: value.Scalar):
        return self.__mul__(1 / a)
    def __bool__(self) -> bool:
        return bool(self._linear_dict)
    def __iadd__(self, other: ProjectorString | ProjectorSum):
        if isinstance(other, ProjectorString):
            other = ProjectorSum.from_projector_strings(other)
        elif not isinstance(other, ProjectorSum):
            return NotImplemented
        self._linear_dict += other._linear_dict
        return self
    def __add__(self, other: ProjectorString | ProjectorSum):
        if isinstance(other, ProjectorString):
            other = ProjectorSum.from_projector_strings(other)
        elif not isinstance(other, ProjectorSum):
            return NotImplemented
        result = self.copy()
        result += other
        return result
    def __isub__(self, other: ProjectorString | ProjectorSum):
        if isinstance(other, ProjectorString):
            other = ProjectorSum.from_projector_strings(other)
        elif not isinstance(other, ProjectorSum):
            return NotImplemented
        self._linear_dict -= other._linear_dict
        return self
    def __sub__(self, other: ProjectorString | ProjectorSum):
        if isinstance(other, ProjectorString):
            other = ProjectorSum.from_projector_strings(other)
        elif not isinstance(other, ProjectorSum):
            return NotImplemented
        result = self.copy()
        result -= other
        return result
    def __neg__(self):
        factory = type(self)
        return factory(-self._linear_dict)
    def __imul__(self, other: value.Scalar):
        if not isinstance(other, numbers.Complex):
            return NotImplemented
        self._linear_dict *= other
        return self
    def __mul__(self, other: value.Scalar):
        if not isinstance(other, numbers.Complex):
            return NotImplemented
        result = self.copy()
        result *= other
        return result
    def __rmul__(self, other: value.Scalar):
        if not isinstance(other, numbers.Complex):
            return NotImplemented
        result = self.copy()
        result *= other
        return result

from __future__ import annotations
from collections.abc import Iterable
from typing import Any, TYPE_CHECKING
import numpy as np
from cirq import _import, linalg, protocols
from cirq._compat import proper_repr
from cirq.ops import global_phase_op, phased_x_z_gate, raw_types
if TYPE_CHECKING:
    import cirq
single_qubit_decompositions = _import.LazyLoader(
    'single_qubit_decompositions', globals(), 'cirq.transformers.analytical_decompositions'
)
two_qubit_to_cz = _import.LazyLoader(
    'two_qubit_to_cz', globals(), 'cirq.transformers.analytical_decompositions'
)
three_qubit_decomposition = _import.LazyLoader(
    'three_qubit_decomposition', globals(), 'cirq.transformers.analytical_decompositions'
)
class MatrixGate(raw_types.Gate):
    r
    def __init__(
        self,
        matrix: np.ndarray,
        *,
        name: str | None = None,
        qid_shape: Iterable[int] | None = None,
        unitary_check: bool = True,
        unitary_check_rtol: float = 1e-5,
        unitary_check_atol: float = 1e-8,
    ) -> None:
        if len(matrix.shape) != 2 or matrix.shape[0] != matrix.shape[1]:
            raise ValueError('`matrix` must be a square 2d numpy array.')
        if qid_shape is None:
            n = int(np.round(np.log2(matrix.shape[0] or 1)))
            if 2**n != matrix.shape[0]:
                raise ValueError(
                    f'Matrix width ({matrix.shape[0]}) is not a power of 2 and '
                    f'qid_shape is not specified.'
                )
            qid_shape = (2,) * n
        self._matrix = matrix
        self._qid_shape = tuple(qid_shape)
        self._name = name
        m = int(np.prod(self._qid_shape, dtype=np.int64))
        if self._matrix.shape != (m, m):
            raise ValueError(
                'Wrong matrix shape for qid_shape.\n'
                f'Matrix shape: {self._matrix.shape}\n'
                f'qid_shape: {self._qid_shape}\n'
            )
        if unitary_check and not linalg.is_unitary(
            matrix, rtol=unitary_check_rtol, atol=unitary_check_atol
        ):
            raise ValueError(f'Not a unitary matrix: {matrix}')
    def with_name(self, name: str) -> MatrixGate:
        return MatrixGate(self._matrix, name=name, qid_shape=self._qid_shape, unitary_check=False)
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'matrix': self._matrix.tolist(),
            'qid_shape': self._qid_shape,
            **({'name': self._name} if self._name is not None else {}),
        }
    @classmethod
    def _from_json_dict_(cls, matrix, qid_shape, name=None, **kwargs):
        return cls(matrix=np.array(matrix), qid_shape=qid_shape, name=name)
    def _qid_shape_(self) -> tuple[int, ...]:
        return self._qid_shape
    def __pow__(self, exponent: Any) -> MatrixGate:
        if not isinstance(exponent, (int, float)):
            return NotImplemented
        new_mat = linalg.map_eigenvalues(self._matrix, lambda b: b**exponent)
        return MatrixGate(new_mat, qid_shape=self._qid_shape)
    def _phase_by_(self, phase_turns: float, qubit_index: int) -> MatrixGate:
        if not isinstance(phase_turns, (int, float)):
            return NotImplemented
        if self._qid_shape[qubit_index] != 2:
            return NotImplemented
        result = np.copy(self._matrix).reshape(self._qid_shape * 2)
        p = np.exp(2j * np.pi * phase_turns)
        i = qubit_index
        j = qubit_index + len(self._qid_shape)
        result[linalg.slice_for_qubits_equal_to([i], 1)] *= p
        result[linalg.slice_for_qubits_equal_to([j], 1)] *= np.conj(p)
        return MatrixGate(matrix=result.reshape(self._matrix.shape), qid_shape=self._qid_shape)
    def _decompose_(self, qubits: tuple[cirq.Qid, ...]) -> cirq.OP_TREE:
        from cirq.circuits import Circuit
        decomposed: list[cirq.Operation] = NotImplemented
        if self._qid_shape == (2,):
            decomposed = [
                g.on(qubits[0])
                for g in single_qubit_decompositions.single_qubit_matrix_to_gates(self._matrix)
            ]
        if self._qid_shape == (2,) * 2:
            decomposed = two_qubit_to_cz.two_qubit_matrix_to_cz_operations(
                *qubits, self._matrix, allow_partial_czs=True
            )
        if self._qid_shape == (2,) * 3:
            decomposed = three_qubit_decomposition.three_qubit_matrix_to_operations(
                *qubits, self._matrix
            )
        if decomposed is NotImplemented:
            return NotImplemented
        circuit = Circuit(*decomposed)
        u = circuit.unitary(qubit_order=qubits, qubits_that_should_be_present=qubits)
        phase_delta = linalg.phase_delta(u, self._matrix)
        if phase_delta.real < 1:
            decomposed.append(global_phase_op.global_phase_operation(phase_delta))
        return decomposed
    def _has_unitary_(self) -> bool:
        return True
    def _unitary_(self) -> np.ndarray:
        return np.copy(self._matrix)
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        n_qubits = len(self._qid_shape)
        if n_qubits == 0:
            return NotImplemented
        if self._name is not None:
            symbols = (
                [self._name] if n_qubits == 1 else [f'{self._name}[{i+1}]' for i in range(n_qubits)]
            )
            return protocols.CircuitDiagramInfo(wire_symbols=symbols)
        main = _matrix_to_diagram_symbol(self._matrix, args)
        rest = [f'#{i+1}' for i in range(1, n_qubits)]
        return protocols.CircuitDiagramInfo(wire_symbols=[main, *rest])
    def _qasm_(self, args: cirq.QasmArgs, qubits: tuple[cirq.Qid, ...]) -> str | None:
        args.validate_version('2.0', '3.0')
        if self._qid_shape == (2,):
            return protocols.qasm(
                phased_x_z_gate.PhasedXZGate.from_matrix(self._matrix), args=args, qubits=qubits
            )
        return None
    def __hash__(self) -> int:
        vals = tuple(v for _, v in np.ndenumerate(self._matrix))
        return hash((MatrixGate, vals))
    def _approx_eq_(self, other: Any, atol) -> bool:
        if not isinstance(other, type(self)):
            return NotImplemented
        return np.allclose(self._matrix, other._matrix, rtol=0, atol=atol)
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented
        return self._qid_shape == other._qid_shape and np.array_equal(self._matrix, other._matrix)
    def __ne__(self, other):
        return not self == other
    def __repr__(self) -> str:
        if all(e == 2 for e in self._qid_shape):
            return f'cirq.MatrixGate({proper_repr(self._matrix)})'
        return f'cirq.MatrixGate({proper_repr(self._matrix)}, qid_shape={self._qid_shape})'
    def __str__(self) -> str:
        return str(self._matrix.round(3))
def _matrix_to_diagram_symbol(matrix: np.ndarray, args: protocols.CircuitDiagramInfoArgs) -> str:
    if args.precision is not None:
        matrix = matrix.round(args.precision)
    result = str(matrix)
    if args.use_unicode_characters:
        lines = result.split('\n')
        for i in range(len(lines)):
            lines[i] = lines[i].replace('[[', '')
            lines[i] = lines[i].replace(' [', '')
            lines[i] = lines[i].replace(']', '')
        w = max(len(line) for line in lines)
        for i in range(len(lines)):
            lines[i] = '│' + lines[i].ljust(w) + '│'
        lines.insert(0, '┌' + ' ' * w + '┐')
        lines.append('└' + ' ' * w + '┘')
        result = '\n'.join(lines)
    return result

from __future__ import annotations
from collections.abc import Iterable, Mapping, Sequence
from typing import Any, TYPE_CHECKING
import numpy as np
from cirq import _compat, protocols, value
from cirq.ops import raw_types
if TYPE_CHECKING:
    import cirq
@value.value_equality
class MeasurementGate(raw_types.Gate):
    def __init__(
        self,
        num_qubits: int | None = None,
        key: str | cirq.MeasurementKey = '',
        invert_mask: tuple[bool, ...] = (),
        qid_shape: tuple[int, ...] | None = None,
        confusion_map: dict[tuple[int, ...], np.ndarray] | None = None,
    ) -> None:
        if qid_shape is None:
            if num_qubits is None:
                raise ValueError('Specify either the num_qubits or qid_shape argument.')
            qid_shape = (2,) * num_qubits
        elif num_qubits is None:
            num_qubits = len(qid_shape)
        if num_qubits == 0:
            raise ValueError('Measuring an empty set of qubits.')
        self._qid_shape = qid_shape
        if len(self._qid_shape) != num_qubits:
            raise ValueError('len(qid_shape) != num_qubits')
        self._mkey = (
            key if isinstance(key, value.MeasurementKey) else value.MeasurementKey(name=key)
        )
        self._invert_mask = invert_mask or ()
        if self.invert_mask is not None and len(self.invert_mask) > self.num_qubits():
            raise ValueError('len(invert_mask) > num_qubits')
        self._confusion_map = confusion_map or {}
        if any(x >= self.num_qubits() for idx in self._confusion_map for x in idx):
            raise ValueError('Confusion matrices have index out of bounds.')
    @property
    def key(self) -> str:
        return str(self.mkey)
    @property
    def mkey(self) -> cirq.MeasurementKey:
        return self._mkey
    @property
    def invert_mask(self) -> tuple[bool, ...]:
        return self._invert_mask
    @property
    def confusion_map(self) -> dict[tuple[int, ...], np.ndarray]:
        return self._confusion_map
    def _qid_shape_(self) -> tuple[int, ...]:
        return self._qid_shape
    def _has_unitary_(self) -> bool:
        return False
    def with_key(self, key: str | cirq.MeasurementKey) -> MeasurementGate:
        if key == self.key:
            return self
        return MeasurementGate(
            self.num_qubits(),
            key=key,
            invert_mask=self.invert_mask,
            qid_shape=self._qid_shape,
            confusion_map=self.confusion_map,
        )
    def _with_key_path_(self, path: tuple[str, ...]):
        return self.with_key(self.mkey._with_key_path_(path))
    def _with_key_path_prefix_(self, prefix: tuple[str, ...]):
        return self.with_key(self.mkey._with_key_path_prefix_(prefix))
    def _with_rescoped_keys_(
        self, path: tuple[str, ...], bindable_keys: frozenset[cirq.MeasurementKey]
    ):
        return self.with_key(protocols.with_rescoped_keys(self.mkey, path, bindable_keys))
    def _with_measurement_key_mapping_(self, key_map: Mapping[str, str]):
        return self.with_key(protocols.with_measurement_key_mapping(self.mkey, key_map))
    def with_bits_flipped(self, *bit_positions: int) -> MeasurementGate:
        old_mask = self.invert_mask or ()
        n = max(len(old_mask) - 1, *bit_positions) + 1
        new_mask = [k < len(old_mask) and old_mask[k] for k in range(n)]
        for b in bit_positions:
            new_mask[b] = not new_mask[b]
        return MeasurementGate(
            self.num_qubits(),
            key=self.key,
            invert_mask=tuple(new_mask),
            qid_shape=self._qid_shape,
            confusion_map=self.confusion_map,
        )
    def full_invert_mask(self) -> tuple[bool, ...]:
        mask = self.invert_mask or self.num_qubits() * (False,)
        deficit = self.num_qubits() - len(mask)
        mask += (False,) * deficit
        return mask
    def _is_measurement_(self) -> bool:
        return True
    def _measurement_key_name_(self) -> str:
        return self.key
    def _measurement_key_obj_(self) -> cirq.MeasurementKey:
        return self.mkey
    def _kraus_(self):
        size = np.prod(self._qid_shape, dtype=np.int64)
        def delta(i):
            result = np.zeros((size, size))
            result[i][i] = 1
            return result
        return tuple(delta(i) for i in range(size))
    def _has_kraus_(self):
        return True
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        symbols = ['M'] * self.num_qubits()
        flipped_indices = {i for i, x in enumerate(self.full_invert_mask()) if x}
        confused_indices = {x for idxs in self.confusion_map for x in idxs}
        for i in range(self.num_qubits()):
            prefix = ''
            if i in flipped_indices:
                prefix += '!'
            if i in confused_indices:
                prefix += '?'
            symbols[i] = prefix + symbols[i]
        label_map = args.label_map or {}
        if not args.known_qubits or self.key != _default_measurement_key(args.known_qubits):
            if self.key not in label_map:
                symbols[0] += f"('{self.key}')"
        if self.key in label_map:
            symbols += '@'
        return protocols.CircuitDiagramInfo(symbols)
    def _qasm_(self, args: cirq.QasmArgs, qubits: tuple[cirq.Qid, ...]) -> str | None:
        if self.confusion_map or not all(d == 2 for d in self._qid_shape):
            return NotImplemented
        args.validate_version('2.0', '3.0')
        invert_mask = self.invert_mask
        if len(invert_mask) < len(qubits):
            invert_mask = invert_mask + (False,) * (len(qubits) - len(invert_mask))
        lines = []
        for i, (qubit, inv) in enumerate(zip(qubits, invert_mask)):
            if inv:
                lines.append(args.format('x {0};  // Invert the following measurement\n', qubit))
            if args.version == '2.0':
                lines.append(args.format('measure {0} -> {1:meas}[{2}];\n', qubit, self.key, i))
            else:
                lines.append(args.format('{1:meas}[{2}] = measure {0};\n', qubit, self.key, i))
            if inv:
                lines.append(args.format('x {0};  // Undo the inversion\n', qubit))
        return ''.join(lines)
    def _op_repr_(self, qubits: Sequence[cirq.Qid]) -> str:
        args = list(repr(q) for q in qubits)
        if self.key != _default_measurement_key(qubits):
            args.append(f'key={self.mkey!r}')
        if self.invert_mask:
            args.append(f'invert_mask={self.invert_mask!r}')
        if self.confusion_map:
            proper_map_str = ', '.join(
                f"{k!r}: {_compat.proper_repr(v)}" for k, v in self.confusion_map.items()
            )
            args.append(f'confusion_map={{{proper_map_str}}}')
        arg_list = ', '.join(args)
        return f'cirq.measure({arg_list})'
    def __repr__(self):
        args = [f'{self.num_qubits()!r}', f'{self.mkey!r}', f'{self.invert_mask}']
        if any(d != 2 for d in self._qid_shape):
            args.append(f'qid_shape={self._qid_shape!r}')
        if self.confusion_map:
            proper_map_str = ', '.join(
                f"{k!r}: {_compat.proper_repr(v)}" for k, v in self.confusion_map.items()
            )
            args.append(f'confusion_map={{{proper_map_str}}}')
        return f'cirq.MeasurementGate({", ".join(args)})'
    def _value_equality_values_(self) -> Any:
        hashable_cmap = frozenset(
            (idxs, tuple(v for _, v in np.ndenumerate(cmap)))
            for idxs, cmap in self._confusion_map.items()
        )
        return self.key, self.full_invert_mask(), self._qid_shape, hashable_cmap
    def _json_dict_(self) -> dict[str, Any]:
        other: dict[str, Any] = {}
        if not all(d == 2 for d in self._qid_shape):
            other['qid_shape'] = self._qid_shape
        if self.confusion_map:
            json_cmap = [(k, v.tolist()) for k, v in self.confusion_map.items()]
            other['confusion_map'] = json_cmap
        return {
            'num_qubits': len(self._qid_shape),
            'key': self.key,
            'invert_mask': self.invert_mask,
            **other,
        }
    @classmethod
    def _from_json_dict_(
        cls, num_qubits, key, invert_mask, qid_shape=None, confusion_map=None, **kwargs
    ):
        return cls(
            num_qubits=num_qubits,
            key=value.MeasurementKey.parse_serialized(key),
            invert_mask=tuple(invert_mask),
            qid_shape=None if qid_shape is None else tuple(qid_shape),
            confusion_map={tuple(k): np.array(v) for k, v in confusion_map or []},
        )
    def _has_stabilizer_effect_(self) -> bool | None:
        return True
    def _act_on_(self, sim_state: cirq.SimulationStateBase, qubits: Sequence[cirq.Qid]) -> bool:
        from cirq.sim import SimulationState
        if not isinstance(sim_state, SimulationState):
            return NotImplemented
        sim_state.measure(qubits, self.key, self.full_invert_mask(), self.confusion_map)
        return True
def _default_measurement_key(qubits: Iterable[raw_types.Qid]) -> str:
    return ','.join(str(q) for q in qubits)

