        base = (
            f'cirq.PauliInteractionGate({self.pauli0!r}, {self.invert0!s}, '
            f'{self.pauli1!r}, {self.invert1!s})'
        )
        if self._exponent == 1:
            return base
        return f'({base}**{proper_repr(self._exponent)})'
