        common_gates.XPowGate: pauli_gates.X,
        common_gates.YPowGate: pauli_gates.Y,
        common_gates.ZPowGate: pauli_gates.Z,
    }
    if (pauli := cached_gates.get(type(op.gate))) is not None:
        exponent = op.gate.exponent  # type: ignore
