from __future__ import annotations
from collections.abc import Iterator, Sequence
from typing import Any, TYPE_CHECKING
from cirq import protocols, value
from cirq.ops import raw_types, swap_gates
if TYPE_CHECKING:
    import cirq
@value.value_equality
class QubitPermutationGate(raw_types.Gate):
    r
    def __init__(self, permutation: Sequence[int]):
        if not permutation:
            raise ValueError(f"Invalid permutation (empty): {permutation}")
        if len(set(permutation)) < len(permutation):
            raise ValueError(f"Invalid permutation {permutation} Each index must appear only once.")
        invalid_indices = [x for x in permutation if not 0 <= x < len(permutation)]
        if len(invalid_indices) > 0:
            raise ValueError(
                f"All indices have to satisfy 0 <= i < {len(permutation)}.\n"
                f"Invalid indices: {invalid_indices}"
            )
        self._permutation = tuple(permutation)
    @property
    def permutation(self) -> tuple[int, ...]:
        return self._permutation
    def _value_equality_values_(self):
        return self.permutation
    def num_qubits(self) -> int:
        return len(self.permutation)
    def _has_unitary_(self):
        return True
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        permutation = [p for p in self.permutation]
        for i in range(len(permutation)):
            if permutation[i] == -1:
                continue
            cycle = [i]
            while permutation[cycle[-1]] != i:
                cycle.append(permutation[cycle[-1]])
            for j in cycle:
                permutation[j] = -1
            for idx in cycle[1:]:
                yield swap_gates.SWAP(qubits[cycle[0]], qubits[idx])
    def _apply_unitary_(self, args: cirq.ApplyUnitaryArgs):
        permuted_axes = list(range(len(args.target_tensor.shape)))
        for i in range(len(args.axes)):
            j = self.permutation[i]
            ai = args.axes[i]
            aj = args.axes[j]
            assert args.target_tensor.shape[ai] == args.target_tensor.shape[aj]
            permuted_axes[aj] = ai
        args.available_buffer[...] = args.target_tensor.transpose(permuted_axes)
        return args.available_buffer
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> tuple[str, ...]:
        return tuple(f'[{i}>{self.permutation[i]}]' for i in range(len(self.permutation)))
    def __repr__(self) -> str:
        return f'cirq.QubitPermutationGate(permutation={self.permutation!r})'
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, attribute_names=['permutation'])
    @classmethod
    def _from_json_dict_(cls, permutation: Sequence[int], **kwargs):
        return cls(permutation)

from __future__ import annotations
from collections.abc import Iterator, Sequence, Set
from typing import Any, cast
import numpy as np
import sympy
import cirq
from cirq import linalg, protocols, value
from cirq._compat import proper_repr
from cirq.ops import eigen_gate, swap_gates
@value.value_equality(manual_cls=True)
class PhasedISwapPowGate(eigen_gate.EigenGate):
    r
    def __init__(
        self,
        *,
        phase_exponent: float | sympy.Expr = 0.25,
        exponent: float | sympy.Expr = 1.0,
        global_shift: float = 0.0,
    ):
        self._phase_exponent = value.canonicalize_half_turns(phase_exponent)
        self._iswap = swap_gates.ISwapPowGate(exponent=exponent, global_shift=global_shift)
        super().__init__(exponent=exponent, global_shift=global_shift)
    @property
    def phase_exponent(self) -> float | sympy.Expr:
        return self._phase_exponent
    def _num_qubits_(self) -> int:
        return 2
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'phase_exponent': self._phase_exponent,
            'exponent': self._exponent,
            'global_shift': self._global_shift,
        }
    def _value_equality_values_cls_(self):
        return PhasedISwapPowGate
    def _value_equality_values_(self):
        return (self.phase_exponent, *self._iswap._value_equality_values_())
    def _value_equality_approximate_values_(self):
        return (self.phase_exponent, *self._iswap._value_equality_approximate_values_())
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self._iswap) or protocols.is_parameterized(
            self._phase_exponent
        )
    def _parameter_names_(self) -> Set[str]:
        return protocols.parameter_names(self._iswap) | protocols.parameter_names(
            self._phase_exponent
        )
    def _resolve_parameters_(
        self, resolver: cirq.ParamResolver, recursive: bool
    ) -> PhasedISwapPowGate:
        return self.__class__(
            phase_exponent=protocols.resolve_parameters(self.phase_exponent, resolver, recursive),
            exponent=protocols.resolve_parameters(self.exponent, resolver, recursive),
        )
    def _with_exponent(self, exponent: value.type_alias.TParamVal) -> PhasedISwapPowGate:
        return PhasedISwapPowGate(
            phase_exponent=self.phase_exponent, exponent=exponent, global_shift=self.global_shift
        )
    def _eigen_shifts(self) -> list[float]:
        return [0.0, +0.5, -0.5]
    def _eigen_components(self) -> list[tuple[float, np.ndarray]]:
        phase = np.exp(1j * np.pi * self.phase_exponent)
        phase_matrix = np.diag([1, phase, phase.conjugate(), 1])
        inverse_phase_matrix = np.conjugate(phase_matrix)
        eigen_components: list[tuple[float, np.ndarray]] = []
        for eigenvalue, projector in self._iswap._eigen_components():
            new_projector = phase_matrix @ projector @ inverse_phase_matrix
            eigen_components.append((eigenvalue, new_projector))
        return eigen_components
    def _apply_unitary_(self, args: protocols.ApplyUnitaryArgs) -> np.ndarray | None:
        if protocols.is_parameterized(self):
            return NotImplemented
        c = np.cos(np.pi * self._exponent / 2)
        s = np.sin(np.pi * self._exponent / 2)
        f = np.exp(2j * np.pi * self._phase_exponent)
        matrix = np.array([[c, 1j * s * f], [1j * s * f.conjugate(), c]])
        p = 1j ** (2 * self._exponent * self._global_shift)
        if p != 1:
            args.target_tensor *= p
        zo = args.subspace_index(0b01)
        oz = args.subspace_index(0b10)
        linalg.apply_matrix_to_slices(
            args.target_tensor, matrix, [oz, zo], out=args.available_buffer
        )
        return args.available_buffer
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        if len(qubits) != 2:
            raise ValueError(f'Expected two qubits, got {len(qubits)}')
        a, b = qubits
        yield cirq.Z(a) ** self.phase_exponent
        yield cirq.Z(b) ** -self.phase_exponent
        yield cirq.ISwapPowGate(exponent=self.exponent, global_shift=self.global_shift).on(a, b)
        yield cirq.Z(a) ** -self.phase_exponent
        yield cirq.Z(b) ** self.phase_exponent
    def _pauli_expansion_(self) -> value.LinearDict[str]:
        if self._is_parameterized_():
            return NotImplemented
        expansion = protocols.pauli_expansion(self._iswap)
        assert set(expansion.keys()).issubset({'II', 'XX', 'YY', 'ZZ'})
        assert np.isclose(cast(np.generic, expansion['XX']), cast(np.generic, expansion['YY']))
        v = (expansion['XX'] + expansion['YY']) / 2
        phase_angle = np.pi * self.phase_exponent
        c, s = np.cos(2 * phase_angle), np.sin(2 * phase_angle)
        return value.LinearDict(
            {
                'II': expansion['II'],
                'XX': c * v,
                'YY': c * v,
                'XY': s * v,
                'YX': -s * v,
                'ZZ': expansion['ZZ'],
            }
        )
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        s = f'PhISwap({args.format_real(self._phase_exponent)})'
        return protocols.CircuitDiagramInfo(
            wire_symbols=(s, s), exponent=self._diagram_exponent(args)
        )
    def __str__(self) -> str:
        if self._global_shift == 0:
            if self.exponent == 1:
                return 'PhasedISWAP'
            return f'PhasedISWAP**{self.exponent}'
        return f'PhasedISWAP(exponent={self._exponent}, global_shift={self._global_shift!r})'
    def __repr__(self) -> str:
        phase_exponent = proper_repr(self._phase_exponent)
        args = [f'phase_exponent={phase_exponent}']
        if self.exponent != 1:
            exponent = proper_repr(self.exponent)
            args.append(f'exponent={exponent}')
        if self._global_shift != 0:
            args.append(f'global_shift={self._global_shift}')
        arg_string = ', '.join(args)
        return f'cirq.PhasedISwapPowGate({arg_string})'
def givens(angle_rads: value.TParamVal) -> PhasedISwapPowGate:
    pi = sympy.pi if protocols.is_parameterized(angle_rads) else np.pi
    return cast(PhasedISwapPowGate, PhasedISwapPowGate() ** (2 * angle_rads / pi))

from __future__ import annotations
import math
import numbers
from collections.abc import Sequence, Set
from types import NotImplementedType
from typing import Any, cast
import numpy as np
import sympy
import cirq
from cirq import protocols, value
from cirq._compat import proper_repr
from cirq.ops import raw_types
@value.value_equality(approximate=True)
class PhasedXPowGate(raw_types.Gate):
    r
    def __init__(
        self,
        *,
        phase_exponent: float | sympy.Expr,
        exponent: float | sympy.Expr = 1.0,
        global_shift: float = 0.0,
    ) -> None:
        self._phase_exponent = value.canonicalize_half_turns(phase_exponent)
        self._exponent = exponent
        self._global_shift = global_shift
    def _qasm_(self, args: cirq.QasmArgs, qubits: tuple[cirq.Qid, ...]) -> str | None:
        if cirq.is_parameterized(self):
            return None
        args.validate_version('2.0', '3.0')
        e = cast(float, value.canonicalize_half_turns(self._exponent))
        p = cast(float, self.phase_exponent)
        epsilon = 10**-args.precision
        if abs(e + 0.5) <= epsilon:
            return args.format(
                'u2({0:half_turns}, {1:half_turns}) {2};\n', p + 0.5, -p - 0.5, qubits[0]
            )
        if abs(e - 0.5) <= epsilon:
            return args.format(
                'u2({0:half_turns}, {1:half_turns}) {2};\n', p - 0.5, -p + 0.5, qubits[0]
            )
        return args.format(
            'u3({0:half_turns}, {1:half_turns}, {2:half_turns}) {3};\n',
            -e,
            p + 0.5,
            -p - 0.5,
            qubits[0],
        )
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        assert len(qubits) == 1
        q = qubits[0]
        z = cirq.Z(q) ** self._phase_exponent
        x = cirq.XPowGate(exponent=self._exponent, global_shift=self.global_shift).on(q)
        return z**-1, x, z
    @property
    def exponent(self) -> float | sympy.Expr:
        return self._exponent
    @property
    def phase_exponent(self) -> float | sympy.Expr:
        return self._phase_exponent
    @property
    def global_shift(self) -> float:
        return self._global_shift
    def __pow__(self, exponent: float | sympy.Expr) -> PhasedXPowGate:
        new_exponent = protocols.mul(self._exponent, exponent, NotImplemented)
        if new_exponent is NotImplemented:
            return NotImplemented  # pragma: no cover
        return PhasedXPowGate(
            phase_exponent=self._phase_exponent,
            exponent=new_exponent,
            global_shift=self._global_shift,
        )
    def _trace_distance_bound_(self) -> float | None:
        if self._is_parameterized_():
            return None
        return abs(np.sin(self._exponent * 0.5 * np.pi))
    def _has_unitary_(self):
        return not self._is_parameterized_()
    def _unitary_(self) -> np.ndarray | NotImplementedType | None:
        if self._is_parameterized_():
            return None
        z = protocols.unitary(cirq.Z**self._phase_exponent)
        x = protocols.unitary(cirq.X**self._exponent)
        p = np.exp(1j * np.pi * self._global_shift * self._exponent)
        return np.dot(np.dot(z, x), np.conj(z)) * p
    def _num_qubits_(self) -> int:
        return 1
    def _pauli_expansion_(self) -> value.LinearDict[str]:
        if self._is_parameterized_():
            return NotImplemented
        phase_angle = np.pi * self._phase_exponent / 2
        angle = np.pi * self._exponent / 2
        phase = 1j ** (2 * self._exponent * (self._global_shift + 0.5))
        return value.LinearDict(
            {
                'I': phase * np.cos(angle),
                'X': -1j * phase * np.sin(angle) * np.cos(2 * phase_angle),
                'Y': -1j * phase * np.sin(angle) * np.sin(2 * phase_angle),
            }
        )
    def _is_parameterized_(self) -> bool:
        return protocols.is_parameterized(self._exponent) or protocols.is_parameterized(
            self._phase_exponent
        )
    def _parameter_names_(self) -> Set[str]:
        return protocols.parameter_names(self._exponent) | protocols.parameter_names(
            self._phase_exponent
        )
    def _resolve_parameters_(self, resolver: cirq.ParamResolver, recursive: bool) -> PhasedXPowGate:
        phase_exponent = resolver.value_of(self._phase_exponent, recursive)
        exponent = resolver.value_of(self._exponent, recursive)
        if not isinstance(phase_exponent, float) and isinstance(phase_exponent, numbers.Complex):
            if isinstance(phase_exponent, numbers.Real):
                phase_exponent = float(phase_exponent)
            else:
                raise ValueError(f'PhasedXPowGate does not support complex value {phase_exponent}')
        if not isinstance(exponent, float) and isinstance(exponent, numbers.Complex):
            if isinstance(exponent, numbers.Real):
                exponent = float(exponent)
            else:
                raise ValueError(f'PhasedXPowGate does not support complex value {exponent}')
        return PhasedXPowGate(
            phase_exponent=phase_exponent, exponent=exponent, global_shift=self._global_shift
        )
    def _phase_by_(self, phase_turns, qubit_index):
        assert qubit_index == 0
        return PhasedXPowGate(
            exponent=self._exponent,
            phase_exponent=self._phase_exponent + phase_turns * 2,
            global_shift=self._global_shift,
        )
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        return protocols.CircuitDiagramInfo(
            wire_symbols=(f'PhX({args.format_real(self.phase_exponent)})',),
            exponent=value.canonicalize_half_turns(self._exponent),
        )
    def __str__(self) -> str:
        info = protocols.circuit_diagram_info(self)
        if info.exponent == 1:
            return info.wire_symbols[0]
        return f'{info.wire_symbols[0]}**{info.exponent}'
    def __repr__(self) -> str:
        args = [f'phase_exponent={proper_repr(self.phase_exponent)}']
        if self.exponent != 1:
            args.append(f'exponent={proper_repr(self.exponent)}')
        if self._global_shift != 0:
            args.append(f'global_shift={self._global_shift!r}')
        args_str = ', '.join(args)
        return f'cirq.PhasedXPowGate({args_str})'
    def _period(self):
        exponents = [self._global_shift, 1 + self._global_shift]
        real_periods = [abs(2 / e) for e in exponents if e != 0]
        int_periods = [int(np.round(e)) for e in real_periods]
        if any(i != r for i, r in zip(real_periods, int_periods)):
            return None
        if len(int_periods) == 1:
            return int_periods[0]
        return int_periods[0] * int_periods[1] / math.gcd(*int_periods)
    @property
    def _canonical_exponent(self):
        period = self._period()
        if not period or isinstance(self._exponent, sympy.Basic):
            return self._exponent
        return self._exponent % period
    def _value_equality_values_(self):
        return self.phase_exponent, self._canonical_exponent, self._global_shift
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, ['phase_exponent', 'exponent', 'global_shift'])

from __future__ import annotations
import numbers
from collections.abc import Iterator, Sequence, Set
from typing import Any, TYPE_CHECKING
import numpy as np
import sympy
from cirq import linalg, ops, protocols, value
from cirq._compat import proper_repr
from cirq.ops import raw_types
if TYPE_CHECKING:
    import cirq
@value.value_equality(approximate=True)
class PhasedXZGate(raw_types.Gate):
    r
    def __init__(
        self,
        *,
        x_exponent: float | sympy.Expr,
        z_exponent: float | sympy.Expr,
        axis_phase_exponent: float | sympy.Expr,
    ) -> None:
        self._x_exponent = x_exponent
        self._z_exponent = z_exponent
        self._axis_phase_exponent = axis_phase_exponent
    @classmethod
    def from_zyz_angles(cls, z0_rad: float, y_rad: float, z1_rad: float) -> cirq.PhasedXZGate:
        r
        return cls.from_zyz_exponents(z0=z0_rad / np.pi, y=y_rad / np.pi, z1=z1_rad / np.pi)
    @classmethod
    def from_zyz_exponents(cls, z0: float, y: float, z1: float) -> cirq.PhasedXZGate:
        return PhasedXZGate(axis_phase_exponent=-z0 + 0.5, x_exponent=y, z_exponent=z0 + z1)
    def _canonical(self) -> cirq.PhasedXZGate:
        x = self.x_exponent
        z = self.z_exponent
        a = self.axis_phase_exponent
        if not isinstance(x, sympy.Expr):
            x %= 2
            if x > 1.0:
                x -= 2
        if x == 0:
            a = 0.0
        if x == 1 and z != 0:
            a += z / 2
            z = 0.0
        if not isinstance(z, sympy.Expr):
            z %= 2
            if z > 1.0:
                z -= 2
        if not isinstance(a, sympy.Expr):
            a %= 2
            if a > 1.0:
                a -= 2
            if a <= -0.5:
                a += 1
                if x != 1:
                    x = -x
            elif a > 0.5:
                a -= 1
                if x != 1:
                    x = -x
        return PhasedXZGate(x_exponent=x, z_exponent=z, axis_phase_exponent=a)
    @property
    def x_exponent(self) -> float | sympy.Expr:
        return self._x_exponent
    @property
    def z_exponent(self) -> float | sympy.Expr:
        return self._z_exponent
    @property
    def axis_phase_exponent(self) -> float | sympy.Expr:
        return self._axis_phase_exponent
    def _value_equality_values_(self):
        if self._is_parameterized_():
            return (self._x_exponent, self._z_exponent, self._axis_phase_exponent)
        c = self._canonical()
        return (
            value.PeriodicValue(c._x_exponent, 2),
            value.PeriodicValue(c._z_exponent, 2),
            value.PeriodicValue(c._axis_phase_exponent, 2),
        )
    @staticmethod
    def from_matrix(mat: np.ndarray) -> cirq.PhasedXZGate:
        pre_phase, rotation, post_phase = linalg.deconstruct_single_qubit_matrix_into_angles(mat)
        pre_phase /= np.pi
        post_phase /= np.pi
        rotation /= np.pi
        pre_phase -= 0.5
        post_phase += 0.5
        return PhasedXZGate(
            x_exponent=rotation, axis_phase_exponent=-pre_phase, z_exponent=post_phase + pre_phase
        )._canonical()
    def with_z_exponent(self, z_exponent: float | sympy.Expr) -> cirq.PhasedXZGate:
        return PhasedXZGate(
            axis_phase_exponent=self._axis_phase_exponent,
            x_exponent=self._x_exponent,
            z_exponent=z_exponent,
        )
    def _qasm_(self, args: cirq.QasmArgs, qubits: tuple[cirq.Qid, ...]) -> str | None:
        from cirq.circuits import qasm_output
        qasm_gate = qasm_output.QasmUGate(
            lmda=0.5 - self._axis_phase_exponent,
            theta=self._x_exponent,
            phi=self._z_exponent + self._axis_phase_exponent - 0.5,
        )
        return protocols.qasm(qasm_gate, args=args, qubits=qubits)
    def _num_qubits_(self) -> int:
        return 1
    def _has_unitary_(self) -> bool:
        return not self._is_parameterized_()
    def _unitary_(self) -> np.ndarray | None:
        if self._is_parameterized_():
            return None
        z_pre = protocols.unitary(ops.Z**-self._axis_phase_exponent)
        x = protocols.unitary(ops.X**self._x_exponent)
        z_post = protocols.unitary(ops.Z ** (self._axis_phase_exponent + self._z_exponent))
        return z_post @ x @ z_pre
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        q = qubits[0]
        yield ops.Z(q) ** -self._axis_phase_exponent
        yield ops.X(q) ** self._x_exponent
        yield ops.Z(q) ** (self._axis_phase_exponent + self._z_exponent)
    def __pow__(self, exponent: float) -> PhasedXZGate:
        if exponent == 1:
            return self
        if exponent == -1:
            return PhasedXZGate(
                x_exponent=-self._x_exponent,
                z_exponent=-self._z_exponent,
                axis_phase_exponent=self._z_exponent + self.axis_phase_exponent,
            )
        return NotImplemented
    def _is_parameterized_(self) -> bool:
        return (
            protocols.is_parameterized(self._x_exponent)
            or protocols.is_parameterized(self._z_exponent)
            or protocols.is_parameterized(self._axis_phase_exponent)
        )
    def _parameter_names_(self) -> Set[str]:
        return (
            protocols.parameter_names(self._x_exponent)
            | protocols.parameter_names(self._z_exponent)
            | protocols.parameter_names(self._axis_phase_exponent)
        )
    def _resolve_parameters_(
        self, resolver: cirq.ParamResolver, recursive: bool
    ) -> cirq.PhasedXZGate:
        z_exponent = resolver.value_of(self._z_exponent, recursive)
        x_exponent = resolver.value_of(self._x_exponent, recursive)
        axis_phase_exponent = resolver.value_of(self._axis_phase_exponent, recursive)
        if not isinstance(z_exponent, float) and isinstance(z_exponent, numbers.Complex):
            if isinstance(z_exponent, numbers.Real):
                z_exponent = float(z_exponent)
            else:
                raise ValueError(f'Complex exponent {z_exponent} not allowed in cirq.PhasedXZGate')
        if not isinstance(x_exponent, float) and isinstance(x_exponent, numbers.Complex):
            if isinstance(x_exponent, numbers.Real):
                x_exponent = float(x_exponent)
            else:
                raise ValueError(f'Complex exponent {x_exponent} not allowed in cirq.PhasedXZGate')
        if not isinstance(axis_phase_exponent, float) and isinstance(
            axis_phase_exponent, numbers.Complex
        ):
            if isinstance(axis_phase_exponent, numbers.Real):
                axis_phase_exponent = float(axis_phase_exponent)
            else:
                raise ValueError(
                    f'Complex exponent {axis_phase_exponent} not allowed in cirq.PhasedXZGate'
                )
        return PhasedXZGate(
            z_exponent=z_exponent, x_exponent=x_exponent, axis_phase_exponent=axis_phase_exponent
        )
    def _phase_by_(self, phase_turns, qubit_index) -> cirq.PhasedXZGate:
        assert qubit_index == 0
        return PhasedXZGate(
            x_exponent=self._x_exponent,
            z_exponent=self._z_exponent,
            axis_phase_exponent=self._axis_phase_exponent + phase_turns * 2,
        )
    def _pauli_expansion_(self) -> cirq.LinearDict[str]:
        if protocols.is_parameterized(self):
            return NotImplemented
        x_angle = np.pi * self._x_exponent / 2
        z_angle = np.pi * self._z_exponent / 2
        axis_angle = np.pi * self._axis_phase_exponent
        phase = np.exp(1j * (x_angle + z_angle))
        cx = np.cos(x_angle)
        sx = np.sin(x_angle)
        return value.LinearDict(
            {
                'I': phase * cx * np.cos(z_angle),
                'X': -1j * phase * sx * np.cos(z_angle + axis_angle),
                'Y': -1j * phase * sx * np.sin(z_angle + axis_angle),
                'Z': -1j * phase * cx * np.sin(z_angle),
            }
        )  # yapf: disable
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> str:
        return (
            f'PhXZ('
            f'a={args.format_real(self._axis_phase_exponent)},'
            f'x={args.format_real(self._x_exponent)},'
            f'z={args.format_real(self._z_exponent)})'
        )
    def __str__(self) -> str:
        return protocols.circuit_diagram_info(self).wire_symbols[0]
    def __repr__(self) -> str:
        return (
            f'cirq.PhasedXZGate('
            f'axis_phase_exponent={proper_repr(self._axis_phase_exponent)},'
            f' x_exponent={proper_repr(self._x_exponent)}, '
            f'z_exponent={proper_repr(self._z_exponent)})'
        )
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(
            self, ['axis_phase_exponent', 'x_exponent', 'z_exponent']
        )

from __future__ import annotations
import itertools
import math
from collections.abc import Iterable, Mapping
from typing import Any, TYPE_CHECKING
import numpy as np
from scipy.sparse import csr_matrix
from cirq import value
if TYPE_CHECKING:
    import cirq
def _check_qids_dimension(qids):
    for qid in qids:
        if qid.dimension != 2:
            raise ValueError(f"Only qubits are supported, but {qid} has dimension {qid.dimension}")
@value.value_equality(approximate=True)
class ProjectorString:
    def __init__(self, projector_dict: dict[cirq.Qid, int], coefficient: complex = 1):
        _check_qids_dimension(projector_dict.keys())
        self._projector_dict = projector_dict
        self._coefficient = complex(coefficient)
    @property
    def projector_dict(self) -> dict[cirq.Qid, int]:
        return self._projector_dict
    @property
    def coefficient(self) -> complex:
        return self._coefficient
    def matrix(self, projector_qids: Iterable[cirq.Qid] | None = None) -> csr_matrix:
        projector_qids = self._projector_dict.keys() if projector_qids is None else projector_qids
        _check_qids_dimension(projector_qids)
        idx_to_keep = [
            [self._projector_dict[qid]] if qid in self._projector_dict else [0, 1]
            for qid in projector_qids
        ]
        total_d = math.prod(qid.dimension for qid in projector_qids)
        ones_idx = []
        for idx in itertools.product(*idx_to_keep):
            d = total_d
            kron_idx = 0
            for i, qid in zip(idx, projector_qids):
                d //= qid.dimension
                kron_idx += i * d
            ones_idx.append(kron_idx)
        return csr_matrix(
            ([self._coefficient] * len(ones_idx), (ones_idx, ones_idx)), shape=(total_d, total_d)
        )
    def _get_idx_to_keep(self, qid_map: Mapping[cirq.Qid, int]):
        num_qubits = len(qid_map)
        idx_to_keep: list[Any] = [slice(0, 2)] * num_qubits
        for q in self.projector_dict.keys():
            idx_to_keep[qid_map[q]] = self.projector_dict[q]
        return tuple(idx_to_keep)
    def expectation_from_state_vector(
        self, state_vector: np.ndarray, qid_map: Mapping[cirq.Qid, int]
    ) -> complex:
        _check_qids_dimension(qid_map.keys())
        num_qubits = len(qid_map)
        index = self._get_idx_to_keep(qid_map)
        return self._coefficient * np.sum(
            np.abs(np.reshape(state_vector, (2,) * num_qubits)[index]) ** 2
        )
    def expectation_from_density_matrix(
        self, state: np.ndarray, qid_map: Mapping[cirq.Qid, int]
    ) -> complex:
        _check_qids_dimension(qid_map.keys())
        num_qubits = len(qid_map)
        index = self._get_idx_to_keep(qid_map) * 2
        result = np.reshape(state, (2,) * (2 * num_qubits))[index]
        while any(result.shape):
            result = np.trace(result, axis1=0, axis2=len(result.shape) // 2)
        return self._coefficient * result
    def __repr__(self) -> str:
        return (
            f"cirq.ProjectorString(projector_dict={self._projector_dict},"
            f"coefficient={self._coefficient})"
        )
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'projector_dict': list(self._projector_dict.items()),
            'coefficient': self._coefficient,
        }
    @classmethod
    def _from_json_dict_(cls, projector_dict, coefficient, **kwargs):
        return cls(projector_dict=dict(projector_dict), coefficient=coefficient)
    def _value_equality_values_(self) -> Any:
        projector_dict = sorted(self._projector_dict.items())
        return (tuple(projector_dict), self._coefficient)

from __future__ import annotations
from typing import overload, TYPE_CHECKING
if TYPE_CHECKING:
    import cirq
@overload
def q(__x: int) -> cirq.LineQubit: ...
@overload
def q(__row: int, __col: int) -> cirq.GridQubit: ...
@overload
def q(__name: str) -> cirq.NamedQubit: ...
def q(*args: int | str) -> cirq.LineQubit | cirq.GridQubit | cirq.NamedQubit:
    import cirq  # avoid circular import
    if len(args) == 1:
        if isinstance(args[0], int):
            return cirq.LineQubit(args[0])
        elif isinstance(args[0], str):
            return cirq.NamedQubit(args[0])
    elif len(args) == 2:
        if isinstance(args[0], int) and isinstance(args[1], int):
            return cirq.GridQubit(args[0], args[1])
    raise ValueError(f"Could not construct qubit: args={args}")

from __future__ import annotations
import abc
import dataclasses
from collections.abc import Iterable
from typing import TYPE_CHECKING
from cirq.ops import raw_types
if TYPE_CHECKING:
    import cirq
class QubitManager(metaclass=abc.ABCMeta):
    @abc.abstractmethod
    def qalloc(self, n: int, dim: int = 2) -> list[cirq.Qid]:
    @abc.abstractmethod
    def qborrow(self, n: int, dim: int = 2) -> list[cirq.Qid]:
    @abc.abstractmethod
    def qfree(self, qubits: Iterable[cirq.Qid]) -> None:
@dataclasses.dataclass(frozen=True)
class _BaseAncillaQid(raw_types.Qid):
    id: int
    dim: int = 2
    prefix: str = ''
    def _comparison_key(self) -> tuple[str, int]:
        return self.prefix, self.id
    @property
    def dimension(self) -> int:
        return self.dim
    def with_dimension(self, dimension: int) -> _BaseAncillaQid:
        return dataclasses.replace(self, dim=dimension)
    def __repr__(self) -> str:
        dim_str = f', dim={self.dim}' if self.dim != 2 else ''
        prefix_str = f', prefix={self.prefix!r}' if self.prefix != '' else ''
        return f"cirq.ops.{type(self).__name__}({self.id}{dim_str}{prefix_str})"
class CleanQubit(_BaseAncillaQid):
    def __str__(self) -> str:
        dim_str = f' (d={self.dimension})' if self.dim != 2 else ''
        return f"{self.prefix}_c({self.id}){dim_str}"
class BorrowableQubit(_BaseAncillaQid):
    def __str__(self) -> str:
        dim_str = f' (d={self.dimension})' if self.dim != 2 else ''
        return f"{self.prefix}_b({self.id}){dim_str}"
class SimpleQubitManager(QubitManager):
    def __init__(self, prefix: str = ''):
        self._clean_id = 0
        self._borrow_id = 0
        self._prefix = prefix
    def qalloc(self, n: int, dim: int = 2) -> list[cirq.Qid]:
        self._clean_id += n
        return [CleanQubit(i, dim, self._prefix) for i in range(self._clean_id - n, self._clean_id)]
    def qborrow(self, n: int, dim: int = 2) -> list[cirq.Qid]:
        self._borrow_id = self._borrow_id + n
        return [
            BorrowableQubit(i, dim, self._prefix)
            for i in range(self._borrow_id - n, self._borrow_id)
        ]
    def qfree(self, qubits: Iterable[cirq.Qid]) -> None:
        for q in qubits:
            good = isinstance(q, CleanQubit) and q.id < self._clean_id
            good |= isinstance(q, BorrowableQubit) and q.id < self._borrow_id
            if not good:
                raise ValueError(f"{q} was not allocated by {self}")

from __future__ import annotations
from collections.abc import Callable, Iterable
from typing import Any, TYPE_CHECKING, TypeVar
if TYPE_CHECKING:
    import cirq
TInternalQubit = TypeVar('TInternalQubit')
TExternalQubit = TypeVar('TExternalQubit')
class QubitOrder:
    def __init__(self, explicit_func: Callable[[Iterable[cirq.Qid]], tuple[cirq.Qid, ...]]) -> None:
        self._explicit_func = explicit_func
    DEFAULT: QubitOrder
    @staticmethod
    def explicit(
        fixed_qubits: Iterable[cirq.Qid], fallback: QubitOrder | None = None
    ) -> QubitOrder:
        result = tuple(fixed_qubits)
        if len(set(result)) < len(result):
            raise ValueError(f'Qubits appear in fixed_order twice: {result}.')
        def func(qubits):
            remaining = set(qubits) - set(result)
            if not remaining:
                return result
            if not fallback:
                raise ValueError(f'Unexpected extra qubits: {remaining}.')
            return result + fallback.order_for(remaining)
        return QubitOrder(func)
    @staticmethod
    def sorted_by(key: Callable[[cirq.Qid], Any]) -> QubitOrder:
        return QubitOrder(lambda qubits: tuple(sorted(qubits, key=key)))
    def order_for(self, qubits: Iterable[cirq.Qid]) -> tuple[cirq.Qid, ...]:
        return self._explicit_func(qubits)
    @staticmethod
    def as_qubit_order(val: cirq.QubitOrderOrList) -> QubitOrder:
        if isinstance(val, Iterable):
            return QubitOrder.explicit(val)
        if isinstance(val, QubitOrder):
            return val
        raise ValueError(f"Don't know how to interpret <{val}> as a Basis.")
    def map(
        self,
        internalize: Callable[[TExternalQubit], TInternalQubit],
        externalize: Callable[[TInternalQubit], TExternalQubit],
    ) -> QubitOrder:
        def func(qubits):
            unwrapped_qubits = [internalize(q) for q in qubits]
            unwrapped_result = self.order_for(unwrapped_qubits)
            return tuple(externalize(q) for q in unwrapped_result)
        return QubitOrder(func)
QubitOrder.DEFAULT = QubitOrder.sorted_by(lambda v: v)

from __future__ import annotations
import numbers
from collections.abc import Set
