        assert_apply_mixture_returns(
            val,
            rho,
            left_axes=[1],
            right_axes=[3],
            assert_result_is_out_buf=False,
            expected_result=np.reshape(np.outer([1, 1j, 1, 1j], [1, -1j, 1, -1j]), shape),
