def inverse(val: cirq.Gate, default: TDefault) -> TDefault | cirq.Gate:
    pass
@overload
def inverse(val: cirq.Operation, default: TDefault) -> TDefault | cirq.Operation:
    pass
@overload
def inverse(val: cirq.Circuit, default: TDefault) -> TDefault | cirq.Circuit:
    pass
