def test_equivalent_to_builtin_mul() -> None:
    test_vals = [
        0,
        1,
        1j,
        -2.5,
        Neither(),
        MulReturnsNotImplemented(),
        RMulReturnsNotImplemented(),
        MulReturnsFive(),
        RMulReturnsSix(),
