import numbers
from collections.abc import Set
from typing import Any, cast, Protocol, Self, TYPE_CHECKING, TypeVar
import sympy
from cirq import study
from cirq._doc import doc_private
if TYPE_CHECKING:
    import cirq
T = TypeVar('T')
class SupportsParameterization(Protocol):
    @doc_private
    def _is_parameterized_(self) -> bool:
    @doc_private
    def _parameter_names_(self) -> Set[str]:
    @doc_private
    def _resolve_parameters_(self, resolver: cirq.ParamResolver, recursive: bool) -> Self:
class ResolvableValue(Protocol):
    @doc_private
    def _resolved_value_(self) -> Any:
def is_parameterized(val: Any) -> bool:
    if isinstance(val, sympy.Basic):
        return True
    if isinstance(val, numbers.Number):
        return False
    if isinstance(val, (list, tuple)):
        return any(is_parameterized(e) for e in val)
    getter = getattr(val, '_is_parameterized_', None)
    result = NotImplemented if getter is None else getter()
    if result is not NotImplemented:
        return result
    return bool(parameter_names(val))
def parameter_names(val: Any) -> Set[str]:
    if isinstance(val, sympy.Basic):
        return {cast(sympy.Symbol, symbol).name for symbol in val.free_symbols}
    if isinstance(val, numbers.Number):
        return set()
    if isinstance(val, (list, tuple)):
        return {name for e in val for name in parameter_names(e)}
    getter = getattr(val, '_parameter_names_', None)
    result = NotImplemented if getter is None else getter()
    if result is not NotImplemented:
        return result
    return set()
def parameter_symbols(val: Any) -> Set[sympy.Symbol]:
    return {sympy.Symbol(name) for name in parameter_names(val)}
def resolve_parameters(
    val: T, param_resolver: cirq.ParamResolverOrSimilarType, recursive: bool = True
) -> T:
    if not param_resolver:
        return val
    if not isinstance(param_resolver, study.ParamResolver):
        param_resolver = study.ParamResolver(param_resolver)
    is_parameterized = (
        val._is_parameterized_() if hasattr(val, '_is_parameterized_') else NotImplemented
    )
    if is_parameterized is not NotImplemented and not is_parameterized:
        return val
    getter = getattr(val, '_resolve_parameters_', None)
    if getter is None:
        result = NotImplemented
    else:
        result = getter(param_resolver, recursive)
    if result is not NotImplemented:
        return result
    if isinstance(val, sympy.Expr):
        return cast(T, param_resolver.value_of(val, recursive))
    if isinstance(val, (list, tuple)):
        return cast(T, type(val)(resolve_parameters(e, param_resolver, recursive) for e in val))
    return val
def resolve_parameters_once(val: T, param_resolver: cirq.ParamResolverOrSimilarType) -> T:
    return resolve_parameters(val, param_resolver, False)

from __future__ import annotations
from collections.abc import Sequence
from typing import Any, Protocol, TypeVar
import numpy as np
from cirq._doc import doc_private
from cirq.protocols import unitary_protocol
TDefault = TypeVar('TDefault')
class SupportsTraceDistanceBound(Protocol):
    @doc_private
    def _trace_distance_bound_(self) -> float:
def trace_distance_bound(val: Any) -> float:
    strats = [_strat_from_trace_distance_bound_method, _strat_distance_from_unitary]
    for strat in strats:
        result = strat(val)
        if result is None:
            break
        if result is not NotImplemented:
            return result
    return 1.0
def _strat_from_trace_distance_bound_method(val: Any) -> float | None:
    getter = getattr(val, '_trace_distance_bound_', None)
    result = NotImplemented if getter is None else getter()
    if result is None:
        return None
    if result is not NotImplemented:
        return min(1.0, result)
    return NotImplemented
def _strat_distance_from_unitary(val: Any) -> float | None:
    u = unitary_protocol.unitary(val, default=None)
    if u is None:
        return NotImplemented
    if u.shape == (2, 2):
        squared = 1 - (0.5 * abs(u[0][0] + u[1][1])) ** 2
        if squared <= 0:
            return 0.0
        return squared**0.5
    return trace_distance_from_angle_list(np.angle(np.linalg.eigvals(u)))
def trace_distance_from_angle_list(angle_list: Sequence[float] | np.ndarray) -> float:
    angles = np.sort(angle_list)
    maxim = 2 * np.pi + angles[0] - angles[-1]
    for i in range(1, len(angles)):
        maxim = max(maxim, angles[i] - angles[i - 1])
    if maxim <= np.pi:
        return 1.0
    return max(0.0, np.sin(0.5 * maxim))

from __future__ import annotations
import numpy as np
import cirq
def test_trace_distance_bound() -> None:
    class NoMethod:
        pass
    class ReturnsNotImplemented:
        def _trace_distance_bound_(self):
            return NotImplemented
    class ReturnsTwo:
        def _trace_distance_bound_(self) -> float:
            return 2.0
    class ReturnsConstant:
        def __init__(self, bound):
            self.bound = bound
        def _trace_distance_bound_(self) -> float:
            return self.bound
    x = cirq.MatrixGate(cirq.unitary(cirq.X))
    cx = cirq.MatrixGate(cirq.unitary(cirq.CX))
    cxh = cirq.MatrixGate(cirq.unitary(cirq.CX**0.5))
    assert np.isclose(cirq.trace_distance_bound(x), cirq.trace_distance_bound(cirq.X))
    assert np.isclose(cirq.trace_distance_bound(cx), cirq.trace_distance_bound(cirq.CX))
    assert np.isclose(cirq.trace_distance_bound(cxh), cirq.trace_distance_bound(cirq.CX**0.5))
    assert cirq.trace_distance_bound(NoMethod()) == 1.0
    assert cirq.trace_distance_bound(ReturnsNotImplemented()) == 1.0
    assert cirq.trace_distance_bound(ReturnsTwo()) == 1.0
    assert cirq.trace_distance_bound(ReturnsConstant(0.1)) == 0.1
    assert cirq.trace_distance_bound(ReturnsConstant(0.5)) == 0.5
    assert cirq.trace_distance_bound(ReturnsConstant(1.0)) == 1.0
    assert cirq.trace_distance_bound(ReturnsConstant(2.0)) == 1.0

from __future__ import annotations
from types import NotImplementedType
from typing import Any, Protocol, TypeVar
import numpy as np
from cirq._doc import doc_private
from cirq.protocols import qid_shape_protocol
from cirq.protocols.apply_unitary_protocol import apply_unitaries, ApplyUnitaryArgs
from cirq.protocols.decompose_protocol import _try_decompose_into_operations_and_qubits
RaiseTypeErrorIfNotProvided: np.ndarray = np.array([])
TDefault = TypeVar('TDefault')
class SupportsUnitary(Protocol):
    @doc_private
    def _unitary_(self) -> np.ndarray | NotImplementedType | None:
    @doc_private
    def _has_unitary_(self) -> bool:
def unitary(
    val: Any, default: np.ndarray | TDefault = RaiseTypeErrorIfNotProvided
) -> np.ndarray | TDefault:
    if isinstance(val, np.ndarray):
        return val
    strats = [
        _strat_unitary_from_unitary,
        _strat_unitary_from_apply_unitary,
        _strat_unitary_from_decompose,
    ]
    for strat in strats:
        result = strat(val)
        if result is None:
            break
        if result is not NotImplemented:
            return result
    if default is not RaiseTypeErrorIfNotProvided:
        return default
    raise TypeError(
        "cirq.unitary failed. "
        "Value doesn't have a (non-parameterized) unitary effect.\n"
        "\n"
        f"type: {type(val)}\n"
        f"value: {val!r}\n"
        "\n"
        "The given value failed to satisfy any of the following criteria:\n"
        "- A `_unitary_(self)` method that returned a value "
        "besides `None` or `NotImplemented`.\n"
        "- A `_decompose_(self)` method that returned a "
        "list of unitary operations.\n"
        "- An `_apply_unitary_(self, args)` method that returned a value "
        "besides `None` or `NotImplemented`."
    )
def _strat_unitary_from_unitary(val: Any) -> np.ndarray | None:
    getter = getattr(val, '_unitary_', None)
    if getter is None:
        return NotImplemented
    return getter()
def _strat_unitary_from_apply_unitary(val: Any) -> np.ndarray | None:
    method = getattr(val, '_apply_unitary_', None)
    if method is None:
        return NotImplemented
    val_qid_shape = qid_shape_protocol.qid_shape(val, None)
    if val_qid_shape is None:
        return NotImplemented
    result = method(ApplyUnitaryArgs.for_unitary(qid_shape=val_qid_shape))
    if result is NotImplemented or result is None:
        return result
    state_len = np.prod(val_qid_shape, dtype=np.int64)
    return result.reshape((state_len, state_len))
def _strat_unitary_from_decompose(val: Any) -> np.ndarray | None:
    operations, qubits, val_qid_shape = _try_decompose_into_operations_and_qubits(val)
    if operations is None:
        return NotImplemented
    all_qubits = frozenset(q for op in operations for q in op.qubits)
    work_qubits = frozenset(qubits)
    ancillas = tuple(sorted(all_qubits.difference(work_qubits)))
    ordered_qubits = ancillas + tuple(qubits)
    val_qid_shape = qid_shape_protocol.qid_shape(ancillas) + val_qid_shape
    result = apply_unitaries(
        operations, ordered_qubits, ApplyUnitaryArgs.for_unitary(qid_shape=val_qid_shape), None
    )
    if result is None:
        return None
    state_len = np.prod(val_qid_shape, dtype=np.int64)
    result = result.reshape((state_len, state_len))
    work_state_len = np.prod(val_qid_shape[len(ancillas) :], dtype=np.int64)
    return result[:work_state_len, :work_state_len]

