        ),
        np.array(
            [
                [0.8, 0, 0, 0.5],
                [0, 0.3, 0, 0],
                [0, 0, 0.2, 0],
                [0.5, 0, 0, 0.7],
            ],
        ),
    ),
)
def test_choi_to_superoperator_inverse_of_superoperator_to_choi(choi) -> None:
    superoperator = cirq.choi_to_superoperator(choi)
    recovered_choi = cirq.superoperator_to_choi(superoperator)
    assert np.allclose(recovered_choi, choi)
    recovered_superoperator = cirq.choi_to_superoperator(recovered_choi)
    assert np.allclose(recovered_superoperator, superoperator)
def test_superoperator_for_completely_dephasing_channel() -> None:
    assert np.all(cirq.operation_to_superoperator(cirq.phase_damp(1)) == np.diag([1, 0, 0, 1]))

from __future__ import annotations
import abc
from collections.abc import Sequence
from typing import Any, TYPE_CHECKING
import numpy as np
from cirq import protocols
from cirq._compat import _method_cache_name, cached_method, proper_repr
from cirq.qis import quantum_state_representation
from cirq.value import big_endian_int_to_digits, linear_dict, random_state
if TYPE_CHECKING:
    import cirq
class StabilizerState(
    quantum_state_representation.QuantumStateRepresentation, metaclass=abc.ABCMeta
):
    @abc.abstractmethod
    def apply_x(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
    @abc.abstractmethod
    def apply_y(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
    @abc.abstractmethod
    def apply_z(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
    @abc.abstractmethod
    def apply_h(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
    @abc.abstractmethod
    def apply_cz(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ) -> None:
    @abc.abstractmethod
    def apply_cx(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ) -> None:
    @abc.abstractmethod
    def apply_global_phase(self, coefficient: linear_dict.Scalar) -> None:
class CliffordTableau(StabilizerState):
    def __init__(
        self,
        num_qubits,
        initial_state: int = 0,
        rs: np.ndarray | None = None,
        xs: np.ndarray | None = None,
        zs: np.ndarray | None = None,
    ):
        self.n = num_qubits
        self.initial_state = initial_state
        self._rs = self._reconstruct_rs(rs)
        self._xs = self._reconstruct_xs(xs)
        self._zs = self._reconstruct_zs(zs)
    def _reconstruct_rs(self, rs: np.ndarray | None) -> np.ndarray:
        if rs is None:
            new_rs = np.zeros(2 * self.n + 1, dtype=bool)
            for i, val in enumerate(
                big_endian_int_to_digits(self.initial_state, digit_count=self.n, base=2)
            ):
                new_rs[self.n + i] = bool(val)
        else:
            shape = rs.shape
            if len(shape) == 1 and shape[0] == 2 * self.n and rs.dtype == np.dtype(bool):
                new_rs = np.append(rs, np.zeros(1, dtype=bool))
            else:
                raise ValueError(
                    "The value you passed for rs is not the correct shape and/or type. "
                    "Please confirm that it's a single row with 2*num_qubits columns "
                    "and of type bool."
                )
        return new_rs
    def _reconstruct_xs(self, xs: np.ndarray | None) -> np.ndarray:
        if xs is None:
            new_xs = np.zeros((2 * self.n + 1, self.n), dtype=bool)
            for i in range(self.n):
                new_xs[i, i] = True
        else:
            shape = xs.shape
            if (
                len(shape) == 2
                and shape[0] == 2 * self.n
                and shape[1] == self.n
                and xs.dtype == np.dtype(bool)
            ):
                new_xs = np.append(xs, np.zeros((1, self.n), dtype=bool), axis=0)
            else:
                raise ValueError(
                    "The value you passed for xs is not the correct shape and/or type. "
                    "Please confirm that it's 2*num_qubits rows, num_qubits columns, "
                    "and of type bool."
                )
        return new_xs
    def _reconstruct_zs(self, zs: np.ndarray | None) -> np.ndarray:
        if zs is None:
            new_zs = np.zeros((2 * self.n + 1, self.n), dtype=bool)
            for i in range(self.n):
                new_zs[self.n + i, i] = True
        else:
            shape = zs.shape
            if (
                len(shape) == 2
                and shape[0] == 2 * self.n
                and shape[1] == self.n
                and zs.dtype == np.dtype(bool)
            ):
                new_zs = np.append(zs, np.zeros((1, self.n), dtype=bool), axis=0)
            else:
                raise ValueError(
                    "The value you passed for zs is not the correct shape and/or type. "
                    "Please confirm that it's 2*num_qubits rows, num_qubits columns, "
                    "and of type bool."
                )
        return new_zs
    @property
    def xs(self) -> np.ndarray:
        return self._xs[:-1, :]
    @xs.setter
    def xs(self, new_xs: np.ndarray) -> None:
        assert np.shape(new_xs) == (2 * self.n, self.n)
        self._xs[:-1, :] = np.array(new_xs).astype(bool)
    @property
    def zs(self) -> np.ndarray:
        return self._zs[:-1, :]
    @zs.setter
    def zs(self, new_zs: np.ndarray) -> None:
        assert np.shape(new_zs) == (2 * self.n, self.n)
        self._zs[:-1, :] = np.array(new_zs).astype(bool)
    @property
    def rs(self) -> np.ndarray:
        return self._rs[:-1]
    @rs.setter
    def rs(self, new_rs: np.ndarray) -> None:
        assert np.shape(new_rs) == (2 * self.n,)
        self._rs[:-1] = np.array(new_rs).astype(bool)
    def matrix(self) -> np.ndarray:
        return np.concatenate([self.xs, self.zs], axis=1)
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, ['n', 'rs', 'xs', 'zs'])
    @classmethod
    def _from_json_dict_(cls, n, rs, xs, zs, **kwargs):
        state = cls(n)
        state.rs = np.array(rs).astype(bool)
        state.xs = np.array(xs).astype(bool)
        state.zs = np.array(zs).astype(bool)
        return state
    def _validate(self) -> bool:
        table = np.concatenate([self.xs, self.zs], axis=1)
        perm = list(range(self.n, 2 * self.n)) + list(range(self.n))
        skew_eye = np.eye(2 * self.n, dtype=int)[perm]
        return np.array_equal(np.mod(table.T.dot(skew_eye).dot(table), 2), skew_eye)
    def __eq__(self, other):
        if not isinstance(other, type(self)):
            return NotImplemented  # pragma: no cover
        return (
            self.n == other.n
            and np.array_equal(self.rs, other.rs)
            and np.array_equal(self.xs, other.xs)
            and np.array_equal(self.zs, other.zs)
        )
    def __copy__(self) -> CliffordTableau:
        return self.copy()
    def copy(self, deep_copy_buffers: bool = True) -> CliffordTableau:
        state = CliffordTableau(self.n)
        state.rs = self.rs.copy()
        state.xs = self.xs.copy()
        state.zs = self.zs.copy()
        return state
    def __repr__(self) -> str:
        return (
            f"cirq.CliffordTableau({self.n},"
            f"rs={proper_repr(np.delete(self._rs, len(self._rs)-1))}, "
            f"xs={proper_repr(np.delete(self._xs, len(self._xs)-1, axis=0))},"
            f"zs={proper_repr(np.delete(self._zs, len(self._zs)-1, axis=0))}, "
            f"initial_state={self.initial_state})"
        )
    def __str__(self) -> str:
        string = ''
        for i in range(self.n, 2 * self.n):
            string += '- ' if self.rs[i] else '+ '
            for k in range(self.n):
                if self.xs[i, k] & (not self.zs[i, k]):
                    string += 'X '
                elif (not self.xs[i, k]) & self.zs[i, k]:
                    string += 'Z '
                elif self.xs[i, k] & self.zs[i, k]:
                    string += 'Y '
                else:
                    string += 'I '
            if i < 2 * self.n - 1:
                string += '\n'
        return string
    def _str_full_(self) -> str:
        left_col_width = max(7, self.n * 2 + 3)
        right_col_width = max(10, self.n * 2 + 4)
        def _fill_row(left: str, right: str, mid='|', fill=' ') -> str:
            return f"{left:{fill}<{left_col_width}}{mid}{right:{fill}<{right_col_width}}".rstrip()
        def _pauli_from_matrix(r: int, c: int) -> str:
            match (bool(self.xs[r, c]), bool(self.zs[r, c])):
                case (True, False):
                    return f'X{c}'
                case (False, True):
                    return f'Z{c}'
                case (True, True):
                    return f'Y{c}'
                case _:
                    return '  '
        title_row = _fill_row('stable', ' destable')
        divider = _fill_row('', '', mid='+', fill='-')
        contents = [
            _fill_row(
                left=(
                    f"{'-' if self.rs[i + self.n] else '+'} "
                    f"{''.join(_pauli_from_matrix(i + self.n, j) for j in range(self.n))}"
                ),
                right=(
                    f" {'-' if self.rs[i] else '+'} "
                    f"{''.join(_pauli_from_matrix(i, j) for j in range(self.n))}"
                ),
            )
            for i in range(self.n)
        ]
        return '\n'.join([title_row, divider, *contents]) + '\n'
    def then(self, second: CliffordTableau) -> CliffordTableau:
        if not isinstance(second, CliffordTableau):
            raise TypeError("The type for second tableau must be the CliffordTableau type")
        if self.n != second.n:
            raise ValueError(
                f"Mismatched number of qubits of two tableaux: {self.n} vs {second.n}."
            )
        m1 = self.matrix().astype(int)
        m2 = second.matrix().astype(int)
        num_ys1 = np.sum(m1[:, : self.n] * m1[:, self.n :], axis=1)
        num_ys2 = np.sum(m2[:, : self.n] * m2[:, self.n :], axis=1)
        p1 = np.mod(num_ys1, 2)
        p2 = np.mod(num_ys2, 2)
        s1 = self.rs.astype(int) + np.mod(num_ys1, 4) // 2
        s2 = second.rs.astype(int) + np.mod(num_ys2, 4) // 2
        lmbda = np.zeros((2 * self.n, 2 * self.n))
        lmbda[: self.n, self.n :] = np.eye(self.n)
        m_12 = np.mod(m1 @ m2, 2)
        p_12 = np.mod(p1 + m1 @ p2, 2)
        s_12 = (
            s1
            + m1 @ s2
            + p1 * (m1 @ p2)
            + np.diag(m1 @ np.tril(np.outer(p2, p2.T) + m2 @ lmbda @ m2.T, -1) @ m1.T)
        )
        num_ys12 = np.sum(m_12[:, : self.n] * m_12[:, self.n :], axis=1)
        merged_sign = np.mod(p_12 + 2 * s_12 - num_ys12, 4) // 2
        merged_tableau = CliffordTableau(num_qubits=self.n)
        merged_tableau.xs = m_12[:, : self.n]
        merged_tableau.zs = m_12[:, self.n :]
        merged_tableau.rs = merged_sign
        return merged_tableau
    def inverse(self) -> CliffordTableau:
        ret_table = CliffordTableau(num_qubits=self.n)
        ret_table.xs[: self.n] = self.zs[self.n :].T
        ret_table.zs[: self.n] = self.zs[: self.n].T
        ret_table.xs[self.n :] = self.xs[self.n :].T
        ret_table.zs[self.n :] = self.xs[: self.n].T
        ret_table.rs = ret_table.then(self).rs
        return ret_table
    def __matmul__(self, second: CliffordTableau):
        if not isinstance(second, CliffordTableau):
            return NotImplemented
        return second.then(self)
    def _rowsum(self, q1, q2):
        def g(x1, z1, x2, z2):
            if not x1 and not z1:
                return 0
            elif x1 and z1:
                return int(z2) - int(x2)
            elif x1 and not z1:
                return int(z2) * (2 * int(x2) - 1)
            else:
                return int(x2) * (1 - 2 * int(z2))
        r = 2 * int(self._rs[q1]) + 2 * int(self._rs[q2])
        for j in range(self.n):
            r += g(self._xs[q2, j], self._zs[q2, j], self._xs[q1, j], self._zs[q1, j])
        r %= 4
        self._rs[q1] = bool(r)
        self._xs[q1, :] ^= self._xs[q2, :]
        self._zs[q1, :] ^= self._zs[q2, :]
    def _row_to_dense_pauli(self, i: int) -> cirq.DensePauliString:
        from cirq.ops.dense_pauli_string import DensePauliString
        coefficient = -1 if self.rs[i] else 1
        pauli_mask = ""
        for k in range(self.n):
            if self.xs[i, k] & (not self.zs[i, k]):
                pauli_mask += "X"
            elif (not self.xs[i, k]) & self.zs[i, k]:
                pauli_mask += "Z"
            elif self.xs[i, k] & self.zs[i, k]:
                pauli_mask += "Y"
            else:
                pauli_mask += "I"
        return DensePauliString(pauli_mask, coefficient=coefficient)
    def stabilizers(self) -> list[cirq.DensePauliString]:
        return [self._row_to_dense_pauli(i) for i in range(self.n, 2 * self.n)]
    def destabilizers(self) -> list[cirq.DensePauliString]:
        return [self._row_to_dense_pauli(i) for i in range(self.n)]
    def _measure(self, q, prng: np.random.RandomState) -> int:
        is_commuting = True
        for i in range(self.n, 2 * self.n):
            if self.xs[i, q]:
                p = i
                is_commuting = False
                break
        if is_commuting:
            self._xs[2 * self.n, :] = False
            self._zs[2 * self.n, :] = False
            self._rs[2 * self.n] = False
            for i in range(self.n):
                if self.xs[i, q]:
                    self._rowsum(2 * self.n, self.n + i)
            return int(self._rs[2 * self.n])
        for i in range(2 * self.n):
            if i != p and self.xs[i, q]:
                self._rowsum(i, p)
        self.xs[p - self.n, :] = self.xs[p, :].copy()
        self.zs[p - self.n, :] = self.zs[p, :].copy()
        self.rs[p - self.n] = self.rs[p]
        self.xs[p, :] = False
        self.zs[p, :] = False
        self.zs[p, q] = True
        self.rs[p] = bool(prng.randint(2))
        return int(self.rs[p])
    def apply_x(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 == 0:
            return
        if exponent % 0.5 != 0.0:
            raise ValueError('X exponent must be half integer')  # pragma: no cover
        effective_exponent = exponent % 2
        if effective_exponent == 0.5:
            self.xs[:, axis] ^= self.zs[:, axis]
            self.rs[:] ^= self.xs[:, axis] & self.zs[:, axis]
        elif effective_exponent == 1:
            self.rs[:] ^= self.zs[:, axis]
        elif effective_exponent == 1.5:
            self.rs[:] ^= self.xs[:, axis] & self.zs[:, axis]
            self.xs[:, axis] ^= self.zs[:, axis]
    def apply_y(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 == 0:
            return
        if exponent % 0.5 != 0.0:
            raise ValueError('Y exponent must be half integer')  # pragma: no cover
        effective_exponent = exponent % 2
        if effective_exponent == 0.5:
            self.rs[:] ^= self.xs[:, axis] & (~self.zs[:, axis])
            (self.xs[:, axis], self.zs[:, axis]) = (
                self.zs[:, axis].copy(),
                self.xs[:, axis].copy(),
            )
        elif effective_exponent == 1:
            self.rs[:] ^= self.xs[:, axis] ^ self.zs[:, axis]
        elif effective_exponent == 1.5:
            self.rs[:] ^= ~(self.xs[:, axis]) & self.zs[:, axis]
            (self.xs[:, axis], self.zs[:, axis]) = (
                self.zs[:, axis].copy(),
                self.xs[:, axis].copy(),
            )
    def apply_z(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 == 0:
            return
        if exponent % 0.5 != 0.0:
            raise ValueError('Z exponent must be half integer')  # pragma: no cover
        effective_exponent = exponent % 2
        if effective_exponent == 0.5:
            self.rs[:] ^= self.xs[:, axis] & self.zs[:, axis]
            self.zs[:, axis] ^= self.xs[:, axis]
        elif effective_exponent == 1:
            self.rs[:] ^= self.xs[:, axis]
        elif effective_exponent == 1.5:
            self.rs[:] ^= self.xs[:, axis] & (~self.zs[:, axis])
            self.zs[:, axis] ^= self.xs[:, axis]
    def apply_h(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 == 0:
            return
        if exponent % 1 != 0:
            raise ValueError('H exponent must be integer')  # pragma: no cover
        self.apply_y(axis, 0.5)
        self.apply_x(axis)
    def apply_cz(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ) -> None:
        if exponent % 2 == 0:
            return
        if exponent % 1 != 0:
            raise ValueError('CZ exponent must be integer')  # pragma: no cover
        (self.xs[:, target_axis], self.zs[:, target_axis]) = (
            self.zs[:, target_axis].copy(),
            self.xs[:, target_axis].copy(),
        )
        self.rs[:] ^= self.xs[:, target_axis] & self.zs[:, target_axis]
        self.rs[:] ^= (
            self.xs[:, control_axis]
            & self.zs[:, target_axis]
            & (~(self.xs[:, target_axis] ^ self.zs[:, control_axis]))
        )
        self.xs[:, target_axis] ^= self.xs[:, control_axis]
        self.zs[:, control_axis] ^= self.zs[:, target_axis]
        (self.xs[:, target_axis], self.zs[:, target_axis]) = (
            self.zs[:, target_axis].copy(),
            self.xs[:, target_axis].copy(),
        )
        self.rs[:] ^= self.xs[:, target_axis] & self.zs[:, target_axis]
    def apply_cx(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ) -> None:
        if exponent % 2 == 0:
            return
        if exponent % 1 != 0:
            raise ValueError('CX exponent must be integer')  # pragma: no cover
        self.rs[:] ^= (
            self.xs[:, control_axis]
            & self.zs[:, target_axis]
            & (~(self.xs[:, target_axis] ^ self.zs[:, control_axis]))
        )
        self.xs[:, target_axis] ^= self.xs[:, control_axis]
        self.zs[:, control_axis] ^= self.zs[:, target_axis]
    def apply_global_phase(self, coefficient: linear_dict.Scalar) -> None:
        pass
    def measure(
        self, axes: Sequence[int], seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None
    ) -> list[int]:
        return [self._measure(axis, random_state.parse_random_state(seed)) for axis in axes]
    @cached_method
    def __hash__(self) -> int:
        return hash(self.matrix().tobytes() + self.rs.tobytes())
    def __getstate__(self) -> dict[str, Any]:
        state = self.__dict__
        hash_attr = _method_cache_name(self.__hash__)
        if hash_attr in state:
            state = state.copy()
            del state[hash_attr]
        return state

from __future__ import annotations
from typing import TYPE_CHECKING
import numpy as np
from cirq import _import, protocols, value
from cirq.qis.states import (
    infer_qid_shape,
    quantum_state,
    QuantumState,
    validate_density_matrix,
    validate_normalized_state_vector,
)
stats = _import.LazyLoader("stats", globals(), "scipy.stats")
linalg = _import.LazyLoader("linalg", globals(), "scipy.linalg")
if TYPE_CHECKING:
    import cirq
def _sqrt_positive_semidefinite_matrix(mat: np.ndarray) -> np.ndarray:
    eigs, vecs = linalg.eigh(mat)
    return vecs @ (np.sqrt(np.abs(eigs)) * vecs).T.conj()
def _validate_int_state(state: int, qid_shape: tuple[int, ...] | None) -> None:
    if state < 0:
        raise ValueError(
            'Invalid state: A state specified as an integer must be non-negative, '
            f'but {state} was given.'
        )
    if qid_shape is not None:
        dim = np.prod(qid_shape, dtype=np.int64)
        if state >= dim:
            raise ValueError(
                'Invalid state for given qid shape: '
                'The maximum computational basis state for qid shape '
                f'{qid_shape} is {dim - 1}, but {state} was given.'
            )
def _validate_product_state(state: cirq.ProductState, qid_shape: tuple[int, ...] | None) -> None:
    if qid_shape is not None and qid_shape != (2,) * len(state):
        raise ValueError(
            'Invalid state for given qid shape: '
            f'Specified shape {qid_shape} but product state '
            f'has shape {(2,) * len(state)}.'
        )
def fidelity(
    state1: cirq.QUANTUM_STATE_LIKE,
    state2: cirq.QUANTUM_STATE_LIKE,
    qid_shape: tuple[int, ...] | None = None,
    validate: bool = True,
    atol: float = 1e-7,
) -> float:
    r
    if isinstance(state1, int) and isinstance(state2, int):
        if validate:
            _validate_int_state(state1, qid_shape)
            _validate_int_state(state2, qid_shape)
        return float(state1 == state2)
    if isinstance(state1, value.ProductState) and isinstance(state2, value.ProductState):
        if len(state1) != len(state2):
            raise ValueError(
                'Mismatched number of qubits in product states: '
                f'{len(state1)} and {len(state2)}.'
            )
        if validate:
            _validate_product_state(state1, qid_shape)
            _validate_product_state(state2, qid_shape)
        prod = 1.0
        for q, s1 in state1:
            s2 = state2[q]
            prod *= np.abs(np.vdot(s1.state_vector(), s2.state_vector()))
        return prod**2
    if (
        isinstance(state1, np.ndarray)
        and state1.dtype.kind == 'c'
        and isinstance(state2, np.ndarray)
        and state2.dtype.kind == 'c'
    ):
        state1, state2 = _numpy_arrays_to_state_vectors_or_density_matrices(
            state1, state2, qid_shape=qid_shape, validate=validate, atol=atol
        )
        return _fidelity_state_vectors_or_density_matrices(state1, state2)
    if qid_shape is None:
        try:
            qid_shape = infer_qid_shape(state1, state2)
        except:
            raise ValueError(
                'Failed to infer the qid shape of the given states. '
                'Please specify the qid shape explicitly using the `qid_shape` argument.'
            )
    state1 = quantum_state(state1, qid_shape=qid_shape, validate=validate, atol=atol)
    state2 = quantum_state(state2, qid_shape=qid_shape, validate=validate, atol=atol)
    state1_arr = state1.state_vector_or_density_matrix()
    state2_arr = state2.state_vector_or_density_matrix()
    return _fidelity_state_vectors_or_density_matrices(state1_arr, state2_arr)
def _numpy_arrays_to_state_vectors_or_density_matrices(
    state1: np.ndarray,
    state2: np.ndarray,
    qid_shape: tuple[int, ...] | None,
    validate: bool,
    atol: float,
) -> tuple[np.ndarray, np.ndarray]:
    if state1.ndim > 2 or (state1.ndim == 2 and state1.shape[0] != state1.shape[1]):
        state1 = state1.reshape(-1)
    if state2.ndim > 2 or (state2.ndim == 2 and state2.shape[0] != state2.shape[1]):
        state2 = state2.reshape(-1)
    if state1.ndim == 2 and state2.ndim == 2:
        if state1.shape == state2.shape:
            if qid_shape is None:
                raise ValueError(
                    'The qid shape of the given states is ambiguous. '
                    'Try specifying the qid shape explicitly or '
                    'using a wrapper function like cirq.density_matrix.'
                )
            if state1.shape == qid_shape:
                state1 = state1.reshape(-1)
                state2 = state2.reshape(-1)
        elif state1.shape[0] < state2.shape[0]:
            state1 = state1.reshape(-1)
        else:  # state1.shape[0] > state2.shape[0]
            state2 = state2.reshape(-1)
    elif (
        state1.ndim == 2
        and state2.ndim < 2
        and np.prod(state1.shape, dtype=np.int64) == np.prod(state2.shape, dtype=np.int64)
    ):
        state1 = state1.reshape(-1)
    elif (
        state1.ndim < 2
        and state2.ndim == 2
        and np.prod(state1.shape, dtype=np.int64) == np.prod(state2.shape, dtype=np.int64)
    ):
        state2 = state2.reshape(-1)
    if validate:
        dim1: int = (
            state1.shape[0] if state1.ndim == 2 else np.prod(state1.shape, dtype=np.int64).item()
        )
        dim2: int = (
            state2.shape[0] if state2.ndim == 2 else np.prod(state2.shape, dtype=np.int64).item()
        )
        if dim1 != dim2:
            raise ValueError(f'Mismatched dimensions in given states: {dim1} and {dim2}.')
        if qid_shape is None:
            qid_shape = (dim1,)
        else:
            expected_dim = np.prod(qid_shape, dtype=np.int64)
            if dim1 != expected_dim:
                raise ValueError(
                    'Invalid state dimension for given qid shape: '
                    f'Expected dimension {expected_dim} but '
                    f'got dimension {dim1}.'
                )
        for state in (state1, state2):
            if state.ndim == 2:
                validate_density_matrix(state, qid_shape=qid_shape, atol=atol)
            else:
                validate_normalized_state_vector(state, qid_shape=qid_shape, atol=atol)
    return state1, state2
def _fidelity_state_vectors_or_density_matrices(state1: np.ndarray, state2: np.ndarray) -> float:
    if state1.ndim == 1 and state2.ndim == 1:
        return np.abs(np.vdot(state1, state2)) ** 2
    elif state1.ndim == 1 and state2.ndim == 2:
        return np.real(np.conjugate(state1) @ state2 @ state1)
    elif state1.ndim == 2 and state2.ndim == 1:
        return np.real(np.conjugate(state2) @ state1 @ state2)
    elif state1.ndim == 2 and state2.ndim == 2:
        state1_sqrt = _sqrt_positive_semidefinite_matrix(state1)
        eigs = linalg.eigvalsh(state1_sqrt @ state2 @ state1_sqrt)
        trace = np.sum(np.sqrt(np.abs(eigs)))
        return trace**2
    raise ValueError(  # pragma: no cover
        'The given arrays must be one- or two-dimensional. '
        f'Got shapes {state1.shape} and {state2.shape}.'
    )
def von_neumann_entropy(
    state: cirq.QUANTUM_STATE_LIKE,
    qid_shape: tuple[int, ...] | None = None,
    validate: bool = True,
    atol: float = 1e-7,
) -> float:
    r
    if isinstance(state, QuantumState) and state._is_density_matrix():
        state = state.data
    if isinstance(state, np.ndarray) and state.ndim == 2 and state.shape[0] == state.shape[1]:
        if validate:
            if qid_shape is None:
                qid_shape = (state.shape[0],)
            validate_density_matrix(state, qid_shape=qid_shape, dtype=state.dtype, atol=atol)
        eigenvalues = np.linalg.eigvalsh(state)
        return stats.entropy(np.abs(eigenvalues), base=2)
    if validate:
        _ = quantum_state(state, qid_shape=qid_shape, copy=False, validate=True, atol=atol)
    return 0.0
def entanglement_fidelity(operation: cirq.SupportsKraus) -> float:
    r
    f = 0.0
    for k in protocols.kraus(operation):
        f += np.abs(np.trace(k)) ** 2
    n_qubits = protocols.num_qubits(operation)
    return float(f / 4**n_qubits)

