class QuantumState:
    def __init__(
        self,
        data: np.ndarray,
        qid_shape: tuple[int, ...] | None = None,
        *,  # Force keyword arguments
        dtype: DTypeLike | None = None,
        validate: bool = True,
        atol: float = 1e-7,
    ) -> None:
