    state: np.ndarray,
    qid_shape: tuple[int, ...] | None = None,
    *,  # Force keyword arguments
    copy: bool = False,
    validate: bool = True,
    dtype: DTypeLike | None = None,
    atol: float = 1e-7,
) -> QuantumState:
