            unfactorized_total_dimension=dim, min_qudit_dimensions=min_qudit_dimensions
        )
    if state.ndim == 2:
        dim, _ = state.shape
        return _QidShapeSet(
            explicit_qid_shapes={state.shape},
            unfactorized_total_dimension=dim,
        )
