    return {
        qid_shape
        for qid_shape in explicit_qid_shapes
        if np.prod(qid_shape, dtype=np.int64) == unfactorized_total_dimension
    }
def _intersection_explicit_with_min_qudit_dims_qid_shapes(
    explicit_qid_shapes: set[tuple[int, ...]], min_qudit_dimensions: tuple[int, ...]
) -> set[tuple[int, ...]]:
    return {
        qid_shape
        for qid_shape in explicit_qid_shapes
        if len(qid_shape) == len(min_qudit_dimensions)
        and all(dim1 >= dim2 for dim1, dim2 in zip(qid_shape, min_qudit_dimensions))
    }
def _intersection_min_qudit_dims_qid_shapes(
    min_qudit_dimensions1: tuple[int, ...], min_qudit_dimensions2: tuple[int, ...]
) -> tuple[int, ...] | None:
    if len(min_qudit_dimensions1) == len(min_qudit_dimensions2):
        return tuple(
            max(dim1, dim2) for dim1, dim2 in zip(min_qudit_dimensions1, min_qudit_dimensions2)
        )
    return None
def bloch_vector_from_state_vector(
    state_vector: np.ndarray, index: int, qid_shape: tuple[int, ...] | None = None
) -> np.ndarray:
    rho = density_matrix_from_state_vector(state_vector, [index], qid_shape=qid_shape)
    v = np.zeros(3, dtype=np.float32)
    v[0] = 2 * np.real(rho[0][1])
    v[1] = 2 * np.imag(rho[1][0])
    v[2] = np.real(rho[0][0] - rho[1][1])
    return v
def density_matrix_from_state_vector(
    state_vector: np.ndarray,
    indices: Iterable[int] | None = None,
    qid_shape: tuple[int, ...] | None = None,
) -> np.ndarray:
    r
    shape = validate_qid_shape(state_vector, qid_shape)
    n_qubits = len(shape)
    if indices is None:
        return np.outer(state_vector, np.conj(state_vector))
    indices = list(indices)
    validate_indices(n_qubits, indices)
    state_vector = np.asarray(state_vector).reshape(shape)
    sum_inds = np.array(range(n_qubits))
    sum_inds[indices] += n_qubits
    rho = np.einsum(
        state_vector,
        list(range(n_qubits)),
        np.conj(state_vector),
        cast(list, sum_inds.tolist()),
        indices + cast(list, sum_inds[indices].tolist()),
    )
    new_shape = np.prod([shape[i] for i in indices], dtype=np.int64)
    return rho.reshape((new_shape, new_shape))
def dirac_notation(
    state_vector: np.ndarray, decimals: int = 2, qid_shape: tuple[int, ...] | None = None
) -> str:
    if qid_shape is None:
        qid_shape = (2,) * (len(state_vector).bit_length() - 1)
    if len(state_vector) != np.prod(qid_shape, dtype=np.int64):
        raise ValueError(
            'state_vector has incorrect size. '
            f'Expected {np.prod(qid_shape, dtype=np.int64)} but was {len(state_vector)}.'
        )
    digit_separator = '' if max(qid_shape, default=0) < 10 else ','
    perm_list = [
        digit_separator.join(seq)
        for seq in itertools.product(*((str(i) for i in range(d)) for d in qid_shape))
    ]
    components = []
    ket = "|{}⟩"
    for x in range(len(perm_list)):
        format_str = "({:." + str(decimals) + "g})"
        val = round(state_vector[x].real, decimals) + 1j * round(state_vector[x].imag, decimals)
        if round(val.real, decimals) == 0 and round(val.imag, decimals) != 0:
            val = val.imag
            format_str = "{:." + str(decimals) + "g}j"
        elif round(val.imag, decimals) == 0 and round(val.real, decimals) != 0:
            val = val.real
            format_str = "{:." + str(decimals) + "g}"
        if val != 0:
            if (
                round(state_vector[x].real, decimals) == 1
                and round(state_vector[x].imag, decimals) == 0
            ):
                components.append(ket.format(perm_list[x]))
            else:
                components.append((format_str + ket).format(val, perm_list[x]))
    if not components:
        return '0'
    return ' + '.join(components).replace(' + -', ' - ')
def to_valid_state_vector(
    state_rep: cirq.STATE_VECTOR_LIKE,
    num_qubits: int | None = None,
    *,  # Force keyword arguments
    qid_shape: Sequence[int] | None = None,
    dtype: DTypeLike | None = None,
    atol: float = 1e-7,
) -> np.ndarray:
    if isinstance(state_rep, value.ProductState):
        num_qubits = len(state_rep)
    if num_qubits is None and qid_shape is None:
        try:
            qid_shape = infer_qid_shape(state_rep)
        except:
            raise ValueError(
                'Failed to infer the qid shape of the given state. '
                'Please specify the qid shape explicitly using either the '
                '`num_qubits` or `qid_shape` argument.'
            )
    if qid_shape is None:
        qid_shape = (2,) * cast(int, num_qubits)
    else:
        qid_shape = tuple(qid_shape)
    if num_qubits is None:
        num_qubits = len(qid_shape)
    if num_qubits != len(qid_shape):
        raise ValueError(
            f'num_qubits != len(qid_shape). num_qubits is <{num_qubits!r}>. '
            f'qid_shape is <{qid_shape!r}>.'
        )
    if isinstance(state_rep, np.ndarray):
        state_rep = np.copy(state_rep)
    state = quantum_state(state_rep, qid_shape, validate=True, dtype=dtype, atol=atol)
    return cast(np.ndarray, state.state_vector())
def _qudit_values_to_state_tensor(
    *, state_vector: np.ndarray, qid_shape: tuple[int, ...], dtype: DTypeLike | None
) -> np.ndarray:
    for i in range(len(qid_shape)):
        s = state_vector[i]
        q = qid_shape[i]
        if not 0 <= s < q:
            raise ValueError(
                f'Qudit value {s} at index {i} is out of bounds for '
                f'qudit dimension {q}.\n'
                f'\n'
                f'qid_shape={qid_shape!r}\n'
                f'state={state_vector!r}\n'
            )
    if state_vector.dtype.kind[0] not in '?bBiu':
        raise ValueError(  # pragma: no cover
            f'Expected a bool or int entry for each qudit in '
            f'`state`, because len(state) == len(qid_shape), '
            f'but got dtype {state_vector.dtype}.'
            f'\n'
            f'qid_shape={qid_shape!r}\n'
            f'state={state_vector!r}\n'
        )
    if dtype is None:
        dtype = DEFAULT_COMPLEX_DTYPE
    return one_hot(index=tuple(int(e) for e in state_vector), shape=qid_shape, dtype=dtype)
def validate_normalized_state_vector(
    state_vector: np.ndarray,
    *,  # Force keyword arguments
    qid_shape: tuple[int, ...],
    dtype: DTypeLike | None = None,
    atol: float = 1e-7,
) -> None:
    if dtype and state_vector.dtype != dtype:
        raise ValueError(
            f'state_vector has invalid dtype. Expected {dtype} but was {state_vector.dtype}'
        )
    if state_vector.size != np.prod(qid_shape, dtype=np.int64):
        raise ValueError(
            'state_vector has incorrect size. '
            f'Expected {np.prod(qid_shape, dtype=np.int64)} but was {state_vector.size}.'
        )
    norm = np.sum(np.abs(state_vector) ** 2)
    if not np.isclose(norm, 1, atol=atol):
        raise ValueError(f'State_vector is not normalized instead had norm {norm}')
def validate_qid_shape(
    state_vector: np.ndarray, qid_shape: tuple[int, ...] | None
) -> tuple[int, ...]:
    size = state_vector.size
    if qid_shape is None:
        qid_shape = (2,) * (size.bit_length() - 1)
    if size != np.prod(qid_shape, dtype=np.int64):
        raise ValueError(
            f'state_vector.size ({size}) is not a power of two or is not a product '
            f'of the qid shape {qid_shape!r}.'
        )
    return qid_shape
def validate_indices(num_qubits: int, indices: Sequence[int]) -> None:
    if any(index < 0 for index in indices):
        raise IndexError(f'Negative index in indices: {indices}')
    if any(index >= num_qubits for index in indices):
        raise IndexError(
            f'Out of range indices, must be less than number of qubits but was {indices}'
        )
def to_valid_density_matrix(
    density_matrix_rep: np.ndarray | cirq.STATE_VECTOR_LIKE,
    num_qubits: int | None = None,
    *,  # Force keyword arguments
    qid_shape: tuple[int, ...] | None = None,
    dtype: DTypeLike | None = None,
    atol: float = 1e-7,
) -> np.ndarray:
    qid_shape = _qid_shape_from_args(num_qubits, qid_shape)
    if isinstance(density_matrix_rep, np.ndarray):
        N = np.prod(qid_shape, dtype=np.int64)
        if len(qid_shape) > 1 and density_matrix_rep.shape == qid_shape * 2:
            density_matrix_rep = density_matrix_rep.reshape((N, N))
        if density_matrix_rep.shape == (N, N):
            validate_density_matrix(density_matrix_rep, qid_shape=qid_shape, dtype=dtype, atol=atol)
            return density_matrix_rep
    state_vector = to_valid_state_vector(
        density_matrix_rep, len(qid_shape), qid_shape=qid_shape, dtype=dtype
    )
    return np.outer(state_vector, np.conj(state_vector))
def validate_density_matrix(
    density_matrix: np.ndarray,
    *,  # Force keyword arguments
    qid_shape: tuple[int, ...],
    dtype: DTypeLike | None = None,
    atol: float = 1e-7,
) -> None:
    if dtype and density_matrix.dtype != dtype:
        raise ValueError(
            f'Incorrect dtype for density matrix: Expected {dtype} '
            f'but has dtype {density_matrix.dtype}.'
        )
    expected_shape = (np.prod(qid_shape, dtype=np.int64),) * 2
    if density_matrix.shape != expected_shape:
        raise ValueError(
            f'Incorrect shape for density matrix: Expected {expected_shape} '
            f'but has shape {density_matrix.shape}.'
        )
    if not np.allclose(density_matrix, density_matrix.conj().T, atol=atol):
        raise ValueError('The density matrix is not hermitian.')
    trace = np.trace(density_matrix)
    if not np.isclose(trace, 1.0, atol=atol):
        raise ValueError(f'Density matrix does not have trace 1. Instead, it has trace {trace}.')
    if not np.all(np.linalg.eigvalsh(density_matrix) > -atol):
        raise ValueError('The density matrix is not positive semidefinite.')
def _qid_shape_from_args(
    num_qubits: int | None, qid_shape: tuple[int, ...] | None
) -> tuple[int, ...]:
    if num_qubits is None and qid_shape is None:
        raise ValueError(
            'Either the num_qubits or qid_shape argument must be specified. Both were None.'
        )
    if num_qubits is None:
        return cast(tuple[int, ...], qid_shape)
    if qid_shape is None:
        return (2,) * num_qubits
    if len(qid_shape) != num_qubits:
        raise ValueError(
            f'num_qubits != len(qid_shape). num_qubits was {num_qubits!r}. '
            f'qid_shape was {qid_shape!r}.'
        )
    return qid_shape
def one_hot(
    *,
    index: None | int | Sequence[int] = None,
    shape: int | Sequence[int],
    value: Any = 1,
    dtype: DTypeLike,
) -> np.ndarray:
    if index is None:
        index = 0 if isinstance(shape, int) else (0,) * len(shape)
    result = np.zeros(shape=shape, dtype=dtype)
    result[index] = value
    return result
def eye_tensor(half_shape: tuple[int, ...], *, dtype: DTypeLike) -> np.ndarray:
    identity = np.eye(np.prod(half_shape, dtype=np.int64).item(), dtype=dtype)
    identity.shape = half_shape * 2
    return identity

from __future__ import annotations
from collections.abc import Sequence
from copy import copy, deepcopy
from typing import Any, Generic, TYPE_CHECKING
import numpy as np
from cirq import ops, qis, sim
from cirq.sim.simulation_state import SimulationState, TSimulationState
from cirq.value import big_endian_int_to_bits
if TYPE_CHECKING:
    import cirq
def _is_identity(action) -> bool:
    gate = action.gate if isinstance(action, ops.Operation) else action
    if isinstance(gate, (ops.XPowGate, ops.CXPowGate, ops.CCXPowGate, ops.SwapPowGate)):
        return gate.exponent % 2 == 0
    return False
class ClassicalBasisState(qis.QuantumStateRepresentation):
    def __init__(self, initial_state: list[int] | np.ndarray):
        self.basis = initial_state
    def copy(self, deep_copy_buffers: bool = True) -> ClassicalBasisState:
        return ClassicalBasisState(
            initial_state=deepcopy(self.basis) if deep_copy_buffers else copy(self.basis)
        )
    def measure(
        self, axes: Sequence[int], seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None
    ) -> list[int]:
        return [self.basis[i] for i in axes]
class ClassicalBasisSimState(SimulationState[ClassicalBasisState]):
    def __init__(
        self,
        initial_state: int | Sequence[int] = 0,
        qubits: Sequence[cirq.Qid] | None = None,
        classical_data: cirq.ClassicalDataStore | None = None,
    ):
        if isinstance(initial_state, int):
            if qubits is None:
                raise ValueError('qubits must be provided if initial_state is not Sequence[int]')
            state = ClassicalBasisState(
                big_endian_int_to_bits(initial_state, bit_count=len(qubits))
            )
        elif isinstance(initial_state, np.ndarray):
            if initial_state.ndim != 1:
                raise ValueError(
                    f'initial_state must be 1-dimensional, got shape {initial_state.shape}'
                )
            state = ClassicalBasisState(list(initial_state))
        elif isinstance(initial_state, Sequence) and not isinstance(initial_state, (str, bytes)):
            state = ClassicalBasisState(list(initial_state))
        else:
            raise ValueError('initial_state must be an int or Sequence[int]')
        super().__init__(state=state, qubits=qubits, classical_data=classical_data)
    def _act_on_fallback_(self, action, qubits: Sequence[cirq.Qid], allow_decompose: bool = True):
        gate = action.gate if isinstance(action, ops.Operation) else action
        mapped_qubits = [self.qubit_map[i] for i in qubits]
        if isinstance(gate, ops.ControlledGate):
            control_qubits = mapped_qubits[: gate.num_controls()]
            mapped_qubits = mapped_qubits[gate.num_controls() :]
            controls_state = tuple(self._state.basis[c] for c in control_qubits)
            if controls_state not in gate.control_values.expand():
                return True
            gate = gate.sub_gate
        if _is_identity(gate):
            pass
        elif gate == ops.X:
            (q,) = mapped_qubits
            self._state.basis[q] ^= 1
        elif gate == ops.CNOT:
            c, q = mapped_qubits
            self._state.basis[q] ^= self._state.basis[c]
        elif gate == ops.SWAP:
            a, b = mapped_qubits
            self._state.basis[a], self._state.basis[b] = self._state.basis[b], self._state.basis[a]
        elif gate == ops.TOFFOLI:
            c1, c2, q = mapped_qubits
            self._state.basis[q] ^= self._state.basis[c1] & self._state.basis[c2]
        elif isinstance(gate, ops.QubitPermutationGate):
            perm = gate.permutation
            basis = self._state.basis
            original_values = [basis[q] for q in mapped_qubits]
            for i, q in enumerate(mapped_qubits):
                basis[perm[i]] = original_values[i]
        else:
            raise ValueError(
                f'{gate} is not one of X, SWAP, QubitPermutationGate; a controlled version '
                'of X or SWAP; or a measurement'
            )
        return True
class ClassicalStateStepResult(
    sim.StepResultBase['ClassicalBasisSimState'], Generic[TSimulationState]
):
class ClassicalStateTrialResult(
    sim.SimulationTrialResultBase['ClassicalBasisSimState'], Generic[TSimulationState]
):
class ClassicalStateSimulator(
    sim.SimulatorBase[
        ClassicalStateStepResult['ClassicalBasisSimState'],
        ClassicalStateTrialResult['ClassicalBasisSimState'],
        'ClassicalBasisSimState',
    ],
    Generic[TSimulationState],
):
    def __init__(
        self, *, noise: cirq.NOISE_MODEL_LIKE = None, split_untangled_states: bool = False
    ):
        if noise is not None:
            raise ValueError(f'{noise=} is not supported')
        super().__init__(noise=noise, split_untangled_states=split_untangled_states)
    def _create_simulator_trial_result(
        self,
        params: cirq.ParamResolver,
        measurements: dict[str, np.ndarray],
        final_simulator_state: cirq.SimulationStateBase[ClassicalBasisSimState],
    ) -> ClassicalStateTrialResult[ClassicalBasisSimState]:
        return ClassicalStateTrialResult(
            params, measurements, final_simulator_state=final_simulator_state
        )
    def _create_step_result(
        self, sim_state: cirq.SimulationStateBase[ClassicalBasisSimState]
    ) -> ClassicalStateStepResult[ClassicalBasisSimState]:
        return ClassicalStateStepResult(sim_state)
    def _create_partial_simulation_state(
        self,
        initial_state: Any,
        qubits: Sequence[cirq.Qid],
        classical_data: cirq.ClassicalDataStore,
    ) -> ClassicalBasisSimState:
        return ClassicalBasisSimState(
            initial_state=initial_state, qubits=qubits, classical_data=classical_data
        )

from __future__ import annotations
from collections.abc import Callable, Sequence
from typing import Any, Self, TYPE_CHECKING
import numpy as np
