from __future__ import annotations
from collections.abc import Sequence
from typing import TYPE_CHECKING
import numpy as np
from cirq import linalg, value
from cirq.sim import simulation_utils
if TYPE_CHECKING:
    import cirq
def sample_density_matrix(
    density_matrix: np.ndarray,
    indices: Sequence[int],
    *,  # Force keyword arguments
    qid_shape: tuple[int, ...] | None = None,
    repetitions: int = 1,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> np.ndarray:
    if repetitions < 0:
        raise ValueError(f'Number of repetitions cannot be negative. Was {repetitions}')
    if qid_shape is None:
        num_qubits = _validate_num_qubits(density_matrix)
        qid_shape = (2,) * num_qubits
    else:
        _validate_density_matrix_qid_shape(density_matrix, qid_shape)
    meas_shape = _indices_shape(qid_shape, indices)
    if repetitions == 0 or len(indices) == 0:
        return np.zeros(shape=(repetitions, len(indices)), dtype=np.int8)
    prng = value.parse_random_state(seed)
    probs = _probs(density_matrix, indices, qid_shape)
    result = prng.choice(len(probs), size=repetitions, p=probs)
    return np.array(
        [value.big_endian_int_to_digits(result[i], base=meas_shape) for i in range(len(result))],
        dtype=np.int8,
    )
def measure_density_matrix(
    density_matrix: np.ndarray,
    indices: Sequence[int],
    qid_shape: tuple[int, ...] | None = None,
    out: np.ndarray | None = None,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> tuple[list[int], np.ndarray]:
    if qid_shape is None:
        num_qubits = _validate_num_qubits(density_matrix)
        qid_shape = (2,) * num_qubits
    else:
        _validate_density_matrix_qid_shape(density_matrix, qid_shape)
    meas_shape = _indices_shape(qid_shape, indices)
    arrout: np.ndarray
    if out is None:
        arrout = np.copy(density_matrix)
    elif out is density_matrix:
        arrout = density_matrix
    else:
        np.copyto(dst=out, src=density_matrix)
        arrout = out
    if len(indices) == 0:
        return ([], arrout)
    prng = value.parse_random_state(seed)
    initial_shape = density_matrix.shape
    probs = _probs(density_matrix, indices, qid_shape)
    result = prng.choice(len(probs), p=probs)
    measurement_bits = value.big_endian_int_to_digits(result, base=meas_shape)
    result_slice = linalg.slice_for_qubits_equal_to(
        indices, big_endian_qureg_value=result, qid_shape=qid_shape
    )
    mask = np.ones(qid_shape * 2, dtype=bool)
    mask[result_slice * 2] = False
    arrout.shape = qid_shape * 2
    arrout[mask] = 0
    arrout.shape = initial_shape
    arrout /= probs[result]
    return measurement_bits, arrout
def _probs(
    density_matrix: np.ndarray, indices: Sequence[int], qid_shape: tuple[int, ...]
) -> np.ndarray:
    all_probs = np.diagonal(np.reshape(density_matrix, (np.prod(qid_shape, dtype=np.int64),) * 2))
    return simulation_utils.state_probabilities_by_indices(all_probs.real, indices, qid_shape)
def _validate_density_matrix_qid_shape(
    density_matrix: np.ndarray, qid_shape: tuple[int, ...]
) -> tuple[int, ...]:
    shape = density_matrix.shape
    if len(shape) == 2:
        if np.prod(qid_shape, dtype=np.int64) ** 2 != np.prod(shape, dtype=np.int64):
            raise ValueError(
                f'Matrix size does not match qid shape {qid_shape!r}. Got matrix with '
                f'shape {shape!r}. Expected {np.prod(qid_shape, dtype=np.int64)!r}.'
            )
        return qid_shape
    if len(shape) % 2 != 0:
        raise ValueError(f'Tensor was not square. Shape was {shape}')
    left_shape = shape[: len(shape) // 2]
    right_shape = shape[len(shape) // 2 :]
    if left_shape != right_shape:
        raise ValueError(f"Tensor's left and right shape are not equal. Shape was {shape}")
    return left_shape
def _validate_num_qubits(density_matrix: np.ndarray) -> int:
    shape = density_matrix.shape
    half_index = len(shape) // 2
    row_size = np.prod(shape[:half_index]).item() if shape else 0
    col_size = np.prod(shape[half_index:]).item() if shape else 0
    if row_size != col_size:
        raise ValueError(f'Matrix was not square. Shape was {shape}')
    if row_size & (row_size - 1):
        raise ValueError(
            'Matrix could not be shaped into a square matrix with dimensions '
            f'that are a power of two. Shape was {shape}'
        )
    if len(shape) > 2 and not np.allclose(shape, 2):
        raise ValueError(
            'Matrix is a tensor of rank greater than 2, but had dimensions '
            f'that are not powers of two. Shape was {shape}'
        )
    return int(row_size).bit_length() - 1
def _indices_shape(qid_shape: tuple[int, ...], indices: Sequence[int]) -> tuple[int, ...]:
    if any(index < 0 for index in indices):
        raise IndexError(f'Negative index in indices: {indices}')
    if any(index >= len(qid_shape) for index in indices):
        raise IndexError(
            f'Out of range indices, must be less than number of qubits but was {indices}'
        )
    return tuple(qid_shape[i] for i in indices)

from __future__ import annotations
from collections.abc import Sequence
from typing import TYPE_CHECKING
import numpy as np
from cirq import circuits, devices, ops, protocols, study, value
from cirq._doc import document
from cirq.linalg import transformations
from cirq.sim import density_matrix_simulator, sparse_simulator
from cirq.sim.clifford import clifford_simulator
from cirq.transformers import measurement_transformers
if TYPE_CHECKING:
    import cirq
CIRCUIT_LIKE = circuits.Circuit | ops.Gate | ops.OP_TREE
document(
    CIRCUIT_LIKE,
    ,
)
def _is_clifford_circuit(program: cirq.Circuit) -> bool:
    return all(
        clifford_simulator.CliffordSimulator.is_supported_operation(op)
        for op in program.all_operations()
    )
def sample(
    program: cirq.Circuit,
    *,
    noise: cirq.NOISE_MODEL_LIKE = None,
    param_resolver: cirq.ParamResolver | None = None,
    repetitions: int = 1,
    dtype: type[np.complexfloating] = np.complex64,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> cirq.Result:
    noise_model = devices.NoiseModel.from_noise_model_like(noise)
    if noise_model == devices.NO_NOISE:
        if _is_clifford_circuit(program):
            return clifford_simulator.CliffordSimulator(seed=seed).run(
                program, param_resolver=param_resolver, repetitions=repetitions
            )
        if protocols.has_unitary(program):
            return sparse_simulator.Simulator(dtype=dtype, seed=seed).run(
                program=program, param_resolver=param_resolver, repetitions=repetitions
            )
    return density_matrix_simulator.DensityMatrixSimulator(
        dtype=dtype, noise=noise_model, seed=seed
    ).run(program=program, param_resolver=param_resolver, repetitions=repetitions)
def _to_circuit(program: cirq.CIRCUIT_LIKE) -> cirq.Circuit:
    if isinstance(program, circuits.Circuit):
        result = program
    elif isinstance(program, ops.Gate):
        result = circuits.Circuit(program.on(*devices.LineQid.for_gate(program)))
    else:
        result = circuits.Circuit(program)
    return result
def final_state_vector(
    program: cirq.CIRCUIT_LIKE,
    *,
    initial_state: cirq.STATE_VECTOR_LIKE = 0,
    param_resolver: cirq.ParamResolverOrSimilarType = None,
    qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
    ignore_terminal_measurements: bool = False,
    dtype: type[np.complexfloating] = np.complex64,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> np.ndarray:
    circuit_like = _to_circuit(program)
    if not ignore_terminal_measurements:
        if any(protocols.is_measurement(op) for op in circuit_like.all_operations()):
            raise ValueError('Circuit contains a measurement.')
    else:
        circuit_like = measurement_transformers.drop_terminal_measurements(circuit_like)
    if not protocols.has_unitary(protocols.resolve_parameters(circuit_like, param_resolver)):
        raise ValueError(
            "Program doesn't have a single well defined final state vector "
            "because it is not unitary. "
            "Maybe you wanted `cirq.final_density_matrix`?\n"
            "\n"
            f"Program: {circuit_like!r}"
        )
    result = sparse_simulator.Simulator(dtype=dtype, seed=seed).simulate(
        program=circuit_like,
        initial_state=initial_state,
        qubit_order=qubit_order,
        param_resolver=param_resolver,
    )
    return result.state_vector()
def sample_sweep(
    program: cirq.Circuit,
    params: cirq.Sweepable,
    *,
    noise: cirq.NOISE_MODEL_LIKE = None,
    repetitions: int = 1,
    dtype: type[np.complexfloating] = np.complex64,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> Sequence[cirq.Result]:
    prng = value.parse_random_state(seed)
    trial_results: list[study.Result] = []
    for param_resolver in study.to_resolvers(params):
        measurements = sample(
            program,
            noise=noise,
            param_resolver=param_resolver,
            repetitions=repetitions,
            dtype=dtype,
            seed=prng,
        )
        trial_results.append(measurements)
    return trial_results
def final_density_matrix(
    program: cirq.CIRCUIT_LIKE,
    *,
    noise: cirq.NOISE_MODEL_LIKE = None,
    initial_state: cirq.STATE_VECTOR_LIKE = 0,
    param_resolver: cirq.ParamResolverOrSimilarType = None,
    qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
    dtype: type[np.complexfloating] = np.complex64,
    seed: int | np.random.RandomState | None = None,
    ignore_measurement_results: bool = True,
) -> np.ndarray:
    noise_model = devices.NoiseModel.from_noise_model_like(noise)
    circuit_like = _to_circuit(program)
    can_do_unitary_simulation = True
    if not protocols.has_unitary(circuit_like):
        can_do_unitary_simulation = False
    if isinstance(circuit_like, circuits.Circuit):
        if circuit_like.has_measurements():
            can_do_unitary_simulation = False
    if noise_model != devices.NO_NOISE:
        can_do_unitary_simulation = False
    if can_do_unitary_simulation:
        sparse_result = sparse_simulator.Simulator(dtype=dtype, seed=seed).simulate(
            program=circuit_like,
            initial_state=initial_state,
            qubit_order=qubit_order,
            param_resolver=param_resolver,
        )
        return sparse_result.density_matrix_of()
    else:
        has_classical_control = circuit_like != measurement_transformers.defer_measurements(
            circuit_like
        )
        handling_classical_control = ignore_measurement_results and has_classical_control
        if handling_classical_control:
            noise_applied = circuit_like.with_noise(noise) if noise is not None else circuit_like
            defered = measurement_transformers.defer_measurements(noise_applied)
            dephased = measurement_transformers.dephase_measurements(defered)
            program = dephased
        elif ignore_measurement_results:
            program = measurement_transformers.dephase_measurements(circuit_like)
        else:
            program = circuit_like
        density_result = density_matrix_simulator.DensityMatrixSimulator(
            dtype=dtype, noise=None if handling_classical_control else noise, seed=seed
        ).simulate(
            program,
            initial_state=initial_state,
            qubit_order=qubit_order,
            param_resolver=param_resolver,
        )
        result = density_result.final_density_matrix
        if handling_classical_control:
            keep = list(range(protocols.num_qubits(circuit_like)))
            dephased_qid_shape = protocols.qid_shape(dephased)
            tensor_form = np.reshape(result, dephased_qid_shape + dephased_qid_shape)
            reduced_form = transformations.partial_trace(tensor_form, keep)
            width = np.prod(protocols.qid_shape(circuit_like))
            result = np.reshape(reduced_form, (width, width))
        return result

from __future__ import annotations
from collections import abc
from collections.abc import Iterator, Mapping, Sequence
from typing import Any, Generic, TYPE_CHECKING
import numpy as np
from cirq import ops, protocols, value
from cirq.sim.simulation_state import TSimulationState
from cirq.sim.simulation_state_base import SimulationStateBase
if TYPE_CHECKING:
    import cirq
class SimulationProductState(
    Generic[TSimulationState], SimulationStateBase[TSimulationState], abc.Mapping
):
    def __init__(
        self,
        sim_states: dict[cirq.Qid | None, TSimulationState],
        qubits: Sequence[cirq.Qid],
        split_untangled_states: bool,
        classical_data: cirq.ClassicalDataStore | None = None,
    ):
        classical_data = classical_data or value.ClassicalDataDictionaryStore()
        super().__init__(qubits=qubits, classical_data=classical_data)
        self._sim_states = sim_states
        self._split_untangled_states = split_untangled_states
    @property
    def sim_states(self) -> Mapping[cirq.Qid | None, TSimulationState]:
        return self._sim_states
    @property
    def split_untangled_states(self) -> bool:
        return self._split_untangled_states
    def create_merged_state(self) -> TSimulationState:
        merged_state = self.sim_states[None]
        if not self.split_untangled_states:
            return merged_state
        extra_states = set([self.sim_states[k] for k in self.sim_states.keys() if k is not None])
        if not extra_states:
            return merged_state
        merged_state = merged_state.copy(deep_copy_buffers=False)
        for state in extra_states:
            merged_state.kronecker_product(state, inplace=True)
        return merged_state.transpose_to_qubit_order(self.qubits, inplace=True)
    def _act_on_fallback_(
        self, action: Any, qubits: Sequence[cirq.Qid], allow_decompose: bool = True
    ) -> bool:
        gate_opt = (
            action
            if isinstance(action, ops.Gate)
            else action.gate if isinstance(action, ops.Operation) else None
        )
        if isinstance(gate_opt, ops.IdentityGate):
            return True
        if (
            isinstance(gate_opt, ops.SwapPowGate)
            and gate_opt.exponent % 2 == 1
            and gate_opt.global_shift == 0
        ):
            q0, q1 = qubits
            args0 = self.sim_states[q0]
            args1 = self.sim_states[q1]
            if args0 is args1:
                args0.swap(q0, q1, inplace=True)
            else:
                self._sim_states[q0] = args1.rename(q1, q0, inplace=True)
                self._sim_states[q1] = args0.rename(q0, q1, inplace=True)
            return True
        op_args_opt: TSimulationState | None = None
        for q in qubits:
            if op_args_opt is None:
                op_args_opt = self.sim_states[q]
            elif q not in op_args_opt.qubits:
                op_args_opt.kronecker_product(self.sim_states[q], inplace=True)
        op_args = op_args_opt or self.sim_states[None]
        for q in op_args.qubits:
            self._sim_states[q] = op_args
        act_on_qubits = qubits if isinstance(action, ops.Gate) else None
        protocols.act_on(action, op_args, act_on_qubits, allow_decompose=allow_decompose)
        if self.split_untangled_states and isinstance(
            gate_opt, (ops.ResetChannel, ops.MeasurementGate)
        ):
            for q in qubits:
                if op_args.allows_factoring and len(op_args.qubits) > 1:
                    q_args, _ = op_args.factor((q,), validate=False, inplace=True)
                    self._sim_states[q] = q_args
            for q in op_args.qubits:
                self._sim_states[q] = op_args
        return True
    def copy(self, deep_copy_buffers: bool = True) -> cirq.SimulationProductState[TSimulationState]:
        classical_data = self._classical_data.copy()
        copies = {}
        for sim_state in set(self.sim_states.values()):
            copies[sim_state] = sim_state.copy(deep_copy_buffers)
        for copy in copies.values():
            copy._classical_data = classical_data
        args = {q: copies[a] for q, a in self.sim_states.items()}
        return SimulationProductState(
            args, self.qubits, self.split_untangled_states, classical_data=classical_data
        )
    def sample(
        self,
        qubits: list[cirq.Qid],
        repetitions: int = 1,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ) -> np.ndarray:
        columns = []
        selected_order: list[ops.Qid] = []
        q_set = set(qubits)
        for v in dict.fromkeys(self.sim_states.values()):
            qs = [q for q in v.qubits if q in q_set]
            if any(qs):
                column = v.sample(qs, repetitions, seed)
                columns.append(column)
                selected_order += qs
        stacked = np.column_stack(columns)
        qubit_map = {q: i for i, q in enumerate(selected_order)}
        index_order = [qubit_map[q] for q in qubits]
        return stacked[:, index_order]
    def __getitem__(self, item: cirq.Qid | None) -> TSimulationState:
        return self.sim_states[item]
    def __len__(self) -> int:
        return len(self.sim_states)
    def __iter__(self) -> Iterator[cirq.Qid | None]:
        return iter(self.sim_states)

from __future__ import annotations
import abc
import copy
from collections.abc import Iterator, Sequence
from typing import Any, cast, Generic, Self, TYPE_CHECKING, TypeVar
import numpy as np
from cirq import ops, protocols, value
from cirq.sim.simulation_state_base import SimulationStateBase
TState = TypeVar('TState', bound='cirq.QuantumStateRepresentation')
if TYPE_CHECKING:
    import cirq
class SimulationState(SimulationStateBase, Generic[TState], metaclass=abc.ABCMeta):
    def __init__(
        self,
        *,
        state: TState,
        prng: np.random.RandomState | None = None,
        qubits: Sequence[cirq.Qid] | None = None,
        classical_data: cirq.ClassicalDataStore | None = None,
    ):
        if qubits is None:
            qubits = ()
        classical_data = classical_data or value.ClassicalDataDictionaryStore()
        super().__init__(qubits=qubits, classical_data=classical_data)
        if prng is None:
            prng = cast(np.random.RandomState, np.random)
        self._prng = prng
        self._state = state
    @property
    def prng(self) -> np.random.RandomState:
        return self._prng
    def measure(
        self,
        qubits: Sequence[cirq.Qid],
        key: str,
        invert_mask: Sequence[bool],
        confusion_map: dict[tuple[int, ...], np.ndarray],
    ) -> None:
        bits = self._perform_measurement(qubits)
        confused = self._confuse_result(bits, qubits, confusion_map)
        corrected = [bit ^ (bit < 2 and mask) for bit, mask in zip(confused, invert_mask)]
        self._classical_data.record_measurement(
            value.MeasurementKey.parse_serialized(key), corrected, qubits
        )
    def get_axes(self, qubits: Sequence[cirq.Qid]) -> list[int]:
        return [self.qubit_map[q] for q in qubits]
    def _perform_measurement(self, qubits: Sequence[cirq.Qid]) -> list[int]:
        if self._state is not None:
            return self._state.measure(self.get_axes(qubits), self.prng)
        raise NotImplementedError()
    def _confuse_result(
        self,
        bits: list[int],
        qubits: Sequence[cirq.Qid],
        confusion_map: dict[tuple[int, ...], np.ndarray],
    ):
        confused = list(bits)
        dims = [q.dimension for q in qubits]
        for indices, confuser in confusion_map.items():
            mat_dims = [dims[k] for k in indices]
            row = value.big_endian_digits_to_int((bits[k] for k in indices), base=mat_dims)
            new_val = self.prng.choice(len(confuser), p=confuser[row])
            new_bits = value.big_endian_int_to_digits(new_val, base=mat_dims)
            for i, k in enumerate(indices):
                confused[k] = new_bits[i]
        return confused
    def sample(
        self,
        qubits: Sequence[cirq.Qid],
        repetitions: int = 1,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ) -> np.ndarray:
        if self._state is not None:
            return self._state.sample(self.get_axes(qubits), repetitions, seed)
        raise NotImplementedError()
    def copy(self, deep_copy_buffers: bool = True) -> Self:
        args = copy.copy(self)
        args._classical_data = self._classical_data.copy()
        args._state = self._state.copy(deep_copy_buffers=deep_copy_buffers)
        return args
    def create_merged_state(self) -> Self:
        return self
    def add_qubits(self: Self, qubits: Sequence[cirq.Qid]) -> Self:
        if not qubits:
            return self
        return NotImplemented
    def remove_qubits(self: Self, qubits: Sequence[cirq.Qid]) -> Self:
        if not qubits:
            return self
        return NotImplemented
    def kronecker_product(self, other: Self, *, inplace=False) -> Self:
        args = self if inplace else copy.copy(self)
        args._state = self._state.kron(other._state)
        args._set_qubits(self.qubits + other.qubits)
        return args
    def factor(
        self, qubits: Sequence[cirq.Qid], *, validate=True, atol=1e-07, inplace=False
    ) -> tuple[Self, Self]:
        extracted = copy.copy(self)
        remainder = self if inplace else copy.copy(self)
        e, r = self._state.factor(self.get_axes(qubits), validate=validate, atol=atol)
        extracted._state = e
        remainder._state = r
        extracted._set_qubits(qubits)
        remainder._set_qubits([q for q in self.qubits if q not in qubits])
        return extracted, remainder
    @property
    def allows_factoring(self) -> bool:
        return self._state.supports_factor if self._state is not None else False
    def transpose_to_qubit_order(self, qubits: Sequence[cirq.Qid], *, inplace=False) -> Self:
        if len(self.qubits) != len(qubits) or set(qubits) != set(self.qubits):
            raise ValueError(f'Qubits do not match. Existing: {self.qubits}, provided: {qubits}')
        args = self if inplace else copy.copy(self)
        args._state = self._state.reindex(self.get_axes(qubits))
        args._set_qubits(qubits)
        return args
    @property
    def qubits(self) -> tuple[cirq.Qid, ...]:
        return self._qubits
    def swap(self, q1: cirq.Qid, q2: cirq.Qid, *, inplace=False) -> Self:
        if q1.dimension != q2.dimension:
            raise ValueError(f'Cannot swap different dimensions: q1={q1}, q2={q2}')
        args = self if inplace else copy.copy(self)
        i1 = self.qubits.index(q1)
        i2 = self.qubits.index(q2)
        qubits = list(args.qubits)
        qubits[i1], qubits[i2] = qubits[i2], qubits[i1]
        args._set_qubits(qubits)
        return args
    def rename(self, q1: cirq.Qid, q2: cirq.Qid, *, inplace=False) -> Self:
        if q1.dimension != q2.dimension:
            raise ValueError(f'Cannot rename to different dimensions: q1={q1}, q2={q2}')
        args = self if inplace else copy.copy(self)
        i1 = self.qubits.index(q1)
        qubits = list(args.qubits)
        qubits[i1] = q2
        args._set_qubits(qubits)
        return args
    def __getitem__(self, item: cirq.Qid | None) -> Self:
        if item not in self.qubit_map:
            raise IndexError(f'{item} not in {self.qubits}')
        return self
    def __len__(self) -> int:
        return len(self.qubits)
    def __iter__(self) -> Iterator[cirq.Qid | None]:
        return iter(self.qubits)
    @property
    def can_represent_mixed_states(self) -> bool:
        return self._state.can_represent_mixed_states if self._state is not None else False
def strat_act_on_from_apply_decompose(
    val: Any, args: cirq.SimulationState, qubits: Sequence[cirq.Qid]
) -> bool:
    if isinstance(val, ops.Gate):
        decomposed = protocols.decompose_once_with_qubits(val, qubits, flatten=False, default=None)
    else:
        decomposed = protocols.decompose_once(val, flatten=False, default=None)
    if decomposed is None:
        return NotImplemented
    all_ancilla: set[cirq.Qid] = set()
    for operation in ops.flatten_to_ops(decomposed):
        curr_ancilla = tuple(q for q in operation.qubits if q not in args.qubits)
        args = args.add_qubits(curr_ancilla)
        if args is NotImplemented:
            return NotImplemented  # pragma: no cover
        all_ancilla.update(curr_ancilla)
        protocols.act_on(operation, args)
    args = args.remove_qubits(tuple(all_ancilla))
    if args is NotImplemented:
        raise TypeError(f"{type(args)} implements add_qubits but not remove_qubits.")
    return True
TSimulationState = TypeVar('TSimulationState', bound=SimulationState)

