        return list(self.simulate_sweep_iter(program, params, qubit_order, initial_state))
    def _simulate_sweep_to_iter(
        self,
        program: cirq.AbstractCircuit,
        params: cirq.Sweepable,
        qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
        initial_state: Any = None,
    ) -> Iterator[TSimulationTrialResult]:
        if type(self).simulate_sweep == SimulatesFinalState.simulate_sweep:
            raise RecursionError("Must define either simulate_sweep or simulate_sweep_iter.")
        yield from self.simulate_sweep(program, params, qubit_order, initial_state)
    @value.alternative(requires='simulate_sweep', implementation=_simulate_sweep_to_iter)
    def simulate_sweep_iter(
        self,
        program: cirq.AbstractCircuit,
        params: cirq.Sweepable,
        qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
        initial_state: Any = None,
    ) -> Iterator[TSimulationTrialResult]:
        raise NotImplementedError()
class SimulatesIntermediateState(
    Generic[TStepResult, TSimulationTrialResult, TSimulatorState],
    SimulatesFinalState[TSimulationTrialResult],
    metaclass=abc.ABCMeta,
):
    def simulate_sweep_iter(
        self,
        program: cirq.AbstractCircuit,
        params: cirq.Sweepable,
        qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
        initial_state: Any = None,
    ) -> Iterator[TSimulationTrialResult]:
        qubit_order = ops.QubitOrder.as_qubit_order(qubit_order)
        resolvers = list(study.to_resolvers(params))
        for i, param_resolver in enumerate(resolvers):
            state = (
                initial_state.copy()
                if isinstance(initial_state, SimulationStateBase) and i < len(resolvers) - 1
                else initial_state
            )
            all_step_results = self.simulate_moment_steps(
                program, param_resolver, qubit_order, state
            )
            measurements: dict[str, np.ndarray] = {}
            for step_result in all_step_results:
                for k, v in step_result.measurements.items():
                    measurements[k] = np.array(v, dtype=np.uint8)
            yield self._create_simulator_trial_result(
                params=param_resolver,
                measurements=measurements,
                final_simulator_state=step_result._simulator_state(),
            )
    def simulate_moment_steps(
        self,
        circuit: cirq.AbstractCircuit,
        param_resolver: cirq.ParamResolverOrSimilarType = None,
        qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
        initial_state: Any = None,
    ) -> Iterator[TStepResult]:
        param_resolver = study.ParamResolver(param_resolver)
        resolved_circuit = protocols.resolve_parameters(circuit, param_resolver)
        check_all_resolved(resolved_circuit)
        actual_initial_state = 0 if initial_state is None else initial_state
        qubits = ops.QubitOrder.as_qubit_order(qubit_order).order_for(circuit.all_qubits())
        return self._base_iterator(resolved_circuit, qubits, actual_initial_state)
    @abc.abstractmethod
    def _base_iterator(
        self, circuit: cirq.AbstractCircuit, qubits: tuple[cirq.Qid, ...], initial_state: Any
    ) -> Iterator[TStepResult]:
    @abc.abstractmethod
    def _create_simulator_trial_result(
        self,
        params: cirq.ParamResolver,
        measurements: dict[str, np.ndarray],
        final_simulator_state: TSimulatorState,
    ) -> TSimulationTrialResult:
        raise NotImplementedError()
class StepResult(Generic[TSimulatorState], metaclass=abc.ABCMeta):
    def __init__(self, sim_state: TSimulatorState) -> None:
        self._sim_state = sim_state
        self._measurements = sim_state.log_of_measurement_results
    @property
    def measurements(self) -> Mapping[str, Sequence[int]]:
        return self._measurements
    def _simulator_state(self) -> TSimulatorState:
        return self._sim_state
    @abc.abstractmethod
    def sample(
        self,
        qubits: list[cirq.Qid],
        repetitions: int = 1,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ) -> np.ndarray:
        raise NotImplementedError()
    def sample_measurement_ops(
        self,
        measurement_ops: list[cirq.GateOperation],
        repetitions: int = 1,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
        *,
        _allow_repeated=False,
    ) -> dict[str, np.ndarray]:
        for op in measurement_ops:
            gate = op.gate
            if not isinstance(gate, ops.MeasurementGate):
                raise ValueError(f'{op.gate} was not a MeasurementGate')
        result = collections.Counter(
            key for op in measurement_ops for key in protocols.measurement_key_names(op)
        )
        if result and not _allow_repeated:
            duplicates = [k for k, v in result.most_common() if v > 1]
            if duplicates:
                raise ValueError(f"Measurement key {','.join(duplicates)} repeated")
        measured_qubits = []
        seen_qubits: set[cirq.Qid] = set()
        for op in measurement_ops:
            for q in op.qubits:
                if q not in seen_qubits:
                    seen_qubits.add(q)
                    measured_qubits.append(q)
        indexed_sample = self.sample(measured_qubits, repetitions, seed=seed)
        results: dict[str, Any] = {}
        qubits_to_index = {q: i for i, q in enumerate(measured_qubits)}
        for op in measurement_ops:
            gate = cast(ops.MeasurementGate, op.gate)
            key = gate.key
            out = np.zeros(shape=(repetitions, len(op.qubits)), dtype=np.int8)
            inv_mask = gate.full_invert_mask()
            cmap = gate.confusion_map
            for i, q in enumerate(op.qubits):
                out[:, i] = indexed_sample[:, qubits_to_index[q]]
                if inv_mask[i]:
                    out[:, i] ^= out[:, i] < 2
            self._confuse_results(out, op.qubits, cmap, seed)
            if _allow_repeated:
                if key not in results:
                    results[key] = []
                results[key].append(out)
            else:
                results[gate.key] = out
        return (
            results
            if not _allow_repeated
            else {k: np.array(v).swapaxes(0, 1) for k, v in results.items()}
        )
    def _confuse_results(
        self,
        bits: np.ndarray,
        qubits: Sequence[cirq.Qid],
        confusion_map: dict[tuple[int, ...], np.ndarray],
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ) -> None:
        prng = value.parse_random_state(seed)
        for rep in bits:
            dims = [q.dimension for q in qubits]
            for indices, confuser in confusion_map.items():
                mat_dims = [dims[k] for k in indices]
                row = value.big_endian_digits_to_int((rep[k] for k in indices), base=mat_dims)
                new_val = prng.choice(len(confuser), p=confuser[row])
                new_bits = value.big_endian_int_to_digits(new_val, base=mat_dims)
                for i, k in enumerate(indices):
                    rep[k] = new_bits[i]
@value.value_equality(unhashable=True)
class SimulationTrialResult(Generic[TSimulatorState]):
    def __init__(
        self,
        params: cirq.ParamResolver,
        measurements: Mapping[str, np.ndarray],
        final_simulator_state: TSimulatorState,
    ) -> None:
        self._params = params
        self._measurements = measurements
        self._final_simulator_state = final_simulator_state
    @property
    def params(self) -> cirq.ParamResolver:
        return self._params
    @property
    def measurements(self) -> Mapping[str, np.ndarray]:
        return self._measurements
    def __repr__(self) -> str:
        return (
            f'cirq.SimulationTrialResult(params={self.params!r}, '
            f'measurements={self.measurements!r}, '
            f'final_simulator_state={self._final_simulator_state!r})'
        )
    def __str__(self) -> str:
        def bitstring(vals):
            separator = ' ' if np.max(vals) >= 10 else ''
            return separator.join(str(v.item()) for v in vals)
        results = sorted([(key, bitstring(val)) for key, val in self.measurements.items()])
        if not results:
            return '(no measurements)'
        return ' '.join([f'{key}={val}' for key, val in results])
    def _repr_pretty_(self, p: Any, cycle: bool) -> None:
        if cycle:
            p.text('SimulationTrialResult(...)')
        else:
            p.text(str(self))
    def _value_equality_values_(self) -> Any:
        measurements = {k: v.tolist() for k, v in sorted(self.measurements.items())}
        return self.params, measurements, self._final_simulator_state
    @property
    def qubit_map(self) -> Mapping[cirq.Qid, int]:
        return self._final_simulator_state.qubit_map
    def _qid_shape_(self) -> tuple[int, ...]:
        return _qubit_map_to_shape(self.qubit_map)
def _qubit_map_to_shape(qubit_map: Mapping[cirq.Qid, int]) -> tuple[int, ...]:
    qid_shape: list[int] = [-1] * len(qubit_map)
    try:
        for q, i in qubit_map.items():
            qid_shape[i] = q.dimension
    except IndexError:
        raise ValueError(f'Invalid qubit_map. Qubit index out of bounds. Map is <{qubit_map!r}>.')
    if -1 in qid_shape:
        raise ValueError(f'Invalid qubit_map. Duplicate qubit index. Map is <{qubit_map!r}>.')
    return tuple(qid_shape)
def check_all_resolved(circuit) -> None:
    if protocols.is_parameterized(circuit):
        unresolved = [op for moment in circuit for op in moment if protocols.is_parameterized(op)]
        raise ValueError(
            'Circuit contains ops whose symbols were not specified in '
            f'parameter sweep. Ops: {unresolved}'
        )
def split_into_matching_protocol_then_general(
    circuit: cirq.AbstractCircuit, predicate: Callable[[cirq.Operation], bool]
) -> tuple[cirq.AbstractCircuit, cirq.AbstractCircuit]:
    blocked_qubits: set[cirq.Qid] = set()
    blocked_keys: set[cirq.MeasurementKey] = set()
    matching_prefix = circuits.Circuit()
    general_suffix = circuits.Circuit()
    for moment in circuit:
        matching_part = []
        general_part = []
        for op in moment:
            qs = set(op.qubits)
            keys = protocols.measurement_keys_touched(op)
            if predicate(op) and qs.isdisjoint(blocked_qubits) and keys.isdisjoint(blocked_keys):
                matching_part.append(op)
            else:
                blocked_qubits |= qs
                blocked_keys |= keys
                general_part.append(op)
        if matching_part:
            matching_prefix.append(circuits.Moment(matching_part))
        if general_part:
            general_suffix.append(circuits.Moment(general_part))
    return matching_prefix, general_suffix

from __future__ import annotations
import abc
import collections
from collections.abc import Iterator, Sequence
from typing import Any, cast, Generic, TYPE_CHECKING, TypeVar
import numpy as np
from cirq import devices, ops, protocols, study, value
from cirq.sim.simulation_product_state import SimulationProductState
from cirq.sim.simulation_state import TSimulationState
from cirq.sim.simulation_state_base import SimulationStateBase
from cirq.sim.simulator import (
    check_all_resolved,
    SimulatesIntermediateState,
    SimulatesSamples,
    SimulationTrialResult,
    split_into_matching_protocol_then_general,
    StepResult,
    TSimulationTrialResult,
)
if TYPE_CHECKING:
    import cirq
TStepResultBase = TypeVar('TStepResultBase', bound='StepResultBase')
class SimulatorBase(
    Generic[TStepResultBase, TSimulationTrialResult, TSimulationState],
    SimulatesIntermediateState[
        TStepResultBase, TSimulationTrialResult, SimulationStateBase[TSimulationState]
    ],
    SimulatesSamples,
    metaclass=abc.ABCMeta,
):
    def __init__(
        self,
        *,
        dtype: type[np.complexfloating] = np.complex64,
        noise: cirq.NOISE_MODEL_LIKE = None,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
        split_untangled_states: bool = False,
    ):
        self._dtype = dtype
        self._prng = value.parse_random_state(seed)
        self._noise = devices.NoiseModel.from_noise_model_like(noise)
        self._split_untangled_states = split_untangled_states
    @property
    def noise(self) -> cirq.NoiseModel:
        return self._noise
    @abc.abstractmethod
    def _create_partial_simulation_state(
        self,
        initial_state: Any,
        qubits: Sequence[cirq.Qid],
        classical_data: cirq.ClassicalDataStore,
    ) -> TSimulationState:
    @abc.abstractmethod
    def _create_step_result(
        self, sim_state: SimulationStateBase[TSimulationState]
    ) -> TStepResultBase:
    def _can_be_in_run_prefix(self, val: Any):
        return protocols.has_unitary(val)
    def _base_iterator(
        self, circuit: cirq.AbstractCircuit, qubits: tuple[cirq.Qid, ...], initial_state: Any
    ) -> Iterator[TStepResultBase]:
        sim_state = self._create_simulation_state(initial_state, qubits)
        return self._core_iterator(circuit, sim_state)
    def _core_iterator(
        self,
        circuit: cirq.AbstractCircuit,
        sim_state: SimulationStateBase[TSimulationState],
        all_measurements_are_terminal: bool = False,
    ) -> Iterator[TStepResultBase]:
        if len(circuit) == 0:
            yield self._create_step_result(sim_state)
            return
        noisy_moments = self.noise.noisy_moments(circuit, sorted(circuit.all_qubits()))
        measured: dict[tuple[cirq.Qid, ...], bool] = collections.defaultdict(bool)
        for moment in noisy_moments:
            for op in ops.flatten_to_ops(moment):
                try:
                    if all_measurements_are_terminal and measured[op.qubits]:
                        continue
                    if isinstance(op.gate, ops.MeasurementGate):
                        measured[op.qubits] = True
                        if all_measurements_are_terminal:
                            continue
                    protocols.act_on(op, sim_state)
                except TypeError:
                    raise TypeError(f"{self.__class__.__name__} doesn't support {op!r}")
            yield self._create_step_result(sim_state)
    def _run(
        self, circuit: cirq.AbstractCircuit, param_resolver: cirq.ParamResolver, repetitions: int
    ) -> dict[str, np.ndarray]:
        param_resolver = param_resolver or study.ParamResolver({})
        resolved_circuit = protocols.resolve_parameters(circuit, param_resolver)
        check_all_resolved(resolved_circuit)
        qubits = tuple(sorted(resolved_circuit.all_qubits()))
        sim_state = self._create_simulation_state(0, qubits)
        prefix, general_suffix = (
            split_into_matching_protocol_then_general(resolved_circuit, self._can_be_in_run_prefix)
            if self._can_be_in_run_prefix(self.noise)
            else (resolved_circuit[0:0], resolved_circuit)
        )
        step_result: TStepResultBase | None = None
        for step_result in self._core_iterator(circuit=prefix, sim_state=sim_state):
            pass
        assert step_result is not None
        general_ops = list(general_suffix.all_operations())
        if all(isinstance(op.gate, ops.MeasurementGate) for op in general_ops):
            for step_result in self._core_iterator(
                circuit=general_suffix, sim_state=sim_state, all_measurements_are_terminal=True
            ):
                pass
            assert step_result is not None
            measurement_ops = [cast(ops.GateOperation, op) for op in general_ops]
            return step_result.sample_measurement_ops(
                measurement_ops, repetitions, seed=self._prng, _allow_repeated=True
            )
        records: dict[cirq.MeasurementKey, list[Sequence[Sequence[int]]]] = {}
        for i in range(repetitions):
            for step_result in self._core_iterator(
                general_suffix,
                sim_state=(
                    sim_state.copy(deep_copy_buffers=False) if i < repetitions - 1 else sim_state
                ),
            ):
                pass
            for k, r in step_result._classical_data.records.items():
                if k not in records:
                    records[k] = []
                records[k].append(r)
            for k, cr in step_result._classical_data.channel_records.items():
                if k not in records:
                    records[k] = []
                records[k].append([cr])
        def pad_evenly(results: Sequence[Sequence[Sequence[int]]]):
            largest = max(len(result) for result in results)
            xs = np.zeros((len(results), largest, len(results[0][0])), dtype=np.uint8)
            for i, result in enumerate(results):
                xs[i, 0 : len(result), :] = result
            return xs
        return {str(k): pad_evenly(v) for k, v in records.items()}
    def simulate_sweep_iter(
        self,
        program: cirq.AbstractCircuit,
        params: cirq.Sweepable,
        qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
        initial_state: Any = None,
    ) -> Iterator[TSimulationTrialResult]:
        def sweep_prefixable(op: cirq.Operation):
            return self._can_be_in_run_prefix(op) and not protocols.is_parameterized(op)
        qubits = ops.QubitOrder.as_qubit_order(qubit_order).order_for(program.all_qubits())
        initial_state = 0 if initial_state is None else initial_state
        sim_state = self._create_simulation_state(initial_state, qubits)
        prefix, suffix = (
            split_into_matching_protocol_then_general(program, sweep_prefixable)
            if self._can_be_in_run_prefix(self.noise)
            else (program[0:0], program)
        )
        step_result: TStepResultBase | None = None
        for step_result in self._core_iterator(circuit=prefix, sim_state=sim_state):
            pass
        assert step_result is not None
        sim_state = step_result._sim_state
        yield from super().simulate_sweep_iter(suffix, params, qubit_order, sim_state)
    def _create_simulation_state(
        self, initial_state: Any, qubits: Sequence[cirq.Qid]
    ) -> SimulationStateBase[TSimulationState]:
        if isinstance(initial_state, SimulationStateBase):
            return initial_state
        classical_data = value.ClassicalDataDictionaryStore()
        if self._split_untangled_states:
            args_map: dict[cirq.Qid | None, TSimulationState] = {}
            if isinstance(initial_state, int):
                for q in reversed(qubits):
                    args_map[q] = self._create_partial_simulation_state(
                        initial_state=initial_state % q.dimension,
                        qubits=[q],
                        classical_data=classical_data,
                    )
                    initial_state = int(initial_state / q.dimension)
            else:
                args = self._create_partial_simulation_state(
                    initial_state=initial_state, qubits=qubits, classical_data=classical_data
                )
                for q in qubits:
                    args_map[q] = args
            args_map[None] = self._create_partial_simulation_state(0, (), classical_data)
            return SimulationProductState(
                args_map, qubits, self._split_untangled_states, classical_data=classical_data
            )
        else:
            return self._create_partial_simulation_state(
                initial_state=initial_state, qubits=qubits, classical_data=classical_data
            )
class StepResultBase(
    Generic[TSimulationState], StepResult[SimulationStateBase[TSimulationState]], abc.ABC
):
    def __init__(self, sim_state: SimulationStateBase[TSimulationState]):
        super().__init__(sim_state)
        self._merged_sim_state_cache: TSimulationState | None = None
        qubits = sim_state.qubits
        self._qubits = qubits
        self._qubit_mapping = {q: i for i, q in enumerate(qubits)}
        self._qubit_shape = tuple(q.dimension for q in qubits)
        self._classical_data = sim_state.classical_data
    def _qid_shape_(self):
        return self._qubit_shape
    @property
    def _merged_sim_state(self) -> TSimulationState:
        if self._merged_sim_state_cache is None:
            self._merged_sim_state_cache = self._sim_state.create_merged_state()
        return self._merged_sim_state_cache
    def sample(
        self,
        qubits: list[cirq.Qid],
        repetitions: int = 1,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ) -> np.ndarray:
        return self._sim_state.sample(qubits, repetitions, seed)
class SimulationTrialResultBase(
    SimulationTrialResult[SimulationStateBase[TSimulationState]], Generic[TSimulationState], abc.ABC
):
    def __init__(
        self,
        params: study.ParamResolver,
        measurements: dict[str, np.ndarray],
        final_simulator_state: cirq.SimulationStateBase[TSimulationState],
    ) -> None:
        super().__init__(params, measurements, final_simulator_state=final_simulator_state)
        self._merged_sim_state_cache: TSimulationState | None = None
    def get_state_containing_qubit(self, qubit: cirq.Qid) -> TSimulationState:
        return self._final_simulator_state[qubit]
    def _get_substates(self) -> Sequence[TSimulationState]:
        state = self._final_simulator_state
        if isinstance(state, SimulationProductState):
            substates: dict[TSimulationState, int] = {}
            for q in state.qubits:
                substates[self.get_state_containing_qubit(q)] = 0
            substates[state[None]] = 0
            return tuple(substates.keys())
        return [state.create_merged_state()]
    def _get_merged_sim_state(self) -> TSimulationState:
        if self._merged_sim_state_cache is None:
            self._merged_sim_state_cache = self._final_simulator_state.create_merged_state()
        return self._merged_sim_state_cache

from __future__ import annotations
import math
from collections.abc import Sequence
from typing import Any
import numpy as np
import pytest
import sympy
import cirq
class CountingState(cirq.qis.QuantumStateRepresentation):
    def __init__(self, data, gate_count=0, measurement_count=0, copy_count=0):
        self.data = data
        self.gate_count = gate_count
        self.measurement_count = measurement_count
        self.copy_count = copy_count
    def measure(
        self, axes: Sequence[int], seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None
    ) -> list[int]:
        self.measurement_count += 1
        return [self.gate_count]
    def kron(self, other: CountingState) -> CountingState:
        return CountingState(
            self.data,
            self.gate_count + other.gate_count,
            self.measurement_count + other.measurement_count,
            self.copy_count + other.copy_count,
        )
    def factor(
        self, axes: Sequence[int], *, validate=True, atol=1e-07
    ) -> tuple[CountingState, CountingState]:
        return CountingState(
            self.data, self.gate_count, self.measurement_count, self.copy_count
        ), CountingState(self.data)
    def reindex(self, axes: Sequence[int]) -> CountingState:
        return CountingState(self.data, self.gate_count, self.measurement_count, self.copy_count)
    def copy(self, deep_copy_buffers: bool = True) -> CountingState:
        return CountingState(
            self.data, self.gate_count, self.measurement_count, self.copy_count + 1
        )
class CountingSimulationState(cirq.SimulationState[CountingState]):
    def __init__(self, state, qubits, classical_data):
        state_obj = CountingState(state)
        super().__init__(state=state_obj, qubits=qubits, classical_data=classical_data)
    def _act_on_fallback_(
        self, action: Any, qubits: Sequence[cirq.Qid], allow_decompose: bool = True
    ) -> bool:
        self._state.gate_count += 1
        return True
    @property
    def data(self) -> Any:
        return self._state.data
    @property
    def gate_count(self) -> int:
        return self._state.gate_count
    @property
    def measurement_count(self) -> int:
        return self._state.measurement_count
    @property
    def copy_count(self) -> int:
        return self._state.copy_count
