from __future__ import annotations
import abc
from collections.abc import Mapping, Sequence
from typing import TYPE_CHECKING
import numpy as np
from cirq import linalg, qis, value
from cirq.sim import simulation_utils, simulator
if TYPE_CHECKING:
    import cirq
class StateVectorMixin:
    def __init__(self, qubit_map: Mapping[cirq.Qid, int] | None = None, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self._qubit_map = qubit_map or {}
        qid_shape = simulator._qubit_map_to_shape(self._qubit_map)
        self._qid_shape = None if qubit_map is None else qid_shape
    @property
    def qubit_map(self) -> Mapping[cirq.Qid, int]:
        return self._qubit_map
    def _qid_shape_(self) -> tuple[int, ...]:
        if self._qid_shape is None:
            return NotImplemented
        return self._qid_shape
    @abc.abstractmethod
    def state_vector(self, copy: bool = False) -> np.ndarray:
        raise NotImplementedError()
    def dirac_notation(self, decimals: int = 2) -> str:
        return qis.dirac_notation(self.state_vector(), decimals, qid_shape=self._qid_shape)
    def density_matrix_of(self, qubits: Sequence[cirq.Qid] | None = None) -> np.ndarray:
        r
        return qis.density_matrix_from_state_vector(
            self.state_vector(),
            [self.qubit_map[q] for q in qubits] if qubits is not None else None,
            qid_shape=self._qid_shape,
        )
    def bloch_vector_of(self, qubit: cirq.Qid) -> np.ndarray:
        return qis.bloch_vector_from_state_vector(
            self.state_vector(), self.qubit_map[qubit], qid_shape=self._qid_shape
        )
def sample_state_vector(
    state_vector: np.ndarray,
    indices: Sequence[int],
    *,  # Force keyword args
    qid_shape: tuple[int, ...] | None = None,
    repetitions: int = 1,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> np.ndarray:
    if repetitions < 0:
        raise ValueError(f'Number of repetitions cannot be negative. Was {repetitions}')
    shape = qis.validate_qid_shape(state_vector, qid_shape)
    num_qubits = len(shape)
    qis.validate_indices(num_qubits, indices)
    if repetitions == 0 or len(indices) == 0:
        return np.zeros(shape=(repetitions, len(indices)), dtype=np.uint8)
    prng = value.parse_random_state(seed)
    probs = (state_vector * state_vector.conj()).real
    probs = simulation_utils.state_probabilities_by_indices(probs, indices, shape)
    result = prng.choice(len(probs), size=repetitions, p=probs)
    meas_shape = tuple(shape[i] for i in indices)
    return np.array(
        [value.big_endian_int_to_digits(result[i], base=meas_shape) for i in range(len(result))],
        dtype=np.uint8,
    )
def measure_state_vector(
    state_vector: np.ndarray,
    indices: Sequence[int],
    *,  # Force keyword args
    qid_shape: tuple[int, ...] | None = None,
    out: np.ndarray | None = None,
    seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> tuple[list[int], np.ndarray]:
    shape = qis.validate_qid_shape(state_vector, qid_shape)
    num_qubits = len(shape)
    qis.validate_indices(num_qubits, indices)
    if len(indices) == 0:
        if out is None:
            out = np.copy(state_vector)
        elif out is not state_vector:
            np.copyto(dst=out, src=state_vector)
        return ([], out)
    prng = value.parse_random_state(seed)
    initial_shape = state_vector.shape
    probs = (state_vector * state_vector.conj()).real
    probs = simulation_utils.state_probabilities_by_indices(probs, indices, shape)
    result = prng.choice(len(probs), p=probs)
    meas_shape = tuple(shape[i] for i in indices)
    measurement_bits = value.big_endian_int_to_digits(result, base=meas_shape)
    result_slice = linalg.slice_for_qubits_equal_to(
        indices, big_endian_qureg_value=result, qid_shape=shape
    )
    mask = np.ones(shape, dtype=bool)
    mask[result_slice] = False
    if out is None:
        out = np.copy(state_vector)
    elif out is not state_vector:
        np.copyto(dst=out, src=state_vector)
    out.shape = shape
    out[mask] = 0
    out.shape = initial_shape
    out /= np.sqrt(probs[result])
    assert out is not None
    return measurement_bits, out

from __future__ import annotations
from collections.abc import Callable, Sequence
from typing import Any, Self, TYPE_CHECKING
import numpy as np
from cirq import linalg, protocols, qis, sim
from cirq._compat import proper_repr
from cirq.linalg import transformations
from cirq.sim.simulation_state import SimulationState, strat_act_on_from_apply_decompose
if TYPE_CHECKING:
    import cirq
class _BufferedStateVector(qis.QuantumStateRepresentation):
    def __init__(self, state_vector: np.ndarray, buffer: np.ndarray | None = None):
        self._state_vector = state_vector
        if buffer is None:
            buffer = np.empty_like(state_vector)
        self._buffer = buffer
        self._qid_shape = state_vector.shape
    @classmethod
    def create(
        cls,
        *,
        initial_state: np.ndarray | cirq.STATE_VECTOR_LIKE = 0,
        qid_shape: tuple[int, ...] | None = None,
        dtype: type[np.complexfloating] | np.dtype[np.complexfloating] | None = None,
        buffer: np.ndarray | None = None,
    ):
        if not isinstance(initial_state, np.ndarray):
            if qid_shape is None:
                raise ValueError('qid_shape must be provided if initial_state is not ndarray')
            state_vector = qis.to_valid_state_vector(
                initial_state, len(qid_shape), qid_shape=qid_shape, dtype=dtype
            ).reshape(qid_shape)
        else:
            if qid_shape is not None:
                state_vector = initial_state.reshape(qid_shape)
            else:
                state_vector = initial_state
            if np.may_share_memory(state_vector, initial_state):
                state_vector = state_vector.copy()
        state_vector = state_vector.astype(dtype, copy=False)
        return cls(state_vector, buffer)
    def copy(self, deep_copy_buffers: bool = True) -> _BufferedStateVector:
        return _BufferedStateVector(
            state_vector=self._state_vector.copy(),
            buffer=self._buffer.copy() if deep_copy_buffers else self._buffer,
        )
    def kron(self, other: _BufferedStateVector) -> _BufferedStateVector:
        target_tensor = transformations.state_vector_kronecker_product(
            self._state_vector, other._state_vector
        )
        return _BufferedStateVector(state_vector=target_tensor, buffer=np.empty_like(target_tensor))
    def factor(
        self, axes: Sequence[int], *, validate=True, atol=1e-07
    ) -> tuple[_BufferedStateVector, _BufferedStateVector]:
        extracted_tensor, remainder_tensor = transformations.factor_state_vector(
            self._state_vector, axes, validate=validate, atol=atol
        )
        extracted = _BufferedStateVector(
            state_vector=extracted_tensor, buffer=np.empty_like(extracted_tensor)
        )
        remainder = _BufferedStateVector(
            state_vector=remainder_tensor, buffer=np.empty_like(remainder_tensor)
        )
        return extracted, remainder
    def reindex(self, axes: Sequence[int]) -> _BufferedStateVector:
        new_tensor = transformations.transpose_state_vector_to_axis_order(self._state_vector, axes)
        return _BufferedStateVector(state_vector=new_tensor, buffer=np.empty_like(new_tensor))
    def apply_unitary(self, action: Any, axes: Sequence[int]) -> bool:
        new_target_tensor = protocols.apply_unitary(
            action,
            protocols.ApplyUnitaryArgs(
                target_tensor=self._state_vector, available_buffer=self._buffer, axes=axes
            ),
            allow_decompose=False,
            default=NotImplemented,
        )
        if new_target_tensor is NotImplemented:
            return False
        self._swap_target_tensor_for(new_target_tensor)
        return True
    def apply_mixture(self, action: Any, axes: Sequence[int], prng) -> int | None:
        mixture = protocols.mixture(action, default=None)
        if mixture is None:
            return None
        probabilities, unitaries = zip(*mixture)
        index = prng.choice(range(len(unitaries)), p=probabilities)
        shape = protocols.qid_shape(action) * 2
        unitary = unitaries[index].astype(self._state_vector.dtype).reshape(shape)
        linalg.targeted_left_multiply(unitary, self._state_vector, axes, out=self._buffer)
        self._swap_target_tensor_for(self._buffer)
        return index
    def apply_channel(self, action: Any, axes: Sequence[int], prng) -> int | None:
        kraus_operators = protocols.kraus(action, default=None)
        if kraus_operators is None:
            return None
        def prepare_into_buffer(k: int):
            linalg.targeted_left_multiply(
                left_matrix=kraus_tensors[k],
                right_target=self._state_vector,
                target_axes=axes,
                out=self._buffer,
            )
        shape = protocols.qid_shape(action)
        kraus_tensors = [
            e.reshape(shape * 2).astype(self._state_vector.dtype) for e in kraus_operators
        ]
        p = prng.random()
        fallback_weight = 0.0
        fallback_weight_index = 0
        for index in range(len(kraus_tensors)):
            prepare_into_buffer(index)
            weight = float(np.linalg.norm(self._buffer) ** 2)
            if weight > fallback_weight:
                fallback_weight_index = index
                fallback_weight = weight
            p -= weight
            if p < 0:
                break
        assert weight is not None, "No Kraus operators"
        if p >= 0 or weight == 0:
            prepare_into_buffer(fallback_weight_index)
            weight = fallback_weight
            index = fallback_weight_index
        self._buffer /= np.sqrt(weight)
        self._swap_target_tensor_for(self._buffer)
        return index
    def measure(
        self, axes: Sequence[int], seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None
    ) -> list[int]:
        bits, _ = sim.measure_state_vector(
            self._state_vector, axes, out=self._state_vector, qid_shape=self._qid_shape, seed=seed
        )
        return bits
    def sample(
        self, axes: Sequence[int], repetitions: int = 1, seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None
    ) -> np.ndarray:
        return sim.sample_state_vector(
            self._state_vector, axes, qid_shape=self._qid_shape, repetitions=repetitions, seed=seed
        )
    def _swap_target_tensor_for(self, new_target_tensor: np.ndarray):
        if new_target_tensor is self._buffer:
            self._buffer = self._state_vector
        self._state_vector = new_target_tensor
    @property
    def supports_factor(self) -> bool:
        return True
class StateVectorSimulationState(SimulationState[_BufferedStateVector]):
    def __init__(
        self,
        *,
        available_buffer: np.ndarray | None = None,
        prng: np.random.RandomState | None = None,
        qubits: Sequence[cirq.Qid] | None = None,
        initial_state: np.ndarray | cirq.STATE_VECTOR_LIKE = 0,
        dtype: type[np.complexfloating] | np.dtype[np.complexfloating] = np.complex64,
        classical_data: cirq.ClassicalDataStore | None = None,
    ):
        state = _BufferedStateVector.create(
            initial_state=initial_state,
            qid_shape=tuple(q.dimension for q in qubits) if qubits is not None else None,
            dtype=dtype,
            buffer=available_buffer,
        )
        super().__init__(state=state, prng=prng, qubits=qubits, classical_data=classical_data)
    def add_qubits(self, qubits: Sequence[cirq.Qid]) -> Self:
        ret = super().add_qubits(qubits)
        return (
            self.kronecker_product(type(self)(qubits=qubits), inplace=True)
            if ret is NotImplemented
            else ret
        )
    def remove_qubits(self, qubits: Sequence[cirq.Qid]) -> Self:
        ret = super().remove_qubits(qubits)
        if ret is not NotImplemented:
            return ret
        extracted, remainder = self.factor(qubits, inplace=True)
        remainder._state._state_vector *= extracted._state._state_vector.reshape((-1,))[0]
        return remainder
    def _act_on_fallback_(
        self, action: Any, qubits: Sequence[cirq.Qid], allow_decompose: bool = True
    ) -> bool:
        strats: list[Callable[[Any, Any, Sequence[cirq.Qid]], bool]] = [
            _strat_act_on_state_vector_from_apply_unitary,
            _strat_act_on_state_vector_from_mixture,
            _strat_act_on_state_vector_from_channel,
        ]
        if allow_decompose:
            strats.append(strat_act_on_from_apply_decompose)
        for strat in strats:
            result = strat(action, self, qubits)
            if result is False:
                break  # pragma: no cover
            if result is True:
                return True
            assert result is NotImplemented, str(result)
        raise TypeError(
            "Can't simulate operations that don't implement "
            "SupportsUnitary, SupportsConsistentApplyUnitary, "
            f"SupportsMixture or is a measurement: {action!r}"
        )
    def __repr__(self) -> str:
        return (
            'cirq.StateVectorSimulationState('
            f'initial_state={proper_repr(self.target_tensor)},'
            f' qubits={self.qubits!r},'
            f' classical_data={self.classical_data!r})'
        )
    @property
    def target_tensor(self) -> np.ndarray:
        return self._state._state_vector
    @property
    def available_buffer(self) -> np.ndarray:
        return self._state._buffer
def _strat_act_on_state_vector_from_apply_unitary(
    action: Any, args: cirq.StateVectorSimulationState, qubits: Sequence[cirq.Qid]
) -> bool:
    if not args._state.apply_unitary(action, args.get_axes(qubits)):
        return NotImplemented
    return True
def _strat_act_on_state_vector_from_mixture(
    action: Any, args: cirq.StateVectorSimulationState, qubits: Sequence[cirq.Qid]
) -> bool:
    index = args._state.apply_mixture(action, args.get_axes(qubits), args.prng)
    if index is None:
        return NotImplemented
    if protocols.is_measurement(action):
        key = protocols.measurement_key_obj(action)
        args._classical_data.record_channel_measurement(key, index)
    return True
def _strat_act_on_state_vector_from_channel(
    action: Any, args: cirq.StateVectorSimulationState, qubits: Sequence[cirq.Qid]
) -> bool:
    index = args._state.apply_channel(action, args.get_axes(qubits), args.prng)
    if index is None:
        return NotImplemented
    if protocols.is_measurement(action):
        key = protocols.measurement_key_obj(action)
        args._classical_data.record_channel_measurement(key, index)
    return True

from __future__ import annotations
import abc
import warnings
from collections.abc import Iterator, Sequence
from functools import cached_property
from typing import Any, Generic, TYPE_CHECKING, TypeVar
import numpy as np
from cirq import _compat, ops, qis, value
from cirq.protocols import qid_shape
from cirq.sim import simulator, simulator_base, state_vector
if TYPE_CHECKING:
    import cirq
TStateVectorStepResult = TypeVar('TStateVectorStepResult', bound='StateVectorStepResult')
class SimulatesIntermediateStateVector(
    Generic[TStateVectorStepResult],
    simulator_base.SimulatorBase[
        TStateVectorStepResult, 'cirq.StateVectorTrialResult', 'cirq.StateVectorSimulationState'
    ],
    simulator.SimulatesAmplitudes,
    metaclass=abc.ABCMeta,
):
    def __init__(
        self,
        *,
        dtype: type[np.complexfloating] = np.complex64,
        noise: cirq.NOISE_MODEL_LIKE = None,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
        split_untangled_states: bool = False,
    ):
        super().__init__(
            dtype=dtype, noise=noise, seed=seed, split_untangled_states=split_untangled_states
        )
    def _create_simulator_trial_result(
        self,
        params: cirq.ParamResolver,
        measurements: dict[str, np.ndarray],
        final_simulator_state: cirq.SimulationStateBase[cirq.StateVectorSimulationState],
    ) -> cirq.StateVectorTrialResult:
        return StateVectorTrialResult(
            params=params, measurements=measurements, final_simulator_state=final_simulator_state
        )
    def compute_amplitudes_sweep_iter(
        self,
        program: cirq.AbstractCircuit,
        bitstrings: Sequence[int],
        params: cirq.Sweepable,
        qubit_order: cirq.QubitOrderOrList = ops.QubitOrder.DEFAULT,
    ) -> Iterator[Sequence[complex]]:
        if isinstance(bitstrings, np.ndarray) and len(bitstrings.shape) > 1:
            raise ValueError(
                'The list of bitstrings must be input as a '
                '1-dimensional array of ints. Got an array with '
                f'shape {bitstrings.shape}.'
            )
        if isinstance(bitstrings, tuple):
            bitstrings = list(bitstrings)
        trial_result_iter = self.simulate_sweep_iter(program, params, qubit_order)
        yield from (
            trial_result.final_state_vector[bitstrings].tolist()
            for trial_result in trial_result_iter
        )
class StateVectorStepResult(
    simulator_base.StepResultBase['cirq.StateVectorSimulationState'], metaclass=abc.ABCMeta
):
    pass
@value.value_equality(unhashable=True)
class StateVectorTrialResult(
    state_vector.StateVectorMixin,
    simulator_base.SimulationTrialResultBase['cirq.StateVectorSimulationState'],
):
    def __init__(
        self,
        params: cirq.ParamResolver,
        measurements: dict[str, np.ndarray],
        final_simulator_state: cirq.SimulationStateBase[cirq.StateVectorSimulationState],
    ) -> None:
        super().__init__(
            params=params,
            measurements=measurements,
            final_simulator_state=final_simulator_state,
            qubit_map=final_simulator_state.qubit_map,
        )
    @cached_property
    def final_state_vector(self) -> np.ndarray:
        ret = self._get_merged_sim_state().target_tensor.reshape(-1)
        norm = np.linalg.norm(ret)
        if abs(norm - 1) > np.sqrt(np.finfo(ret.dtype).eps):
            warnings.warn(
                f"final state vector's {norm=} is too far from 1,"
                f" {abs(norm-1)} > {np.sqrt(np.finfo(ret.dtype).eps)}."
                "skipping renormalization"
            )
            return ret
        ret_norm = ret / norm
        round_off_change = abs(np.vdot(ret_norm, ret_norm) - 1) - abs(np.vdot(ret, ret) - 1)
        result = ret_norm if round_off_change < 0 else ret
        return result
    def state_vector(self, copy: bool = False) -> np.ndarray:
        return self.final_state_vector.copy() if copy else self.final_state_vector
    def _value_equality_values_(self):
        measurements = {k: v.tolist() for k, v in sorted(self.measurements.items())}
        return self.params, measurements, self.qubit_map, self.final_state_vector.tolist()
    def __str__(self) -> str:
        samples = super().__str__()
        ret = f'measurements: {samples}'
        for substate in self._get_substates():
            final = substate.target_tensor
            shape = final.shape
            size = np.prod(shape, dtype=np.int64)
            final = final.reshape(size)
            if len([1 for e in final if abs(e) > 0.001]) < 16:
                state_vector = qis.dirac_notation(final, 3, qid_shape(substate.qubits))
            else:
                state_vector = str(final)
            label = f'qubits: {substate.qubits}' if substate.qubits else 'phase:'
            ret += f'\n\n{label}\noutput vector: {state_vector}'
        return ret
    def _repr_pretty_(self, p: Any, cycle: bool):
        if cycle:
            p.text('StateVectorTrialResult(...)')
        else:
            p.text(str(self))
    def __repr__(self) -> str:
        return (
            'cirq.StateVectorTrialResult('
            f'params={self.params!r}, measurements={_compat.proper_repr(self.measurements)}, '
            f'final_simulator_state={self._final_simulator_state!r})'
        )

