    val: Any, params: resolver.ParamResolverOrSimilarType
) -> tuple[Any, resolver.ParamDictType]:
    val_flat, expr_map = flatten(val)
    new_params = expr_map.transform_params(params)
    return val_flat, new_params
class _ParamFlattener(resolver.ParamResolver):
    def __new__(cls, *args, **kwargs):
        return super().__new__(cls)
    def __init__(
        self,
        param_dict: resolver.ParamResolverOrSimilarType | None = None,
        *,  # Force keyword args
        get_param_name: Callable[[sympy.Expr], str] | None = None,
    ):
        if hasattr(self, '_taken_symbols'):
            return
        if isinstance(param_dict, resolver.ParamResolver):
            params = param_dict.param_dict
        else:
            params = param_dict if param_dict else {}
        symbol_params: resolver.ParamDictType = {
            _ensure_not_str(param): _ensure_not_str(val) for param, val in params.items()
        }
        super().__init__(symbol_params)
        if get_param_name is None:
            get_param_name = self.default_get_param_name
        self.get_param_name = get_param_name
        self._taken_symbols = set(self.param_dict.values())
    @staticmethod
    def default_get_param_name(val: sympy.Expr) -> str:
        if isinstance(val, sympy.Symbol):
            return val.name
        return f'<{val!s}>'
    def _next_symbol(self, val: sympy.Expr) -> sympy.Symbol:
        name = self.get_param_name(val)
        symbol = sympy.Symbol(name)
        collision = 0
        while symbol in self._taken_symbols:
            collision += 1
            symbol = sympy.Symbol(f'{name}_{collision}')
        return symbol
    def value_of(
        self, value: cirq.TParamKey | cirq.TParamValComplex, recursive: bool = False
    ) -> cirq.TParamValComplex:
        if isinstance(value, numbers.Complex):
            return value
        if isinstance(value, str):
            value = sympy.Symbol(value)
        out = self.param_dict.get(value, None)
        if out is not None:
            return out
        symbol = self._next_symbol(value)
        self._param_dict[value] = symbol
        self._taken_symbols.add(symbol)
        return symbol
    __eq__ = object.__eq__
    __ne__ = object.__ne__
    __hash__ = object.__hash__
    def __bool__(self) -> bool:
        return True
    def __repr__(self) -> str:
        if self.get_param_name == self.default_get_param_name:
            return f'_ParamFlattener({self._param_dict!r})'
        else:
            return f'_ParamFlattener({self._param_dict!r}, get_param_name={self.get_param_name!r})'
    def flatten(self, val: Any) -> Any:
        return protocols.resolve_parameters(val, self)
class ExpressionMap(dict):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
    def transform_sweep(self, sweep: sweeps.Sweep | list[resolver.ParamResolver]) -> sweeps.Sweep:
        sweep = sweepable.to_sweep(sweep)
        param_list: list[resolver.ParamDictType] = []
        for r in sweep:
            param_dict: resolver.ParamDictType = {}
            for formula, sym in self.items():
                if isinstance(sym, (sympy.Symbol, str)):
                    param_dict[str(sym)] = protocols.resolve_parameters(formula, r)
            param_list.append(param_dict)
        return sweeps.ListSweep(param_list)
    def transform_params(
        self, params: resolver.ParamResolverOrSimilarType
    ) -> resolver.ParamDictType:
        param_dict: resolver.ParamDictType = {
            sym: protocols.resolve_parameters(formula, params)
            for formula, sym in self.items()
            if isinstance(sym, sympy.Expr)
        }
        return param_dict
    def __repr__(self) -> str:
        super_repr = super().__repr__()
        return f'cirq.ExpressionMap({super_repr})'
def _ensure_not_str(
    param: sympy.Expr | cirq.TParamValComplex | str,
) -> sympy.Expr | cirq.TParamValComplex:
    if isinstance(param, str):
        return sympy.Symbol(param)
    return param

from __future__ import annotations
import numbers
from collections.abc import Iterator, Mapping
from typing import Any, cast, TYPE_CHECKING, Union
import numpy as np
import sympy
from sympy.core import numbers as sympy_numbers
from cirq._compat import proper_repr
from cirq._doc import document
if TYPE_CHECKING:
    import cirq
ParamDictType = dict['cirq.TParamKey', 'cirq.TParamValComplex']
ParamMappingType = Mapping['cirq.TParamKey', 'cirq.TParamValComplex']
document(ParamDictType, )
document(ParamMappingType, )
ParamResolverOrSimilarType = Union['cirq.ParamResolver', ParamMappingType, None]
document(
    ParamResolverOrSimilarType, 
)
_NOT_FOUND = object()
_RECURSION_FLAG = object()
class ParamResolver:
    def __new__(cls, param_dict: cirq.ParamResolverOrSimilarType = None):
        if isinstance(param_dict, ParamResolver):
            return param_dict
        return super().__new__(cls)
    def __init__(self, param_dict: cirq.ParamResolverOrSimilarType = None) -> None:
        if hasattr(self, 'param_dict'):
            return  # Already initialized. Got wrapped as part of the __new__.
        self._param_hash: int | None = None
        self._param_dict = cast(ParamDictType, {} if param_dict is None else param_dict)
        self._param_dict_with_str_keys = self._param_dict
        generate_str_keys = False
        for key in self._param_dict:
            if isinstance(key, sympy.Expr):
                if isinstance(key, sympy.Symbol):
                    generate_str_keys = True
                else:
                    raise TypeError(f'ParamResolver keys cannot be (non-symbol) formulas ({key})')
        if generate_str_keys:
            self._param_dict_with_str_keys = {
                (key.name if isinstance(key, sympy.Symbol) else key): value
                for key, value in self._param_dict.items()
            }
        self._deep_eval_map: ParamDictType = {}
    @property
    def param_dict(self) -> ParamMappingType:
        return self._param_dict
    def value_of(
        self, value: cirq.TParamKey | cirq.TParamValComplex, recursive: bool = True
    ) -> cirq.TParamValComplex:
        original_value = value
        if isinstance(value, sympy.Symbol):
            value = value.name
        if isinstance(value, str):
            param_value = self._param_dict_with_str_keys.get(value, _NOT_FOUND)
            if isinstance(param_value, float):
                return param_value
            if param_value is _NOT_FOUND:
                return sympy.Symbol(value)
            v = _resolve_value(param_value)
            if v is not NotImplemented:
                return v
            if isinstance(param_value, str):
                param_value = sympy.Symbol(param_value)
            elif not isinstance(param_value, sympy.Basic):
                return original_value
            if recursive:
                param_value = self._value_of_recursive(value)
            return param_value
        v = _resolve_value(value)
        if v is not NotImplemented:
            return v
        if not isinstance(value, sympy.Basic):
            return value
        if isinstance(value, sympy.Float):
            return float(value)
        if isinstance(value, sympy.Add):
            summation = self.value_of(value.args[0], recursive)
            for addend in value.args[1:]:
                summation += self.value_of(addend, recursive)
            return summation
        if isinstance(value, sympy.Mul):
            product = self.value_of(value.args[0], recursive)
            for factor in value.args[1:]:
                product *= self.value_of(factor, recursive)
            return product
        if isinstance(value, sympy.Pow) and len(value.args) == 2:
            base = self.value_of(value.args[0], recursive)
            exponent = self.value_of(value.args[1], recursive)
            if isinstance(base, numbers.Number):
                return np.float_power(cast(complex, base), cast(complex, exponent))
            return np.power(cast(complex, base), cast(complex, exponent))
        if not recursive:
            v = value.subs(self._param_dict, simultaneous=True)
            if v.free_symbols:
                return v
            elif sympy.im(v):
                return complex(v)
            else:
                return float(v)
        return self._value_of_recursive(value)
    def _value_of_recursive(self, value: cirq.TParamKey) -> cirq.TParamValComplex:
        if value in self._deep_eval_map:
            v = self._deep_eval_map[value]
            if v is _RECURSION_FLAG:
                raise RecursionError(f'Evaluation of {value} indirectly contains itself.')
            return v
        self._deep_eval_map[value] = _RECURSION_FLAG
        v = self.value_of(value, recursive=False)
        if v == value or (isinstance(v, sympy.Symbol) and v.name == value):
            self._deep_eval_map[value] = v
        else:
            self._deep_eval_map[value] = self.value_of(v, recursive=True)
        return self._deep_eval_map[value]
    def _resolve_parameters_(self, resolver: ParamResolver, recursive: bool) -> ParamResolver:
        new_dict: dict[cirq.TParamKey, float | str | sympy.Symbol | sympy.Expr] = {
            k: k for k in resolver
        }
        new_dict.update({k: self.value_of(k, recursive) for k in self})
        new_dict.update({k: resolver.value_of(v, recursive) for k, v in new_dict.items()})
        if recursive and self._param_dict:
            new_resolver = ParamResolver(cast(ParamDictType, new_dict))
            return ParamResolver()._resolve_parameters_(new_resolver, recursive=True)
        return ParamResolver(cast(ParamDictType, new_dict))
    def __iter__(self) -> Iterator[str | sympy.Expr]:
        return iter(self._param_dict)
    def __bool__(self) -> bool:
        return bool(self._param_dict)
    def __getitem__(self, key: cirq.TParamKey | cirq.TParamValComplex) -> cirq.TParamValComplex:
        return self.value_of(key)
    def __hash__(self) -> int:
        if self._param_hash is None:
            self._param_hash = hash(frozenset(self._param_dict.items()))
        return self._param_hash
    def __getstate__(self) -> dict[str, Any]:
        state = self.__dict__
        if state["_param_hash"] is not None:
            state = state.copy()
            state["_param_hash"] = None
        return state
    def __eq__(self, other):
        if not isinstance(other, ParamResolver):
            return NotImplemented
        return self._param_dict == other._param_dict
    def __ne__(self, other):
        return not self == other
    def __repr__(self) -> str:
        param_dict_repr = (
            '{'
            + ', '.join(f'{proper_repr(k)}: {proper_repr(v)}' for k, v in self._param_dict.items())
            + '}'
        )
        return f'cirq.ParamResolver({param_dict_repr})'
    def _json_dict_(self) -> dict[str, Any]:
        return {
            'param_dict': list(self._param_dict.items())
        }
    @classmethod
    def _from_json_dict_(cls, param_dict, **kwargs):
        return cls(dict(param_dict))
def _resolve_value(val: Any) -> Any:
    if isinstance(val, float) or val is None:
        return val
    if isinstance(val, numbers.Number) and not isinstance(val, sympy.Basic):
        return val
    if isinstance(val, sympy_numbers.IntegerConstant):
        return val.p
    if isinstance(val, sympy_numbers.RationalConstant):
        return val.p / val.q
    if val is sympy.pi:
        return np.pi
    getter = getattr(val, '_resolved_value_', None)
    result = NotImplemented if getter is None else getter()
    return result

from __future__ import annotations
import abc
import collections
import io
from collections.abc import Callable, Iterable, Mapping, Sequence
from typing import Any, cast, TYPE_CHECKING, TypeVar, Union
import numpy as np
import pandas as pd
from cirq import ops, value
from cirq._compat import proper_repr
from cirq.study import resolver
if TYPE_CHECKING:
    import cirq
T = TypeVar('T')
TMeasurementKey = Union[str, 'cirq.Qid', Iterable['cirq.Qid']]
def _tuple_of_big_endian_int(bit_groups: Iterable[Any]) -> tuple[int, ...]:
    return tuple(value.big_endian_bits_to_int(bits) for bits in bit_groups)
def _bitstring(vals: Iterable[Any]) -> str:
    str_list = [str(int(v)) for v in vals]
    separator = '' if all(len(s) == 1 for s in str_list) else ' '
    return separator.join(str_list)
def _keyed_repeated_bitstrings(vals: Mapping[str, np.ndarray]) -> str:
    keyed_bitstrings = []
    for key in sorted(vals.keys()):
        reps = vals[key]
        n = 0 if len(reps) == 0 else len(reps[0])
        all_bits = ', '.join(_bitstring(reps[:, i]) for i in range(n))
        keyed_bitstrings.append(f'{key}={all_bits}')
    return '\n'.join(keyed_bitstrings)
def _keyed_repeated_records(vals: Mapping[str, np.ndarray]) -> str:
    keyed_bitstrings = []
    for key in sorted(vals.keys()):
        reps = vals[key]
        n = reps.shape[2]
        num_records = reps.shape[1]
        for j in range(num_records):
            all_bits = ', '.join(_bitstring(reps[:, j, i]) for i in range(n))
            keyed_bitstrings.append(f'{key}={all_bits}')
    return '\n'.join(keyed_bitstrings)
def _key_to_str(key: TMeasurementKey) -> str:
    if isinstance(key, str):
        return key
    if isinstance(key, ops.Qid):
        return str(key)
    return ','.join(str(q) for q in key)
class Result(abc.ABC):
    @property
    @abc.abstractmethod
    def params(self) -> cirq.ParamResolver:
    @property
    @abc.abstractmethod
    def measurements(self) -> Mapping[str, np.ndarray]:
    @property
    @abc.abstractmethod
    def records(self) -> Mapping[str, np.ndarray]:
    @property
    @abc.abstractmethod
    def data(self) -> pd.DataFrame:
    @staticmethod
    def dataframe_from_measurements(measurements: Mapping[str, np.ndarray]) -> pd.DataFrame:
        converted_dict = {}
        for key, bitstrings in measurements.items():
            _, n = bitstrings.shape
            dtype = object if n > 63 else np.int64
            basis = 2 ** np.arange(n, dtype=dtype)[::-1]
            converted_dict[key] = np.sum(basis * bitstrings, axis=1)
        dtype = object if any(bs.shape[1] > 63 for _, bs in measurements.items()) else np.int64
        return pd.DataFrame(converted_dict, dtype=dtype)
    @property
    def repetitions(self) -> int:
        if not self.records:
            return 0
        return len(next(iter(self.records.values())))
    def multi_measurement_histogram(
        self,
        *,  # Forces keyword args.
        keys: Iterable[TMeasurementKey],
        fold_func: Callable[[tuple], T] = cast(Callable[[tuple], T], _tuple_of_big_endian_int),
    ) -> collections.Counter:
        fixed_keys = tuple(_key_to_str(key) for key in keys)
        samples: Iterable[Any] = zip(*(self.measurements[sub_key] for sub_key in fixed_keys))
        if len(fixed_keys) == 0:
            samples = [()] * self.repetitions
        c: collections.Counter = collections.Counter()
        for sample in samples:
            c[fold_func(sample)] += 1
        return c
    def histogram(
        self,
        *,  # Forces keyword args.
        key: TMeasurementKey,
        fold_func: Callable[[tuple], T] = cast(Callable[[tuple], T], value.big_endian_bits_to_int),
    ) -> collections.Counter:
        return self.multi_measurement_histogram(keys=[key], fold_func=lambda e: fold_func(e[0]))
    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Result):
            return NotImplemented
        return (
            self.records.keys() == other.records.keys()
            and all(np.array_equal(self.records[k], other.records[k]) for k in self.records)
            and self.params == other.params
        )
    def __add__(self, other: cirq.Result) -> cirq.Result:
        if not isinstance(other, Result):
            return NotImplemented
        if self.params != other.params:
            raise ValueError(
                f'Cannot add results with different parameters: {self.params} != {other.params}'
            )
        shape = {k: v.shape[1:] for k, v in self.records.items()}
        other_shape = {k: v.shape[1:] for k, v in other.records.items()}
        if shape != other_shape:
            raise ValueError(
                f'Cannot add results with different measurement shapes: {shape} != {other_shape}'
            )
        all_records: dict[str, np.ndarray] = {}
        for key in other.records:
            all_records[key] = np.append(self.records[key], other.records[key], axis=0)
        return ResultDict(params=self.params, records=all_records)
class ResultDict(Result):
    def __init__(
        self,
        *,  # Forces keyword args.
        params: resolver.ParamResolver | None = None,
        measurements: Mapping[str, np.ndarray] | None = None,
        records: Mapping[str, np.ndarray] | None = None,
    ) -> None:
        if params is None:
            params = resolver.ParamResolver({})
        if measurements is None and records is None:
            measurements = {}
            records = {}
        self._params = params
        self._measurements = measurements
        self._records = records
        self._data: pd.DataFrame | None = None
    @property
    def params(self) -> cirq.ParamResolver:
        return self._params
    @property
    def measurements(self) -> Mapping[str, np.ndarray]:
        if self._measurements is None:
            assert self._records is not None
            self._measurements = {}
            for key, data in self._records.items():
                reps, instances, qubits = data.shape
                if instances != 1:
                    raise ValueError('Cannot extract 2D measurements for repeated keys')
                self._measurements[key] = data.reshape((reps, qubits))
        return self._measurements
    @property
    def records(self) -> Mapping[str, np.ndarray]:
        if self._records is None:
            assert self._measurements is not None
            self._records = {
                key: data[:, np.newaxis, :] for key, data in self._measurements.items()
            }
        return self._records
    @property
    def repetitions(self) -> int:
        if self._records is not None:
            if not self._records:
                return 0
            return len(next(iter(self._records.values())))
        else:
            if not self._measurements:
                return 0
            return len(next(iter(self._measurements.values())))
    @property
    def data(self) -> pd.DataFrame:
        if self._data is None:
            self._data = self.dataframe_from_measurements(self.measurements)
        return self._data
    def _record_dict_repr(self):
        return '{' + ', '.join(f'{k!r}: {proper_repr(v)}' for k, v in self.records.items()) + '}'
    def __repr__(self) -> str:
        return f'cirq.ResultDict(params={self.params!r}, records={self._record_dict_repr()})'
    def _repr_pretty_(self, p: Any, cycle: bool) -> None:
        if cycle:
            p.text('ResultDict(...)')
        else:
            p.text(str(self))
    def __str__(self) -> str:
        if self._records:
            return _keyed_repeated_records(self.records)
        return _keyed_repeated_bitstrings(self.measurements)
    def _json_dict_(self):
        packed_records = {}
        for key, digits in self.records.items():
            packed_digits, binary = _pack_digits(digits)
            packed_records[key] = {
                'packed_digits': packed_digits,
                'binary': binary,
                'dtype': digits.dtype.name,
                'shape': digits.shape,
            }
        return {'params': self.params, 'records': packed_records}
    @classmethod
    def _from_packed_records(cls, records, **kwargs):
        return cls(records={key: _unpack_digits(**val) for key, val in records.items()}, **kwargs)
    @classmethod
    def _from_json_dict_(cls, params, **kwargs):
        if 'measurements' in kwargs:
            measurements = kwargs['measurements']
            return cls(
                params=params,
                measurements={key: _unpack_digits(**val) for key, val in measurements.items()},
            )
        return cls._from_packed_records(params=params, records=kwargs['records'])
def _pack_digits(digits: np.ndarray, pack_bits: str = 'auto') -> tuple[str, bool]:
    if pack_bits == 'force':
        return _pack_bits(digits), True
    if pack_bits not in ['auto', 'never']:
        raise ValueError("Please set `pack_bits` to 'auto', 'force', or 'never'.")
    if pack_bits == 'auto' and np.array_equal(digits, digits.astype(np.bool_)):
        return _pack_bits(digits.astype(np.bool_)), True
    buffer = io.BytesIO()
    np.save(buffer, digits, allow_pickle=False)
    buffer.seek(0)
    packed_digits = buffer.read().hex()
    buffer.close()
    return packed_digits, False
def _pack_bits(bits: np.ndarray) -> str:
    return np.packbits(bits).tobytes().hex()
def _unpack_digits(
    packed_digits: str, binary: bool, dtype: None | str, shape: None | Sequence[int]
) -> np.ndarray:
    if binary:
        dtype = cast(str, dtype)
        shape = cast(Sequence[int], shape)
        return _unpack_bits(packed_digits, dtype, shape)
    buffer = io.BytesIO()
    buffer.write(bytes.fromhex(packed_digits))
    buffer.seek(0)
    digits = np.load(buffer, allow_pickle=False)
    buffer.close()
    return digits
def _unpack_bits(packed_bits: str, dtype: str, shape: Sequence[int]) -> np.ndarray:
    bits_bytes = bytes.fromhex(packed_bits)
    bits = np.unpackbits(np.frombuffer(bits_bytes, dtype=np.uint8))
    return bits[: np.prod(shape).item()].reshape(shape).astype(dtype)

from __future__ import annotations
import collections
import numpy as np
import pandas as pd
import pytest
import cirq
