    )
    cirq.testing.assert_equivalent_repr(v)
    v = cirq.ResultDict(
        params=cirq.ParamResolver({'a': 2}),
        records={'xy': np.array([[[0, 0], [0, 1]], [[1, 0], [1, 1]]])},
    )
