from __future__ import annotations
import fractions
import pytest
import cirq
CMP_OPS = [
    lambda a, b: a == b,
    lambda a, b: a != b,
    lambda a, b: a < b,
    lambda a, b: a > b,
    lambda a, b: a <= b,
    lambda a, b: a >= b,
]
class MockValue:
    def __init__(self, val, eq, ne, lt, gt, le, ge):
        self.val = val
        self._eq = eq
        self._ne = ne
        self._lt = lt
        self._gt = gt
        self._le = le
        self._ge = ge
    __hash__ = None  # type: ignore
    def __eq__(self, other):
        return self._eq(self, other)
    def __ne__(self, other):
        return self._ne(self, other)
    def __lt__(self, other):
        return self._lt(self, other)
    def __gt__(self, other):
        return self._gt(self, other)
    def __le__(self, other):
        return self._le(self, other)
    def __ge__(self, other):
        return self._ge(self, other)
    def __repr__(self):
        return f'MockValue(val={self.val!r}, ...)'
def test_add_ordering_group_correct() -> None:
    ot = cirq.testing.OrderTester()
    ot.add_ascending(-4, 0)
    ot.add_ascending(1, 2)
    ot.add_ascending_equivalence_group(fractions.Fraction(6, 2), fractions.Fraction(12, 4), 3, 3.0)
    ot.add_ascending_equivalence_group(float('inf'), float('inf'))
def test_add_ordering_group_incorrect() -> None:
    ot = cirq.testing.OrderTester()
    ot.add_ascending(0)
    with pytest.raises(AssertionError):
        ot.add_ascending_equivalence_group(0, 0)
    ot.add_ascending(1, 2)
    with pytest.raises(AssertionError):
        ot.add_ascending(20, 20)  # not ascending within call
    with pytest.raises(AssertionError):
        ot.add_ascending(1, 3)  # not ascending w.r.t. previous call
    with pytest.raises(AssertionError):
        ot.add_ascending(6, 6)  # not ascending within call
    with pytest.raises(AssertionError):
        ot.add_ascending(99, 10)  # not ascending within call
    with pytest.raises(AssertionError):
        ot.add_ascending(0)
def test_propagates_internal_errors() -> None:
    class UnorderableClass:  # pragma: no cover
        def __eq__(self, other):
            return NotImplemented
        def __ne__(self, other):
            return NotImplemented
        def __lt__(self, other):
            raise ValueError('oh no')
        def __le__(self, other):
            return NotImplemented
        def __ge__(self, other):
            return NotImplemented
        def __gt__(self, other):
            return NotImplemented
    ot = cirq.testing.OrderTester()
    with pytest.raises(ValueError, match='oh no'):
        ot.add_ascending(UnorderableClass())
def test_add_ascending_equivalence_group() -> None:
    ot = cirq.testing.OrderTester()
    with pytest.raises(AssertionError, match='Expected X=1 to equal Y=3'):
        ot.add_ascending_equivalence_group(1, 3)
    ot.add_ascending_equivalence_group(2)
    ot.add_ascending_equivalence_group(4)
    with pytest.raises(AssertionError, match='Expected X=4 to be less than Y=3'):
        ot.add_ascending_equivalence_group(3)
    ot.add_ascending_equivalence_group(5)
def test_fails_to_return_not_implemented_vs_unknown() -> None:
    def make_impls(bad_index: int, bad_result: bool):
        def make_impl(i, op):
            def impl(x, y):
                if isinstance(y, MockValue):
                    return op(x.val, y.val)
                if bad_index == i:
                    return bad_result
                return NotImplemented
            return impl
        return [make_impl(i, op) for i, op in enumerate(CMP_OPS)]
    ot = cirq.testing.OrderTester()
    for k in range(len(CMP_OPS)):
        for b in [False, True]:
            item = MockValue(0, *make_impls(bad_index=k, bad_result=b))
            with pytest.raises(AssertionError, match='return NotImplemented'):
                ot.add_ascending(item)
    good_impls = make_impls(bad_index=-1, bad_result=NotImplemented)
    ot.add_ascending(MockValue(0, *good_impls))
    ot.add_ascending(MockValue(1, *good_impls))
def test_fails_on_inconsistent_hashes() -> None:
    class ModifiedHash(tuple):
        def __hash__(self):
            return super().__hash__() ^ 1
    ot = cirq.testing.OrderTester()
    ot.add_ascending((1, 0), (1, 1))
    ot.add_ascending(ModifiedHash((1, 2)), ModifiedHash((2, 0)))
    ot.add_ascending_equivalence_group((2, 2), (2, 2))
    ot.add_ascending_equivalence_group(ModifiedHash((3, 3)), ModifiedHash((3, 3)))
    with pytest.raises(AssertionError, match='different hashes'):
        ot.add_ascending_equivalence_group((4, 4), ModifiedHash((4, 4)))

from __future__ import annotations
from collections.abc import Sequence
from typing import TYPE_CHECKING
from cirq import circuits, ops, value
from cirq._doc import document
if TYPE_CHECKING:
    import cirq
DEFAULT_GATE_DOMAIN: dict[ops.Gate, int] = {
    ops.CNOT: 2,  # type: ignore[has-type]
    ops.CZ: 2,  # type: ignore[has-type]
    ops.H: 1,  # type: ignore[has-type]
    ops.ISWAP: 2,  # type: ignore[has-type]
    ops.CZPowGate(): 2,
    ops.S: 1,  # type: ignore[has-type]
    ops.SWAP: 2,  # type: ignore[has-type]
    ops.T: 1,  # type: ignore[has-type]
    ops.X: 1,  # type: ignore[has-type]
    ops.Y: 1,  # type: ignore[has-type]
    ops.Z: 1,  # type: ignore[has-type]
}
document(
    DEFAULT_GATE_DOMAIN,
    ,
)
def random_circuit(
    qubits: Sequence[cirq.Qid] | int,
    n_moments: int,
    op_density: float,
    gate_domain: dict[ops.Gate, int] | None = None,
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> circuits.Circuit:
    if not 0 < op_density <= 1:
        raise ValueError(f'op_density must be in (0, 1] but was {op_density}.')
    if gate_domain is None:
        gate_domain = DEFAULT_GATE_DOMAIN
    if not gate_domain:
        raise ValueError('gate_domain must be non-empty.')
    if isinstance(qubits, int):
        qubits = tuple(ops.NamedQubit(str(i)) for i in range(qubits))
    n_qubits = len(qubits)
    if n_qubits < 1:
        raise ValueError('At least one qubit must be specified.')
    gate_domain = {k: v for k, v in gate_domain.items() if v <= n_qubits}
    if not gate_domain:
        raise ValueError(
            f'After removing gates that act on less than '
            f'{n_qubits} qubits, gate_domain had no gates.'
        )
    max_arity = max(gate_domain.values())
    prng = value.parse_random_state(random_state)
    moments: list[circuits.Moment] = []
    gate_arity_pairs = sorted(gate_domain.items(), key=repr)
    num_gates = len(gate_domain)
    for _ in range(n_moments):
        operations = []
        free_qubits = set(qubits)
        while len(free_qubits) >= max_arity:
            gate, arity = gate_arity_pairs[prng.randint(num_gates)]
            op_qubits = prng.choice(sorted(free_qubits), size=arity, replace=False)
            free_qubits.difference_update(op_qubits)
            if prng.rand() <= op_density:
                operations.append(gate(*op_qubits))
        moments.append(circuits.Moment(operations))
    return circuits.Circuit(moments)
def random_two_qubit_circuit_with_czs(
    num_czs: int = 3,
    q0: cirq.Qid | None = None,
    q1: cirq.Qid | None = None,
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> circuits.Circuit:
    prng = value.parse_random_state(random_state)
    q0 = ops.NamedQubit('q0') if q0 is None else q0
    q1 = ops.NamedQubit('q1') if q1 is None else q1
    def random_one_qubit_gate():
        return ops.PhasedXPowGate(phase_exponent=prng.rand(), exponent=prng.rand())
    def one_cz():
        return [ops.CZ.on(q0, q1), random_one_qubit_gate().on(q0), random_one_qubit_gate().on(q1)]
    return circuits.Circuit(
        [
            random_one_qubit_gate().on(q0),
            random_one_qubit_gate().on(q1),
            [one_cz() for _ in range(num_czs)],
        ]
    )

