class _MeasurementQid(ops.Qid):
    def __init__(self, key: str | cirq.MeasurementKey, qid: cirq.Qid, index: int = 0):
        self._key = value.MeasurementKey.parse_serialized(key) if isinstance(key, str) else key
        self._qid = qid
        self._index = index
