    import sympy
    import cirq
@transformer_api.transformer
def merge_single_qubit_gates_to_phased_x_and_z(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    atol: float = 1e-8,
) -> cirq.Circuit:
    def rewriter(op: cirq.CircuitOperation) -> cirq.OP_TREE:
        u = protocols.unitary(op)
        if protocols.num_qubits(op) == 0:
            return ops.GlobalPhaseGate(u[0, 0]).on()
        return [
            g(op.qubits[0])
            for g in single_qubit_decompositions.single_qubit_matrix_to_phased_x_z(u, atol)
        ]
    return merge_k_qubit_gates.merge_k_qubit_unitaries(
        circuit, k=1, context=context, rewriter=rewriter
    )
@transformer_api.transformer
def merge_single_qubit_gates_to_phxz(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    merge_tags_fn: Callable[[cirq.CircuitOperation], list[Hashable]] | None = None,
    atol: float = 1e-8,
) -> cirq.Circuit:
    def rewriter(circuit_op: cirq.CircuitOperation) -> cirq.OP_TREE:
        u = protocols.unitary(circuit_op)
        if protocols.num_qubits(circuit_op) == 0:
            return ops.GlobalPhaseGate(u[0, 0]).on()
        gate = single_qubit_decompositions.single_qubit_matrix_to_phxz(u, atol) or ops.I
        phxz_op = gate.on(circuit_op.qubits[0])
        return phxz_op.with_tags(*merge_tags_fn(circuit_op)) if merge_tags_fn else phxz_op
    return merge_k_qubit_gates.merge_k_qubit_unitaries(
        circuit, k=1, context=context, rewriter=rewriter
    )
@transformer_api.transformer
def merge_single_qubit_moments_to_phxz(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    atol: float = 1e-8,
) -> cirq.Circuit:
    tags_to_ignore = set(context.tags_to_ignore) if context else set()
    def can_merge_moment(m: cirq.Moment):
        return all(
            protocols.num_qubits(op) <= 1
            and protocols.has_unitary(op)
            and tags_to_ignore.isdisjoint(op.tags)
            for op in m
        )
    def merge_func(m1: cirq.Moment, m2: cirq.Moment) -> cirq.Moment | None:
        if not (can_merge_moment(m1) and can_merge_moment(m2)):
            return None
        ret_ops = []
        for q in m1.qubits | m2.qubits:
            op1, op2 = m1.operation_at(q), m2.operation_at(q)
            if op1 and op2:
                mat = protocols.unitary(op2) @ protocols.unitary(op1)
                gate = single_qubit_decompositions.single_qubit_matrix_to_phxz(mat, atol)
                if gate:
                    ret_ops.append(gate(q))
            else:
                op = op1 or op2
                assert op is not None
                if isinstance(op.gate, ops.PhasedXZGate):
                    ret_ops.append(op)
                else:
                    gate = single_qubit_decompositions.single_qubit_matrix_to_phxz(
                        protocols.unitary(op), atol
                    )
                    if gate:
                        ret_ops.append(gate(q))
        for op in m1.operations + m2.operations:
            if protocols.num_qubits(op) == 0:
                ret_ops.append(op)
        return circuits.Moment(ret_ops)
    return transformer_primitives.merge_moments(
        circuit,
        merge_func,
        deep=context.deep if context else False,
        tags_to_ignore=tuple(tags_to_ignore),
    ).unfreeze(copy=False)
def _sweep_on_symbols(sweep: Sweep, symbols: set[sympy.Symbol]) -> Sweep:
    new_resolvers: list[cirq.ParamResolver] = []
    for resolver in sweep:
        param_dict: cirq.ParamMappingType = {s: resolver.value_of(s) for s in symbols}
        new_resolvers.append(ParamResolver(param_dict))
    return ListSweep(new_resolvers)
def _calc_phxz_sweeps(
    symbolized_circuit: cirq.Circuit, resolved_circuits: list[cirq.Circuit]
) -> Sweep:
    def _extract_axz(op: ops.Operation | None) -> tuple[float, float, float]:
        if not op or not op.gate or not isinstance(op.gate, ops.IdentityGate | ops.PhasedXZGate):
            raise ValueError(f"Expect a PhasedXZGate or IdentityGate on op {op}.")
        if isinstance(op.gate, ops.IdentityGate):
            return 0.0, 0.0, 0.0  # Identity gate's a, x, z in PhasedXZ
        return op.gate.axis_phase_exponent, op.gate.x_exponent, op.gate.z_exponent
    values_by_params: dict[sympy.Symbol, tuple[float, ...]] = {}
    for mid, moment in enumerate(symbolized_circuit):
        for op in moment.operations:
            if op.gate and isinstance(op.gate, ops.PhasedXZGate) and protocols.is_parameterized(op):
                sa, sx, sz = op.gate.axis_phase_exponent, op.gate.x_exponent, op.gate.z_exponent
                values_by_params[sa], values_by_params[sx], values_by_params[sz] = zip(
                    *[_extract_axz(c[mid].operation_at(op.qubits[0])) for c in resolved_circuits]
                )
    return dict_to_zip_sweep(cast(ProductOrZipSweepLike, values_by_params))
def merge_single_qubit_gates_to_phxz_symbolized(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    sweep: Sweep,
    atol: float = 1e-8,
) -> tuple[cirq.Circuit, Sweep]:
    deep = context.deep if context else False
    symbolized_single_tag = "_tmp_symbolize_tag"
    circuit_tagged = transformer_primitives.map_operations(
        circuit,
        lambda op, _: (
            op.with_tags(symbolized_single_tag)
            if protocols.is_parameterized(op) and len(op.qubits) == 1
            else op
        ),
        deep=deep,
    )
    single_qubit_gate_symbols: set[sympy.Symbol] = set().union(
        *[
            protocols.parameter_symbols(op) if symbolized_single_tag in op.tags else set()
            for op in circuit_tagged.all_operations()
        ]
    )
    remaining_symbols: set[sympy.Symbol] = set(
        protocols.parameter_symbols(circuit) - single_qubit_gate_symbols
    )
    if not single_qubit_gate_symbols:
        return (merge_single_qubit_gates_to_phxz(circuit, context=context, atol=atol), sweep)
    sweep_of_single: Sweep = _sweep_on_symbols(sweep, single_qubit_gate_symbols)
    resolved_circuits = [
        protocols.resolve_parameters(circuit_tagged, resolver) for resolver in sweep_of_single
    ]
    merged_circuits: list[cirq.Circuit] = [
        merge_single_qubit_gates_to_phxz(
            c,
            context=context,
            merge_tags_fn=lambda circuit_op: (
                [symbolized_single_tag]
                if any(
                    symbolized_single_tag in set(op.tags)
                    for op in circuit_op.circuit.all_operations()
                )
                else []
            ),
            atol=atol,
        )
        for c in resolved_circuits
    ]
    new_circuit = tag_transformers.remove_tags(  # remove the temp tags used to track merges
        symbolize.symbolize_single_qubit_gates_by_indexed_tags(
            tag_transformers.index_tags(  # index all 1-qubit-ops merged from ops with symbols
                merged_circuits[0],
                context=transformer_api.TransformerContext(deep=deep),
                target_tags={symbolized_single_tag},
            ),
            symbolize_tag=symbolize.SymbolizeTag(prefix=symbolized_single_tag),
        ),
        remove_if=lambda tag: str(tag).startswith(symbolized_single_tag),
    )
    if remaining_symbols:
        new_sweep: Sweep = Zip(
            _calc_phxz_sweeps(new_circuit, merged_circuits),  # phxz sweeps
            _sweep_on_symbols(sweep, remaining_symbols),  # remaining sweeps
        )
    else:
        new_sweep = _calc_phxz_sweeps(new_circuit, merged_circuits)
    return align.align_right(new_circuit), new_sweep

from __future__ import annotations
from collections.abc import Mapping
from typing import cast
import numpy as np
from cirq import circuits, ops
from cirq.transformers import transformer_api
def _gate_in_moment(gate: ops.Gate, moment: circuits.Moment) -> bool:
    return any(op.gate == gate for op in moment)
@transformer_api.transformer
class DepolarizingNoiseTransformer:
    def __init__(
        self, p: float | Mapping[tuple[ops.Qid, ops.Qid], float], target_gate: ops.Gate = ops.CZ
    ):
        if not isinstance(p, (Mapping, float)):
            raise TypeError(  # pragma: no cover
                "p must either be a float or a mapping from"  # pragma: no cover
                "sorted qubit pairs to floats"  # pragma: no cover
            )  # pragma: no cover
        self.p = p
        self.p_func = (
            (lambda _: p)
            if isinstance(p, (int, float))
            else (lambda pair: cast(Mapping, p).get(pair, 0.0))
        )
        self.target_gate = target_gate
    def __call__(
        self,
        circuit: circuits.AbstractCircuit,
        rng: np.random.Generator | None = None,
        *,
        context: transformer_api.TransformerContext | None = None,
    ):
        if rng is None:
            rng = np.random.default_rng()
        target_gate = self.target_gate
        assert target_gate.num_qubits() == 2, "`target_gate` must be a two-qubit gate."
        paulis = [ops.I, ops.X, ops.Y, ops.Z]
        new_moments = []
        for moment in circuit:
            new_moments.append(moment)
            if _gate_in_moment(target_gate, moment):
                target_pairs = {
                    tuple(sorted(op.qubits)) for op in moment.operations if op.gate == target_gate
                }
                added_moment_ops = []
                for pair in target_pairs:
                    pair_sorted_tuple = (pair[0], pair[1])
                    p_i = self.p_func(pair_sorted_tuple)
                    apply = rng.choice([True, False], p=[p_i, 1 - p_i])
                    if apply:
                        choices = [
                            (pauli_a(pair[0]), pauli_b(pair[1]))
                            for pauli_a in paulis
                            for pauli_b in paulis
                        ][1:]
                        pauli_to_apply = rng.choice(np.array(choices, dtype=object))
                        added_moment_ops.append(pauli_to_apply)
                if len(added_moment_ops) > 0:
                    new_moments.append(circuits.Moment(*added_moment_ops))
        return circuits.Circuit.from_moments(*new_moments)

from __future__ import annotations
from collections.abc import Callable, Hashable, Sequence
from typing import TYPE_CHECKING
from cirq import circuits
from cirq.protocols import decompose_protocol as dp
from cirq.transformers import transformer_api, transformer_primitives
if TYPE_CHECKING:
    import cirq
def _create_on_stuck_raise_error(gateset: cirq.Gateset):
    def _value_error_describing_bad_operation(op: cirq.Operation) -> ValueError:
        return ValueError(f"Unable to convert {op} to target gateset {gateset!r}")
    return _value_error_describing_bad_operation
@transformer_api.transformer
def _decompose_operations_to_target_gateset(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    gateset: cirq.Gateset | None = None,
    decomposer: Callable[[cirq.Operation, int], dp.DecomposeResult] = lambda *_: NotImplemented,
    ignore_failures: bool = True,
    tags_to_decompose: Sequence[Hashable] = (),
) -> cirq.Circuit:
    def map_func(op: cirq.Operation, moment_index: int):
        if (
            context
            and context.deep
            and isinstance(op.untagged, circuits.CircuitOperation)
            and set(op.tags).isdisjoint(tags_to_decompose)
        ):
            return op
        return dp.decompose(
            op,
            intercepting_decomposer=lambda o: decomposer(o, moment_index),
            keep=gateset.validate if gateset else None,
            on_stuck_raise=(
                None
                if ignore_failures or gateset is None
                else _create_on_stuck_raise_error(gateset)
            ),
        )
    return transformer_primitives.map_operations_and_unroll(
        circuit,
        map_func,
        tags_to_ignore=context.tags_to_ignore if context else (),
        deep=context.deep if context else False,
    ).unfreeze(copy=False)
@transformer_api.transformer
def optimize_for_target_gateset(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    gateset: cirq.CompilationTargetGateset | None = None,
    ignore_failures: bool = True,
    max_num_passes: int | None = 1,
) -> cirq.Circuit:
    if gateset is None:
        return _decompose_operations_to_target_gateset(
            circuit, context=context, ignore_failures=ignore_failures
        )
    if isinstance(max_num_passes, int):
        _outerloop = lambda: range(max_num_passes)
    else:
        def _outerloop():
            while True:
                yield 0
    initial_num_moments, initial_num_ops = len(circuit), sum(1 for _ in circuit.all_operations())
    for _ in _outerloop():
        for transformer in gateset.preprocess_transformers:
            circuit = transformer(circuit, context=context)
        circuit = _decompose_operations_to_target_gateset(
            circuit,
            context=context,
            gateset=gateset,
            decomposer=gateset.decompose_to_target_gateset,
            ignore_failures=ignore_failures,
            tags_to_decompose=(gateset._intermediate_result_tag,),
        )
        for transformer in gateset.postprocess_transformers:
            circuit = transformer(circuit, context=context)
        num_moments, num_ops = len(circuit), sum(1 for _ in circuit.all_operations())
        if (num_moments, num_ops) == (initial_num_moments, initial_num_ops):
            break
        initial_num_moments, initial_num_ops = num_moments, num_ops
    return circuit.unfreeze(copy=False)

from __future__ import annotations
from typing import TYPE_CHECKING
from cirq import circuits, ops
if TYPE_CHECKING:
    import cirq
def _get_qubit_mapping_first_and_last_moment(
    circuit: cirq.AbstractCircuit,
) -> dict[cirq.Qid, tuple[int, int]]:
    ret = {q: (len(circuit), 0) for q in circuit.all_qubits()}
    for i, moment in enumerate(circuit):
        for q in moment.qubits:
            ret[q] = (min(ret[q][0], i), max(ret[q][1], i))
    return ret
def _is_temp(q: cirq.Qid) -> bool:
    return isinstance(q, (ops.CleanQubit, ops.BorrowableQubit))
def map_clean_and_borrowable_qubits(
    circuit: cirq.AbstractCircuit, *, qm: cirq.QubitManager | None = None
) -> cirq.Circuit:
    if qm is None:
        qm = ops.GreedyQubitManager(prefix="ancilla")
    allocated_qubits = {q for q in circuit.all_qubits() if _is_temp(q)}
    qubits_lifespan = _get_qubit_mapping_first_and_last_moment(circuit)
    all_qubits = frozenset(circuit.all_qubits() - allocated_qubits)
    trivial_map = {q: q for q in all_qubits}
    allocated_map: dict[cirq.Qid, cirq.Qid] = {}
    to_free: set[cirq.Qid] = set()
    last_op_idx = -1
    def map_func(op: cirq.Operation, idx: int) -> cirq.OP_TREE:
        nonlocal last_op_idx, to_free
        assert isinstance(qm, ops.QubitManager)
        for q in sorted(to_free):
            is_managed_qubit = allocated_map[q] not in all_qubits
            if idx > last_op_idx or is_managed_qubit:
                if is_managed_qubit:
                    qm.qfree([allocated_map[q]])
                allocated_map.pop(q)
                to_free.remove(q)
        last_op_idx = idx
        borrowable_qubits = set(all_qubits) - set(allocated_map.values())
        op_temp_qubits = (q for q in op.qubits if _is_temp(q))
        for q in op_temp_qubits:
            st, en = qubits_lifespan[q]
            assert st <= idx <= en
            if en == idx:
                to_free.add(q)
            if q in allocated_map or st < idx:
                assert st < idx and q in allocated_map
                continue  # pragma: no cover
            if isinstance(q, ops.CleanQubit):
                allocated_map[q] = qm.qalloc(1)[0]
            elif isinstance(q, ops.BorrowableQubit):
                start_frontier = {q: st for q in borrowable_qubits}
                end_frontier = {q: en + 1 for q in borrowable_qubits}
                ops_in_between = circuit.findall_operations_between(start_frontier, end_frontier)
                filtered_borrowable_qubits = borrowable_qubits - set(
                    q for _, op in ops_in_between for q in op.qubits
                )
                if filtered_borrowable_qubits:
                    allocated_map[q] = min(filtered_borrowable_qubits)
                    borrowable_qubits.remove(allocated_map[q])
                else:
                    allocated_map[q] = qm.qborrow(1)[0]
            else:
                assert False, f"Unknown temporary qubit type {q}"  # pragma: no cover
        return op.transform_qubits({**allocated_map, **trivial_map})
    return circuits.Circuit(map_func(op, idx) for idx, m in enumerate(circuit) for op in m)

from __future__ import annotations
from collections.abc import Callable
import cirq
class GateAllocInDecompose(cirq.Gate):
    def __init__(self, num_alloc: int = 1):
        self.num_alloc = num_alloc
    def _num_qubits_(self) -> int:
        return 1
    def _decompose_with_context_(self, qubits, context):
        assert context is not None
        qm = context.qubit_manager
        for q in qm.qalloc(self.num_alloc):
            yield cirq.CNOT(qubits[0], q)
            qm.qfree([q])
    def __str__(self):
        return 'TestGateAlloc'
class GateAllocAndBorrowInDecompose(cirq.Gate):
    def __init__(self, num_alloc: int = 1):
        self.num_alloc = num_alloc
    def _num_qubits_(self) -> int:
        return 1
    def __str__(self) -> str:
        return 'TestGate'
    def _decompose_with_context_(self, qubits, context):
        assert context is not None
        qm = context.qubit_manager
        qa, qb = qm.qalloc(self.num_alloc), qm.qborrow(self.num_alloc)
        for q, b in zip(qa, qb):
            yield cirq.CSWAP(qubits[0], q, b)
        yield cirq.qft(*qb).controlled_by(qubits[0])
        for q, b in zip(qa, qb):
            yield cirq.CSWAP(qubits[0], q, b)
        qm.qfree(qa + qb)
def get_decompose_func(
    gate_type: type[cirq.Gate], qm: cirq.QubitManager
) -> Callable[[cirq.Operation, int], cirq.OP_TREE]:
    def decompose_func(op: cirq.Operation, _: int) -> cirq.OP_TREE:
        return (
            cirq.decompose_once(op, context=cirq.DecompositionContext(qm))
            if isinstance(op.gate, gate_type)
            else op
        )
    return decompose_func
def test_map_clean_and_borrowable_qubits_greedy_types() -> None:
    qm = cirq.ops.SimpleQubitManager()
    q = cirq.LineQubit.range(2)
    g = GateAllocInDecompose(1)
    circuit = cirq.Circuit(cirq.Moment(g(q[0]), g(q[1])))
    cirq.testing.assert_has_diagram(
        circuit,
        ,
    )
    unrolled_circuit = cirq.map_operations_and_unroll(
        circuit, map_func=get_decompose_func(GateAllocInDecompose, qm), raise_if_add_qubits=False
    )
    cirq.testing.assert_has_diagram(
        unrolled_circuit,
        ,
    )
    qubit_manager = cirq.GreedyQubitManager(prefix='ancilla', size=2, maximize_reuse=False)
    allocated_circuit = cirq.map_clean_and_borrowable_qubits(unrolled_circuit, qm=qubit_manager)
    cirq.testing.assert_has_diagram(
        allocated_circuit,
        ,
    )
    qubit_manager = cirq.GreedyQubitManager(prefix='ancilla', size=2, maximize_reuse=True)
    allocated_circuit = cirq.map_clean_and_borrowable_qubits(unrolled_circuit, qm=qubit_manager)
    cirq.testing.assert_has_diagram(
        allocated_circuit,
        ,
    )
def test_map_clean_and_borrowable_qubits_borrows() -> None:
    qm = cirq.ops.SimpleQubitManager()
    op = GateAllocAndBorrowInDecompose(3).on(cirq.NamedQubit("original"))
    extra = cirq.LineQubit.range(3)
    circuit = cirq.Circuit(
        cirq.H.on_each(*extra),
        cirq.Moment(op),
        cirq.decompose_once(op, context=cirq.DecompositionContext(qm)),
    )
    cirq.testing.assert_has_diagram(
        circuit,
        ,
    )
    allocated_circuit = cirq.map_clean_and_borrowable_qubits(circuit)
    cirq.testing.assert_has_diagram(
        allocated_circuit,
        ,
    )
    decompose_func = get_decompose_func(GateAllocAndBorrowInDecompose, qm)
    allocated_and_decomposed_circuit = cirq.map_clean_and_borrowable_qubits(
        cirq.map_operations_and_unroll(circuit, map_func=decompose_func, raise_if_add_qubits=False)
    )
    cirq.testing.assert_has_diagram(
        allocated_and_decomposed_circuit,
        ,
    )
    allocated_and_decomposed_circuit = cirq.map_clean_and_borrowable_qubits(
        cirq.map_operations_and_unroll(
            cirq.align_left(circuit), map_func=decompose_func, raise_if_add_qubits=False
        )
    )
    cirq.testing.assert_has_diagram(
        allocated_and_decomposed_circuit,
        ,
    )
def test_map_clean_and_borrowable_qubits_deallocates_only_once() -> None:
    q = [cirq.ops.BorrowableQubit(i) for i in range(2)] + [cirq.q('q')]
