from __future__ import annotations
from collections.abc import Sequence
from typing import Any
import numpy as np
import cirq
from cirq.ops import SingleQubitCliffordGate
from cirq.transformers import transformer_api
@transformer_api.transformer
class RandomizedMeasurements:
    def __init__(self, subsystem: Sequence[int] | None = None):
        self.subsystem = subsystem
    def __call__(
        self,
        circuit: cirq.AbstractCircuit,
        unitary_ensemble: str = "pauli",
        rng: np.random.Generator | None = None,
        *,
        context: transformer_api.TransformerContext | None = None,
    ) -> cirq.Circuit:
        all_qubits = sorted(circuit.all_qubits())
        if self.subsystem is None:
            subsystem_qubits = all_qubits
        else:
            subsystem_qubits = [all_qubits[s] for s in self.subsystem]
        if rng is None:
            rng = np.random.default_rng()
        pre_measurement_moment = self.random_single_qubit_unitary_moment(
            unitary_ensemble, subsystem_qubits, rng
        )
        return cirq.Circuit.from_moments(
            *circuit.moments, pre_measurement_moment, cirq.M(*subsystem_qubits, key="m")
        )
    def random_single_qubit_unitary_moment(
        self, unitary_ensemble: str, qubits: Sequence[Any], rng: np.random.Generator
    ) -> cirq.Moment:
        if unitary_ensemble.lower() == "pauli":
            unitaries = [_pauli_basis_rotation(rng) for _ in range(len(qubits))]
        elif unitary_ensemble.lower() == "clifford":
            unitaries = [_single_qubit_clifford(rng) for _ in range(len(qubits))]
        elif unitary_ensemble.lower() == "cue":
            unitaries = [_single_qubit_cue(rng) for _ in range(len(qubits))]
        else:
            raise ValueError("Only pauli, clifford and cue unitaries are available")
        op_list: list[cirq.Operation] = []
        for idx, unitary in enumerate(unitaries):
            op_list.append(unitary.on(qubits[idx]))
        return cirq.Moment.from_ops(*op_list)
def _pauli_basis_rotation(rng: np.random.Generator) -> cirq.Gate:
    basis_idx = rng.choice(np.arange(3))
    if basis_idx == 0:
        gate: cirq.Gate = cirq.Ry(rads=-np.pi / 2)
    elif basis_idx == 1:
        gate = cirq.Rx(rads=np.pi / 2)
    else:
        gate = cirq.I
    return gate
def _single_qubit_clifford(rng: np.random.Generator) -> cirq.Gate:
    clifford_idx = rng.choice(np.arange(24))
    return SingleQubitCliffordGate.to_phased_xz_gate(
        SingleQubitCliffordGate.all_single_qubit_cliffords[clifford_idx]
    )
def _single_qubit_cue(rng: np.random.Generator) -> cirq.Gate:
    x_exponent, z_exponent, axis_phase_exponent = 1 - 2 * rng.random(size=3)
    return cirq.PhasedXZGate(
        x_exponent=x_exponent, z_exponent=z_exponent, axis_phase_exponent=axis_phase_exponent
    )

from __future__ import annotations
import itertools
from collections.abc import Callable, Iterable, Sequence
from typing import TYPE_CHECKING, Union
from cirq import _import, circuits, ops, protocols
from cirq.transformers import transformer_api
drop_empty_moments = _import.LazyLoader('drop_empty_moments', globals(), 'cirq.transformers')
if TYPE_CHECKING:
    import cirq
Classifier = Callable[['cirq.Operation'], bool]
Category = Union[
    'cirq.Gate', 'cirq.Operation', type['cirq.Gate'], type['cirq.Operation'], Classifier
]
@transformer_api.transformer(add_deep_support=True)
def stratified_circuit(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    categories: Iterable[Category] = (),
) -> cirq.Circuit:
    classifiers = _get_classifiers(circuit, categories)
    smallest_depth = protocols.num_qubits(circuit) * len(circuit) + 1
    shortest_stratified_circuit = circuits.Circuit()
    reversed_circuit = circuit[::-1]
    for ordered_classifiers in itertools.permutations(classifiers):
        solution = _stratify_circuit(
            circuit,
            classifiers=ordered_classifiers,
            context=context or transformer_api.TransformerContext(),
        )
        if len(solution) < smallest_depth:
            shortest_stratified_circuit = solution
            smallest_depth = len(solution)
        solution = _stratify_circuit(
            reversed_circuit,
            classifiers=ordered_classifiers,
            context=context or transformer_api.TransformerContext(),
        )[::-1]
        if len(solution) < smallest_depth:
            shortest_stratified_circuit = solution
            smallest_depth = len(solution)
    return shortest_stratified_circuit
def _stratify_circuit(
    circuit: circuits.AbstractCircuit,
    *,
    context: cirq.TransformerContext,
    classifiers: Sequence[Classifier],
) -> cirq.Circuit:
    num_classes = len(classifiers) + 1  # include one "extra" category for ignored operations
    new_moments: list[list[cirq.Operation]] = []
    qubit_time_index: dict[cirq.Qid, int] = {}
    measurement_time_index: dict[cirq.MeasurementKey, int] = {}
    control_time_index: dict[cirq.MeasurementKey, int] = {}
    last_ignored_ops_time_index = 0
    for moment in circuit:
        ignored_ops = []
        op_time_indices = {}
        for op in moment:
            min_time_index_for_op = circuits.circuit.get_earliest_accommodating_moment_index(
                op, qubit_time_index, measurement_time_index, control_time_index
            )
            ignored_op = any(tag in op.tags for tag in context.tags_to_ignore)
            if not ignored_op:
                op_class = _get_op_class(op, classifiers)
            else:
                op_class = len(classifiers)
                ignored_ops.append(op)
                min_time_index_for_op = max(min_time_index_for_op, last_ignored_ops_time_index + 1)
            time_index = (min_time_index_for_op // num_classes) * num_classes + op_class
            if time_index < min_time_index_for_op:
                time_index += num_classes
            op_time_indices[op] = time_index
        if ignored_ops:
            last_ignored_ops_time_index = max(op_time_indices[op] for op in ignored_ops)
            for op in ignored_ops:
                op_time_indices[op] = last_ignored_ops_time_index
        for op, time_index in op_time_indices.items():
            if time_index >= len(new_moments):
                new_moments += [[] for _ in range(num_classes)]
            new_moments[time_index].append(op)
            for qubit in op.qubits:
                qubit_time_index[qubit] = time_index
            for key in protocols.measurement_key_objs(op):
                measurement_time_index[key] = time_index
            for key in protocols.control_keys(op):
                control_time_index[key] = time_index
    return circuits.Circuit(circuits.Moment(moment) for moment in new_moments if moment)
def _get_classifiers(
    circuit: circuits.AbstractCircuit, categories: Iterable[Category]
) -> list[Classifier]:
    classifiers = [_category_to_classifier(cat) for cat in categories] + [_mock_classifier]
    class_is_used = [False for _ in classifiers]
    for op in circuit.all_operations():
        class_is_used[_get_op_class(op, classifiers)] = True
        if all(class_is_used):
            break
    return [classifier for classifier, is_used in zip(classifiers, class_is_used) if is_used]
def _category_to_classifier(category) -> Classifier:
    if isinstance(category, ops.Gate):
        return lambda op: op.gate == category
    if isinstance(category, ops.Operation):
        return lambda op: op == category
    elif isinstance(category, type) and issubclass(category, ops.Gate):
        return lambda op: isinstance(op.gate, category)
    elif isinstance(category, type) and issubclass(category, ops.Operation):
        return lambda op: isinstance(op, category)
    elif callable(category):
        return lambda op: category(op)
    else:
        raise TypeError(
            f'Unrecognized classifier type '
            f'{type(category)} ({category!r}).\n'
            f'Expected a cirq.Gate, cirq.Operation, '
            f'Type[cirq.Gate], Type[cirq.Operation], '
            f'or Callable[[cirq.Operation], bool].'
        )
def _mock_classifier(op: cirq.Operation) -> bool:
    return False  # pragma: no cover
def _get_op_class(op: cirq.Operation, classifiers: Sequence[Classifier]) -> int:
    for class_index, classifier in enumerate(classifiers):
        if classifier is _mock_classifier:
            mock_classifier_index = class_index
        elif classifier(op):
            return class_index
    try:
        return mock_classifier_index
    except NameError:
        raise ValueError(f"Operation {op} not identified by any classifier")

from __future__ import annotations
import re
from collections.abc import Hashable
from typing import TYPE_CHECKING
import attrs
import sympy
from attrs import validators
from cirq import ops
from cirq.transformers import transformer_api, transformer_primitives
if TYPE_CHECKING:
    import cirq
@attrs.frozen
class SymbolizeTag:
    prefix: str = attrs.field(
        validator=validators.and_(validators.instance_of(str), validators.min_len(1))
    )
@transformer_api.transformer
def symbolize_single_qubit_gates_by_indexed_tags(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    symbolize_tag: SymbolizeTag = SymbolizeTag(prefix="TO-PHXZ"),
) -> cirq.Circuit:
    def _map_func(op: cirq.Operation, _):
        tags: set[Hashable] = set(op.tags)
        tag_id: None | int = None
        for tag in tags:
            if re.fullmatch(f"{symbolize_tag.prefix}_\\d+", str(tag)):
                if tag_id is None:
                    tag_id = int(str(tag).rsplit("_", maxsplit=-1)[-1])
                else:
                    raise ValueError(f"Multiple tags are prefixed with {symbolize_tag.prefix}.")
        if tag_id is None:
            return op
        tags.remove(f"{symbolize_tag.prefix}_{tag_id}")
        phxz_params = {
            "x_exponent": sympy.Symbol(f"x{tag_id}"),
            "z_exponent": sympy.Symbol(f"z{tag_id}"),
            "axis_phase_exponent": sympy.Symbol(f"a{tag_id}"),
        }
        return ops.PhasedXZGate(**phxz_params).on(*op.qubits).with_tags(*tags)
    return transformer_primitives.map_operations(
        circuit.freeze(),
        _map_func,
        deep=context.deep if context else False,
        tags_to_ignore=context.tags_to_ignore if context else [],
    ).unfreeze(copy=False)

from __future__ import annotations
from typing import TYPE_CHECKING
from cirq import circuits, protocols
from cirq.transformers import transformer_api
if TYPE_CHECKING:
    import cirq
def find_terminal_measurements(circuit: cirq.AbstractCircuit) -> list[tuple[int, cirq.Operation]]:
    open_qubits: set[cirq.Qid] = set(circuit.all_qubits())
    seen_control_keys: set[cirq.MeasurementKey] = set()
    terminal_measurements: set[tuple[int, cirq.Operation]] = set()
    for i in range(len(circuit) - 1, -1, -1):
        moment = circuit[i]
        for q in open_qubits:
            op = moment.operation_at(q)
            if (
                op is not None
                and open_qubits.issuperset(op.qubits)
                and protocols.is_measurement(op)
                and not (seen_control_keys & protocols.measurement_key_objs(op))
            ):
                terminal_measurements.add((i, op))
        open_qubits -= moment.qubits
        seen_control_keys |= protocols.control_keys(moment)
        if not open_qubits:
            break
    return list(terminal_measurements)
@transformer_api.transformer(add_deep_support=True)
def synchronize_terminal_measurements(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    after_other_operations: bool = True,
) -> cirq.Circuit:
    if context is None:
        context = transformer_api.TransformerContext()
    terminal_measurements = [
        (i, op)
        for i, op in find_terminal_measurements(circuit)
        if set(op.tags).isdisjoint(context.tags_to_ignore)
    ]
    ret = circuit.unfreeze(copy=True)
    if not terminal_measurements:
        return ret
    ret.batch_remove(terminal_measurements)
    if ret[-1] and after_other_operations:
        ret.append(circuits.Moment())
    ret[-1] = ret[-1].with_operations(op for _, op in terminal_measurements)
    return ret

from __future__ import annotations
import itertools
from collections.abc import Callable, Hashable
from typing import TYPE_CHECKING
from cirq.transformers import transformer_api, transformer_primitives
if TYPE_CHECKING:
    import cirq
@transformer_api.transformer
def index_tags(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    target_tags: set[Hashable] | None = None,
) -> cirq.Circuit:
    if context and context.tags_to_ignore:
        raise ValueError("index_tags doesn't support tags_to_ignore, use function args instead.")
    if not target_tags:
        return circuit.unfreeze(copy=False)
    tag_iter_by_tags = {tag: itertools.count(start=0, step=1) for tag in target_tags}
    def _map_func(op: cirq.Operation, _) -> cirq.OP_TREE:
        tag_set = set(op.tags)
        nonlocal tag_iter_by_tags
        for tag in target_tags.intersection(op.tags):
            tag_set.remove(tag)
            tag_set.add(f"{tag}_{next(tag_iter_by_tags[tag])}")
        return op.untagged.with_tags(*tag_set)
    return transformer_primitives.map_operations(
        circuit, _map_func, deep=context.deep if context else False
    ).unfreeze(copy=False)
@transformer_api.transformer
def remove_tags(
    circuit: cirq.AbstractCircuit,
    *,
    context: cirq.TransformerContext | None = None,
    target_tags: set[Hashable] | None = None,
    remove_if: Callable[[Hashable], bool] = lambda _: False,
) -> cirq.Circuit:
    if context and context.tags_to_ignore:
        raise ValueError("remove_tags doesn't support tags_to_ignore, use function args instead.")
    target_tags = target_tags or set()
    def _map_func(op: cirq.Operation, _) -> cirq.OP_TREE:
        remaining_tags = set()
        for tag in op.tags:
            if not remove_if(tag) and tag not in target_tags:
                remaining_tags.add(tag)
        return op.untagged.with_tags(*remaining_tags)
    return transformer_primitives.map_operations(
        circuit, _map_func, deep=context.deep if context else False
    ).unfreeze(copy=False)

