            return NotImplemented
        return self.total_picos() != other.total_picos()
    def __gt__(self, other):
        other = _attempt_duration_like_to_duration(other)
        if other is None:
            return NotImplemented
        return self.total_picos() > other.total_picos()
    def __lt__(self, other):
        other = _attempt_duration_like_to_duration(other)
