MAX_REPETITIONS_PER_JOB = 3_000_000
document(
    MAX_REPETITIONS_PER_JOB,
    ,
)
def _with_parameterized_layers(
    circuit: cirq.AbstractCircuit, qubits: Sequence[cirq.Qid], needs_init_layer: bool
) -> cirq.Circuit:
    x_beg_mom = circuits.Moment([ops.X(q) ** sympy.Symbol(f'{q}-Xi') for q in qubits])
    y_beg_mom = circuits.Moment([ops.Y(q) ** sympy.Symbol(f'{q}-Yi') for q in qubits])
    x_end_mom = circuits.Moment([ops.X(q) ** sympy.Symbol(f'{q}-Xf') for q in qubits])
    y_end_mom = circuits.Moment([ops.Y(q) ** sympy.Symbol(f'{q}-Yf') for q in qubits])
    meas_mom = circuits.Moment([ops.measure(*qubits, key='z')])
    if needs_init_layer:
        total_circuit = circuits.Circuit([x_beg_mom, y_beg_mom])
        total_circuit += circuit.unfreeze()
    else:
        total_circuit = circuit.unfreeze()
    total_circuit.append([x_end_mom, y_end_mom, meas_mom])
    return total_circuit
class StoppingCriteria(abc.ABC):
    @abc.abstractmethod
    def more_repetitions(self, accumulator: BitstringAccumulator) -> int:
@dataclasses.dataclass(frozen=True)
class VarianceStoppingCriteria(StoppingCriteria):
    variance_bound: float
    repetitions_per_chunk: int = 10_000
    def more_repetitions(self, accumulator: BitstringAccumulator) -> int:
        if len(accumulator.bitstrings) == 0:
            return self.repetitions_per_chunk
        cov = accumulator.covariance()
        n_terms = cov.shape[0]
        sum_variance = np.sum(cov)
        var_of_the_e = sum_variance / len(accumulator.bitstrings)
        vpt = var_of_the_e / n_terms
        if vpt <= self.variance_bound:
            return 0
        return self.repetitions_per_chunk
    def _json_dict_(self):
        return protocols.dataclass_json_dict(self)
@dataclasses.dataclass(frozen=True)
class RepetitionsStoppingCriteria(StoppingCriteria):
    total_repetitions: int
    repetitions_per_chunk: int = 10_000
    def more_repetitions(self, accumulator: BitstringAccumulator) -> int:
        done = accumulator.n_repetitions
        todo = self.total_repetitions - done
        if todo <= 0:
            return 0
        to_do_next = min(self.repetitions_per_chunk, todo)
        return to_do_next
    def _json_dict_(self):
        return protocols.dataclass_json_dict(self)
_OBS_TO_PARAM_VAL: dict[tuple[cirq.Pauli, bool], tuple[float, float]] = {
    (ops.X, False): (0, -1 / 2),
    (ops.X, True): (0, +1 / 2),
    (ops.Y, False): (1 / 2, 0),
    (ops.Y, True): (-1 / 2, 0),
    (ops.Z, False): (0, 0),
    (ops.Z, True): (1, 0),
}
_STATE_TO_PARAM_VAL: dict[_NamedOneQubitState, tuple[float, float]] = {
    value.KET_PLUS: (0, +1 / 2),
    value.KET_MINUS: (0, -1 / 2),
    value.KET_IMAG: (-1 / 2, 0),
    value.KET_MINUS_IMAG: (+1 / 2, 0),
    value.KET_ZERO: (0, 0),
    value.KET_ONE: (1, 0),
}
def _get_params_for_setting(
    setting: InitObsSetting,
    flips: Iterable[bool],
    qubits: Sequence[cirq.Qid],
    needs_init_layer: bool,
) -> dict[str, float]:
    setting = _pad_setting(setting, qubits)
    params = {}
    for qubit, flip in itertools.zip_longest(qubits, flips):
        if qubit is None or flip is None:
            raise ValueError("`qubits` and `flips` must be equal length")
        pauli = setting.observable[qubit]
        xf_param, yf_param = _OBS_TO_PARAM_VAL[pauli, flip]
        params[f'{qubit}-Xf'] = xf_param
        params[f'{qubit}-Yf'] = yf_param
        if needs_init_layer:
            state = setting.init_state[qubit]
            xi_param, yi_param = _STATE_TO_PARAM_VAL[state]
            params[f'{qubit}-Xi'] = xi_param
            params[f'{qubit}-Yi'] = yi_param
    return params
def _pad_setting(
    max_setting: InitObsSetting,
    qubits: Sequence[cirq.Qid],
    pad_init_state_with=value.KET_ZERO,
    pad_obs_with: cirq.Gate = ops.Z,
) -> InitObsSetting:
    obs = max_setting.observable
    assert obs.coefficient == 1, "Only the max_setting should be padded."
    for qubit in qubits:
        if not qubit in obs:
            obs *= pad_obs_with(qubit)
    init_state = max_setting.init_state
    init_state_original_qubits = init_state.qubits
    for qubit in qubits:
        if not qubit in init_state_original_qubits:
            init_state *= pad_init_state_with(qubit)
    return InitObsSetting(init_state=init_state, observable=obs)
def _aggregate_n_repetitions(next_chunk_repetitions: set[int]) -> int:
    if len(next_chunk_repetitions) == 1:
        return list(next_chunk_repetitions)[0]
    reps = max(next_chunk_repetitions)
    warnings.warn(
        f"The stopping criteria specified a various numbers of "
        f"repetitions to perform next. To be able to submit as a single "
        f"sweep, the largest value will be used: {reps}."
    )
    return reps
def _check_meas_specs_still_todo(
    meas_specs: list[_MeasurementSpec],
    accumulators: Mapping[_MeasurementSpec, BitstringAccumulator],
    stopping_criteria: StoppingCriteria,
) -> tuple[list[_MeasurementSpec], int]:
    still_todo = []
    repetitions_set: set[int] = set()
    for meas_spec in meas_specs:
        accumulator = accumulators[meas_spec]
        more_repetitions = stopping_criteria.more_repetitions(accumulator)
        if more_repetitions < 0:
            raise ValueError(
                "Stopping criteria's `more_repetitions` should return 0 or a positive number."
            )
        if more_repetitions == 0:
            continue
        repetitions_set.add(more_repetitions)
        still_todo.append(meas_spec)
    if len(still_todo) == 0:
        return still_todo, 0
    repetitions = _aggregate_n_repetitions(repetitions_set)
    total_repetitions = len(still_todo) * repetitions
    if total_repetitions > MAX_REPETITIONS_PER_JOB:
        old_repetitions = repetitions
        repetitions = MAX_REPETITIONS_PER_JOB // len(still_todo)
        if repetitions < 10:
            raise ValueError(
                "You have requested too many parameter settings to batch your job effectively. "
                "Consider fewer sweeps or manually splitting sweeps into multiple jobs."
            )
        warnings.warn(
            f"The number of requested sweep parameters is high. To avoid a batched job with more "
            f"than {MAX_REPETITIONS_PER_JOB} shots, the number of shots per call to run_sweep "
            f"(per parameter value) will be throttled from {old_repetitions} to {repetitions}."
        )
    return still_todo, repetitions
@dataclasses.dataclass(frozen=True)
class _FlippyMeasSpec:
    meas_spec: _MeasurementSpec
    flips: np.ndarray
    qubits: Sequence[cirq.Qid]
    def param_tuples(self, *, needs_init_layer=True):
        yield from _get_params_for_setting(
            self.meas_spec.max_setting,
            flips=self.flips,
            qubits=self.qubits,
            needs_init_layer=needs_init_layer,
        ).items()
        yield from self.meas_spec.circuit_params.items()
def _subdivide_meas_specs(
    meas_specs: Iterable[_MeasurementSpec],
    repetitions: int,
    qubits: Sequence[cirq.Qid],
    readout_symmetrization: bool,
) -> tuple[list[_FlippyMeasSpec], int]:
    n_qubits = len(qubits)
    flippy_mspecs = []
    for meas_spec in meas_specs:
        all_normal = np.zeros(n_qubits, dtype=bool)
        flippy_mspecs.append(_FlippyMeasSpec(meas_spec=meas_spec, flips=all_normal, qubits=qubits))
        if readout_symmetrization:
            all_flipped = np.ones(n_qubits, dtype=bool)
            flippy_mspecs.append(
                _FlippyMeasSpec(meas_spec=meas_spec, flips=all_flipped, qubits=qubits)
            )
    if readout_symmetrization:
        repetitions //= 2
    return flippy_mspecs, repetitions
def _to_sweep(param_tuples):
    to_sweep = [dict(pt) for pt in param_tuples]
    to_sweep = study.to_sweep(to_sweep)
    return to_sweep
def _parse_checkpoint_options(
    checkpoint: bool, checkpoint_fn: str | None, checkpoint_other_fn: str | None
) -> tuple[str | None, str | None]:
    if not checkpoint:
        if checkpoint_fn is not None or checkpoint_other_fn is not None:
            raise ValueError(
                "Checkpoint filenames were provided but `checkpoint` was set to False."
            )
        return None, None
    if checkpoint_fn is None:
        checkpoint_dir = tempfile.mkdtemp()
        chk_basename = 'observables'
        checkpoint_fn = f'{checkpoint_dir}/{chk_basename}.json'
    if checkpoint_other_fn is None:
        checkpoint_dir = os.path.dirname(checkpoint_fn)
        chk_basename = os.path.basename(checkpoint_fn)
        chk_basename, dot, ext = chk_basename.rpartition('.')
        if chk_basename == '' or dot != '.' or ext == '':
            raise ValueError(
                f"You specified `checkpoint_fn={checkpoint_fn!r}` which does not follow the "
                f"pattern of 'filename.extension'. Please follow this pattern or fully specify "
                f"`checkpoint_other_fn`."
            )
        if ext != 'json':
            raise ValueError(
                "Please use a `.json` filename or fully "
                "specify checkpoint_fn and checkpoint_other_fn"
            )
        if checkpoint_dir == '':
            checkpoint_other_fn = f'{chk_basename}.prev.json'
        else:
            checkpoint_other_fn = f'{checkpoint_dir}/{chk_basename}.prev.json'
    if checkpoint_fn == checkpoint_other_fn:
        raise ValueError(
            f"`checkpoint_fn` and `checkpoint_other_fn` were set to the same "
            f"filename: {checkpoint_fn}. Please use two different filenames."
        )
    return checkpoint_fn, checkpoint_other_fn
@dataclasses.dataclass(frozen=True)
class CheckpointFileOptions:
    checkpoint: bool = False
    checkpoint_fn: str | None = None
    checkpoint_other_fn: str | None = None
    def __post_init__(self):
        fn, other_fn = _parse_checkpoint_options(
            self.checkpoint, self.checkpoint_fn, self.checkpoint_other_fn
        )
        object.__setattr__(self, 'checkpoint_fn', fn)
        object.__setattr__(self, 'checkpoint_other_fn', other_fn)
    def maybe_to_json(self, obj: Any):
        if not self.checkpoint:
            return
        assert self.checkpoint_fn is not None, 'mypy'
        assert self.checkpoint_other_fn is not None, 'mypy'
        if os.path.exists(self.checkpoint_fn):
            os.replace(self.checkpoint_fn, self.checkpoint_other_fn)
        protocols.to_json(obj, self.checkpoint_fn)
def _needs_init_layer(grouped_settings: dict[InitObsSetting, list[InitObsSetting]]) -> bool:
    for max_setting in grouped_settings.keys():
        if any(st is not value.KET_ZERO for _, st in max_setting.init_state):
            return True
    return False
def measure_grouped_settings(
    circuit: cirq.AbstractCircuit,
    grouped_settings: dict[InitObsSetting, list[InitObsSetting]],
    sampler: cirq.Sampler,
    stopping_criteria: StoppingCriteria,
    *,
    readout_symmetrization: bool = False,
    circuit_sweep: cirq.Sweepable = None,
    readout_calibrations: BitstringAccumulator | None = None,
    checkpoint: CheckpointFileOptions = CheckpointFileOptions(),
) -> list[BitstringAccumulator]:
    if readout_calibrations is not None and not readout_symmetrization:
        raise ValueError("Readout calibration only works if `readout_symmetrization` is enabled.")
    qubits = sorted({q for ms in grouped_settings.keys() for q in ms.init_state.qubits})
    qubit_to_index = {q: i for i, q in enumerate(qubits)}
    needs_init_layer = _needs_init_layer(grouped_settings)
    measurement_param_circuit = _with_parameterized_layers(circuit, qubits, needs_init_layer)
    accumulators = {}
    meas_specs_todo = []
    for max_setting, param_resolver in itertools.product(
        grouped_settings.keys(), study.to_resolvers(circuit_sweep)
    ):
        circuit_params = param_resolver.param_dict
        meas_spec = _MeasurementSpec(max_setting=max_setting, circuit_params=circuit_params)
        accumulator = BitstringAccumulator(
            meas_spec=meas_spec,
            simul_settings=grouped_settings[max_setting],
            qubit_to_index=qubit_to_index,
            readout_calibration=readout_calibrations,
        )
        accumulators[meas_spec] = accumulator
        meas_specs_todo += [meas_spec]
    while True:
        meas_specs_todo, repetitions = _check_meas_specs_still_todo(
            meas_specs=meas_specs_todo,
            accumulators=accumulators,
            stopping_criteria=stopping_criteria,
        )
        if len(meas_specs_todo) == 0:
            break
        flippy_meas_specs, repetitions = _subdivide_meas_specs(
            meas_specs=meas_specs_todo,
            repetitions=repetitions,
            qubits=qubits,
            readout_symmetrization=readout_symmetrization,
        )
        resolved_params = [
            flippy_ms.param_tuples(needs_init_layer=needs_init_layer)
            for flippy_ms in flippy_meas_specs
        ]
        resolved_params = _to_sweep(resolved_params)
        results = sampler.run_sweep(
            program=measurement_param_circuit, params=resolved_params, repetitions=repetitions
        )
        assert len(results) == len(
            flippy_meas_specs
        ), 'Not as many results received as sweeps requested!'
        for flippy_ms, result in zip(flippy_meas_specs, results):
            accumulator = accumulators[flippy_ms.meas_spec]
            bitstrings = np.logical_xor(flippy_ms.flips, result.measurements['z'])
            accumulator.consume_results(bitstrings.astype(np.uint8, casting='safe'))
        checkpoint.maybe_to_json(list(accumulators.values()))
    return list(accumulators.values())
_GROUPING_FUNCS: dict[str, GROUPER_T] = {'greedy': group_settings_greedy}
def _parse_grouper(grouper: str | GROUPER_T = group_settings_greedy) -> GROUPER_T:
    if isinstance(grouper, str):
        try:
            grouper = _GROUPING_FUNCS[grouper.lower()]
        except KeyError:
            raise ValueError(f"Unknown grouping function {grouper}")
    return grouper
def _get_all_qubits(
    circuit: cirq.AbstractCircuit, observables: Iterable[cirq.PauliString]
) -> list[cirq.Qid]:
    qubit_set = set()
    for obs in observables:
        qubit_set |= set(obs.qubits)
    qubit_set |= circuit.all_qubits()
    return sorted(qubit_set)
def measure_observables(
    circuit: cirq.AbstractCircuit,
    observables: Iterable[cirq.PauliString],
    sampler: cirq.Simulator | cirq.Sampler,
    stopping_criteria: StoppingCriteria,
    *,
    readout_symmetrization: bool = False,
    circuit_sweep: cirq.Sweepable | None = None,
    grouper: str | GROUPER_T = group_settings_greedy,
    readout_calibrations: BitstringAccumulator | None = None,
    checkpoint: CheckpointFileOptions = CheckpointFileOptions(),
) -> list[ObservableMeasuredResult]:
    qubits = _get_all_qubits(circuit, observables)
    settings = list(observables_to_settings(observables, qubits))
    actual_grouper = _parse_grouper(grouper)
    grouped_settings = actual_grouper(settings)
    accumulators = measure_grouped_settings(
        circuit=circuit,
        grouped_settings=grouped_settings,
        sampler=sampler,
        stopping_criteria=stopping_criteria,
        circuit_sweep=circuit_sweep,
        readout_symmetrization=readout_symmetrization,
        readout_calibrations=readout_calibrations,
        checkpoint=checkpoint,
    )
    return flatten_grouped_results(accumulators)
def measure_observables_df(
    circuit: cirq.AbstractCircuit,
    observables: Iterable[cirq.PauliString],
    sampler: cirq.Simulator | cirq.Sampler,
    stopping_criteria: StoppingCriteria,
    *,
    readout_symmetrization: bool = False,
    circuit_sweep: cirq.Sweepable | None = None,
    grouper: str | GROUPER_T = group_settings_greedy,
    readout_calibrations: BitstringAccumulator | None = None,
    checkpoint: CheckpointFileOptions = CheckpointFileOptions(),
):
    results = measure_observables(
        circuit=circuit,
        observables=observables,
        sampler=sampler,
        stopping_criteria=stopping_criteria,
        readout_symmetrization=readout_symmetrization,
        circuit_sweep=circuit_sweep,
        grouper=grouper,
        readout_calibrations=readout_calibrations,
        checkpoint=checkpoint,
    )
    df = pd.DataFrame(res.as_dict() for res in results)
    return df

from __future__ import annotations
import dataclasses
import datetime
from collections.abc import Iterable, Mapping
from typing import Any, TYPE_CHECKING
import numpy as np
import sympy
from cirq import ops, protocols, value
from cirq._compat import proper_repr
from cirq.work.observable_settings import (
    _max_weight_observable,
    _max_weight_state,
    _MeasurementSpec,
    InitObsSetting,
    zeros_state,
)
if TYPE_CHECKING:
    import cirq
def _check_and_get_real_coef(observable: cirq.PauliString, atol: float):
    coef = observable.coefficient
    if isinstance(coef, sympy.Expr) or not np.isclose(coef.imag, 0, atol=atol):
        raise ValueError(f"{observable} has a complex or symbolic coefficient.")
    return coef.real
def _obs_vals_from_measurements(
    bitstrings: np.ndarray,
    qubit_to_index: Mapping[cirq.Qid, int],
    observable: cirq.PauliString,
    atol: float,
):
    idxs = [qubit_to_index[q] for q in observable.keys()]
    selected_bitstrings = np.asarray(bitstrings[:, idxs], dtype=np.int8)
    selected_obsstrings = 1 - 2 * selected_bitstrings
    coeff = _check_and_get_real_coef(observable, atol=atol)
    obs_vals = coeff * np.prod(selected_obsstrings, axis=1)
    return obs_vals
def _stats_from_measurements(
    bitstrings: np.ndarray,
    qubit_to_index: Mapping[cirq.Qid, int],
    observable: cirq.PauliString,
    atol: float,
) -> tuple[float, float]:
    obs_vals = _obs_vals_from_measurements(bitstrings, qubit_to_index, observable, atol=atol)
    obs_mean = np.mean(obs_vals)
    obs_err = np.var(obs_vals, ddof=1) / len(obs_vals)
    return obs_mean.item(), obs_err.item()
@dataclasses.dataclass(frozen=True)
class ObservableMeasuredResult:
    setting: InitObsSetting
    mean: float
    variance: float
    repetitions: int
    circuit_params: Mapping[str | sympy.Expr, value.Scalar | sympy.Expr]
    __hash__ = None  # type: ignore
    def __repr__(self):
        return (
            f'cirq.work.ObservableMeasuredResult('
            f'setting={self.setting!r}, '
            f'mean={self.mean!r}, '
            f'variance={self.variance!r}, '
            f'repetitions={self.repetitions!r}, '
            f'circuit_params={self.circuit_params!r})'
        )
    @property
    def init_state(self):
        return self.setting.init_state
    @property
    def observable(self):
        return self.setting.observable
    @property
    def stddev(self):
        return np.sqrt(self.variance)
    def as_dict(self) -> dict[str, Any]:
        record = dataclasses.asdict(self)
        del record['circuit_params']
        del record['setting']
        record['init_state'] = self.init_state
        record['observable'] = self.observable
        circuit_param_dict = {f'param.{k}': v for k, v in self.circuit_params.items()}
        record.update(**circuit_param_dict)
        return record
    def _json_dict_(self):
        return protocols.dataclass_json_dict(self)
def _setting_to_z_observable(setting: InitObsSetting):
    qubits = setting.observable.qubits
    return InitObsSetting(
        init_state=zeros_state(qubits),
        observable=ops.PauliString(qubit_pauli_map={q: ops.Z for q in qubits}),
    )
class BitstringAccumulator:
    def __init__(
        self,
        meas_spec: _MeasurementSpec,
        simul_settings: list[InitObsSetting],
        qubit_to_index: Mapping[cirq.Qid, int],
        bitstrings: np.ndarray | None = None,
        chunksizes: np.ndarray | None = None,
        timestamps: np.ndarray | None = None,
        readout_calibration: BitstringAccumulator | None = None,
    ):
        self._meas_spec = meas_spec
        self._simul_settings = simul_settings
        self._qubit_to_index = qubit_to_index
        self._readout_calibration = readout_calibration
        self.bitstrings: np.ndarray[tuple[int, ...], np.dtype[np.uint8]]
        if bitstrings is None:
            n_bits = len(qubit_to_index)
            self.bitstrings = np.zeros((0, n_bits), dtype=np.uint8)
        else:
            self.bitstrings = np.asarray(bitstrings, dtype=np.uint8)
        self.chunksizes: np.ndarray[tuple[int, ...], np.dtype[np.int64]]
        if chunksizes is None:
            self.chunksizes = np.zeros((0,), dtype=np.int64)
        else:
            self.chunksizes = np.asarray(chunksizes, dtype=np.int64)
        self.timestamps: np.ndarray[tuple[int, ...], np.dtype[np.datetime64]]
        if timestamps is None:
            self.timestamps = np.zeros((0,), dtype='datetime64[us]')
        else:
            self.timestamps = np.asarray(timestamps, dtype='datetime64[us]')
        if len(self.chunksizes) != len(self.timestamps):
            raise ValueError(
                "Invalid BitstringAccumulator state. "
                "`chunksizes` and `timestamps` must have the same length."
            )
        if np.sum(self.chunksizes) != len(self.bitstrings):
            raise ValueError(
                "Invalid BitstringAccumulator state. "
                "`chunksizes` must sum to the number of bitstrings."
            )
    @property
    def meas_spec(self):
        return self._meas_spec
    @property
    def max_setting(self):
        return self.meas_spec.max_setting
    @property
    def circuit_params(self):
        return self.meas_spec.circuit_params
    @property
    def simul_settings(self):
        return self._simul_settings
    @property
    def qubit_to_index(self):
        return self._qubit_to_index
    def consume_results(self, bitstrings):
        if bitstrings.dtype != np.uint8:
            raise ValueError("`bitstrings` should be of type np.uint8")
        self.bitstrings = np.append(self.bitstrings, bitstrings, axis=0)
        self.chunksizes = np.append(self.chunksizes, [len(bitstrings)], axis=0)
        self.timestamps = np.append(self.timestamps, [np.datetime64(datetime.datetime.now())])
    @property
    def n_repetitions(self):
        return len(self.bitstrings)
    @property
    def results(self) -> Iterable[ObservableMeasuredResult]:
        for setting in self._simul_settings:
            yield ObservableMeasuredResult(
                setting=setting,
                mean=self.mean(setting),
                variance=self.variance(setting),
                repetitions=len(self.bitstrings),
                circuit_params=self._meas_spec.circuit_params,
            )
    @property
    def records(self):
        for result in self.results:
            yield result.as_dict()
    def _json_dict_(self):
        from cirq.study.result import _pack_digits
        def ndarray_to_hex_str(a):
            return _pack_digits(a, pack_bits='never')[0]
        return {
            'meas_spec': self.meas_spec,
            'simul_settings': self.simul_settings,
            'qubit_to_index': list(self.qubit_to_index.items()),
            'bitstrings': ndarray_to_hex_str(self.bitstrings),
            'chunksizes': ndarray_to_hex_str(self.chunksizes),
            'timestamps': ndarray_to_hex_str(self.timestamps),
        }
    @classmethod
    def _from_json_dict_(
        cls,
        *,
        meas_spec,
        simul_settings,
        qubit_to_index,
        bitstrings,
        chunksizes,
        timestamps,
        **kwargs,
    ):
        from cirq.study.result import _unpack_digits
        def hex_str_to_ndarray(hexstr):
            return _unpack_digits(hexstr, binary=False, dtype=None, shape=None)
        return cls(
            meas_spec=meas_spec,
            simul_settings=simul_settings,
            qubit_to_index=dict(qubit_to_index),
            bitstrings=hex_str_to_ndarray(bitstrings),
            chunksizes=hex_str_to_ndarray(chunksizes),
            timestamps=hex_str_to_ndarray(timestamps),
        )
    def __eq__(self, other):
        if not isinstance(other, BitstringAccumulator):
            return NotImplemented
        if (
            self.max_setting != other.max_setting
            or self.simul_settings != other.simul_settings
            or self.circuit_params != other.circuit_params
            or self.qubit_to_index != other.qubit_to_index
        ):
            return False
        if not np.array_equal(self.bitstrings, other.bitstrings):
            return False
        if not np.array_equal(self.chunksizes, other.chunksizes):
            return False
        if not np.array_equal(self.timestamps, other.timestamps):
            return False
        return True
    def summary_string(self, setting: InitObsSetting, number_fmt='.3f'):
        return (
            f'{setting}: {self.mean(setting):{number_fmt}} +- {self.stderr(setting):{number_fmt}}'
        )
    def __repr__(self):
        return (
            f'cirq.work.BitstringAccumulator('
            f'meas_spec={self.meas_spec!r}, '
            f'simul_settings={self.simul_settings!r}, '
            f'qubit_to_index={self.qubit_to_index!r}, '
            f'bitstrings={proper_repr(self.bitstrings)}, '
            f'chunksizes={proper_repr(self.chunksizes)}, '
            f'timestamps={proper_repr(self.timestamps)}, '
            f'readout_calibration={self._readout_calibration!r})'
        )
    def __str__(self):
        s = f'Accumulator {self.max_setting}; {self.n_repetitions} repetitions\n'
        s += '\n'.join('  ' + self.summary_string(setting) for setting in self._simul_settings)
        return s
    def covariance(self, *, atol=1e-8) -> np.ndarray:
        if len(self.bitstrings) == 0:
            raise ValueError("No measurements")
        all_obs_vals = np.array(
            [
                _obs_vals_from_measurements(
                    bitstrings=self.bitstrings,
                    qubit_to_index=self._qubit_to_index,
                    observable=setting.observable,
                    atol=atol,
                )
                for setting in self._simul_settings
            ]
        )
        if all_obs_vals.shape[0] == 1:
            cov = np.array([[np.var(all_obs_vals[0], ddof=1)]])
            return cov
        cov = np.cov(all_obs_vals, ddof=1) / all_obs_vals.shape[1]
        return cov
    def _validate_setting(self, setting: InitObsSetting, what: str):
        mws = _max_weight_state([self.max_setting.init_state, setting.init_state])
        mwo = _max_weight_observable([self.max_setting.observable, setting.observable])
        if mws is None or mwo is None:
            raise ValueError(
                f"You requested the {what} for a setting that is not compatible "
                f"with this BitstringAccumulator's meas_spec."
            )
    def variance(self, setting: InitObsSetting, *, atol: float = 1e-8):
        if len(self.bitstrings) == 0:
            raise ValueError("No measurements")
        self._validate_setting(setting, what='variance')
        mean, var = _stats_from_measurements(
            bitstrings=self.bitstrings,
            qubit_to_index=self._qubit_to_index,
            observable=setting.observable,
            atol=atol,
        )
        if self._readout_calibration is not None:
            a = mean
            if np.isclose(a, 0, atol=atol):
                return np.inf
            var_a = var
            ro_setting = _setting_to_z_observable(setting)
            b = self._readout_calibration.mean(ro_setting)
            if np.isclose(b, 0, atol=atol):
                return np.inf
            var_b = self._readout_calibration.variance(ro_setting)
            f = a / b
            var = f**2 * (var_a / (a**2) + var_b / (b**2))
        return var
    def stderr(self, setting: InitObsSetting, *, atol: float = 1e-8):
        return np.sqrt(self.variance(setting, atol=atol))
    def means(self, *, atol: float = 1e-8) -> np.ndarray:
        return np.asarray([self.mean(setting, atol=atol) for setting in self.simul_settings])
    def mean(self, setting: InitObsSetting, *, atol: float = 1e-8):
        if len(self.bitstrings) == 0:
            raise ValueError("No measurements")
        self._validate_setting(setting, what='mean')
        mean, _ = _stats_from_measurements(
            bitstrings=self.bitstrings,
            qubit_to_index=self._qubit_to_index,
            observable=setting.observable,
            atol=atol,
        )
        if self._readout_calibration is not None:
            ro_setting = _setting_to_z_observable(setting)
            return mean / self._readout_calibration.mean(ro_setting, atol=atol)
        return mean
def flatten_grouped_results(
    grouped_results: list[BitstringAccumulator],
) -> list[ObservableMeasuredResult]:
    return [res for acc in grouped_results for res in acc.results]

from __future__ import annotations
import dataclasses
import numbers
from collections.abc import Iterable, Mapping
from typing import TYPE_CHECKING
import sympy
from cirq import ops, protocols, value
if TYPE_CHECKING:
    import cirq
    from cirq.value.product_state import _NamedOneQubitState
@dataclasses.dataclass(frozen=True)
class InitObsSetting:
    init_state: value.ProductState
    observable: ops.PauliString
    def __post_init__(self):
        init_qs = self.init_state.qubits
        obs_qs = self.observable.qubits
        if set(obs_qs) > set(init_qs):
            raise ValueError(
                "`observable`'s qubits should be a subset of those "
                "found in `init_state`. "
                f"observable qubits: {obs_qs}. init_state qubits: {init_qs}"
            )
    def __str__(self):
        return f'{self.init_state} → {self.observable}'
    def __repr__(self):
        return (
            f'cirq.work.InitObsSetting('
            f'init_state={self.init_state!r}, '
            f'observable={self.observable!r})'
        )
    def _json_dict_(self):
        return protocols.dataclass_json_dict(self)
def _max_weight_observable(observables: Iterable[ops.PauliString]) -> ops.PauliString | None:
    qubit_pauli_map: dict[ops.Qid, ops.Pauli] = {}
    for observable in observables:
        for qubit, pauli in observable.items():
            if qubit in qubit_pauli_map:
                if qubit_pauli_map[qubit] != pauli:
                    return None
            else:
                qubit_pauli_map[qubit] = pauli
    return ops.PauliString(qubit_pauli_map)
def _max_weight_state(states: Iterable[value.ProductState]) -> value.ProductState | None:
    qubit_state_map: dict[ops.Qid, _NamedOneQubitState] = {}
    for state in states:
        for qubit, named_state in state:
            if qubit in qubit_state_map:
                if qubit_state_map[qubit] != named_state:
                    return None
            else:
                qubit_state_map[qubit] = named_state
    return value.ProductState(qubit_state_map)
def zeros_state(qubits: Iterable[cirq.Qid]):
    return value.ProductState({q: value.KET_ZERO for q in qubits})
def observables_to_settings(
    observables: Iterable[cirq.PauliString], qubits: Iterable[cirq.Qid]
) -> Iterable[InitObsSetting]:
    for observable in observables:
        yield InitObsSetting(init_state=zeros_state(qubits), observable=observable)
def _fix_precision(val: value.Scalar | sympy.Expr, precision) -> int | tuple[int, int]:
    if isinstance(val, sympy.Expr):
        raise ValueError(f'Cannot convert {val} to fixed precision in observable settings')
    if isinstance(val, (complex, numbers.Complex)):
        return int(val.real * precision), int(val.imag * precision)
    return int(val * precision)  # pragma: no cover
def _hashable_param(
    param_tuples: Iterable[tuple[str | sympy.Expr, value.Scalar | sympy.Expr]], precision=1e7
) -> frozenset[tuple[str, int | tuple[int, int]]]:
    return frozenset(
        (k, _fix_precision(v, precision)) for k, v in param_tuples if isinstance(k, str)
    )
@dataclasses.dataclass(frozen=True)
class _MeasurementSpec:
    max_setting: InitObsSetting
    circuit_params: Mapping[str | sympy.Expr, value.Scalar | sympy.Expr]
    def __hash__(self):
        return hash((self.max_setting, _hashable_param(self.circuit_params.items())))
    def __repr__(self):
        return (
            f'cirq.work._MeasurementSpec(max_setting={self.max_setting!r}, '
            f'circuit_params={self.circuit_params!r})'
        )
    def _json_dict_(self):
        return protocols.dataclass_json_dict(self)

