from __future__ import annotations
import itertools
from collections.abc import Sequence
from typing import TYPE_CHECKING
import numpy as np
from cirq import ops
from cirq.linalg import is_special_unitary, is_unitary, map_eigenvalues
from cirq.protocols import unitary
if TYPE_CHECKING:
    import cirq
def _unitary_power(matrix: np.ndarray, power: float) -> np.ndarray:
    return map_eigenvalues(matrix, lambda e: e**power)
def _is_identity(matrix):
    return np.allclose(matrix, np.eye(matrix.shape[0]))
def _flatten(x):
    return list(itertools.chain.from_iterable(x))
def _decompose_abc(matrix: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray, float]:
    assert matrix.shape == (2, 2)
    with np.errstate(divide="ignore", invalid="ignore"):
        delta = np.angle(np.linalg.det(matrix)) * 0.5
    alpha = np.angle(matrix[0, 0]) + np.angle(matrix[0, 1]) - 2 * delta
    beta = np.angle(matrix[0, 0]) - np.angle(matrix[0, 1])
    m00_abs = np.abs(matrix[0, 0])
    if np.abs(m00_abs - 1.0) < 1e-9:
        m00_abs = 1
    theta = 2 * np.arccos(m00_abs)
    a = unitary(ops.rz(-alpha)) @ unitary(ops.ry(-theta / 2))
    b = unitary(ops.ry(theta / 2)) @ unitary(ops.rz((alpha + beta) / 2))
    c = unitary(ops.rz((alpha - beta) / 2))
    x = unitary(ops.X)
    assert np.allclose(a @ b @ c, np.eye(2), atol=1e-2)
    assert np.allclose((a @ x @ b @ x @ c) * np.exp(1j * delta), matrix, atol=1e-2)
    return a, b, c, delta
def _decompose_single_ctrl(
    matrix: np.ndarray, control: cirq.Qid, target: cirq.Qid
) -> list[cirq.Operation]:
    a, b, c, delta = _decompose_abc(matrix)
    result = [
        ops.ZPowGate(exponent=delta / np.pi).on(control),
        ops.MatrixGate(c).on(target),
        ops.CNOT.on(control, target),
        ops.MatrixGate(b).on(target),
        ops.CNOT.on(control, target),
        ops.MatrixGate(a).on(target),
    ]
    result = [g for g in result if not _is_identity(unitary(g))]
    return result
def _ccnot_congruent(c0: cirq.Qid, c1: cirq.Qid, target: cirq.Qid) -> list[cirq.Operation]:
    return [
        ops.ry(-np.pi / 4).on(target),
        ops.CNOT(c1, target),
        ops.ry(-np.pi / 4).on(target),
        ops.CNOT(c0, target),
        ops.ry(np.pi / 4).on(target),
        ops.CNOT(c1, target),
        ops.ry(np.pi / 4).on(target),
    ]
def decompose_multi_controlled_x(
    controls: Sequence[cirq.Qid], target: cirq.Qid, free_qubits: Sequence[cirq.Qid]
) -> list[cirq.Operation]:
    m = len(controls)
    if m == 0:
        return [ops.X.on(target)]
    elif m == 1:
        return [ops.CNOT.on(controls[0], target)]
    elif m == 2:
        return [ops.CCNOT.on(controls[0], controls[1], target)]
    m = len(controls)
    n = m + 1 + len(free_qubits)
    if (n >= 2 * m - 1) and (m >= 3):
        gates1 = [
            _ccnot_congruent(controls[m - 2 - i], free_qubits[m - 4 - i], free_qubits[m - 3 - i])
            for i in range(m - 3)
        ]
        gates2 = _ccnot_congruent(controls[0], controls[1], free_qubits[0])
        gates3 = _flatten(gates1) + gates2 + _flatten(gates1[::-1])
        first_ccnot = ops.CCNOT(controls[m - 1], free_qubits[m - 3], target)
        return [first_ccnot, *gates3, first_ccnot, *gates3]
    elif len(free_qubits) >= 1:
        m1 = n // 2
        free1 = [*controls[m1:], target, *free_qubits[1:]]
        ctrl1 = controls[:m1]
        part1 = decompose_multi_controlled_x(ctrl1, free_qubits[0], free1)
        free2 = [*controls[:m1], *free_qubits[1:]]
        ctrl2 = [*controls[m1:], free_qubits[0]]
        part2 = decompose_multi_controlled_x(ctrl2, target, free2)
        return [*part1, *part2, *part1, *part2]
    else:
        return decompose_multi_controlled_rotation(unitary(ops.X), controls, target)
def _decompose_su(
    matrix: np.ndarray, controls: Sequence[cirq.Qid], target: cirq.Qid
) -> list[cirq.Operation]:
    assert matrix.shape == (2, 2)
    assert is_special_unitary(matrix)
    assert len(controls) >= 1
    a, b, c, _ = _decompose_abc(matrix)
    cnots = decompose_multi_controlled_x(controls[:-1], target, [controls[-1]])
    return [
        *_decompose_single_ctrl(c, controls[-1], target),
        *cnots,
        *_decompose_single_ctrl(b, controls[-1], target),
        *cnots,
        *_decompose_single_ctrl(a, controls[-1], target),
    ]
def _decompose_recursive(
    matrix: np.ndarray,
    power: float,
    controls: Sequence[cirq.Qid],
    target: cirq.Qid,
    free_qubits: Sequence[cirq.Qid],
) -> list[cirq.Operation]:
    if len(controls) == 1:
        return _decompose_single_ctrl(_unitary_power(matrix, power), controls[0], target)
    cnots = decompose_multi_controlled_x(controls[:-1], controls[-1], [*free_qubits, target])
    return [
        *_decompose_single_ctrl(_unitary_power(matrix, 0.5 * power), controls[-1], target),
        *cnots,
        *_decompose_single_ctrl(_unitary_power(matrix, -0.5 * power), controls[-1], target),
        *cnots,
        *_decompose_recursive(
            matrix, 0.5 * power, controls[:-1], target, [controls[-1], *free_qubits]
        ),
    ]
def decompose_multi_controlled_rotation(
    matrix: np.ndarray, controls: Sequence[cirq.Qid], target: cirq.Qid
) -> list[cirq.Operation]:
    assert is_unitary(matrix)
    assert matrix.shape == (2, 2)
    if len(controls) == 0:
        return [ops.MatrixGate(matrix).on(target)]
    elif len(controls) == 1:
        return _decompose_single_ctrl(matrix, controls[0], target)
    elif is_special_unitary(matrix):
        return _decompose_su(matrix, controls, target)
    else:
        return _decompose_recursive(matrix, 1.0, controls, target, [])

from __future__ import annotations
import numpy as np
import scipy.stats
import cirq
def test_decompose_x() -> None:
    for total_qubits_count in range(1, 8):
        qubits = cirq.LineQubit.range(total_qubits_count)
        for controls_count in range(total_qubits_count):
            gates = cirq.decompose_multi_controlled_x(
                qubits[:controls_count], qubits[controls_count], qubits[controls_count + 1 :]
            )
            circuit1 = cirq.Circuit([cirq.I.on(q) for q in qubits])
            circuit1.append(gates)
            result_matrix = circuit1.unitary()
            circuit2 = cirq.Circuit([cirq.I.on(q) for q in qubits])
            circuit2 += cirq.ControlledGate(cirq.X, num_controls=controls_count).on(
                *qubits[0 : controls_count + 1]
            )
            expected_matrix = circuit2.unitary()
            assert np.allclose(expected_matrix, result_matrix)
def _random_unitary():
    return scipy.stats.unitary_group.rvs(2)
def _random_special_unitary():
    U = _random_unitary()
    return U / np.sqrt(np.linalg.det(U))
def _count_operations(operations):
    count_2x2 = 0
    count_cnot = 0
    count_ccnot = 0
    for operation in operations:
        u = cirq.unitary(operation)
        if u.shape == (2, 2):
            count_2x2 += 1
        elif u.shape == (4, 4):
            assert np.allclose(u, cirq.unitary(cirq.CNOT))
            count_cnot += 1
        elif u.shape == (8, 8):
            assert np.allclose(u, cirq.unitary(cirq.CCNOT))
            count_ccnot += 1
    return count_2x2, count_cnot, count_ccnot
def _test_decompose(matrix, controls_count):
    qubits = cirq.LineQubit.range(controls_count + 1)
    operations = cirq.decompose_multi_controlled_rotation(matrix, qubits[:-1], qubits[-1])
    _count_operations(operations)
    result_matrix = cirq.Circuit(operations).unitary()
    expected_matrix = cirq.Circuit(
        [cirq.MatrixGate(matrix).on(qubits[-1]).controlled_by(*qubits[:-1])]
    ).unitary()
    cirq.testing.assert_allclose_up_to_global_phase(expected_matrix, result_matrix, atol=1e-8)
def test_decompose_specific_matrices() -> None:
    for gate in [cirq.X, cirq.Y, cirq.Z, cirq.H, cirq.I, cirq.T, cirq.S]:
        for controls_count in range(7):
            _test_decompose(cirq.unitary(gate), controls_count)
@cirq.testing.retry_once_with_later_random_values
def test_decompose_random_unitary() -> None:
    for controls_count in range(5):
        for _ in range(10):
            _test_decompose(_random_unitary(), controls_count)
    for controls_count in range(5, 8):
        _test_decompose(_random_unitary(), controls_count)
@cirq.testing.retry_once_with_later_random_values
def test_decompose_random_special_unitary() -> None:
    for controls_count in range(5):
        for _ in range(10):
            _test_decompose(_random_special_unitary(), controls_count)
    for controls_count in range(5, 8):
        _test_decompose(_random_special_unitary(), controls_count)
def _decomposition_size(U, controls_count):
    qubits = cirq.LineQubit.range(controls_count + 1)
    operations = cirq.decompose_multi_controlled_rotation(U, qubits[:controls_count], qubits[-1])
    return _count_operations(operations)
def test_decompose_size_special_unitary() -> None:
    np.random.seed(0)
    u = _random_special_unitary()
    assert _decomposition_size(u, 0) == (1, 0, 0)
    assert _decomposition_size(u, 1) == (3, 2, 0)
    assert _decomposition_size(u, 2) == (8, 8, 0)
    assert _decomposition_size(u, 3) == (8, 6, 2)
    assert _decomposition_size(u, 4) == (24, 18, 4)
    assert _decomposition_size(u, 5) == (40, 30, 12)
    for i in range(6, 20):
        assert _decomposition_size(u, i) == (64 * i - 312, 48 * i - 234, 16)
def test_decompose_size_unitary() -> None:
    np.random.seed(0)
    u = _random_unitary()
    assert _decomposition_size(u, 0) == (1, 0, 0)
    assert _decomposition_size(u, 1) == (4, 2, 0)
    assert _decomposition_size(u, 2) == (12, 8, 0)
    assert _decomposition_size(u, 3) == (20, 12, 2)
    assert _decomposition_size(u, 4) == (44, 28, 6)
    assert _decomposition_size(u, 5) == (84, 56, 18)
    assert _decomposition_size(u, 6) == (172, 120, 26)
    assert _decomposition_size(u, 7) == (340, 244, 38)
    assert _decomposition_size(u, 8) == (524, 380, 46)
    assert _decomposition_size(u, 9) == (820, 600, 58)

from __future__ import annotations
from typing import cast
import numpy as np
import numpy.typing as npt
from cirq import protocols
from cirq.ops import DensePauliString
def _argmax(V: npt.NDArray) -> tuple[int, float]:
    V = (V * V.conj()).real
    idx_max = np.argmax(V)
    V[idx_max] = 0
    return cast(int, idx_max), np.max(V)
def _validate_decomposition(decomposition: DensePauliString, U: npt.NDArray, eps: float) -> bool:
    got = protocols.unitary(decomposition)
    return np.abs(got - U).max() < eps
def _fast_walsh_hadamard_transform(V: npt.NDArray) -> None:
    m = len(V)
    n = m.bit_length() - 1
    for h in [2**i for i in range(n)]:
        for i in range(0, m, h * 2):
            for j in range(i, i + h):
                x = V[j]
                y = V[j + h]
                V[j] = x + y
                V[j + h] = x - y
def _conjugate_with_hadamard(U: npt.NDArray) -> npt.NDArray:
    U = np.copy(U.T)
    for i in range(U.shape[1]):
        _fast_walsh_hadamard_transform(U[:, i])
    U = U.T
    for i in range(U.shape[1]):
        _fast_walsh_hadamard_transform(U[:, i])
    return U
def unitary_to_pauli_string(U: npt.NDArray, eps: float = 1e-15) -> DensePauliString | None:
    if len(U.shape) != 2 or U.shape[0] != U.shape[1]:
        raise ValueError(f'Input has a non-square shape {U}')
    n = U.shape[0].bit_length() - 1
    if U.shape[0] != 2**n:
        raise ValueError(f'Input dimension {U.shape[0]} isn\'t a power of 2')
    x_msk, second_largest = _argmax(U[:, 0])
    if second_largest > eps:
        return None
    U_z = _conjugate_with_hadamard(U)
    z_msk, second_largest = _argmax(U_z[:, 0])
    if second_largest > eps:
        return None
    def select(i):
        has_x = (x_msk >> i) & 1
        has_z = (z_msk >> i) & 1
        gate_table = ['IX', 'ZY']
        return gate_table[has_z][has_x]
    decomposition = DensePauliString(''.join(select(i) for i in reversed(range(n))))
    guess = protocols.unitary(decomposition)
    if np.abs(guess[x_msk, 0]) < eps:
        return None
    phase = U[x_msk, 0] / guess[x_msk, 0]
    phase /= np.abs(phase)  # Make sure |phase| = 1 to avoid rounding issues.
    decomposition = DensePauliString(
        ''.join(select(i) for i in reversed(range(n))), coefficient=phase
    )
    if not _validate_decomposition(decomposition, U, eps):
        return None
    return decomposition

from __future__ import annotations
from collections.abc import Callable, Iterable, Sequence
from typing import cast, TYPE_CHECKING
import numpy as np
from attr import define
from scipy.linalg import cossin
from cirq import ops
from cirq.circuits.frozen_circuit import FrozenCircuit
from cirq.linalg import decompositions, predicates
from cirq.protocols import unitary_protocol
from cirq.transformers.analytical_decompositions.two_qubit_to_cz import (
    two_qubit_matrix_to_cz_operations,
    two_qubit_matrix_to_diagonal_and_cz_operations,
)
if TYPE_CHECKING:
    import cirq
@define
class _TwoQubitGate:
    location: int
    matrix: np.ndarray
def quantum_shannon_decomposition(
    qubits: Sequence[cirq.Qid], u: np.ndarray, atol: float = 1e-8
) -> Iterable[cirq.Operation]:
    if not predicates.is_unitary(u, atol=atol):  # Check that u is unitary
        raise ValueError(
            "Expected input matrix u to be unitary, \
                but it fails cirq.is_unitary check"
        )
    n = u.shape[0]
    if n & (n - 1):
        raise ValueError(
            f"Expected input matrix u to be a (2^n x 2^n) shaped numpy array, \
                but instead got shape {u.shape}"
        )
    if n == 2:
        yield from _single_qubit_decomposition(qubits[0], u)
        return
    shannon_decomp: list[cirq.Operation | list[cirq.Operation]] = [
        *_recursive_decomposition(qubits, u)
    ]
    two_qubit_gates = [
        _TwoQubitGate(location=loc, matrix=unitary_protocol.unitary(o))
        for loc, o in enumerate(cast(list[ops.Operation], shannon_decomp))
        if isinstance(o.gate, ops.MatrixGate)
    ]
    q0 = qubits[-2]
    q1 = qubits[-1]
    for idx in range(len(two_qubit_gates) - 1, 0, -1):
        diagonal, operations = two_qubit_matrix_to_diagonal_and_cz_operations(
            q0,
            q1,
            two_qubit_gates[idx].matrix,
            allow_partial_czs=True,
            clean_operations=True,
            atol=atol,
        )
        global_phase = _global_phase_difference(
            two_qubit_gates[idx].matrix, [ops.MatrixGate(diagonal)(q0, q1), *operations]
        )
        if not np.isclose(global_phase, 0, atol=atol):
            operations.append(ops.global_phase_operation(np.exp(1j * global_phase)))
        shannon_decomp[two_qubit_gates[idx].location] = operations
        two_qubit_gates[idx - 1].matrix = diagonal @ two_qubit_gates[idx - 1].matrix
    if len(two_qubit_gates) > 0:
        operations = two_qubit_matrix_to_cz_operations(
            q0,
            q1,
            two_qubit_gates[0].matrix,
            allow_partial_czs=True,
            clean_operations=True,
            atol=atol,
        )
        global_phase = _global_phase_difference(two_qubit_gates[0].matrix, operations)
        if not np.isclose(global_phase, 0, atol=atol):
            operations.append(ops.global_phase_operation(np.exp(1j * global_phase)))
        shannon_decomp[two_qubit_gates[0].location] = operations
    yield from cast(Iterable[ops.Operation], ops.flatten_op_tree(shannon_decomp))
def _recursive_decomposition(qubits: Sequence[cirq.Qid], u: np.ndarray) -> Iterable[cirq.Operation]:
    n = u.shape[0]
    if n & (n - 1):
        raise ValueError(
            f"Expected input matrix u to be a (2^n x 2^n) shaped numpy array, \
                but instead got shape {u.shape}"
        )
    if n <= 2:
        raise ValueError(
            f"Expected input matrix u for recursive step to have size at least 4, \
                but it has size {n}"
        )
    if n == 4:
        yield ops.MatrixGate(u).on(*qubits)
        return
    (u1, u2), theta, (v1, v2) = cossin(u, n / 2, n / 2, separate=True)
    yield from _msb_demuxer(qubits, v1, v2)
    yield from _multiplexed_cossin(qubits, theta, ops.ry)
    cz_diag = np.concatenate((np.ones(n >> 2), np.full(n >> 2, -1)))
    u2 = u2 @ np.diag(cz_diag)
    yield from _msb_demuxer(qubits, u1, u2)
def _global_phase_difference(u: np.ndarray, ops: list[cirq.Operation]) -> float:
    i, j = np.unravel_index(np.argmax(np.abs(u)), u.shape)
    new_unitary = unitary_protocol.unitary(FrozenCircuit.from_moments(*ops))
    return np.angle(u[i, j]) - np.angle(new_unitary[i, j])
def _single_qubit_decomposition(qubit: cirq.Qid, u: np.ndarray) -> Iterable[cirq.Operation]:
    phi_0, phi_1, phi_2 = np.array(
        decompositions.deconstruct_single_qubit_matrix_into_angles(u)
    ) % (2 * np.pi)
    global_phase = np.angle(u[0, 0]) + phi_0 / 2 + phi_2 / 2
    if np.abs(u[0, 0]) < 1e-9:
        global_phase = np.angle(u[1, 0]) + phi_0 / 2 - phi_2 / 2
    if np.abs(phi_2) > 1e-18:
        yield ops.rz(phi_0).on(qubit)
        yield ops.ry(phi_1).on(qubit)
        yield ops.ZPowGate(exponent=phi_2 / np.pi, global_shift=global_phase / phi_2 - 0.5)(qubit)
    elif np.abs(phi_1) > 1e-18:
        if np.abs(phi_0) > 1e-18:
            yield ops.rz(phi_0)(qubit)
        yield ops.YPowGate(exponent=phi_1 / np.pi, global_shift=global_phase / phi_1 - 0.5)(qubit)
    elif np.abs(phi_0) > 1e-18:
        yield ops.ZPowGate(exponent=phi_0 / np.pi, global_shift=global_phase / phi_0 - 0.5)(qubit)
    elif np.abs(global_phase) > 1e-18:
        yield ops.global_phase_operation(np.exp(1j * global_phase))
    else:
        return
def _msb_demuxer(
    demux_qubits: Sequence[cirq.Qid], u1: np.ndarray, u2: np.ndarray
) -> Iterable[cirq.Operation]:
    u1 = u1.astype(np.complex128)
    u2 = u2.astype(np.complex128)
    u = u1 @ u2.T.conjugate()
    if predicates.is_hermitian(u):
        dsquared, V = np.linalg.eigh(u)
    else:
        dsquared, V = np.linalg.eig(u)
        for i in range(V.shape[0]):
            for j in range(i):
                if np.abs(dsquared[i] - dsquared[j]) < 1e-9:
                    V[:, i] -= np.dot(V[:, j].conj(), V[:, i]) * V[:, j]
            V[:, i] /= np.linalg.norm(V[:, i])  # normalize.
    dsquared = dsquared.astype(np.complex128)
    d = np.sqrt(dsquared)
    D = np.diag(d)
    W = D @ V.T.conjugate() @ u2
    yield from _recursive_decomposition(demux_qubits[1:], W)
    yield from _multiplexed_cossin(demux_qubits, -np.angle(d), ops.rz)
    yield from _recursive_decomposition(demux_qubits[1:], V)
def _nth_gray(n: int) -> int:
    return n ^ (n >> 1)
def _multiplexed_cossin(
    cossin_qubits: Sequence[cirq.Qid], angles: list[float], rot_func: Callable = ops.ry
) -> Iterable[cirq.Operation]:
    main_qubit = cossin_qubits[0]
    control_qubits = cossin_qubits[1:]
    for j in range(len(angles)):
        rotation = sum(
            -angle if bin(_nth_gray(j) & i).count('1') % 2 else angle
            for i, angle in enumerate(angles)
        )
        rotation = rotation * 2 / len(angles)
        select_string = _nth_gray(j) ^ _nth_gray(j + 1)
        select_qubit = next(i for i in range(len(angles)) if (select_string >> i & 1))
        select_qubit = max(-select_qubit - 1, -len(control_qubits))
        if np.abs(rotation) > 1e-9:
            yield rot_func(rotation).on(main_qubit)
        if rot_func == ops.ry:
            if j < len(angles) - 1:
                yield ops.CZ(control_qubits[select_qubit], main_qubit)
        else:
            yield ops.CNOT(control_qubits[select_qubit], main_qubit)

from __future__ import annotations
import math
import numpy as np
import sympy
from cirq import linalg, ops, protocols
from cirq.linalg.tolerance import near_zero_mod
def is_negligible_turn(turns: float, tolerance: float) -> bool:
    if isinstance(turns, sympy.Expr):
        if not turns.is_constant():
            return False
        turns = float(turns)
    return abs(_signed_mod_1(turns)) <= tolerance
def _signed_mod_1(x: float) -> float:
    return (x + 0.5) % 1 - 0.5
def single_qubit_matrix_to_pauli_rotations(
    mat: np.ndarray, atol: float = 0
) -> list[tuple[ops.Pauli, float]]:
    def is_clifford_rotation(half_turns):
        return near_zero_mod(half_turns, 0.5, atol=atol)
    def to_quarter_turns(half_turns):
        return round(2 * half_turns) % 4
    def is_quarter_turn(half_turns):
        return is_clifford_rotation(half_turns) and to_quarter_turns(half_turns) % 2 == 1
    def is_half_turn(half_turns):
        return is_clifford_rotation(half_turns) and to_quarter_turns(half_turns) == 2
    def is_no_turn(half_turns):
        return is_clifford_rotation(half_turns) and to_quarter_turns(half_turns) == 0
    z_rad_before, y_rad, z_rad_after = linalg.deconstruct_single_qubit_matrix_into_angles(mat)
    z_ht_before = z_rad_before / np.pi - 0.5
    m_ht = y_rad / np.pi
    m_pauli: ops.Pauli = ops.X
    z_ht_after = z_rad_after / np.pi + 0.5
    if is_clifford_rotation(z_ht_before):
        if (is_quarter_turn(z_ht_before) or is_quarter_turn(z_ht_after)) ^ (
            is_half_turn(m_ht) and is_no_turn(z_ht_before - z_ht_after)
        ):
            z_ht_before += 0.5
            z_ht_after -= 0.5
            m_pauli = ops.Y
        if is_half_turn(z_ht_before) or is_half_turn(z_ht_after):
            z_ht_before -= 1
            z_ht_after += 1
            m_ht = -m_ht
    if is_no_turn(m_ht):
        z_ht_before += z_ht_after
        z_ht_after = 0
    elif is_half_turn(m_ht):
        z_ht_after -= z_ht_before
        z_ht_before = 0
    rotation_list = [(ops.Z, z_ht_before), (m_pauli, m_ht), (ops.Z, z_ht_after)]
    return [(pauli, ht) for pauli, ht in rotation_list if not is_no_turn(ht)]
def single_qubit_matrix_to_gates(mat: np.ndarray, tolerance: float = 0) -> list[ops.Gate]:
    rotations = single_qubit_matrix_to_pauli_rotations(mat, tolerance)
    return [pauli**ht for pauli, ht in rotations]
def single_qubit_op_to_framed_phase_form(mat: np.ndarray) -> tuple[np.ndarray, complex, complex]:
    vals, vecs = linalg.unitary_eig(mat)
    u = np.conj(vecs).T
    r = vals[1] / vals[0]
    g = vals[0]
    return u, r, g
def _deconstruct_single_qubit_matrix_into_gate_turns(mat: np.ndarray) -> tuple[float, float, float]:
    pre_phase, rotation, post_phase = linalg.deconstruct_single_qubit_matrix_into_angles(mat)
    tau = 2 * np.pi
    xy_turn = rotation / tau
    xy_phase_turn = 0.25 - pre_phase / tau
    total_z_turn = (post_phase + pre_phase) / tau
    return (_signed_mod_1(xy_turn), _signed_mod_1(xy_phase_turn), _signed_mod_1(total_z_turn))
def single_qubit_matrix_to_phased_x_z(mat: np.ndarray, atol: float = 0) -> list[ops.Gate]:
    xy_turn, xy_phase_turn, total_z_turn = _deconstruct_single_qubit_matrix_into_gate_turns(mat)
    result = [
        ops.PhasedXPowGate(exponent=2 * xy_turn, phase_exponent=2 * xy_phase_turn),
        ops.Z ** (2 * total_z_turn),
    ]
    result = [g for g in result if protocols.trace_distance_bound(g) > atol]
    if len(result) == 2 and math.isclose(abs(xy_turn), 0.5, abs_tol=atol):
        return [ops.PhasedXPowGate(phase_exponent=2 * xy_phase_turn + total_z_turn)]
    return result
def single_qubit_matrix_to_phxz(mat: np.ndarray, atol: float = 0) -> ops.PhasedXZGate | None:
    xy_turn, xy_phase_turn, total_z_turn = _deconstruct_single_qubit_matrix_into_gate_turns(mat)
    g = ops.PhasedXZGate(
        axis_phase_exponent=2 * xy_phase_turn, x_exponent=2 * xy_turn, z_exponent=2 * total_z_turn
    )
    if protocols.trace_distance_bound(g) <= atol:
        return None
    if math.isclose(abs(xy_turn), 0.5, abs_tol=atol):
        g = ops.PhasedXZGate(
            axis_phase_exponent=2 * xy_phase_turn + total_z_turn, x_exponent=1, z_exponent=0
        )
    return g

from __future__ import annotations
from typing import TYPE_CHECKING
import numpy as np
from cirq import circuits, ops, qis
from cirq.transformers.analytical_decompositions import single_qubit_decompositions
if TYPE_CHECKING:
    import cirq
def _1q_matrices_to_ops(g0, g1, q0, q1, include_identity=False):
    ret = []
    for g, q in zip(
        map(single_qubit_decompositions.single_qubit_matrix_to_phxz, [g0, g1]), [q0, q1]
    ):
        if g is not None:
            ret.append(g.on(q))
        elif include_identity:
            ret.append(ops.I.on(q))
    return ret
def prepare_two_qubit_state_using_sqrt_iswap(
    q0: cirq.Qid, q1: cirq.Qid, state: cirq.STATE_VECTOR_LIKE, *, use_sqrt_iswap_inv: bool = True
) -> list[cirq.Operation]:
    state_vector = qis.to_valid_state_vector(state, num_qubits=2)
    state_vector = state_vector / np.linalg.norm(state_vector)
    u, s, vh = np.linalg.svd(state_vector.reshape(2, 2))
    if np.isclose(s[0], 1):
        return _1q_matrices_to_ops(u, vh.T, q0, q1, True)
    alpha = np.arccos(np.sqrt(np.clip(1 - s[0] * 2 * s[1], 0, 1)))
    sqrt_iswap_gate = ops.SQRT_ISWAP_INV if use_sqrt_iswap_inv else ops.SQRT_ISWAP
    op_list = [ops.ry(2 * alpha).on(q0), sqrt_iswap_gate.on(q0, q1)]
    intermediate_state = circuits.Circuit(op_list).final_state_vector(
        ignore_terminal_measurements=False, dtype=np.complex64
    )
    u_iSWAP, _, vh_iSWAP = np.linalg.svd(intermediate_state.reshape(2, 2))
    return op_list + _1q_matrices_to_ops(
        np.dot(u, np.linalg.inv(u_iSWAP)), np.dot(vh.T, np.linalg.inv(vh_iSWAP.T)), q0, q1
    )
def prepare_two_qubit_state_using_cz(
    q0: cirq.Qid, q1: cirq.Qid, state: cirq.STATE_VECTOR_LIKE
) -> list[cirq.Operation]:
    state_vector = qis.to_valid_state_vector(state, num_qubits=2)
    state_vector = state_vector / np.linalg.norm(state_vector)
    u, s, vh = np.linalg.svd(state_vector.reshape(2, 2))
    if np.isclose(s[0], 1):
        return _1q_matrices_to_ops(u, vh.T, q0, q1, True)
    alpha = np.arccos(np.clip(s[0], 0, 1))
    op_list = [ops.ry(2 * alpha).on(q0), ops.H.on(q1), ops.CZ.on(q0, q1)]
    intermediate_state = circuits.Circuit(op_list).final_state_vector(
        ignore_terminal_measurements=False, dtype=np.complex64
    )
    u_CZ, _, vh_CZ = np.linalg.svd(intermediate_state.reshape(2, 2))
    return op_list + _1q_matrices_to_ops(
        np.dot(u, np.linalg.inv(u_CZ)), np.dot(vh.T, np.linalg.inv(vh_CZ.T)), q0, q1
    )
def prepare_two_qubit_state_using_iswap(
    q0: cirq.Qid, q1: cirq.Qid, state: cirq.STATE_VECTOR_LIKE, use_iswap_inv: bool = False
) -> list[cirq.Operation]:
    state_vector = qis.to_valid_state_vector(state, num_qubits=2)
    state_vector = state_vector / np.linalg.norm(state_vector)
    u, s, vh = np.linalg.svd(state_vector.reshape(2, 2))
    if np.isclose(s[0], 1):
        return _1q_matrices_to_ops(u, vh.T, q0, q1, True)
    alpha = np.arccos(np.clip(s[0], 0, 1))
    op_list = [
        ops.ry(2 * alpha).on(q0),
        ops.H.on(q1),
        ops.ISWAP_INV.on(q0, q1) if use_iswap_inv else ops.ISWAP.on(q0, q1),
    ]
    intermediate_state = circuits.Circuit(op_list).final_state_vector(
        ignore_terminal_measurements=False, dtype=np.complex64
    )
    u_CZ, _, vh_CZ = np.linalg.svd(intermediate_state.reshape(2, 2))
    return op_list + _1q_matrices_to_ops(
        np.dot(u, np.linalg.inv(u_CZ)), np.dot(vh.T, np.linalg.inv(vh_CZ.T)), q0, q1
    )

from __future__ import annotations
from collections.abc import Iterable, Sequence
from typing import cast, TYPE_CHECKING
import numpy as np
from cirq import circuits, linalg, ops, protocols
from cirq.linalg import predicates
from cirq.linalg.decompositions import extract_right_diag, num_cnots_required
from cirq.transformers.analytical_decompositions import single_qubit_decompositions
from cirq.transformers.eject_phased_paulis import eject_phased_paulis
from cirq.transformers.eject_z import eject_z
if TYPE_CHECKING:
    import cirq
def _remove_partial_czs_or_fail(
    operations: Iterable[cirq.Operation], atol: float
) -> list[cirq.Operation]:
    result = []
    for op in operations:
        if isinstance(op.gate, ops.CZPowGate):
            t = op.gate.exponent % 2  # CZ^t is periodic with period 2.
            if t < atol:
                continue  # Identity.
            elif abs(t - 1) < atol:
                result.append(ops.CZ(*op.qubits))  # Was either CZ or CZ**-1.
            else:
                raise ValueError(f'CZ^t is not allowed for t={t}')
        else:
            result.append(op)
    return result
def two_qubit_matrix_to_cz_operations(
    q0: cirq.Qid,
    q1: cirq.Qid,
    mat: np.ndarray,
    allow_partial_czs: bool,
    atol: float = 1e-8,
    clean_operations: bool = True,
) -> list[ops.Operation]:
    kak = linalg.kak_decomposition(mat, atol=atol)
    operations = _kak_decomposition_to_operations(q0, q1, kak, allow_partial_czs, atol=atol)
    if clean_operations:
        if not allow_partial_czs:
            return _remove_partial_czs_or_fail(cleanup_operations(operations, atol=atol), atol=atol)
        return cleanup_operations(operations, atol=atol)
    return operations
def two_qubit_matrix_to_diagonal_and_cz_operations(
    q0: cirq.Qid,
    q1: cirq.Qid,
    mat: np.ndarray,
    allow_partial_czs: bool = False,
    atol: float = 1e-8,
    clean_operations: bool = True,
) -> tuple[np.ndarray, list[cirq.Operation]]:
    if predicates.is_diagonal(mat, atol=atol):
        return mat, []
    if num_cnots_required(mat) == 3:
        right_diag = extract_right_diag(mat)
        two_cnot_unitary = mat @ right_diag
        return right_diag.conj().T, two_qubit_matrix_to_cz_operations(
            q0,
            q1,
            two_cnot_unitary,
            allow_partial_czs=allow_partial_czs,
            atol=atol,
            clean_operations=clean_operations,
        )
    return np.eye(4), two_qubit_matrix_to_cz_operations(
        q0,
        q1,
        mat,
        allow_partial_czs=allow_partial_czs,
        atol=atol,
        clean_operations=clean_operations,
    )
def _xx_interaction_via_full_czs(q0: cirq.Qid, q1: cirq.Qid, x: float):
    a = x * -2 / np.pi
    yield ops.H(q1)
    yield ops.CZ(q0, q1)
    yield ops.X(q0) ** a
    yield ops.CZ(q0, q1)
    yield ops.H(q1)
def _xx_yy_interaction_via_full_czs(q0: cirq.Qid, q1: cirq.Qid, x: float, y: float):
    a = x * -2 / np.pi
    b = y * -2 / np.pi
    yield ops.X(q0) ** 0.5
    yield ops.H(q1)
    yield ops.CZ(q0, q1)
    yield ops.H(q1)
    yield ops.X(q0) ** a
    yield ops.Y(q1) ** b
    yield ops.H(q1)
    yield ops.CZ(q0, q1)
    yield ops.H(q1)
    yield ops.X(q0) ** -0.5
def _xx_yy_zz_interaction_via_full_czs(q0: cirq.Qid, q1: cirq.Qid, x: float, y: float, z: float):
    a = x * -2 / np.pi + 0.5
    b = y * -2 / np.pi + 0.5
    c = z * -2 / np.pi + 0.5
    yield ops.X(q0) ** 0.5
    yield ops.H(q1)
    yield ops.CZ(q0, q1)
    yield ops.H(q1)
    yield ops.X(q0) ** a
    yield ops.Y(q1) ** b
    yield ops.H.on(q0)
    yield ops.CZ(q1, q0)
    yield ops.H(q0)
    yield ops.X(q1) ** -0.5
    yield ops.Z(q1) ** c
    yield ops.H(q1)
    yield ops.CZ(q0, q1)
    yield ops.H(q1)
def cleanup_operations(
    operations: Sequence[ops.Operation], atol: float = 1e-8
) -> list[ops.Operation]:
    operations = _merge_single_qubit_gates(operations, atol=atol)
    circuit = circuits.Circuit(operations)
    circuit = eject_phased_paulis(circuit)
    circuit = eject_z(circuit)
    circuit = circuits.Circuit(circuit.all_operations(), strategy=circuits.InsertStrategy.EARLIEST)
    return list(circuit.all_operations())
def _transform_single_qubit_operations_to_phased_x_and_z(
    operations: Sequence[ops.Operation], atol: float
) -> Sequence[ops.Operation]:
    u = np.eye(2)
    for op in operations:
        u = protocols.unitary(op) @ u
    return [
        g(op.qubits[0])
        for g in single_qubit_decompositions.single_qubit_matrix_to_phased_x_z(u, atol=atol)
    ]
def _merge_single_qubit_gates(
    operations: Sequence[ops.Operation], atol: float
) -> Sequence[ops.Operation]:
    merged_ops: list[ops.Operation] = []
    pending_ops: dict[tuple[cirq.Qid, ...], list[ops.Operation]] = dict()
    for op in operations:
        if protocols.num_qubits(op) == 2:
            for qubit_ops in pending_ops.values():
                merged_ops.extend(
                    _transform_single_qubit_operations_to_phased_x_and_z(qubit_ops, atol=atol)
                )
            pending_ops.clear()
            merged_ops.append(op)
        elif protocols.num_qubits(op) == 1:
            if op.qubits not in pending_ops:
                pending_ops[op.qubits] = []
            pending_ops[op.qubits].append(op)
        else:
            raise ValueError(f'operation is on {protocols.num_qubits(op)} qubits, expected 1 or 2')
    for qubit_ops in pending_ops.values():
        merged_ops.extend(
            _transform_single_qubit_operations_to_phased_x_and_z(qubit_ops, atol=atol)
        )
    return merged_ops
def _kak_decomposition_to_operations(
    q0: cirq.Qid,
    q1: cirq.Qid,
    kak: linalg.KakDecomposition,
    allow_partial_czs: bool,
    atol: float = 1e-8,
) -> list[ops.Operation]:
    b0, b1 = kak.single_qubit_operations_before
    pre = [_do_single_on(b0, q0, atol=atol), _do_single_on(b1, q1, atol=atol)]
    a0, a1 = kak.single_qubit_operations_after
    post = [_do_single_on(a0, q0, atol=atol), _do_single_on(a1, q1, atol=atol)]
    return list(
        cast(
            Iterable[ops.Operation],
            ops.flatten_op_tree(
                [
                    pre,
                    _non_local_part(
                        q0, q1, kak.interaction_coefficients, allow_partial_czs, atol=atol
                    ),
                    post,
                ]
            ),
        )
    )
def _is_trivial_angle(rad: float, atol: float) -> bool:
    return abs(rad) < atol or abs(abs(rad) - np.pi / 4) < atol
def _parity_interaction(
    q0: cirq.Qid, q1: cirq.Qid, rads: float, atol: float, gate: ops.Gate | None = None
):
    if abs(rads) < atol:
        return
    h = rads * -2 / np.pi
    if gate is not None:
        yield gate.on(q0), gate.on(q1)
    if _is_trivial_angle(rads, atol):
        yield ops.CZ.on(q0, q1)
    else:
        yield ops.CZ(q0, q1) ** (-2 * h)
    yield ops.Z(q0) ** h
    yield ops.Z(q1) ** h
    if gate is not None:
        g = protocols.inverse(gate)
        yield g.on(q0), g.on(q1)
def _do_single_on(u: np.ndarray, q: cirq.Qid, atol: float = 1e-8):
    for gate in single_qubit_decompositions.single_qubit_matrix_to_gates(u, atol):
        yield gate(q)
def _non_local_part(
    q0: cirq.Qid,
    q1: cirq.Qid,
    interaction_coefficients: tuple[float, float, float],
    allow_partial_czs: bool,
    atol: float = 1e-8,
):
    x, y, z = interaction_coefficients
    if allow_partial_czs or all(_is_trivial_angle(e, atol) for e in [x, y, z]):
        return [
            _parity_interaction(q0, q1, x, atol, ops.Y**-0.5),
            _parity_interaction(q0, q1, y, atol, ops.X**0.5),
            _parity_interaction(q0, q1, z, atol),
        ]
    if abs(z) >= atol:
        return _xx_yy_zz_interaction_via_full_czs(q0, q1, x, y, z)
    if y >= atol:
        return _xx_yy_interaction_via_full_czs(q0, q1, x, y)
    return _xx_interaction_via_full_czs(q0, q1, x)

from __future__ import annotations
from collections.abc import Iterable, Iterator, Sequence
from typing import TYPE_CHECKING
import numpy as np
from cirq import circuits, devices, linalg, ops, protocols
if TYPE_CHECKING:
    import cirq
def decompose_two_qubit_interaction_into_four_fsim_gates(
    interaction: cirq.SupportsUnitary | np.ndarray,
    *,
    fsim_gate: cirq.FSimGate | cirq.ISwapPowGate,
    qubits: Sequence[cirq.Qid] | None = None,
) -> cirq.Circuit:
    if protocols.is_parameterized(fsim_gate):
        raise ValueError("FSimGate must not have parameterized values for angles.")
    if isinstance(fsim_gate, ops.ISwapPowGate):
        mapped_gate = ops.FSimGate(-fsim_gate.exponent * np.pi / 2, 0)
    else:
        mapped_gate = fsim_gate
    theta, phi = mapped_gate.theta, mapped_gate.phi
    assert isinstance(theta, float) and isinstance(phi, float)
    if not 3 / 8 * np.pi <= abs(theta) <= 5 / 8 * np.pi:
        raise ValueError('Must have 3π/8 ≤ |fsim_gate.theta| ≤ 5π/8')
    if abs(phi) > np.pi / 4:
        raise ValueError('Must have abs(fsim_gate.phi) ≤ π/4')
    if qubits is None:
        if isinstance(interaction, ops.Operation):
            qubits = interaction.qubits
        else:
            qubits = devices.LineQubit.range(2)
    if len(qubits) != 2:
        raise ValueError(f'Expected a pair of qubits, but got {qubits!r}.')
    kak = linalg.kak_decomposition(interaction)
    result_using_b_gates = _decompose_two_qubit_interaction_into_two_b_gates(kak, qubits=qubits)
    b_decomposition = _decompose_b_gate_into_two_fsims(fsim_gate=mapped_gate, qubits=qubits)
    b_decomposition = [
        fsim_gate(*op.qubits) if op.gate == mapped_gate else op for op in b_decomposition
    ]
    result = circuits.Circuit()
    for op in result_using_b_gates:
        if isinstance(op.gate, _BGate):
            result.append(b_decomposition)
        else:
            result.append(op)
    return result
def _sticky_0_to_1(v: float, *, atol: float) -> float | None:
    if 0 <= v <= 1:
        return v
    if 1 < v <= 1 + atol:
        return 1
    if 0 > v >= -atol:
        return 0
    return None
def _decompose_xx_yy_into_two_fsims_ignoring_single_qubit_ops(
    *,
    qubits: Sequence[cirq.Qid],
    fsim_gate: cirq.FSimGate,
    canonical_x_kak_coefficient: float,
    canonical_y_kak_coefficient: float,
    atol: float = 1e-8,
) -> list[cirq.Operation]:
    x = canonical_x_kak_coefficient
    y = canonical_y_kak_coefficient
    assert 0 <= y <= x <= np.pi / 4
    eta = np.sin(x) ** 2 * np.cos(y) ** 2 + np.cos(x) ** 2 * np.sin(y) ** 2
    xi = abs(np.sin(2 * x) * np.sin(2 * y))
    t = fsim_gate.phi / 2
    assert isinstance(fsim_gate.theta, float)
    kappa = np.sin(fsim_gate.theta) ** 2 - np.sin(t) ** 2
    s_sum = (eta - np.sin(t) ** 2) / kappa
    s_dif = 0.5 * xi / kappa
    a_dif = _sticky_0_to_1(s_sum + s_dif, atol=atol)
    a_sum = _sticky_0_to_1(s_sum - s_dif, atol=atol)
    if a_dif is None or a_sum is None:
        raise ValueError(
            f'Failed to synthesize XX^{x/np.pi}·YY^{y/np.pi} from two '
            f'{fsim_gate!r} separated by single qubit operations.'
        )
    x_dif = np.arcsin(np.sqrt(a_dif))
    x_sum = np.arcsin(np.sqrt(a_sum))
    x_a = x_sum + x_dif
    x_b = x_dif - x_sum
    a, b = qubits
    return [
        fsim_gate(a, b),
        ops.rz(t + np.pi).on(a),
        ops.rz(t).on(b),
        ops.rx(x_a).on(a),
        ops.rx(x_b).on(b),
        fsim_gate(a, b),
    ]
class _BGate(ops.Gate):
    def num_qubits(self) -> int:
        return 2
    def _decompose_(self, qubits):
        a, b = qubits
        return [ops.XX(a, b) ** -0.5, ops.YY(a, b) ** -0.25]
_B = _BGate()
def _decompose_two_qubit_interaction_into_two_b_gates(
    interaction: cirq.SupportsUnitary | np.ndarray | cirq.KakDecomposition,
    *,
    qubits: Sequence[cirq.Qid],
) -> list[cirq.Operation]:
    kak = linalg.kak_decomposition(interaction)
    result = _decompose_interaction_into_two_b_gates_ignoring_single_qubit_ops(
        qubits, kak.interaction_coefficients
    )
    return list(
        _fix_single_qubit_gates_around_kak_interaction(
            desired=kak, qubits=qubits, operations=result
        )
    )
def _decompose_b_gate_into_two_fsims(
    *, fsim_gate: cirq.FSimGate, qubits: Sequence[cirq.Qid]
) -> list[cirq.Operation]:
    kak = linalg.kak_decomposition(_B)
    result = _decompose_xx_yy_into_two_fsims_ignoring_single_qubit_ops(
        qubits=qubits,
        fsim_gate=fsim_gate,
        canonical_x_kak_coefficient=kak.interaction_coefficients[0],
        canonical_y_kak_coefficient=kak.interaction_coefficients[1],
    )
    return list(
        _fix_single_qubit_gates_around_kak_interaction(
            desired=kak, qubits=qubits, operations=result
        )
    )
def _decompose_interaction_into_two_b_gates_ignoring_single_qubit_ops(
    qubits: Sequence[cirq.Qid], kak_interaction_coefficients: Iterable[float]
) -> list[cirq.Operation]:
    a, b = qubits
    x, y, z = kak_interaction_coefficients
    r = (np.sin(y) * np.cos(z)) ** 2
    r = max(0.0, r)  # Clamp out-of-range floating point error.
    if r > 0.499999999999:
        rb = [ops.ry(np.pi).on(b)]
    else:
        b1 = np.cos(y * 2) * np.cos(z * 2) / (1 - 2 * r)
        b1 = max(0.0, min(1, b1))  # Clamp out-of-range floating point error.
        b2 = np.arcsin(np.sqrt(b1))
        b3 = np.arccos(1 - 4 * r)
        rb = [ops.rz(-b2).on(b), ops.ry(-b3).on(b), ops.rz(-b2).on(b)]
    s = 1 if z < 0 else -1
    return [_B(a, b), ops.ry(s * 2 * x).on(a), *rb, _B(a, b)]
def _fix_single_qubit_gates_around_kak_interaction(
    *, desired: cirq.KakDecomposition, operations: list[cirq.Operation], qubits: Sequence[cirq.Qid]
) -> Iterator[cirq.Operation]:
    actual = linalg.kak_decomposition(circuits.Circuit(operations).unitary(qubit_order=qubits))
    def dag(a: np.ndarray) -> np.ndarray:
        return np.transpose(np.conjugate(a))
    for k in range(2):
        g = ops.MatrixGate(
            dag(actual.single_qubit_operations_before[k])
            @ desired.single_qubit_operations_before[k]
        )
        yield g(qubits[k])
    yield from operations
    for k in range(2):
        g = ops.MatrixGate(
            desired.single_qubit_operations_after[k] @ dag(actual.single_qubit_operations_after[k])
        )
        yield g(qubits[k])
    yield ops.global_phase_operation(desired.global_phase / actual.global_phase)

