@frozen
class TwoQubitGateSymbolizer:
    symbolizer_fn: Callable[[ops.Gate, Sequence[sympy.Symbol]], tuple[ops.Gate, dict[str, Real]]]
    n_symbols: int
    def __call__(
        self, two_qubit_gate: ops.Gate, symbols: Sequence[sympy.Symbol]
    ) -> tuple[ops.Gate, dict[str, Real]]:
        if len(symbols) != self.n_symbols:
            raise ValueError(
                f"Expect {self.n_symbols} symbols, but got {len(symbols)} symbols in {symbols}"
            )
        return self.symbolizer_fn(two_qubit_gate, symbols)
def _select(choices: Sequence[Gauge], probabilites: np.ndarray, prng: np.random.Generator) -> Gauge:
    return choices[prng.choice(len(choices), p=probabilites)]
@dataclass(frozen=True)
class GaugeSelector:
    gauges: Sequence[Gauge]
    @functools.cached_property
    def _weights(self) -> np.ndarray:
        weights = np.array([g.weight() for g in self.gauges])
        return weights / np.sum(weights)
    def __call__(self, prng: np.random.Generator) -> Gauge:
        return _select(self.gauges, self._weights, prng)
@transformer_api.transformer
class GaugeTransformer:
    def __init__(
        self,
        target: ops.Gate | ops.Gateset | ops.GateFamily,
        gauge_selector: Callable[[np.random.Generator], Gauge],
        two_qubit_gate_symbolizer: TwoQubitGateSymbolizer | None = None,
    ) -> None:
        self.target = ops.GateFamily(target) if isinstance(target, ops.Gate) else target
        self.gauge_selector = gauge_selector
        self.two_qubit_gate_symbolizer = two_qubit_gate_symbolizer
    def __call__(
        self,
        circuit: circuits.AbstractCircuit,
        *,
        context: transformer_api.TransformerContext | None = None,
        prng: np.random.Generator | None = None,
    ) -> circuits.AbstractCircuit:
        rng = np.random.default_rng() if prng is None else prng
        if context is None:
            context = transformer_api.TransformerContext(deep=False)
        if context.deep:
            raise ValueError('GaugeTransformer cannot be used with deep=True')
        new_moments = []
        left: list[list[ops.Operation]] = []
        right: list[list[ops.Operation]] = []
        for moment in circuit:
            left.clear()
            right.clear()
            center: list[ops.Operation] = []
            for op in moment:
                if isinstance(op, ops.TaggedOperation) and set(op.tags).intersection(
                    context.tags_to_ignore
                ):
                    center.append(op)
                    continue
                if op.gate is not None and len(op.qubits) == 2 and op in self.target:
                    gauge = self.gauge_selector(rng).sample(op.gate, rng)
                    q0, q1 = op.qubits
                    left.extend([g(q) for g in gs] for q, gs in zip(op.qubits, gauge.pre))
                    center.append(gauge.on(q0, q1))
                    right.extend([g(q) for g in gs] for q, gs in zip(op.qubits, gauge.post))
                else:
                    center.append(op)
            if left:
                new_moments.extend(_build_moments(left))
            new_moments.append(center)
            if right:
                new_moments.extend(_build_moments(right))
        return circuits.Circuit.from_moments(*new_moments)
    def as_sweep(
        self,
        circuit: circuits.AbstractCircuit,
        *,
        N: int,
        context: transformer_api.TransformerContext | None = None,
        prng: np.random.Generator | None = None,
    ) -> tuple[circuits.AbstractCircuit, cirq.Sweep]:
        rng = np.random.default_rng() if prng is None else prng
        if context is None:
            context = transformer_api.TransformerContext(deep=False)
        if context.deep:
            raise ValueError('GaugeTransformer cannot be used with deep=True')
        new_moments: list[list[ops.Operation]] = []  # Store parameterized circuits.
        phxz_sid = itertools.count()
        two_qubit_gate_sid = itertools.count()
        phxz_symbols_by_locs: dict[tuple[str, ops.Qid, int], dict[str, sympy.Symbol]] = {}
        two_qubit_gate_symbols_by_locs: dict[tuple[ops.Qid, ops.Qid, int], list[sympy.Symbol]] = {}
        def single_qubit_next_symbol() -> dict[str, sympy.Symbol]:
            sid = next(phxz_sid)
            return _parameterize_to_phxz(sid)
        def two_qubit_gate_next_symbol_list(n: int) -> list[sympy.Symbol]:
            sid = next(two_qubit_gate_sid)
            symbols: list[sympy.Symbol] = [sympy.Symbol(f"s{sid}_{sub}") for sub in range(n)]
            return symbols
        for moment_id, moment in enumerate(circuit):
            center_moment: list[ops.Operation] = []
            left_moment: list[ops.Operation] = []
            right_moment: list[ops.Operation] = []
            for op in moment:
                if isinstance(op, ops.TaggedOperation) and set(op.tags).intersection(
                    context.tags_to_ignore
                ):
                    center_moment.append(op)
                    continue
                if op.gate is not None and op in self.target:
                    random_gauge = self.gauge_selector(rng).sample(op.gate, rng)
                    if self.two_qubit_gate_symbolizer is not None:
                        symbols: list[sympy.Symbol] = two_qubit_gate_next_symbol_list(
                            self.two_qubit_gate_symbolizer.n_symbols
                        )
                        two_qubit_gate_symbols_by_locs[(op.qubits[0], op.qubits[1], moment_id)] = (
                            symbols
                        )
                        parameterized_2_qubit_gate, _ = self.two_qubit_gate_symbolizer(
                            random_gauge.two_qubit_gate, symbols
                        )
                        center_moment.append(parameterized_2_qubit_gate.on(*op.qubits))
                    else:
                        center_moment.append(op)
                    for prefix, q in itertools.product(["pre", "post"], op.qubits):
                        xza_by_symbols = single_qubit_next_symbol()  # xza in phased xz gate.
                        phxz_symbols_by_locs[(prefix, q, moment_id)] = xza_by_symbols
                        new_op = ops.PhasedXZGate(**xza_by_symbols).on(q)
                        if prefix == "pre":
                            left_moment.append(new_op)
                        else:
                            right_moment.append(new_op)
                else:
                    center_moment.append(op)
            new_moments.extend(
                [moment for moment in [left_moment, center_moment, right_moment] if moment]
            )
        values_by_params: dict[str, list[float]] = {
            **{
                str(symbol): []
                for symbols_by_names in phxz_symbols_by_locs.values()
                for symbol in symbols_by_names.values()
            },
            **{
                str(symbol): []
                for symbols in two_qubit_gate_symbols_by_locs.values()
                for symbol in symbols
            },
        }
        for _ in range(N):
            for moment_id, moment in enumerate(circuit):
                for op in moment:
                    if isinstance(op, ops.TaggedOperation) and set(op.tags).intersection(
                        context.tags_to_ignore
                    ):
                        continue
                    if op.gate is not None and len(op.qubits) == 2 and op in self.target:
                        gauge = self.gauge_selector(rng).sample(op.gate, rng)
                        if self.two_qubit_gate_symbolizer is not None:
                            _, vals_by_symbols = self.two_qubit_gate_symbolizer(
                                gauge.two_qubit_gate,
                                [
                                    *two_qubit_gate_symbols_by_locs[
                                        (op.qubits[0], op.qubits[1], moment_id)
                                    ]
                                ],
                            )
                            for symbol_str, val in vals_by_symbols.items():
                                values_by_params[symbol_str].append(float(val))
                        for pre_or_post, idx in itertools.product(["pre", "post"], [0, 1]):
                            gates = getattr(gauge, f"{pre_or_post}_q{idx}")
                            phxz_params = _gate_sequence_to_phxz_params(
                                gates,
                                phxz_symbols_by_locs[(pre_or_post, op.qubits[idx], moment_id)],
                            )
                            for key, value in phxz_params.items():
                                values_by_params[key].append(float(value))
        sweeps: list[Points] = [
            Points(key=key, points=values) for key, values in values_by_params.items()
        ]
        return circuits.Circuit.from_moments(*new_moments), Zip(*sweeps)
def _build_moments(operation_by_qubits: list[list[ops.Operation]]) -> list[list[ops.Operation]]:
    moments = []
    for moment in itertools.zip_longest(*operation_by_qubits):
        moments.append([op for op in moment if op is not None])
    return moments
def _parameterize_to_phxz(symbol_id: int) -> dict[str, sympy.Symbol]:
    phased_xz_params = {
        "x_exponent": sympy.Symbol(f"x{symbol_id}"),
        "z_exponent": sympy.Symbol(f"z{symbol_id}"),
        "axis_phase_exponent": sympy.Symbol(f"a{symbol_id}"),
    }
    return phased_xz_params
def _gate_sequence_to_phxz_params(
    gates: tuple[ops.Gate, ...], xza_by_symbols: dict[str, sympy.Symbol]
) -> dict[str, float]:
    identity_gate_in_phxz = {
        str(xza_by_symbols["x_exponent"]): 0.0,
        str(xza_by_symbols["z_exponent"]): 0.0,
        str(xza_by_symbols["axis_phase_exponent"]): 0.0,
    }
    if not gates:
        return identity_gate_in_phxz
    for gate in gates:
        if not has_unitary(gate) or gate.num_qubits() != 1:
            raise ValueError(
                "Invalid gate sequence to be converted to PhasedXZGate."
                f"Found incompatiable gate {gate} in sequence."
            )
    phxz = (
        single_qubit_decompositions.single_qubit_matrix_to_phxz(
            functools.reduce(
                np.matmul, [unitary_protocol.unitary(gate) for gate in reversed(gates)]
            )
        )
        or ops.I
    )
    if phxz is ops.I:  # Identity gate
        return identity_gate_in_phxz
    if not isinstance(phxz, ops.PhasedXZGate):
        raise ValueError("Failed to convert the gate sequence to a PhasedXZ gate.")
    if phxz is not None:
        return {
            str(xza_by_symbols["x_exponent"]): phxz.x_exponent,
            str(xza_by_symbols["z_exponent"]): phxz.z_exponent,
            str(xza_by_symbols["axis_phase_exponent"]): phxz.axis_phase_exponent,
        }

from __future__ import annotations
from unittest.mock import patch
import numpy as np
import pytest
import cirq
from cirq.transformers.gauge_compiling import GaugeSelector, GaugeTransformer
class GaugeTester:
    two_qubit_gate: cirq.Gate
    gauge_transformer: GaugeTransformer
    must_fail: bool = False
    @pytest.mark.parametrize(
        ['generation_seed', 'transformation_seed'],
        np.random.RandomState(0).randint(2**31, size=(5, 2)).tolist(),
    )
    def test_gauge_transformer(self, generation_seed, transformation_seed) -> None:
        c = cirq.Circuit()
        while not any(op.gate == self.two_qubit_gate for op in c.all_operations()):
            c = cirq.testing.random_circuit(
                qubits=3,
                n_moments=3,
                op_density=1,
                gate_domain={self.two_qubit_gate: 2, cirq.X: 1, cirq.Y: 1, cirq.H: 1, cirq.Z: 1},
                random_state=generation_seed,
            )
            generation_seed += 1
        nc = self.gauge_transformer(c, prng=np.random.default_rng(transformation_seed))
        if self.must_fail:
            with pytest.raises(AssertionError):
                cirq.testing.assert_circuits_have_same_unitary_given_final_permutation(
                    nc, c, qubit_map={q: q for q in c.all_qubits()}
                )
        else:
            cirq.testing.assert_circuits_have_same_unitary_given_final_permutation(
                nc, c, qubit_map={q: q for q in c.all_qubits()}
            )
    @patch('cirq.transformers.gauge_compiling.gauge_compiling._select', autospec=True)
    @pytest.mark.parametrize('seed', range(5))
    def test_all_gauges(self, mock_select, seed) -> None:
        assert isinstance(
            self.gauge_transformer.gauge_selector, GaugeSelector
        ), 'When using a custom selector, please override this method to properly test all gauges'
        c = cirq.Circuit(self.two_qubit_gate(cirq.LineQubit(0), cirq.LineQubit(1)))
        prng = np.random.default_rng(seed)
        for gauge in self.gauge_transformer.gauge_selector.gauges:
            mock_select.return_value = gauge
            assert self.gauge_transformer.gauge_selector(prng) == gauge
            nc = self.gauge_transformer(c, prng=prng)
            if self.must_fail:
                with pytest.raises(AssertionError):
                    _check_equivalent_with_error_message(c, nc, gauge)
            else:
                _check_equivalent_with_error_message(c, nc, gauge)
    def test_sweep(self) -> None:
        qubits = cirq.LineQubit.range(3)
        input_circuit = cirq.Circuit(
            cirq.Moment(cirq.H(qubits[0])),
            cirq.Moment(self.two_qubit_gate(*qubits[:2])),
            cirq.Moment(self.two_qubit_gate(*qubits[1:])),
            cirq.Moment([cirq.H(q) for q in qubits]),
            cirq.Moment([cirq.measure(q) for q in qubits]),
        )
        n_samples = 5
        parameterized_circuit, sweeps = self.gauge_transformer.as_sweep(input_circuit, N=n_samples)
        assert cirq.is_parameterized(parameterized_circuit)
        simulator = cirq.Simulator()
        results = simulator.run_sweep(parameterized_circuit, sweeps)
        assert len(results) == n_samples
        for params in sweeps:
            compiled_circuit = cirq.resolve_parameters(parameterized_circuit, params)
            if self.must_fail:
                with pytest.raises(AssertionError):
                    cirq.testing.assert_circuits_have_same_unitary_given_final_permutation(
                        input_circuit[:-1],
                        compiled_circuit[:-1],
                        qubit_map={q: q for q in input_circuit.all_qubits()},
                    )
                break
            cirq.testing.assert_circuits_have_same_unitary_given_final_permutation(
                input_circuit[:-1],
                compiled_circuit[:-1],
                qubit_map={q: q for q in input_circuit.all_qubits()},
            )
def _check_equivalent_with_error_message(c: cirq.AbstractCircuit, nc: cirq.AbstractCircuit, gauge):
    try:
        cirq.testing.assert_circuits_have_same_unitary_given_final_permutation(
            nc, c, qubit_map={q: q for q in c.all_qubits()}
        )
    except AssertionError as ex:
        raise AssertionError(f"{gauge=} didn't result in an equivalent circuit") from ex

from __future__ import annotations
import functools
from collections.abc import Hashable, Iterator, Sequence
from typing import TYPE_CHECKING
import attrs
import numpy as np
import cirq.circuits as circuits
import cirq.ops as ops
import cirq.protocols as protocols
import cirq.transformers.transformer_api as transformer_api
if TYPE_CHECKING:
    import cirq
_PAULIS: tuple[cirq.Gate, ...] = (ops.I, ops.X, ops.Y, ops.Z)  # type: ignore[has-type]
_CLIFFORDS = tuple(ops.SingleQubitCliffordGate.all_single_qubit_cliffords)
_INV_CLIFFORDS = tuple(c**-1 for c in ops.SingleQubitCliffordGate.all_single_qubit_cliffords)
_NAME_TO_GATES = {'pauli': _PAULIS, 'clifford': _CLIFFORDS, 'inv_clifford': _INV_CLIFFORDS}
def _gauges_arg_converter(gauges: str | Sequence[cirq.Gate] = 'clifford') -> tuple[cirq.Gate, ...]:
    if isinstance(gauges, str):
        if gauges not in _NAME_TO_GATES:
            valid_names = tuple(_NAME_TO_GATES.keys())
            raise ValueError(f"{gauges} is not a valid gauge name, valid names are {valid_names}")
        return _NAME_TO_GATES[gauges]
    return tuple(gauges)
def _repr_fn(gauges: tuple[cirq.Gate, ...]) -> str:
    if gauges is _PAULIS or gauges == _PAULIS:
        return '"pauli"'
    if gauges is _CLIFFORDS or gauges == _CLIFFORDS:
        return '"clifford"'
    if gauges is _INV_CLIFFORDS or gauges == _INV_CLIFFORDS:
        return '"inv_clifford"'
    return repr(gauges)
def _get_structure(
    active: list[tuple[int, bool]],
    min_length: int,
    n: int,
    gauge_beginning: bool,
    gauge_ending: bool,
) -> Iterator[tuple[int, int]]:
    if gauge_beginning:
        stop, is_mergable = active[0]
        if min_length <= stop:
            if is_mergable:
                yield (0, stop)
            else:
                yield (0, stop - 1)
    for i in range(len(active) - 1):
        left_pos, left_is_mergable = active[i]
        right_pos, right_is_mergable = active[i + 1]
        if right_pos - left_pos - 1 >= min_length:
            yield (left_pos + 1 - left_is_mergable, right_pos - 1 + right_is_mergable)
    if gauge_ending:
        stop, is_mergable = active[-1]
        if min_length <= n - stop - 1:
            if is_mergable:
                yield (stop, n - 1)
            else:
                yield (stop + 1, n - 1)
def _merge(g1: cirq.Gate, g2: cirq.Gate, q: cirq.Qid, tags: Sequence[Hashable]) -> cirq.Operation:
    u1 = protocols.unitary(g1)
    u2 = protocols.unitary(g2)
    return ops.PhasedXZGate.from_matrix(u2 @ u1)(q).with_tags(*tags)
@transformer_api.transformer
@attrs.frozen
class IdleMomentsGauge:
    r
    min_length: int = attrs.field(
        validator=(attrs.validators.instance_of(int), attrs.validators.ge(1))
    )
    gauges: tuple[cirq.Gate, ...] = attrs.field(
        default='clifford', converter=_gauges_arg_converter, repr=_repr_fn
    )
    gauge_beginning: bool = False
    gauge_ending: bool = False
    @functools.cached_property
    def gauges_inverse(self) -> tuple[cirq.Gate, ...]:
        if self.gauges is _PAULIS:
            return _PAULIS
        if self.gauges is _CLIFFORDS:
            return _INV_CLIFFORDS
        if self.gauges is _INV_CLIFFORDS:
            return _CLIFFORDS
        return tuple(g**-1 for g in self.gauges)
    def __call__(
        self,
        circuit: cirq.AbstractCircuit,
        *,
        context: transformer_api.TransformerContext | None = None,
        rng_or_seed: np.random.Generator | int | None = None,
    ):
        rng = (
            rng_or_seed
            if isinstance(rng_or_seed, np.random.Generator)
            else np.random.default_rng(rng_or_seed)
        )
        context = (
            context
            if isinstance(context, transformer_api.TransformerContext)
            else transformer_api.TransformerContext(deep=False)
        )
        if context.deep:
            raise ValueError("IdleMomentsGauge doesn't support deep TransformerContext")
        tags_to_ignore = frozenset(context.tags_to_ignore)
        all_qubits = circuit.all_qubits()
        active_moments: dict[cirq.Qid, list[tuple[int, bool]]] = {q: [] for q in all_qubits}
        for m_id, moment in enumerate(circuit):
            if not tags_to_ignore.isdisjoint(moment.tags):
                for q in all_qubits:
                    active_moments[q].append((m_id, False))
            else:
                for op in moment:
                    is_mergable = (
                        len(op.qubits) == 1
                        and tags_to_ignore.isdisjoint(op.tags)
                        and op.gate is not None
                    )
                    for q in op.qubits:
                        active_moments[q].append((m_id, is_mergable))
        single_qubit_moments = [
            {op.qubits[0]: op for op in m if len(op.qubits) == 1} for m in circuit
        ]
        non_single_qubit_moments = [[op for op in m if len(op.qubits) != 1] for m in circuit]
        for q, active in active_moments.items():
            for s, e in _get_structure(
                active, self.min_length, len(circuit), self.gauge_beginning, self.gauge_ending
            ):
                gate_index = rng.choice(len(self.gauges))
                gate = self.gauges[gate_index]
                gate_inv = self.gauges_inverse[gate_index]
                if existing_op := single_qubit_moments[s].get(q, None):
                    existing_gate = existing_op.gate
                    assert existing_gate is not None
                    single_qubit_moments[s][q] = _merge(existing_gate, gate, q, existing_op.tags)
                else:
                    single_qubit_moments[s][q] = gate(q)
                if existing_op := single_qubit_moments[e].get(q, None):
                    existing_gate = existing_op.gate
                    assert existing_gate is not None
                    single_qubit_moments[e][q] = _merge(
                        gate_inv, existing_gate, q, existing_op.tags
                    )
                else:
                    single_qubit_moments[e][q] = gate_inv(q)
        return circuits.Circuit.from_moments(
            *(
                [op for op in sq.values()] + nsq
                for sq, nsq in zip(single_qubit_moments, non_single_qubit_moments, strict=True)
            )
        )

from __future__ import annotations
import numpy as np
from cirq import ops
from cirq.transformers.gauge_compiling.gauge_compiling import (
    ConstantGauge,
    Gauge,
    GaugeSelector,
    GaugeTransformer,
)
class RZRotation(Gauge):
    def weight(self) -> float:
        return 2.0
    def _rz(self, theta, sgn: int) -> ConstantGauge:
        flip_diangonal = sgn == -1
        rz = ops.rz(theta)
        n_rz = ops.rz(-theta)
        return ConstantGauge(
            two_qubit_gate=ops.ISWAP,
            pre_q0=rz,
            pre_q1=n_rz if flip_diangonal else rz,
            post_q0=rz if flip_diangonal else n_rz,
            post_q1=n_rz,
        )
    def sample(self, gate: ops.Gate, prng: np.random.Generator) -> ConstantGauge:
        theta = prng.random() * 2 * np.pi
        return self._rz(theta, prng.choice([-1, 1]))
class XYRotation(Gauge):
    def weight(self) -> float:
        return 2.0
    def _xy(self, theta: float) -> ops.PhasedXZGate:
        unitary = np.cos(theta) * np.array([[0, 1], [1, 0]]) + np.sin(theta) * np.array(
            [[0, -1j], [1j, 0]]
        )
        return ops.PhasedXZGate.from_matrix(unitary)
    def _xy_gauge(self, a: float, b: float) -> ConstantGauge:
        xy_a = self._xy(a)
        xy_b = self._xy(b)
        return ConstantGauge(
            two_qubit_gate=ops.ISWAP, pre_q0=xy_a, pre_q1=xy_b, post_q0=xy_b, post_q1=xy_a
        )
    def sample(self, gate: ops.Gate, prng: np.random.Generator) -> ConstantGauge:
        a = prng.random() * 2 * np.pi
        if prng.choice([0, 1]):
            return self._xy_gauge(a, a)
        else:
            b = prng.random() * 2 * np.pi
            return self._xy_gauge(a, b)
ISWAPGaugeTransformer = GaugeTransformer(
    target=ops.ISWAP, gauge_selector=GaugeSelector(gauges=[RZRotation(), XYRotation()])
)

from __future__ import annotations
from typing import cast
import numpy as np
from attrs import field, frozen
from cirq import circuits, ops
from cirq.transformers.gauge_compiling.multi_moment_gauge_compiling import (
    MultiMomentGaugeTransformer,
)
_PAULIS: np.ndarray = np.array((ops.I, ops.X, ops.Y, ops.Z), dtype=object)
_COMMUTING_GATES = {ops.I, ops.Z}  # I,Z Commute with ZPowGate and CZPowGate; X,Y anti-commute.
def _merge_pauliandzpow(left: _PauliAndZPow, right: _PauliAndZPow) -> _PauliAndZPow:
    if right.pauli in _COMMUTING_GATES:
        new_zpow_exp = left.zpow.exponent + right.zpow.exponent
    else:
        new_zpow_exp = -left.zpow.exponent + right.zpow.exponent
    new_pauli = left.pauli
    if right.pauli is not ops.I:
        if new_pauli is ops.I:
            new_pauli = right.pauli
        else:
            new_pauli = cast(ops.Pauli, new_pauli).phased_pauli_product(
                cast(ops.Pauli, right.pauli)
            )[1]
    return _PauliAndZPow(pauli=new_pauli, zpow=ops.ZPowGate(exponent=new_zpow_exp))
@frozen
class _PauliAndZPow:
    pauli: ops.Pauli | ops.IdentityGate = ops.I
    zpow: ops.ZPowGate = ops.ZPowGate(exponent=0)
    def merge_left(self, left: _PauliAndZPow) -> _PauliAndZPow:
        return _merge_pauliandzpow(left, self)
    def merge_right(self, right: _PauliAndZPow) -> _PauliAndZPow:
        return _merge_pauliandzpow(self, right)
    def after_cphase(
        self, cphase: ops.CZPowGate
    ) -> tuple[ops.CZPowGate, _PauliAndZPow, _PauliAndZPow]:
        if self.pauli in _COMMUTING_GATES:
            return cphase, _PauliAndZPow(self.pauli, self.zpow), _PauliAndZPow()
        else:
            return (
                cast(ops.CZPowGate, cphase**-1),
                _PauliAndZPow(self.pauli, self.zpow),
                _PauliAndZPow(zpow=ops.ZPowGate(exponent=cphase.exponent)),
            )
    def after_pauli(self, pauli: ops.Pauli | ops.IdentityGate) -> _PauliAndZPow:
        if pauli in _COMMUTING_GATES:
            return _PauliAndZPow(self.pauli, self.zpow)
        else:
            return _PauliAndZPow(self.pauli, ops.ZPowGate(exponent=-self.zpow.exponent))
    def after_zpow(self, zpow: ops.ZPowGate) -> tuple[ops.ZPowGate, _PauliAndZPow]:
        if self.pauli in _COMMUTING_GATES:
            return zpow, _PauliAndZPow(self.pauli, self.zpow)
        else:
            return ops.ZPowGate(exponent=-zpow.exponent), self
    def __str__(self) -> str:
        return f"─{self.pauli}──{self.zpow}─"
    def to_single_qubit_gate(self) -> ops.PhasedXZGate | ops.ZPowGate | ops.IdentityGate:
        exp = self.zpow.exponent
        match self.pauli:
            case ops.I:
                if exp % 2 == 0:
                    return ops.I
                return self.zpow
            case ops.X:
                return ops.PhasedXZGate(x_exponent=1, z_exponent=exp, axis_phase_exponent=0)
            case ops.Y:
                return ops.PhasedXZGate(x_exponent=1, z_exponent=exp - 1, axis_phase_exponent=0)
            case _:  # ops.Z
                return ops.ZPowGate(exponent=1 + exp)
def _pull_through_single_cphase(
    cphase: ops.CZPowGate, input0: _PauliAndZPow, input1: _PauliAndZPow
) -> tuple[ops.CZPowGate, _PauliAndZPow, _PauliAndZPow]:
    output_cphase, output0, output1 = input0.after_cphase(cphase)
    output_cphase, pulled1, pulled0 = input1.after_cphase(output_cphase)
    output0 = output0.merge_left(pulled0)
    output1 = output1.merge_left(pulled1)
    return output_cphase, output0, output1
_TARGET_GATESET: ops.Gateset = ops.Gateset(ops.CZPowGate)
_SUPPORTED_GATESET: ops.Gateset = ops.Gateset(ops.Pauli, ops.IdentityGate, ops.ZPowGate)
@frozen
class CPhaseGaugeTransformerMM(MultiMomentGaugeTransformer):
    target: ops.GateFamily | ops.Gateset = field(default=_TARGET_GATESET, init=False)
    supported_gates: ops.GateFamily | ops.Gateset = field(default=_SUPPORTED_GATESET)
    def sample_left_moment(
        self, active_qubits: frozenset[ops.Qid], prng: np.random.Generator
    ) -> circuits.Moment:
        return circuits.Moment([cast(ops.Gate, prng.choice(_PAULIS)).on(q) for q in active_qubits])
    def gauge_on_moments(
        self, moments_to_gauge: list[circuits.Moment], prng: np.random.Generator
    ) -> list[circuits.Moment]:
        active_qubits = circuits.Circuit.from_moments(*moments_to_gauge).all_qubits()
        left_moment = self.sample_left_moment(active_qubits, prng)
        pulled: dict[ops.Qid, _PauliAndZPow] = {
            op.qubits[0]: _PauliAndZPow(pauli=cast(ops.Pauli | ops.IdentityGate, op.gate))
            for op in left_moment
            if op.gate
        }
        ret: list[circuits.Moment] = [left_moment]
        for moment in moments_to_gauge:
            prev = pulled
            pulled = {}
            ops_at_updated_moment: list[ops.Operation] = []
            for op in moment:
                if op.gate:
                    match op.gate:
                        case ops.CZPowGate():
                            q0, q1 = op.qubits
                            new_gate, pulled[q0], pulled[q1] = _pull_through_single_cphase(
                                op.gate, prev[q0], prev[q1]
                            )
                            ops_at_updated_moment.append(new_gate.on(q0, q1))
                        case ops.Pauli() | ops.IdentityGate():
                            q = op.qubits[0]
                            ops_at_updated_moment.append(op)
                            pulled[q] = prev[q].after_pauli(op.gate)
                        case ops.ZPowGate():
                            q = op.qubits[0]
                            new_zpow, pulled[q] = prev[q].after_zpow(op.gate)
                            ops_at_updated_moment.append(new_zpow.on(q))
                        case _:
                            raise ValueError(f"Gate type {type(op.gate)} is not supported.")
            for q, gate in prev.items():
                if q not in pulled:
                    pulled[q] = gate
            ret.append(circuits.Moment(ops_at_updated_moment))
        last_moment = circuits.Moment(
            [gate.to_single_qubit_gate().on(q) for q, gate in pulled.items()]
        )
        ret.append(last_moment)
        return ret

