from __future__ import annotations
from collections.abc import Sequence
import numpy as np
import cirq
from cirq import protocols, value
from cirq.qis.clifford_tableau import CliffordTableau
from cirq.sim.clifford.clifford_tableau_simulation_state import CliffordTableauSimulationState
from cirq.work import sampler
class StabilizerSampler(sampler.Sampler):
    def __init__(self, *, seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None):
        self.init = True
        self._prng = value.parse_random_state(seed)
    def run_sweep(
        self, program: cirq.AbstractCircuit, params: cirq.Sweepable, repetitions: int = 1
    ) -> Sequence[cirq.Result]:
        results: list[cirq.Result] = []
        for param_resolver in cirq.to_resolvers(params):
            resolved_circuit = cirq.resolve_parameters(program, param_resolver)
            measurements = self._run(resolved_circuit, repetitions=repetitions)
            results.append(cirq.ResultDict(params=param_resolver, measurements=measurements))
        return results
    def _run(self, circuit: cirq.AbstractCircuit, repetitions: int) -> dict[str, np.ndarray]:
        measurements: dict[str, list[np.ndarray]] = {
            key: [] for key in protocols.measurement_key_names(circuit)
        }
        qubits = circuit.all_qubits()
        for _ in range(repetitions):
            state = CliffordTableauSimulationState(
                CliffordTableau(num_qubits=len(qubits)), qubits=list(qubits), prng=self._prng
            )
            for op in circuit.all_operations():
                protocols.act_on(op, state)
            for k, v in state.log_of_measurement_results.items():
                measurements[k].append(np.array(v, dtype=np.uint8))
        return {k: np.array(v) for k, v in measurements.items()}

from __future__ import annotations
import abc
from collections.abc import Sequence
from types import NotImplementedType
from typing import Any, cast, Generic, TYPE_CHECKING, TypeVar
import sympy
from cirq import linalg, ops, protocols
from cirq.ops import common_gates, global_phase_op, matrix_gates, swap_gates
from cirq.ops.clifford_gate import SingleQubitCliffordGate
from cirq.protocols import has_unitary, num_qubits, unitary
from cirq.sim.simulation_state import SimulationState
if TYPE_CHECKING:
    import numpy as np
    import cirq
TStabilizerState = TypeVar('TStabilizerState', bound='cirq.StabilizerState')
class StabilizerSimulationState(
    SimulationState[TStabilizerState], Generic[TStabilizerState], metaclass=abc.ABCMeta
):
    def __init__(
        self,
        *,
        state: TStabilizerState,
        prng: np.random.RandomState | None = None,
        qubits: Sequence[cirq.Qid] | None = None,
        classical_data: cirq.ClassicalDataStore | None = None,
    ):
        super().__init__(state=state, prng=prng, qubits=qubits, classical_data=classical_data)
    @property
    def state(self) -> TStabilizerState:
        return self._state
    def _act_on_fallback_(
        self, action: Any, qubits: Sequence[cirq.Qid], allow_decompose: bool = True
    ) -> bool | NotImplementedType:
        strats = [self._strat_apply_gate, self._strat_apply_mixture]
        if allow_decompose:
            strats.append(self._strat_decompose)
            strats.append(self._strat_act_from_single_qubit_decompose)
        for strat in strats:
            result = strat(action, qubits)
            if result is True:
                return True
            assert result is NotImplemented, str(result)
        return NotImplemented
    def _swap(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ):
        if exponent % 1 != 0:
            raise ValueError('Swap exponent must be integer')  # pragma: no cover
        self._state.apply_cx(control_axis, target_axis)
        self._state.apply_cx(target_axis, control_axis, exponent, global_shift)
        self._state.apply_cx(control_axis, target_axis)
    def _strat_apply_gate(self, val: Any, qubits: Sequence[cirq.Qid]) -> bool:
        if not protocols.has_stabilizer_effect(val):
            return NotImplemented
        gate = val.gate if isinstance(val, ops.Operation) else val
        axes = self.get_axes(qubits)
        exponent = cast(float, getattr(gate, 'exponent', None))
        if isinstance(gate, common_gates.XPowGate):
            self._state.apply_x(axes[0], exponent, gate.global_shift)
        elif isinstance(gate, common_gates.YPowGate):
            self._state.apply_y(axes[0], exponent, gate.global_shift)
        elif isinstance(gate, common_gates.ZPowGate):
            self._state.apply_z(axes[0], exponent, gate.global_shift)
        elif isinstance(gate, common_gates.HPowGate):
            self._state.apply_h(axes[0], exponent, gate.global_shift)
        elif isinstance(gate, common_gates.CXPowGate):
            self._state.apply_cx(axes[0], axes[1], exponent, gate.global_shift)
        elif isinstance(gate, common_gates.CZPowGate):
            self._state.apply_cz(axes[0], axes[1], exponent, gate.global_shift)
        elif isinstance(gate, global_phase_op.GlobalPhaseGate):
            if isinstance(gate.coefficient, sympy.Expr):
                return NotImplemented
            self._state.apply_global_phase(gate.coefficient)
        elif isinstance(gate, swap_gates.SwapPowGate):
            self._swap(axes[0], axes[1], exponent, gate.global_shift)
        else:
            return NotImplemented
        return True
    def _strat_apply_mixture(self, val: Any, qubits: Sequence[cirq.Qid]) -> bool:
        mixture = protocols.mixture(val, None)
        if mixture is None:
            return NotImplemented
        if not all(linalg.is_unitary(m) for _, m in mixture):
            return NotImplemented  # pragma: no cover
        probabilities, unitaries = zip(*mixture)
        index = self.prng.choice(len(unitaries), p=probabilities)
        return self._strat_act_from_single_qubit_decompose(
            matrix_gates.MatrixGate(unitaries[index]), qubits
        )
    def _strat_act_from_single_qubit_decompose(self, val: Any, qubits: Sequence[cirq.Qid]) -> bool:
        if num_qubits(val) == 1:
            if not has_unitary(val):
                return NotImplemented
            u = unitary(val)
            gate_and_phase = SingleQubitCliffordGate.from_unitary_with_global_phase(u)
            if gate_and_phase is not None:
                clifford_gate, global_phase = gate_and_phase
                for gate in clifford_gate.decompose_gate():
                    self._strat_apply_gate(gate, qubits)
                self._state.apply_global_phase(global_phase)
                return True
        return NotImplemented
    def _strat_decompose(self, val: Any, qubits: Sequence[cirq.Qid]) -> bool:
        gate = val.gate if isinstance(val, ops.Operation) else val
        operations = protocols.decompose_once_with_qubits(gate, qubits, None)
        if operations is None or not all(protocols.has_stabilizer_effect(op) for op in operations):
            return NotImplemented
        for op in operations:
            protocols.act_on(op, self)
        return True

from __future__ import annotations
from collections.abc import Sequence
from typing import Any
import numpy as np
import cirq
from cirq import protocols, qis, value
from cirq.value import big_endian_int_to_digits, random_state
@value.value_equality(unhashable=True)
class StabilizerStateChForm(qis.StabilizerState):
    r
    def __init__(self, num_qubits: int, initial_state: int = 0) -> None:
        self.n = num_qubits
        self.G = np.eye(self.n, dtype=bool)
        self.F = np.eye(self.n, dtype=bool)
        self.M = np.zeros((self.n, self.n), dtype=bool)
        self.gamma = np.zeros(self.n, dtype=int)
        self.v = np.zeros(self.n, dtype=bool)
        self.s = np.zeros(self.n, dtype=bool)
        self.omega: complex = 1
        for i, val in enumerate(
            big_endian_int_to_digits(initial_state, digit_count=num_qubits, base=2)
        ):
            if val:
                self.apply_x(i)
    def _json_dict_(self) -> dict[str, Any]:
        return protocols.obj_to_dict_helper(self, ['n', 'G', 'F', 'M', 'gamma', 'v', 's', 'omega'])
    @classmethod
    def _from_json_dict_(cls, n, G, F, M, gamma, v, s, omega, **kwargs):
        copy = StabilizerStateChForm(n)
        copy.G = np.array(G)
        copy.F = np.array(F)
        copy.M = np.array(M)
        copy.gamma = np.array(gamma)
        copy.v = np.array(v)
        copy.s = np.array(s)
        copy.omega = omega
        return copy
    def _value_equality_values_(self) -> Any:
        return (self.n, self.G, self.F, self.M, self.gamma, self.v, self.s, self.omega)
    def copy(self, deep_copy_buffers: bool = True) -> cirq.StabilizerStateChForm:
        copy = StabilizerStateChForm(self.n)
        copy.G = self.G.copy()
        copy.F = self.F.copy()
        copy.M = self.M.copy()
        copy.gamma = self.gamma.copy()
        copy.v = self.v.copy()
        copy.s = self.s.copy()
        copy.omega = self.omega
        return copy
    def __str__(self) -> str:
        return cirq.dirac_notation(self.to_state_vector())
    def __repr__(self) -> str:
        return f'StabilizerStateChForm(num_qubits={self.n!r})'
    def inner_product_of_state_and_x(self, x: int) -> complex:
        if type(x) == int:
            y = cirq.big_endian_int_to_bits(x, bit_count=self.n)
        mu = sum(y * self.gamma)
        u = np.zeros(self.n, dtype=bool)
        for p in range(self.n):
            if y[p]:
                u ^= self.F[p, :]
                mu += 2 * (sum(self.M[p, :] & u) % 2)
        return (
            self.omega
            * 2 ** (-sum(self.v) / 2)
            * 1j**mu
            * (-1) ** sum(self.v & u & self.s)
            * bool(np.all(self.v | (u == self.s)))
        )
    def state_vector(self) -> np.ndarray:
        wf = np.zeros(2**self.n, dtype=complex)
        for x in range(2**self.n):
            wf[x] = self.inner_product_of_state_and_x(x)
        return wf
    def _S_right(self, q):
        r
        self.M[:, q] ^= self.F[:, q]
        self.gamma[:] = (self.gamma[:] - self.F[:, q]) % 4
    def _CZ_right(self, q, r):
        r
        self.M[:, q] ^= self.F[:, r]
        self.M[:, r] ^= self.F[:, q]
        self.gamma[:] = (self.gamma[:] + 2 * self.F[:, q] * self.F[:, r]) % 4
    def _CNOT_right(self, q, r):
        r
        self.G[:, q] ^= self.G[:, r]
        self.F[:, r] ^= self.F[:, q]
        self.M[:, q] ^= self.M[:, r]
    def update_sum(self, t, u, delta=0, alpha=0) -> None:
        if np.all(t == u):
            self.s = t
            self.omega *= 1 / np.sqrt(2) * (-1) ** alpha * (1 + 1j**delta)
            return
        set0 = np.where((~self.v) & (t ^ u))[0]
        set1 = np.where(self.v & (t ^ u))[0]
        if len(set0) > 0:
            q = set0[0]
            for i in set0:
                if i != q:
                    self._CNOT_right(q, i)
            for i in set1:
                self._CZ_right(q, i)
        elif len(set1) > 0:
            q = set1[0]
            for i in set1:
                if i != q:
                    self._CNOT_right(i, q)
        e = np.zeros(self.n, dtype=bool)
        e[q] = True
        if t[q]:
            y = u ^ e
            z = u
        else:
            y = t
            z = t ^ e
        (omega, a, b, c) = self._H_decompose(self.v[q], y[q], z[q], delta)
        self.s = y
        self.s[q] = c
        self.omega *= (-1) ** alpha * omega
        if a:
            self._S_right(q)
        self.v[q] ^= b ^ self.v[q]
    def _H_decompose(self, v, y, z, delta):
        if y == z:
            raise ValueError('|y> is equal to |z>')
        if not v:
            omega = (1j) ** (delta * int(y))
            delta2 = ((-1) ** y * delta) % 4
            c = bool(delta2 >> 1)
            a = bool(delta2 & 1)
            b = True
        else:
            if not (delta & 1):
                a = False
                b = False
                c = bool(delta >> 1)
                omega = (-1) ** (c & y)
            else:
                omega = 1 / np.sqrt(2) * (1 + 1j**delta)
                b = True
                a = True
                c = not ((delta >> 1) ^ y)
        return omega, a, b, c
    def to_state_vector(self) -> np.ndarray:
        arr = np.zeros(2**self.n, dtype=complex)
        for x in range(len(arr)):
            arr[x] = self.inner_product_of_state_and_x(x)
        return arr
    def _measure(self, q, prng: np.random.RandomState) -> int:
        w = self.s.copy()
        for i, v_i in enumerate(self.v):
            if v_i == 1:
                w[i] = bool(prng.randint(2))
        x_i = sum(w & self.G[q, :]) % 2
        self.project_Z(q, x_i)
        return x_i
    def project_Z(self, q, z) -> None:
        t = self.s.copy()
        u = (self.G[q, :] & self.v) ^ self.s
        delta = (2 * sum((self.G[q, :] & (~self.v)) & self.s) + 2 * z) % 4
        if np.all(t == u):
            self.omega /= np.sqrt(2)
        self.update_sum(t, u, delta=delta)
    def kron(self, other: cirq.StabilizerStateChForm) -> cirq.StabilizerStateChForm:
        n = self.n + other.n
        copy = StabilizerStateChForm(n)
        copy.G[: self.n, : self.n] = self.G
        copy.G[self.n :, self.n :] = other.G
        copy.F[: self.n, : self.n] = self.F
        copy.F[self.n :, self.n :] = other.F
        copy.M[: self.n, : self.n] = self.M
        copy.M[self.n :, self.n :] = other.M
        copy.gamma = np.concatenate([self.gamma, other.gamma])
        copy.v = np.concatenate([self.v, other.v])
        copy.s = np.concatenate([self.s, other.s])
        copy.omega = self.omega * other.omega
        return copy
    def reindex(self, axes: Sequence[int]) -> cirq.StabilizerStateChForm:
        copy = StabilizerStateChForm(self.n)
        copy.G = self.G[axes][:, axes]
        copy.F = self.F[axes][:, axes]
        copy.M = self.M[axes][:, axes]
        copy.gamma = self.gamma[axes]
        copy.v = self.v[axes]
        copy.s = self.s[axes]
        copy.omega = self.omega
        return copy
    def apply_x(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 != 0:
            if exponent % 0.5 != 0.0:
                raise ValueError('X exponent must be half integer')  # pragma: no cover
            self.apply_h(axis)
            self.apply_z(axis, exponent)
            self.apply_h(axis)
        self.omega *= _phase(exponent, global_shift)
    def apply_y(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 0.5 != 0.0:
            raise ValueError('Y exponent must be half integer')  # pragma: no cover
        shift = _phase(exponent, global_shift)
        if exponent % 2 == 0:
            self.omega *= shift
        elif exponent % 2 == 0.5:
            self.apply_z(axis)
            self.apply_h(axis)
            self.omega *= shift * (1 + 1j) / (2**0.5)
        elif exponent % 2 == 1:
            self.apply_z(axis)
            self.apply_h(axis)
            self.apply_z(axis)
            self.apply_h(axis)
            self.omega *= shift * 1j
        elif exponent % 2 == 1.5:
            self.apply_h(axis)
            self.apply_z(axis)
            self.omega *= shift * (1 - 1j) / (2**0.5)
    def apply_z(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 != 0:
            if exponent % 0.5 != 0.0:
                raise ValueError('Z exponent must be half integer')  # pragma: no cover
            effective_exponent = exponent % 2
            for _ in range(int(effective_exponent * 2)):
                self.M[axis, :] ^= self.G[axis, :]
                self.gamma[axis] = (self.gamma[axis] - 1) % 4
        self.omega *= _phase(exponent, global_shift)
    def apply_h(self, axis: int, exponent: float = 1, global_shift: float = 0) -> None:
        if exponent % 2 != 0:
            if exponent % 1 != 0:
                raise ValueError('H exponent must be integer')  # pragma: no cover
            t = self.s ^ (self.G[axis, :] & self.v)
            u = self.s ^ (self.F[axis, :] & (~self.v)) ^ (self.M[axis, :] & self.v)
            alpha = sum(self.G[axis, :] & (~self.v) & self.s) % 2
            beta = sum(self.M[axis, :] & (~self.v) & self.s)
            beta += sum(self.F[axis, :] & self.v & self.M[axis, :])
            beta += sum(self.F[axis, :] & self.v & self.s)
            beta %= 2
            delta = (self.gamma[axis] + 2 * (alpha + beta)) % 4
            self.update_sum(t, u, delta=delta, alpha=alpha)
        self.omega *= _phase(exponent, global_shift)
    def apply_cz(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ) -> None:
        if exponent % 2 != 0:
            if exponent % 1 != 0:
                raise ValueError('CZ exponent must be integer')  # pragma: no cover
            self.M[control_axis, :] ^= self.G[target_axis, :]
            self.M[target_axis, :] ^= self.G[control_axis, :]
        self.omega *= _phase(exponent, global_shift)
    def apply_cx(
        self, control_axis: int, target_axis: int, exponent: float = 1, global_shift: float = 0
    ) -> None:
        if exponent % 2 != 0:
            if exponent % 1 != 0:
                raise ValueError('CX exponent must be integer')  # pragma: no cover
            self.gamma[control_axis] = (
                self.gamma[control_axis]
                + self.gamma[target_axis]
                + 2 * (sum(self.M[control_axis, :] & self.F[target_axis, :]) % 2)
            ) % 4
            self.G[target_axis, :] ^= self.G[control_axis, :]
            self.F[control_axis, :] ^= self.F[target_axis, :]
            self.M[control_axis, :] ^= self.M[target_axis, :]
        self.omega *= _phase(exponent, global_shift)
    def apply_global_phase(self, coefficient: value.Scalar) -> None:
        self.omega *= coefficient
    def measure(
        self, axes: Sequence[int], seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None
    ) -> list[int]:
        return [self._measure(axis, random_state.parse_random_state(seed)) for axis in axes]
def _phase(exponent, global_shift):
    return np.exp(1j * np.pi * global_shift * exponent)

