        self.name = name
        super().__init__(permutation)
    def _value_equality_values_(self):
        return self.identifier, self.name, self.permutation
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> tuple[str, ...]:
        return tuple(
            f'{self.name}[{i}>{self.permutation[i]}]' for i in range(len(self.permutation))
        )
    def __repr__(self) -> str:
        return (
            'cirq.interop.quirk.QuirkQubitPermutationGate('
            f'identifier={repr(self.identifier)},'
            f'name={repr(self.name)},'
            f'permutation={repr(self.permutation)})'
        )
def generate_all_qubit_permutation_cell_makers() -> Iterator[CellMaker]:
    yield from _permutation_family("<<", 'left_rotate', lambda _, x: x + 1)
    yield from _permutation_family(">>", 'right_rotate', lambda _, x: x - 1)
    yield from _permutation_family("rev", 'reverse', lambda _, x: ~x)
    yield from _permutation_family("weave", 'interleave', _interleave_bit)
    yield from _permutation_family("split", 'deinterleave', _deinterleave_bit)
def _permutation_family(
    identifier_prefix: str, name: str, permute: Callable[[int, int], int]
) -> Iterator[CellMaker]:
    for n in CELL_SIZES:
        permutation = tuple(permute(n, i) % n for i in range(n))
        yield _permutation(identifier_prefix + str(n), name, permutation)
def _permutation(identifier: str, name: str, permutation: tuple[int, ...]) -> CellMaker:
    return CellMaker(
        identifier,
        size=len(permutation),
        maker=lambda args: QuirkQubitPermutationGate(
            identifier=identifier, name=name, permutation=permutation
        ).on(*args.qubits),
    )
def _interleave_bit(n: int, x: int) -> int:
    h = (n + 1) // 2
    group = x // h
    stride = x % h
    return stride * 2 + group
def _deinterleave_bit(n: int, x: int) -> int:
    h = (n + 1) // 2
    stride = x // 2
    group = x % 2
    return stride + group * h

from __future__ import annotations
from collections.abc import Iterable, Iterator
from typing import Any, TYPE_CHECKING
from cirq import ops, value
from cirq.interop.quirk.cells.cell import Cell, CellMaker
if TYPE_CHECKING:
    import cirq
@value.value_equality(unhashable=True)
class SwapCell(Cell):
    def __init__(self, qubits: Iterable[cirq.Qid], controls: Iterable[cirq.Qid]):
        self._qubits = list(qubits)
        self._controls = list(controls)
    def gate_count(self) -> int:
        return 1
    def with_line_qubits_mapped_to(self, qubits: list[cirq.Qid]) -> Cell:
        return SwapCell(
            qubits=Cell._replace_qubits(self._qubits, qubits),
            controls=Cell._replace_qubits(self._controls, qubits),
        )
    def modify_column(self, column: list[Cell | None]) -> None:
        for i in range(len(column)):
            gate = column[i]
            if gate is not self and isinstance(gate, SwapCell):
                assert self._controls == gate._controls
                self._qubits += gate._qubits
                column[i] = None
    def operations(self) -> cirq.OP_TREE:
        if len(self._qubits) != 2:
            raise ValueError('Wrong number of swap gates in a column.')
        return ops.SWAP(*self._qubits).controlled_by(*self._controls)
    def controlled_by(self, qubit: cirq.Qid) -> SwapCell:
        return SwapCell(self._qubits, self._controls + [qubit])
    def _value_equality_values_(self) -> Any:
        return self._qubits, self._controls
    def __repr__(self) -> str:
        return (
            f'cirq.interop.quirk.cells.swap_cell.SwapCell('
            f'\n    {self._qubits!r},'
            f'\n    {self._controls!r})'
        )
def generate_all_swap_cell_makers() -> Iterator[CellMaker]:
    yield CellMaker("Swap", 1, lambda args: SwapCell(args.qubits, []))

