import cirq.experiments.xeb_fitting as xeb_fitting
from cirq import circuits, devices, ops, protocols, sim, value
if TYPE_CHECKING:
    import cirq
_TARGET_T = Union['cirq.Gate', 'cirq.Operation', 'cirq.AbstractCircuit']
_QUBIT_PAIR_T = tuple['cirq.GridQubit', 'cirq.GridQubit']
_CANONICAL_TARGET_T = Union['cirq.Operation', Mapping[_QUBIT_PAIR_T, 'cirq.Operation']]
_PROBABILITIES_DICT_T = Mapping[_QUBIT_PAIR_T, list[list[np.ndarray]]]
def _canonize_pair(pair: _QUBIT_PAIR_T) -> _QUBIT_PAIR_T:
    return min(pair), max(pair)
def _tuple_from_ints(seq: Iterable[int]) -> tuple[int, ...]:
    return tuple(seq)
@attrs.frozen
class XEBParameters:
    n_repetitions: int = 10**4
    n_combinations: int = 10
    n_circuits: int = 20
    cycle_depths: tuple[int, ...] = attrs.field(
        default=(5, 25, 50, 100, 200, 300), converter=_tuple_from_ints
    )
@attrs.frozen
class XEBWideCircuitInfo:
    wide_circuit: circuits.Circuit
    pairs: Sequence[_QUBIT_PAIR_T] = attrs.field(
        converter=lambda seq: [_canonize_pair(pair) for pair in seq]
    )
    narrow_template_indices: tuple[int, ...] = attrs.field(converter=_tuple_from_ints)
    cycle_depth: int | None = None
    @staticmethod
    def from_narrow_circuits(
        circuit_templates: Sequence[cirq.Circuit],
        permutation: np.ndarray,
        pairs: Sequence[_QUBIT_PAIR_T],
        target: _CANONICAL_TARGET_T,
    ) -> XEBWideCircuitInfo:
        transformed_circuits = []
        has_circuit_operations = False
        for i, pair in zip(permutation, pairs, strict=True):
            circuit = circuit_templates[i].transform_qubits(lambda q: pair[q.x])
            if isinstance(target, ops.Operation):
                xeb_op = target.with_qubits(*pair)
            else:
                if pair not in target:
                    continue
                xeb_op = target[pair]
                xeb_op = xeb_op.with_qubits(*pair)
            if isinstance(xeb_op, circuits.CircuitOperation):
                xeb_op = xeb_op.mapped_op()
                has_circuit_operations = True
            def _map_operation(op):
                num_qubits = protocols.num_qubits(op)
                if num_qubits <= 1:
                    return op
                assert num_qubits == 2
                return xeb_op
            circuit = circuit.map_operations(_map_operation)
            transformed_circuits.append(circuit)
        zipped_circuit = circuits.Circuit.zip(*transformed_circuits)
        if has_circuit_operations and len(circuit_templates) > 1:
            new_moments = []
            for moment in zipped_circuit:
                if any(isinstance(op, circuits.CircuitOperation) for op in moment):
                    new_moments.append(
                        _transform_moment_with_circuit_ops_to_moment_with_single_op(moment)
                    )
                else:
                    new_moments.append(moment)
            zipped_circuit = circuits.Circuit.from_moments(*new_moments)
        return XEBWideCircuitInfo(zipped_circuit, pairs, narrow_template_indices=permutation)
    def sliced_circuits(self, cycle_depths: Sequence[int]) -> Sequence[XEBWideCircuitInfo]:
        xeb_circuits = []
        for cycle_depth in cycle_depths:
            circuit_depth = 2 * cycle_depth + 1
            xeb_circuit = self.wide_circuit[:circuit_depth]
            xeb_circuit.append(
                circuits.Moment(ops.measure(pair, key=str(pair)) for pair in self.pairs)
            )
            xeb_circuits.append(
                attrs.evolve(self, wide_circuit=xeb_circuit, cycle_depth=cycle_depth)
            )
        return xeb_circuits
def _target_to_operation(target: _TARGET_T) -> cirq.Operation:
    if isinstance(target, ops.Gate):
        return target(*devices.LineQid.for_gate(target))
    elif isinstance(target, circuits.AbstractCircuit):
        return circuits.CircuitOperation(target.freeze())
    return target
def _canonize_target(target: _TARGET_T | Mapping[_QUBIT_PAIR_T, _TARGET_T]) -> _CANONICAL_TARGET_T:
    if isinstance(target, (ops.Gate, ops.Operation, circuits.AbstractCircuit)):
        return _target_to_operation(target)
    return {k: _target_to_operation(v) for k, v in target.items()}
def _transform_moment_with_circuit_ops_to_moment_with_single_op(
    moment: circuits.Moment,
) -> circuits.Moment:
    circuit_ops = [
        op.mapped_circuit() for op in moment if isinstance(op, circuits.CircuitOperation)
    ]
    not_circuit_ops = [op for op in moment if not isinstance(op, circuits.CircuitOperation)]
    all_subcircuits = circuit_ops
    if not_circuit_ops:
        all_subcircuits.append(circuits.Circuit(circuits.Moment(not_circuit_ops)))
    return circuits.Moment(circuits.CircuitOperation(circuits.FrozenCircuit.zip(*all_subcircuits)))
def create_combination_circuits(
    circuit_templates: Sequence[cirq.Circuit],
    combinations_by_layer: Sequence[rqcg.CircuitLibraryCombination],
    target: _CANONICAL_TARGET_T,
) -> Sequence[XEBWideCircuitInfo]:
    wide_circuits_info = []
    for layer_comb in combinations_by_layer:
        pairs = layer_comb.pairs
        if isinstance(target, dict):
            pairs = [pair for pair in pairs if pair in target]
            assert pairs
        for comb in layer_comb.combinations:
            wide_circuits_info.append(
                XEBWideCircuitInfo.from_narrow_circuits(
                    circuit_templates,
                    permutation=comb,
                    pairs=layer_comb.pairs,  # type: ignore[arg-type]
                    target=target,
                )
            )
    return wide_circuits_info
def simulate_circuit(
    simulator: cirq.Simulator, circuit: cirq.Circuit, cycle_depths: Sequence[int]
) -> Sequence[np.ndarray]:
    cycle_depths_set = frozenset(cycle_depths)
    result = []
    for moment_i, step_result in enumerate(simulator.simulate_moment_steps(circuit=circuit)):
        if moment_i % 2 == 1:
            continue
        cycle_depth = moment_i // 2
        if cycle_depth not in cycle_depths_set:
            continue
        psi = step_result.state_vector()
        pure_probs = value.state_vector_to_probabilities(psi)
        result.append(pure_probs)
    return result
@overload
def simulate_circuit_library(
    circuit_templates: Sequence[cirq.Circuit],
    target_or_dict: ops.Operation,
    cycle_depths: Sequence[int],
    pool: futures.Executor | None = None,
) -> Sequence[Sequence[np.ndarray]]: ...
@overload
def simulate_circuit_library(
    circuit_templates: Sequence[cirq.Circuit],
    target_or_dict: Mapping[_QUBIT_PAIR_T, ops.Operation],
    cycle_depths: Sequence[int],
    pool: futures.Executor | None = None,
) -> Mapping[_QUBIT_PAIR_T, Sequence[Sequence[np.ndarray]]]: ...
def simulate_circuit_library(
    circuit_templates: Sequence[cirq.Circuit],
    target_or_dict: _CANONICAL_TARGET_T,
    cycle_depths: Sequence[int],
    pool: futures.Executor | None = None,
) -> Sequence[Sequence[np.ndarray]] | Mapping[_QUBIT_PAIR_T, Sequence[Sequence[np.ndarray]]]:
    two_qubit_ops = []
    keys = None
    if isinstance(target_or_dict, dict):
        keys = tuple(target_or_dict.keys())
        two_qubit_ops = list(target_or_dict[k] for k in keys)
    else:
        two_qubit_ops = [target_or_dict]
    all_circuits = []
    for target_op in two_qubit_ops:
        def _map_op(op: ops.Operation) -> ops.Operation:
            num_qubits = protocols.num_qubits(op)
            if num_qubits <= 1:
                return op
            assert num_qubits == 2
            return target_op.with_qubits(*op.qubits)
        for circuit in circuit_templates:
            all_circuits.append(circuit.map_operations(_map_op))
    if pool is None:
        simulation_results = [
            simulate_circuit(
                sim.Simulator(seed=np.random.RandomState(), dtype=np.complex128),
                circuit=circuit,
                cycle_depths=cycle_depths,
            )
            for circuit in all_circuits
        ]
    else:
        simulation_results = [[np.empty(0)] for _ in range(len(all_circuits))]
        tasks = [
            pool.submit(
                simulate_circuit,
                simulator=sim.Simulator(seed=np.random.RandomState(), dtype=np.complex128),
                circuit=circuit,
                cycle_depths=cycle_depths,
            )
            for circuit in all_circuits
        ]
        tasks_index = {t: i for i, t in enumerate(tasks)}
        for task in futures.as_completed(tasks):
            sim_result = task.result()
            i = tasks_index[task]
            simulation_results[i] = sim_result
    if keys is None:
        return simulation_results
    num_templates = len(circuit_templates)
    return {
        keys[i]: simulation_results[i * num_templates : (i + 1) * num_templates]
        for i in range(len(keys))
    }
def sample_all_circuits(
    sampler: cirq.Sampler, circuits: Sequence[cirq.Circuit], repetitions: int
) -> Sequence[dict[str, np.ndarray]]:
    sampling_results = []
    for (result,) in sampler.run_batch(programs=circuits, repetitions=repetitions):
        record = {}
        for key in result.data.keys():
            values = result.data[key]
            sampled_probs = np.bincount(values, minlength=4) / len(values)
            record[key] = sampled_probs
        sampling_results.append(record)
    return sampling_results
def _reshape_sampling_results(
    sampling_results: Sequence[dict[str, np.ndarray]],
    cycle_depths: Sequence[int],
    wide_circuits_info: Sequence[XEBWideCircuitInfo],
    pairs: Sequence[_QUBIT_PAIR_T],
    num_templates: int,
) -> _PROBABILITIES_DICT_T:
    cycle_depth_to_index = {d: i for i, d in enumerate(cycle_depths)}
    sampled_probabilities = {
        pair: [[np.empty(0)] * num_templates for _ in range(len(cycle_depths))] for pair in pairs
    }
    for sampling_result, info in zip(sampling_results, wide_circuits_info, strict=True):
        cycle_depth = info.cycle_depth
        assert cycle_depth is not None
        cycle_idx = cycle_depth_to_index[cycle_depth]
        for template_idx, pair in zip(info.narrow_template_indices, info.pairs, strict=True):
            pair = _canonize_pair(pair)
            key = str(pair)
            sampled_prob = sampling_result.get(key, np.empty(0))
            sampled_probabilities[pair][cycle_idx][template_idx] = sampled_prob
    return sampled_probabilities
def _reshape_simulation_results(
    simulation_results: (
        Sequence[Sequence[np.ndarray]] | Mapping[_QUBIT_PAIR_T, Sequence[Sequence[np.ndarray]]]
    ),
    cycle_depths: Sequence[int],
    pairs: Sequence[_QUBIT_PAIR_T],
    num_templates: int,
) -> _PROBABILITIES_DICT_T:
    cycle_depth_to_index: dict[int, int]
    cycle_depth_to_index = {d: i for i, d in enumerate(cycle_depths)}
    if isinstance(simulation_results, Mapping):
        pure_probabilities = {
            pair: [[np.empty(0)] * num_templates for _ in range(len(cycle_depths))]
            for pair in pairs
        }
        for pair, simulation_result_for_pair in simulation_results.items():
            for template_idx, template_simulation_result in enumerate(simulation_result_for_pair):
                for cycle_depth, pure_probs in zip(
                    cycle_depths, template_simulation_result, strict=True
                ):
                    cycle_idx = cycle_depth_to_index[cycle_depth]
                    pure_probabilities[pair][cycle_idx][template_idx] = pure_probs
        return pure_probabilities
    else:
        common_pure_probs = [[np.empty(0)] * num_templates for _ in range(len(cycle_depths))]
        for template_idx, template_simulation_result in enumerate(simulation_results):
            for cycle_depth, pure_probs in zip(
                cycle_depths, template_simulation_result, strict=True
            ):
                cycle_idx = cycle_depth_to_index[cycle_depth]
                common_pure_probs[cycle_idx][template_idx] = pure_probs
        return {pair: common_pure_probs for pair in pairs}
@attrs.frozen
class XEBFidelity:
    pair: _QUBIT_PAIR_T
    cycle_depth: int
    fidelity: float
def _cross_entropy(p: np.ndarray, q: np.ndarray, eps: float = 1e-60) -> float:
    q[q <= 0] = eps  # for numerical stability
    return -np.dot(p, np.log2(q))
def estimate_fidelities(
    sampling_results: Sequence[dict[str, np.ndarray]],
    simulation_results: (
        Sequence[Sequence[np.ndarray]] | Mapping[_QUBIT_PAIR_T, Sequence[Sequence[np.ndarray]]]
    ),
    cycle_depths: Sequence[int],
    wide_circuits_info: Sequence[XEBWideCircuitInfo],
    pairs: Sequence[_QUBIT_PAIR_T],
    num_templates: int,
) -> Sequence[XEBFidelity]:
    sampled_probabilities = _reshape_sampling_results(
        sampling_results, cycle_depths, wide_circuits_info, pairs, num_templates
    )
    pure_probabilities = _reshape_simulation_results(
        simulation_results, cycle_depths, pairs, num_templates
    )
    records = []
    for pair in pairs:
        for depth_idx, cycle_depth in enumerate(cycle_depths):
            numerator = 0.0
            denominator = 0.0
            for template_idx in range(num_templates):
                pure_probs = pure_probabilities[pair][depth_idx][template_idx]
                sampled_probs = sampled_probabilities[pair][depth_idx][template_idx]
                if len(sampled_probs) == 0:
                    continue
                assert (
                    len(sampled_probs) == 4
                ), f'{pair=} {cycle_depth=} {template_idx=}: {sampled_probs=}'
                p_uniform = np.ones_like(pure_probs) / len(pure_probs)
                pure_probs /= pure_probs.sum()
                sampled_probs /= sampled_probs.sum()
                h_up = _cross_entropy(p_uniform, pure_probs)  # H[uniform, pure probs]
                h_sp = _cross_entropy(sampled_probs, pure_probs)  # H[sampled probs, pure probs]
                h_pp = _cross_entropy(pure_probs, pure_probs)  # H[pure probs]
                y = h_up - h_sp
                x = h_up - h_pp
                numerator += x * y
                denominator += x**2
            fidelity = numerator / denominator
            records.append(XEBFidelity(pair=pair, cycle_depth=cycle_depth, fidelity=fidelity))
    return records
def _extract_pairs(
    sampler: cirq.Sampler,
    target: _TARGET_T | Mapping[_QUBIT_PAIR_T, _TARGET_T],
    qubits: Sequence[cirq.GridQubit] | None,
    pairs: Sequence[_QUBIT_PAIR_T] | None,
) -> Sequence[_QUBIT_PAIR_T]:
    if isinstance(target, dict):
        if pairs is None:
            pairs = tuple(target.keys())
        else:
            assert target.keys() == set(pairs)
    qubits, device_pairs = tqxeb.qubits_and_pairs(sampler, qubits, pairs)
    device_pairs = [_canonize_pair(pair) for pair in device_pairs]
    if pairs is None:
        return device_pairs
    else:
        pairs = [_canonize_pair(p) for p in pairs]
        return tuple(set(pairs) & set(device_pairs))
def parallel_xeb_workflow(
    sampler: cirq.Sampler,
    target: _TARGET_T | Mapping[_QUBIT_PAIR_T, _TARGET_T],
    ideal_target: _TARGET_T | Mapping[_QUBIT_PAIR_T, _TARGET_T] | None = None,
    qubits: Sequence[cirq.GridQubit] | None = None,
    pairs: Sequence[_QUBIT_PAIR_T] | None = None,
    parameters: XEBParameters = XEBParameters(),
    rng: np.random.Generator | None = None,
    pool: futures.Executor | None = None,
) -> Sequence[XEBFidelity]:
    if rng is None:
        rng = np.random.default_rng()
    rs = np.random.RandomState(rng.integers(0, 10**9))
    pairs = _extract_pairs(sampler, target, qubits, pairs)
    graph = nx.Graph(pairs)
    circuit_templates = rqcg.generate_library_of_2q_circuits(
        n_library_circuits=parameters.n_circuits,
        random_state=rs,
        two_qubit_gate=ops.CZ,
        max_cycle_depth=max(parameters.cycle_depths),
    )
    combs_by_layer = rqcg.get_random_combinations_for_device(
        n_library_circuits=len(circuit_templates),
        n_combinations=parameters.n_combinations,
        device_graph=graph,
        random_state=rs,
    )
    canonical_target = _canonize_target(target)
    if ideal_target is None:
        canonical_ideal_target = canonical_target
    else:
        canonical_ideal_target = _canonize_target(ideal_target)
    if isinstance(canonical_target, dict):
        assert all(
            all(pair in canonical_target for pair in layer_comb.pairs)
            for layer_comb in combs_by_layer
        )
    if isinstance(canonical_ideal_target, dict):
        assert all(
            all(pair in canonical_ideal_target for pair in layer_comb.pairs)
            for layer_comb in combs_by_layer
        )
    wide_circuits_info = create_combination_circuits(
        circuit_templates, combs_by_layer, canonical_target
    )
    wide_circuits_info = [
        info_with_depth
        for info in wide_circuits_info
        for info_with_depth in info.sliced_circuits(parameters.cycle_depths)
    ]
    sampling_results = sample_all_circuits(
        sampler, [info.wide_circuit for info in wide_circuits_info], parameters.n_repetitions
    )
    simulation_results = simulate_circuit_library(
        circuit_templates, canonical_ideal_target, parameters.cycle_depths, pool
    )
    estimated_fidelities = estimate_fidelities(
        sampling_results,
        simulation_results,
        parameters.cycle_depths,
        wide_circuits_info,
        pairs,
        parameters.n_circuits,
    )
    return estimated_fidelities
def parallel_two_qubit_xeb(
    sampler: cirq.Sampler,
    target: _TARGET_T | Mapping[_QUBIT_PAIR_T, _TARGET_T],
    ideal_target: _TARGET_T | Mapping[_QUBIT_PAIR_T, _TARGET_T] | None = None,
    qubits: Sequence[cirq.GridQubit] | None = None,
    pairs: Sequence[_QUBIT_PAIR_T] | None = None,
    parameters: XEBParameters = XEBParameters(),
    rng: np.random.Generator | None = None,
    pool: futures.Executor | None = None,
) -> tqxeb.TwoQubitXEBResult:
    estimated_fidelities = parallel_xeb_workflow(
        sampler, target, ideal_target, qubits, pairs, parameters, rng, pool
    )
    df = pd.DataFrame.from_records([attrs.asdict(ef) for ef in estimated_fidelities])
    return tqxeb.TwoQubitXEBResult(xeb_fitting.fit_exponential_decays(df))

from __future__ import annotations
import enum
import itertools
from collections.abc import Iterator, Sequence
from typing import TYPE_CHECKING
from cirq import ops
from cirq.contrib.acquaintance.gates import acquaint
from cirq.contrib.acquaintance.permutation import PermutationGate, SwapPermutationGate
if TYPE_CHECKING:
    import cirq
@enum.unique
class BipartiteGraphType(enum.Enum):
    MATCHING = 1
    COMPLETE = 2
    def __repr__(self) -> str:
        return 'cirq.contrib.acquaintance.bipartite.BipartiteGraphType.' + self.name
class BipartiteSwapNetworkGate(PermutationGate):
    def __init__(
        self, subgraph: str | BipartiteGraphType, part_size: int, swap_gate: cirq.Gate = ops.SWAP
    ) -> None:
        super().__init__(2 * part_size, swap_gate)
        self.part_size = part_size
        self.subgraph = (
            subgraph if isinstance(subgraph, BipartiteGraphType) else BipartiteGraphType[subgraph]
        )
        self.swap_gate = swap_gate
    def decompose_complete(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        swap_gate = SwapPermutationGate(self.swap_gate)
        if self.part_size == 1:
            yield acquaint(*qubits)
            return
        for k in range(-self.part_size + 1, self.part_size - 1):
            for x in range(abs(k), 2 * self.part_size - abs(k), 2):
                yield acquaint(*qubits[x : x + 2])
                yield swap_gate(*qubits[x : x + 2])
        yield acquaint(qubits[self.part_size - 1], qubits[self.part_size])
        for k in reversed(range(-self.part_size + 1, self.part_size - 1)):
            for x in range(abs(k), 2 * self.part_size - abs(k), 2):
                yield acquaint(*qubits[x : x + 2])
                yield swap_gate(*qubits[x : x + 2])
    def decompose_matching(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        swap_gate = SwapPermutationGate(self.swap_gate)
        for k in range(-self.part_size + 1, self.part_size):
            for x in range(abs(k), 2 * self.part_size - abs(k), 2):
                if (x + 1) % self.part_size:
                    yield swap_gate(*qubits[x : x + 2])
                else:
                    yield acquaint(*qubits[x : x + 2])
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> cirq.OP_TREE:
        if len(qubits) != 2 * self.part_size:
            raise ValueError('len(qubits) != 2 * self.part_size')
        if self.subgraph == BipartiteGraphType.COMPLETE:
            return self.decompose_complete(qubits)
        if self.subgraph == BipartiteGraphType.MATCHING:
            return self.decompose_matching(qubits)
        raise NotImplementedError('No decomposition implemented for ' + str(self.subgraph))
    def permutation(self) -> dict[int, int]:
        if self.num_qubits() != 2 * self.part_size:
            raise ValueError('qubit_count != 2 * self.part_size')
        if self.subgraph == BipartiteGraphType.MATCHING:
            return dict(
                enumerate(
                    itertools.chain(
                        *(
                            range(self.part_size + offset - 1, offset - 1, -1)
                            for offset in (0, self.part_size)
                        )
                    )
                )
            )
        if self.subgraph == BipartiteGraphType.COMPLETE:
            return dict(enumerate(range(2 * self.part_size)))
        raise NotImplementedError(str(self.subgraph) + 'not implemented')
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> tuple[str, ...]:
        qubit_count = 2 * self.part_size
        if args.known_qubit_count not in (None, qubit_count):
            raise ValueError('args.known_qubit_count not in (None, 2 * self.part_size)')
        partial_permutation = self.permutation()
        permutation = {i: partial_permutation.get(i, i) for i in range(qubit_count)}
        if self.subgraph == BipartiteGraphType.MATCHING:
            name = 'Matching'
        elif self.subgraph == BipartiteGraphType.COMPLETE:
            name = f'K_{{{self.part_size}, {self.part_size}}}'
        arrow = '↦' if args.use_unicode_characters else '->'
        wire_symbols = tuple(
            name
            + ':'
            + str((i // self.part_size, i % self.part_size))
            + arrow
            + str((j // self.part_size, j % self.part_size))
            for i, j in permutation.items()
        )
        return wire_symbols
    def __repr__(self) -> str:
        args: tuple[str, ...] = (repr(self.subgraph), repr(self.part_size))
        if self.swap_gate != ops.SWAP:
            args += (repr(self.swap_gate),)
        args_str = ', '.join(args)
        return f'cirq.contrib.acquaintance.bipartite.BipartiteSwapNetworkGate({args_str})'
    def __eq__(self, other) -> bool:
        return (
            isinstance(other, self.__class__)
            and self.subgraph == other.subgraph
            and self.part_size == other.part_size
            and self.swap_gate == other.swap_gate
        )

from __future__ import annotations
import abc
from typing import TYPE_CHECKING
from cirq import circuits, devices, ops
from cirq.contrib.acquaintance.bipartite import BipartiteSwapNetworkGate
from cirq.contrib.acquaintance.gates import AcquaintanceOpportunityGate, SwapNetworkGate
from cirq.contrib.acquaintance.permutation import PermutationGate
from cirq.contrib.acquaintance.shift_swap_network import ShiftSwapNetworkGate
if TYPE_CHECKING:
    import cirq
class AcquaintanceDevice(devices.Device, metaclass=abc.ABCMeta):
    gate_types = (AcquaintanceOpportunityGate, PermutationGate)
    def validate_operation(self, operation: cirq.Operation) -> None:
        if not (
            isinstance(operation, ops.GateOperation) and isinstance(operation.gate, self.gate_types)
        ):
            raise ValueError(
                f'not (isinstance({operation!r}, {ops.Operation!r}) and '
                f'ininstance({operation!r}.gate, {self.gate_types!r})'
            )
def get_acquaintance_size(obj: circuits.Circuit | ops.Operation) -> int:
    if isinstance(obj, circuits.Circuit):
        return max((get_acquaintance_size(op) for op in obj.all_operations()), default=0)
    if not isinstance(obj, ops.Operation):
        raise TypeError('not isinstance(obj, (Circuit, Operation))')
    if not isinstance(obj, ops.GateOperation):
        return 0
    if isinstance(obj.gate, AcquaintanceOpportunityGate):
        return len(obj.qubits)
    if isinstance(obj.gate, BipartiteSwapNetworkGate):
        return 2
    if isinstance(obj.gate, ShiftSwapNetworkGate):
        return obj.gate.acquaintance_size()
    if isinstance(obj.gate, SwapNetworkGate):
        if obj.gate.acquaintance_size is None:
            return sum(sorted(obj.gate.part_lens)[-2:])
        if (obj.gate.acquaintance_size - 1) in obj.gate.part_lens:
            return obj.gate.acquaintance_size
    sizer = getattr(obj.gate, '_acquaintance_size_', None)
    return 0 if sizer is None else sizer(len(obj.qubits))
class _UnconstrainedAcquaintanceDevice(AcquaintanceDevice):
    def __repr__(self) -> str:
        return 'UnconstrainedAcquaintanceDevice'  # pragma: no cover
UnconstrainedAcquaintanceDevice = _UnconstrainedAcquaintanceDevice()

from __future__ import annotations
import abc
from collections import defaultdict
from collections.abc import Iterator, Sequence
from typing import TYPE_CHECKING
from cirq import circuits, devices, ops, protocols, transformers
from cirq.contrib.acquaintance.gates import AcquaintanceOpportunityGate
from cirq.contrib.acquaintance.mutation_utils import expose_acquaintance_gates
from cirq.contrib.acquaintance.permutation import (
    LogicalGates,
    LogicalIndex,
    LogicalIndexSequence,
    LogicalMapping,
    PermutationGate,
)
if TYPE_CHECKING:
    import cirq
class ExecutionStrategy(metaclass=abc.ABCMeta):
    keep_acquaintance = False
    @property
    @abc.abstractmethod
    def device(self) -> cirq.Device:
    @property
    @abc.abstractmethod
    def initial_mapping(self) -> LogicalMapping:
    @abc.abstractmethod
    def get_operations(
        self, indices: Sequence[LogicalIndex], qubits: Sequence[cirq.Qid]
    ) -> cirq.OP_TREE:
    def __call__(self, *args, **kwargs):
        if len(args) < 1 or not isinstance(args[0], circuits.AbstractCircuit):
            raise ValueError(
                "To call ExecutionStrategy, an argument of type "
                "circuits.AbstractCircuit must be passed in as the first non-keyword argument"
            )
        input_circuit = args[0]
        strategy = StrategyExecutorTransformer(self)
        final_circuit = strategy(input_circuit, **kwargs)
        input_circuit._moments = final_circuit._moments
        input_circuit._placement_cache = final_circuit._placement_cache
        return strategy.mapping
@transformers.transformer
class StrategyExecutorTransformer:
    def __init__(self, execution_strategy: ExecutionStrategy) -> None:
        if execution_strategy is None:
            raise ValueError('execution_strategy cannot be None')
        self.execution_strategy = execution_strategy
        self._mapping = execution_strategy.initial_mapping.copy()
    def __call__(
        self, circuit: circuits.AbstractCircuit, context: cirq.TransformerContext | None = None
    ) -> circuits.Circuit:
        circuit = transformers.expand_composite(
            circuit, no_decomp=expose_acquaintance_gates.no_decomp
        )
        return transformers.map_operations_and_unroll(
            circuit=circuit,
            map_func=self._map_func,
            deep=context.deep if context else False,
            tags_to_ignore=context.tags_to_ignore if context else (),
        ).unfreeze(copy=False)
    @property
    def mapping(self) -> LogicalMapping:
        return self._mapping
    def _map_func(self, op: cirq.Operation, index) -> cirq.OP_TREE:
        if isinstance(op.gate, AcquaintanceOpportunityGate):
            logical_indices = tuple(self._mapping[q] for q in op.qubits)
            logical_operations = self.execution_strategy.get_operations(logical_indices, op.qubits)
            clear_span = int(not self.execution_strategy.keep_acquaintance)
            return logical_operations if clear_span else [op, logical_operations]
        if isinstance(op.gate, PermutationGate):
            op.gate.update_mapping(self._mapping, op.qubits)
            return op
        raise TypeError(
            'Can only execute a strategy consisting of gates that '
            'are instances of AcquaintanceOpportunityGate or '
            'PermutationGate.'
        )
class AcquaintanceOperation(ops.GateOperation):
    def __init__(self, qubits: Sequence[cirq.Qid], logical_indices: Sequence[LogicalIndex]) -> None:
        if len(logical_indices) != len(qubits):
            raise ValueError('len(logical_indices) != len(qubits)')
        super().__init__(AcquaintanceOpportunityGate(num_qubits=len(qubits)), qubits)
        self.logical_indices: LogicalIndexSequence = logical_indices
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        wire_symbols = tuple(f'({i})' for i in self.logical_indices)
        return protocols.CircuitDiagramInfo(wire_symbols=wire_symbols)
class GreedyExecutionStrategy(ExecutionStrategy):
    def __init__(
        self,
        gates: LogicalGates,
        initial_mapping: LogicalMapping,
        device: cirq.Device | None = None,
    ) -> None:
        if len(set(len(indices) for indices in gates)) > 1:
            raise NotImplementedError(
                'Can only implement greedy strategy if all gates are of the same arity.'
            )
        self.index_set_to_gates = self.canonicalize_gates(gates)
        self._initial_mapping = initial_mapping.copy()
        self._device = device or devices.UNCONSTRAINED_DEVICE
    @property
    def initial_mapping(self) -> LogicalMapping:
        return self._initial_mapping
    @property
    def device(self) -> cirq.Device:
        return self._device
    def get_operations(
        self, indices: Sequence[LogicalIndex], qubits: Sequence[cirq.Qid]
    ) -> Iterator[cirq.OP_TREE]:
        index_set = frozenset(indices)
        if index_set in self.index_set_to_gates:
            gates = self.index_set_to_gates.pop(index_set)
            index_to_qubit = dict(zip(indices, qubits))
            for gate_indices, gate in sorted(gates.items()):
                yield gate(*[index_to_qubit[i] for i in gate_indices])
    @staticmethod
    def canonicalize_gates(gates: LogicalGates) -> dict[frozenset, LogicalGates]:
        canonicalized_gates: defaultdict[frozenset, LogicalGates] = defaultdict(dict)
        for indices, gate in gates.items():
            indices = tuple(indices)
            canonicalized_gates[frozenset(indices)][indices] = gate
        return {
            canonical_indices: dict(list(gates.items()))
            for canonical_indices, gates in canonicalized_gates.items()
        }

from __future__ import annotations
from collections.abc import Sequence
from itertools import combinations
from string import ascii_lowercase
from typing import Any
import numpy as np
import pytest
import cirq
import cirq.contrib.acquaintance as cca
import cirq.testing as ct
class ExampleGate(cirq.Gate):
    def __init__(self, wire_symbols: Sequence[str]) -> None:
        self._num_qubits = len(wire_symbols)
        self._wire_symbols = tuple(wire_symbols)
    def num_qubits(self) -> int:
        return self._num_qubits
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs):
        return self._wire_symbols
def test_executor_explicit() -> None:
    num_qubits = 8
    qubits = cirq.LineQubit.range(num_qubits)
    circuit = cca.complete_acquaintance_strategy(qubits, 2)
    gates: dict[tuple[Any, ...], cirq.Gate]
    gates = {
        (i, j): ExampleGate([str(k) for k in ij])
        for ij in combinations(range(num_qubits), 2)
        for i, j in (ij, ij[::-1])
    }
    initial_mapping = {q: i for i, q in enumerate(sorted(qubits))}
    execution_strategy = cca.GreedyExecutionStrategy(gates, initial_mapping)
    assert execution_strategy.device == cirq.UNCONSTRAINED_DEVICE
    with pytest.raises(ValueError):
        executor = cca.StrategyExecutorTransformer(None)  # type: ignore[arg-type]
    executor = cca.StrategyExecutorTransformer(execution_strategy)
    with pytest.raises(NotImplementedError):
        bad_gates: dict[tuple[Any, ...], cirq.Gate]
        bad_gates = {(0,): ExampleGate(['0']), (0, 1): ExampleGate(['0', '1'])}
        cca.GreedyExecutionStrategy(bad_gates, initial_mapping)
    with pytest.raises(TypeError):
        bad_strategy = cirq.Circuit(cirq.X(qubits[0]))
        executor(bad_strategy)
    circuit = executor(circuit)
    expected_text_diagram = .strip()  # noqa: E501
    ct.assert_has_diagram(circuit, expected_text_diagram)
def random_diagonal_gates(
    num_qubits: int, acquaintance_size: int
) -> dict[tuple[cirq.Qid, ...], cirq.Gate]:
    return {
        Q: cirq.DiagonalGate(np.random.random(2**acquaintance_size))
        for Q in combinations(cirq.LineQubit.range(num_qubits), acquaintance_size)
    }
@pytest.mark.parametrize(
    'num_qubits, acquaintance_size, gates',
    [
        (num_qubits, acquaintance_size, random_diagonal_gates(num_qubits, acquaintance_size))
        for acquaintance_size, num_qubits in (
            [(2, n) for n in range(2, 9)] + [(3, n) for n in range(3, 8)] + [(4, 4), (4, 6), (5, 5)]
        )
        for _ in range(2)
    ],
)
def test_executor_random(
    num_qubits: int, acquaintance_size: int, gates: dict[tuple[cirq.Qid, ...], cirq.Gate]
) -> None:
    qubits = cirq.LineQubit.range(num_qubits)
    circuit = cca.complete_acquaintance_strategy(qubits, acquaintance_size)
    logical_circuit = cirq.Circuit([g(*Q) for Q, g in gates.items()])
    expected_unitary = logical_circuit.unitary()
    initial_mapping = {q: q for q in qubits}
    with pytest.raises(ValueError):
        cca.GreedyExecutionStrategy(gates, initial_mapping)()
    final_mapping = cca.GreedyExecutionStrategy(gates, initial_mapping)(circuit)
    permutation = {q.x: qq.x for q, qq in final_mapping.items()}
    circuit.append(cca.LinearPermutationGate(num_qubits, permutation)(*qubits))
    actual_unitary = circuit.unitary()
    np.testing.assert_allclose(actual=actual_unitary, desired=expected_unitary, verbose=True)
def test_acquaintance_operation() -> None:
    n = 5
    physical_qubits = tuple(cirq.LineQubit.range(n))
    logical_qubits = tuple(cirq.NamedQubit(s) for s in ascii_lowercase[:n])
    int_indices = tuple(range(n))
    with pytest.raises(ValueError):
        cca.AcquaintanceOperation(physical_qubits[:3], int_indices[:4])
    for logical_indices in (logical_qubits, int_indices):
        op = cca.AcquaintanceOperation(physical_qubits, logical_indices)  # type: ignore[type-var]
        assert op.logical_indices == logical_indices
        assert op.qubits == physical_qubits
        wire_symbols = tuple(f'({i})' for i in logical_indices)
        assert cirq.circuit_diagram_info(op) == cirq.CircuitDiagramInfo(wire_symbols=wire_symbols)

from __future__ import annotations
import functools
import itertools
import math
import operator
from collections.abc import Iterable, Iterator, Sequence
from typing import NamedTuple, TYPE_CHECKING
from cirq import ops, protocols, value
from cirq.contrib.acquaintance.permutation import (
    LinearPermutationGate,
    PermutationGate,
    SwapPermutationGate,
)
from cirq.contrib.acquaintance.shift import CircularShiftGate
if TYPE_CHECKING:
    import cirq
def operations_to_part_lens(
    qubit_order: Sequence[cirq.Qid], op_tree: cirq.OP_TREE
) -> tuple[int, ...]:
    qubit_sort_key = functools.partial(operator.indexOf, qubit_order)
    op_parts = [tuple(sorted(op.qubits, key=qubit_sort_key)) for op in ops.flatten_op_tree(op_tree)]
    singletons: list[tuple[cirq.Qid, ...]] = [(q,) for q in set(qubit_order).difference(*op_parts)]
    part_sort_key = lambda p: min(qubit_sort_key(q) for q in p)
    parts = tuple(tuple(part) for part in sorted(singletons + op_parts, key=part_sort_key))
    if tuple(itertools.chain.from_iterable(parts)) != tuple(qubit_order):
        raise ValueError('sum(parts, ()) != tuple(qubit_order)')
    return tuple(len(part) for part in parts)
class AcquaintanceOpportunityGate(ops.Gate, ops.InterchangeableQubitsGate):
    def __init__(self, num_qubits: int):
        self._num_qubits = num_qubits
    def __repr__(self) -> str:
        return (
            'cirq.contrib.acquaintance.AcquaintanceOpportunityGate('
            f'num_qubits={self.num_qubits()!r})'
        )
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> Iterable[str]:
        wire_symbol = '█' if args.use_unicode_characters else 'Acq'
        wire_symbols = (wire_symbol,) * self.num_qubits()
        return wire_symbols
    def num_qubits(self) -> int:
        return self._num_qubits
def acquaint(*qubits) -> cirq.Operation:
    return AcquaintanceOpportunityGate(len(qubits)).on(*qubits)
Layers = NamedTuple(
    'Layers',
    [
        ('prior_interstitial', list['cirq.Operation']),
        ('pre', list['cirq.Operation']),
        ('intra', list['cirq.Operation']),
        ('post', list['cirq.Operation']),
        ('posterior_interstitial', list['cirq.Operation']),
    ],
)
def new_layers(**kwargs: list[cirq.Operation]) -> Layers:
    return Layers._make(kwargs.get(field, []) for field in Layers._fields)
def acquaint_insides(
    swap_gate: cirq.Gate,
    acquaintance_gate: cirq.Operation,
    qubits: Sequence[cirq.Qid],
    before: bool,
    layers: Layers,
    mapping: dict[ops.Qid, int],
) -> None:
    max_reach = _get_max_reach(len(qubits), round_up=before)
    reaches = itertools.chain(range(1, max_reach + 1), range(max_reach, -1, -1))
    offsets = (0, 1) * max_reach
    swap_gate = SwapPermutationGate(swap_gate)
    ops = []
    for offset, reach in zip(offsets, reaches):
        if offset == before:
            ops.append(acquaintance_gate)
        for dr in range(offset, reach, 2):
            ops.append(swap_gate(*qubits[dr : dr + 2]))
    intrastitial_layer = getattr(layers, 'pre' if before else 'post')
    intrastitial_layer += ops
    interstitial_layer = getattr(layers, ('prior' if before else 'posterior') + '_interstitial')
    interstitial_layer.append(acquaintance_gate)
    reached_qubits = qubits[: max_reach + 1]
    positions = list(mapping[q] for q in reached_qubits)
    mapping.update(zip(reached_qubits, reversed(positions)))
def _get_max_reach(size: int, round_up: bool = True) -> int:
    if round_up:
        return int(math.ceil(size / 2)) - 1
    return max((size // 2) - 1, 0)
def acquaint_and_shift(
    parts: tuple[list[cirq.Qid], list[cirq.Qid]],
    layers: Layers,
    acquaintance_size: int | None,
    swap_gate: cirq.Gate,
    mapping: dict[ops.Qid, int],
) -> None:
    left_part, right_part = parts
    left_size, right_size = len(left_part), len(right_part)
    assert not (set(left_part) & set(right_part))
    qubits = left_part + right_part
    shift = CircularShiftGate(len(qubits), left_size, swap_gate=swap_gate)(*qubits)
    if acquaintance_size is None:
        layers.intra.append(shift)
        layers.post.append(acquaint(*qubits))
        shift.gate.update_mapping(mapping, qubits)
    elif max(left_size, right_size) != acquaintance_size - 1:
        layers.intra.append(shift)
        shift.gate.update_mapping(mapping, qubits)
    elif acquaintance_size == 2:
        layers.prior_interstitial.append(acquaint(*qubits))
        layers.intra.append(shift)
        shift.gate.update_mapping(mapping, qubits)
    else:
        if left_size == acquaintance_size - 1:
            pre_acquaintance_gate = acquaint(*qubits[:acquaintance_size])
            acquaint_insides(
                swap_gate=swap_gate,
                acquaintance_gate=pre_acquaintance_gate,
                qubits=right_part,
                before=True,
                layers=layers,
                mapping=mapping,
            )
        if right_size == acquaintance_size - 1:
            pre_acquaintance_gate = acquaint(*qubits[-acquaintance_size:])
            acquaint_insides(
                swap_gate=swap_gate,
                acquaintance_gate=pre_acquaintance_gate,
                qubits=left_part[::-1],
                before=True,
                layers=layers,
                mapping=mapping,
            )
        layers.intra.append(shift)
        shift.gate.update_mapping(mapping, qubits)
        if (left_size == acquaintance_size - 1) and (right_size > 1):
            post_acquaintance_gate = acquaint(*qubits[-acquaintance_size:])
            new_left_part = qubits[right_size - 1 :: -1]
            acquaint_insides(
                swap_gate=swap_gate,
                acquaintance_gate=post_acquaintance_gate,
                qubits=new_left_part,
                before=False,
                layers=layers,
                mapping=mapping,
            )
        if (right_size == acquaintance_size - 1) and (left_size > 1):
            post_acquaintance_gate = acquaint(*qubits[:acquaintance_size])
            acquaint_insides(
                swap_gate=swap_gate,
                acquaintance_gate=post_acquaintance_gate,
                qubits=qubits[right_size:],
                before=False,
                layers=layers,
                mapping=mapping,
            )
@value.value_equality
class SwapNetworkGate(PermutationGate):
    def __init__(
        self,
        part_lens: Sequence[int],
        acquaintance_size: int | None = 0,
        swap_gate: cirq.Gate = ops.SWAP,
    ) -> None:
        super().__init__(sum(part_lens), swap_gate)
        if len(part_lens) < 2:
            raise ValueError('len(part_lens) < 2.')
        self.part_lens = tuple(part_lens)
        self.acquaintance_size = acquaintance_size
    def _decompose_(self, qubits: Sequence[cirq.Qid]) -> Iterator[cirq.OP_TREE]:
        qubit_to_position = {q: i for i, q in enumerate(qubits)}
        mapping = dict(qubit_to_position)
        parts = []
        n_qubits = 0
        for part_len in self.part_lens:
            parts.append(list(qubits[n_qubits : n_qubits + part_len]))
            n_qubits += part_len
        n_parts = len(parts)
        op_sort_key = (
            None
            if self.acquaintance_size is None
            else (lambda op: min(qubit_to_position[q] for q in op.qubits) % self.acquaintance_size)
        )
        layers = new_layers()
        for layer_num in range(n_parts):
            layers = new_layers(prior_interstitial=layers.posterior_interstitial)
            for i in range(layer_num % 2, n_parts - 1, 2):
                left_part, right_part = parts[i : i + 2]
                acquaint_and_shift(
                    parts=(left_part, right_part),
                    layers=layers,
                    acquaintance_size=self.acquaintance_size,
                    swap_gate=self.swap_gate,
                    mapping=mapping,
                )
                parts_qubits = list(left_part + right_part)
                parts[i] = parts_qubits[: len(right_part)]
                parts[i + 1] = parts_qubits[len(right_part) :]
            if op_sort_key is not None:
                layers.prior_interstitial.sort(key=op_sort_key)
            for l in ('prior_interstitial', 'pre', 'intra', 'post'):
                yield getattr(layers, l)
        if op_sort_key is not None:
            layers.posterior_interstitial.sort(key=op_sort_key)
        yield layers.posterior_interstitial
        assert list(
            itertools.chain(*(sorted(mapping[q] for q in part) for part in reversed(parts)))
        ) == list(range(n_qubits))
        final_permutation = {i: n_qubits - 1 - mapping[q] for i, q in enumerate(qubits)}
        final_gate = LinearPermutationGate(n_qubits, final_permutation, self.swap_gate)
        if final_gate:
            yield final_gate(*qubits)
    def _circuit_diagram_info_(self, args: cirq.CircuitDiagramInfoArgs) -> cirq.CircuitDiagramInfo:
        wire_symbol = '×' if args.use_unicode_characters else 'swap'
        wire_symbols = tuple(
            wire_symbol + f'({part_index},{qubit_index})'
            for part_index, part_len in enumerate(self.part_lens)
            for qubit_index in range(part_len)
        )
        return protocols.CircuitDiagramInfo(wire_symbols=wire_symbols)
    @staticmethod
    def from_operations(
        qubit_order: Sequence[cirq.Qid],
        operations: Sequence[cirq.Operation],
        acquaintance_size: int | None = 0,
        swap_gate: cirq.Gate = ops.SWAP,
    ) -> SwapNetworkGate:
        part_sizes = operations_to_part_lens(qubit_order, operations)
        return SwapNetworkGate(part_sizes, acquaintance_size, swap_gate)
    def permutation(self) -> dict[int, int]:
        return {i: j for i, j in enumerate(reversed(range(sum(self.part_lens))))}
    def __repr__(self) -> str:
        return (
            'cirq.contrib.acquaintance.SwapNetworkGate('
            f'{self.part_lens!r}, {self.acquaintance_size!r})'
        )
    def _value_equality_values_(self):
        return (self.part_lens, self.acquaintance_size, self.swap_gate)

