from __future__ import annotations
from typing import cast
from cirq import circuits, ops, protocols, transformers
from cirq.contrib.paulistring.clifford_target_gateset import CliffordTargetGateset
def clifford_optimized_circuit(circuit: circuits.Circuit, atol: float = 1e-8) -> circuits.Circuit:
    c_cliff = transformers.optimize_for_target_gateset(
        circuit, gateset=CliffordTargetGateset(atol=atol)
    )
    all_ops = list(c_cliff.all_operations())
    def find_merge_point(
        start_i: int, string_op: ops.PauliStringPhasor, stop_at_cz: bool
    ) -> tuple[int, ops.PauliStringPhasor, int]:
        STOP = 0
        CONTINUE = 1
        SKIP = 2
        def continue_condition(
            op: ops.Operation, current_string: ops.PauliStringPhasor, is_first: bool
        ) -> int:
            if isinstance(op.gate, ops.SingleQubitCliffordGate):
                return CONTINUE if len(current_string.pauli_string) != 1 else STOP
            if isinstance(op.gate, ops.CZPowGate):
                return STOP if stop_at_cz else CONTINUE
            if (
                isinstance(op, ops.PauliStringPhasor)
                and len(op.qubits) == 1
                and (op.pauli_string[op.qubits[0]] == current_string.pauli_string[op.qubits[0]])
            ):
                return SKIP
            return STOP
        modified_op = string_op
        furthest_op = string_op
        furthest_i = start_i + 1
        num_passed_over = 0
        for i in range(start_i + 1, len(all_ops)):
            op = all_ops[i]
            if not set(op.qubits) & set(modified_op.qubits):
                continue
            cont_cond = continue_condition(op, modified_op, i == start_i + 1)
            if cont_cond == STOP:
                if len(modified_op.pauli_string) == 1:
                    furthest_op = modified_op
                    furthest_i = i
                break
            if cont_cond == CONTINUE:
                modified_op = modified_op.conjugated_by(protocols.inverse(op))
            num_passed_over += 1
            if len(modified_op.pauli_string) == 1:
                furthest_op = modified_op
                furthest_i = i + 1
        return furthest_i, furthest_op, num_passed_over
    def try_merge_clifford(cliff_op: ops.GateOperation, start_i: int) -> bool:
        (orig_qubit,) = cliff_op.qubits
        remaining_cliff_gate = ops.SingleQubitCliffordGate.I
        for pauli, quarter_turns in reversed(
            cast(ops.SingleQubitCliffordGate, cliff_op.gate).decompose_rotation()
        ):
            trans = remaining_cliff_gate.pauli_tuple(pauli)
            pauli = trans[0]
            quarter_turns *= -1 if trans[1] else 1
            string_op = ops.PauliStringPhasor(
                ops.PauliString(pauli(cliff_op.qubits[0])), exponent_neg=quarter_turns / 2
            )
            merge_i, merge_op, num_passed = find_merge_point(start_i, string_op, quarter_turns == 2)
            assert merge_i > start_i
            assert len(merge_op.pauli_string) == 1, 'PauliString length != 1'
            assert not protocols.is_parameterized(merge_op.pauli_string)
            coefficient = merge_op.pauli_string.coefficient
            assert isinstance(coefficient, complex)
            qubit, pauli = next(iter(merge_op.pauli_string.items()))
            quarter_turns = round(merge_op.exponent_relative * 2)
            quarter_turns *= int(coefficient.real)
            quarter_turns %= 4
            part_cliff_gate = ops.SingleQubitCliffordGate.from_quarter_turns(pauli, quarter_turns)
            other_op = all_ops[merge_i] if merge_i < len(all_ops) else None
            if other_op is not None and qubit not in set(other_op.qubits):
                other_op = None
            if isinstance(other_op, ops.GateOperation) and isinstance(
                other_op.gate, ops.SingleQubitCliffordGate
            ):
                new_op = part_cliff_gate.merged_with(other_op.gate)(qubit)
                all_ops[merge_i] = new_op
            elif (
                isinstance(other_op, ops.GateOperation)
                and isinstance(other_op.gate, ops.CZPowGate)
                and other_op.gate.exponent == 1
                and quarter_turns == 2
            ):
                if pauli != ops.pauli_gates.Z:
                    other_qubit = other_op.qubits[other_op.qubits.index(qubit) - 1]
                    all_ops.insert(merge_i + 1, ops.SingleQubitCliffordGate.Z(other_qubit))
                all_ops.insert(merge_i + 1, part_cliff_gate(qubit))
            elif isinstance(other_op, ops.PauliStringPhasor):
                mod_op = other_op.conjugated_by([part_cliff_gate(qubit)])
                all_ops[merge_i] = mod_op
                all_ops.insert(merge_i + 1, part_cliff_gate(qubit))
            elif merge_i > start_i + 1 and num_passed > 0:
                all_ops.insert(merge_i, part_cliff_gate(qubit))
            else:
                remaining_cliff_gate = remaining_cliff_gate.merged_with(part_cliff_gate)
        if remaining_cliff_gate == ops.SingleQubitCliffordGate.I:
            all_ops.pop(start_i)
            return True
        all_ops[start_i] = remaining_cliff_gate(orig_qubit)
        return False
    def try_merge_cz(cz_op: ops.GateOperation, start_i: int) -> int:
        for i in reversed(range(start_i)):
            op = all_ops[i]
            if not set(cz_op.qubits) & set(op.qubits):
                continue
            elif not (
                isinstance(op, ops.GateOperation)
                and isinstance(op.gate, ops.CZPowGate)
                and op.gate.exponent == 1
            ):
                return 0
            elif cz_op == op:
                all_ops.pop(start_i)
                all_ops.pop(i)
                return 2
            else:
                continue  # pragma: no cover
        return 0
    i = 0
    while i < len(all_ops):
        op = all_ops[i]
        if isinstance(op, ops.GateOperation) and isinstance(op.gate, ops.SingleQubitCliffordGate):
            if try_merge_clifford(op, i):
                i -= 1
        elif (
            isinstance(op, ops.GateOperation)
            and isinstance(op.gate, ops.CZPowGate)
            and op.gate.exponent == 1
        ):
            num_rm = try_merge_cz(op, i)
            i -= num_rm
        i += 1
    return circuits.Circuit(all_ops, strategy=circuits.InsertStrategy.EARLIEST)

from __future__ import annotations
from enum import Enum
from types import NotImplementedType
from typing import cast, TYPE_CHECKING
from cirq import linalg, ops, protocols, transformers
if TYPE_CHECKING:
    import numpy as np
    import cirq
def _matrix_to_clifford_op(
    mat: np.ndarray, qubit: cirq.Qid, *, atol: float
) -> ops.Operation | NotImplementedType:
    rotations = transformers.single_qubit_matrix_to_pauli_rotations(mat, atol)
    clifford_gate = ops.SingleQubitCliffordGate.I
    for pauli, half_turns in rotations:
        if linalg.all_near_zero_mod(half_turns, 0.5):
            quarter_turns = round(half_turns * 2) % 4
            clifford_gate = clifford_gate.merged_with(
                ops.SingleQubitCliffordGate.from_pauli(pauli, sqrt=bool(quarter_turns % 2))
                ** (1 - 2 * int(quarter_turns == 3))
            )
        else:
            return NotImplemented
    return clifford_gate(qubit)
def _matrix_to_pauli_string_phasors(
    mat: np.ndarray, qubit: cirq.Qid, *, keep_clifford: bool, atol: float
) -> ops.OP_TREE:
    rotations = transformers.single_qubit_matrix_to_pauli_rotations(mat, atol)
    out_ops: list[ops.GateOperation] = []
    for pauli, half_turns in rotations:
        if keep_clifford and linalg.all_near_zero_mod(half_turns, 0.5):
            cliff_gate = ops.SingleQubitCliffordGate.from_quarter_turns(
                pauli, round(half_turns * 2)
            )
            if out_ops and not isinstance(out_ops[-1], ops.PauliStringPhasor):
                gate = cast(ops.SingleQubitCliffordGate, out_ops[-1].gate)
                out_ops[-1] = gate.merged_with(cliff_gate)(qubit)
            else:
                out_ops.append(cliff_gate(qubit))
        else:
            out_ops.append(
                ops.PauliStringPhasor(
                    ops.PauliString(pauli.on(qubit)), exponent_neg=round(half_turns, 10)
                )
            )
    return out_ops
class CliffordTargetGateset(transformers.TwoQubitCompilationTargetGateset):
    class SingleQubitTarget(Enum):
        SINGLE_QUBIT_CLIFFORDS = 1
        PAULI_STRING_PHASORS_AND_CLIFFORDS = 2
        PAULI_STRING_PHASORS = 3
    def __init__(
        self,
        *,
        single_qubit_target: SingleQubitTarget = SingleQubitTarget.PAULI_STRING_PHASORS_AND_CLIFFORDS,  # noqa: E501
        atol: float = 1e-8,
    ):
        self.atol = atol
        self.single_qubit_target = single_qubit_target
        gates: list[cirq.Gate | type[cirq.Gate]] = [ops.CZ, ops.MeasurementGate]
        if single_qubit_target in [
            self.SingleQubitTarget.SINGLE_QUBIT_CLIFFORDS,
            self.SingleQubitTarget.PAULI_STRING_PHASORS_AND_CLIFFORDS,
        ]:
            gates.append(ops.SingleQubitCliffordGate)
        if single_qubit_target in [
            self.SingleQubitTarget.PAULI_STRING_PHASORS_AND_CLIFFORDS,
            self.SingleQubitTarget.PAULI_STRING_PHASORS,
        ]:
            gates.append(ops.PauliStringPhasorGate)
        super().__init__(*gates)
    def _decompose_single_qubit_operation(
        self, op: cirq.Operation, _
    ) -> NotImplementedType | cirq.OP_TREE:
        if not protocols.has_unitary(op):
            return NotImplemented
        mat = protocols.unitary(op)
        keep_clifford = (
            self.single_qubit_target == self.SingleQubitTarget.PAULI_STRING_PHASORS_AND_CLIFFORDS
        )
        return (
            _matrix_to_clifford_op(mat, op.qubits[0], atol=self.atol)
            if self.single_qubit_target == self.SingleQubitTarget.SINGLE_QUBIT_CLIFFORDS
            else _matrix_to_pauli_string_phasors(
                mat, op.qubits[0], keep_clifford=keep_clifford, atol=self.atol
            )
        )
    def _decompose_two_qubit_operation(
        self, op: cirq.Operation, _
    ) -> NotImplementedType | cirq.OP_TREE:
        if not protocols.has_unitary(op):
            return NotImplemented
        return transformers.two_qubit_matrix_to_cz_operations(
            op.qubits[0],
            op.qubits[1],
            protocols.unitary(op),
            allow_partial_czs=False,
            atol=self.atol,
        )
    @property
    def postprocess_transformers(self) -> list[cirq.TRANSFORMER]:
        def rewriter(o: cirq.CircuitOperation):
            result = self._decompose_single_qubit_operation(o, -1)
            return o.circuit.all_operations() if result is NotImplemented else result
        return [
            transformers.create_transformer_with_kwargs(
                transformers.merge_k_qubit_unitaries, k=1, rewriter=rewriter
            ),
            transformers.drop_negligible_operations,
            transformers.drop_empty_moments,
        ]

from __future__ import annotations
from collections.abc import Callable
from cirq import circuits, ops, transformers
from cirq.contrib.paulistring.clifford_optimize import clifford_optimized_circuit
from cirq.contrib.paulistring.pauli_string_optimize import pauli_string_optimized_circuit
class _CZTargetGateSet(transformers.CZTargetGateset):
    def __init__(
        self, post_clean_up: Callable[[ops.OP_TREE], ops.OP_TREE] = lambda op_tree: op_tree
    ):
        super().__init__()
        self.post_clean_up = post_clean_up
    def _decompose_two_qubit_operation(self, op: ops.Operation, _) -> ops.OP_TREE:
        ret = super()._decompose_two_qubit_operation(op, _)
        return ret if ret is NotImplemented else self.post_clean_up(ret)
def optimized_circuit(
    circuit: circuits.Circuit, atol: float = 1e-8, repeat: int = 10, merge_interactions: bool = True
) -> circuits.Circuit:
    circuit = circuits.Circuit(circuit)  # Make a copy
    gateset = _CZTargetGateSet(post_clean_up=_optimized_ops)
    for _ in range(repeat):
        start_len = len(circuit)
        start_cz_count = _cz_count(circuit)
        if merge_interactions:
            circuit = transformers.optimize_for_target_gateset(circuit, gateset=gateset)
        circuit2 = pauli_string_optimized_circuit(circuit, move_cliffords=False, atol=atol)
        circuit3 = clifford_optimized_circuit(circuit2, atol=atol)
        if len(circuit3) == start_len and _cz_count(circuit3) == start_cz_count:
            return circuit3
        circuit = circuit3
    return circuit
def _optimized_ops(ops: ops.OP_TREE, atol: float = 1e-8, repeat: int = 10) -> ops.OP_TREE:
    c = circuits.Circuit(ops)
    c_opt = optimized_circuit(c, atol, repeat, merge_interactions=False)
    return [*c_opt.all_operations()]
def _cz_count(circuit):
    return sum(isinstance(op.gate, ops.CZPowGate) for moment in circuit for op in moment)

from __future__ import annotations
from typing import cast
from cirq import circuits, ops, protocols
from cirq.contrib import circuitdag
def pauli_string_reorder_pred(op1: ops.Operation, op2: ops.Operation) -> bool:
    ps1 = cast(ops.PauliStringGateOperation, op1).pauli_string
    ps2 = cast(ops.PauliStringGateOperation, op2).pauli_string
    return protocols.commutes(ps1, ps2)
def pauli_string_dag_from_circuit(circuit: circuits.Circuit) -> circuitdag.CircuitDag:
    return circuitdag.CircuitDag.from_circuit(circuit, pauli_string_reorder_pred)

