from __future__ import annotations
from typing import TYPE_CHECKING
import networkx
from cirq import circuits, linalg
from cirq.contrib.paulistring.pauli_string_dag import pauli_string_dag_from_circuit
from cirq.contrib.paulistring.recombine import move_pauli_strings_into_circuit
from cirq.contrib.paulistring.separate import convert_and_separate_circuit
from cirq.ops import PauliStringGateOperation
if TYPE_CHECKING:
    from cirq.contrib import circuitdag
def pauli_string_optimized_circuit(
    circuit: circuits.Circuit, move_cliffords: bool = True, atol: float = 1e-8
) -> circuits.Circuit:
    cl, cr = convert_and_separate_circuit(circuit, leave_cliffords=not move_cliffords, atol=atol)
    string_dag = pauli_string_dag_from_circuit(cl)
    while True:
        before_len = len(string_dag.nodes())
        merge_equal_strings(string_dag)
        remove_negligible_strings(string_dag)
        if len(string_dag.nodes()) >= before_len:
            break
    c_all = move_pauli_strings_into_circuit(string_dag, cr)
    assert_no_multi_qubit_pauli_strings(c_all)
    return c_all
def assert_no_multi_qubit_pauli_strings(circuit: circuits.Circuit) -> None:
    for op in circuit.all_operations():
        if isinstance(op, PauliStringGateOperation):
            assert (
                len(op.pauli_string) == 1
            ), 'Multi qubit Pauli string left over'  # pragma: no cover
def merge_equal_strings(string_dag: circuitdag.CircuitDag) -> None:
    for node in tuple(string_dag.nodes()):
        if node not in string_dag.nodes():
            continue
        commuting_nodes = (
            set(string_dag.nodes())
            - set(networkx.dag.ancestors(string_dag, node))
            - set(networkx.dag.descendants(string_dag, node))
            - set([node])
        )
        for other_node in commuting_nodes:
            if node.val.pauli_string.equal_up_to_coefficient(other_node.val.pauli_string):
                string_dag.remove_node(other_node)
                node.val = node.val.merged_with(other_node.val)
def remove_negligible_strings(string_dag: circuitdag.CircuitDag, atol=1e-8) -> None:
    for node in tuple(string_dag.nodes()):
        if linalg.all_near_zero_mod(node.val.exponent_relative, 2, atol=atol):
            string_dag.remove_node(node)

from __future__ import annotations
from collections.abc import Callable, Iterable, Sequence
from typing import Any, cast
from cirq import circuits, ops, protocols
from cirq.contrib import circuitdag
from cirq.contrib.paulistring.pauli_string_dag import (
    pauli_string_dag_from_circuit,
    pauli_string_reorder_pred,
)
def _sorted_best_string_placements(
    possible_nodes: Iterable[Any],
    output_ops: Sequence[ops.Operation],
    key: Callable[[Any], ops.PauliStringPhasor] = lambda node: node.val,
) -> list[tuple[ops.PauliStringPhasor, int, circuitdag.Unique[ops.PauliStringPhasor]]]:
    sort_key = lambda placement: (-len(placement[0].pauli_string), placement[1])
    node_maxes = []
    for possible_node in possible_nodes:
        string_op = key(possible_node)
        node_max = (string_op, 0, possible_node)
        for i, out_op in enumerate(output_ops):
            if not set(out_op.qubits) & set(string_op.qubits):
                continue
            if isinstance(out_op, ops.PauliStringPhasor) and protocols.commutes(
                out_op.pauli_string, string_op.pauli_string
            ):
                continue
            if not (
                isinstance(out_op, ops.GateOperation)
                and isinstance(
                    out_op.gate,
                    (ops.SingleQubitCliffordGate, ops.PauliInteractionGate, ops.CZPowGate),
                )
            ):
                break
            string_op = string_op.conjugated_by(protocols.inverse(out_op))
            curr = (string_op, i + 1, possible_node)
            if sort_key(curr) > sort_key(node_max):
                node_max = curr
        node_maxes.append(node_max)
    return sorted(node_maxes, key=sort_key, reverse=True)
def move_pauli_strings_into_circuit(
    circuit_left: circuits.Circuit | circuitdag.CircuitDag, circuit_right: circuits.Circuit
) -> circuits.Circuit:
    if isinstance(circuit_left, circuitdag.CircuitDag):
        string_dag = circuitdag.CircuitDag(
            incoming_graph_data=circuit_left, can_reorder=pauli_string_reorder_pred
        )
    else:
        string_dag = pauli_string_dag_from_circuit(cast(circuits.Circuit, circuit_left))
    output_ops = list(circuit_right.all_operations())
    rightmost_nodes = set(string_dag.nodes()) - set(before for before, _ in string_dag.edges())
    while rightmost_nodes:
        placements = _sorted_best_string_placements(rightmost_nodes, output_ops)
        last_index = len(output_ops)
        for best_string_op, best_index, best_node in placements:
            assert best_index <= last_index, (
                "Unexpected insertion index order, "
                f"{best_index} >= {last_index}, len: {len(output_ops)}"
            )
            last_index = best_index
            output_ops.insert(best_index, best_string_op)
            rightmost_nodes.remove(best_node)
            rightmost_nodes.update(
                pred_node
                for pred_node in string_dag.predecessors(best_node)
                if len(string_dag.succ[pred_node]) <= 1
            )
            string_dag.remove_node(best_node)
    assert not string_dag.nodes(), 'There was a cycle in the CircuitDag'
    return circuits.Circuit(output_ops, strategy=circuits.InsertStrategy.EARLIEST)

