from __future__ import annotations
from collections.abc import Sequence
from functools import lru_cache
import numpy as np
import quimb
import quimb.tensor as qtn
import cirq
@lru_cache()
def _qpos_tag(qubits: cirq.Qid | tuple[cirq.Qid]):
    if isinstance(qubits, cirq.Qid):
        return _qpos_tag((qubits,))
    x = min(qubits)
    return f'q{x}'
@lru_cache()
def _qpos_y(qubits: cirq.Qid | tuple[cirq.Qid, ...], all_qubits: tuple[cirq.Qid, ...]) -> float:
    if isinstance(qubits, cirq.Qid):
        return _qpos_y((qubits,), all_qubits)
    pos = [all_qubits.index(q) for q in qubits]
    x = np.mean(pos).item()
    return len(all_qubits) - x - 1
def _add_to_positions(
    positions: dict[tuple[str, str], tuple[float, float]],
    mi: int,
    qubits: cirq.Qid | tuple[cirq.Qid],
    *,
    all_qubits: tuple[cirq.Qid, ...],
    x_scale,
    y_scale,
    x_nudge,
    yb_offset,
):
    qy = _qpos_y(qubits, all_qubits)
    positions[(f'i{mi}f', _qpos_tag(qubits))] = (mi * x_scale + qy * x_nudge, y_scale * qy)
    positions[(f'i{mi}b', _qpos_tag(qubits))] = (mi * x_scale, y_scale * qy + yb_offset)
def circuit_to_density_matrix_tensors(
    circuit: cirq.Circuit, qubits: Sequence[cirq.Qid] | None = None
) -> tuple[list[qtn.Tensor], dict[cirq.Qid, int], dict[tuple[str, str], tuple[float, float]]]:
    if qubits is None:
        qubits = sorted(circuit.all_qubits())  # pragma: no cover
    qubits = tuple(qubits)
    qubit_frontier: dict[cirq.Qid, int] = {q: 0 for q in qubits}
    kraus_frontier = 0
    positions: dict[tuple[str, str], tuple[float, float]] = {}
    tensors: list[qtn.Tensor] = []
    x_scale = 2
    y_scale = 3
    x_nudge = 0.3
    n_qubits = len(qubits)
    yb_offset = (n_qubits + 0.5) * y_scale
    def _positions(_mi, _these_qubits):
        return _add_to_positions(
            positions,
            _mi,
            _these_qubits,
            all_qubits=qubits,
            x_scale=x_scale,
            y_scale=y_scale,
            x_nudge=x_nudge,
            yb_offset=yb_offset,
        )
    for q in qubits:
        tensors += [
            qtn.Tensor(
                data=quimb.up().squeeze(), inds=(f'nf0_q{q}',), tags={'Q0', 'i0f', _qpos_tag(q)}
            ),
            qtn.Tensor(
                data=quimb.up().squeeze(), inds=(f'nb0_q{q}',), tags={'Q0', 'i0b', _qpos_tag(q)}
            ),
        ]
        _positions(0, q)
    for mi, moment in enumerate(circuit.moments):
        for op in moment.operations:
            start_inds_f = [f'nf{qubit_frontier[q]}_q{q}' for q in op.qubits]
            start_inds_b = [f'nb{qubit_frontier[q]}_q{q}' for q in op.qubits]
            for q in op.qubits:
                qubit_frontier[q] += 1
            end_inds_f = [f'nf{qubit_frontier[q]}_q{q}' for q in op.qubits]
            end_inds_b = [f'nb{qubit_frontier[q]}_q{q}' for q in op.qubits]
            if cirq.has_unitary(op):
                U = cirq.unitary(op).reshape((2,) * 2 * len(op.qubits)).astype(np.complex128)
                tensors.append(
                    qtn.Tensor(
                        data=U,
                        inds=end_inds_f + start_inds_f,
                        tags={f'Q{len(op.qubits)}', f'i{mi + 1}f', _qpos_tag(op.qubits)},
                    )
                )
                tensors.append(
                    qtn.Tensor(
                        data=np.conj(U),
                        inds=end_inds_b + start_inds_b,
                        tags={f'Q{len(op.qubits)}', f'i{mi + 1}b', _qpos_tag(op.qubits)},
                    )
                )
            elif cirq.has_kraus(op):
                K = np.asarray(cirq.kraus(op), dtype=np.complex128)
                kraus_inds = [f'k{kraus_frontier}']
                tensors.append(
                    qtn.Tensor(
                        data=K,
                        inds=kraus_inds + end_inds_f + start_inds_f,
                        tags={f'kQ{len(op.qubits)}', f'i{mi + 1}f', _qpos_tag(op.qubits)},
                    )
                )
                tensors.append(
                    qtn.Tensor(
                        data=np.conj(K),
                        inds=kraus_inds + end_inds_b + start_inds_b,
                        tags={f'kQ{len(op.qubits)}', f'i{mi + 1}b', _qpos_tag(op.qubits)},
                    )
                )
                kraus_frontier += 1
            else:
                raise ValueError(repr(op))  # pragma: no cover
            _positions(mi + 1, op.qubits)
    return tensors, qubit_frontier, positions
def tensor_density_matrix(
    circuit: cirq.Circuit, qubits: Sequence[cirq.Qid] | None = None
) -> np.ndarray:
    if qubits is None:
        qubits = sorted(circuit.all_qubits())
    tensors, qubit_frontier, _ = circuit_to_density_matrix_tensors(circuit=circuit, qubits=qubits)
    tn = qtn.TensorNetwork(tensors)
    f_inds = tuple(f'nf{qubit_frontier[q]}_q{q}' for q in qubits)
    b_inds = tuple(f'nb{qubit_frontier[q]}_q{q}' for q in qubits)
    if len(qubits) <= 6:
        tags_seq = [(f'i{i}b', f'i{i}f') for i in range(len(circuit) + 1)]
        tn.contract_cumulative(tags_seq, inplace=True)
    else:
        tn.contract(inplace=True)
    return tn.to_dense(f_inds, b_inds)

from __future__ import annotations
from collections.abc import Sequence
import networkx as nx
import numpy as np
import pytest
import cirq
import cirq.contrib.quimb as ccq
def _get_circuit(width, height, rs, p=2):
    graph = nx.grid_2d_graph(width, height)
    nx.set_edge_attributes(
        graph, name='weight', values={e: np.round(rs.uniform(), 2) for e in graph.edges}
    )
    qubits = [cirq.GridQubit(*n) for n in graph]
    circuit = cirq.Circuit(
        cirq.H.on_each(qubits),
        [
            (ccq.get_grid_moments(graph), cirq.Moment([cirq.rx(0.456).on_each(qubits)]))
            for _ in range(p)
        ],
    )
    return circuit, qubits
def test_simplify_sandwich() -> None:
    rs = np.random.RandomState(52)
    for width in [2, 3]:
        for height in [1, 3]:
            for p in [1, 2]:
                circuit, qubits = _get_circuit(width=width, height=height, p=p, rs=rs)
                operator: cirq.PauliString
                operator = cirq.PauliString(
                    {q: cirq.Z for q in rs.choice(qubits, size=2, replace=False)}
                )
                tot_c = ccq.circuit_for_expectation_value(circuit, operator)
                tot_c_init = tot_c.copy()
                ccq.simplify_expectation_value_circuit(tot_c)
                assert len(list(tot_c.all_operations())) < len(list(tot_c_init.all_operations()))
                np.testing.assert_allclose(
                    tot_c.unitary(qubit_order=qubits),
                    tot_c_init.unitary(qubit_order=qubits),
                    atol=1e-5,
                )
@pytest.mark.parametrize('simplify', [False, True])
def test_circuit_to_tensors(simplify) -> None:
    qubits: Sequence[cirq.Qid]
    qubits = cirq.LineQubit.range(2)
    circuit = cirq.testing.random_circuit(qubits=qubits, n_moments=10, op_density=0.8)
    operator: cirq.PauliString
    operator = cirq.PauliString(dict.fromkeys(qubits, cirq.Z))
    circuit_sand = ccq.circuit_for_expectation_value(circuit, operator)
    if simplify:
        ccq.simplify_expectation_value_circuit(circuit_sand)
    qubits = sorted(circuit_sand.all_qubits())
    u_tn = ccq.tensor_unitary(circuit=circuit_sand, qubits=qubits)
    u_cirq = cirq.unitary(circuit_sand)
    np.testing.assert_allclose(u_tn, u_cirq, atol=1e-6)
def test_tensor_expectation_value() -> None:
    for _ in range(10):
        for width in [2, 3]:
            for height in [1, 3]:
                for p in [1, 2]:
                    rs = np.random.RandomState(52)
                    circuit, qubits = _get_circuit(width=width, height=height, p=p, rs=rs)
                    operator: cirq.PauliString
                    operator = cirq.PauliString(
                        {q: cirq.Z for q in rs.choice(qubits, size=2, replace=False)},
                        coefficient=rs.uniform(-1, 1),
                    )
                    eval_tn = ccq.tensor_expectation_value(circuit, operator)
                    wfn = cirq.Simulator().simulate(circuit)
                    eval_normal = operator.expectation_from_state_vector(
                        wfn.final_state_vector, wfn.qubit_map
                    )
                    assert eval_normal.imag < 1e-6
                    eval_normal = eval_normal.real
                    np.testing.assert_allclose(eval_tn, eval_normal, atol=1e-3)

from __future__ import annotations
import dataclasses
import math
from collections.abc import Sequence
from typing import Any, TYPE_CHECKING
import numpy as np
import quimb.tensor as qtn
from cirq import devices, protocols, qis, value
from cirq.sim import simulator_base
from cirq.sim.simulation_state import SimulationState
if TYPE_CHECKING:
    import cirq
@dataclasses.dataclass(frozen=True)
class MPSOptions:
    method: str = 'svds'
    max_bond: int | None = None
    cutoff_mode: str = 'rsum2'
    cutoff: float = 1e-6
    sum_prob_atol: float = 1e-3
class MPSSimulator(
    simulator_base.SimulatorBase['MPSSimulatorStepResult', 'MPSTrialResult', 'MPSState']
):
    def __init__(
        self,
        noise: cirq.NOISE_MODEL_LIKE = None,
        seed: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
        simulation_options: MPSOptions = MPSOptions(),
        grouping: dict[cirq.Qid, int] | None = None,
    ):
        self.init = True
        noise_model = devices.NoiseModel.from_noise_model_like(noise)
        if not protocols.has_mixture(noise_model):
            raise ValueError(f'noise must be unitary or mixture but was {noise_model}')
        self.simulation_options = simulation_options
        self.grouping = grouping
        super().__init__(noise=noise, seed=seed)
    def _create_partial_simulation_state(
        self,
        initial_state: int | MPSState,
        qubits: Sequence[cirq.Qid],
        classical_data: cirq.ClassicalDataStore,
    ) -> MPSState:
        if isinstance(initial_state, MPSState):
            return initial_state  # pragma: no cover
        return MPSState(
            qubits=qubits,
            prng=self._prng,
            simulation_options=self.simulation_options,
            grouping=self.grouping,
            initial_state=initial_state,
            classical_data=classical_data,
        )
    def _create_step_result(self, sim_state: cirq.SimulationStateBase[MPSState]):
        return MPSSimulatorStepResult(sim_state)
    def _create_simulator_trial_result(
        self,
        params: cirq.ParamResolver,
