import json
import urllib.parse
from collections.abc import Iterable
from typing import Any, cast
from cirq import circuits, devices, ops, protocols
from cirq.contrib.quirk.linearize_circuit import linearize_circuit_qubits
from cirq.contrib.quirk.quirk_gate import (
    known_quirk_op_for_operation,
    QuirkOp,
    single_qubit_matrix_gate,
    UNKNOWN_GATE,
)
def _try_convert_to_quirk_gate(op: ops.Operation, prefer_unknown_gate_to_failure: bool) -> QuirkOp:
    quirk_gate = known_quirk_op_for_operation(op)
    if quirk_gate is not None:
        return quirk_gate
    matrix_op = single_qubit_matrix_gate(protocols.unitary(op, None))
    if matrix_op is not None:
        return matrix_op
    if prefer_unknown_gate_to_failure:
        return UNKNOWN_GATE
    raise TypeError(f'Unrecognized operation: {op!r}')
def _to_quirk_cols(
    op: ops.Operation, prefer_unknown_gate_to_failure: bool
) -> Iterable[tuple[list[Any], bool]]:
    gate = _try_convert_to_quirk_gate(op, prefer_unknown_gate_to_failure)
    qubits = cast(Iterable[devices.LineQubit], op.qubits)
    max_index = max(q.x for q in qubits)
    col = [1] * (max_index + 1)
    for i, q in enumerate(qubits):
        col[q.x] = gate.keys[min(i, len(gate.keys) - 1)]
    yield col, gate.can_merge
def circuit_to_quirk_url(
    circuit: circuits.Circuit, prefer_unknown_gate_to_failure: bool = False, escape_url=True
) -> str:
    circuit = circuit.copy()
    linearize_circuit_qubits(circuit)
    cols: list[list[Any]] = []
    for moment in circuit:
        can_merges = []
        for op in moment.operations:
            for col, can_merge in _to_quirk_cols(op, prefer_unknown_gate_to_failure):
                if can_merge:
                    can_merges.append(col)
                else:
                    cols.append(col)
        if can_merges:
            merged_col = [1] * max(len(e) for e in can_merges)
            for col in can_merges:
                for i in range(len(col)):
                    if col[i] != 1:
                        merged_col[i] = col[i]
            cols.append(merged_col)
    circuit_json = json.JSONEncoder(
        ensure_ascii=False, separators=(',', ':'), sort_keys=True
    ).encode({'cols': cols})
    if escape_url:
        suffix = urllib.parse.quote(circuit_json)
    else:
        suffix = circuit_json
    return f'http://algassert.com/quirk#circuit={suffix}'

from __future__ import annotations
from collections.abc import Callable
from cirq import circuits, devices, ops
class QubitMapper:
    def __init__(self, qubit_map: Callable[[ops.Qid], ops.Qid]) -> None:
        self.qubit_map = qubit_map
    def map_operation(self, operation: ops.Operation) -> ops.Operation:
        return operation.transform_qubits(self.qubit_map)
    def map_moment(self, moment: circuits.Moment) -> circuits.Moment:
        return circuits.Moment(self.map_operation(op) for op in moment.operations)
    def optimize_circuit(self, circuit: circuits.Circuit) -> None:
        circuit[:] = (self.map_moment(m) for m in circuit)
def linearize_circuit_qubits(
    circuit: circuits.Circuit, qubit_order: ops.QubitOrderOrList = ops.QubitOrder.DEFAULT
) -> None:
    qubits = ops.QubitOrder.as_qubit_order(qubit_order).order_for(circuit.all_qubits())
    qubit_map = {q: devices.LineQubit(i) for i, q in enumerate(qubits)}
    QubitMapper(qubit_map.__getitem__).optimize_circuit(circuit)

from __future__ import annotations
from collections.abc import Callable
from typing import Any, cast
import numpy as np
import sympy
from cirq import ops
class QuirkOp:
    def __init__(self, *keys: Any, can_merge: bool = True) -> None:
        self.keys = keys
        self.can_merge = can_merge
    def controlled(self, control_count: int = 1) -> QuirkOp:
        return QuirkOp(*['•'] * control_count, *self.keys, can_merge=False)
UNKNOWN_GATE = QuirkOp('UNKNOWN', can_merge=False)
def same_half_turns(a1: float, a2: float, atol=0.0001) -> bool:
    d = (a1 - a2 + 1) % 2 - 1
    return abs(d) < atol
def _is_supported_formula(formula: sympy.Basic) -> bool:
    if isinstance(
        formula, (sympy.Symbol, sympy.Integer, sympy.Float, sympy.Rational, sympy.NumberSymbol)
    ):
        return True
    if isinstance(formula, (sympy.Add, sympy.Mul)):
        return all(_is_supported_formula(f) for f in formula.args)
    return False
def _val_to_quirk_formula(t: float | sympy.Basic) -> str:
    if isinstance(t, sympy.Basic):
        if not set(t.free_symbols) <= {sympy.Symbol('t')}:
            raise ValueError(f'Symbol other than "t": {t!r}.')
        if not _is_supported_formula(t):
            raise ValueError(f'Formula uses unsupported operations: {t!r}')
        return str(t)
    return f'{float(t):.4f}'
def angle_to_exponent_key(t: float | sympy.Basic) -> str | None:
    if isinstance(t, sympy.Basic):
        if t == sympy.Symbol('t'):
            return '^t'
        if t == -sympy.Symbol('t'):
            return '^-t'
        return None
    if same_half_turns(t, 1):
        return ''
    if same_half_turns(t, 0.5):
        return '^½'
    if same_half_turns(t, -0.5):
        return '^-½'
    if same_half_turns(t, 0.25):
        return '^¼'
    if same_half_turns(t, -0.25):
        return '^-¼'
    return None
def single_qubit_matrix_gate(matrix: np.ndarray | None) -> QuirkOp | None:
    if matrix is None or matrix.shape[0] != 2:
        return None
    matrix = matrix.round(6)
    matrix_repr = '{{%s+%si,%s+%si},{%s+%si,%s+%si}}' % (
        np.real(matrix[0, 0]),
        np.imag(matrix[0, 0]),
        np.real(matrix[1, 0]),
        np.imag(matrix[1, 0]),
        np.real(matrix[0, 1]),
        np.imag(matrix[0, 1]),
        np.real(matrix[1, 1]),
        np.imag(matrix[1, 1]),
    )
    matrix_repr = matrix_repr.replace('+-', '-')
    matrix_repr = matrix_repr.replace('+0.0i', '')
    matrix_repr = matrix_repr.replace('.0,', ',')
    matrix_repr = matrix_repr.replace('.0}', '}')
    matrix_repr = matrix_repr.replace('.0+', '+')
    matrix_repr = matrix_repr.replace('.0-', '-')
    return QuirkOp({'id': '?', 'matrix': matrix_repr})
def known_quirk_op_for_operation(op: ops.Operation) -> QuirkOp | None:
    if isinstance(op, ops.GateOperation):
        return _gate_to_quirk_op(op.gate)
    if isinstance(op, ops.ControlledOperation):
        return controlled_unwrap(op)
    return None
def _gate_to_quirk_op(gate: ops.Gate) -> QuirkOp | None:
    for gate_type, func in _known_gate_conversions.items():
        if isinstance(gate, gate_type):
            return func(gate)
    return None
def xyz_to_quirk_op(axis: str, gate: ops.EigenGate) -> QuirkOp:
    d = axis.lower()
    u = axis.upper()
    if gate.global_shift == -0.5:
        return QuirkOp({'id': f'R{d}ft', 'arg': f'({_val_to_quirk_formula(gate.exponent)}) pi'})
    e = angle_to_exponent_key(gate.exponent)
    if e is not None:
        return QuirkOp(u + e)
    return QuirkOp({'id': f'{u}^ft', 'arg': f'{_val_to_quirk_formula(gate.exponent)}'})
def x_to_quirk_op(gate: ops.XPowGate) -> QuirkOp:
    return xyz_to_quirk_op('x', gate)
def y_to_quirk_op(gate: ops.YPowGate) -> QuirkOp:
    return xyz_to_quirk_op('y', gate)
def z_to_quirk_op(gate: ops.ZPowGate) -> QuirkOp:
    return xyz_to_quirk_op('z', gate)
def cz_to_quirk_op(gate: ops.CZPowGate) -> QuirkOp | None:
    return z_to_quirk_op(ops.Z**gate.exponent).controlled()
def cnot_to_quirk_op(gate: ops.CXPowGate) -> QuirkOp | None:
    return x_to_quirk_op(ops.X**gate.exponent).controlled()
def h_to_quirk_op(gate: ops.HPowGate) -> QuirkOp | None:
    if gate.exponent == 1:
        return QuirkOp('H')
    return None
def swap_to_quirk_op(gate: ops.SwapPowGate) -> QuirkOp | None:
    if gate.exponent == 1:
        return QuirkOp('Swap', 'Swap', can_merge=False)
    return None
def cswap_to_quirk_op(gate: ops.CSwapGate) -> QuirkOp | None:
    return QuirkOp('•', 'Swap', 'Swap', can_merge=False)
def ccx_to_quirk_op(gate: ops.CCXPowGate) -> QuirkOp | None:
    e = angle_to_exponent_key(gate.exponent)
    if e is None:
        return None
    return QuirkOp('•', '•', 'X' + e, can_merge=False)
def ccz_to_quirk_op(gate: ops.CCZPowGate) -> QuirkOp | None:
    e = angle_to_exponent_key(gate.exponent)
    if e is None:
        return None
    return QuirkOp('•', '•', 'Z' + e, can_merge=False)
def controlled_unwrap(op: ops.ControlledOperation) -> QuirkOp | None:
    sub = known_quirk_op_for_operation(op.sub_operation)
    if sub is None:
        return None
    return sub.controlled(len(op.controls))
_known_gate_conversions = cast(
    dict[type, Callable[[ops.Gate], QuirkOp | None]],
    {
        ops.CCXPowGate: ccx_to_quirk_op,
        ops.CCZPowGate: ccz_to_quirk_op,
        ops.CSwapGate: cswap_to_quirk_op,
        ops.XPowGate: x_to_quirk_op,
        ops.YPowGate: y_to_quirk_op,
        ops.ZPowGate: z_to_quirk_op,
        ops.CXPowGate: cnot_to_quirk_op,
        ops.CZPowGate: cz_to_quirk_op,
        ops.SwapPowGate: swap_to_quirk_op,
        ops.HPowGate: h_to_quirk_op,
        ops.MeasurementGate: lambda _: QuirkOp('Measure'),
    },
)

from __future__ import annotations
import itertools
from collections.abc import Iterable
import networkx as nx
import cirq
def get_linear_device_graph(n_qubits: int) -> nx.Graph:
    qubits = cirq.LineQubit.range(n_qubits)
    edges = [tuple(qubits[i : i + 2]) for i in range(n_qubits - 1)]
    return nx.Graph(edges)
def get_grid_device_graph(*args, **kwargs) -> nx.Graph:
    return gridqubits_to_graph_device(cirq.GridQubit.rect(*args, **kwargs))
def gridqubits_to_graph_device(qubits: Iterable[cirq.GridQubit]) -> nx.Graph:
    return nx.Graph(
        pair for pair in itertools.combinations(qubits, 2) if _manhattan_distance(*pair) == 1
    )
def _manhattan_distance(qubit1: cirq.GridQubit, qubit2: cirq.GridQubit) -> int:
    return abs(qubit1.row - qubit2.row) + abs(qubit1.col - qubit2.col)
def nx_qubit_layout(graph: nx.Graph) -> dict[cirq.Qid, tuple[float, float]]:
    pos: dict[cirq.Qid, tuple[float, float]] = {}
    _node_to_i_cache = None
    for node in graph.nodes:
        if isinstance(node, cirq.GridQubit):
            pos[node] = (node.col, -node.row)
        elif isinstance(node, cirq.LineQubit):
            pos[node] = (node.x, 0.5)
        else:
            if _node_to_i_cache is None:
                _node_to_i_cache = {n: i for i, n in enumerate(sorted(graph.nodes))}
            pos[node] = (0.5, _node_to_i_cache[node] + 1)
    return pos

from __future__ import annotations
import itertools
from collections.abc import Callable, Iterable, Sequence
from typing import cast, TYPE_CHECKING
import networkx as nx
import numpy as np
import cirq.contrib.acquaintance as cca
from cirq import circuits, ops, value
from cirq.contrib import circuitdag
from cirq.contrib.routing.initialization import get_initial_mapping
from cirq.contrib.routing.swap_network import SwapNetwork
from cirq.contrib.routing.utils import get_time_slices, ops_are_consistent_with_device_graph
if TYPE_CHECKING:
    import cirq
SWAP = cca.SwapPermutationGate()
QidPair = tuple[ops.Qid, ops.Qid]
def route_circuit_greedily(
    circuit: circuits.Circuit, device_graph: nx.Graph, **kwargs
) -> SwapNetwork:
    router = _GreedyRouter(circuit, device_graph, **kwargs)
    router.route()
    swap_network = router.swap_network
    swap_network.circuit = circuits.Circuit(swap_network.circuit.all_operations())
    return swap_network
class _GreedyRouter:
    def __init__(
        self,
        circuit,
        device_graph: nx.Graph,
        *,
        max_search_radius: int = 1,
        max_num_empty_steps: int = 5,
        initial_mapping: dict[ops.Qid, ops.Qid] | None = None,
        can_reorder: Callable[[ops.Operation, ops.Operation], bool] = lambda op1, op2: not set(
            op1.qubits
        )
        & set(op2.qubits),
        random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
    ):
        self.prng = value.parse_random_state(random_state)
        self.device_graph = device_graph
        self.physical_distances: dict[QidPair, int] = {
            (a, b): d
            for a, neighbor_distances in nx.shortest_path_length(device_graph)
            for b, d in neighbor_distances.items()
        }
        self.remaining_dag = circuitdag.CircuitDag.from_circuit(circuit, can_reorder=can_reorder)
        self.logical_qubits = list(self.remaining_dag.all_qubits())
        self.physical_qubits = list(self.device_graph.nodes)
        self.edge_sets: dict[int, list[Sequence[QidPair]]] = {}
        self.physical_ops: list[ops.Operation] = []
        self.set_initial_mapping(initial_mapping)
        if max_search_radius < 1:
            raise ValueError('max_search_radius must be a positive integer.')
        self.max_search_radius = max_search_radius
        if max_num_empty_steps < 1:
            raise ValueError('max_num_empty_steps must be a positive integer.')
        self.max_num_empty_steps = max_num_empty_steps
    def get_edge_sets(self, edge_set_size: int) -> Iterable[Sequence[QidPair]]:
        if edge_set_size not in self.edge_sets:
            self.edge_sets[edge_set_size] = [
                cast(Sequence[QidPair], edge_set)
                for edge_set in itertools.combinations(self.device_graph.edges, edge_set_size)
                if all(set(e).isdisjoint(f) for e, f in itertools.combinations(edge_set, 2))
            ]
        return self.edge_sets[edge_set_size]
    def log_to_phys(self, *qubits: cirq.Qid) -> Iterable[ops.Qid]:
        return (self._log_to_phys[q] for q in qubits)
    def phys_to_log(self, *qubits: cirq.Qid) -> Iterable[ops.Qid | None]:
        return (self._phys_to_log[q] for q in qubits)
    def apply_swap(self, *physical_edges: QidPair):
        self.update_mapping(*physical_edges)
        self.physical_ops += [SWAP(*e) for e in physical_edges]
    def update_mapping(self, *physical_edges: QidPair):
        for physical_edge in physical_edges:
            old_logical_edge = tuple(self.phys_to_log(*physical_edge))
            new_logical_edge = old_logical_edge[::-1]
            for p, l in zip(physical_edge, new_logical_edge):
                self._phys_to_log[p] = l
                if l is not None:
                    self._log_to_phys[l] = p
    def set_initial_mapping(self, initial_mapping: dict[ops.Qid, ops.Qid] | None = None):
        if initial_mapping is None:
            time_slices = get_time_slices(self.remaining_dag)
            if not time_slices:
                initial_mapping = dict(zip(self.device_graph, self.logical_qubits))
            else:
                logical_graph = time_slices[0]
                logical_graph.add_nodes_from(self.logical_qubits)
                initial_mapping = get_initial_mapping(logical_graph, self.device_graph, self.prng)
        self.initial_mapping = initial_mapping
        self._phys_to_log = {q: initial_mapping.get(q) for q in self.physical_qubits}
        self._log_to_phys = {l: p for p, l in self._phys_to_log.items() if l is not None}
        self._assert_mapping_consistency()
    def _assert_mapping_consistency(self):
        assert sorted(self._log_to_phys) == sorted(self.logical_qubits)
        assert sorted(self._phys_to_log) == sorted(self.physical_qubits)
        for l in self._log_to_phys:
            assert l == self._phys_to_log[self._log_to_phys[l]]
    def acts_on_nonadjacent_qubits(self, op: ops.Operation) -> bool:
        if len(op.qubits) == 1:
            return False
        return tuple(self.log_to_phys(*op.qubits)) not in self.device_graph.edges
    def apply_possible_ops(self) -> int:
        nodes = list(
            self.remaining_dag.findall_nodes_until_blocked(self.acts_on_nonadjacent_qubits)
        )
        assert not any(
            self.remaining_dag.has_edge(b, a) for a, b in itertools.combinations(nodes, 2)
        )
        assert not any(self.acts_on_nonadjacent_qubits(node.val) for node in nodes)
        remaining_nodes = [node for node in self.remaining_dag.ordered_nodes() if node not in nodes]
        for node, remaining_node in itertools.product(nodes, remaining_nodes):
            assert not self.remaining_dag.has_edge(remaining_node, node)
        for node in nodes:
            self.remaining_dag.remove_node(node)
            logical_op = node.val
            physical_op = logical_op.with_qubits(*self.log_to_phys(*logical_op.qubits))
            assert len(physical_op.qubits) < 2 or physical_op.qubits in self.device_graph.edges
            self.physical_ops.append(physical_op)
        return len(nodes)
    @property
    def swap_network(self) -> SwapNetwork:
        return SwapNetwork(circuits.Circuit(self.physical_ops), self.initial_mapping)
    def distance(self, edge: QidPair) -> int:
        return self.physical_distances[cast(QidPair, tuple(self.log_to_phys(*edge)))]
    def swap_along_path(self, path: tuple[ops.Qid]):
        for i in range(len(path) - 1):
            self.apply_swap(cast(QidPair, path[i : i + 2]))
    def bring_farthest_pair_together(self, pairs: Sequence[QidPair]):
        distances = [self.distance(pair) for pair in pairs]
        assert distances
        max_distance = min(distances)
        farthest_pairs = [pair for pair, d in zip(pairs, distances) if d == max_distance]
        choice = self.prng.choice(len(farthest_pairs))
        farthest_pair = farthest_pairs[choice]
        edge = self.log_to_phys(*farthest_pair)
        shortest_path = nx.shortest_path(self.device_graph, *edge)
        assert len(shortest_path) - 1 == max_distance
        midpoint = max_distance // 2
        self.swap_along_path(shortest_path[:midpoint])
        self.swap_along_path(shortest_path[midpoint:])
    def get_distance_vector(self, logical_edges: Iterable[QidPair], swaps: Sequence[QidPair]):
        self.update_mapping(*swaps)
        distance_vector = np.array([self.distance(e) for e in logical_edges])
        self.update_mapping(*swaps)
        return distance_vector
    def apply_next_swaps(self, require_frontier_adjacency: bool = False):
        time_slices = get_time_slices(self.remaining_dag)
        if require_frontier_adjacency:
            frontier_edges = sorted(time_slices[0].edges)
            self.bring_farthest_pair_together(frontier_edges)
            return
        for k in range(1, self.max_search_radius + 1):
            candidate_swap_sets = list(self.get_edge_sets(k))
            for time_slice in time_slices:
                edges = sorted(time_slice.edges)
                distance_vectors = list(
                    self.get_distance_vector(edges, swap_set) for swap_set in candidate_swap_sets
                )
                dominated_indices = _get_dominated_indices(distance_vectors)
                candidate_swap_sets = [
                    S for i, S in enumerate(candidate_swap_sets) if i not in dominated_indices
                ]
                if len(candidate_swap_sets) == 1:
                    self.apply_swap(*candidate_swap_sets[0])
                    if list(
                        self.remaining_dag.findall_nodes_until_blocked(
                            self.acts_on_nonadjacent_qubits
                        )
                    ):
                        return
                    else:
                        break
        self.apply_next_swaps(True)
    def route(self):
        self.apply_possible_ops()
        empty_steps_remaining = self.max_num_empty_steps
        while self.remaining_dag:
            self.apply_next_swaps(not empty_steps_remaining)
            n_applied_ops = self.apply_possible_ops()
            if n_applied_ops:
                empty_steps_remaining = self.max_num_empty_steps
            else:
                empty_steps_remaining -= 1
        assert ops_are_consistent_with_device_graph(self.physical_ops, self.device_graph)
def _get_dominated_indices(vectors: list[np.ndarray]) -> set[int]:
    dominated_indices = set()
    for i, v in enumerate(vectors):
        for w in vectors[:i] + vectors[i + 1 :]:
            if all(v >= w):
                dominated_indices.add(i)
                break
    return dominated_indices

from __future__ import annotations
import itertools
from collections.abc import Hashable
from typing import cast, TYPE_CHECKING
import networkx as nx
from sortedcontainers import SortedDict, SortedSet
from cirq import ops, value
if TYPE_CHECKING:
    import cirq
def get_center(graph: nx.Graph) -> Hashable:
    centralities = nx.betweenness_centrality(graph)
    return max(centralities, key=centralities.get)
def get_initial_mapping(
    logical_graph: nx.Graph,
    device_graph: nx.Graph,
    random_state: cirq.RANDOM_STATE_OR_SEED_LIKE = None,
) -> dict[ops.Qid, ops.Qid]:
    prng = value.parse_random_state(random_state)
    unplaced_vertices = set(logical_graph)
    logical_center = cast(ops.Qid, get_center(logical_graph))
    device_center = cast(ops.Qid, get_center(device_graph))
    mapping = {device_center: logical_center}
    unplaced_vertices.remove(logical_center)
    physical_distances = {
        (a, b): d
        for a, neighbor_distances in nx.shortest_path_length(device_graph)
        for b, d in neighbor_distances.items()
    }
    while unplaced_vertices:
        placed_vertices = set(mapping.values())
        placed_neighbors = {
            v: placed_vertices.intersection(logical_graph[v]) for v in unplaced_vertices
        }
        nums_placed_neighbors = {v: len(N) for v, N in placed_neighbors.items()}
        max_num_placed_neighbors = max(nums_placed_neighbors.values())
        candidates = [v for v, n in nums_placed_neighbors.items() if n == max_num_placed_neighbors]
        border = SortedSet().union(*(device_graph[v] for v in mapping)).difference(mapping)
        total_distances = SortedDict()
        for l, p in itertools.product(candidates, border):
            total_distance = 0
            for pp, ll in mapping.items():
                if logical_graph.has_edge(l, ll):
                    total_distance += physical_distances[p, pp]
            total_distances[l, p] = total_distance
        min_total_distance = min(total_distances.values())
        best_candidates = [lp for lp, d in total_distances.items() if d == min_total_distance]
        choice = prng.choice(len(best_candidates))
        l, p = best_candidates[choice]
        assert p not in mapping
        assert l not in mapping.values()
        mapping[p] = l
        unplaced_vertices.remove(l)
    return mapping

from __future__ import annotations
from collections.abc import Callable
from typing import TYPE_CHECKING
from cirq import circuits, protocols
from cirq.contrib.routing.greedy import route_circuit_greedily
if TYPE_CHECKING:
    import networkx as nx
    from cirq.contrib.routing.swap_network import SwapNetwork
ROUTERS = {'greedy': route_circuit_greedily}
def route_circuit(
    circuit: circuits.Circuit,
    device_graph: nx.Graph,
    *,
    algo_name: str | None = None,
    router: Callable[..., SwapNetwork] | None = None,
    **kwargs,
) -> SwapNetwork:
    if any(protocols.num_qubits(op) > 2 for op in circuit.all_operations()):
        raise ValueError('Can only route circuits with operations that act on at most 2 qubits.')
    if len(list(circuit.all_qubits())) > device_graph.number_of_nodes():
        raise ValueError('Number of logical qubits is greater than number of physical qubits.')
    if not (algo_name is None or router is None):
        raise ValueError('At most one of algo_name or router can be specified.')
    if algo_name is not None:
        router = ROUTERS[algo_name]
    elif router is None:
        raise ValueError('No routing algorithm specified.')
    return router(circuit, device_graph, **kwargs)

from __future__ import annotations
from collections.abc import Iterable
from typing import TYPE_CHECKING
import cirq.contrib.acquaintance as cca
from cirq import ops
if TYPE_CHECKING:
    import cirq
class SwapNetwork:
    def __init__(self, circuit: cirq.Circuit, initial_mapping: dict[cirq.Qid, cirq.Qid]) -> None:
        if not all(isinstance(i, ops.Qid) for I in initial_mapping.items() for i in I):
            raise ValueError('Mapping must be from Qids to Qids.')
        self.circuit = circuit
        self.initial_mapping = initial_mapping
    def final_mapping(self) -> dict[cirq.Qid, cirq.Qid]:
        mapping = dict(self.initial_mapping)
        cca.update_mapping(mapping, self.circuit.all_operations())
        return mapping
    def get_logical_operations(self) -> Iterable[cirq.Operation]:
        return cca.get_logical_operations(self.circuit.all_operations(), self.initial_mapping)
    def __eq__(self, other) -> bool:
        if not isinstance(other, type(self)):
            return NotImplemented
        return self.circuit == other.circuit and self.initial_mapping == other.initial_mapping
    def __str__(self) -> str:
        circuit = self.circuit.copy()
        cca.display_mapping(circuit, self.initial_mapping)
        return str(circuit)

